/****** Object:  UserDefinedFunction [dbo].[AllPollsHasAnswer]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[AllPollsHasAnswer] 
(@ContactId bigint,@ClassroomId Bigint,@PollId Bigint)
RETURNS bit
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Anserwed bit
	select @Anserwed = ( CASE WHEN COUNT(dbo.GENPolls.id) = COUNT(GENExamAnswerDetails.PollId)  THEN cast(1 as bit) else cast(0 as bit) END)
FROM   dbo.GENPolls      
LEFT JOIN dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId
LEFT JOIN dbo.GENPollCategories ON dbo.GENPollCategories.Id = dbo.PollCategoryandPolls.PollCategoryId
left join GENExamAnswerHeaders on GENExamAnswerHeaders.StudentId = @contactId and GENExamAnswerHeaders.ExamId = GENPollCategories.Id and GENExamAnswerHeaders.ClassroomId = @ClassroomId
left join GENExamAnswerDetails on GENExamAnswerDetails.PollId = dbo.GENPolls.Id and GENExamAnswerDetails.ExamAnswerHeaderId = GENExamAnswerHeaders.Id
WHERE  dbo.GENPolls.IsActive=1 AND dbo.GENPollCategories.ExamType = 12 
	AND dbo.GENPollCategories.IsActive = 1  AND dbo.GENPollCategories.IsPosted = 1 AND GENPollCategories.Id = @PollId AND GENExamAnswerHeaders.Id =@ClassroomId
return @Anserwed;​
END
GO
/****** Object:  UserDefinedFunction [dbo].[AllRatingVCRLecture]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[AllRatingVCRLecture] 
(@ContactId bigint,@ClassroomId Bigint)
RETURNS bit
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Anserwed bit

	select @Anserwed = ( CASE WHEN COUNT(distinct GENItems.id) <= COUNT(distinct GENRatings.Id)  THEN cast(1 as bit) else cast(0 as bit) END)
FROM   dbo.GENClassrooms      
inner JOIN dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id
LEFT JOIN  Course_Session ON Course_Session.CourseId = GENTypes.Id 
inner join TLMSClassroom_Session on dbo.GENClassrooms.Id = TLMSClassroom_Session.ClassroomId and TLMSClassroom_Session.SessionId is not null and  Course_Session.SessionId=TLMSClassroom_Session.SessionId
inner join GENItems on GENItems.Id = TLMSClassroom_Session.SessionId  and  dbo.GENItems.IsDeleted=0 
inner join GENEmployees on GENEmployees.Id = TLMSClassroom_Session.InstructorId
left join GENRatings on GENRatings.EntityId = TLMSClassroom_Session.id and GENRatings.BaseEntityId = 198 and EntityId2 is  null
and GENRatings.Userid = (select Userid from GENContacts where id = @ContactId)
where ClassroomId = @ClassroomId
return @Anserwed;​
END

GO
