CREATE FUNCTION [dbo].[AllRatingVCRLectureInstructor] 
(@ContactId bigint,@ClassroomId Bigint)
RETURNS bit
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Anserwed bit

	select @Anserwed = ( CASE WHEN COUNT(distinct GENItems.id) <= COUNT(GENRatings.Id)  THEN cast(1 as bit) else cast(0 as bit) END)
FROM   dbo.GENClassrooms      
inner JOIN dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id
LEFT JOIN  Course_Session ON Course_Session.CourseId = GENTypes.Id 
inner join TLMSClassroom_Session on dbo.GENClassrooms.Id = TLMSClassroom_Session.ClassroomId and TLMSClassroom_Session.SessionId is not null and  Course_Session.SessionId=TLMSClassroom_Session.SessionId
inner join GENItems on GENItems.Id = TLMSClassroom_Session.SessionId  and  dbo.GENItems.IsDeleted=0 
inner join GENEmployees on GENEmployees.Id = TLMSClassroom_Session.InstructorId
left join GENRatings on GENRatings.EntityId = TLMSClassroom_Session.id and GENRatings.BaseEntityId = 198 and EntityId2 is not null
and GENRatings.Userid = (select Userid from GENContacts where id = @ContactId)
where ClassroomId = @ClassroomId
return @Anserwed;​
END
