/****** Object:  UserDefinedFunction [dbo].[AttendanceCall]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[AttendanceCall] 
(@ContactId bigint,@ClassroomId Bigint)
RETURNS int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Atten decimal(18,2)
​
	select @Atten = (case when res.VCRDur > 0
    then cast(((cast(res.AttDur as dec(18,4))/cast(res.VCRDur as dec(18,4))) * 100.00) as decimal(18,2)) else cast(100 as decimal(18,2)) end) from (
select GENClassroom_GENContact.StudentId,(count(distinct Classroom_Attendance.Id)) as AttDur
,(select count(distinct Id) as Dur from TLMSClassroom_Session 
where TLMSClassroom_Session.ClassroomId = GENClassroom_GENContact.ClassroomId and TLMSClassroom_Session.TypeSession =0 ) as VCRDur,
GENContacts.Name AS StudentName,GENClassroom_GENContact.ClassroomId
from GENClassroom_GENContact
inner join GENContacts ON GENClassroom_GENContact.StudentId = GENContacts.Id
left join TLMSClassroom_Session on  GENClassroom_GENContact.ClassroomId = TLMSClassroom_Session.ClassroomId
left join Classroom_Attendance ON TLMSClassroom_Session.SessionId = Classroom_Attendance.SessionId and
GENContacts.Id = Classroom_Attendance.StudentId and GENClassroom_GENContact.ClassroomId = Classroom_Attendance.ClassroomId
and ExecuseId IN (77113,77118)
where GENClassroom_GENContact.ClassroomId = @ClassroomId  
and GENClassroom_GENContact.StudentId = @ContactId
group by GENClassroom_GENContact.StudentId,GENClassroom_GENContact.ClassroomId,GENContacts.Name
) as res

where StudentId = @ContactId

	RETURN @Atten
​
END
GO
/****** Object:  UserDefinedFunction [dbo].[CalculateAge]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create FUNCTION [dbo].[CalculateAge] (@ContactId bigint )
RETURNS int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Age int
​
	-- Add the T-SQL statements to compute the return value here
	SELECT @Age = DATEDIFF(year,Birthdate ,GETDATE()) FROM GENContacts Where GENContacts.Id= @ContactId
​
	-- Return the result of the function
	RETURN @Age
​
END
GO
/****** Object:  UserDefinedFunction [dbo].[ContactCalcExpireDate]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


Create FUNCTION [dbo].[ContactCalcExpireDate] (@Id bigint)
RETURNS DateTime
AS
BEGIN
	-- Declare the return variable here
	DECLARE @ExpireDate DateTime
	-- Add the T-SQL statements to compute the return value here
	SELECT @ExpireDate = ( DATEADD(DAY ,365,GENContacts.DateCreated))
	From GENContacts 
	where GENContacts.Id=@Id
	-- Return the result of the function
	RETURN @ExpireDate
END
GO
