CREATE FUNCTION [dbo].[CountChatGroupMessages](
    @GroupId BIGINT,
    @UserREId nvarchar(256)
)
RETURNS int
AS 
BEGIN

    RETURN (select count(*)
	from GENChatGroupMessages me
	INNER JOIN GENChatMessages ON me.ChatMessageId = GENChatMessages.Id
	where GENChatMessages.ChatGroupId = @GroupId and me.UserReceiverId=@UserREId and me.IsSeen=0);
END;
GO
