CREATE FUNCTION [dbo].[countMessages](
    @UserSenderId nvarchar(256),
    @UserREId nvarchar(256)
)
RETURNS int
AS 
BEGIN

    RETURN (select count(*)
	from GENChatMessages me
	where me.UserSenderId=@UserSenderId and me.UserReceiverId=@UserREId and me.IsSeen=0);
END;
