/****** Object:  UserDefinedFunction [dbo].[Diff_BetweenDates]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[Diff_BetweenDates]
(
  
   @startDate DATETIME,
     @endDate DATETIME
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
 DECLARE @Date nvarchar(Max) 
DECLARE @start DATETIME = @startDate ,
@end DATETIME = @endDate ,
@x INT;

SET @x = DATEDIFF(s, @start, @end);

SELECT @Date= CONVERT(VARCHAR(10), ( @x / 86400 )) + 'd - '
        + CONVERT(VARCHAR(10), ( ( @x % 86400 ) / 3600 )) + 'h:'
        + CONVERT(VARCHAR(10), ( ( ( @x % 86400 ) % 3600 ) / 60 ))
        + 'm:' + CONVERT(VARCHAR(10), ( ( ( @x % 86400 ) % 3600 ) % 60 ))
        + 's';
		  RETURN  @Date
		end
GO
/****** Object:  UserDefinedFunction [dbo].[Diff_BetweenDates_HoursAndMin]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[Diff_BetweenDates_HoursAndMin]
(
  
   @startDate DATETIME,
     @endDate DATETIME
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
 
DECLARE @sd DATETIME = @startDate
DECLARE @ed DATETIME = @endDate
DECLARE @result nvarchar(Max)

SELECT @result= CAST(DATEDIFF(ss, @sd, @ed) / 3600 AS VARCHAR(10)) + ' H ' +
       CAST((DATEDIFF(ss, @sd, @ed) -  3600 * (DATEDIFF(ss, @sd, @ed) / 3600)) / 60 AS VARCHAR(10)) + ' M'
		  RETURN  @result
		end
GO
/****** Object:  UserDefinedFunction [dbo].[Diff_BetweenDates_HoursAndMin_Lang]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[Diff_BetweenDates_HoursAndMin_Lang]
(
  
   @startDate DATETIME,
     @endDate DATETIME,
	 @lang nvarchar(Max)
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
 
DECLARE @sd DATETIME = @startDate
DECLARE @ed DATETIME = @endDate
DECLARE @result nvarchar(Max)

		IF (@lang =N'en' )
		BEGIN
		  SELECT @result= CAST(DATEDIFF(ss, @sd, @ed) / 3600 AS VARCHAR(10)) + ' H ' +
			   CAST((DATEDIFF(ss, @sd, @ed) -  3600 * (DATEDIFF(ss, @sd, @ed) / 3600)) / 60 AS VARCHAR(10)) + ' M'
	 
		
		END
 
		ELSE
		BEGIN
		 SELECT @result= CAST(DATEDIFF(ss, @sd, @ed) / 3600 AS VARCHAR(10)) + N' س ' +
			   CAST((DATEDIFF(ss, @sd, @ed) -  3600 * (DATEDIFF(ss, @sd, @ed) / 3600)) / 60 AS VARCHAR(10)) + N' د'
				end
RETURN  @result	
END
GO
/****** Object:  UserDefinedFunction [dbo].[f_check_string]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[f_check_string] (@string VARCHAR(MAX)) RETURNS INT AS BEGIN
    DECLARE @ret_val INT;
    SET @ret_val=1;
    IF (@string like '%''%') SET @ret_val=0
    ELSE IF (@string like '%--%') SET @ret_val=0
    ELSE IF (@string like '%/*%') SET @ret_val=0
    ELSE IF (@string like '%*/%') SET @ret_val=0
    ELSE IF (@string like '%@') SET @ret_val=0
    ELSE IF (@string like '%@@%') SET @ret_val=0
    ELSE IF (@string like '%char%') SET @ret_val=0
    ELSE IF (@string like '%nchar%') SET @ret_val=0
    ELSE IF (@string like '%varchar%') SET @ret_val=0
    ELSE IF (@string like '%nvarchar%') SET @ret_val=0
    
    ELSE IF (@string like '%select %') SET @ret_val=0
    ELSE IF (@string like '%insert %') SET @ret_val=0
    ELSE IF (@string like '%update %') SET @ret_val=0
    ELSE IF (@string like '%delete %') SET @ret_val=0
    ELSE IF (@string like '%from%') SET @ret_val=0
    ELSE IF (@string like '%table%') SET @ret_val=0
 
    ELSE IF (@string like '%drop%') SET @ret_val=0
    ELSE IF (@string like '%create%') SET @ret_val=0
    ELSE IF (@string like '%alter%') SET @ret_val=0
 
    ELSE IF (@string like '%begin%') SET @ret_val=0
    ELSE IF (@string like '%end%') SET @ret_val=0
 
    ELSE IF (@string like '%grant%') SET @ret_val=0
    ELSE IF (@string like '%deny%') SET @ret_val=0
 
    ELSE IF (@string like '%exec%') SET @ret_val=0
    ELSE IF (@string like '%sp_%') SET @ret_val=0
    ELSE IF (@string like '%xp_%') SET @ret_val=0
 
    ELSE IF (@string like '%cursor%') SET @ret_val=0
    --ELSE IF (@string like '%fetch%') SET @ret_val=0
 
    ELSE IF (@string like '%kill%') SET @ret_val=0
    ELSE IF (@string like '%open%') SET @ret_val=0
 
    ELSE IF (@string like '%sysobjects%') SET @ret_val=0
    ELSE IF (@string like '%syscolumns%') SET @ret_val=0
    ELSE IF (@string like '%sys%') SET @ret_val=0;
 
    RETURN (@ret_val);
END;
GO
/****** Object:  UserDefinedFunction [dbo].[fn_Activity_OverDue]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_Activity_OverDue]
(
   @ActivityId bigint
   ,@CurrentStatusId bigint
)
RETURNS bit-- or whatever length you need
AS
BEGIN
declare @IsOverDue bit
declare @SelectedActivityId bigint =0
Declare @PlannedStatusId bigint 
select  @PlannedStatusId = Id from GENStatus where Name='Planned'
declare @OverDueTime datetime = DATEADD(HOUR, -2, GETDATE())

 
select @SelectedActivityId = Id from CRMSRVTicket_Comment

where Id = @ActivityId and IsDeleted =0 and IsCancelled=0 and StatusId = @PlannedStatusId and  CAST( ActionDate AS Datetime) >=CAST( @OverDueTime AS Datetime)

if((@SelectedActivityId=0 or @SelectedActivityId is null) and @CurrentStatusId =@PlannedStatusId)
begin
set @IsOverDue = 1
end
else
begin
set @IsOverDue =0
end
    RETURN  @IsOverDue

END
GO
