CREATE FUNCTION [dbo].[fn_Activity_PreviousAction]
(
   @ActivityId bigint = null
  
)
RETURNS nvarchar(500)-- or whatever length you need
AS
BEGIN
 
declare @SelectedActionName nvarchar(500)
 

 
select @SelectedActionName = dbo.GENCommentTypes.Name
FROM             dbo.CRMSRVTicket_Comment LEFT OUTER JOIN
                         dbo.GENCommentTypes ON dbo.CRMSRVTicket_Comment.CommentTypeId = dbo.GENCommentTypes.Id
				where	dbo.CRMSRVTicket_Comment.Id	  = @ActivityId 

 
    RETURN  @SelectedActionName

END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_ActivityCount_ByEntityandBaseEntityId]    Script Date: 7/1/2026 10:44:55 AM ******/
