CREATE FUNCTION [dbo].[fn_ActivityCount_ByEntityandBaseEntityId_TypeName]
(
 @EntityId bigint,
   @BaseEntityId bigint,
   @TypeName nvarchar(500)

)
RETURNS int -- or whatever length you need
AS
BEGIN
  DECLARE @count int
 
 
SELECT top(1)   @count=   COUNT(  dbo.CRMSRVTicket_Comment.Id)
FROM            dbo.CRMSRVTicket_Comment LEFT OUTER JOIN
                         dbo.GENCommentTypes ON dbo.CRMSRVTicket_Comment.CommentTypeId = dbo.GENCommentTypes.Id
WHERE        (dbo.CRMSRVTicket_Comment.BaseEntityId = @BaseEntityId and dbo.CRMSRVTicket_Comment.EntityId = @EntityId) and dbo.CRMSRVTicket_Comment.IsDeleted = 0

 and  dbo.GENCommentTypes.Name like '%Call%'
  RETURN  @count
END
