GO
Create FUNCTION [dbo].[fn_Address_Translate_ByKeyandId]
(
   @id bigint,
   @Key nvarchar(500),
   @langCode nvarchar(500)
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
-- declare @id bigint = 2
--declare @Key nvarchar(500) = 'Name'
declare @Value nvarchar(500) 
 
 if @Key ='Name'

 begin
select top(1)  @Value= value from Branch_TranslateView 

where BranchId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = Name from Branch_TranslateView where Id =@id
end
 end
  if @Key ='Description'

 begin
select top(1)  @Value= value from Branch_TranslateView 

where BranchId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = [Description] from Branch_TranslateView where Id =@id
end
 end
   if @Key ='Address'

 begin
select top(1)  @Value= value from Branch_TranslateView 

where BranchId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = [Address] from Branch_TranslateView where Id =@id
end
 end
 if @Key ='String1'

 begin
select top(1)  @Value= value from Branch_TranslateView 

where BranchId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)   @Value = String1 from Branch_TranslateView where Id =@id
end
 end

 if @Key ='String2'

 begin
select top(1)  @Value= value from Branch_TranslateView 

where BranchId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)   @Value = String2 from Branch_TranslateView where Id =@id
end
 end

 if @Key ='String3'

 begin
select top(1)  @Value= value from Branch_TranslateView 

where BranchId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = String3 from Branch_TranslateView where Id =@id
end
 end
 if @Key ='String4'

