/****** Object:  UserDefinedFunction [dbo].[FN_CalculateCompletionPercentage]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

​
CREATE FUNCTION [dbo].[FN_CalculateCompletionPercentage] ( @compId bigint )
RETURNS float
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Percentage FLOAT
	
	SELECT @Percentage = (SUM(ISNULL(CompletionPercentage,0))/SUM(TotalRequiredProgressValue)) * 100
	FROM GENContactProgressCompletionDetails
	WHERE ContactProgressCompletionId = @compId​
	GROUP BY GENContactProgressCompletionDetails.ContactProgressCompletionId
	-- Return the result of the function
	RETURN @Percentage
​
END
GO
/****** Object:  UserDefinedFunction [dbo].[FN_CalculateEllapsedTime]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

​
CREATE FUNCTION [dbo].[FN_CalculateEllapsedTime] ( @compDetailId bigint )
RETURNS float
AS
BEGIN
	-- Declare the return variable here
	DECLARE @EllapsedTime BIGINT
​
	-- Add the T-SQL statements to compute the return value here
	SELECT @EllapsedTime = (CASE WHEN TotalVideoDuration IS NOT NULL THEN TotalVideoDuration - FirstVideoPlay ELSE 
	TotalFilePages - CurrentReadPages END) from GENContactProgressCompletionDetails 
	where Id = @compDetailId
​
	-- Return the result of the function
	RETURN @EllapsedTime 
​
END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_CalculateExamQuestions]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create FUNCTION [dbo].[fn_CalculateExamQuestions]
(
	-- Add the parameters for the function here
	@ExamId bigint
 
)
RETURNS  decimal (18,2)
AS
BEGIN
	
	DECLARE @Total decimal (18,2)

	-- Add the T-SQL statements to compute the return value here
	SELECT   @Total=   sum(  dbo.GENPolls.Weight)
FROM            dbo.PollCategoryandPolls LEFT OUTER JOIN
                         dbo.GENPolls ON dbo.PollCategoryandPolls.PollId = dbo.GENPolls.Id
	where dbo.PollCategoryandPolls.PollCategoryId =@ExamId

	-- Return the result of the function
	--set @date = select DATEADD(HOUR,-2,@date)
	RETURN @Total
	end
GO
/****** Object:  UserDefinedFunction [dbo].[FN_CalculatePercentage]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

​
CREATE FUNCTION [dbo].[FN_CalculatePercentage] ( @compDetailId bigint )
RETURNS float
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Percentage FLOAT
​
	-- Add the T-SQL statements to compute the return value here
	SELECT @Percentage = (CASE WHEN TotalVideoDuration > 0 THEN ROUND((CAST(FirstVideoPlay AS float)/CAST(TotalVideoDuration AS float)) * 100,0)  ELSE 
	CASE WHEN TotalFilePages > 0 THEN ROUND((CAST(CurrentReadPages AS float)/CAST(TotalFilePages AS float)) * 100,0) ELSE 
	CASE WHEN FileVideoDownloaded = 1 THEN 100.0 ELSE 0.0 END END END) from GENContactProgressCompletionDetails 
	where Id = @compDetailId
​
	-- Return the result of the function
	RETURN @Percentage
​
END
GO
