/****** Object:  UserDefinedFunction [dbo].[fn_Concatenate2Strings]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_Concatenate2Strings]
(
   @string1 nvarchar(128),
    @string2 nvarchar(128)
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
if(@string1 is null)
begin
set @string1 ='';
end
if(@string2 is null)
begin
set @string2 ='';
end
  DECLARE @ConcatenatedString nvarchar(Max) =@string1+','+@string2
    DECLARE @ResultConcatenatedString nvarchar(Max) 
 SELECT @ResultConcatenatedString= LEFT(@ConcatenatedString, LEN(REPLACE(@ConcatenatedString, ',', '')))
 set @ConcatenatedString =@ResultConcatenatedString
 SELECT @ResultConcatenatedString= right(@ConcatenatedString, LEN(REPLACE(@ConcatenatedString, ',', '')))
 RETURN  @ResultConcatenatedString
END
GO
