/****** Object:  UserDefinedFunction [dbo].[FN_ConvertDatetoArabic]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[FN_ConvertDatetoArabic]
(
	-- Add the parameters for the function here
	@type NVARCHAR(500)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
	-- Declare the return variable here
declare @str NVARCHAR(500) = @type
	
Set @str = replace (@str , N'1',N'١')
Set @str = replace (@str , N'2',N'٢')
Set @str = replace (@str , N'3',N'٣')
Set @str = replace (@str , N'4',N'٤')
