/****** Object:  UserDefinedFunction [dbo].[FN_ConvertDaystoArabic]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[FN_ConvertDaystoArabic]
(
	-- Add the parameters for the function here
	@type nvarchar(500),@LangCode nvarchar(MAX)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
	-- Declare the return variable here
	IF (@LangCode =N'ar' )
	begin
	Set @type = replace (@type , N'Saturday',N'السبت')
	Set @type = replace (@type , N'Sunday',N'الأحد')
	Set @type = replace (@type , N'Monday',N'الأثنين')
	Set @type = replace (@type , N'Tuesday',N'الثلاثاء')
	Set @type = replace (@type , N'Wednesday',N'الأربعاء')
	Set @type = replace (@type , N'Thursday',N'الخميس')
	Set @type = replace (@type , N'Friday',N'الجمعة')
	
	Set @type = replace (@type , N'1',N'١')
	Set @type = replace (@type , N'2',N'٢')
	Set @type = replace (@type , N'3',N'٣')
	Set @type = replace (@type , N'4',N'٤')
	Set @type = replace (@type , N'5',N'٥')
	Set @type = replace (@type , N'6',N'٦')
	Set @type = replace (@type , N'7',N'٧')
	Set @type = replace (@type , N'8',N'٨')
	Set @type = replace (@type , N'9',N'٩')
	Set @type = replace (@type , N'0',N'٠')
	END

	ELSE
	begin
	RETURN @type
	END
	-- Return the result of the function
RETURN @type

END
GO
