/****** Object:  UserDefinedFunction [dbo].[fn_Correct_QuestionAnswers]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_Correct_QuestionAnswers]
(
   @PollId bigint
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
DECLARE @QuestionType INT
DECLARE @Answer NVARCHAR(Max) 
SELECT @QuestionType = QuestionType FROM GENPolls WHERE ID = @PollId
IF(@QuestionType = 0 OR @QuestionType = 2)
BEGIN
SELECT @Answer = COALESCE(@Answer + ',', '') + Answer
FROM GENPollAnswers
where GENPollAnswers.PollId = @PollId and GENPollAnswers.IsCorrect =1
END
ELSE IF(@QuestionType = 1)
BEGIN
SELECT @Answer = CAST([Value] AS NVARCHAR(Max))
FROM GENPolls WHERE ID = @PollId
END
 

RETURN  @Answer

END
GO
