  ,@CompanyId int
  ,@GroupTypeId int
  ,@CourseId int
)
RETURNS int -- or whatever length you need
AS
BEGIN
  DECLARE @VCRCount int =0
SELECT @VCRCount = COUnt(Id)
FROM dbo.GENClassrooms
