Create FUNCTION [dbo].[fn_Course_Status]
(
   @CourseStatusId int
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
  DECLARE @StatusName nvarchar(Max) 

  if @CourseStatusId =0
  begin
  set @StatusName = 'Requested'
  end
  else if  @CourseStatusId =1
  begin
    set @StatusName = 'Canceled'
  end
  else if  @CourseStatusId =2
  begin
    set @StatusName = 'Rejected'
  end
  else if  @CourseStatusId =3
  begin
    set @StatusName = 'Registred'
  end
  else if  @CourseStatusId =3
  begin
    set @StatusName = 'Done'
  end
 RETURN  @StatusName
END
GO
