/****** Object:  UserDefinedFunction [dbo].[fn_EmpCreatedCRMTicketLastDay]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_EmpCreatedCRMTicketLastDay]
(
	-- Add the parameters for the function here
	@UserId NVARCHAR(250)
)
RETURNS INT
AS
BEGIN
	
	DECLARE @Count INT
	DECLARE @date Datetime

	-- Add the T-SQL statements to compute the return value here
	SELECT @Count = COUNT(Id) FROM CRMTickets WHERE CreatedById = @UserId AND DateCreated BETWEEN DATEADD(day,-1,GETDATE()) AND GETDATE()

	-- Return the result of the function
	RETURN @Count

END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_EmpLastActivty]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 13 May 2019
-- Description:	Total Count Created
-- =============================================
CREATE FUNCTION [dbo].[fn_EmpLastActivty]
(
	-- Add the parameters for the function here
	@UserName NVARCHAR(250)
)
RETURNS DATETIME
AS
BEGIN
	
	DECLARE @date Datetime

	-- Add the T-SQL statements to compute the return value here
	SELECT TOP 1 @date =DATEADD(HOUR,2,EventDateUTC)  FROM AuditLogs WHERE UserName = @UserName
	ORDER BY EventDateUTC DESC

	-- Return the result of the function
	--set @date = select DATEADD(HOUR,-2,@date)
	RETURN @date

END
GO
