/****** Object:  UserDefinedFunction [dbo].[fn_Exam_QuestionCount]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_Exam_QuestionCount]
(
   @ExamId bigint
)
RETURNS int -- or whatever length you need
AS
BEGIN
  DECLARE @QuestionCount int =0
SELECT   
                   @QuestionCount=    COUnt( DISTINCT( dbo.GENPolls.Id))
FROM            dbo.GENPollCategories RIGHT OUTER JOIN
                         dbo.PollCategoryandPolls ON dbo.GENPollCategories.Id = dbo.PollCategoryandPolls.PollCategoryId LEFT OUTER JOIN
                         dbo.GENPollAnswers RIGHT OUTER JOIN
                         dbo.GENPolls ON dbo.GENPollAnswers.PollId = dbo.GENPolls.Id ON dbo.PollCategoryandPolls.PollId = dbo.GENPolls.Id
WHERE        (dbo.PollCategoryandPolls.PollCategoryId = @ExamId)

    RETURN  @QuestionCount

END
GO
