/****** Object:  UserDefinedFunction [dbo].[fn_GetEmployeeFirstNameBy_EmployeeId]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_GetEmployeeFirstNameBy_EmployeeId]
(
   @Id bigint
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
declare @ConfigValue nvarchar(max) = null
select @ConfigValue = Value from GENConfigurations where Name ='AssignToName'

if ( @ConfigValue is null or @ConfigValue = 'FirstName')
  DECLARE @FirstName nvarchar(Max) 

begin
SELECT top(1) @FirstName =FirstName COLLATE Latin1_General_CI_AS
FROM GENEmployees
 where Id =@Id
 
 end

 if (@ConfigValue ='FirstCharacter_LastName')
 begin
  
SELECT top(1) @FirstName =(SUBSTRING(FirstName COLLATE Latin1_General_CI_AS, 1, 1)+'.'+ ThirdName COLLATE Latin1_General_CI_AS )
FROM GENEmployees
 where Id =@Id


 end
  if @ConfigValue ='FirstCharacter_LastCharacter'
 begin
  
SELECT top(1) @FirstName =(SUBSTRING(FirstName COLLATE Latin1_General_CI_AS, 1, 1)+' ' +SUBSTRING(ThirdName COLLATE Latin1_General_CI_AS, 1, 1) )
FROM GENEmployees
 where Id =@Id


 end
  RETURN  @FirstName
END
GO
