/****** Object:  UserDefinedFunction [dbo].[FN_GetExamResultType]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 31/08/2020
-- Description:	Get Poll Category Enum
-- =============================================
CREATE FUNCTION [dbo].[FN_GetExamResultType]
(
	-- Add the parameters for the function here
	@type int,
	@langCode nvarchar(500)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @typeName NVARCHAR(MAX)

	-- Add the T-SQL statements to compute the return value here
	IF(@type = 0 AND @langCode = 'ar')
	SET @typeName = N'بدأ'
	ELSE IF(@type = 0)
	SET @typeName = 'Started'

	IF(@type = 1 AND @langCode = 'ar')
	SET @typeName = N'تم إسقاطه'
	ELSE IF(@type = 1)
	SET @typeName = 'Dropped'

	IF(@type = 2 AND @langCode = 'ar')
	SET @typeName = N'تم'
	ELSE IF(@type = 2)
	SET @typeName = 'Done'

	IF(@type = 3 AND @langCode = 'ar')
	SET @typeName = N'قيد الإجابه'
	ELSE IF(@type = 3)
	SET @typeName = 'Answering in progress'

	IF(@type = 4 AND @langCode = 'ar')
	SET @typeName = N'تم إنهاء الإمتحان'
	ELSE IF(@type = 4)
	SET @typeName = 'Exam completed'
	
	RETURN @typeName

END
GO
/****** Object:  UserDefinedFunction [dbo].[FN_GetExamType]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 31/08/2020
-- Description:	Get Poll Category Enum
-- =============================================
CREATE FUNCTION [dbo].[FN_GetExamType]
(
	-- Add the parameters for the function here
	@type int,
	@langCode nvarchar(500)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @typeName NVARCHAR(MAX)

	-- Add the T-SQL statements to compute the return value here
	IF(@type = 0 AND @langCode = 'ar')
	SET @typeName = N'النهائي'
	ELSE IF(@type = 0)
	SET @typeName = 'Final'

	IF(@type = 1 AND @langCode = 'ar')
	SET @typeName = N'منتصف المدة'
	ELSE IF(@type = 1)
	SET @typeName = 'Midterm'

	IF(@type = 2 AND @langCode = 'ar')
	SET @typeName = N'تقييم'
	ELSE IF(@type = 2)
	SET @typeName = 'Quiz'

	IF(@type = 3 AND @langCode = 'ar')
	SET @typeName = N'اختبار'
	ELSE IF(@type = 3)
	SET @typeName = 'Exercise'

	IF(@type = 4 AND @langCode = 'ar')
	SET @typeName = N'تقدير'
	ELSE IF(@type = 4)
	SET @typeName = 'Assessment'

	IF(@type = 5 AND @langCode = 'ar')
	SET @typeName = N'مهمة'
	ELSE IF(@type = 5)
	SET @typeName = 'Assignment'

	IF(@type = 6 AND @langCode = 'ar')
	SET @typeName = N'استبيان'
	ELSE IF(@type = 6)
	SET @typeName = 'Questionaire'

	IF(@type = 7 AND @langCode = 'ar')
	SET @typeName = N'تصويت'
	ELSE IF(@type = 7)
	SET @typeName = 'Poll'

	IF(@type = 8 AND @langCode = 'ar')
	SET @typeName = N'أخرى'
	ELSE IF(@type = 8)
	SET @typeName = 'Other'



	IF(@type = 9 AND @langCode = 'ar')
	SET @typeName = N'PreAssessment'
	ELSE IF(@type = 9)
	SET @typeName = 'PreAssessment'


		IF(@type = 10 AND @langCode = 'ar')
	SET @typeName = N'PostAssessment'
	ELSE IF(@type = 10)
	SET @typeName = 'PostAssessment'

		IF(@type = 11 AND @langCode = 'ar')
	SET @typeName = N'TrainerAssessment'
	ELSE IF(@type = 11)
	SET @typeName = 'TrainerAssessment'

	
		IF(@type = 12 AND @langCode = 'ar')
	SET @typeName = N'VCRAssessment'
	ELSE IF(@type = 12)
	SET @typeName = 'VCRAssessment'

	
		IF(@type = 13 AND @langCode = 'ar')
	SET @typeName = N'AcceptanceTest'
	ELSE IF(@type = 13)
	SET @typeName = 'AcceptanceTest'

	IF (@type IS NULL AND @langCode = 'ar')
	SET @typeName = N'امتحان'
	ELSE IF (@type IS NULL)
	SET @typeName = 'Exam'




	-- Return the result of the function
	RETURN @typeName

END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_GetPriceString_ById]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_GetPriceString_ById]
(
   @BaseEntityId bigint,
   @EntityId bigint,
   @LangCode nvarchar(50),
   @IsLocal bit
)
RETURNS nvarchar(500) -- or whatever length you need
AS
BEGIN
  DECLARE @PriceString nvarchar(150) = null

if @IsLocal = 1
begin

SELECT  top(1)  @PriceString= (REPLACE(CONVERT(nvarchar, CONVERT(money,NetPrice),1), '.00', '')+' '+dbo.fn_Currency_Translate_ByKeyandId(CurrencyId,'Name',@LangCode) ) 
FROM              GENEntityPricings
where BaseEntityId =@BaseEntityId and EntityId =@EntityId and (FromDateTime is not null and FromDateTime <= getdate())and (ToDateTime is not null and
ToDateTime >= getdate()) and CurrencyId =16 AND NetPrice > 0 AND NetPrice IS NOT NULL
end

 if @IsLocal = 0
begin
SELECT  top(1)  @PriceString= (REPLACE(CONVERT(nvarchar, CONVERT(money,NetPrice),1), '.00', '')+' '+dbo.fn_Currency_Translate_ByKeyandId(CurrencyId,'Name',@LangCode) ) 
FROM              GENEntityPricings
where BaseEntityId =@BaseEntityId and EntityId =@EntityId and (FromDateTime is not null and FromDateTime <= getdate())and 
(ToDateTime is not null and ToDateTime >= getdate()) and CurrencyId =21  AND NetPrice > 0 AND NetPrice IS NOT NULL


end
 if (@IsLocal = 1 and  @PriceString is null)
begin

SELECT  top(1)  @PriceString= (REPLACE(CONVERT(nvarchar, CONVERT(money,NetPrice),1), '.00', '')+' '+dbo.fn_Currency_Translate_ByKeyandId(CurrencyId,'Name',@LangCode) ) 
FROM              GENEntityPricings
where BaseEntityId =@BaseEntityId and EntityId =@EntityId and CurrencyId =16 and FromDateTime is null and ToDateTime is null  AND NetPrice > 0 AND NetPrice IS NOT NULL

end
 if (@IsLocal = 0 and  @PriceString is null)
begin

SELECT  top(1)  @PriceString= (REPLACE(CONVERT(nvarchar, CONVERT(money,NetPrice),1), '.00', '')+' '+dbo.fn_Currency_Translate_ByKeyandId(CurrencyId,'Name',@LangCode) ) 
FROM              GENEntityPricings
where BaseEntityId =@BaseEntityId and EntityId =@EntityId  and CurrencyId =21  and FromDateTime is null and ToDateTime is null  AND NetPrice > 0 AND NetPrice IS NOT NULL

end


 if  @PriceString is null
begin
SELECT  top(1)  @PriceString= (REPLACE(CONVERT(nvarchar, CONVERT(money,NetPrice),1), '.00', '')+' '+dbo.fn_Currency_Translate_ByKeyandId(CurrencyId,'Name',@LangCode) ) 
FROM              GENEntityPricings
where BaseEntityId =@BaseEntityId and EntityId =@EntityId  and IsDefault =1  AND NetPrice > 0 AND NetPrice IS NOT NULL
end
    RETURN  @PriceString

END
GO
