/****** Object:  UserDefinedFunction [dbo].[fn_ItemCount_AttendanceInSessions]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create FUNCTION [dbo].[fn_ItemCount_AttendanceInSessions]
(
   @SessionId bigint,@VcrId bigint ,@InstructorId bigint
)
RETURNS int -- or whatever length you need
AS
BEGIN
  DECLARE @ItemCount int
SELECT    @ItemCount=   Count(Classroom_Attendance.Id)
From Classroom_Attendance 
inner join GENClassrooms ON Classroom_Attendance.ClassroomId =  GENClassrooms.Id  
inner join GENClassroom_GENContact ON Classroom_Attendance.ClassroomId=GENClassroom_GENContact.ClassroomId 
and Classroom_Attendance.StudentId= GENClassroom_GENContact.StudentId
inner join GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id 
inner join TLMSClassroom_Session ON Classroom_Attendance.ClassroomId=TLMSClassroom_Session.ClassroomId and  Classroom_Attendance.SessionId= TLMSClassroom_Session.SessionId 
inner join GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id
left join GENListValues on Classroom_Attendance.ExecuseId = GENListValues.Id
inner join GENEmployees ON TLMSClassroom_Session.InstructorId=GENEmployees.Id  
where Classroom_Attendance.ClassroomId=@VcrId and GENEmployees.Id=@InstructorId   and GENItems.Id =@SessionId

    RETURN  @ItemCount

END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_ItemCount_ClassId]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[fn_ItemCount_ClassId]
(
 @GENClassrooms bigint
)
RETURNS int -- or whatever length you need
AS
BEGIN
  DECLARE @ItemCount int
SELECT    @ItemCount=  count(Course_Session.Id) 
FROM              Course_Session
inner join GENItems ON  Course_Session.SessionId=GENItems.Id
inner join TLMSClassroom_Session ON GENItems.Id=TLMSClassroom_Session.SessionId
inner join GENClassrooms ON TLMSClassroom_Session.ClassroomId=GENClassrooms.Id
where  GENItems.IsActive =1 and  GENItems.IsPublish =1 AND (GENItems.IsDeleted =0 OR GENItems.IsDeleted IS NULL)
and GENClassrooms.Id=@GENClassrooms
    RETURN  @ItemCount

END
GO
