/****** Object:  UserDefinedFunction [dbo].[fn_MessageTime]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_MessageTime] (@Date datetime)
RETURNS nvarchar(MAX)
AS
BEGIN
	DECLARE @dateString nvarchar(MAX)
	-- Add the T-SQL statements to compute the return value here
	SELECT @dateString = 
	case 
		when (DATEADD(day, -1, CAST(getdate() as date)) = CAST(@Date as date)) then 'YesterDay'
		when CAST(getdate() as date) = CAST(@Date as date) then 'Today'
		else format(@Date,'dddd, dd MMMM yyyy')
	END
	-- Return the result of the function
	RETURN @dateString
END
GO
