-- Description:	Get progress check 
-- =============================================
CREATE FUNCTION [dbo].[FN_ProgressDone]
(
	-- Add the parameters for the function here
	@ClassroomId BIGINT, @ContactId BIGINT, @EntityId BIGINT, @BaseEntityId BIGINT
)
RETURNS BIT
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Checked BIT

	-- Add the T-SQL statements to compute the return value here
	SELECT @Checked = (CASE WHEN CompletionPercentage = 100 THEN 1 ELSE 0 END)
	FROM GENContactProgressCompletions WHERE ClassroomId = @ClassroomId AND ContactId = @ContactId AND EntityId = @EntityId AND BaseEntityId = @BaseEntityId

	-- Return the result of the function
	RETURN @Checked

END
GO
