/****** Object:  UserDefinedFunction [dbo].[fn_ReturnOrderStatus_Color]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_ReturnOrderStatus_Color]
(
   @ReturnOrderStatusId int
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
  DECLARE @StatusName nvarchar(Max) 

  if @ReturnOrderStatusId =0
  begin
  --set @StatusName = 'Requested'
  set @StatusName = 'darkgray'
  end
  else if  @ReturnOrderStatusId =1
  begin
    --set @StatusName = 'Canceled'
    set @StatusName = 'red'
  end
  else if  @ReturnOrderStatusId =2
  begin
    --set @StatusName = 'Rejected'
    set @StatusName = 'green'
  end
  else if  @ReturnOrderStatusId =3
  begin
    --set @StatusName = 'Rejected'
    set @StatusName = 'yellow'
  end
 RETURN  @StatusName
END
GO
/****** Object:  UserDefinedFunction [dbo].[fn_ReturnOrderStatusName]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_ReturnOrderStatusName]
(
   @ReturnOrderStatusId int,
   @lang varchar(30)  
)
RETURNS nvarchar(Max) -- or whatever length you need
AS
BEGIN
  DECLARE @StatusName nvarchar(Max) =
CASE WHEN @lang ='ar'
	    THEN 				
			CASE @ReturnOrderStatusId
			WHEN 0 THEN  N'طلب'  
			WHEN 1 THEN  N'رفض'  
			WHEN 2 THEN  N'تأكيد'
			WHEN 3 THEN N'أرجاع'
			END 
		ELSE
			CASE @ReturnOrderStatusId			
			WHEN 0 THEN  N'Requested'  
			WHEN 1 THEN  N'Rejected'  
			WHEN 2 THEN  N'Confirmed'
			WHEN 3 THEN N'Refund'
			END
END
return @StatusName
end
GO
