/****** Object:  UserDefinedFunction [dbo].[FN_SessionsType]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[FN_SessionsType]
(
	-- Add the parameters for the function here
	@type int,
	@langCode nvarchar(500)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @typeName NVARCHAR(MAX)

	-- Add the T-SQL statements to compute the return value here
	IF(@type = 0 AND @langCode = 'ar')
	SET @typeName = N'محاضرة'
	ELSE IF(@type = 0)
	SET @typeName = 'Lecture'

	IF(@type = 1 AND @langCode = 'ar')
	SET @typeName = N'راحة'
	ELSE IF(@type = 1)
	SET @typeName = 'Break'

	IF(@type = 2 AND @langCode = 'ar')
	SET @typeName = N'ورشة عمل'
	ELSE IF(@type = 2)
	SET @typeName = 'WorkShop'

	IF(@type = 3 AND @langCode = 'ar')
	SET @typeName = N'تجمع'
	ELSE IF(@type = 3)
	SET @typeName = 'Gathering'

	IF(@type = 4 AND @langCode = 'ar')
	SET @typeName = N'ندوة'
	ELSE IF(@type = 4)
	SET @typeName = 'Seminar'

	IF(@type = 5 AND @langCode = 'ar')
	SET @typeName = N'يوم تدريبي'
	ELSE IF(@type = 5)
	SET @typeName = 'TrainingDay'

	IF(@type = 6 AND @langCode = 'ar')
	SET @typeName = N'حلقة نقاش'
	ELSE IF(@type = 6)
	SET @typeName = 'DiscussionRing'

	IF(@type = 7 AND @langCode = 'ar')
	SET @typeName = N'أجتماع'
	ELSE IF(@type = 7)
	SET @typeName = 'Meetings'

	IF(@type = 8 AND @langCode = 'ar')
	SET @typeName = N'مؤتمر'
	ELSE IF(@type = 8)
	SET @typeName = 'Conferences'



	IF(@type = 9 AND @langCode = 'ar')
	SET @typeName = N'مبارايات'
	ELSE IF(@type = 9)
	SET @typeName = 'Matches'


		IF(@type = 10 AND @langCode = 'ar')
	SET @typeName = N'محاكاة'
	ELSE IF(@type = 10)
	SET @typeName = 'Simulation'

	--IF (@type IS NULL AND @langCode = 'ar')
	--SET @typeName = N'امتحان'
	--ELSE IF (@type IS NULL)
	--SET @typeName = 'Exam'
	-- Return the result of the function
	RETURN @typeName

END
GO
