/****** Object:  UserDefinedFunction [dbo].[fn_TCR_DealAmount]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fn_TCR_DealAmount]
(
   @dealId bigint
)
RETURNS Decimal(18,2) -- or whatever length you need
AS
BEGIN
  DECLARE @DealAmount Decimal =0
SELECT    @DealAmount=  sum(dbo.CRMDealItems.Total) 
FROM              CRMDealItems

					 
where DealId =@dealId
if @DealAmount is null 
begin
set @DealAmount = 0
end 
    RETURN  @DealAmount

END
GO
