/****** Object:  UserDefinedFunction [dbo].[fn_UserExamQuestionsDeagree]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create FUNCTION [dbo].[fn_UserExamQuestionsDeagree]
(
	-- Add the parameters for the function here
	@ContactId bigint,
	@ExamId bigint,
	@CourseId bigint
)
RETURNS  bigint
AS
BEGIN
	
	DECLARE @IsSuccess bit

	-- Add the T-SQL statements to compute the return value here
	select @IsSuccess = (case when SuccessScore > AnnouncedDegree then 0 else 1 end) from(
	SELECT  GENPollCategories.SuccessScore,(CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END) as AnnouncedDegree
	from GENExamAnswerHeaders
	inner JOIN GENPollCategories ON dbo.GENExamAnswerHeaders.ExamId = GENPollCategories.Id
	where examId =@ExamId and StudentId =@ContactId and CourseId =@CourseId
	) as res
	RETURN @IsSuccess
	end
GO
/****** Object:  UserDefinedFunction [dbo].[fn_UserExamQuestionsDeagreeWithChild]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create FUNCTION [dbo].[fn_UserExamQuestionsDeagreeWithChild]
(
	-- Add the parameters for the function here
	@ContactId bigint,
	@ExamId bigint,
	@CourseId bigint
)
RETURNS  bigint
AS
BEGIN
	
	DECLARE @IsSuccess bit

	-- Add the T-SQL statements to compute the return value here
	select @IsSuccess = (case when res.SuccessScore > res.AnnouncedDegree and ChildID is not null then (case when GENExam_GENType.Id is not null and ChildExam.Id is null then 0 else 1 end) else 1 end) from(
	SELECT  GENPollCategories.SuccessScore,(CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END) as AnnouncedDegree
	  ,ChildPoll.SuccessScore as childSuccessScore,GENExam_GENType.Id as ChildID,ChildExam.Id as ChildExamId,ChildPoll.Id as ChildPollID,
	  (CASE WHEN ISNULL(ChildExam.[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL(ChildExam.[TotalExamScore],0) * ISNULL(ChildExam.[ExamWeight], 0)) / ChildExam.TotalScore AS decimal(18,2)) ELSE ChildExam.[AnnouncedDegree] END) as ChildAnnouncedDegree
	from GENExamAnswerHeaders
	inner JOIN GENPollCategories ON dbo.GENExamAnswerHeaders.ExamId = GENPollCategories.Id
	left join GENExam_GENType on GENExam_GENType.MakeUpParentId = GENExamAnswerHeaders.ExamId
	left join GENPollCategories ChildPoll on ChildPoll.Id = GENExam_GENType.ExamId
	left join GENExamAnswerHeaders ChildExam on ChildExam.ExamId = GENExam_GENType.ExamId and ChildExam.StudentId = @ContactId and ChildExam.CourseId = @CourseId
	where GENExamAnswerHeaders.examId =@ExamId and GENExamAnswerHeaders.StudentId =@ContactId and GENExamAnswerHeaders.CourseId =@CourseId
	) as res
    left join GENExam_GENType on GENExam_GENType.MakeUpParentId = res.ChildPollID
	left join GENExamAnswerHeaders ChildExam on ChildExam.ExamId = GENExam_GENType.ExamId and ChildExam.StudentId = @ContactId and ChildExam.CourseId = @CourseId
	RETURN @IsSuccess
	end
GO
