/****** Object:  UserDefinedFunction [dbo].[fnContact_AddressString]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fnContact_AddressString]
(
   @ContactId bigint
)
RETURNS Nvarchar(Max) -- or whatever length you need
AS
BEGIN
DECLARE @BaseEntityId bigint 
  SELECT top 1 @BaseEntityId = Id FRom BaseEntities WHERE Name='GENContact'
  DECLARE @ContactAddress NVARCHAR(Max) 
  set  @ContactAddress  = N'Not Exist';
SELECT top(1)   @ContactAddress=  (dbo.GENAddresses.StreetBuilding+',' +   dbo.GENGovernorates.Name+','+ dbo.GENProvinces.Name+','+ dbo.GENCountries.Name )
FROM            dbo.GENAddresses LEFT OUTER JOIN
                         dbo.GENGovernorates ON dbo.GENAddresses.GovernorateId = dbo.GENGovernorates.Id LEFT OUTER JOIN
                         dbo.GENProvinces ON dbo.GENAddresses.ProvinceId = dbo.GENProvinces.Id LEFT OUTER JOIN
                         dbo.GENCountries ON dbo.GENAddresses.CountryId = dbo.GENCountries.Id 

					 
where EntityId = @ContactId and BaseEntityId = @BaseEntityId
if @ContactAddress is null
begin
SELECT @ContactAddress  = DefaultAddress FROM Contact_View WHERE Id = @ContactId
END
if @ContactAddress is null
begin
 set  @ContactAddress  =N'Not Exist';
end
    RETURN  @ContactAddress

END
GO
