CREATE FUNCTION [dbo].[fnCount_DestVcrs_ByDestResponsible]
(
   @ContactId Bigint,@UserId nvarchar(100) 
 
)
RETURNS int   -- or whatever length you need
AS
BEGIN
	DECLARE @DestId Bigint 	
  DECLARE @CountTalent nvarchar(20) 
  Select Distinct Top 1 @DestId= CompanyId From GENContacts where UserId=@UserId
SELECT  Distinct Top 1 @CountTalent =  Count( distinct GENClassrooms.Id)
FROM GENClassroom_GENContact left join 
GENContacts ON GENContacts.Id=GENClassroom_GENContact.StudentId left join 
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
where GENClassrooms.DestinationsId=@DestId and GENClassroom_GENContact.StudentId=@ContactId and 
GENClassrooms.isdeleted=0 and GENContacts.isdeleted=0

if @CountTalent is null
begin
 set  @CountTalent = 0;
end

RETURN  @CountTalent

END
GO
