CREATE FUNCTION [dbo].[fnCount_VcrsByContactId]
(
   @ContactId bigint
 
)
RETURNS int -- or whatever length you need
AS
BEGIN
  DECLARE @CountTalent int 
SELECT @CountTalent =COUNT(GENClassroom_GENContact.Id)
FROM dbo.GENClassroom_GENContact inner join 
GENClassrooms ON GENClassroom_GENContact.classroomId=GENClassrooms.Id inner join 
GENTypes ON GENClassrooms.courseId=GENTypes.Id
where GENClassroom_GENContact.StudentId =@ContactId and GENClassrooms.isdeleted=0 and 
GENClassroom_GENContact.BookingTypeId=1 and ([dbo].[AttendanceCall]([GENClassroom_GENContact].StudentId,GENClassrooms.Id) >=isnull(GENClassrooms.Int4,GENTypes.int3))


if @CountTalent is null
begin
 set  @CountTalent = 0;
end

RETURN  @CountTalent

END
