/****** Object:  UserDefinedFunction [dbo].[fnEventDate]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fnEventDate] 
(
	@UserName nvarchar(150)
)
RETURNS datetime
AS
BEGIN
	DECLARE @DateTime datetime
	DECLARE @DateTimeAfterAddTwoHours datetime
	-- Add the T-SQL statements to compute the return value here
	SELECT top(1) @DateTime = dbo.AuditLogs.EventDateUTC
	FROM dbo.AuditLogs 
	LEFT JOIN AspNetUsers ON AuditLogs.UserName = AspNetUsers.UserName OR AuditLogs.UserName = AspNetUsers.Id
	where AspNetUsers.UserName = @UserName OR AspNetUsers.Id = @UserName
	order by dbo.AuditLogs.EventDateUTC DESC
	select @DateTimeAfterAddTwoHours= dateadd(HOUR, 2,@DateTime)
	RETURN @DateTimeAfterAddTwoHours
END
GO
/****** Object:  UserDefinedFunction [dbo].[fnEventDateString]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[fnEventDateString] 
(
	@UserName nvarchar(150)
)
RETURNS nvarchar(120)
AS
BEGIN
	DECLARE @DateTime datetime
	DECLARE @DateTimeAfterAddTwoHours datetime
	-- Add the T-SQL statements to compute the return value here
	SELECT top(1) @DateTime = dbo.AuditLogs.EventDateUTC
	FROM dbo.AuditLogs 
	LEFT JOIN AspNetUsers ON AuditLogs.UserName = AspNetUsers.UserName OR AuditLogs.UserName = AspNetUsers.Id
	where AspNetUsers.UserName = @UserName OR AspNetUsers.Id = @UserName
	order by dbo.AuditLogs.EventDateUTC DESC
	select @DateTimeAfterAddTwoHours= dateadd(HOUR, 2,@DateTime)
	RETURN  Format(@DateTimeAfterAddTwoHours, 'ddd hh:mm tt')
END

GO
