CREATE FUNCTION [dbo].[fnLastActionType_ByContactId]
(
   @ContactId bigint
)
RETURNS nvarchar(150) -- or whatever length you need
AS
BEGIN
  DECLARE @ActionName nvarchar(150)
  DECLARE @ActivityId bigint

  select top(1) @ActivityId = Ticket_CommentId from ActivityContacts where ContactId = @ContactId or ContactPersonId =@ContactId 
  order by ActivityContacts.Id desc ;
  if(@ActivityId>0)
  begin
SELECT top(1)   @ActionName=     dbo.GENCommentTypes.Name
FROM            dbo.CRMSRVTicket_Comment LEFT OUTER JOIN
                         dbo.GENCommentTypes ON dbo.CRMSRVTicket_Comment.CommentTypeId = dbo.GENCommentTypes.Id
WHERE        (dbo.CRMSRVTicket_Comment.Id = @ActivityId)
end
else
begin
set @ActionName = '';
end
  RETURN  @ActionName
END
GO
