AS
BEGIN
  DECLARE @CountTalent nvarchar(100) 
SELECT  Top 1 @CountTalent =  FORMAT(GENTypes.DateCreated,'dd/MM/yyyy')
FROM Contacts_Courses left join 
GENContacts ON GENContacts.Id=Contacts_Courses.StudentId left join 
GENTypes ON Contacts_Courses.CourseId=GENTypes.Id
where Contacts_Courses.StudentId=@ContactId 
order by GENContacts.Id desc


if @CountTalent is null
begin
 set  @CountTalent = N'No Date';
end

RETURN  @CountTalent

END
