CREATE FUNCTION [dbo].[fnLastDealStatus_ByContactId]
(
   @ContactId bigint
)
RETURNS nvarchar(150) -- or whatever length you need
AS
BEGIN
  DECLARE @StatusName nvarchar(150)
  DECLARE @DealId bigint

  select top(1) @DealId = Id from CRMDeals where ContactId = @ContactId
  order by  CRMDeals.DateUpdated desc
  if(@DealId>0)
  begin
SELECT  top(1)  @StatusName=     dbo.GENStatus.Name
FROM            dbo.CRMDeals LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.CRMDeals.StatusId = dbo.GENStatus.Id
WHERE        (dbo.CRMDeals.Id = @DealId)
end
else
begin
set @StatusName = '';
end
  RETURN  @StatusName
END
GO
