/****** Object:  UserDefinedFunction [dbo].[fnLogFile_InsertContent]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create FUNCTION [dbo].[fnLogFile_InsertContent]
(
   @RawString nvarchar(Max),@ColumnString nvarchar(Max),@LineNumber int
)
RETURNS varchar(Max) -- or whatever length you need
AS
BEGIN
   Declare @TEMPColumnCount int
declare @TEMPColumn table (ID int, Item varchar(max))
insert into @TEMPColumn SELECT ID, Item FROM dbo.Split(@ColumnString,',')

declare @TEMPRow table (ID int, Item varchar(max))
insert into @TEMPRow SELECT ID, Item FROM dbo.Split(@RawString,',')

SELECT @TEMPColumnCount =   COUNT(*) FROM @TEMPColumn 
 DECLARE @i int = 0
 Declare @ContentValue nvarchar(Max) =CAST(@LineNumber AS nvarchar(Max)) +'-';
WHILE @i < @TEMPColumnCount
BEGIN
    SET @i = @i + 1

	Declare @ColumnValue nvarchar(250)
	Declare @RowValue nvarchar(250)

	select @RowValue = Item from @TEMPRow where Id =@i
	select @ColumnValue = Item from @TEMPColumn where Id =@i
set @ContentValue =@ContentValue+@ColumnValue+': '  + @RowValue+','

    /* do some work */
END

    RETURN  @ContentValue

END
GO
