/****** Object:  UserDefinedFunction [dbo].[GETClassRoomStatusName]    Script Date: 7/1/2026 10:44:55 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE function [dbo].[GETClassRoomStatusName]
(  
   @examtype int,  
   @lang varchar(30)  
)  
returns nvarchar(MAX)  
as  
begin 
DECLARE @retrunString AS NVARCHAR(100) = 
CASE WHEN @lang ='ar'
	    THEN 				
			CASE @examtype
			WHEN 0 THEN  N'تم البدء'  
			WHEN 1 THEN  N'تم إسقاطه'  
			WHEN 2 THEN  N'انتهى'
			WHEN 3 THEN N'مخطط'
			ELSE  N'أخرى'  
			END 
		ELSE
			CASE @examtype			
			WHEN 0 THEN  N'Started'  
			WHEN 1 THEN  N'Dropped'  
			WHEN 2 THEN  N'Done'
			WHEN 3 THEN N'Planned'
			ELSE  N'Other'  
			END
END
return @retrunString
end
GO
/****** Object:  UserDefinedFunction [dbo].[GETClassRoomStatusNum]    Script Date: 7/1/2026 10:44:55 AM ******/
