GO
CREATE function [dbo].[GETClassRoomStatusNum]
(  
   @examtype nvarchar(MAX),  
   @lang varchar(30)  
)  
returns int  
as  
begin 
DECLARE @retrunString AS int = 
CASE WHEN @lang ='ar'
	    THEN 				
			CASE @examtype
			WHEN N'تم البدء'  THEN 0   
			WHEN N'تم إسقاطه' THEN 1
			WHEN N'انتهى' THEN 2
			ELSE 3  
			END 
		ELSE
			CASE @examtype			
			WHEN N'Started' THEN 0 
			WHEN N'Dropped' THEN 1
			WHEN N'Done' THEN 2
			ELSE 3  
			END
END
return @retrunString
end 
