CREATE function [dbo].[getCurrentlVCRs] (@StudentId bigint)
Returns int
AS
BEGIN
DECLARE @Num AS int=0
Select distinct @Num=count(distinct ClassroomId) from GENClassroom_GENContact 
INNER JOIN GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id 
where StudentId=@StudentId and GENClassrooms.FromDateTime<=GETDATE() and GENClassrooms.ToDateTime>=GETDATE()  and GENClassrooms.IsActive=1  and GENClassrooms.ispublish=1 and GENClassrooms.IsDeleted=0
and GENClassrooms.ClassRoomStatus<>2 and GENClassrooms.ClassRoomStatus<>1
Return @Num
END
