/****** Object:  UserDefinedFunction [dbo].[getPageType]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:      <Author, , Name>
-- Create Date: <Create Date, , >
-- Description: <Description, , >
-- =============================================
CREATE FUNCTION [dbo].[getPageType]
(
   @PageTypeId int
)
RETURNS nvarchar(30)
AS
BEGIN
--CRUD = 0, Search = 1, QuickAdd = 3, PopUp = 4, CRUDQuick = 5, CRUDDashboard = 6, Report = 7
	RETURN CASE
	    WHEN @PageTypeId=0 THEN  N'CRUD'
		WHEN @PageTypeId=1 THEN  N'Search'
		WHEN @PageTypeId=2 THEN  NULL
		WHEN @PageTypeId=3 THEN  N'QuickAdd'
		WHEN @PageTypeId=4 THEN  N'PopUp'
		WHEN @PageTypeId=5 THEN  N'CRUDQuick'
		WHEN @PageTypeId=6 THEN  N'CRUDDashboard'
		WHEN @PageTypeId=7 THEN  N'Report'
    ELSE NULL
END;

END
GO
/****** Object:  UserDefinedFunction [dbo].[GetReportedTo_ByStatusId]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create  FUNCTION [dbo].[GetReportedTo_ByStatusId]
(
  
   @BaseEntityId bigint,
   @StatusId bigint,
   @EmployeeId bigint 
)
RETURNS bigint -- or whatever length you need
AS
BEGIN
  DECLARE @NewEmployeeId bigint = NULL;
  declare @displayOrder bigint = null;
  select @displayOrder= DisplayOrder from EmployeeEscalations where BaseEntityId =@BaseEntityId and EntityId =@StatusId and EmployeeId= @EmployeeId
SELECT top (1) @NewEmployeeId= EmployeeId FROM EmployeeEscalations WHERE DisplayOrder < @displayOrder and BaseEntityId =@BaseEntityId and EntityId =@StatusId  ORDER BY DisplayOrder asc

if  @NewEmployeeId is not null
begin
set @NewEmployeeId= @NewEmployeeId
end
else
begin
set @NewEmployeeId= @EmployeeId
end
return @NewEmployeeId

END
GO
/****** Object:  UserDefinedFunction [dbo].[GetReportedToTableByStatusId]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[GetReportedToTableByStatusId]
(
  
   @BaseEntityId bigint,
   @StatusId bigint,
   @EmployeeId bigint 
)
RETURNS @statusTable TABLE (
EmployeeId bigint,
EscalationTime float NULL)

AS
BEGIN
 
  DECLARE @CurrentEmployeeId bigint = NULL, @NewEmployeeId bigint = NULL, @displayOrder bigint = null, @EscalationTime float = null;
  select @displayOrder= DisplayOrder from EmployeeEscalations where BaseEntityId =@BaseEntityId and EntityId =@StatusId and EmployeeId= @EmployeeId
  if(@displayOrder is null)
  begin
   select top(1) @displayOrder= DisplayOrder from EmployeeEscalations where BaseEntityId =@BaseEntityId and EntityId =@StatusId order by DisplayOrder asc
   SELECT top (1) @NewEmployeeId= EmployeeId, @EscalationTime = EscalationTime FROM EmployeeEscalations WHERE DisplayOrder = @displayOrder and BaseEntityId =@BaseEntityId and EntityId =@StatusId  ORDER BY DisplayOrder asc
  end
  else
  begin
  SELECT top (1) @NewEmployeeId= EmployeeId, @EscalationTime = EscalationTime FROM EmployeeEscalations WHERE DisplayOrder > @displayOrder and BaseEntityId =@BaseEntityId and EntityId =@StatusId  ORDER BY DisplayOrder asc
  end
if(@NewEmployeeId IS NULL)
BEGIN
SET @NewEmployeeId = @EmployeeId
--SET @EscalationTime = NULL
END
 BEGIN
        INSERT @statusTable
        SELECT @NewEmployeeId, @EscalationTime;
    END;
return;

END
GO
