CREATE Function [dbo].[isInstructorConnected] (@EmployeeId bigint,@VCRId bigint,@CourseId bigint,@TalentId bigint)
RETURNS bit AS
BEGIN
DECLARE @Number AS int
SET @Number = 0
Select @Number=Count(*) from [TLMSClassroom_Session] 
where  @VCRId IS NOT NULL AND  @EmployeeId=InstructorId AND  @VCRId=ClassroomId
IF @Number>0   
BEGIN
    RETURN 1
END

Select @Number=Count(*) from [TLMSClassroom_Session] 
inner join GENClassrooms on GENClassrooms.Id=[TLMSClassroom_Session].ClassroomId
inner join gentypes on gentypes.Id=GENClassrooms.CourseId
where  @CourseId IS NOT NULL AND  @EmployeeId=[TLMSClassroom_Session].InstructorId AND  @CourseId=gentypes.Id
IF @Number>0   
BEGIN
    RETURN 1
END

Select @Number=Count(*) from [TLMSClassroom_Session] 
inner join GENTalents_Generic on GENTalents_Generic.VcrId=[TLMSClassroom_Session].ClassroomId
where  @TalentId IS NOT NULL AND  @EmployeeId=[TLMSClassroom_Session].InstructorId AND  @TalentId=GENTalents_Generic.TalentId
IF @Number>0   
BEGIN
    RETURN 1
END

    RETURN 0
END
GO
