CREATE Function [dbo].[isStudentConnected] (@ContactId bigint,@VCRId bigint,@CourseId bigint,@TalentId bigint)
RETURNS bit AS
BEGIN
DECLARE @Number AS int
SET @Number = 0

Select @Number=Count(*) from GENClassroom_GENContact 
where @ContactId IS NOT NULL AND @VCRId IS NOT NULL AND  @ContactId=StudentId AND  @VCRId=ClassroomId
IF @Number>0   
BEGIN
    RETURN 1
END 

Select @Number=Count(*) from [GENContact_Talent] 
where @ContactId IS NOT NULL AND @TalentId IS NOT NULL AND  @ContactId=ContactId AND  @TalentId=TalentId
IF @Number>0   
BEGIN
    RETURN 1
END

Select @Number=Count(*) from GENClassroom_GENContact 
inner join GENClassrooms on GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
inner join GENTypes on GENClassrooms.CourseId=GENTypes.Id
where @ContactId IS NOT NULL AND @CourseId IS NOT NULL AND  @ContactId=StudentId AND  @CourseId=GENTypes.Id
IF @Number>0   
BEGIN
    RETURN 1
END 


    RETURN 0
END
GO
/****** Object:  UserDefinedFunction [dbo].[Split]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[Split] (
      @InputString                  nvarchar(MAX),
      @Delimiter                    VARCHAR(50)
)

RETURNS @Items TABLE (
Id int IDENTITY(1,1) ,
      Item                          nvarchar(MAX)
)

AS
BEGIN
      IF @Delimiter = ' '
      BEGIN
            SET @Delimiter = ','
            SET @InputString = REPLACE(@InputString, ' ', @Delimiter)
      END

      IF (@Delimiter IS NULL OR @Delimiter = '')
            SET @Delimiter = ','

--INSERT INTO @Items VALUES (@Delimiter) -- Diagnostic
--INSERT INTO @Items VALUES (@InputString) -- Diagnostic

      DECLARE @Item           nvarchar(MAX)
      DECLARE @ItemList       nvarchar(MAX)
      DECLARE @DelimIndex     INT

      SET @ItemList = @InputString
      SET @DelimIndex = CHARINDEX(@Delimiter, @ItemList, 0)
      WHILE (@DelimIndex != 0)
      BEGIN
            SET @Item = SUBSTRING(@ItemList, 0, @DelimIndex)
            INSERT INTO @Items VALUES (@Item)

            -- Set @ItemList = @ItemList minus one less item
            SET @ItemList = SUBSTRING(@ItemList, @DelimIndex+1, LEN(@ItemList)-@DelimIndex)
            SET @DelimIndex = CHARINDEX(@Delimiter, @ItemList, 0)
      END -- End WHILE

      IF @Item IS NOT NULL -- At least one delimiter was encountered in @InputString
      BEGIN
            SET @Item = @ItemList
            INSERT INTO @Items VALUES (@Item)
      END

      -- No delimiters were encountered in @InputString, so just return @InputString
      ELSE INSERT INTO @Items VALUES (@InputString)

      RETURN

END -- End Function
GO
