CREATE FUNCTION [dbo].[TalentCalcEndDate] (@TalentId bigint,@ContactId bigint)
RETURNS DateTime
AS
BEGIN
	-- Declare the return variable here
	DECLARE @EndDate DateTime
	-- Add the T-SQL statements to compute the return value here
	SELECT @EndDate = ( DATEADD(DAY ,ISNULL(GENTalents.DurationDays,100),GENContact_Talent.DateCreated))
	From GENContact_Talent inner Join
	GENTalents ON GENContact_Talent.TalentId=GENTalents.Id
	where GENContact_Talent.ContactId = @ContactId AND GENContact_Talent.TalentId = @TalentId
	-- Return the result of the function
	RETURN @EndDate
END
GO
