-- Description:	Return Deal Status From Process according to Id
-- =============================================
CREATE FUNCTION [dbo].[tfn_CategoryParentAndGrandById]
(	
	-- Add the parameters for the function here
	@CategoryId bigint
)
RETURNS @CatTable TABLE (
ParentId bigint NULL,
GrandId bigint NULL
)
AS
BEGIN
DECLARE @ParentId bigint = NULL,
@GrandId bigint = NULL

SELECT TOP 1 @ParentId = GENItemCategories.ParentId, @GrandId = GENItemCategories.GrandId FROM GENItemCategories
WHERE Id = @CategoryId
ORDER BY Id DESC

 BEGIN
        INSERT @CatTable
        SELECT @ParentId, @GrandId;
    END;
	RETURN;
END
GO
