-- Author:		YAHIA ZAKARIA
-- Create date: 26 JAN 2020
-- Description:	Return Deal Status From Process according to Id
-- =============================================
CREATE FUNCTION [dbo].[tfn_fnEventDate]
(	
	-- Add the parameters for the function here
	@UserName nvarchar(150)
)
RETURNS @EventDate TABLE (
EventDateString NVARCHAR(500) NULL,
EventDate DATETIME NULL
)
AS
BEGIN
DECLARE @DateTime datetime,
@DateTimeString NVARCHAR(500)

-- Add the T-SQL statements to compute the return value here
	SELECT top(1) @DateTime = dateadd(HOUR, 2,dbo.AuditLogs.EventDateUTC), @DateTimeString = Format(dateadd(HOUR, 2,dbo.AuditLogs.EventDateUTC), 'ddd hh:mm tt')
	FROM dbo.AuditLogs 
	INNER JOIN AspNetUsers ON AuditLogs.UserName = AspNetUsers.UserName OR AuditLogs.UserName = AspNetUsers.Id
	where AspNetUsers.UserName = @UserName OR AspNetUsers.Id = @UserName
	order by dbo.AuditLogs.EventDateUTC DESC

 BEGIN
        INSERT @EventDate
        SELECT @DateTimeString, @DateTime;
    END;
	RETURN;
END
GO
