-- =============================================
-- Author:		YAHIA ZAKARIA
-- Create date: 07 May 2019
-- Description:	Return Deal Status From Process according to Id
-- =============================================
CREATE FUNCTION [dbo].[tfn_fnLastDealStatus_ByDealId]
(	
	-- Add the parameters for the function here
	@DealId bigint
)
RETURNS @statusTable TABLE (
StatusId bigint NULL,
StatusName NVARCHAR(500) NULL,
StatusColor NVARCHAR(500) NULL,
StatusStyle NVARCHAR(500) NULL
)
AS
BEGIN
DECLARE @StatusId bigint,
@StatusName NVARCHAR(500),
@StatusColor NVARCHAR(500),
@StatusStyle NVARCHAR(500),
@DealEntity BIGINT

SELECT @DealEntity = Id FROM BaseEntities WHERE Name = 'CRMDeal';

SELECT TOP 1 @StatusId = GENProcesses.ProcessId, @StatusName = GENStatus.Name, @StatusColor = GENStatus.ColorCode, @StatusStyle = GENStyles.StyleValue FROM GENProcesses
LEFT JOIN GENStatus ON GENProcesses.ProcessId = GENStatus.Id
LEFT JOIN GENStyles ON GENStatus.IconId = GENStyles.Id
WHERE GENProcesses.BaseEntityId = @DealEntity AND EntityId = @DealId
ORDER BY GENProcesses.Id DESC

 BEGIN
        INSERT @statusTable
        SELECT @StatusId, @StatusName, @StatusColor, @StatusStyle;
    END;
	RETURN;
END
GO
