SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 13 May 2019
-- Description:	Return Process Data
-- =============================================
CREATE FUNCTION [dbo].[tfn_ProcessByEntity]
(	
	-- Add the parameters for the function here
	@EntityId bigint,
	@BaseEntityId bigint
)
RETURNS @statusTable TABLE (
StatusId bigint NULL,
StatusName NVARCHAR(500) NULL,
StatusColor NVARCHAR(500) NULL,
StatusStyle NVARCHAR(500) NULL,
SuccessRate INT,
CompletionRate INT,
DisplayOrdering INT NULL,
IsFinal BIT,
IsFirst Bit,
IsMap Bit,IsFailure BIT,
ListValueName  NVARCHAR(500),
Comment  NVARCHAR(MAX))
AS
BEGIN
DECLARE @StatusId bigint,
@StatusName NVARCHAR(500),
@StatusColor NVARCHAR(500),
@StatusStyle NVARCHAR(500),
@SuccessRate INT,
@CompletionRate INT,
@DisplayOrdering INT = NULL,
@IsFinal BIT,
@IsFirst BIT,
@IsMap BIT,
@IsFailure BIT,
@ListValueName  NVARCHAR(500),
@Comment  NVARCHAR(MAX)

SELECT TOP 1 @StatusId = GENProcesses.ProcessId, @StatusName = GENStatus.Name, @StatusColor = GENStatus.ColorCode, 
@StatusStyle = GENStyles.StyleValue, @SuccessRate = GENStatus.SuccessRate, @IsFinal = GENStatus.IsFinal, @IsFirst = GENStatus.IsFirst,
@IsMap = GENStatus.IsMap, @DisplayOrdering = GENStatus.DisplayOrdering, @CompletionRate = GENStatus.CompletionRate,@IsFailure=GENStatus.IsFailure,@ListValueName = GENListValues.Name,
@Comment = GENProcesses.Comment
FROM GENProcesses
LEFT JOIN GENStatus ON GENProcesses.ProcessId = GENStatus.Id
LEFT JOIN GENStyles ON GENStatus.IconId = GENStyles.Id
LEFT JOIN GENListValues ON GENListValues.Id = GENProcesses.ListValueId
WHERE GENProcesses.BaseEntityId = @BaseEntityId AND EntityId = @EntityId
ORDER BY GENProcesses.Id DESC
 BEGIN
        INSERT @statusTable
        SELECT @StatusId, @StatusName, @StatusColor, @StatusStyle, @SuccessRate,@DisplayOrdering, @IsFinal, @IsFirst, @IsMap,@CompletionRate,@IsFailure,@ListValueName , @Comment;
    END;
RETURN 
END
GO
