CREATE FUNCTION [dbo].[tfn_StatusCRMCount]
(	
	-- Add the parameters for the function here
	@StatusId bigint,
   @dateTimefrom datetime,
   @dateTimeto datetime
)
RETURNS @statusTable TABLE (
CountStatus int)
AS
BEGIN
DECLARE @CountStatus int

SELECT  @CountStatus= COUNT(dbo.CRMTicketView.Id)
FROM            dbo.CRMTicketView
WHERE        ProcessId = @StatusId AND DateCreated between @dateTimefrom and @dateTimeto
 BEGIN
        INSERT @statusTable
        SELECT @CountStatus;
    END;
RETURN 
END
GO
