CREATE VIEW [dbo].[Item_TranslateView]
AS
SELECT        dbo.GENTranslate_Items.ItemId, dbo.GENTranslate_Items.LangId, dbo.GENTranslate_Items.FieldId, dbo.GENTranslate_Items.FieldName, dbo.GENTranslate_Items.Value, dbo.GENItems.Id, dbo.GENItems.Name, 
                         dbo.GENItems.Description, dbo.GENItems.String1, dbo.GENItems.String2, dbo.GENItems.String3, dbo.GENItems.String4, dbo.GENItems.String5, dbo.fnListValueCode_ById(dbo.GENTranslate_Items.LangId) 
                         AS LanguageCode
FROM            dbo.GENItems left JOIN
                         dbo.GENTranslate_Items ON dbo.GENItems.Id = dbo.GENTranslate_Items.ItemId
GO
