/****** Object:  View [dbo].[GENCertification_Requests_View]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create VIEW [dbo].[GENCertification_Requests_View]
AS
SELECT       GENCertification_Requests.*,FORMAT(GENCertification_Requests.ExtractionRequestDate,'dd/MM/yyyy') AS ExtractionRequestDatestring ,GENContacts.Name AS StudentName,GENClassrooms.Name AS  VcrName ,
(case when GENCertification_Requests.PaymentType =0 then 'Coupon' else 'Visa' end) as PaymentTypeString,
(CASE WHEN dbo.GENCertification_Requests.CertificateRequestStatus = 0 THEN N'Requested' WHEN dbo.GENCertification_Requests.CertificateRequestStatus = 1 THEN N'Done' WHEN dbo.GENClassrooms.PaymentCondation
                          = 2 THEN N'Collected' ELSE N'' END) AS CertificateRequestStatusName
						 
FROM           
                         dbo.GENCertification_Requests inner JOIN
						 GENContacts ON GENCertification_Requests.StudentId=GENContacts.Id left join
                         dbo.GENOrders ON dbo.GENCertification_Requests.Id = dbo.GENOrders.CertificationRequestId left join
						GENClassrooms ON GENCertification_Requests.ClassroomId=GENClassrooms.Id
                         
GO
