CREATE VIEW [dbo].[AllActivitiesWithDetails]
AS
SELECT        dbo.CRMSRVTicket_Comment.MainContactId, GENContacts_2.Name AS ActivityMainContactName, GENContacts_2.Code AS ContactMainCode, GENContacts_2.DefaultEmail AS ContactDefaultEmailMain, 
                         GENContacts_2.Image AS ContactMainImage, GENContacts_2.DefaultPhone AS ContactDefaultPhoneMain, GENContacts_2.DefaultAddress AS ContactDefaultAddressMain, GENContacts_1.Name AS ActivityContactName, 
                         GENContacts_1.Code AS ContactCode, GENContacts_1.DefaultEmail AS ContactDefaultEmail, GENContacts_1.Image AS ContactImage, GENContacts_1.DefaultPhone AS ContactDefaultPhone, 
                         GENContacts_1.DefaultAddress AS ContactDefaultAddress, dbo.GENContacts.Code AS ContactPersonCode, dbo.GENContacts.Name AS ActivityContactPersonName, dbo.GENContacts.DefaultEmail AS ContactPersonDefaultEmail, 
                         FORMAT(dbo.CRMSRVTicket_Comment.ActionDate, 'hh:mm tt') AS ActionTime, FORMAT(dbo.CRMSRVTicket_Comment.ActionDate, 'dd/MM/yyyy') AS ActionDateFormat, 
                         dbo.fnUser_Name(dbo.CRMSRVTicket_Comment.CreatedById) AS CreatedByName, CONVERT(varchar, dbo.CRMSRVTicket_Comment.DateCreated, 103) AS DateCreatedString, CONVERT(varchar, 
                         dbo.CRMSRVTicket_Comment.DateCreated, 108) AS TimeCreatedString, CONVERT(varchar, dbo.CRMSRVTicket_Comment.DateUpdated, 103) AS DateUpdatedString, CONVERT(varchar, 
                         dbo.CRMSRVTicket_Comment.DateUpdated, 108) AS TimeUpdatedString,
                             (SELECT        LEFT(dbo.CRMSRVTicket_Comment.Comment, 50) AS Expr1) AS ShortDescription,
                             (SELECT        LEFT(dbo.CRMSRVTicket_Comment.Comment, 20) AS Expr1) AS VeryShortDescription, dbo.fnListValue_ById(dbo.CRMSRVTicket_Comment.ValueId4,NULL) AS ValueId4tName, 
                         dbo.fnListValue_ById(dbo.CRMSRVTicket_Comment.ValueId2,NULL) AS ValueId2tName, FORMAT(dbo.CRMSRVTicket_Comment.ActionDate, 'dd/MM/yyyy hh:mm tt') AS ActionDateString, dbo.fn_Icon_Style(dbo.GENStatus.IconId) 
                         AS StatusIcon, dbo.GENStatus.ColorCode AS StatusColor, dbo.fn_Icon_Style(GENCommentTypes_1.IconId) AS CommentIcon, GENCommentTypes_1.ColorCode AS CommentColor, 
                         dbo.fnPaymentMethod_ById(dbo.CRMSRVTicket_Comment.PaymentMethodId) AS PaymentMethodName, dbo.CRMSRVTicket_Comment.Id, dbo.CRMSRVTicket_Comment.TicketId, dbo.CRMSRVTicket_Comment.Comment, 
                         dbo.CRMSRVTicket_Comment.CommentTypeId, dbo.CRMSRVTicket_Comment.DateCreated, dbo.CRMSRVTicket_Comment.DateUpdated, dbo.CRMSRVTicket_Comment.DateDeleted, dbo.CRMSRVTicket_Comment.CreatedById, 
                         dbo.CRMSRVTicket_Comment.DeletedById, dbo.CRMSRVTicket_Comment.LastUpdatedById, dbo.CRMSRVTicket_Comment.NextActionDate, dbo.CRMSRVTicket_Comment.NextActionId, dbo.CRMSRVTicket_Comment.IsNextStep, 
                         dbo.CRMSRVTicket_Comment.ActionDate, dbo.CRMSRVTicket_Comment.NextStepDescription, dbo.CRMSRVTicket_Comment.StatusId, dbo.CRMSRVTicket_Comment.EntityId, dbo.CRMSRVTicket_Comment.BaseEntityId, 
                         dbo.CRMSRVTicket_Comment.NextActivityId, dbo.CRMSRVTicket_Comment.ParentActivityId, dbo.CRMSRVTicket_Comment.IsCancelled, dbo.CRMSRVTicket_Comment.Day, dbo.CRMSRVTicket_Comment.BaseEntityTo, 
                         dbo.CRMSRVTicket_Comment.EntityIdTo, dbo.CRMSRVTicket_Comment.IsRepeated, dbo.CRMSRVTicket_Comment.LastNotificationDate, dbo.CRMSRVTicket_Comment.ExpiredDate, dbo.CRMSRVTicket_Comment.DateFrom, 
                         dbo.CRMSRVTicket_Comment.TimeFrom, dbo.CRMSRVTicket_Comment.Dateto, dbo.CRMSRVTicket_Comment.Timeto, dbo.CRMSRVTicket_Comment.RepeatPeriodId, dbo.CRMSRVTicket_Comment.SchedulerType, 
                         dbo.CRMSRVTicket_Comment.NotificationType, dbo.CRMSRVTicket_Comment.EventTypeId, dbo.CRMSRVTicket_Comment.ActivtyTypeId, dbo.CRMSRVTicket_Comment.Number, dbo.CRMSRVTicket_Comment.ActionTypeId, 
                         dbo.CRMSRVTicket_Comment.ListValueId, dbo.CRMSRVTicket_Comment.Name, dbo.CRMSRVTicket_Comment.IsDeleted, dbo.CRMSRVTicket_Comment.Reason, dbo.CRMSRVTicket_Comment.IsCompleted, 
                         dbo.CRMSRVTicket_Comment.PageofPagesId, dbo.fn_PageName_ByPopId(dbo.CRMSRVTicket_Comment.PageofPagesId) AS PageName, dbo.CRMSRVTicket_Comment.RepeatNumber, 
                         dbo.CRMSRVTicket_Comment.RepeatEndDate, dbo.CRMSRVTicket_Comment.Color, dbo.CRMSRVTicket_Comment.IsCancelledActivities, dbo.fn_Activity_OverDue(dbo.CRMSRVTicket_Comment.Id, 
                         dbo.CRMSRVTicket_Comment.StatusId) AS IsOverDueActivities, dbo.fn_Activity_OverDue(dbo.CRMSRVTicket_Comment.Id, dbo.CRMSRVTicket_Comment.StatusId) AS IsOverDue, 
                         dbo.CRMSRVTicket_Comment.IsNextActionsActivities, dbo.CRMSRVTicket_Comment.IsPlannedActivities, dbo.CRMSRVTicket_Comment.IsDoneActivities, dbo.GENStyles.StyleValue AS ActivityIcon, 
                         GENCommentTypes_1.Name AS CommentTypeName, dbo.GENCommentTypes.Name AS NextActionName, GENEmployees_1.Name AS ActivityEmployeeName, dbo.GENStatus.Name AS StatusName, 
                         GENEmployees_1.Code AS EmployeeCode, GENEmployees_1.Image AS EmployeeImage, GENContacts_1.Id AS ContactId, dbo.GENContacts.DefaultPhone AS ContactPersonDefaultPhone, 
                         dbo.GENContacts.Image AS ContactPersonImage, dbo.GENContacts.DefaultAddress AS ContactPersonAddress, dbo.fnContact_ContactNames(dbo.CRMSRVTicket_Comment.Id) AS ContactName, 
                         dbo.fnEmployee_Name(dbo.CRMSRVTicket_Comment.Id) AS EmployeeName, dbo.fnContactPerson_Name(dbo.CRMSRVTicket_Comment.Id) AS ContactPersonName, 
                         dbo.fnUser_Name(dbo.CRMSRVTicket_Comment.CreatedById) AS Expr1, dbo.ActivityContacts.ContactId AS ActivityContactId, dbo.ActivityContacts.ContactPersonId, dbo.ActivityEmployees.EmployeeId, 
                         dbo.fn_UserImage_Employee(dbo.CRMSRVTicket_Comment.CreatedById) AS CreatedByImage, dbo.GENPushNotifications.NotificationDate, dbo.GENPushNotifications.Number AS NotificationNumber, 
                         dbo.GENPushNotifications.Id AS NotId, dbo.GENNotificationsRelatedDatas.Name AS ActivityNotificationName, dbo.GENPushNotifications.Message AS NotificationString, 
                         dbo.GENPushNotifications.EventTypeId AS NotificationEventTypeId, dbo.fn_Activity_PreviousAction(dbo.CRMSRVTicket_Comment.ParentActivityId) AS PreviousActionName, 
                         dbo.fn_NextandPrevActionIcon(dbo.CRMSRVTicket_Comment.NextActivityId) AS NextActionIcon, dbo.fn_NextandPrevActionIcon(dbo.CRMSRVTicket_Comment.ParentActivityId) AS PreviousActionIcon, 
                         dbo.fn_NextandPrevActionColor(dbo.CRMSRVTicket_Comment.NextActivityId) AS NextActionColor, dbo.fn_NextandPrevActionColor(dbo.CRMSRVTicket_Comment.ParentActivityId) AS PreviousActionColor, 
                         dbo.CRMSRVTicket_Comment.CRMTicketId, dbo.CRMSRVTicket_Comment.FieldName, dbo.fnUser_Name(dbo.CRMSRVTicket_Comment.LastUpdatedById) AS LastUpdatedByName
FROM            dbo.GENCommentTypes RIGHT OUTER JOIN
                         dbo.ActivityEmployees RIGHT OUTER JOIN
                         dbo.ActivityContacts RIGHT OUTER JOIN
                         dbo.GENCommentTypes AS GENCommentTypes_1 RIGHT OUTER JOIN
                         dbo.CRMSRVTicket_Comment LEFT OUTER JOIN
                         dbo.GENNotificationsRelatedDatas RIGHT OUTER JOIN
                         dbo.GENPushNotifications ON dbo.GENNotificationsRelatedDatas.PushNotificationId = dbo.GENPushNotifications.Id ON dbo.CRMSRVTicket_Comment.Id = dbo.GENPushNotifications.SchedulerId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.CRMSRVTicket_Comment.CreatedById = dbo.GENEmployees.UserId LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.CRMSRVTicket_Comment.StatusId = dbo.GENStatus.Id ON GENCommentTypes_1.Id = dbo.CRMSRVTicket_Comment.CommentTypeId LEFT OUTER JOIN
                         dbo.GENStyles ON GENCommentTypes_1.IconId = dbo.GENStyles.Id ON dbo.ActivityContacts.Ticket_CommentId = dbo.CRMSRVTicket_Comment.Id ON 
                         dbo.ActivityEmployees.TicketCommentId = dbo.CRMSRVTicket_Comment.Id ON dbo.GENCommentTypes.Id = dbo.CRMSRVTicket_Comment.NextActionId LEFT OUTER JOIN
                         dbo.GENEmployees AS GENEmployees_1 ON dbo.ActivityEmployees.EmployeeId = GENEmployees_1.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.ActivityContacts.ContactPersonId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENContacts AS GENContacts_1 ON dbo.ActivityContacts.ContactId = GENContacts_1.Id LEFT OUTER JOIN
                         dbo.GENContacts AS GENContacts_2 ON dbo.CRMSRVTicket_Comment.MainContactId = GENContacts_2.Id
WHERE        (dbo.CRMSRVTicket_Comment.IsDeleted = 0)
GO
