CREATE VIEW [dbo].[PageOfPageCustomFieldTabs_TranslateView]
AS
SELECT        dbo.Translate_PageOfPageCustomFieldTabs.PageOfPageCustomFieldTabsId, dbo.Translate_PageOfPageCustomFieldTabs.LangId, dbo.Translate_PageOfPageCustomFieldTabs.FieldId as TrnasFieldId, dbo.Translate_PageOfPageCustomFieldTabs.[Value] AS TransVal,
PageOfPageCustomFieldTabs.*,dbo.fnListValueCode_ById(dbo.Translate_PageOfPageCustomFieldTabs.LangId) AS LanguageCode,
