CREATE VIEW [dbo].[RawData_View]
AS
SELECT        dbo.GENRawDatas.Id, dbo.GENRawDatas.Position, dbo.GENRawDatas.ContactTypeName, dbo.GENRawDatas.ResponsiblePersonId, dbo.GENRawDatas.IsPublish, dbo.GENRawDatas.IsActive, 
                         dbo.GENRawDatas.RawDataTypeId, dbo.GENRawDatas.RawDataCategoryId, dbo.GENRawDatas.TypeId, dbo.GENRawDatas.SalutationId, dbo.GENRawDatas.SourceId, dbo.GENRawDatas.DepartmentId, 
                         dbo.GENRawDatas.UserId, dbo.GENRawDatas.Code, dbo.GENRawDatas.BirthDate, dbo.GENRawDatas.ExpirationDate, dbo.GENRawDatas.IDNumber, dbo.GENRawDatas.ReleaseDate, dbo.GENRawDatas.CommunicationMedia, 
                         dbo.GENRawDatas.CommunicateTime, dbo.GENRawDatas.BudgetRange, dbo.GENRawDatas.GenderId, dbo.GENRawDatas.CompanyId, dbo.GENRawDatas.LanguageId, dbo.GENRawDatas.BaseEntityId, 
                         dbo.GENRawDatas.EntityId, dbo.GENRawDatas.StatusId, dbo.GENRawDatas.ReasonId, dbo.GENRawDatas.IsJunk, dbo.GENRawDatas.IsDeleted, dbo.GENRawDatas.Title, dbo.GENRawDatas.CompanyString, 
                         dbo.GENRawDatas.CityString, dbo.GENRawDatas.SourceString, dbo.GENRawDatas.ExtendString1, dbo.GENRawDatas.Phone1, dbo.GENRawDatas.Phone2, dbo.GENRawDatas.Mobile1, dbo.GENRawDatas.Mobile2, 
                         dbo.GENRawDatas.HotLine, dbo.GENRawDatas.Fax, dbo.GENRawDatas.Email1, dbo.GENRawDatas.Email2, dbo.GENRawDatas.AddressString, dbo.GENRawDatas.CompanyPhone1, dbo.GENRawDatas.CompanyPhone2, 
                         dbo.GENRawDatas.CompanyMobile1, dbo.GENRawDatas.CompanyMobile2, dbo.GENRawDatas.CompanyHotLine, dbo.GENRawDatas.CompanyFax, dbo.GENRawDatas.CompanyEmail1, dbo.GENRawDatas.CompanyEmail2, 
                         dbo.GENRawDatas.CompanyAddressString, dbo.GENRawDatas.TypeString, dbo.GENRawDatas.ReasonString, dbo.GENRawDatas.AssessmentId, dbo.GENRawDatas.PaymentMethodId, dbo.GENRawDatas.PriortyId, 
                         dbo.GENRawDatas.RentPeriodId, dbo.GENRawDatas.Name, dbo.GENRawDatas.Description, dbo.GENRawDatas.ColorCode, dbo.GENRawDatas.IsCheckedOut,dbo.GENRawDatas.ExpectedCheckoutDate, dbo.GENRawDatas.DateCreated, dbo.GENRawDatas.DateUpdated, 
                         dbo.GENRawDatas.CheckinDate, dbo.GENRawDatas.CheckoutDate, dbo.GENRawDatas.Timeout, dbo.GENRawDatas.DisplayOrdering, dbo.GENRawDatas.CreatedById, dbo.GENRawDatas.LastUpdatedById, 
                         dbo.GENRawDatas.CheckoutBy, dbo.GENRawDatas.String1, dbo.GENRawDatas.String2, dbo.GENRawDatas.String3, dbo.GENRawDatas.String4, dbo.GENRawDatas.String5, dbo.GENRawDatas.Int1, dbo.GENRawDatas.Int2, 
                         dbo.GENRawDatas.Int3, dbo.GENRawDatas.Int4, dbo.GENRawDatas.Int5, dbo.GENRawDatas.Long1, dbo.GENRawDatas.Long2, dbo.GENRawDatas.Long3, dbo.GENRawDatas.Long4, dbo.GENRawDatas.Long5, 
                         dbo.GENRawDatas.Float2, dbo.GENRawDatas.Float1, dbo.GENRawDatas.Float3, dbo.GENRawDatas.Float4, dbo.GENRawDatas.Float5, dbo.GENRawDatas.Decimal1, dbo.GENRawDatas.Decimal2, dbo.GENRawDatas.Decimal3, 
                         dbo.GENRawDatas.Decimal4, dbo.GENRawDatas.Decimal5, dbo.GENRawDatas.Bool1, dbo.GENRawDatas.Bool2, dbo.GENRawDatas.Bool3, dbo.GENRawDatas.Bool4, dbo.GENRawDatas.Bool5, dbo.GENRawDatas.Date1, 
                         dbo.GENRawDatas.Date2, dbo.GENRawDatas.Date3, dbo.GENRawDatas.Date4, dbo.GENRawDatas.Date5, dbo.GENRawDatas.ValueId1, dbo.GENRawDatas.ValueId2, dbo.GENRawDatas.ValueId3, dbo.GENRawDatas.ValueId4, 
                         dbo.GENRawDatas.ValueId5, dbo.GENRawDatas.IconId, dbo.GENEmployees.Name AS ResponsiblePersonName, dbo.GENRawDataTypes.Name AS RawDataTypeName, 
                         dbo.RawDataCategories.Name AS RawDataCategoryName, dbo.GENTypes.Name AS TypeName, dbo.CRMSources.Name AS SourceName, dbo.GENDepartments.Name AS DepartmentName, 
                         dbo.GENCompanies.Name AS CompanyName, dbo.GENSalutations.Name AS SalutationName, dbo.GENStatus.Name AS StatusName, dbo.GENStatus.ColorCode AS StatusColor, dbo.CRMSRVReasons.Name AS ReasonName, 
						 dbo.GENStyles.StyleValue AS ProcessIcon,Process.ListValueName AS ProcessListValueName,Process.Comment AS ProcessComment,
                         dbo.fnListValue_ById(dbo.GENRawDatas.AssessmentId,null) AS AssessmentName, dbo.fnListValue_ById(dbo.GENRawDatas.PriortyId,null) AS PriortyName, dbo.AspNetUsers.Name AS LastUpdatedByName, CONVERT(varchar, 
                         dbo.GENRawDatas.DateCreated, 103) AS DateCreatedString, FORMAT(dbo.GENRawDatas.DateCreated,'hh:mm tt') AS TimeCreatedString, CONVERT(varchar, dbo.GENRawDatas.DateUpdated, 103) AS DateUpdatedString, 
                         FORMAT(dbo.GENRawDatas.DateUpdated,'hh:mm tt') AS TimeUpdatedString, dbo.fn_Concatenate2Strings(dbo.GENRawDatas.Email1, dbo.GENRawDatas.Email2) AS AllIndividualEmails, 
                         dbo.fn_Concatenate2Strings(dbo.GENRawDatas.Mobile1, dbo.GENRawDatas.Mobile2) AS AllIndividualTelephones,FORMAT(dbo.GENRawDatas.Date1, 'dd/MM/yyyy') AS Date1String,
						 FORMAT(dbo.GENRawDatas.Date2, 'dd/MM/yyyy') AS Date2String,FORMAT(dbo.GENRawDatas.Date3, 'dd/MM/yyyy') AS Date3String,FORMAT(dbo.GENRawDatas.Date4, 'dd/MM/yyyy') AS Date4String,
						 FORMAT(dbo.GENRawDatas.Date5, 'dd/MM/yyyy') AS Date5String,FORMAT(dbo.GENRawDatas.ExpirationDate, 'dd/MM/yyyy') AS ExpirationDateString,
						 FORMAT(dbo.GENRawDatas.BirthDate, 'dd/MM/yyyy') AS BirthDateString
FROM             dbo.GENRawDatas LEFT JOIN
					 dbo.GENEmployees ON dbo.GENEmployees.Id = dbo.GENRawDatas.ResponsiblePersonId LEFT JOIN
                         dbo.GENDepartments  ON dbo.GENDepartments.Id = dbo.GENRawDatas.DepartmentId LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.GENTypes.Id = dbo.GENRawDatas.TypeId LEFT JOIN
                         dbo.AspNetUsers ON dbo.GENRawDatas.LastUpdatedById = dbo.AspNetUsers.Id LEFT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENRawDatas.CompanyId = dbo.GENCompanies.Id LEFT OUTER JOIN
                         dbo.CRMSRVReasons ON dbo.GENRawDatas.ReasonId = dbo.CRMSRVReasons.Id LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.GENRawDatas.StatusId = dbo.GENStatus.Id LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENStatus.IconId = dbo.GENStyles.Id LEFT OUTER JOIN
                         dbo.GENSalutations ON dbo.GENRawDatas.SalutationId = dbo.GENSalutations.Id LEFT OUTER JOIN
                         dbo.CRMSources ON dbo.GENRawDatas.SourceId = dbo.CRMSources.Id LEFT OUTER JOIN
                         dbo.GENRawDataTypes ON dbo.GENRawDatas.RawDataTypeId = dbo.GENRawDataTypes.Id LEFT OUTER JOIN
                         dbo.RawDataCategories ON dbo.GENRawDatas.RawDataCategoryId = dbo.RawDataCategories.Id 
						 CROSS APPLY dbo.tfn_ProcessByEntity(dbo.GENRawDatas.Id, 170) AS Process
GO
