Create   View [dbo].[V_BaseEntityWithItsInfoRelation]
as
select BaseEntities.Id AS BaseEntityId, BaseEntities.Name as BaseEntityName,BaseEntities.CategoryApiUrl ,BaseEntities.Url,BaseEntities.Theme
,BaseEntities.Description,
BaseTabs.Id As TabId ,BaseTabs.Name As TabName,
BaseEntityFields.Id AS BaseEntityFieldId, BaseEntityFields.DBField AS BaseEntityFieldDbfield,BaseEntityFields.DisplayName AS BaseEntityFieldDisplayName
,BaseEntityFields.DisplayOrder AS BaseEntityFieldDisplayOrder,BaseEntityFields.TypeListValueName As BaseEntityFieldType ,BaseEntityFields.IsmandatoryField AS BaseEntityFieldIsmandatoryField,
 BaseEntityRelations.Id AS BaseEntityRelationId ,BaseEntityRelations.DBField AS BaseEntityRelationDbfield , BaseEntityRelations.DisplayName AS BaseEntityRelationDisplayName ,BaseEntityRelations.EntityFKName AS BaseEntityRelationEntityFkname
,BaseEntityRelations.TypeListValueName As BaseEntityRelationType ,BaseEntityRelations.EntityApi As BaseEntityRelationEntityApi

from BaseEntities
inner join BaseTabBaseEntities on BaseTabBaseEntities.BaseEntity_Id = BaseEntities.Id
inner join BaseTabs on BaseTabBaseEntities.BaseTab_Id = BaseTabs.Id
inner join BaseEntityFields on BaseEntityFields.BaseEntityId = BaseEntities.Id
inner join BaseEntityRelations on BaseEntityRelations.BaseEntityId = BaseEntities.Id

where BaseTabs.isActive = 1 and BaseTabs.IsPublish = 1

GO
