/****** Object:  View [dbo].[Talents_Requestes]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[Talents_Requestes]
AS
SELECT        dbo.GENContacts.Name, dbo.GENContacts.DefaultEmail, dbo.GENContacts.DefaultPhone, dbo.GENTalents.Id AS TalentId,dbo.GENTalents.Name AS TalentName, dbo.Contacts_Courses.CourseStatus, dbo.fn_Course_TalentStatus(dbo.Contacts_Courses.TalentStatus) 
                         AS StatusName, dbo.fn_Course_TalentStatus_Color(dbo.Contacts_Courses.TalentStatus) AS StatusColor, dbo.AspNetUsers.Email, dbo.Contacts_Courses.CreatedDate, dbo.Contacts_Courses.UpdatedDate, dbo.Contacts_Courses.Id, 
                         dbo.Contacts_Courses.CourseId, dbo.Contacts_Courses.StudentId, dbo.Contacts_Courses.ClassRoomId,
						 dbo.GENContacts.Phone1, dbo.GENContacts.Phone2, dbo.GENContacts.Mobile1, dbo.GENContacts.Mobile2, 
                          dbo.GENTalents.Int1 AS CoursePriodHours,dbo.GENTalents.Int2 AS CoursePriodMinutes, 
						  dbo.GENContacts.Salutation_Name, 
                         dbo.GENContacts.LanguageId AS ContactlanguageId, dbo.GENListValues.Name AS ContactlanguageName, dbo.Contacts_Courses.OrderId, dbo.GENOrders.IsPaid, dbo.GENOrders.OrderPrice, dbo.GENOrders.PaidPrice, 
                         dbo.GENOrders.PaymentType, dbo.GENOrders.UserName, dbo.GENOrders.PhoneNumber, dbo.GENOrders.DateCreated, dbo.GENOrders.DateUpdated, dbo.GENOrders.CurrencyId, dbo.GENOrders.TransactionId, 
                         dbo.GENOrders.TransactionDetails, dbo.GENOrders.ResponseMessageCode, dbo.GENOrders.ResponseMessage, dbo.GENPaymentMethods.Name AS PaymentMethodName, dbo.GENOrders.Name AS CurrencyName,Contacts_Courses.TalentStatus,
						 GENCountries.Name AS CountryName,GENCountries.Code AS CountryCode,Contacts_Courses.Reason
FROM           
                         dbo.Contacts_Courses inner JOIN
						  dbo.GENTalents ON dbo.Contacts_Courses.TalentId = dbo.GENTalents.Id and Contacts_Courses.CourseId is NULL  LEFT OUTER JOIN
						 GENContacts ON Contacts_Courses.StudentId=GENContacts.Id left join 
						 AspNetUsers ON GENContacts.UserId =AspNetUsers.Id left join 
                         dbo.GENListValues ON dbo.GENContacts.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.GENOrders ON dbo.Contacts_Courses.OrderId = dbo.GENOrders.Id LEFT OUTER JOIN
                         dbo.GENPaymentMethods ON dbo.GENOrders.PaymentType = dbo.GENPaymentMethods.Id LEFT OUTER JOIN
                         dbo.GENCurrencies ON dbo.GENOrders.CurrencyId = dbo.GENCurrencies.Id left join 
						 GENAddresses ON GENContacts.Id=GENAddresses.EntityId and GENAddresses.BaseEntityId=47 left join 
						 GENCountries ON GENAddresses.CountryId=GENCountries.Id
WHERE GENContacts.IsDeleted = 0 and GENTalents.IsDeleted=0
GO
