CREATE VIEW [dbo].[Classroom_View]
AS
SELECT        dbo.GENClassrooms.Id, dbo.GENClassrooms.InteractiveMeetingURL, dbo.GENClassrooms.InstructorInstructions, dbo.GENClassrooms.ExamStartTime, FORMAT(dbo.GENClassrooms.ExamStartTime, 'dd/MM/yyyy HH:mm') 
                         AS ExamStartTimeString, dbo.GENClassrooms.ExamEndTime, FORMAT(dbo.GENClassrooms.ExamEndTime, 'dd/MM/yyyy HH:mm') AS ExamEndTimeString, dbo.GENClassrooms.FromDateTime, 
                         FORMAT(dbo.GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS FromDateTimeString, dbo.GENClassrooms.ToDateTime, FORMAT(dbo.GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS ToDateTimeString, 
                         FORMAT(dbo.GENClassrooms.ToDateTime, 'HH:mm') AS ToTimeString, FORMAT(dbo.GENClassrooms.FromDateTime, 'HH:mm') AS FromTimeString, dbo.GENClassrooms.InteractiveMeetingDateTime, 
                         FORMAT(dbo.GENClassrooms.InteractiveMeetingDateTime, 'dd/MM/yyyy HH:mm') AS InteractiveMeetingDateTimeString, dbo.GENClassrooms.IsShowInteractiveMeeting, dbo.GENClassrooms.DisplayOrder, 
                         dbo.GENClassrooms.CourseId, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.Code, dbo.GENClassrooms.Name, dbo.GENClassrooms.Description, dbo.GENClassrooms.ColorCode, dbo.GENClassrooms.IsCheckedOut, 
                         dbo.GENClassrooms.DateCreated, dbo.GENClassrooms.DateUpdated, dbo.GENClassrooms.CheckinDate, dbo.GENClassrooms.CheckoutDate, dbo.GENClassrooms.ExpectedCheckoutDate, dbo.GENClassrooms.Timeout, 
                         dbo.GENClassrooms.DisplayOrdering, dbo.GENClassrooms.CreatedById, dbo.GENClassrooms.LastUpdatedById, dbo.GENClassrooms.CheckoutBy, dbo.GENClassrooms.String1, dbo.GENClassrooms.String2, 
                         dbo.GENClassrooms.String3, dbo.GENClassrooms.String4, dbo.GENClassrooms.String5, dbo.GENClassrooms.Int1, dbo.GENClassrooms.Int2, dbo.GENClassrooms.Int3, dbo.GENClassrooms.Int4, dbo.GENClassrooms.Int5, 
                         dbo.GENClassrooms.Long1, dbo.GENClassrooms.Long2, dbo.GENClassrooms.Long3, dbo.GENClassrooms.Long4, dbo.GENClassrooms.Long5, dbo.GENClassrooms.Float1, dbo.GENClassrooms.Float2, 
                         dbo.GENClassrooms.Float3, dbo.GENClassrooms.Float4, dbo.GENClassrooms.Float5, dbo.GENClassrooms.Decimal1, dbo.GENClassrooms.Decimal2, dbo.GENClassrooms.Decimal3, dbo.GENClassrooms.Decimal4, 
                         dbo.GENClassrooms.Decimal5, dbo.GENClassrooms.Bool1, dbo.GENClassrooms.Bool2, dbo.GENClassrooms.Bool3, dbo.GENClassrooms.Bool4, dbo.GENClassrooms.Bool5, dbo.GENClassrooms.Date1, 
                         dbo.GENClassrooms.Date2, dbo.GENClassrooms.Date3, dbo.GENClassrooms.Date4, dbo.GENClassrooms.Date5, dbo.GENClassrooms.ValueId1, dbo.GENClassrooms.ValueId2, dbo.GENClassrooms.ValueId3, 
                         dbo.GENClassrooms.ValueId4, dbo.GENClassrooms.ValueId5, dbo.GENClassrooms.IconId, dbo.GENClassrooms.IsActive, dbo.GENClassrooms.IsPublish, dbo.GENClassrooms.ExamId, 
                         dbo.GENEmployees.Name AS InstructorName, dbo.GENTypes.Name AS CourseName, dbo.GENTypes.Description AS CourseDescription, dbo.GENPollCategories.Name AS ExamName, dbo.GENClassrooms.ClassRoomStatus, 
                         (CASE WHEN dbo.GENClassrooms.ClassRoomStatus = 0 THEN N'Started-تم البدء'  WHEN dbo.GENClassrooms.ClassRoomStatus = 1 THEN N'Dropped-تم إسقاطه' WHEN dbo.GENClassrooms.ClassRoomStatus
                          = 2 THEN N'Done-انتهى' WHEN dbo.GENClassrooms.ClassRoomStatus = 3 THEN N'Planned-مخطط' WHEN dbo.GENClassrooms.ClassRoomStatus = 4 THEN N'Open-مفتوح'  ELSE N'' END) AS ClassRoomStatusString, FORMAT(dbo.GENClassrooms.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, FORMAT(dbo.GENClassrooms.DateUpdated, 'dd/MM/yyyy') 
                         AS DateUpdatedString, dbo.GENClassrooms.LanguageId AS Lang_Id, dbo.GENListValues.Name AS Lang_Name, dbo.GENListValues.ShortCode, dbo.GENClassrooms.RoomId, GENRooms.Name AS RoomName, 
                         (CASE WHEN dbo.GENClassrooms.PaymentTypeId = 0 THEN N'Paied-مدفوع' ELSE CASE WHEN dbo.GENClassrooms.PaymentTypeId = 1 THEN N'NotPaid-غير مدفوع' ELSE CASE WHEN dbo.GENClassrooms.PaymentTypeId = 2 THEN
                          N'Returned-عاد' ELSE N'' END END END) AS PaymentTypeString, 
                         (CASE WHEN dbo.GENClassrooms.BookingTypeId = 0 THEN N'Requested-طلب' WHEN dbo.GENClassrooms.BookingTypeId = 1 THEN N'Confirmed-مؤكد' WHEN dbo.GENClassrooms.BookingTypeId = 2 THEN N'Rejected-مرفوض' WHEN
                          dbo.GENClassrooms.BookingTypeId = 3 THEN N'Blocked-مقفول' WHEN dbo.GENClassrooms.BookingTypeId = 4 THEN N'Canceled-ملغي' WHEN dbo.GENClassrooms.BookingTypeId = 5 THEN N'Waiting-انتظال' WHEN dbo.GENClassrooms.BookingTypeId
                          = 6 THEN N'Added-مضاف' ELSE N'' END) AS BookingTypeString, GENClassrooms.BookingTypeId, GENClassrooms.PaymentTypeId, GENTypes.Int2 AS NumberOfDays, GENTypes.int1 AS TotalCoursehours, 
                         dbo.GENClassrooms.ClassRoomShift, (CASE WHEN dbo.GENClassrooms.ClassRoomShift = 0 THEN N'Morning-صباحي' WHEN dbo.GENClassrooms.ClassRoomShift = 1 THEN N'Evening-مسائي' ELSE N'' END) 
                         AS ClassRoomShiftString, dbo.GENClassrooms.PaymentCondation, dbo.GENClassrooms.IsDeleted, 
                         (CASE WHEN dbo.GENClassrooms.PaymentCondation = 0 THEN N'FullAdvancedPayment-كلي' WHEN dbo.GENClassrooms.PaymentCondation = 1 THEN N'NoAdvancedPayment-بدون' WHEN dbo.GENClassrooms.PaymentCondation
                          = 2 THEN N'PreAdvancedPayment-دفعة' WHEN dbo.GENClassrooms.PaymentCondation = 3 THEN N'Free-مجاني' ELSE N'' END) AS PaymentCondationString, GENClassrooms.GroupTypeId, GENClassrooms.IsPlan, 
                         GENClassrooms.IsAchievementRanking, GENClassrooms.CompanyId AS Co_Id, GENClassrooms.ActivityResponsiblePerson, GENClassrooms.ActivityTitle, GENCompanies.Name AS Co_Name, 
                         GENCompanies.Code AS Co_Code, GENClassrooms.GovernorateId, GENClassrooms.CityId, GENGovernorates.Name AS GovernorateName, GENCities.Name AS CityName, GENTypes.Code AS CourseCode, 
                         GENClassrooms.ClassroomCategoryId, GENClassrooms.EventTypeId, GENClassrooms.Instructor_Name, Event.Name AS EventTypeString, Event.Code AS EventTypeCode, dbo.GENClassrooms.IsPosted, 
                         (CASE WHEN CAST(dbo.GENClassrooms.ToDateTime AS date) < CAST(getdate() AS date) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END) AS IsExpired, destinations.Name AS DestinationsName, GENClassrooms.DestinationsId, 
                         GENClassrooms.ProsecutionId, dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) AS ConfirmedCount, dbo.fn_VcrBookingStudentCount_Waiting(GENClassrooms.Id) AS WaitingCount, 
                         dbo.fn_VcrBookingStudentCount_Requested(GENClassrooms.Id) AS Req_Count, AspNetUsers.Name AS LastUpdatedByName, GENClassrooms.IsAgenda, GENTypes.Int3 AS AttPre, dbo.GENClassrooms.RandomNumber, 
                         dbo.GENClassrooms.IsPrivate,GENClassrooms.deletedByName,FORMAT(dbo.GENClassrooms.DeletedDate, 'dd/MM/yyyy') AS DeletedDateString,
						 GENClassrooms.vcrCourseDescription, Organization.Id as OrganizationId,Organization.Code as OrganizationCode,Organization.Name as OrganizationName,GENClassrooms.WikiId as WikiId,GENWikis.name as WikiName
						 ,[dbo].[fn_VcrStudentCount](GENClassrooms.Id) + dbo.GENClassrooms.Int1 AS AllStudentCounts, 
                         (CASE WHEN dbo.GENClassrooms.ProsecutionId = 0 THEN N'TrainingPlanning-تدريب' WHEN dbo.GENClassrooms.ProsecutionId = 1 THEN N'PostGraduate-الدراسات العليا'  WHEN dbo.GENClassrooms.ProsecutionId = 2 THEN
                          N'Research-ابحاث' WHEN dbo.GENClassrooms.ProsecutionId = 3 THEN N'CommunicationInternationalRelations-الاتصالات والعلاقات الدولية'  WHEN dbo.GENClassrooms.ProsecutionId = 4 THEN N'SecretaryGeneral-الأمين العام' ELSE N'' END ) AS ProsecutionString
FROM            dbo.GENClassrooms LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENClassrooms.CompanyId = dbo.GENCompanies.Id LEFT OUTER JOIN
                         dbo.GENPollCategories ON dbo.GENClassrooms.ExamId = dbo.GENPollCategories.Id LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.GENRooms ON GENClassrooms.RoomId = GENRooms.Id LEFT OUTER JOIN
                         dbo.GENGovernorates ON dbo.GENClassrooms.GovernorateId = dbo.GENGovernorates.Id LEFT OUTER JOIN
                         dbo.GENCities ON dbo.GENClassrooms.CityId = dbo.GENCities.Id LEFT OUTER JOIN
                         dbo.GENListValues AS Event ON dbo.GENClassrooms.EventTypeId = Event.Id LEFT OUTER JOIN
                         dbo.GENCompanies AS destinations ON dbo.GENClassrooms.DestinationsId = destinations.Id LEFT OUTER JOIN
                         dbo.AspNetUsers ON GENClassrooms.LastUpdatedById = AspNetUsers.UserName  LEFT OUTER JOIN
                         dbo.GENCompanies Organization ON dbo.GENClassrooms.OrganizationId = Organization.Id left join
						 GENWikis on GENWikis.Id =GENClassrooms.WikiId
GO
