CREATE VIEW [dbo].[Courses_Requestes]
AS
SELECT        dbo.GENContacts.Name, dbo.GENContacts.DefaultEmail, dbo.GENContacts.DefaultPhone, dbo.GENTypes.Name AS TypeName, dbo.Contacts_Courses.CourseStatus, dbo.fn_Course_Status(dbo.Contacts_Courses.CourseStatus) 
                         AS StatusName, dbo.fn_Course_Status_Color(dbo.Contacts_Courses.CourseStatus) AS StatusColor, dbo.AspNetUsers.Email, dbo.Contacts_Courses.CreatedDate, dbo.Contacts_Courses.UpdatedDate, dbo.Contacts_Courses.Id, 
                         dbo.Contacts_Courses.CourseId, dbo.Contacts_Courses.StudentId, dbo.Contacts_Courses.ClassRoomId, dbo.fn_ClassRoomName_ContactandCourseId(dbo.Contacts_Courses.StudentId, dbo.Contacts_Courses.CourseId) 
                         AS ClassRoomName, dbo.GENContacts.Phone1, dbo.GENContacts.Phone2, dbo.GENContacts.Mobile1, dbo.GENContacts.Mobile2, CONVERT(varchar, 
                         dbo.fn_ClassRoomIdId_ContactandCourseStartFrom(dbo.Contacts_Courses.StudentId, dbo.Contacts_Courses.CourseId), 103) AS StartFrom, CONVERT(varchar, 
                         dbo.fn_ClassRoom_ContactandCourseDatTo(dbo.Contacts_Courses.StudentId, dbo.Contacts_Courses.CourseId), 103) AS EndDate, dbo.Classroom_View.InstructorName, dbo.Classroom_View.ExamName, 
                          dbo.GENTypes.Int1 AS CoursePriodHours,dbo.GENTypes.Int2 AS CoursePriodMinutes, dbo.fn_ItemCount_TypeId(dbo.Contacts_Courses.CourseId) AS LectureCount, dbo.Classroom_View.Lang_Id, dbo.Classroom_View.Lang_Name, dbo.GENContacts.Salutation_Name, 
                         dbo.GENContacts.LanguageId AS ContactlanguageId, dbo.GENListValues.Name AS ContactlanguageName, dbo.Contacts_Courses.OrderId, dbo.GENOrders.IsPaid, dbo.GENOrders.OrderPrice, dbo.GENOrders.PaidPrice, 
                         dbo.GENOrders.PaymentType, dbo.GENOrders.UserName, dbo.GENOrders.PhoneNumber, dbo.GENOrders.DateCreated, dbo.GENOrders.DateUpdated, dbo.GENOrders.CurrencyId, dbo.GENOrders.TransactionId, 
                         dbo.GENOrders.TransactionDetails, dbo.GENOrders.ResponseMessageCode, dbo.GENOrders.ResponseMessage, dbo.GENPaymentMethods.Name AS PaymentMethodName, dbo.GENOrders.Name AS CurrencyName
FROM            dbo.AspNetUsers RIGHT OUTER JOIN
                         dbo.GENContacts RIGHT OUTER JOIN
                         dbo.Contacts_Courses LEFT OUTER JOIN
                         dbo.Classroom_View ON dbo.Contacts_Courses.ClassRoomId = dbo.Classroom_View.Id ON dbo.GENContacts.Id = dbo.Contacts_Courses.StudentId ON dbo.AspNetUsers.Id = dbo.GENContacts.UserId LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.Contacts_Courses.CourseId = dbo.GENTypes.Id LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENContacts.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.GENOrders ON dbo.Contacts_Courses.OrderId = dbo.GENOrders.Id LEFT OUTER JOIN
                         dbo.GENPaymentMethods ON dbo.GENOrders.PaymentType = dbo.GENPaymentMethods.Id LEFT OUTER JOIN
                         dbo.GENCurrencies ON dbo.GENOrders.CurrencyId = dbo.GENCurrencies.Id
WHERE GENContacts.IsDeleted = 0
GO
