      ,[GENContacts].[Club_Name]
      ,[GENContacts].[PositionRecruitment_Name]
      ,[GENContacts].[Referral_Name]
      ,[GENContacts].[Nationality_Name]
      ,[GENContacts].[ContactCategory_Name]
	  ,[GENContacts].[PageOfPageId] AS PopId
      ,[GENContacts].[PageOfPageName]
      ,[GENContacts].[RichContent]
	  ,[GENContacts].[AppVersion],org.Name AS OrganizationName,GENContacts.Training,(CASE WHEN dbo.GENContacts.isResponsibleDestinations =1 THEN N'متدرب جهة' ELSE N'متدرب فردي' END) AS StudentType,dbo.fnCount_VcrsByContactId(GENContacts.Id) as VCRCount,
	GENContacts.Other1,GENContacts.Other2,GENContacts.isResponsibleDestinations,GENCompanies.Code AS DestCode,dbo.GENContacts.Company_Name,
	CountryDegreeId
FROM            dbo.GENContacts LEFT OUTER JOIN 
                         dbo.GENContactTypes ON dbo.GENContacts.ContactTypeId = dbo.GENContactTypes.Id LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.GENContacts.TypeId = dbo.GENTypes.Id LEFT OUTER JOIN
                         dbo.GENDepartments ON dbo.GENContacts.DepartmentId = dbo.GENDepartments.Id LEFT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENContacts.CompanyId = dbo.GENCompanies.Id LEFT OUTER JOIN
                         dbo.ContactInfoes ON dbo.GENContacts.Id = dbo.ContactInfoes.ContactId LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENContacts.LanguageId = dbo.GENListValues.Id Left join 
						 dbo.GENListValues RR ON dbo.GENContacts.RelativeRelationId = RR.Id Left join 
