/****** Object:  View [dbo].[VCRContact_View]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE View [dbo].[VCRContact_View]
as
	select DISTINCT Contact_View.Id,Contact_View.Name,Contact_View.DateUpdated,GENClassroom_GENContact.StudentStatus as StudentStatusValue ,

	(CASE
    WHEN GENClassroom_GENContact.StudentStatus =1 THEN 'Regular'
    WHEN GENClassroom_GENContact.StudentStatus =2 THEN 'Ban'
   WHEN GENClassroom_GENContact.StudentStatus =3 THEN 'Stopped'
   WHEN GENClassroom_GENContact.StudentStatus =4 THEN 'Dropped'
    ELSE ''
END)as StudentStatus,GENClassroom_GENContact.IsConfirmed,

	(CASE
    WHEN GENClassroom_GENContact.PaymentTypeId = 0 THEN 'Paid'
    WHEN GENClassroom_GENContact.PaymentTypeId = 1 THEN 'NotPaid'
   WHEN GENClassroom_GENContact.PaymentTypeId = 2 THEN 'Returned'
    ELSE ''
END)as PaymentType,GENClassroom_GENContact.PaymentTypeId,

	(CASE
    WHEN GENClassroom_GENContact.BookingTypeId = 0 THEN 'Requested'
    WHEN GENClassroom_GENContact.BookingTypeId = 1 THEN 'Confirmed'
   WHEN GENClassroom_GENContact.BookingTypeId = 2 THEN 'Rejected'
   WHEN GENClassroom_GENContact.BookingTypeId = 3 THEN 'Blocked'
   WHEN GENClassroom_GENContact.BookingTypeId = 4 THEN 'Canceled'
   WHEN GENClassroom_GENContact.BookingTypeId = 5 THEN 'Waiting'
   WHEN GENClassroom_GENContact.BookingTypeId = 6 THEN 'Added'
    ELSE ''
END)as BookingType,GENClassroom_GENContact.BookingTypeId,GENClassroom_GENContact.Id as ClassRoomContactId,GENClassrooms.Name as ClassroomName
	 from GENClassroom_GENContact
	 inner join GENClassrooms on GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
	INNER JOIN Contact_View ON GENClassroom_GENContact.StudentId = Contact_View.Id
GO
/****** Object:  View [dbo].[Employee_Contacts_Chat_View]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


Create VIEW [dbo].[Employee_Contacts_Chat_View]
AS
select AspNetUsers.Id AS UserId,GENcontacts.Name,'Student' AS Type
from GENcontacts
inner join AspNetUsers ON GENcontacts.UserId =AspNetUsers.Id

where GENcontacts.IsActive=1 and GENcontacts.IsDeleted=0
union 


select  AspNetUsers.Id AS UserId,GENEmployees.Name,'Employee' AS Type
from GENEmployees
inner join AspNetUsers ON GENEmployees.UserId =AspNetUsers.Id
where GENEmployees.IsActive=1 and GENEmployees.IsDeleted=0
GO
