                         dbo.TicketInfoes.ReasonTypeName, dbo.TicketInfoes.ReasonIcon, dbo.TicketInfoes.ReasonColor, dbo.TicketInfoes.ReasonName, dbo.TicketInfoes.TicketTypeColor, dbo.TicketInfoes.TicketTypeIcon, 
                         dbo.TicketInfoes.ComplainClassifIcon , Process.ListValueName AS ProcessListValueName, Process.Comment AS ProcessComment, dbo.TicketInfoes.ComplainClassifColor, dbo.TicketInfoes.ComplainTypeIcon, dbo.TicketInfoes.ComplainTypeColor, dbo.TicketInfoes.CurrencyName, dbo.TicketInfoes.TicketTypeName, 
                         dbo.TicketInfoes.ContactCategoryName, dbo.TicketInfoes.EscalatedToName, dbo.TicketInfoes.valueId5tName, dbo.TicketInfoes.valueId4tName, dbo.TicketInfoes.valueId3tName, dbo.TicketInfoes.valueId2tName, 
                         dbo.TicketInfoes.valueId1tName, dbo.TicketInfoes.numSet, dbo.CRMTickets.ManualEscalationTime, dbo.CRMTickets.EscalatedById, dbo.TicketInfoes.EscalatedToPosition, dbo.CRMTickets.StartDate, 
                         dbo.Diff_BetweenDates(CRMTickets.DateCreated, GETDATE()) AS TicketLifeDate, dbo.CRMTickets.StartDateDiff, dbo.CRMTickets.IsUsed, (dbo.fnEmployee_PosisionById(dbo.CRMTickets.EscalatedById) 
                         + ' ' + dbo.fnEmployee_NameById(dbo.CRMTickets.EscalatedById)) AS EscalatedByName, FORMAT(dbo.CRMTickets.ManualEscalationTime, 'dd/MM/yyyy hh:mm tt') AS EscalatedDateString, 
                         iif(dbo.CRMTickets.OverDueDate <= getdate(), cast(1 AS bit), cast(0 AS bit)) AS IsOverDue,CRMTickets.ProsecutionId
FROM            dbo.CRMTickets LEFT OUTER JOIN
                         dbo.TicketInfoes ON dbo.CRMTickets.Id = dbo.TicketInfoes.TIcketId LEFT OUTER JOIN
                         dbo.GENEmployees AS Worker ON dbo.CRMTickets.EmployeeId = Worker.Id LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.TicketInfoes.ProcessId = dbo.GENStatus.Id LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENStatus.IconId = dbo.GENStyles.Id LEFT OUTER JOIN
						 dbo.GENItems ON dbo.CRMTickets.ItemId= dbo.GENItems.Id LEFT OUTER JOIN
						 dbo.CRMSRVReasons ON dbo.CRMTickets.ReasonId = dbo.CRMSRVReasons.Id LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.CRMTickets.CheckoutBy = dbo.GENEmployees.UserId LEFT OUTER JOIN
                         dbo.GENEmployees AS ResponsiblePerson ON dbo.CRMTickets.EmployeeId = ResponsiblePerson.Id 
						 CROSS APPLY dbo.tfn_ProcessByEntity(dbo.CRMTickets.Id, 169) AS Process
GO
