						 FORMAT(dbo.CRMDeals.Date3, 'dd/MM/yyyy') AS Date3String,FORMAT(dbo.CRMDeals.Date4, 'dd/MM/yyyy') AS Date4String,
						 FORMAT(dbo.CRMDeals.Date5, 'dd/MM/yyyy') AS Date5String
FROM            dbo.CRMDeals LEFT OUTER JOIN
                         dbo.DealInfoes ON dbo.CRMDeals.Id = dbo.DealInfoes.DealId LEFT JOIN
                         dbo.GENEmployees ON dbo.CRMDeals.CheckoutBy = dbo.GENEmployees.UserId LEFT JOIN
                         dbo.GENEmployees AS ResponsiblePerson ON dbo.CRMDeals.ResponsiblePersonId = ResponsiblePerson.Id
