/****** Object:  View [dbo].[NACA_MenuView]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[NACA_MenuView]
AS
SELECT        dbo.GENListValues.Name AS SectionName, dbo.GENWikiCategories.Name, dbo.GENListValues.Id, dbo.GENWikiCategories.String1 + '/' + CAST(dbo.GENWikiCategories.Id AS nvarchar(200)) AS URL, 
                         dbo.GENListValues.DisplayOrdering, dbo.GENListValues.String1 AS MainURL, dbo.GENWikiCategories.DisplayOrdering AS SubMenuOrder, dbo.fn_FirstImageNotDefault_BaseEntityEntityId(26, dbo.GENWikiCategories.Id) 
                         AS CategoryImage
FROM            dbo.GENListValues LEFT OUTER JOIN
                         dbo.GENWikiCategories ON dbo.GENListValues.Id = dbo.GENWikiCategories.ValueId1 RIGHT OUTER JOIN
                         dbo.GENListValuesTypes ON dbo.GENListValues.GENListValuesTypeId = dbo.GENListValuesTypes.Id
WHERE        (dbo.GENListValuesTypes.Name = N'Menu section') AND (dbo.GENListValues.IsActive = 1) AND (dbo.GENWikiCategories.Name IS NOT NULL) AND (dbo.GENWikiCategories.IsMenu = 1)
GO
/****** Object:  View [dbo].[Rpt_AchievementsDtls_View]    Script Date: 7/1/2026 10:44:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create VIEW [dbo].[Rpt_AchievementsDtls_View]
AS
select GENClassrooms.Id,GENClassrooms.Code as ClassroomCode,GENTypes.Name as CourseName,GENClassrooms.Name as ClassroomName,(case when GroupTypeID = 0 then 'Free' when GroupTypeID = 1 then 'Money'
when GroupTypeID =2 then 'Plan' when GroupTypeID = 3 then 'Approval' when GroupTypeID = 4 then 'GraduateStudies' end) as GroupType
,(case when isnull(IsPlan,0) = 1 then N'انشطه داخل التدريب' else N'انشطه خارج التدريب' end) as IsPlan,GENCompanies.Name as CompanyName
,GENGovernorates.Name as GENGovernorateName,GENCities.Name as GENCityName,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,(GENClassrooms.Int1) as ContactCount,(case when GENClassrooms.ProsecutionId = 2 then N'بحوث' when GENClassrooms.ProsecutionId = 4 then N'الامين العام'
when GENClassrooms.ProsecutionId = 1 then N'الدراسات العليا' when GENClassrooms.ProsecutionId = 3 then N'الاتصالات والعلاقات الدولية' when GENClassrooms.ProsecutionId = 0 then N'التخطيط والتدريب' end)as Prosecution
,GENClassrooms.instructor_Name AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudents,
GENClassrooms.ClassRoomStatus
from GENClassrooms
left join GENCompanies on GENClassrooms.CompanyId = GENCompanies.Id
left join GENTypes on GENClassrooms.CourseId = GENTypes.Id
left join GENGovernorates on GENGovernorates.Id = GENClassrooms.GovernorateId
left join GENCities on GENCities.Id = GENClassrooms.CityId 
left join AspNetUsers Created ON GENClassrooms.CreatedById =Created.email 
left join GENRooms ON GENClassrooms.RoomId=GENRooms.Id
where ClassroomCategoryId = 2  
 and (GENClassrooms.IsDeleted = 0 or GENClassrooms.IsDeleted is null) 
 and (GENClassrooms.ClassRoomStatus = 2)
and GENClassrooms.ProsecutionId = 0 

union 

select GENClassrooms.Id, GENClassrooms.Code as ClassroomCode,GENTypes.Name as CourseName,GENClassrooms.Name as ClassroomName,(case when GroupTypeID = 0 then 'Free' when GroupTypeID = 1 then 'Money'
when GroupTypeID =2 then 'Plan' when GroupTypeID = 3 then 'Approval' when GroupTypeID = 4 then 'GraduateStudies' end) as GroupType
,(case when isnull(IsPlan,0) = 1 then N'انشطه داخل التدريب' else N'انشطه خارج التدريب' end) as IsPlan,GENCompanies.Name as CompanyName
,GENGovernorates.Name as GENGovernorateName,GENCities.Name as GENCityName,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,count(GENClassroom_GENContact.Id) as ContactCount,
(case when GENClassrooms.ProsecutionId = 2 then N'بحوث' when GENClassrooms.ProsecutionId = 4 then N'الامين العام'
when GENClassrooms.ProsecutionId = 1 then N'الدراسات العليا' when GENClassrooms.ProsecutionId = 3 then N'الاتصالات والعلاقات الدولية' when GENClassrooms.ProsecutionId = 0 then N'التخطيط والتدريب' end)as Prosecution
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudents,
GENClassrooms.ClassRoomStatus
from GENClassrooms
left join GENCompanies on GENClassrooms.CompanyId = GENCompanies.Id
left join GENTypes on GENClassrooms.CourseId = GENTypes.Id
left join GENGovernorates on GENGovernorates.Id = GENClassrooms.GovernorateId
left join GENCities on GENCities.Id = GENClassrooms.CityId
left join GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId = GENClassrooms.Id 
and ([dbo].[AttendanceCall]([GENClassroom_GENContact].StudentId,GENClassrooms.Id) >=isnull(GENClassrooms.Int4,GENTypes.int3))  and [GENClassroom_GENContact].BookingTypeId = 1
left join AspNetUsers Created ON GENClassrooms.CreatedById =Created.email 
left join GENRooms ON GENClassrooms.RoomId=GENRooms.Id
where ClassroomCategoryId = 1 


  and (GENClassrooms.IsDeleted = 0 or GENClassrooms.IsDeleted is null)
 and (GENClassrooms.ClassRoomStatus = 2) and GENClassrooms.ProsecutionId = 0
group by GENClassrooms.Code,GENClassrooms.Name,GroupTypeID,IsPlan,GENCompanies.Name,GENGovernorates.Name,GENCities.Name,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,GENTypes.Name,GENClassrooms.ProsecutionId,GENClassrooms.ClassRoomStatus,GENClassrooms.String1,GENRooms.Name,Created.Name,GENClassrooms.Id,GENClassrooms.instructor_Name
GO
