CREATE VIEW [dbo].[TCR_View]
AS
SELECT        dbo.GENTCRs.Id, dbo.GENTCRs.ContactId, dbo.GENTCRs.DealId, dbo.fn_TCR_DealAmount(dbo.GENTCRs.DealId) AS TcrDealAmount, dbo.GENTCRs.EmployeeId, dbo.GENTCRs.PriceSales, dbo.GENTCRs.Amount, 
                         dbo.GENTCRs.Comment, dbo.GENTCRs.IsActive, dbo.GENTCRs.IsPublish, dbo.GENTCRs.IsJunk, dbo.GENTCRs.IsDeleted, dbo.GENTCRs.Code, dbo.GENTCRs.Name, dbo.GENTCRs.Description, dbo.GENTCRs.IsCheckedOut, 
                         dbo.GENTCRs.DateCreated, dbo.GENTCRs.DateUpdated, dbo.GENTCRs.CheckinDate, dbo.GENTCRs.CheckoutDate, dbo.GENTCRs.Timeout, dbo.GENTCRs.CreatedById, dbo.GENTCRs.LastUpdatedById, 
                         dbo.GENTCRs.CheckoutBy, dbo.GENTCRs.ContractDate, CONVERT(varchar, dbo.CRMDeals.DateCreated, 103) AS ContractDateString, dbo.GENTCRs.ExtendDateTime, dbo.GENTCRs.DisplayOrdering, dbo.GENTCRs.ColorCode, 
                         dbo.GENTCRs.String1, dbo.GENTCRs.String2, dbo.GENTCRs.String3, dbo.GENTCRs.String4, dbo.GENTCRs.String5, dbo.GENTCRs.Int1, dbo.GENTCRs.Int2, dbo.GENTCRs.Int3, dbo.GENTCRs.Int4, dbo.GENTCRs.Long1, 
                         dbo.GENTCRs.Long2, dbo.GENTCRs.Long3, dbo.GENTCRs.Long4, dbo.GENTCRs.Int5, dbo.GENTCRs.Long5, dbo.GENTCRs.Float1, dbo.GENTCRs.Float2, dbo.GENTCRs.Float3, dbo.GENTCRs.Float4, dbo.GENTCRs.Float5, 
                         dbo.GENTCRs.Decimal1, dbo.GENTCRs.Decimal3, dbo.GENTCRs.Decimal2, dbo.GENTCRs.Decimal4, dbo.GENTCRs.Decimal5, dbo.GENTCRs.Bool1, dbo.GENTCRs.Bool2, dbo.GENTCRs.Bool3, dbo.GENTCRs.Bool4, 
                         dbo.GENTCRs.Bool5, dbo.GENTCRs.Date1, dbo.GENTCRs.Date2, dbo.GENTCRs.Date3, dbo.GENTCRs.Date4, dbo.GENTCRs.Date5, dbo.GENTCRs.ValueId1, dbo.GENTCRs.ValueId2, dbo.GENTCRs.ValueId3, 
                         dbo.GENTCRs.ValueId4, dbo.GENTCRs.ValueId5, dbo.GENTCRs.IconId, dbo.GENContacts.Name AS ContactName, dbo.CRMDeals.Name AS DealName, dbo.GENEmployees.Name AS EmployeeName, 
                         dbo.GENEmployees.Image AS EmployeeImage, AspNetUsers_1.Name AS CreatedByName, dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENListValues.Name AS AssessmentName, dbo.CRMDeals.DefaultEmail, 
                         dbo.CRMDeals.DefaultPhone, GENListValues_1.Name AS PriortyName, GENListValues_1.Value AS PriortyColor, GENStyles_1.StyleValue AS PriortyIcon, dbo.CRMSources.Name AS SourceName, 
                         dbo.GENStatus.Name AS StatusName, dbo.GENStatus.ColorCode AS StatusColor, dbo.GENStyles.StyleValue AS StatusIcon, dbo.GENStatus.SuccessRate, dbo.CRMDealItems.Name AS ItemName, 
                         dbo.GENTypes.Name AS PropertyType, dbo.GENProjects.Name AS ProjectName, dbo.fnCompany_Phone(dbo.CRMDeals.CompanyId) AS CompanyPhone, dbo.fnCompany_Email(dbo.CRMDeals.CompanyId) AS CompanyEmail, 
                         dbo.fnCompany_Name(dbo.CRMDeals.CompanyId) AS CompanyName, dbo.GENCompanies.Name AS DeveloperName, dbo.CRMDeals.DealTypeId, dbo.GENItems.ProjectId, dbo.GENProjects.CompanyId AS DeveloperId, 
                         dbo.GENTCRs.TCRTypeId, Process.CompletionRate AS StatusComplition, Process.StatusStyle AS ProcessIcon, Process.SuccessRate AS ProcessSuccessRate, Process.StatusName AS ProcessName, Process.IsFinal AS IsFinal, 
                         Process.IsFirst AS IsFirst, Process.IsMap AS IsClosed, Process.StatusColor AS ProcessColor, Process.StatusId AS ProcessId, dbo.GENTCRs.BranchId, GENContacts.Title AS ContactTitle, 
                         GENEmployees.Telephone AS EmployeeTel, GENEmployees.Email AS EmployeeEmail, GENEmployees.Position AS EmployeeTitle, InvoiceNumber, InvoiceAmount, NetInvoiceAmount,iif( dbo.GENTCRs.Discount is null,0,dbo.GENTCRs.Discount) as Discount, 
                         dbo.GENTCRs.OpreationId
FROM            dbo.GENProjects LEFT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENProjects.CompanyId = dbo.GENCompanies.Id RIGHT OUTER JOIN
                         dbo.GENItems ON dbo.GENProjects.Id = dbo.GENItems.ProjectId LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.GENItems.TypeId = dbo.GENTypes.Id RIGHT OUTER JOIN
                         dbo.CRMDealItems ON dbo.GENItems.Id = dbo.CRMDealItems.Id RIGHT OUTER JOIN
                         dbo.CRMDeals ON dbo.CRMDealItems.Id = dbo.CRMDeals.Id LEFT OUTER JOIN
                         dbo.GENStatus LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENStatus.IconId = dbo.GENStyles.Id ON dbo.CRMDeals.StatusId = dbo.GENStatus.TypeStatusId LEFT OUTER JOIN
                         dbo.CRMSources ON dbo.CRMDeals.SourceId = dbo.CRMSources.Id LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_1 LEFT OUTER JOIN
                         dbo.GENStyles AS GENStyles_1 ON GENListValues_1.IconId = GENStyles_1.Id ON dbo.CRMDeals.PriortyId = GENListValues_1.Id LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.CRMDeals.AssessmentId = dbo.GENListValues.Id RIGHT OUTER JOIN
                         dbo.GENTCRs LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENTCRs.LastUpdatedById = dbo.AspNetUsers.Id LEFT OUTER JOIN
                         dbo.AspNetUsers AS AspNetUsers_1 ON dbo.GENTCRs.CreatedById = AspNetUsers_1.Id ON dbo.CRMDeals.Id = dbo.GENTCRs.DealId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENTCRs.EmployeeId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.GENTCRs.ContactId = dbo.GENContacts.Id CROSS APPLY dbo.tfn_ProcessByEntity(dbo.GENTCRs.Id, 167) AS Process
GO
