CREATE VIEW [dbo].[Rpt_Activity_View]
AS
SELECT DISTINCT 
Activity.Id AS Id2, Activity.Id, Activity.FieldName, Activity.PaymentMethodId, 
PaymentMethod.Name AS PaymentMethodName, 
CreatorEmp.Id AS CreatedEmployeeId, 
ActivityStatusStyle.StyleValue AS StatusIcon, 
ActivityStatus.ColorCode AS StatusColor, 
Activity.TicketId, Activity.Comment, Activity.CommentTypeId, Activity.DateCreated, 
Value1.Name AS ValueId1tName, 
Value2.Name AS ValueId2tName, 
Value3.Name AS ValueId3tName, 
Value4.Name AS ValueId4tName, 
Value5.Name AS ValueId5tName, 
Activity.DateUpdated, 
Activity.DateDeleted, 
Activity.CreatedById, 
Activity.DeletedById, 
Activity.LastUpdatedById, 
Activity.NextActionDate, Activity.NextActionId, Activity.IsNextStep, Activity.ActionDate, 
 FORMAT(Activity.ActionDate, 'dd/MM/yyyy hh:mm tt') AS ActionDateString, Activity.NextStepDescription, Activity.StatusId, Activity.EntityId, 
 Activity.BaseEntityId, Activity.NextActivityId, Activity.ParentActivityId, 
 Activity.IsCancelled, Activity.Day, Activity.BaseEntityTo, Activity.EntityIdTo, Activity.IsRepeated, Activity.LastNotificationDate, Activity.ExpiredDate, 
 Activity.DateFrom, Activity.TimeFrom, Activity.Dateto, Activity.Timeto, 
 Activity.RepeatPeriodId, Activity.SchedulerType, Activity.NotificationType, Activity.EventTypeId, Activity.ActivtyTypeId, Activity.Number, 
 Activity.ActionTypeId, Activity.ListValueId, Activity.Name, Activity.IsDeleted, Activity.Reason, 
 Activity.IsCompleted, Activity.PageofPagesId, 
 BackendPage.DisplayName AS PageName, Activity.RepeatNumber, Activity.RepeatEndDate, Activity.Color, Activity.IsCancelledActivities, 
 dbo.fn_Activity_OverDue(Activity.Id, Activity.StatusId) AS IsOverDueActivities, 
 dbo.fn_Activity_OverDue(Activity.Id, Activity.StatusId) AS IsOverDue, Activity.IsNextActionsActivities, Activity.IsPlannedActivities, 
 Activity.IsDoneActivities, ActivityStatusStyle.StyleValue AS ActivityIcon, 
 CommentStyle.StyleValue AS CommentIcon, 
 activityType.Name AS CommentTypeName, 
 activityType.Name AS NextActionName, activityType.ColorCode AS CommentColor, ActivityStatus.Name AS StatusName, 
 MainContact.Id AS ContactId, MainContact.Name AS ActivityContactName, 
 MainContact.Code AS ContactCode, MainContact.DefaultEmail AS ContactDefaultEmail, MainContact.Image AS ContactImage, MainContact.DefaultPhone AS ContactDefaultPhone, 
 MainContact.DefaultAddress AS ContactDefaultAddress, MainContact.Name AS ContactName, 
 ActivityEmployee.Name AS EmployeeName, 
 ActivityEmployee.Id AS EmployeeId, 
 ActivityEmployee.Telephone AS EmployeeDefaultPhone, 
 ManagerEmployee.Name AS ManagerName, 
 --dbo.fnContactPerson_Name(Activity.Id) AS ContactPersonName, 
 CreatorEmp.Name AS CreatedByName, 
 Activity.ItemId, Activity.CRMTicketId, Activity.MainContactId,
 (CASE WHEN dbo.ItemFlatDatas.PriceSales IS NOT NULL THEN dbo.ItemFlatDatas.PriceSales ELSE 0.0 END) AS Price, (CASE WHEN dbo.CRMSRVTicketTypes.Name IS NOT NULL 
 THEN dbo.CRMSRVTicketTypes.Name ELSE dbo.CRMTickets.Name END) AS CRMTicketName, 
 dbo.CRMTickets.OpenDate, CONVERT(varchar, Activity.DateCreated, 103) AS DateCreatedString, CONVERT(varchar, 
 Activity.DateCreated, 108) AS TimeCreatedString, CONVERT(varchar, Activity.DateUpdated, 103) AS DateUpdatedString, 
 CONVERT(varchar, Activity.DateUpdated, 108) AS TimeUpdatedString, 
 CAST(activityType.Id AS nvarchar) AS categorize,
     (SELECT        Format(Activity.ActionDate, 'yyyy/MM/dd hh:mm tt') AS Expr1) AS StartTime,
     (SELECT        Format(DATEADD(mi, 30, Activity.ActionDate), 'yyyy/MM/dd hh:mm tt') AS Expr1) AS EndTime, dbo.fnUser_Name(Activity.LastUpdatedById) AS UpdatedByName,
     (SELECT        LEFT(Activity.Comment, 50) AS Expr1) AS ShortDescription,
     (SELECT        LEFT(Activity.Comment, 20) AS Expr1) AS VeryShortDescription, Activity.ValueId2, Activity.ValueId4,
	 Activity.[Transaction]
FROM            dbo.CRMSRVTicket_Comment AS Activity LEFT JOIN
dbo.GENPaymentMethods AS PaymentMethod ON Activity.PaymentMethodId= PaymentMethod.Id LEFT JOIN
dbo.GENCommentTypes AS activityType ON Activity.CommentTypeId = activityType.Id LEFT JOIN 
dbo.ActivityEmployees AS ActEmployee ON Activity.Id = ActEmployee.TicketCommentId LEFT JOIN
dbo.GENEmployees AS ActivityEmployee ON ActivityEmployee.Id = ActEmployee.EmployeeId LEFT JOIN
dbo.GENEmployees AS ManagerEmployee ON ActivityEmployee.EmployeeId = ManagerEmployee.Id LEFT JOIN
dbo.GENStatus AS ActivityStatus ON Activity.StatusId = ActivityStatus.Id  LEFT JOIN
dbo.GENStyles AS ActivityStatusStyle ON ActivityStatus.IconId = ActivityStatusStyle.Id LEFT JOIN
dbo.GENEmployees AS CreatorEmp ON Activity.CreatedById = CreatorEmp.UserId LEFT JOIN
dbo.GENStyles AS CommentStyle ON activityType.IconId = CommentStyle.Id LEFT JOIN
dbo.GENContacts AS MainContact ON Activity.MainContactId = MainContact.Id LEFT OUTER JOIN
dbo.CRMTickets ON Activity.CRMTicketId = dbo.CRMTickets.Id LEFT JOIN
dbo.CRMSRVTicketTypes ON dbo.CRMTickets.TicketTypeId = dbo.CRMSRVTicketTypes.Id LEFT JOIN
dbo.ItemFlatDatas ON Activity.ItemFlatDataId = dbo.ItemFlatDatas.Id LEFT JOIN
dbo.GENListValues AS Value1 ON Activity.ValueId1 = Value1.Id LEFT JOIN
dbo.GENListValues AS Value2 ON Activity.ValueId2 = Value2.Id LEFT JOIN
dbo.GENListValues AS Value3 ON Activity.ValueId3 = Value3.Id LEFT JOIN
dbo.GENListValues AS Value4 ON Activity.ValueId4 = Value4.Id LEFT JOIN
dbo.GENListValues AS Value5 ON Activity.ValueId5 = Value5.Id LEFT JOIN
dbo.GENPageOfPages AS POP ON POP.Id = Activity.PageofPagesId LEFT JOIN
dbo.GENBackendPages AS BackendPage ON POP.BackendPageId = BackendPage.Id
WHERE        (Activity.IsDeleted = 0) AND (Activity.CRMTicketId IS NOT NULL) AND (dbo.CRMTickets.IsDeleted = 0) OR
                         (Activity.IsDeleted = 0) AND (Activity.CRMTicketId IS NULL)


GO
