CREATE VIEW [dbo].[Contact_View_Rpt]
AS
/****** Script for SelectTopNRows command from SSMS  ******/
SELECT 
		 [GENContacts].Id,
       [GENContacts].[Name] AS Name,
       [GENContacts].[DateCreated]
      ,[GENContacts].[Disability] AS Birthdate
      ,[GENContacts].[String1] AS PlaceOfBirth
      ,Lang.Name AS Language
      ,[GENContacts].[String3] AS PositionDegree
      ,[GENContacts].[Position] AS Position
      ,[GENContacts].[String4] AS Company
      ,MaritalStatus.Name AS MaritalStatus
      ,[GENContacts].[DefaultAddress] AS DefaultAddress
      ,[GENContacts].[IDNumber] AS IDNumber
      ,[GENContacts].[String2] AS Qualifications
      ,[GENContacts].[DefaultPhone] AS Mobile
      ,[GENContacts].[Phone1]  AS WorkNumber
      ,[GENContacts].[Phone2]  AS HomeNumber
      ,[GENContacts].[DefaultEmail] AS DefaultEmail
      ,[GENContacts].[Description] AS ImportantCourse
      ,[GENContacts].[BloodPressure] AS Others,Qualification.Name AS QualificationName,[GENContacts].Qualification_Name,
	  dbo.getCurrentlVCRs(GENContacts.Id) AS CurrentVcrs,Gender.Name AS GenderName,[GENContacts].QualificationId,[GENContacts].GENderId ,
	  GENCountries.Name AS NationalityName,GENAddresses.CountryId,GENCompanyTypes.Name AS DestionationType,GENCompanyTypes.Id AS DestionationTypeId,[GENContacts].CompanyId
  FROM [dbo].[GENContacts]
  LEFT JOIN GENListValues Lang ON [GENContacts].LanguageId  = Lang.Id
  LEFT JOIN GENListValues MaritalStatus ON [GENContacts].MartialStatusId  = MaritalStatus.Id
  LEFT JOIN GENListValues Qualification ON [GENContacts].QualificationId  = Qualification.Id
  LEFT JOIN GENListValues Gender ON [GENContacts].GENderId  = Gender.Id
  LEFT JOIN GENAddresses  ON [GENContacts].Id  = GENAddresses.EntityId and GENAddresses.BaseEntityId=47
  LEFT JOIN GENCountries ON GENAddresses.CountryId=GENCountries.Id
  LEFT JOIN GENCompanies ON [GENContacts].CompanyId=GENCompanies.Id
  LEFT JOIN GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id
  WHERE [GENContacts].Isdeleted=0
GO
