CREATE VIEW [dbo].[Classroom_View_Rpt]
AS
SELECT   DISTINCT dbo.GENClassrooms.Id, dbo.GENClassrooms.InteractiveMeetingURL, dbo.GENClassrooms.InstructorInstructions, dbo.GENClassrooms.ExamStartTime, FORMAT(dbo.GENClassrooms.ExamStartTime, 'dd/MM/yyyy hh:mm tt') 
                         AS ExamStartTimeString, dbo.GENClassrooms.ExamEndTime, FORMAT(dbo.GENClassrooms.ExamEndTime, 'dd/MM/yyyy hh:mm tt') AS ExamEndTimeString, dbo.GENClassrooms.FromDateTime, 
                         FORMAT(dbo.GENClassrooms.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString, dbo.GENClassrooms.ToDateTime, FORMAT(dbo.GENClassrooms.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString, 
                         dbo.GENClassrooms.InteractiveMeetingDateTime, FORMAT(dbo.GENClassrooms.InteractiveMeetingDateTime, 'dd/MM/yyyy hh:mm tt') AS InteractiveMeetingDateTimeString, dbo.GENClassrooms.DisplayOrder, 
                         dbo.GENClassrooms.CourseId, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.Code, dbo.GENClassrooms.Name, dbo.GENClassrooms.Description, dbo.GENClassrooms.ColorCode, dbo.GENClassrooms.IsCheckedOut, 
                         dbo.GENClassrooms.DateCreated, dbo.GENClassrooms.DateUpdated, dbo.GENClassrooms.CheckinDate, dbo.GENClassrooms.CheckoutDate, dbo.GENClassrooms.ExpectedCheckoutDate, dbo.GENClassrooms.Timeout, 
                         dbo.GENClassrooms.DisplayOrdering, dbo.GENClassrooms.CreatedById, dbo.GENClassrooms.LastUpdatedById, dbo.GENClassrooms.CheckoutBy, dbo.GENClassrooms.String1, dbo.GENClassrooms.String2, 
                         dbo.GENClassrooms.String3, dbo.GENClassrooms.String4, dbo.GENClassrooms.String5, dbo.GENClassrooms.Int1, dbo.GENClassrooms.Int2, dbo.GENClassrooms.Int3, dbo.GENClassrooms.Int4, dbo.GENClassrooms.Int5, 
                         dbo.GENClassrooms.Long1, dbo.GENClassrooms.Long2, dbo.GENClassrooms.Long3, dbo.GENClassrooms.Long4, dbo.GENClassrooms.Long5, dbo.GENClassrooms.Float1, dbo.GENClassrooms.Float2, 
                         dbo.GENClassrooms.Float3, dbo.GENClassrooms.Float4, dbo.GENClassrooms.Float5, dbo.GENClassrooms.Decimal1, dbo.GENClassrooms.Decimal2, dbo.GENClassrooms.Decimal3, dbo.GENClassrooms.Decimal4, 
                         dbo.GENClassrooms.Decimal5, dbo.GENClassrooms.Bool1, dbo.GENClassrooms.Bool2, dbo.GENClassrooms.Bool3, dbo.GENClassrooms.Bool4, dbo.GENClassrooms.Bool5, dbo.GENClassrooms.Date1, 
                         dbo.GENClassrooms.Date2, dbo.GENClassrooms.Date3, dbo.GENClassrooms.Date4, dbo.GENClassrooms.Date5, dbo.GENClassrooms.ValueId1, dbo.GENClassrooms.ValueId2, dbo.GENClassrooms.ValueId3, 
                         dbo.GENClassrooms.ValueId4, dbo.GENClassrooms.ValueId5, dbo.GENClassrooms.IconId, dbo.GENClassrooms.IsActive, dbo.GENClassrooms.IsPublish, dbo.GENClassrooms.ExamId, 
                         dbo.GENEmployees.Name AS InstructorName, dbo.GENTypes.Name AS CourseName, dbo.GENTypes.Description AS CourseDescription, dbo.GENPollCategories.Name AS ExamName, 
						 dbo.GENClassrooms.ClassRoomStatus,(CASE WHEN dbo.GENClassrooms.ClassRoomStatus = 0 THEN N'Started-?? ?????' ELSE 
						 CASE WHEN dbo.GENClassrooms.ClassRoomStatus = 1 THEN N'Dropped-?? ??????' ELSE CASE WHEN dbo.GENClassrooms.ClassRoomStatus = 2 THEN N'Done-?????' ELSE N'' END END END) AS ClassRoomStatusString,
                         FORMAT(dbo.GENClassrooms.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, FORMAT(dbo.GENClassrooms.DateUpdated, 'dd/MM/yyyy') AS DateUpdatedString, dbo.GENClassrooms.LanguageId, 
                         dbo.GENListValues.Name AS LanguageName, dbo.GENListValues.ShortCode, GENContacts.Id AS StudentId,
						 GENContacts.Name AS StudentName, GENContacts.Code AS StudentCode, GENTypes.Code AS CourseCode, ExamHeaderResults.Id AS ExamHeaderId,
						 (CASE WHEN ISNULL([dbo].[ExamHeaderResults].[AnnouncedDegree], 0) = 0 THEN 
						 
						CASE WHEN (CAST((ISNULL([dbo].[ExamHeaderResults].[TotalExamScore],0) * ISNULL([dbo].[ExamHeaderResults].[ExamWeight], 0)) / [dbo].[ExamHeaderResults].TotalScore AS decimal(18,2))) IS NOT NULL
						THEN CAST((ISNULL([dbo].[ExamHeaderResults].[TotalExamScore],0) * ISNULL([dbo].[ExamHeaderResults].[ExamWeight], 0)) / [dbo].[ExamHeaderResults].TotalScore AS decimal(18,2))
						ELSE -1 END
						ELSE [dbo].[ExamHeaderResults].[AnnouncedDegree] END)
						AS AnnouncedDegree, ExamHeaderResults.ExamName AS ExamHeaderName, ExamHeaderResults.StartDateTime,ExamHeaderResults.EndtDateTime,
						ExamHeaderResults.ExamTime,
						COUNT(GENItems.Id) AS CountSessions,GENPollCategories.SuccessScore,
						 (CASE WHEN ISNULL([dbo].[ExamHeaderResults].[AnnouncedDegree], 0) = 0 THEN 
						CASE WHEN (CAST((ISNULL([dbo].[ExamHeaderResults].[TotalExamScore],0) * ISNULL([dbo].[ExamHeaderResults].[ExamWeight], 0)) / [dbo].[ExamHeaderResults].TotalScore AS decimal(18,2))) >= GENPollCategories.SuccessScore
						THEN 1 ELSE  0 END
						ELSE CASE WHEN [dbo].[ExamHeaderResults].[AnnouncedDegree] >= GENPollCategories.SuccessScore THEN 1 ELSE 0 END END) AS SuccessResult,
						 (CASE WHEN ISNULL([dbo].[ExamHeaderResults].[AnnouncedDegree], 0) = 0 THEN 
						CASE WHEN (CAST((ISNULL([dbo].[ExamHeaderResults].[TotalExamScore],0) * ISNULL([dbo].[ExamHeaderResults].[ExamWeight], 0)) / [dbo].[ExamHeaderResults].TotalScore AS decimal(18,2))) < GENPollCategories.SuccessScore
						THEN 1 ELSE  0 END
						ELSE CASE WHEN [dbo].[ExamHeaderResults].[AnnouncedDegree] < GENPollCategories.SuccessScore THEN 1 ELSE 0 END END) AS FailedResult,
						 (CASE WHEN ISNULL([dbo].[ExamHeaderResults].[AnnouncedDegree], 0) = 0 THEN 
						CASE WHEN CAST((((ISNULL([dbo].[ExamHeaderResults].[TotalExamScore],0) * ISNULL([dbo].[ExamHeaderResults].[ExamWeight], 0)) / [dbo].[ExamHeaderResults].TotalScore) / [dbo].[ExamHeaderResults].[ExamWeight]) * 100 AS decimal(18,2)) IS NOT NULL
						THEN
						CAST((((ISNULL([dbo].[ExamHeaderResults].[TotalExamScore],0) * ISNULL([dbo].[ExamHeaderResults].[ExamWeight], 0)) / [dbo].[ExamHeaderResults].TotalScore) / [dbo].[ExamHeaderResults].[ExamWeight]) * 100 AS decimal(18,2))
						ELSE  -1 END
						ELSE CAST(([dbo].[ExamHeaderResults].[AnnouncedDegree] / [dbo].[ExamHeaderResults].[ExamWeight]) *100 AS DECIMAL(18,2)) END)
						AS AnnouncedDegreePercentage, 
						(CASE WHEN [dbo].[ExamHeaderResults].StartDateTime IS NOT NULL AND [dbo].[ExamHeaderResults].EndtDateTime IS NOT NULL
						THEN DATEDIFF(MINUTE,[dbo].[ExamHeaderResults].StartDateTime,[dbo].[ExamHeaderResults].EndtDateTime) ELSE
						0 END) AS ExamDuration, GENContacts.ContactTypeId, GENContactTypes.Name AS ContactTypeName
FROM            dbo.GENClassrooms LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT OUTER JOIN
						 GENItems ON GENItems.TypeId = dbo.GENTypes.Id LEFT JOIN
                         dbo.GENPollCategories ON dbo.GENClassrooms.ExamId = dbo.GENPollCategories.Id LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT JOIN
						 GENClassroom_GENContact ON GENClassrooms.Id = GENClassroom_GENContact.ClassroomId LEFT JOIN 
						 GENContacts ON GENClassroom_GENContact.StudentId = GENContacts.Id LEFT JOIN
						 ExamHeaderResults ON GENClassrooms.ExamId = ExamHeaderResults.ExamId AND GENClassrooms.Id = ExamHeaderResults.ClassroomId 
						 AND GENContacts.Id = ExamHeaderResults.StudentId LEFT JOIN
						 GENContactTypes ON GENContacts.ContactTypeId = GENContactTypes.Id 
GROUP BY dbo.GENClassrooms.Id, dbo.GENClassrooms.InteractiveMeetingURL, dbo.GENClassrooms.InstructorInstructions, dbo.GENClassrooms.ExamStartTime,
                         dbo.GENClassrooms.FromDateTime, 
                         dbo.GENClassrooms.ToDateTime, 
                         dbo.GENClassrooms.InteractiveMeetingDateTime, dbo.GENClassrooms.DisplayOrder, 
                         dbo.GENClassrooms.CourseId, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.Code, dbo.GENClassrooms.Name, dbo.GENClassrooms.Description, dbo.GENClassrooms.ColorCode, dbo.GENClassrooms.IsCheckedOut, 
                         dbo.GENClassrooms.DateCreated, dbo.GENClassrooms.DateUpdated, dbo.GENClassrooms.CheckinDate, dbo.GENClassrooms.CheckoutDate, dbo.GENClassrooms.ExpectedCheckoutDate, dbo.GENClassrooms.Timeout, 
                         dbo.GENClassrooms.DisplayOrdering, dbo.GENClassrooms.CreatedById, dbo.GENClassrooms.LastUpdatedById, dbo.GENClassrooms.CheckoutBy, dbo.GENClassrooms.String1, dbo.GENClassrooms.String2, 
                         dbo.GENClassrooms.String3, dbo.GENClassrooms.String4, dbo.GENClassrooms.String5, dbo.GENClassrooms.Int1, dbo.GENClassrooms.Int2, dbo.GENClassrooms.Int3, dbo.GENClassrooms.Int4, dbo.GENClassrooms.Int5, 
                         dbo.GENClassrooms.Long1, dbo.GENClassrooms.Long2, dbo.GENClassrooms.Long3, dbo.GENClassrooms.Long4, dbo.GENClassrooms.Long5, dbo.GENClassrooms.Float1, dbo.GENClassrooms.Float2, 
                         dbo.GENClassrooms.Float3, dbo.GENClassrooms.Float4, dbo.GENClassrooms.Float5, dbo.GENClassrooms.Decimal1, dbo.GENClassrooms.Decimal2, dbo.GENClassrooms.Decimal3, dbo.GENClassrooms.Decimal4, 
                         dbo.GENClassrooms.Decimal5, dbo.GENClassrooms.Bool1, dbo.GENClassrooms.Bool2, dbo.GENClassrooms.Bool3, dbo.GENClassrooms.Bool4, dbo.GENClassrooms.Bool5, dbo.GENClassrooms.Date1, 
                         dbo.GENClassrooms.Date2, dbo.GENClassrooms.Date3, dbo.GENClassrooms.Date4, dbo.GENClassrooms.Date5, dbo.GENClassrooms.ValueId1, dbo.GENClassrooms.ValueId2, dbo.GENClassrooms.ValueId3, 
                         dbo.GENClassrooms.ValueId4, dbo.GENClassrooms.ValueId5, dbo.GENClassrooms.IconId, dbo.GENClassrooms.IsActive, dbo.GENClassrooms.IsPublish, dbo.GENClassrooms.ExamId, 
                         dbo.GENEmployees.Name, dbo.GENTypes.Name, dbo.GENTypes.Description, dbo.GENPollCategories.Name, 
						 dbo.GENClassrooms.ClassRoomStatus,
                         dbo.GENClassrooms.LanguageId, 
                         dbo.GENListValues.Name, dbo.GENListValues.ShortCode, GENContacts.Id,
						 GENContacts.Name, GENContacts.Code, GENTypes.Code, ExamHeaderResults.Id,
						 ExamHeaderResults.ExamName , ExamHeaderResults.StartDateTime,ExamHeaderResults.EndtDateTime,ExamHeaderResults.ExamTime,dbo.GENClassrooms.ExamEndTime,
						 [dbo].[ExamHeaderResults].TotalScore,[dbo].[ExamHeaderResults].AnnouncedDegree,[dbo].[ExamHeaderResults].ExamWeight,[dbo].[ExamHeaderResults].TotalExamScore,
						 GENPollCategories.SuccessScore,GENContacts.ContactTypeId, GENContactTypes.Name

GO
