						 FORMAT(dbo.GENCompanies.Date3, 'dd/MM/yyyy') AS Date3String,FORMAT(dbo.GENCompanies.Date4, 'dd/MM/yyyy') AS Date4String,FORMAT(dbo.GENCompanies.Date5, 'dd/MM/yyyy') AS Date5String,dbo.GENCompanies.Date2, dbo.GENCompanies.Date3, dbo.GENCompanies.Date4, dbo.GENCompanies.Date5, 
                         dbo.GENCompanies.ValueId1, dbo.GENCompanies.ValueId2, dbo.GENCompanies.ValueId3, dbo.GENCompanies.ValueId4, dbo.GENCompanies.ValueId5, dbo.GENCompanies.IconId, dbo.GENCompanies.StatusId,dbo.GENStatus.Name AS StatusName, 
                         dbo.GENCompanies.SLAId, dbo.GENCompanies.ExpectedCheckoutDate, dbo.GENCompanies.CRMSources_Name, dbo.GENCompanies.GENIndustries_Name, dbo.GENCompanies.GENCurrencies_Name, 
