CREATE VIEW [dbo].[Employee_View]
AS
SELECT        dbo.GENEmployees.Id, dbo.GENEmployees.FirstName, dbo.GENEmployees.SecondName, dbo.GENEmployees.ThirdName, dbo.GENEmployees.Image, dbo.GENEmployees.DepartmentId, dbo.GENEmployees.Address,
                         dbo.GENEmployees.Email, dbo.GENEmployees.Email As DEfaultEmail, dbo.GENEmployees.Telephone , dbo.GENEmployees.Telephone AS DefaultPhone, dbo.GENEmployees.SocialSecurityNumber, dbo.GENEmployees.Position, dbo.GENEmployees.ContactId, dbo.GENEmployees.EmployeeTypeId,
                         dbo.GENEmployees.BaseBranchId, dbo.GENEmployees.GraduationDate, dbo.GENEmployees.HiringDate, dbo.GENEmployees.BirthDate, dbo.GENEmployees.CRMSRVRequester_Id, dbo.GENEmployees.IsPublish,
                         dbo.GENEmployees.IsManager, dbo.GENEmployees.IsActive, dbo.GENEmployees.IsUser, dbo.GENEmployees.EmployeeCategoryId, dbo.GENEmployees.Fax, dbo.GENEmployees.Telephone2, dbo.GENEmployees.UserId,
                         dbo.GENEmployees.PassportNumber, dbo.GENEmployees.MultiSessionLogin, dbo.GENEmployees.Language1Id, dbo.GENEmployees.Language2Id, dbo.GENEmployees.LicenseExpire,FORMAT(dbo.GENEmployees.LicenseExpire, 'dd/MM/yyyy') AS LicenseExpireString, dbo.GENEmployees.SalutationId, dbo.GENEmployees.EmployeeId,
                         dbo.GENEmployees.GenderId, dbo.GENEmployees.MartialStatusId, dbo.GENEmployees.MilitaryStatusId, dbo.GENEmployees.ExtensionLong1, dbo.GENEmployees.GENCompany_Id, dbo.GENEmployees.ClassificationId,
                         dbo.GENEmployees.Code, dbo.GENEmployees.Name, dbo.GENEmployees.Description, dbo.GENEmployees.ColorCode, dbo.GENEmployees.IsCheckedOut, dbo.GENEmployees.DateCreated, dbo.GENEmployees.DateUpdated,
                         dbo.GENEmployees.CheckinDate, dbo.GENEmployees.CheckoutDate, dbo.GENEmployees.Timeout, dbo.GENEmployees.DisplayOrdering, dbo.GENEmployees.CreatedById, dbo.GENEmployees.LastUpdatedById,
                         dbo.GENEmployees.CheckoutBy, dbo.GENEmployees.String1, dbo.GENEmployees.String2, dbo.GENEmployees.String3, dbo.GENEmployees.String4, dbo.GENEmployees.String5, dbo.GENEmployees.Int1,
                         dbo.GENEmployees.Int2, dbo.GENEmployees.Int3, dbo.GENEmployees.Int4, dbo.GENEmployees.Int5, dbo.GENEmployees.Long1, dbo.GENEmployees.Long2, dbo.GENEmployees.Long3, dbo.GENEmployees.Long4,
                         dbo.GENEmployees.Long5, dbo.GENEmployees.Float1, dbo.GENEmployees.Float2, dbo.GENEmployees.Float3, dbo.GENEmployees.Float4, dbo.GENEmployees.Float5, dbo.GENEmployees.Decimal1,
                         dbo.GENEmployees.Decimal2, dbo.GENEmployees.Decimal3, dbo.GENEmployees.Decimal4, dbo.GENEmployees.Decimal5, dbo.GENEmployees.Bool1, dbo.GENEmployees.Bool2, dbo.GENEmployees.Bool3,
                         dbo.GENEmployees.Bool4, dbo.GENEmployees.Bool5, dbo.GENEmployees.Date1,FORMAT(dbo.GENEmployees.Date1, 'dd/MM/yyyy') AS Date1String,FORMAT(dbo.GENEmployees.Date2, 'dd/MM/yyyy') AS Date2String
						 ,FORMAT(dbo.GENEmployees.Date3, 'dd/MM/yyyy') AS Date3String,FORMAT(dbo.GENEmployees.Date4, 'dd/MM/yyyy') AS Date4String,FORMAT(dbo.GENEmployees.Date5, 'dd/MM/yyyy') AS Date5String ,dbo.GENEmployees.Date2, dbo.GENEmployees.Date3, dbo.GENEmployees.Date4, dbo.GENEmployees.Date5, dbo.GENEmployees.ValueId1,
                         dbo.GENEmployees.ValueId2, dbo.GENEmployees.ValueId3, dbo.GENEmployees.ValueId4, dbo.GENEmployees.ValueId5, dbo.GENEmployees.IconId, dbo.GENEmployees.KPI1, dbo.GENEmployees.KPI2,
                         dbo.GENEmployees.KPI3, dbo.GENEmployees.Benefit1, dbo.GENEmployees.Benefit2, dbo.GENEmployees.Benefit3, dbo.GENDepartments.Name AS DepartmentName, dbo.GENContacts.Name AS ContactName,
                         dbo.GENEmployeeTypes.Name AS EmployeeTypeName, dbo.GENBranches.Name AS BaseBranchName, dbo.GENEmployeeCategories.Name AS EmployeeCategoryName, dbo.GENCompanies.Name AS CompanyName,
                         dbo.GENClassifications.Name AS classificationName, dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENStyles.Name AS FontIcon, CONVERT(varchar, dbo.GENEmployees.DateCreated, 103) AS DateCreatedString,
                         FORMAT(dbo.GENEmployees.DateCreated, 'hh:mm tt') AS TimeCreatedString, dbo.GENEmployees.DateUpdated AS Expr2, CONVERT(varchar, dbo.GENEmployees.DateUpdated, 103) AS DateUpdatedString,
                         FORMAT(dbo.GENEmployees.DateUpdated, 'hh:mm tt') AS TimeUpdatedString, dbo.GENEmployees.ExpectedCheckoutDate, dbo.GENEmployees.UserNameMail, dbo.GENEmployees.IncomingMailServer,
                         dbo.GENEmployees.OutgoingMailServer, dbo.GENEmployees.PasswordMail, dbo.GENEmployees.IncomingMailPort, dbo.GENEmployees.OutgoingMailPort, dbo.GENEmployees.AccountEmailType,
                         dbo.GENEmployees.IncomigEncryption, dbo.GENEmployees.OutgoingEncryption, dbo.GENEmployees.DiscountLimitMax, dbo.GENContacts.Id AS Expr1, dbo.fnEmployee_NameById(dbo.GENEmployees.EmployeeId)
                         AS EmployeeName, dbo.fnListValue_ById(dbo.GENEmployees.Language1Id,NULL) AS language1Name, dbo.fnListValue_ById(dbo.GENEmployees.Language2Id,NULL) AS language2Name,
                         dbo.fnListValue_ById(dbo.GENEmployees.GenderId,NULL) AS GenderName, dbo.fnListValue_ById(dbo.GENEmployees.ValueId2,NULL) AS ValueId2tName, dbo.fnListValue_ById(dbo.GENEmployees.ValueId1,NULL) AS ValueId1tName,
                         CONVERT(varchar, dbo.GENEmployees.BirthDate, 103) AS BirthDateString, CONVERT(varchar, dbo.GENEmployees.HiringDate, 103) AS HiringDateString,GENEmployees.IsDeleted,
						 GENEmployees.Destination,GENEmployees.QualificationId,GENEmployees.IDNumber,GENEmployees.AccountNumber,dbo.GENListValues.Id as JobCategoryId
						 ,dbo.GENListValues.Name as JobCategoryName ,dbo.GENEmployees.AcceptJobPricing,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.Id ELSE GENEntityPricings.Id END) as GENEntityPricingId,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.Name ELSE GENEntityPricings.Name END) as PricingName,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.Price ELSE GENEntityPricings.Price END) as Price,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.NetPrice ELSE GENEntityPricings.NetPrice END) as NetPrice,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.DisocuntPerecentage ELSE GENEntityPricings.DisocuntPerecentage END) as DisocuntPerecentage,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.DisocuntAmount ELSE GENEntityPricings.DisocuntAmount END) as DisocuntAmount,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.CurrencyId ELSE GENEntityPricings.CurrencyId END) as CurrencyId,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.UnitId ELSE GENEntityPricings.UnitId END) as UnitId,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.RegionId ELSE GENEntityPricings.RegionId END) as RegionId,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.PriceType ELSE GENEntityPricings.PriceType END) as PriceType,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.PriceInstructorType ELSE GENEntityPricings.PriceInstructorType END) as PriceInstructorType,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.Note ELSE GENEntityPricings.Note END) as Note,
						 (CASE WHEN GENEmployees.AcceptJobPricing = 1 THEN wiki.LanguageId ELSE GENEntityPricings.LanguageId END) as LanguageId,
						 wiki.NetPrice as JobCategoryPricing,wiki.ValueId1 as JobCategoryValueId1,
						 (select top 1 TLMSClassroom_Session.Name from Classroom_Session_Instructor
						 inner join TLMSClassroom_Session on TLMSClassroom_Session.Id = Classroom_Session_Instructor.SessionId
						 where Classroom_Session_Instructor.InstructorId = dbo.GENEmployees.Id
						 order by TLMSClassroom_Session.SessionDateTime,TLMSClassroom_Session.FromDateTime
						 ) as LastSessionName

FROM                     dbo.GENEmployees LEFT OUTER JOIN
                         dbo.GENEmployeeCategories ON dbo.GENEmployees.EmployeeCategoryId = dbo.GENEmployeeCategories.Id LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENEmployees.LastUpdatedById = dbo.AspNetUsers.Id LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENEmployees.IconId = dbo.GENStyles.Id LEFT OUTER JOIN
                         dbo.GENClassifications ON dbo.GENEmployees.ClassificationId = dbo.GENClassifications.Id LEFT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENEmployees.GENCompany_Id = dbo.GENCompanies.Id LEFT OUTER JOIN
                         dbo.GENBranches ON dbo.GENEmployees.BaseBranchId = dbo.GENBranches.Id LEFT OUTER JOIN
                         dbo.GENEmployeeTypes ON dbo.GENEmployees.EmployeeTypeId = dbo.GENEmployeeTypes.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.GENEmployees.ContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENDepartments ON dbo.GENEmployees.DepartmentId = dbo.GENDepartments.Id LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENEmployees.JobCategoryId = dbo.GENListValues.Id LEFT OUTER JOIN
						 GENEntityPricings ON GENEntityPricings.EntityId = GENEmployees.id and GENEntityPricings.BaseEntityId = 55 LEFT JOIN
						 (select top 1 wikiPrice.*,GENListValues.Id as WikiId,GENListValues.ValueId1 from GENListValues
						 inner join  GENEntityPricings wikiPrice on wikiPrice.BaseEntityId = 30 and wikiPrice.EntityId = GENListValues.ValueId1 and wikiPrice.IsDefault = 1
                              ) wiki ON  wiki.WikiId = GENEmployees.JobCategoryId -- افترضت هنا مفتاح الربط هو InstructorId

