CREATE VIEW [dbo].[Activity_View]
AS
select DISTINCT Activity.[Id]
      ,Activity.[TicketId]
      ,Activity.[Color]
      ,Activity.[IsCancelledActivities]
      ,Activity.[IsNextActionsActivities]
      ,Activity.[IsPlannedActivities]
      ,Activity.[IsDoneActivities]
      ,Activity.[Comment]
      ,Activity.[Name]
      ,Activity.[CommentTypeId]
      ,Activity.[IsCancelled]
      ,Activity.[IsDeleted]
      ,Activity.[Reason]
      ,Activity.[DateCreated]
      ,Activity.[DateUpdated]
      ,Activity.[DateDeleted]
      ,Activity.[CreatedById]
      ,Activity.[DeletedById]
      ,Activity.[LastUpdatedById]
      ,Activity.[NextActionDate]
      ,Activity.[NextActionId]
      ,Activity.[PageofPagesId]
      ,Activity.[IsNextStep]
      ,Activity.[IsCompleted]
      ,Activity.[ActionDate]
      ,Activity.[NextStepDescription]
      ,Activity.[StatusId]
      ,Activity.[EntityId]
      ,Activity.[BaseEntityId]
      ,Activity.[NextActivityId]
      ,Activity.[ParentActivityId]
      ,Activity.[Day]
      ,Activity.[BaseEntityTo]
      ,Activity.[EntityIdTo]
      ,Activity.[IsRepeated]
      ,Activity.[ListValueId]
      ,Activity.[LastNotificationDate]
      ,Activity.[ExpiredDate]
      ,Activity.[DateFrom]
      ,Activity.[TimeFrom]
      ,Activity.[Dateto]
      ,Activity.[Timeto]
      ,Activity.[RepeatPeriodId]
      ,Activity.[SchedulerType]
      ,Activity.[NotificationType]
      ,Activity.[EventTypeId]
      ,Activity.[ActivtyTypeId]
      ,Activity.[Number]
      ,Activity.[RepeatNumber]
      ,Activity.[RepeatEndDate]
      ,Activity.[ActionTypeId]
      ,Activity.[CRMTicketId]
      ,Activity.[ItemId]
      ,Activity.[ItemFlatDataId]
      ,Activity.[MainContactId]
      ,Activity.[String1]
      ,Activity.[String2]
      ,Activity.[String3]
      ,Activity.[String4]
      ,Activity.[String5]
      ,Activity.[ValueId1]
      ,Activity.[ValueId2]
      ,Activity.[ValueId3]
      ,Activity.[ValueId4]
      ,Activity.[ValueId5]
      ,Activity.[FieldName]
      ,Activity.[PaymentMethodId]
      ,Activity.[OverDueDate]
      ,Activity.[Transaction],
Activity.Id AS Id2, 
CONVERT(varchar, Activity.DateCreated, 103) AS DateCreatedString, CONVERT(varchar, Activity.DateCreated, 108) AS TimeCreatedString, 
CONVERT(varchar, Activity.DateUpdated, 103) AS DateUpdatedString, CONVERT(varchar, Activity.DateUpdated, 108) AS TimeUpdatedString, 
Format(Activity.ActionDate, 'yyyy/MM/dd hh:mm tt') AS StartTime,
Format(DATEADD(mi, 30, Activity.ActionDate), 'yyyy/MM/dd hh:mm tt') AS EndTime, 
LEFT(Activity.Comment, 50) AS ShortDescription,
LEFT(Activity.Comment, 20) AS VeryShortDescription, 
FORMAT(Activity.ActionDate, 'dd/MM/yyyy hh:mm tt') AS ActionDateString, 
GENPaymentMethods.Name AS PaymentMethodName, 
GENEmployees.Id AS CreatedEmployeeId, GENEmployees.Name AS CreatedByName, GENEmployees.Image AS CreatedByImage,
ListValue1.Name AS ValueId1tName, 
ListValue2.Name AS ValueId2tName, 
ListValue3.Name AS ValueId3tName, 
ListValue4.Name AS ValueId4tName, 
ListValue5.Name AS ValueId5tName, 
MainContact.Id AS ContactId, 
MainContact.Name AS ActivityContactName, 
MainContact.Code AS ContactCode, 
MainContact.DefaultEmail AS ContactDefaultEmail, 
MainContact.Image AS ContactImage, 
MainContact.DefaultPhone AS ContactDefaultPhone, 
MainContact.DefaultAddress AS ContactDefaultAddress, 
MainContact.Name AS ContactName,
ActivityType.Name AS CommentTypeName, 
ActivityType.ColorCode AS CommentColor, 
ActivityTypeStyle.StyleValue AS CommentIcon,
ActivityTypeStyle.StyleValue AS ActivityIcon,
CAST(ActivityType.Id AS nvarchar) AS categorize,
NextActivityType.Name AS NextActionName,
ActivityStatus.ColorCode AS StatusColor, 
ActivityStatus.Name AS StatusName,
ActivityStatusStyle.StyleValue AS StatusIcon,
CRMTicket.OpenDate, UpdatedBy.Name AS UpdatedByName,
(CASE WHEN TicketType.Name IS NOT NULL THEN TicketType.Name ELSE CRMTicket.Name END) AS CRMTicketName,
(CASE WHEN dbo.ItemFlatDatas.PriceSales IS NOT NULL THEN dbo.ItemFlatDatas.PriceSales ELSE 0.0 END) AS Price,
dbo.GENBackendPages.DisplayName AS PageName,
dbo.fnEmployee_Name(Activity.Id) AS EmployeeName,
dbo.fnContactPerson_Name(Activity.Id) AS ContactPersonName,
PreviousActivityType.Name AS PreviousActionName,
dbo.fn_Activity_OverDue(Activity.Id, Activity.StatusId) AS IsOverDueActivities, 
dbo.fn_Activity_OverDue(Activity.Id, Activity.StatusId) AS IsOverDue

--dbo.fn_Activity_OverDue(Activity.Id, Activity.StatusId) AS IsOverDueActivities, 
--dbo.fn_Activity_OverDue(Activity.Id, Activity.StatusId) AS IsOverDue
FROM CRMSRVTicket_Comment Activity 
LEFT JOIN GENPaymentMethods ON GENPaymentMethods.Id = Activity.PaymentMethodId
LEFT JOIN GENEmployees ON GENEmployees.UserId = Activity.CreatedById
LEFT JOIN GENEmployees UpdatedBy ON UpdatedBy.UserId = Activity.LastUpdatedById
LEFT JOIN dbo.GENListValues ListValue1 ON Activity.ValueId1 = ListValue1.Id 
LEFT JOIN dbo.GENListValues ListValue2 ON Activity.ValueId2 = ListValue2.Id 
LEFT JOIN dbo.GENListValues ListValue3 ON Activity.ValueId3 = ListValue3.Id 
LEFT JOIN dbo.GENListValues ListValue4 ON Activity.ValueId4 = ListValue4.Id 
LEFT JOIN dbo.GENListValues ListValue5 ON Activity.ValueId5 = ListValue5.Id
LEFT JOIN dbo.GENContacts MainContact ON Activity.MainContactId = MainContact.Id
LEFT JOIN dbo.GENCommentTypes ActivityType ON Activity.CommentTypeId = ActivityType.Id
LEFT JOIN dbo.GENStyles ActivityTypeStyle ON ActivityType.IconId = ActivityTypeStyle.Id
LEFT JOIN dbo.GENCommentTypes NextActivityType ON Activity.NextActionId = NextActivityType.Id
LEFT JOIN dbo.GENStatus ActivityStatus ON Activity.StatusId = ActivityStatus.Id
LEFT JOIN dbo.GENStyles ActivityStatusStyle ON ActivityStatus.IconId = ActivityStatusStyle.Id
LEFT JOIN dbo.CRMTickets CRMTicket ON CRMTicket.Id = Activity.CRMTicketId
LEFT JOIN dbo.CRMSRVTicketTypes TicketType ON CRMTicket.TicketTypeId = TicketType.Id
LEFT JOIN dbo.ItemFlatDatas ON Activity.ItemFlatDataId = dbo.ItemFlatDatas.Id
LEFT JOIN dbo.GENPageOfPages ON Activity.PageofPagesId = dbo.GENPageOfPages.Id
LEFT JOIN dbo.GENBackendPages ON dbo.GENPageOfPages.BackendPageId = dbo.GENBackendPages.Id
LEFT JOIN dbo.CRMSRVTicket_Comment AS PreviousActivity ON PreviousActivity.Id = Activity.ParentActivityId
LEFT JOIN dbo.GENCommentTypes PreviousActivityType ON PreviousActivity.CommentTypeId = PreviousActivityType.Id
WHERE        (Activity.IsDeleted = 0) AND ((Activity.CRMTicketId IS NOT NULL AND CRMTicket.IsDeleted = 0) OR Activity.CRMTicketId IS NULL)

