GO


CREATE VIEW [dbo].[ActivityStatus_View]
AS
select DISTINCT Activity.*,Activity.Id AS Id2, 
CONVERT(varchar, Activity.DateCreated, 103) AS DateCreatedString, CONVERT(varchar, Activity.DateCreated, 108) AS TimeCreatedString, 
CONVERT(varchar, Activity.DateUpdated, 103) AS DateUpdatedString, CONVERT(varchar, Activity.DateUpdated, 108) AS TimeUpdatedString, 
Format(Activity.ActionDate, 'yyyy/MM/dd hh:mm tt') AS StartTime,
Format(DATEADD(mi, 30, Activity.ActionDate), 'yyyy/MM/dd hh:mm tt') AS EndTime, 
LEFT(Activity.Comment, 50) AS ShortDescription,
LEFT(Activity.Comment, 20) AS VeryShortDescription, 
FORMAT(Activity.ActionDate, 'dd/MM/yyyy hh:mm tt') AS ActionDateString, 
GENEmployees.Id AS CreatedEmployeeId, GENEmployees.Name AS CreatedByName, GENEmployees.Image AS CreatedByImage
FROM CRMSRVTicket_Comment Activity 
LEFT JOIN GENEmployees ON GENEmployees.UserId = Activity.CreatedById
LEFT JOIN dbo.CRMTickets CRMTicket ON CRMTicket.Id = Activity.CRMTicketId

WHERE        (Activity.IsDeleted = 0) AND ((Activity.CRMTicketId IS NOT NULL AND CRMTicket.IsDeleted = 0) OR Activity.CRMTicketId IS NULL)
GO
