                         [dbo].[GENTypes] ON [dbo].[GENItems].TypeId = [dbo].[GENTypes].Id LEFT JOIN
						   [dbo].[GENCountries] ON [dbo].[GENItems].OriginId = [dbo].[GENCountries].Id LEFT JOIN
						      [dbo].[GENContacts] ON [dbo].[GENContacts].ContactId = [dbo].[GENContacts].Id LEFT JOIN
                         [dbo].[GENStyles] AS TypeIconStyle ON [dbo].[GENTypes].IconId = TypeIconStyle.Id LEFT JOIN
                         [dbo].[GENListValues] ON [dbo].[GENItems].ExtListValue1Id = [dbo].[GENListValues].Id LEFT JOIN
                         [dbo].[GENStyles] AS ExtIconStyle ON [dbo].[GENListValues].IconId = ExtIconStyle.Id LEFT JOIN
                         [dbo].[GENProjects] ON [dbo].[GENItems].ProjectId = [dbo].[GENProjects].Id LEFT JOIN
                         [dbo].[GENBrands] ON [dbo].[GENItems].BrandId = [dbo].[GENBrands].Id LEFT JOIN
                         [dbo].[GENCompanies] ON [dbo].[GENItems].CompanyId = [dbo].[GENCompanies].Id LEFT JOIN
                         [dbo].[AspNetUsers] ON [dbo].[GENItems].LastUpdatedById = [dbo].[AspNetUsers].Id LEFT JOIN
						 GENClassifications ON GENItems.ClassificationId =GENClassifications.Id 
						 --LEFT JOIN
						
                         --[dbo].[GENItemCategory_Item] ON [dbo].[GENItems].Id = [dbo].[GENItemCategory_Item].ItemId CROSS APPLY[dbo].[tfn_CategoryParentAndGrandById]([dbo].[GENItemCategory_Item].ItemCategoryId) CatGrand left join
						 --dbo.GENItemCategories ON  dbo.GENItemCategory_Item.ItemCategoryId= dbo.GENItemCategories.Id
GO
