                         dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENListValues.Name AS TypeName, dbo.GENStyles.StyleValue AS TypeIcon, dbo.GENListValues.ColorCode AS TypeColor, 
                         dbo.fn_LastActivityStatus_ByEntityandBaseEntityId(dbo.GENCompanies.Id, 158) AS ActivityType, dbo.fn_LastActionType_ByEntityandBaseEntityId(dbo.GENCompanies.Id, 158) AS ActivityAction, 
                         dbo.fn_Company_CompanyDealCount(dbo.GENCompanies.Id) AS DealCount, dbo.fn_Company_CompanyLeadCount(dbo.GENCompanies.Id) AS LeadCount, dbo.fn_Company_CompanyItemCount(dbo.GENCompanies.Id) 
                         AS ItemCount, dbo.fn_LastDealStatus_ByCompanyId(dbo.GENCompanies.Id) AS LastDealStatus, dbo.GENCompanies.DateCreated AS Expr1, CONVERT(varchar, dbo.GENCompanies.DateCreated, 103) AS DateCreatedString, 
                         CONVERT(varchar, dbo.GENCompanies.DateCreated, 108) AS TimeCreatedString, dbo.GENCompanies.DateUpdated AS Expr2, CONVERT(varchar, dbo.GENCompanies.DateUpdated, 103) AS DateUpdatedString, 
                         CONVERT(varchar, dbo.GENCompanies.DateUpdated, 108) AS TimeUpdatedString, dbo.fn_Company_AccountItemCount(dbo.GENCompanies.Id) AS AccountItemCount
FROM            dbo.GENCompanyTypes RIGHT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENCompanyTypes.Id = dbo.GENCompanies.CompanyTypeId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENCompanies.ResponsiblePersonId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.GENIndustries ON dbo.GENCompanies.IndustryId = dbo.GENIndustries.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.GENCompanies.MainContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENListValues LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENListValues.IconId = dbo.GENStyles.Id ON dbo.GENCompanies.ValueId1 = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENCompanies.LastUpdatedById = dbo.AspNetUsers.Id
GO
