                         dbo.GENPolls.DisplayOrdering, dbo.GENPolls.CreatedById, dbo.GENPolls.LastUpdatedById, dbo.GENPolls.CheckoutBy, dbo.GENPolls.String1, dbo.GENPolls.String2, dbo.GENPolls.String3, dbo.GENPolls.String4, 
                         dbo.GENPolls.String5, dbo.GENPolls.Int1, dbo.GENPolls.Int2, dbo.GENPolls.Int3, dbo.GENPolls.Int4, dbo.GENPolls.Int5, dbo.GENPolls.Long1, dbo.GENPolls.Long2, dbo.GENPolls.Long3, dbo.GENPolls.Long4, 
