                         dbo.GENPolls.Date4, dbo.GENPolls.Date5, dbo.GENPolls.ValueId1, dbo.GENPolls.ValueId2, dbo.GENPolls.ValueId3, dbo.GENPolls.ValueId4, dbo.GENPolls.ValueId5, dbo.GENPolls.IconId, dbo.GENPolls.ExpectedCheckoutDate, 
                         dbo.GENPolls.MinAnsNumber, dbo.GENPolls.MaxAnsNumber, dbo.GENPolls.Time, dbo.GENPolls.Weight, dbo.GENPolls.QuestionType, dbo.GENPolls.Video, dbo.GENPolls.Audio, dbo.GENPolls.[File], dbo.GENPolls.IsCheckList, 
