                         AS CountQuestions, dbo.GenRoles.RoleId, dbo.GenRoles.IsEdit, (CASE WHEN dbo.GenRoles.IsMove IS NOT NULL THEN dbo.GenRoles.IsMove ELSE CAST(0 AS bit) END) AS IsMove, dbo.GenRoles.IsReadOnly
						 ,dbo.GENPollCategories.ExamType,(case when dbo.GENPollCategories.ExamType = 0 then N'FinalExam' when dbo.GENPollCategories.ExamType = 1 then N'MidExam'
						 when dbo.GENPollCategories.ExamType = 2 then N'Quiz' when dbo.GENPollCategories.ExamType = 3 then N'Exercise' 
