                         dbo.GENPollCategories.Float5, dbo.GENPollCategories.Decimal3, dbo.GENPollCategories.Decimal1, dbo.GENPollCategories.Decimal2, dbo.GENPollCategories.Decimal4, dbo.GENPollCategories.Decimal5, 
                         dbo.GENPollCategories.Bool1, dbo.GENPollCategories.Bool2, dbo.GENPollCategories.Bool3, dbo.GENPollCategories.Bool4, dbo.GENPollCategories.Date1, dbo.GENPollCategories.Date2, dbo.GENPollCategories.Bool5, 
                         dbo.GENPollCategories.Date3, dbo.GENPollCategories.Date4, dbo.GENPollCategories.Date5, dbo.GENPollCategories.ValueId1, dbo.GENPollCategories.ValueId2, dbo.GENPollCategories.ValueId3, 
