/****** Object:  View [dbo].[VW_Employee_CRMTicket_Dashboard]    Script Date: 7/1/2026 10:44:57 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[VW_Employee_CRMTicket_Dashboard]
AS
SELECT dbo.AspNetUsers.Name, 
	   AuditLogs.EventDateUTC AS ActivityDate, 
	   dbo.GENEmployees.ColorCode, 
	   dbo.GENEmployees.Image, 
	   dbo.GENEmployees.Id,
	   CAST(COUNT(dbo.CRMTickets.Id) AS bigint) AS TotalCountCreated,
	   CAST(COUNT(LastTickets.Id) AS bigint) AS CountCreated
FROM  dbo.AspNetUsers LEFT JOIN
      dbo.GENEmployees ON dbo.AspNetUsers.Id = dbo.GENEmployees.UserId LEFT JOIN
      dbo.CRMTickets ON dbo.AspNetUsers.Id = dbo.CRMTickets.CreatedById LEFT JOIN
      dbo.CRMTickets AS LastTickets ON dbo.AspNetUsers.Id = LastTickets.CreatedById AND CAST(LastTickets.DateCreated AS date) = CAST(GETDATE() AS date)  OUTER APPLY
	  (SELECT TOP 1 * FROM dbo.AuditLogs WHERE dbo.AuditLogs.UserName = dbo.AspNetUsers.UserName ORDER BY EventDateUTC DESC) as AuditLogs
	  WHERE dbo.GENEmployees.IsPublish = 1
GROUP BY dbo.AspNetUsers.Name, 
	   AuditLogs.EventDateUTC, 
	   dbo.GENEmployees.ColorCode, 
	   dbo.GENEmployees.Image, 
	   dbo.AspNetUsers.Id, dbo.GENEmployees.Id
GO
