/****** Object:  View [dbo].[Work_Order_View]    Script Date: 7/1/2026 10:44:57 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[Work_Order_View]
AS
SELECT        dbo.TCRWorkOrders.Id, dbo.TCRWorkOrders.Name, dbo.TCRWorkOrders.TypeName, dbo.TCRWorkOrders.TypeId, dbo.TCRWorkOrders.TCRId, dbo.TCRWorkOrders.CreatedDate, dbo.TCRWorkOrders.CreatedBy, 
                         dbo.TCRWorkOrders.TotalItemPrice, dbo.TCRWorkOrders.TotalPrice, dbo.TCRWorkOrders.CC, dbo.TCRWorkOrders.[To], dbo.TCRWorkOrders.TypeFunction, dbo.TCRWorkOrders.NumberOfPerson, dbo.TCRWorkOrders.Guranted, 
                         dbo.TCRWorkOrders.PaymentDetails, dbo.TCRWorkOrders.String1, dbo.TCRWorkOrders.String2, dbo.TCRWorkOrders.String3, dbo.TCRWorkOrders.String4, dbo.TCRWorkOrders.String5, dbo.TCRWorkOrders.PaymentMethod, 
                         dbo.TCRWorkOrders.FI, dbo.TCRWorkOrders.PricePerson, dbo.TCRWorkOrders.RichContent, dbo.GENTCRs.Name AS BillName, dbo.CRMDeals.Name AS DealName, dbo.CRMQuotes.Name AS QuoteName, 
                         dbo.GENEmployees.Id AS EmployeeId, dbo.GENEmployees.Name AS CreatedByName, CONVERT(varchar, dbo.TCRWorkOrders.CreatedDate, 103) AS CreatedDateString, CONVERT(varchar, dbo.TCRWorkOrders.CreatedDate, 
                         108) AS CreatedTimeString
FROM            dbo.GENEmployees RIGHT OUTER JOIN
                         dbo.TCRWorkOrders ON dbo.GENEmployees.UserId = dbo.TCRWorkOrders.CreatedBy LEFT OUTER JOIN
                         dbo.CRMQuotes RIGHT OUTER JOIN
                         dbo.CRMDeals RIGHT OUTER JOIN
                         dbo.GENTCRs ON dbo.CRMDeals.Id = dbo.GENTCRs.DealId ON dbo.CRMQuotes.Id = dbo.CRMDeals.QuoteId ON dbo.TCRWorkOrders.TCRId = dbo.GENTCRs.Id
GO
