CREATE VIEW [dbo].[GENTalents_View]
AS
SELECT   dbo.GENTalents.*,FORMAT(dbo.GENTalents.DateCreated, 'dd/MM/yyyy') AS DateCreatedString
          ,FORMAT(dbo.GENTalents.DateUpdated, 'dd/MM/yyyy') AS DateUpdatedString
		  ,FORMAT(dbo.GENTalents.DateCreated, 'hh:mm tt') AS TimeCreatedString
		  ,FORMAT(dbo.GENTalents.DateUpdated, 'hh:mm tt') AS TimeUpdatedString
		  ,FORMAT(dbo.GENTalents.FromDateTime, 'dd/MM/yyyy') AS FromDateTimeString
		  ,FORMAT(dbo.GENTalents.ToDateTime, 'dd/MM/yyyy') AS ToDateTimeString
		  ,dbo.GENTalentBuilders.Name as TalentBuilderName
FROM dbo.GENTalents
left join dbo.GENTalentBuilders on dbo.GENTalentBuilders.Id = dbo.GENTalents.TalentBuilderId
