/****** Object:  StoredProcedure [dbo].[ChkOnRatingByClassroomAndContact]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create proc [dbo].[ChkOnRatingByClassroomAndContact]
@contactId bigint,
@ClassId bigint
as
begin
select dbo.[AllRatingVCRLecture](@contactId,@ClassId) as AllRatingVCRLecture,dbo.[AllRatingVCRLectureInstructor](@contactId,@ClassId) as AllRatingVCRLectureInstructor
end
GO
/****** Object:  StoredProcedure [dbo].[Contact_Create]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Contact_Create] (@ContactId bigint)
as
INSERT
INTO ContactInfoes(
      [ContactId]
      ,[CountryName]
      ,[ProvinceName]
      ,[GovernrateName]
      ,[Address]
      ,[NoOfTickets]
      ,[AmountPaid]
      ,[Phone]
      ,[RoleName]
	  ,[LastUpdatedByName]
      ,[CreatedByName]
      ,[SourceName]
      ,[ContactCategoryName]
      ,[CompanyName]
      ,[StatusName]
      ,[ContactReferralName]
      ,[ReferrarEmail]
      ,[ReferrarPhone]
      ,[FontIcon]
      ,[AssessmentName]
      ,[PriortyName]
      ,[ContactTypeName]
      ,[ResponsiblePersonName]
      ,[SalutationName]
      ,[LastDealStatus]
      ,[ActivityType]
      ,[DealCount]
	  ,[DateCreatedString]
	  ,[DateUpdatedString])

SELECT @ContactId,
		dbo.fnContact_CountryString(@ContactId), 
		dbo.fnContact_ProvinceString(@ContactId),
		dbo.fnContact_GovernorateString(@ContactId), 
		dbo.fnContact_AddressString(@ContactId), 
		dbo.fnContact_TicketCount(@ContactId), 
	   dbo.fnContact_TicketAmountPaid(@ContactId), 
	   dbo.fnContact_PhoneString(@ContactId), 
	   [dbo].[fnContactRoleName_ByContactId](@ContactId), 
	   dbo.AspNetUsers.Name,
	   CreatedBy.Name, 
	   [dbo].[CRMSources].Name,
	   dbo.GENContactCategories.Name,
	   dbo.GENCompanies.Name,
	   dbo.GENStatus.Name,
	   Referral.Name,
	   Referral.DefaultEmail,
	   Referral.DefaultPhone, 
	   GENStyles.StyleValue,
	   Assessment.Name,
	   [Priority].Name,
	   dbo.GENContactTypes.Name, 
	   dbo.GENEmployees.Name,
	   dbo.GENSalutations.Name,
	   dbo.fnLastDealStatus_ByContactId(@ContactId),
	   dbo.fnLastActivityStatus_ByContactId(dbo.GENContacts.Id),
	   dbo.fnContact_ContactDealCount(@ContactId),
	   CONVERT(varchar,dbo.GENContacts.DateCreated, 103),
	   CONVERT(varchar,dbo.GENContacts.DateUpdated, 103)
	   FROM dbo.GENContacts LEFT JOIN
		dbo.AspNetUsers ON dbo.GENContacts.LastUpdatedById = dbo.AspNetUsers.Id LEFT JOIN
		dbo.AspNetUsers AS CreatedBy ON dbo.GENContacts.CreatedById = CreatedBy.Id LEFT JOIN
		[dbo].[CRMSources] ON dbo.GENContacts.SourceId = [dbo].[CRMSources].Id LEFT JOIN
		dbo.GENContactCategories ON dbo.GENContacts.ContactCategoryId = dbo.GENContactCategories.Id LEFT JOIN
        dbo.GENCompanies ON dbo.GENContacts.CompanyId = dbo.GENCompanies.Id LEFT JOIN
		dbo.GENStatus ON dbo.GENContacts.StatusId = dbo.GENStatus.Id LEFT JOIN
        dbo.GENContacts AS Referral ON dbo.GENContacts.ReferralId = Referral.Id LEFT JOIN
		GENListValues AS Assessment ON dbo.GENContacts.AssessmentId = Assessment.Id LEFT JOIN
		GENListValues AS [Priority] ON dbo.GENContacts.PriortyId = [Priority].Id LEFT JOIN
		GENListValues AS Gender ON dbo.GENContacts.GenderId = Gender.Id LEFT JOIN
		GENStyles ON Gender.IconId = GENStyles.Id LEFT JOIN
        dbo.GENContactTypes ON dbo.GENContacts.ContactTypeId = dbo.GENContactTypes.Id LEFT JOIN
		dbo.GENEmployees ON dbo.GENContacts.ResponsiblePersonId = dbo.GENEmployees.Id LEFT JOIN
        dbo.GENSalutations ON dbo.GENContacts.SalutationId = dbo.GENSalutations.Id
		WHERE dbo.GENContacts.Id = @ContactId
GO
