CREATE proc [dbo].[Contact_InsertNotExistType](@userId nvarchar(128))
 
 as
INSERT INTO GENTypes (Name, IsActive, IsPublish,IsCheckedOut, DateCREATED, DATEUPDATED,CheckoutDate,Timeout,CreatedById ,LastUpdatedById)
SELECT distinct  TypeString, 1,0,0, GETDATE(), GetDATE(),GetDATE(),0,@userId,@userId
