/****** Object:  StoredProcedure [dbo].[Contact_UpateById]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Contact_UpateById] (@ContactId bigint)
as
DECLARE @Count bigint
SELECT @Count = COUNT(Id) FROM ContactInfoes WHERE ContactId = @ContactId;
if(@Count > 0)
BEGIN
MERGE INTO ContactInfoes
   USING (
          SELECT dbo.GENContacts.Id AS ContactId,
		dbo.fnContact_CountryString(@ContactId) As CountryName, 
		dbo.fnContact_ProvinceString(@ContactId) AS ProvinceName,
		dbo.fnContact_GovernorateString(@ContactId) AS GovernrateName, 
		dbo.fnContact_AddressString(@ContactId) AS AddressName, 
		dbo.fnContact_TicketCount(@ContactId) AS TicketCount, 
	   dbo.fnContact_TicketAmountPaid(@ContactId) AS TicketAmounPaid, 
	   dbo.fnContact_PhoneString(@ContactId) AS Phone, 
	   [dbo].[fnContactRoleName_ByContactId](@ContactId) AS RoleName, 
	   dbo.AspNetUsers.Name AS LastUpdatedByName,
	   CreatedBy.Name AS CreatedByName, 
	   [dbo].[CRMSources].Name AS SourceName,
	   dbo.GENContactCategories.Name AS ContactCategoryName,
	   dbo.GENCompanies.Name AS CompanyName,
	   dbo.GENStatus.Name AS StatusName,
	   Referral.Name AS ReferralName,
	   Referral.DefaultEmail AS ReferralDefaultEmail,
	   Referral.DefaultPhone AS ReferralDefaultPhone, 
	   GENStyles.StyleValue AS FontIcon,
	   Assessment.Name AS AssessmentName,
	   [Priority].Name AS PriorityName,
	   dbo.GENContactTypes.Name AS ContactTypeName, 
	   dbo.GENEmployees.Name AS ResponsibleName,
	   dbo.GENSalutations.Name AS SalutationName,
	   dbo.fnLastDealStatus_ByContactId(@ContactId) AS LastDealStatus,
	  
	   dbo.fnLastActivityStatus_ByContactId(dbo.GENContacts.Id) AS LastActivityStatus,
	  
	   dbo.fnContact_ContactDealCount(@ContactId) AS DealCount,
	   dbo.GENContacts.DateCreated AS DateCreated,
	   dbo.GENContacts.DateUpdated AS DateUpdated
	   FROM dbo.GENContacts LEFT JOIN
		dbo.AspNetUsers ON dbo.GENContacts.LastUpdatedById = dbo.AspNetUsers.Id LEFT JOIN
		dbo.AspNetUsers AS CreatedBy ON dbo.GENContacts.CreatedById = CreatedBy.Id LEFT JOIN
		[dbo].[CRMSources] ON dbo.GENContacts.SourceId = [dbo].[CRMSources].Id LEFT JOIN
		dbo.GENContactCategories ON dbo.GENContacts.ContactCategoryId = dbo.GENContactCategories.Id LEFT JOIN
        dbo.GENCompanies ON dbo.GENContacts.CompanyId = dbo.GENCompanies.Id LEFT JOIN
		dbo.GENStatus ON dbo.GENContacts.StatusId = dbo.GENStatus.Id LEFT JOIN
        dbo.GENContacts AS Referral ON dbo.GENContacts.ReferralId = Referral.Id LEFT JOIN
		GENListValues AS Assessment ON dbo.GENContacts.AssessmentId = Assessment.Id LEFT JOIN
		GENListValues AS [Priority] ON dbo.GENContacts.PriortyId = [Priority].Id LEFT JOIN
		GENListValues AS Gender ON dbo.GENContacts.GenderId = Gender.Id LEFT JOIN
		GENStyles ON Gender.IconId = GENStyles.Id LEFT JOIN
        dbo.GENContactTypes ON dbo.GENContacts.ContactTypeId = dbo.GENContactTypes.Id LEFT JOIN
		dbo.GENEmployees ON dbo.GENContacts.ResponsiblePersonId = dbo.GENEmployees.Id LEFT JOIN
        dbo.GENSalutations ON dbo.GENContacts.SalutationId = dbo.GENSalutations.Id
		WHERE dbo.GENContacts.Id = @ContactId
         ) Contact
      ON ContactInfoes.ContactId = Contact.ContactId
WHEN MATCHED THEN
   UPDATE 
      SET [CountryName] = Contact.CountryName
      ,[ProvinceName] = Contact.ProvinceName
      ,[GovernrateName] = Contact.GovernrateName
      ,[Address] = Contact.AddressName
      ,[NoOfTickets] = Contact.TicketCount
      ,[AmountPaid] = Contact.TicketAmounPaid
      ,[Phone] = Contact.Phone
      ,[RoleName] = Contact.RoleName
      ,[LastUpdatedByName] = Contact.LastUpdatedByName
      ,[CreatedByName] = Contact.CreatedByName
      ,[SourceName] = Contact.SourceName
      ,[ContactCategoryName] = Contact.ContactCategoryName
      ,[CompanyName] = Contact.CompanyName
      ,[StatusName] = Contact.StatusName
      ,[ContactReferralName] = Contact.ReferralName
      ,[ReferrarEmail] = Contact.ReferralDefaultEmail
      ,[ReferrarPhone] = Contact.ReferralDefaultPhone
      ,[FontIcon] = Contact.FontIcon
      ,[AssessmentName] = Contact.AssessmentName
      ,[PriortyName] = Contact.PriorityName
      ,[ContactTypeName] = Contact.ContactTypeName
      ,[ResponsiblePersonName] = Contact.ResponsibleName
      ,[SalutationName] = Contact.SalutationName
      ,[LastDealStatus] = Contact.LastDealStatus
    
      ,[ActivityType] = Contact.LastActivityStatus
      
      ,[DealCount] = Contact.DealCount
      ,[DateCreatedString] = CONVERT(varchar,Contact.DateCreated, 103)
      ,[DateUpdatedString] = CONVERT(varchar,Contact.DateUpdated, 103);
--UPDATE
--    ContactInfoes
--SET
--    GovernrateName = dbo.fnContact_GovernorateString(@ContactId),
--	ProvinceName = dbo.fnContact_ProvinceString(@ContactId),
--    CountryName = dbo.fnContact_CountryString(@ContactId),
--    Address = dbo.fnContact_AddressString(@ContactId),
--    NoOfTickets = dbo.fnContact_TicketCount(@ContactId),
--    AmountPaid = dbo.fnContact_TicketAmountPaid(@ContactId),
--    Phone = dbo.fnContact_PhoneString(@ContactId)
--FROM
--    ContactInfoes
--WHERE
--    ContactInfoes.ContactId = @ContactId
END
ELSE
BEGIN
exec [dbo].[Contact_Create] @ContactId
END
GO
