CREATE PROCEDURE [dbo].[ForwardChatMessage]
	-- Add the parameters for the stored procedure here
	@MessageId BIGINT,
	@SenderId NVARCHAR(MAX),
	@ReceiverId NVARCHAR(MAX),
	@IsReceived BIT,
	@IsSeen Bit,
	@BaseEntityId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @MessageInserted BIGINT
    -- Insert statements for procedure here
	INSERT INTO [dbo].[GENChatMessages]
           ([MessageTime] ,[UserSenderId] ,[UserReceiverId] ,[MessageText] ,[TicketId] ,[IsReceived] ,[IsSeen] ,[ChatEntityUrl] ,[ChatEntityPoPId]
           ,[ChatEntityId] ,[IsSenderDeleted] ,[IsReceiverDeleted] ,[IsForwarded] ,[OriginalMessageId] ,[IsReply])
     SELECT 
           GETDATE() ,@SenderId ,@ReceiverId ,GENChatMessages.MessageText ,GENChatMessages.TicketId ,@IsReceived ,@IsSeen ,GENChatMessages.ChatEntityUrl ,GENChatMessages.ChatEntityPoPId
           ,GENChatMessages.ChatEntityId ,0 ,0 ,1 ,GENChatMessages.Id ,0
		   FROM GENChatMessages Where Id = @MessageId;

SELECT @MessageInserted = SCOPE_IDENTITY();

INSERT INTO [dbo].[GENImages]
           ([Name] ,[Description] ,[AzureUri] ,[DisplayOrder] ,[IsPublish] ,[IsActive] ,[DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById]
           ,[IsDefault] ,[IsDay] ,[IsRange] ,[Day] ,[From] ,[To] ,[EntityId] ,[BaseEntityId] ,[ImageTypeId])
     SELECT 
	 [Name] ,[Description] ,[AzureUri] ,[DisplayOrder] ,[IsPublish] ,[IsActive] ,GETDATE() ,GETDATE() ,@SenderId ,@SenderId ,[IsDefault] ,[IsDay]
           ,[IsRange] ,[Day] ,[From] ,[To] ,@MessageInserted ,[BaseEntityId]
           ,[ImageTypeId] FROM GENImages 
	WHERE EntityId = @MessageId AND BaseEntityId = @BaseEntityId;
INSERT INTO [dbo].[GENFiles]
           ([FileName] ,[AzureUri] ,[DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById] ,[EntityId] ,[BaseEntityId] ,[DisplayOrder] ,[Description] ,[LanguageId])
     SELECT [FileName] ,[AzureUri] ,GETDATE() ,GETDATE() ,@SenderId ,@SenderId ,@MessageInserted ,[BaseEntityId] ,[DisplayOrder] ,[Description]
           ,[LanguageId] FROM GENFiles 
		   WHERE EntityId = @MessageId AND BaseEntityId = @BaseEntityId;

SELECT @MessageInserted;
END
GO
/****** Object:  StoredProcedure [dbo].[GENPolls_SelectAll]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[GENPolls_SelectAll]   -- GENPolls_SelectAll 37,null
@CourseId bigint=null,
@LanguageId bigint=null,
@ExamId bigint=null
as
begin
DECLARE @ProsectionId int=NULL
IF @ExamId IS NOT NULL   
BEGIN
SELECT @ProsectionId=ProsecutionId from GENPollCategories where Id=@ExamId
END 
SELECT 
                 GENPolls.Id,
                 GENPolls.Description,
                 GENPolls.Question,
                 GENPolls.Image,
                 GENPolls.IsActive,
                 GENPolls.IsUsed,
				(case GENPolls.LevelQuestions when 1 then 'Easy' when 2 then 'Medium' when 3 then 'High'
				when 4 then 'Distinct' else null end) as  LevelOfQuestionName,
				GENPolls.LevelQuestions,
                GENPolls.IsPublish,
                GENPolls.DisplayOrder,
                GENPolls.DateCreated,
				FORMAT(GENPolls.DateCreated,'dd/MM/yyyy')as DateCreatedString,
				FORMAT(GENPolls.DateUpdated,'dd/MM/yyyy')as DateUpdatedString,
				GENPolls.Weight,
                GENPolls.IsCheckList,
				(case GENPolls.QuestionType when 0 then 'MultipleChoice' when 1 then 'Value' when 2 then 'TrueFalse' when 3 then 'Article'
				when 4 then 'Checkbox' when 5 then 'MCQSingle' when 6 then 'MCQMulti' else null end) as  QuestionTypeName,
                GENPolls.Name,
               GENPolls.MaxAnsNumber,
               GENPolls.MinAnsNumber,
               GENPolls.Value,
			   GENTypes.Name as Course,
			   GENItems.Name as SessionName,GENPolls.Time

FROM GENPolls left join
Course_Question on GENPolls.Id=Course_Question.QuestionId	left join 
GENItems ON Course_Question.SessionId=GENItems.Id left join 
GENTypes ON Course_Question.CourseId=GENTypes.Id left join 
GENListValues on GENPolls.LanguageId=GENListValues.Id
where (GENPolls.LanguageId = @LanguageId or @LanguageId is null)and GENPolls.IsActive=1
and (GENPolls.Id in ( select QuestionId from Course_Question where CourseId = @CourseId) or @CourseId is null)
AND (@ProsectionId IS NULL OR @ProsectionId=GENPolls.ProsecutionId)
order by DisplayOrder
end
GO
