/****** Object:  StoredProcedure [dbo].[GetAttendanceDetailsByClassroom]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetAttendanceDetailsByClassroom]
    @classroomid INT
AS
BEGIN
    SELECT 
        GENContacts.id,
        GENContacts.name,
        Classroom_Attendance.execuseid
    FROM 
        GENContacts 
    INNER JOIN 
        GENClassroom_GENContact 
    ON 
        GENContacts.Id = GENClassroom_GENContact.StudentId 
    AND 
        GENClassroom_GENContact.ClassroomId = @classroomid
    LEFT JOIN 
        TLMSClassroom_Session 
    ON 
        TLMSClassroom_Session.ClassroomId = GENClassroom_GENContact.ClassroomId 
    AND 
        CAST(TLMSClassroom_Session.SessionDateTime AS DATE) = CAST(GETDATE() AS DATE)
    LEFT JOIN 
        Classroom_Attendance 
    ON 
        TLMSClassroom_Session.ClassroomId = Classroom_Attendance.ClassroomId 
    AND 
        TLMSClassroom_Session.SessionId = Classroom_Attendance.SessionId
    AND 
        Classroom_Attendance.StudentId = GENContacts.Id;
END;
GO
/****** Object:  StoredProcedure [dbo].[GetAttendanceDetailsByClassroomId]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetAttendanceDetailsByClassroomId]
    @ClassroomId INT
AS
BEGIN
    SELECT B.name, B.id, a.execuseid
    FROM Classroom_Attendance a 
    INNER JOIN GENContacts B ON a.StudentId = B.Id 
    INNER JOIN GENClassroom_GENContact c ON B.id = c.StudentId
    WHERE c.ClassroomId = @ClassroomId;
END;
GO
