CREATE proc [dbo].[GetAuthenticationsByID] @id bigint 
as 
begin
select auth.Name,auth.PageName,auth.BackendPageId
,auth.UserAuthentication,
AC.Name AccessCriteriaName,ro.Id IdentityRoleId,
ro.Name IdentityRoleName,
auth.AccessCriteriaId AccessCriteriaId

from Authentications auth 

left JOIN AccessCriterias AC ON auth.AccessCriteriaId= AC.Id
left join  AspNetRoles ro on auth.IdentityRoleId=ro.Id

where @id=auth.BackendPageId  ;

end
