CREATE proc [dbo].[GetBaseEntityByID] @id bigint 
as 
begin
select BT.Id,bt.DisplayName,BT.BaseTabId,BT.GENPageOfPagesId,
BT.BaseEntityId,bt.SearchPageId,btab.Name Name , isnull(be.Name,'') baseEntityName, 
isNUll(GNG.Name,'') searchPageName ,BT.IsIndex 
from((( BaseTabGENPageOfPages BT 

left JOIN BaseTabs btab ON bt.BaseTabId = btab.Id)
left JOIN BaseEntities be ON bt.BaseEntityId =be.Id)
left JOIN GENPageOfPages GNG on BT.SearchPageId=GNG.Id)
where @id=bt.GENPageOfPagesId And ( BT.SearchPageId <> @id or BT.SearchPageId is null)   ;

end
