 CREATE PROCEDURE [dbo].[GetClassroomsForToday]
AS
BEGIN
    DECLARE @Today DATE = CONVERT(DATE, GETDATE());

    SELECT DISTINCT gc.*
    FROM TlmsclassroomSessions ts
    INNER JOIN Genclassrooms gc ON ts.ClassroomId = gc.Id
    WHERE CONVERT(DATE, ts.SessionDateTime) = @Today;
END;
GO
