CREATE PROCEDURE [dbo].[GetClassroomToday]
AS
BEGIN
    SELECT g.*
    FROM genclassrooms g
    INNER JOIN GENClassroom_GENContact cc ON cc.classroomId = g.Id
    INNER JOIN GenContacts c ON cc.studentId = c.Id
    INNER JOIN TLMSClassroom_Session d ON d.ClassroomId = cc.classroomId
    WHERE CAST(d.SessionDateTime AS date) = CAST(GETDATE() AS date);
END;
