CREATE PROCEDURE [dbo].[GetContactDetailsById]
    @contactId INT
AS
BEGIN
    SELECT c.name AS ContactName,
           c.nationalityid AS NationalityId,
           g.name AS CountryName
    FROM GenContacts c
