/****** Object:  StoredProcedure [dbo].[GetContactInfo]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[GetContactInfo]
    @Value NVARCHAR(50)
AS
BEGIN
    SELECT c.name, 
           c.idnumber, 
           c.DefaultPhone, 
           cc.ClassroomId, 
           d.Name AS Nationality,
           cc.ClassroomCode, 
           g.FromDateTime, 
           g.ToDateTime
    FROM genclassrooms g
    INNER JOIN GENClassroom_GENContact cc 
        ON cc.classroomId = g.Id
    INNER JOIN GenContacts c 
        ON cc.studentId = c.Id
    INNER JOIN GENAddresses e 
        ON e.entityid = c.id 
    INNER JOIN Gencountries d 
        ON e.CountryId = d.id
    INNER JOIN TLMSClassroom_Session f 
        ON f.ClassroomId = cc.ClassroomId
    INNER JOIN OTP_Attendance h 
        ON h.TLMSClassroom_SessionId = f.Id
    WHERE h.Value = @Value
END;
GO
