/****** Object:  StoredProcedure [dbo].[GetContactToday]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[GetContactToday]
AS
BEGIN
    SELECT gencontacts.*
    FROM GENContacts 
    INNER JOIN GENClassroom_GENContact 
        ON GENContacts.Id = GENClassroom_GENContact.StudentId 
        AND GENClassroom_GENContact.ClassroomId = ClassroomId
    LEFT JOIN TLMSClassroom_Session 
        ON TLMSClassroom_Session.ClassroomId = GENClassroom_GENContact.ClassroomId 
    LEFT JOIN Classroom_Attendance 
        ON TLMSClassroom_Session.ClassroomId = Classroom_Attendance.ClassroomId 
        AND TLMSClassroom_Session.SessionId = Classroom_Attendance.SessionId
        AND Classroom_Attendance.StudentId = GENContacts.Id
    WHERE CAST(TLMSClassroom_Session.SessionDateTime AS DATE) = CAST(GETDATE() AS DATE)
END;
GO
