/****** Object:  StoredProcedure [dbo].[GetExamsAndQuestions]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetExamsAndQuestions]
AS
SELECT DISTINCT [GENPollCategories].[Code]
      ,[GENPollCategories].[Name]
	  ,[ExamType]
	  , null AS ExamTypeName
	  ,[GENPollCategories].[LanguageId]
	  ,[GENPollCategories].[Time]
      ,[GENPollCategories].[Weight] AS OfficalScore
      ,[SuccessScore]
	  ,[GENPollCategories].[DisplayOrder]
      ,[GENPollCategories].[IsActive]
      ,[GENPollCategories].[IsPublish]
	  ,GENListValues.Name AS LanguageName
	  ,[GENPolls].[Code] AS PollCode
	  ,[GENPolls].[Name] AS QuestionNumber
      ,[Question]
	  ,[GENPolls].[DisplayOrder] AS PollDisplayOrder
      ,[GENPolls].[Weight] AS [FullMark]
      ,[Total] AS [TotalMarks]
	  ,dbo.FN_GetQuestionType(QuestionType,GENListValues.ShortCode) AS QuestionTypeName
	  ,[QuestionType]
	  ,[GENPolls].[IsPublish] as PollIsPublish
      ,[GENPolls].[IsActive] as PollIsActive
  FROM [dbo].[GENPollCategories]
  LEFT JOIN GENListValues on GENListValues.Id=[GENPollCategories].[LanguageId]
  LEFT JOIN [PollCategoryandPolls] ON [GENPollCategories].Id=[PollCategoryandPolls].PollCategoryId
  LEFT JOIN [GENPolls] on [GENPolls].Id=[PollCategoryandPolls].PollId
GO
