  CREATE PROCEDURE [dbo].[GetFieldAuth]
  AS
  SELECT 
		[UserAuthentication]
      ,[PageOfPageFieldId]
      ,[IdentityRoleId]
	  ,[AspNetRoles].Name AS IdentityRoleName
	  ,[BaseEntityFields].DBField as FieldName
  FROM [dbo].[PageOfPageField_Role] 
