/****** Object:  StoredProcedure [dbo].[GetGenTypeCategoriesAndChildren]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetGenTypeCategoriesAndChildren] 
    @Id INT
AS
BEGIN
    WITH GENTypeCategories_hierarchy AS (
        SELECT 
            id,
            ParentId,
            Name,
            TalentBuilderId,
			TalentId
        FROM 
            GENTypeCategories
        WHERE 
            id = @Id
        
        UNION ALL
        
        SELECT 
            child.Id,
            child.ParentId,
            child.Name,
            child.TalentBuilderId,
			child.TalentId
        FROM 
            GENTypeCategories child
        INNER JOIN 
            GENTypeCategories_hierarchy parent ON child.ParentId = parent.id
    )
    SELECT 
        id,
        ParentId,
        Name,
        TalentBuilderId,
		TalentId
    FROM 
        GENTypeCategories_hierarchy;
END
GO
