CREATE proc [dbo].[GetPageOfPageFeildsByID] @id bigint 
as 
begin
select POPF.Id Id,POPF.Value,POPF.FeildId,POPF.PageOfPageId,
POPF.FilterName,POPF.FilterValue,POPF.FilterEntityId,
BEF.DBField,POPF.DisplayName,POPF.IsMandatory,POPF.IsActive,
POPF.RegEx,POPF.RegExMessage,POPF.DisplayOrder,POPF.Cols,
POPF.IsIndex,POPF.IsPrimaryKey,POPF.IsIdentity,POPF.AllowEditing,
POPF.AllowFiltering,POPF.IsTemplateColumn,POPF.Visible,POPF.Width,
POPF.TextAlign,POPF.Format,POPF.Type,POPF.TemplateID,POPF.Field,
POPF.InputType

from PageOfPageFeilds POPF 

left JOIN BaseEntityFields BEF ON POPF.FeildId= BEF.Id


where @id=POPF.PageOfPageId  ;

end
GO
