CREATE proc [dbo].[GetPOPFromByID] @id bigint 
as 
begin
select  GNG.Id,GNG.Code,GNG.Description,GNG.DateCreated,GNG.DateUpdated, CAST (0 AS BIGINT) as ContactSearchpopId,
GNG.CreatedById,GNG.LastUpdatedById,GNG.IsActive,GNG.IsPublish, GNG.CategoryId,
GNG.EntityId,ISNULL(be.Name,'') EntityName ,GNG.BackendPageId,GNG.IsSPSubsidiaries,
gng.IsFPSubsidiaries,
ISNULL(GNGBP.BackendSectionId,0) BackendSectionId,
CAST (IsNULL(ISNULL(GNG.BackendPageId,GNG.Name),GNGBP.Name ) AS nvarchar(MAX) ) BackendPageName,
ISNULL(GNGBP.BackgroundColor,'')BackgroundColor,
ISNULL(GNGBP.IconDisplayId,0)IconDisplayId,
ISNULL(GNGBP.PaddingIconDisplay,20)PaddingIconDisplay,
ISNULL(GNGBP.Size,1)Size,GNGBP.StyleId StyleId ,
ISNULL(GNGBP.TextAlignId,0)TextAlignId
,CAST( IsNULL(ISNULL(GNG.BackendPageId,GNG.Name),GNGBP.TextColor) AS nvarchar(MAX) ) TextColor,
CAST( IsNULL(ISNULL(GNG.BackendPageId,GNG.Name),GNGBP.DisplayName ) AS nvarchar(MAX) ) DisplayName,
iif(GNGBP.DisplayOrder is null, CAST (0 AS BIGINT) ,cast(GNGBP.DisplayOrder as bigint)) DisplayOrder,CAST (0 AS BIGINT) as GENListValuesTypeId,
GNG.Name,GNG.popTypeId,GNG.TypeStatusId,GNG.IsUser,
GNG.IsSearchBar,GNG.IsReadOnly,GNG.IsCheckedout,GNG.TimeoutCount,GNG.IsActivityMenu
,isnull(be.CategoryApiUrl,'') ApiURL,GNG.CreateType,GNG.FirstCode

,CAST (0 AS BIGINT) as SelectedRelation

from GENPageOfPages GNG

left JOIN GENBackendPages GNGBP on gng.BackendPageId=GNGBP.Id
left JOIN BaseEntities BE on gng.EntityId=be.Id

where @id=GNG.Id  ;

end


