/****** Object:  StoredProcedure [dbo].[ItemCategoryMaxLevel]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 14 Apr 2019
-- Description:	Getting Max Level for Item Category
-- =============================================
CREATE PROCEDURE [dbo].[ItemCategoryMaxLevel] 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	with a as
(
    select 
       id, 
       ParentId, 
       1 lvl 
    from [GENItemCategories] 
    where ParentId is null
    union all
    select 
        b.id, 
        b.ParentId, 
        lvl+1 
    from [GENItemCategories] b 
        join a on a.id = b.ParentId
)
select 
    MAX(a.lvl) as MaxLevel
from a
    left join a b on a.id = b.ParentId
where b.id is null
option (maxrecursion 0)
END
GO
/****** Object:  StoredProcedure [dbo].[LogFile_InsertContent]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[LogFile_InsertContent] (@RawString nvarchar(Max),@ColumnString nvarchar(Max),@LineNumber int)
as
 Declare @TEMPColumnCount int
declare @TEMPColumn table (ID int, Item varchar(max))
insert into @TEMPColumn SELECT ID, Item FROM dbo.Split(@ColumnString,',')

declare @TEMPRow table (ID int, Item varchar(max))
insert into @TEMPRow SELECT ID, Item FROM dbo.Split(@RawString,',')

SELECT @TEMPColumnCount =   COUNT(*) FROM @TEMPColumn 
 DECLARE @i int = 0
 Declare @ContentValue nvarchar(Max) =CAST(@LineNumber AS nvarchar(Max)) +'-';
WHILE @i < @TEMPColumnCount
BEGIN
    SET @i = @i + 1

	Declare @ColumnValue nvarchar(250)
	Declare @RowValue nvarchar(250)

	select @RowValue = Item from @TEMPRow where Id =@i
	select @ColumnValue = Item from @TEMPColumn where Id =@i
set @ContentValue =@ContentValue+@ColumnValue+': '  + @RowValue+','

    /* do some work */
END

select @ContentValue
GO
/****** Object:  StoredProcedure [dbo].[NoOfActivityOfRpt_AchievementsDtls]    Script Date: 7/1/2026 10:45:02 AM ******/
