GO
SET QUOTED_IDENTIFIER ON
GO
create   proc [dbo].[NoOfActivityOfRpt_AchievementsDtls]
@DateF Datetime,
@DateTo Datetime
as
SELECT 
    (SELECT COUNT(*) FROM GENCLassRooms WHERE ClassroomCategoryId = 1 AND IsDeleted = 0 and ((cast(GENClassrooms.DateCreated as date) >= cast(@DateF as date) and cast(GENClassrooms.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))) +
    (SELECT COUNT(*) FROM GENCLassRooms WHERE ClassroomCategoryId = 2 AND IsDeleted = 0 and ((cast(GENClassrooms.DateCreated as date) >= cast(@DateF as date) and cast(GENClassrooms.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))) AS TotalActivity
GO
/****** Object:  StoredProcedure [dbo].[PagingWikiSample]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PagingWikiSample]
(
    @PageNumber INT = 1,
    @PageSize INT = 10,
    @langCode NVARCHAR(50),
    @CategoryId BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Skip INT = (@PageNumber - 1) * @PageSize;

    -- 1. استخدام جدول مؤقت لتخزين المعرفات المطلوبة فقط (لتحسين السرعة)
    DECLARE @SelectedIds TABLE (Id BIGINT, TotalRecords INT);

    INSERT INTO @SelectedIds (Id, TotalRecords)
    SELECT w.Id, COUNT(*) OVER() 
    FROM GENWikis w
    WHERE w.WikiCategoryId = @CategoryId
      AND w.IsPublish = 1
      AND w.IsActive = 1
      AND w.IsDeleted = 0
      AND (
            @langCode = 'ar'
            OR EXISTS (SELECT 1 FROM Wiki_TranslateView t WHERE t.WikiId = w.Id AND t.LanguageCode = @langCode)
          )
    ORDER BY w.Date1 DESC
    OFFSET @Skip ROWS
    FETCH NEXT @PageSize ROWS ONLY;

    -- حساب إجمالي الصفحات من أول سجل في الجدول المؤقت
    DECLARE @TotalRecords INT = (SELECT TOP 1 TotalRecords FROM @SelectedIds);
    DECLARE @TotalPages INT = CEILING(1.0 * ISNULL(@TotalRecords, 0) / @PageSize);

    -- 2. جلب البيانات النهائية فقط للـ 10 سجلات المختارة
    ;WITH Trans AS
    (
        SELECT 
            t.WikiId,
            MAX(CASE WHEN FieldName='VideoURL' THEN Value END) AS VideoURL,
            MAX(CASE WHEN FieldName='RichContent' THEN Value END) AS RichContent,
            MAX(CASE WHEN FieldName='TargetUrl' THEN Value END) AS TargetUrl,
            MAX(CASE WHEN FieldName='Name' THEN Value END) AS Name,
            MAX(CASE WHEN FieldName='Description' THEN Value END) AS Description,
            MAX(CASE WHEN FieldName='String1' THEN Value END) AS String1,
            MAX(CASE WHEN FieldName='Image' THEN Value END) AS Image
        FROM Wiki_TranslateView t
        INNER JOIN @SelectedIds s ON t.WikiId = s.Id -- هنا الربط لتقليل البحث
        WHERE t.LanguageCode = @langCode
        GROUP BY t.WikiId
    )
    SELECT
        w.Id,
        ISNULL(tr.VideoURL, w.VideoURL) AS VideoURL,
        w.AudioURL,
        '' AS RichContent,
        ISNULL(tr.TargetUrl, w.TargetUrl) AS TargetUrl,
        ISNULL(tr.Name, w.Name) AS Name,
        ISNULL(tr.Description, w.[Description]) AS Description,
        w.DisplayOrdering,
        w.LastUpdatedById,
        w.CheckoutBy,
        ISNULL(tr.String1, w.String1) AS String,
        CONVERT(VARCHAR(10), w.Date1, 103) AS Date1String,
        YEAR(w.Date1) AS [Year],
        CASE 
            WHEN NULLIF(tr.Image, '') IS NOT NULL THEN tr.Image
            WHEN NULLIF(w.Image, '') IS NOT NULL THEN w.Image
            ELSE '/assets/images/Default.png'
        END AS Image,
        w.IsActive,
        w.IsPublish,
        w.ValueId1 AS CatId,
        w.WikiCategory_Name AS CatName,
        w.Date1,
        @TotalPages AS TotalPage,
        (SELECT TOP 1 AzureUri FROM GENFiles WHERE BaseEntityId = 6 AND EntityId = w.Id) AS TapFileURL,
        (SELECT TOP 1 AzureUri FROM GENVideos WHERE BaseEntityId = 6 AND EntityId = w.Id) AS TapVideoURL
    FROM @SelectedIds s
    JOIN GENWikis w ON s.Id = w.Id
    LEFT JOIN Trans tr ON tr.WikiId = w.Id
    ORDER BY w.Date1 DESC; -- الترتيب النهائي
END
GO
/****** Object:  StoredProcedure [dbo].[Print_TCR]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Print_TCR] --3
@ID bigint
as
begin
select Distinct TCR_View.*
,(Case when TCRItems.OpreationId =1 then (TCRItems.Discount/100) * TCRItems.Total when TCRItems.OpreationId =2 then TCRItems.Discount * TCRItems.BillQTY end)as DiscountValue  
,TCRItems.Id as ItemID,TCRItems.Name as ItemBillName,TCRItems.BillQTY as ItmQty,TCRItems.Total ,TCRItems.Discount,TCRItems.TotalPrice,TCRItems.OpreationId,TCRItems.Price as UnitPrice
from TCR_View
inner join TCRItems on TCRItems.TCRId = TCR_View.Id
where TCR_View.Id = @Id
end
GO
