/****** Object:  StoredProcedure [dbo].[Rpt_AchievementsAllDtls]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_AchievementsAllDtls] --Rpt_AchievementsDtls null,null,null,null,null,null,null,null,null
@CourseId int
,@GroupTypeId int
,@IsPlane bit
,@CompanyId int
,@GovernorateId int
,@Isimportant bit
,@DateF datetime = null
,@DateTo datetime = null
,@ClassRoomStatus int = 2,
@ProsecutionId int=null
as
begin

select distinct GENClassrooms.Id,GENClassrooms.Code as ClassroomCode,GENTypes.Name as CourseName,GENClassrooms.Name as ClassroomName,(case when GroupTypeID = 0 then 'Free' when GroupTypeID = 1 then 'Money'
when GroupTypeID =2 then 'Plan' when GroupTypeID = 3 then 'Approval' when GroupTypeID = 4 then 'GraduateStudies' end) as GroupType
,(case when isnull(IsPlan,0) = 1 then N'انشطه داخل التدريب' else N'انشطه خارج التدريب' end) as IsPlan,GENCompanies.Name as CompanyName
,GENGovernorates.Name as GENGovernorateName,GENCities.Name as GENCityName,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,(GENClassrooms.Int1) as ContactCount,(case when GENClassrooms.ProsecutionId = 2 then N'بحوث' when GENClassrooms.ProsecutionId = 4 then N'الامين العام'
when GENClassrooms.ProsecutionId = 1 then N'الدراسات العليا' when GENClassrooms.ProsecutionId = 3 then N'الاتصالات والعلاقات الدولية' when GENClassrooms.ProsecutionId = 0 then N'التخطيط والتدريب' end)as Prosecution
,GENClassrooms.instructor_Name AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudents,
GENClassrooms.ClassRoomStatus
from GENClassrooms
left join GENCompanies on GENClassrooms.CompanyId = GENCompanies.Id
left join GENTypes on GENClassrooms.CourseId = GENTypes.Id
left join GENGovernorates on GENGovernorates.Id = GENClassrooms.GovernorateId
left join GENCities on GENCities.Id = GENClassrooms.CityId 
left join AspNetUsers Created ON GENClassrooms.CreatedById =Created.email 
left join GENRooms ON GENClassrooms.RoomId=GENRooms.Id
where
--ClassroomCategoryId = 2 and

(GENClassrooms.ProsecutionId = @ProsecutionId or @ProsecutionId is null)  and
(GENClassrooms.CourseId = @CourseId or @CourseId is null) and (GENClassrooms.GroupTypeId = @GroupTypeId or @GroupTypeId is null)
and (GENClassrooms.IsPlan = @IsPlane or @IsPlane is null ) and (GENClassrooms.CompanyId = @CompanyId or @CompanyId is null)
 and (GENClassrooms.GovernorateId = @GovernorateId or @GovernorateId is null) and (GENClassrooms.IsAchievementRanking = @Isimportant or @Isimportant is null or @Isimportant = 0)
 and (GENClassrooms.IsDeleted = 0 or GENClassrooms.IsDeleted is null) 
 and 
 --((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.ToDateTime as date) <= cast(@DateTo as date)) 

 (((Fromdatetime <= @DateF and ToDateTime >= @DateF) AND   (Fromdatetime <= @DateTo and ToDateTime >= @DateTo))  OR
(@DateF <= Fromdatetime AND @DateF >= Fromdatetime) OR (@DateF <= ToDateTime AND @DateTo >= ToDateTime)) 


or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) 
or (cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)) and (GENClassrooms.ClassRoomStatus = @ClassRoomStatus or @ClassRoomStatus is null or @ClassRoomStatus = -1)




end
GO
