,@ClassRoomStatus int = null
,@CompanyIds nvarchar(MAX) = null
,@courseIds nvarchar(MAX) = null
,@governorateIds nvarchar(MAX) = null
,@classroomIds nvarchar(MAX) = null
,@eventIds nvarchar(MAX) = null
,@ClassRoomStatusIds nvarchar(MAX) = null
,@GroupTypeIds nvarchar(MAX) = null
,@EventTypeIds nvarchar(MAX) = null
,@CourseCategoryIds nvarchar(MAX) = null
,@ProsecutionIds nvarchar(MAX) = null

as
begin

WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE ( H1.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CourseCategoryIds, ',')))
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)

select * from (
select DISTINCT GENClassrooms.String2 as InstructorPerson , GENClassrooms.Id,GENClassrooms.Code as ClassroomCode,GENTypes.Name as CourseName,GENClassrooms.Name as ClassroomName,(case when GroupTypeID = 0 then N'مجاني' when GroupTypeID = 1 then N'رسوم'
when GroupTypeID =2 then N'خطة' when GroupTypeID = 3 then N'تصديق' when GroupTypeID = 4 then N'الدراسات العليا' end) as GroupType
,(case when isnull(IsPlan,0) = 1 then N'انشطه داخل التدريب' else N'انشطه خارج التدريب' end) as IsPlan,GENCompanies.Name as CompanyName
,GENGovernorates.Name as GENGovernorateName,GENCities.Name as GENCityName,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,(GENClassrooms.Int1) as ContactCount,(case when GENClassrooms.ProsecutionId = 2 then N'بحوث' when GENClassrooms.ProsecutionId = 4 then N'الامين العام'
when GENClassrooms.ProsecutionId = 1 then N'الدراسات العليا' when GENClassrooms.ProsecutionId = 3 then N'الاتصالات والعلاقات الدولية' when GENClassrooms.ProsecutionId = 0 then N'التخطيط والتدريب' end)as Prosecution
,GENClassrooms.instructor_Name AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,dbo.fn_VcrStudentCount(GENClassrooms.Id) + GENClassrooms.Int1 AS CountStudents,
GENClassrooms.ClassRoomStatus,Destination.name DonorDestination
from GENClassrooms
left join GENCompanies on GENClassrooms.CompanyId = GENCompanies.Id
left join GENTypes on GENClassrooms.CourseId = GENTypes.Id
left join CourseCategories ON CourseCategories.CourseId=GENTypes.Id
left join RecursiveCte ON CourseCategories.CategoryId =RecursiveCte.Id
left join GENGovernorates on GENGovernorates.Id = GENClassrooms.GovernorateId
left join GENCities on GENCities.Id = GENClassrooms.CityId 
left join AspNetUsers Created ON GENClassrooms.CreatedById =Created.email 
left join GENRooms ON GENClassrooms.RoomId=GENRooms.Id
left join GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
left join GenContacts on GenContacts.Id = GENClassroom_GENContact.StudentId
left join GENCompanies Destination on GENClassrooms.DestinationsId = Destination.Id
where  ClassroomCategoryId = 2 and (GENClassrooms.CourseId = @CourseId or @CourseId is null) 
and (GENClassrooms.GroupTypeId = @GroupTypeId or @GroupTypeId is null)
and (@CourseCategoryIds IS NULL OR  len(@CourseCategoryIds) =0 or(RecursiveCte.Id is not null))
and (GENClassrooms.IsPlan = @IsPlane or @IsPlane is null ) and (GENClassrooms.CompanyId = @CompanyId or @CompanyId is null)
 and (GENClassrooms.GovernorateId = @GovernorateId or @GovernorateId is null) and (GENClassrooms.IsAchievementRanking = @Isimportant or @Isimportant is null or @Isimportant = 0)
 and (GENClassrooms.IsDeleted = 0 or GENClassrooms.IsDeleted is null) and GENClassrooms.IsActive = 1 
 and 
 --((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.ToDateTime as date) <= cast(@DateTo as date)) 

 ((((cast(Fromdatetime as date) <= @DateF and cast(ToDateTime as date) >= @DateF) AND   (cast(Fromdatetime as date) <= @DateTo and cast(todatetime as date) >= @DateTo))  OR
(@DateF <= cast(Fromdatetime as date) AND @DateF >= cast(Fromdatetime as date)) OR (@DateF <= cast(ToDateTime as date) AND @DateTo >= cast(ToDateTime as date))) 


or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) 
or (cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)))

and (GENClassrooms.ClassRoomStatus = @ClassRoomStatus or @ClassRoomStatus is null or @ClassRoomStatus = -1)

AND (@CompanyIds IS NULL OR  len(@CompanyIds) =0 or GENCompanies.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CompanyIds, ',')))

	
AND (@ContactDestination IS NULL OR  len(@ContactDestination) =0 or GENContacts.CompanyId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ContactDestination, ',')))

AND (@DonorDestination IS NULL OR  len(@DonorDestination) =0 or Destination.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@DonorDestination, ',')))


AND (@courseIds IS NULL OR  len(@courseIds) =0 or GENClassrooms.CourseId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@courseIds, ',')))

	
AND (@governorateIds IS NULL OR  len(@governorateIds) =0 or GENClassrooms.GovernorateId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@governorateIds, ',')))

AND (@eventIds IS NULL OR  len(@eventIds) =0 or GENClassrooms.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@eventIds, ',')))

AND (@ClassRoomStatusIds IS NULL OR  len(@ClassRoomStatusIds) =0 or GENClassrooms.ClassRoomStatus IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ClassRoomStatusIds, ',')))

AND (@GroupTypeIds IS NULL OR  len(@GroupTypeIds) =0 or GENClassrooms.GroupTypeId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@GroupTypeIds, ',')))
	
AND (@EventTypeIds IS NULL OR  len(@EventTypeIds) =0 or GENClassrooms.EventTypeId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@EventTypeIds, ',')))
			
AND (@ProsecutionIds IS NULL OR  len(@ProsecutionIds) =0 or GENClassrooms.ProsecutionId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ProsecutionIds, ',')))

AND (@classroomIds IS NULL OR  len(@classroomIds) =0 or GENClassrooms.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@classroomIds, ',')))

union 

select DISTINCT  GENClassrooms.String2 as InstructorPerson ,  GENClassrooms.Id, GENClassrooms.Code as ClassroomCode,GENTypes.Name as CourseName,GENClassrooms.Name as ClassroomName,(case when GroupTypeID = 0 then N'مجاني' when GroupTypeID = 1 then N'رسوم'
when GroupTypeID =2 then N'خطة' when GroupTypeID = 3 then N'تصديق' when GroupTypeID = 4 then N'الدراسات العليا' end) as GroupType
,(case when isnull(IsPlan,0) = 1 then N'انشطه داخل التدريب' else N'انشطه خارج التدريب' end) as IsPlan,GENCompanies.Name as CompanyName
,GENGovernorates.Name as GENGovernorateName,GENCities.Name as GENCityName,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) as ContactCount,
(case when GENClassrooms.ProsecutionId = 2 then N'بحوث' when GENClassrooms.ProsecutionId = 4 then N'الامين العام'
when GENClassrooms.ProsecutionId = 1 then N'الدراسات العليا' when GENClassrooms.ProsecutionId = 3 then N'الاتصالات والعلاقات الدولية' when GENClassrooms.ProsecutionId = 0 then N'التخطيط والتدريب' end)as Prosecution
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudents,
GENClassrooms.ClassRoomStatus,Destination.name DonorDestination
from GENClassrooms
left join GENCompanies on GENClassrooms.CompanyId = GENCompanies.Id
left join GENCompanies Destination on GENClassrooms.DestinationsId = Destination.Id
left join GENTypes on GENClassrooms.CourseId = GENTypes.Id
left join CourseCategories ON CourseCategories.CourseId=GENTypes.Id
left join RecursiveCte ON CourseCategories.CategoryId =RecursiveCte.Id
left join GENGovernorates on GENGovernorates.Id = GENClassrooms.GovernorateId
left join GENCities on GENCities.Id = GENClassrooms.CityId
left join GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId = GENClassrooms.Id 
and ([dbo].[AttendanceCall]([GENClassroom_GENContact].StudentId,GENClassrooms.Id) >=isnull(GENClassrooms.Int4,GENTypes.int3))  and [GENClassroom_GENContact].BookingTypeId = 1
left join AspNetUsers Created ON GENClassrooms.CreatedById =Created.email 
left join GENRooms ON GENClassrooms.RoomId=GENRooms.Id
left join GenContacts on GenContacts.Id = GENClassroom_GENContact.StudentId
where  ClassroomCategoryId = 1
and (GENClassrooms.CourseId = @CourseId or @CourseId is null) and (GENClassrooms.GroupTypeId = @GroupTypeId or @GroupTypeId is null)
and (@CourseCategoryIds IS NULL OR  len(@CourseCategoryIds) =0 or(RecursiveCte.Id is not null))
and (GENClassrooms.IsPlan = @IsPlane or @IsPlane is null ) and (GENClassrooms.CompanyId = @CompanyId or @CompanyId is null)
 and (GENClassrooms.GovernorateId = @GovernorateId or @GovernorateId is null) and (GENClassrooms.IsAchievementRanking = @Isimportant or @Isimportant is null or @Isimportant = 0)
  and (GENClassrooms.IsDeleted = 0 or GENClassrooms.IsDeleted is null)  and GENClassrooms.IsActive = 1 
   --and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.ToDateTime as date) <= cast(@DateTo as date)) 
   and   
 ((((cast(Fromdatetime as date) <= @DateF and cast(ToDateTime as date) >= @DateF) AND   (cast(Fromdatetime as date) <= @DateTo and cast(todatetime as date) >= @DateTo))  OR
(@DateF <= cast(Fromdatetime as date) AND @DateF >= cast(Fromdatetime as date)) OR (@DateF <= cast(ToDateTime as date) AND @DateTo >= cast(ToDateTime as date) )) 


or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) 
or (cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0))) 

and (GENClassrooms.ClassRoomStatus = @ClassRoomStatus or @ClassRoomStatus is null or @ClassRoomStatus = -1) 

AND (@CompanyIds IS NULL OR  len(@CompanyIds) =0 or GENCompanies.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CompanyIds, ',')))
AND (@ClassRoomStatusIds IS NULL OR  len(@ClassRoomStatusIds) =0 or GENClassrooms.ClassRoomStatus IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ClassRoomStatusIds, ',')))
		
AND (@ContactDestination IS NULL OR  len(@ContactDestination) =0 or GENContacts.CompanyId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ContactDestination, ',')))

	
AND (@DonorDestination IS NULL OR  len(@DonorDestination) =0 or Destination.Id IN ( SELECT CAST(value AS BIGINT)
FROM STRING_SPLIT(@DonorDestination, ',')))


AND (@courseIds IS NULL OR  len(@courseIds) =0 or GENClassrooms.CourseId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@courseIds, ',')))

AND (@governorateIds IS NULL OR  len(@governorateIds) =0 or GENClassrooms.GovernorateId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@governorateIds, ',')))

AND (@classroomIds IS NULL OR  len(@classroomIds) =0 or GENClassrooms.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@classroomIds, ',')))

AND (@GroupTypeIds IS NULL OR  len(@GroupTypeIds) =0 or GENClassrooms.GroupTypeId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@GroupTypeIds, ',')))
	
AND (@EventTypeIds IS NULL OR  len(@EventTypeIds) =0 or GENClassrooms.EventTypeId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@EventTypeIds, ',')))

AND (@ProsecutionIds IS NULL OR  len(@ProsecutionIds) =0 or GENClassrooms.ProsecutionId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ProsecutionIds, ',')))

AND (@eventIds IS NULL OR  len(@eventIds) =0 or GENClassrooms.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@eventIds, ',')))

group by  GENClassrooms.CompanyId,GENClassrooms.String2 , GENClassrooms.Code,GENClassrooms.Name,GroupTypeID,IsPlan,GENCompanies.Name,GENGovernorates.Name,GENCities.Name,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
,GENClassrooms.ActivityTitle,GENTypes.Name,GENClassrooms.ProsecutionId,GENClassrooms.ClassRoomStatus,GENClassrooms.String1,GENRooms.Name,Created.Name,GENClassrooms.Id,GENClassrooms.instructor_Name
,Destination.name
) as res
order by res.FromDateTime
end
GO
/****** Object:  StoredProcedure [dbo].[Rpt_ActivitiesView]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 01/06/2020
-- Description:	Getting Activities Data with Employees data
-- =============================================
CREATE PROCEDURE [dbo].[Rpt_ActivitiesView]
	-- Add the parameters for the stored procedure here
	@CommentType BIGINT = NULL,
	@DateFrom DateTime = NULL,
	@DateTo DateTime = NULL,
	@EmployeeId BIGINT = NULL,
	@SectionName BIGINT = NULL,
	@SalesAreaName BIGINT = NULL,
	@StatusId BIGINT = NULL,
	@CompanyId BIGINT = NULL,
	@ContactId BIGINT = NULL,
	@PaymentMethodId BIGINT = NULL,
	@IsCompleted BIT = NULL
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT * FROM Rpt_Activity_View
	WHERE (CommentTypeId = @CommentType OR @CommentType IS NULL)
	AND (ActionDate >= @DateFrom OR (@DateFrom IS NULL and cast(ActionDate as date) >= cast(DATEADD(MONTH,-1,GETDATE()) as date)))
	AND (ActionDate <= @DateTo OR (@DateTo IS NULL and cast(ActionDate as date) <= cast(DATEADD(MONTH,1,GETDATE()) as date)))
	AND (EmployeeId = @EmployeeId OR @EmployeeId IS NULL)
	AND (EmployeeId = @EmployeeId OR @EmployeeId IS NULL)
	AND (ValueId2 = @SectionName OR @SectionName IS NULL)
	AND (ValueId4 = @SalesAreaName OR @SalesAreaName IS NULL)
	AND (StatusId = @StatusId OR @StatusId IS NULL)
	AND (MainContactId = @ContactId OR @ContactId IS NULL)
	AND ((EntityId = @CompanyId AND BaseEntityId = 158) OR @CompanyId IS NULL)
	AND ((@IsCompleted = 1 AND IsCompleted = @IsCompleted) OR @IsCompleted IS NULL OR @IsCompleted = 0)
	AND (PaymentMethodId = @PaymentMethodId OR @PaymentMethodId IS NULL)
END
GO
/****** Object:  StoredProcedure [dbo].[RPT_BK_GETLogsByCompanyId]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create procedure [dbo].[RPT_BK_GETLogsByCompanyId] @CompanyId bigint
 as
  select N'قام '+responsibleperson.Name as P1,
  N'ب'+(case
  WHEN GENOperationsLogs.Action=N'Delete' then N'مسح '
  WHEN GENOperationsLogs.Action=N'Add' then N'اضافة '
  WHEN GENOperationsLogs.Action=N'Reminder' then N'تذكير '
  WHEN GENOperationsLogs.Action=N'Import' then N'رفع '
  WHEN GENOperationsLogs.Action=N'AddNew' then N'اضافة جديدة ل'
  END) as P2,
  (case
  WHEN GENOperationsLogs.number=0 then    gencontacts.name + N' المتدرب '
  WHEN GENOperationsLogs.number is null then   N' المتدرب ' + gencontacts.name 
  ELSE  N' عدد ' + CAST(number AS nvarchar) + N' متدرب '
  END) as P3,
  (case
  WHEN (GENOperationsLogs.vcrId IS NOT NULL AND GENOperationsLogs.vcrId>0) then    N' في قاعة '+genclassrooms.NAME
  ELSE ''
  END) as P4,
 GENOperationsLogs.createDate as createDate,format(GENOperationsLogs.createDate,'dd/MM/yyyy HH:MM') as CreateDateString,

 (N'قام '+responsibleperson.Name  + ' ' +(N'ب'+(case
  WHEN GENOperationsLogs.Action=N'Delete' then N'مسح '
  WHEN GENOperationsLogs.Action=N'Add' then N'اضافة '
  WHEN GENOperationsLogs.Action=N'Reminder' then N'تذكير '
  WHEN GENOperationsLogs.Action=N'Import' then N'رفع '
  WHEN GENOperationsLogs.Action=N'AddNew' then N'اضافة جديدة ل'
  END)) + ' '+  (case
  WHEN GENOperationsLogs.number=0 then    gencontacts.name + N' المتدرب '
  WHEN GENOperationsLogs.number is null then   N' المتدرب ' + gencontacts.name 
  ELSE  N' عدد ' + CAST(number AS nvarchar) + N' متدرب '
  END)+ ' '+(case
  WHEN (GENOperationsLogs.vcrId IS NOT NULL AND GENOperationsLogs.vcrId>0) then    N' في قاعة '+genclassrooms.NAME
  ELSE ''
  END)) AS Actions



  from GENOperationsLogs
 left join gencontacts as responsibleperson on GENOperationsLogs.UserId=responsibleperson.Id
 left join gencontacts on gencontacts.Id=GENOperationsLogs.targetId
 left join genclassrooms on genclassrooms.Id=GENOperationsLogs.vcrId
 where ((number IS NOT NULL AND number >0) OR targetId IS NOT NULL)
 and GENOperationsLogs.CompanyId=@CompanyId
 order by GENOperationsLogs.Id DESC
GO
/****** Object:  StoredProcedure [dbo].[Rpt_CompanyInfo]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_CompanyInfo]
as
begin
select * from(select distinct C.Id as CoID,C.AnnualIncome,C.Website,C.String1 as Facebook,C.String2 as linkedin, C.String3 as instgram,C.String4 as Google,C.IsActive
,E.Name as AccountManger,S.Name as SourceName,E.Name as KeyPerson,I.Name as IndustryName,L.name as SLA,L1.Name as AccountType,C.Description
, dbo.fn_LastDealStatus_ByCompanyId(C.Id) AS LastDealStatus, c.DateUpdated,C.Name as CompanyName,C.DefaultAddress as ComapnyDefaultAddress
,C.DefaultEmail as ComapanyDefaultEmail,dbo.fn_Company_CompanyDealCount(C.Id) AS DealCount,C.DefaultPhone as CompanyDefaultPhone,CP.PhoneNumber,CE.Email as CompanyEmail
	,(A.StreetBuilding+',' +   G.Name+','+ P.Name+','+ CO.Name ) As Address 
from GENCompanies C
left join GENEmployees E on C.ResponsiblePersonId = E.Id
left JOIN GENContacts Con ON Con.Id = C.Id 
left join CRMSources S on S.Id = C.SourceId
left join GENIndustries I on I.Id = C.IndustryId
left join GENListValues L on L.Id = C.SLAId
left join GENListValues L1 on L.Id = C.ValueId1
left join GENCompanyEmails CE on CE.CompanyId = C.Id
left join GENCompanyPhones CP on C.Id = CP.CompanyId
left join GENAddresses A on C.Id = A.EntityId and A.BaseEntityId = 158
LEFT OUTER JOIN dbo.GENGovernorates G ON A.GovernorateId = G.Id 
LEFT OUTER JOIN dbo.GENProvinces P ON A.ProvinceId = P.Id 
LEFT OUTER JOIN dbo.GENCountries CO ON A.CountryId = CO.Id )as result
order by CompanyName asc

end
GO
/****** Object:  StoredProcedure [dbo].[Rpt_ContactInfo]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_ContactInfo] --N'حمد',null,null,null,null,null,null,1,null
@name NVARCHAR(MAX) = NULL, @jobTitle NVARCHAR(MAX) = NULL, @assessment  NVARCHAR(MAX) = NULL,
 @companyName NVARCHAR(MAX) = NULL, @tel  NVARCHAR(MAX) = NULL, @email  NVARCHAR(MAX) = NULL, @source  NVARCHAR(MAX) = NULL, @operator int,@WhereClause nvarchar(MAX)=null
as
begin
DECLARE @TableSelect nvarchar(MAX)
DECLARE @WhereSelect nvarchar(MAX)
DECLARE @OrderSelect nvarchar(MAX)
DECLARE @SelectAll nvarchar(MAX)
SET @TableSelect  = 'select * from
('
set @WhereSelect = 'select distinct CI.*,C.Id as CoID ,
(case when c.SalutationName is null then '''' + C.Name
when RIGHT(c.SalutationName,1) = ''.'' then c.SalutationName +C.Name else c.SalutationName +''.''+C.Name end) as ContactName,c.Name as CName,
C.BirthDate as ContactBirthDate,C.DefaultAddress as ContactDefaultAddress,C.DefaultEmail as ContactDefaultEmail
,C.DefaultPhone as ContactDefaultPhone,dbo.fnContact_PhoneString(c.Id) as PhoneNumber,dbo.fnContact_EmailString(c.Id) as Emails
,dbo.fnContact_AddressString(c.Id) As ContectAddress ,C.AssessmentName as Assesment,C.Position as Jobtitle
from Contact_View C
left join ContactInfoes CI on C.Id = CI.ContactId
WHERE (('+ (case when @name is null then 'null' else 'N''' + @name +'''' end) +' IS NOT NULL AND C.Name like ''%'' + '+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' + ''%'' AND '+cast(@operator as nvarchar(50))+' = 1) OR ('+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' IS NOT NULL AND C.Name like '+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' + ''%'' AND '+cast(@operator as nvarchar(50))+' = 2) 
OR ('+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' IS NOT NULL AND C.Name like ''%'' + '+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' AND '+cast(@operator as nvarchar(50))+' = 3) OR ('+ (case when @name is null then 'null' else 'N''' + @name+'''' end )+' IS NOT NULL AND C.Name = '+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' AND '+cast(@operator as nvarchar(50))+' = 4) OR ('+ (case when @name is null then 'null' else 'N''' + @name+'''' end ) +' IS NULL)) 
AND (('+ (case when @jobTitle is null then 'null' else 'N''' +@jobTitle+ '''' end)+' IS NOT NULL AND C.Position like ''%'' + '+(case when @jobTitle is null then 'null' else 'N''' +@jobTitle+ '''' end)+' + ''%'') OR ('+(case when @jobTitle is null then 'null' else 'N''' +@jobTitle+ '''' end)+' IS NULL))
AND (('+(case when @assessment is null then 'null' else 'N''' +@assessment+ '''' end)+' IS NOT NULL AND C.AssessmentName like ''%'' + '+(case when @assessment is null then 'null' else 'N''' +@assessment+ '''' end)+' + ''%'') OR ('+(case when @assessment is null then 'null' else 'N''' +@assessment+ '''' end)+' IS NULL)) 
AND (('+(case when @companyName is null then 'null' else 'N''' +@companyName+ '''' end)+' IS NOT NULL AND C.CompanyName like ''%'' + '+(case when @companyName is null then 'null' else 'N''' +@companyName+ '''' end)+' + ''%'') OR ('+(case when @companyName is null then 'null' else 'N''' +@companyName+ '''' end)+' IS NULL))
AND (('+(case when @tel is null then 'null' else 'N''' +@tel+ '''' end)+' IS NOT NULL AND dbo.fnContact_PhoneString(c.ContactId) like ''%'' + '+(case when @tel is null then 'null' else 'N''' +@tel+ '''' end)+' + ''%'') OR ('+(case when @tel is null then 'null' else 'N''' +@tel+ '''' end)+' IS NULL)) 
AND (('+(case when @email is null then 'null' else 'N''' + @email+ '''' end)+' IS NOT NULL AND dbo.fnContact_EmailString(c.ContactId) like ''%'' + '+(case when @email is null then 'null' else 'N''' + @email+ '''' end)+' + ''%'') OR ('+(case when @email is null then 'null' else 'N''' + @email+ '''' end)+' IS NULL)) AND
(('+(case when @source is null then 'null' else 'N''' +@source+ '''' end)+' IS NOT NULL AND C.SourceName like ''%'' + '+(case when @source is null then 'null' else 'N''' +@source+ '''' end)+' + ''%'') OR ('+(case when @source is null then 'null' else 'N''' +@source+ '''' end)+' IS NULL))'
set @OrderSelect = ') 
 as res
 order by CName asc';
SET @SelectAll = (case when @WhereClause is null then @TableSelect + @WhereSelect + @OrderSelect
else @TableSelect + @WhereSelect + @WhereClause + @OrderSelect end)
EXEC(@SelectAll)
end
GO
/****** Object:  StoredProcedure [dbo].[Rpt_EvolutionAndStatus]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_EvolutionAndStatus] --null,null,null,null
@GENContactID int,
@DateF datetime,
@DateTo datetime,
@ExamId int,
@Code nvarchar(MAX)
as
begin
select GENContacts.Code,GENContacts.Name,BirthDate,GenderId,GENListValues.Name as GenderName,GENExamAnswerHeaders.ExamName
,GENExamAnswerDetails.AnswerName,(case when GENPolls.QuestionType = 1 or GENPolls.QuestionType = 3then GENExamAnswerDetails.AnswerName else GENPollAnswers.Answer end)as Answer,GENPolls.Question,GENExamAnswerDetails.DateCreated as GENExamAnswerDetailsDateCreated
,GENExamAnswerHeaders.DateCreated as GENExamAnswerHeadersDateCreated,GENPolls.Id as GENPollID,GENExamAnswerHeaders.Id as GENExamAnswerHeaderID
,GENContacts.Id as GENContactID,GENContacts.ContactTypeId,GENContactTypes.Name As ContactTypeName,GENExamAnswerDetails.PollAnswerId as GENExamAnswerDetailsPollAnswerId,GENPollAnswers.Id as PollAnswerId
,GENExamAnswerDetails.Id as GENExamAnswerDetailID,GENExamAnswerHeaders.ExamId from GENContacts
left join GENListValues on GENListValues.Id  = GenderId
inner join GENExamAnswerHeaders on GENExamAnswerHeaders.StudentId = GENContacts.Id
left join GENExamAnswerDetails on ExamAnswerHeaderId = GENExamAnswerHeaders.Id
Left Join GENContactTypes ON GENContacts.ContactTypeId=GENContactTypes.Id
left join GENPolls on GENExamAnswerDetails.PollId = GENPolls.Id
left join GENPollAnswers on GENPolls.Id = GENPollAnswers.PollId
where (GENContacts.Id = @GENContactID or @GENContactID is null or @GENContactID = 0 or len(@GENContactID) = 0) 
and GENExamAnswerHeaders.Id in (
select top 10 GENExamAnswerHeaders.id from GENExamAnswerHeaders
where GENExamAnswerHeaders.StudentId = GENContacts.Id
order by GENExamAnswerHeaders.DateCreated desc
)
and ((cast(GENExamAnswerHeaders.DateCreated as date) >= cast(@DateF as date) and cast(GENExamAnswerHeaders.DateCreated as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null)
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (GENExamAnswerHeaders.ExamId = @ExamId or @ExamId is null or @ExamId = 0 or len(@ExamId) = 0)
and (GENContacts.Code like '%'+@Code+'%' or @Code is null or len(@Code) =0)
End
GO
/****** Object:  StoredProcedure [dbo].[Rpt_FieldsCount]    Script Date: 7/1/2026 10:45:02 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_FieldsCount]
as
begin
WITH RecursiveCte AS
(
    SELECT H1.Id AS Id,
     H1.Id AS Parent
    ,H1.Name,H1.Name AS Text,1 as Lvl FROM GENTypeCategories H1
    where H1.ParentId in (3,21) and H1.IsActive = 1 And H1.IsPublish = 1
    UNION ALL
    SELECT H2.Id AS Id,
    RCTE.Parent AS Parent
    ,H2.Name,H2.Name AS Text,Lvl + 1 as Lvl FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
    WHERE  H2.IsActive = 1 And H2.IsPublish = 1
)
select RecursiveCte.Parent,GENTypeCategories.Name,count(distinct GENTypes.Id) as CountCourse from RecursiveCte
left join GENTypeCategories on GENTypeCategories.Id= RecursiveCte.Parent
left join CourseCategories on CourseCategories.CategoryId = RecursiveCte.Id
left join GENTypes on GENTypes.Id = CourseCategories.CourseId  AND GENTypes.IsActive = 1 ANd GENTypes.IsPublish = 1 and GENTypes.IsDeleted=0
group by Parent,GENTypeCategories.Name
end
GO
