CREATE proc [dbo].[Rpt_FunctionSheet] --3
@Id bigint
as
begin
select distinct WO.[To],WO.[CC],WO.[FI],T.[Name] as TcrName,WO.FunctionDate as [ContractDate],B.[Name] as BranchName,B.[Address],C.[Name] as ComapanyName
,WO.[TypeFunction],WO.[NumberOfPerson],Br.Name as BrandName
,WO.[Guranted],WO.[PaymentDetails],WO.[String1],WO.[String2],WO.Remarks as [Description],WO.[PricePerson],WO.[PaymentMethod]
,CONVERT(varchar, WO.FunctionDate, 103) AS ContractDateString,cast(format(WO.FunctionDate , 'hh:mm tt') as varchar)AS ContractTimeString, T.ProcessName AS ProcessName,
cast(IFD.ItemId as nvarchar(max))as ItmCode,IFD.Name as ItmName,E.Position AS EmpPosition
 from TCRWorkOrders WO
left  join GENEmployees E on WO.CreatedBy = E.UserId
left join TCR_View T on T.Id = WO.TCRId
left join CRMDeals D on D.Id =T.DealId
left join GENCompanies C on C.Id = D.CompanyId
left join GENBranches B on B.Id = WO.BranchId
left join GENBrands Br on Br.Id = WO.BrandId
Left join TCRWorkItems TWO on TWO.WorkOrderId = WO.Id
Left join ItemFlatDatas IFD on TWO.ItemFLatDataId = IFD.Id
where WO.Id = @Id
end
GO
