/****** Object:  StoredProcedure [dbo].[RPT_GET_ClassRoomPricing]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [dbo].[RPT_GET_ClassRoomPricing] 
@DateF datetime=null,
@DateTo datetime=null,
@VCRId bigint,
@Cost decimal(18,4) = null,
@TotalCost decimal(18,4) = null,
@companyId bigint = null,
@NoOfDays int = null,
@groupTypeId int = null
AS
Begin
select * from (
select GENClassrooms.Id,GENClassrooms.FromDateTime,isnull(GENCompanies.Name,N'غير محددة الجهة') as CompanyName,GENClassrooms.Name as ClassroomName
,DATEDIFF(DAY,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime)+1 as NoOfDays,count(distinct GENClassroom_GENContact.StudentId) as NoOfStudents
,count(distinct case when GENClassroom_GENContact.BookingTypeId = 1 then GENClassroom_GENContact.StudentId end) as ConfirmedNoOfStudents,
(case when GENEntityPricings.PriceType = 1 and PaymentCondation = 0 then N'برسوم' when GENEntityPricings.PriceType = 1 and PaymentCondation = 2 then N'برسوم' when  PaymentCondation = 3 then N'مجاني' 
else N'لا يوجد' end) as PriceTypeName
,(case when GENEntityPricings.PriceType = 1  then isnull(GENEntityPricings.NetPrice,0) else Cast(0 as decimal(18,4)) end)  as NetPrice,
ROUND((case when GENEntityPricings.PriceType = 1  then isnull(GENEntityPricings.NetPrice,0)else Cast(0 as decimal(18,4)) end)
* count(distinct case when GENClassroom_GENContact.BookingTypeId = 1 then GENClassroom_GENContact.StudentId end),2)  AS ClassRoomPay,GENClassrooms.ToDateTime
,(case when GENClassrooms.GroupTypeId = 0 then N'مجاني' when GENClassrooms.GroupTypeId = 1 then N'رسوم' 
      when GENClassrooms.GroupTypeId = 2 then N'خطة' when GENClassrooms.GroupTypeId = 3 then N'تصديق' else '' end) as GroupType
,TargetGroup.Id as TargetGroupId, TargetGroup.Name as TargetGroupName
from GENClassrooms
left join GENCompanies on GENClassrooms.DestinationsId = GENCompanies.Id
left join GENCompanies as TargetGroup on GENClassrooms.CompanyId = TargetGroup.Id
left join GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
left join GENEntityPricings on GENEntityPricings.EntityId = GENClassrooms.id and BaseEntityId = 176 and GENEntityPricings.PriceType = 1
where ((cast(GENClassrooms.ToDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.ToDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.ToDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) 
and cast(GENClassrooms.ToDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0)) 
and (GENClassrooms.Id = @VCRId or @VCRId is null or @VCRId = 0 or len(@VCRId) = 0) and GENClassrooms.IsDeleted=0
and GENClassrooms.ClassroomCategoryId=1 
and GENClassrooms.ClassRoomStatus = 2
AND (@Cost IS NULL OR GENEntityPricings.NetPrice = @Cost)
AND (@companyId IS NULL OR TargetGroup.Id = @companyId)
AND (@groupTypeId IS NULL OR GENClassrooms.GroupTypeId = @groupTypeId)
AND (@NoOfDays IS NULL OR DATEDIFF(DAY,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime)+1 = @NoOfDays)
group by GENClassrooms.PaymentCondation,GENClassrooms.Id,GENClassrooms.FromDateTime,GENCompanies.Name,GENClassrooms.Name,GENClassrooms.ToDateTime,GENEntityPricings.PriceType,GENEntityPricings.NetPrice
,TargetGroup.Id,TargetGroup.Name,GENClassrooms.GroupTypeId
)as res
where (@TotalCost IS NULL OR ClassRoomPay = @TotalCost)
END
GO
/****** Object:  StoredProcedure [dbo].[RPT_GET_TrainerAchievement]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [dbo].[RPT_GET_TrainerAchievement] --'2022-09-07','2022-09-18',null,null,null
@DateF datetime,
@DateTo datetime,
@InstructorId bigint,
@VCRId bigint,
@Code nvarchar(MAX)
AS
Begin
Select TLMSClassroom_Session.InstructorId,GENEmployees.Name AS InstructorName,
GENClassrooms.Name AS VCRName,0 AS WorkingHours,DATEDIFF(MINUTE,TLMSClassroom_Session.FromDateTime,
TLMSClassroom_Session.ToDateTime) AS WorkingMin,GENClassrooms.Id AS VCRId,GENItems.Name AS SessionName,
GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Code AS VCRCode,TLMSClassroom_Session.Id AS SessionVCRId
From GENEmployees inner join 
TLMSClassroom_Session ON GENEmployees.Id=TLMSClassroom_Session.InstructorId inner join 
GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id inner join 
GENClassrooms ON TLMSClassroom_Session.ClassroomId=GENClassrooms.Id
where 
((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (GENEmployees.Id = @InstructorId or @InstructorId is null or @InstructorId = 0 or len(@InstructorId) = 0)
and (GENClassrooms.Id = @VCRId or @VCRId is null or @VCRId = 0 or len(@VCRId) = 0)
and (GENClassrooms.Code like '%'+@Code+'%' or @Code is null or len(@Code) =0)
and GENClassrooms.IsDeleted=0 and GENClassrooms.ClassroomCategoryId=1 and GENClassrooms.ClassRoomStatus=2 
END
GO
/****** Object:  StoredProcedure [dbo].[RPT_GET_TrainerAchievement_PerHour]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [dbo].[RPT_GET_TrainerAchievement_PerHour] 
@DateF datetime=null,
@DateTo datetime=null,
@InstructorId bigint,
@VCRId bigint
AS
Begin
Select distinct TLMSClassroom_Session.InstructorId,GENEmployees.Name AS InstructorName,
GENClassrooms.Name AS VCRName,0 AS WorkingHours,DATEDIFF(MINUTE,TLMSClassroom_Session.FromDateTime,
TLMSClassroom_Session.ToDateTime) AS WorkingMin,GENClassrooms.Id AS VCRId,GENItems.Name AS SessionName,
GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Code AS VCRCode,TLMSClassroom_Session.Id AS SessionVCRId,
FORMAT(TLMSClassroom_Session.FromDateTime,'HH:mm') AS FromTime,FORMAT(TLMSClassroom_Session.ToDateTime,'HH:mm') AS ToTime
From GENEmployees inner join 
Classroom_Session_Instructor on Classroom_Session_Instructor.InstructorId = GENEmployees.Id inner join 
TLMSClassroom_Session ON Classroom_Session_Instructor.SessionId=TLMSClassroom_Session.id inner join 
GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id inner join 
GENClassrooms ON TLMSClassroom_Session.ClassroomId=GENClassrooms.Id
where 
((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (GENEmployees.Id = @InstructorId or @InstructorId is null or @InstructorId = 0 or len(@InstructorId) = 0)
and (GENClassrooms.Id = @VCRId or @VCRId is null or @VCRId = 0 or len(@VCRId) = 0) and GENClassrooms.IsDeleted=0 
and GENClassrooms.ClassRoomStatus=2 and GENEmployees.IsActive = 1 and GENEmployees.IsDeleted = 0
--and (GENClassrooms.Code like '%'+@Code+'%' or @Code is null or len(@Code) =0)
END
GO
/****** Object:  StoredProcedure [dbo].[RPT_GET_TrainerPricing_PerHour]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [dbo].[RPT_GET_TrainerPricing_PerHour] 
    @DateF datetime = null,
    @DateTo datetime = null,
    @InstructorId bigint = null,
    @VCRId bigint = null,
    @Cost decimal(18,4) = null,
    @TotalCost decimal(18,4) = null,
    @SessionId bigint = null
AS
BEGIN
    SET NOCOUNT ON;

    WITH MainData AS (
        SELECT DISTINCT 
            Classroom_Session_Instructor.InstructorId,
            GENEmployees.Name AS InstructorName,
            GENEmployees.Code AS InstructorCode,
            GENEmployees.Telephone AS InstructorTelephone,
            GENEmployees.Position AS InstructorPosition,
            GENEmployees.Email AS InstructorEmail,
            GENItems.Name AS SessionName,
            GENClassrooms.Code AS VCRCode,
            GENClassrooms.Name AS VCRName,
            DATEDIFF(MINUTE, TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime) AS WorkingMin,
            GENClassrooms.Id AS VCRId,
            TLMSClassroom_Session.Id AS SessionVCRId,
            ISNULL(Classroom_Session_Instructor.NetPrice, 0) AS NetPrice,
            Classroom_Session_Instructor.PriceInstructorType,
              FORMAT(TLMSClassroom_Session.FromDateTime,'HH:mm') AS FromTime
              ,FORMAT(TLMSClassroom_Session.ToDateTime,'HH:mm') AS ToTime,
                GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,0 AS WorkingHours,
(case when Classroom_Session_Instructor.PriceInstructorType = 0 then N'بالساعه'
when Classroom_Session_Instructor.PriceInstructorType = 1 then N'باليوم'
when Classroom_Session_Instructor.PriceInstructorType = 2 then N'بالدوره'
when Classroom_Session_Instructor.PriceInstructorType = 3 then N'بالمحاضره'
when Classroom_Session_Instructor.PriceInstructorType = 3 then N'بالطالب'
else N'لا يوجد' end) as PriceInstructorTypeName
                ,
            -- نصيب الجلسة الواحدة (مهم جداً للجمع التراكمي الصحيح)
            CAST(CASE 
                WHEN Classroom_Session_Instructor.PriceInstructorType = 0 or Classroom_Session_Instructor.PriceInstructorType  is null THEN  
                    (ISNULL(Classroom_Session_Instructor.NetPrice,0) / 60.0) * DATEDIFF(MINUTE, TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime)
                
                WHEN Classroom_Session_Instructor.PriceInstructorType = 1 THEN 
                    ISNULL(Classroom_Session_Instructor.NetPrice, 0) / 
                    NULLIF(COUNT(TLMSClassroom_Session.Id) OVER(PARTITION BY Classroom_Session_Instructor.InstructorId, CAST(TLMSClassroom_Session.FromDateTime AS DATE)), 0)
                
                WHEN Classroom_Session_Instructor.PriceInstructorType = 2 THEN 
                    ISNULL(Classroom_Session_Instructor.NetPrice, 0) / 
                    NULLIF(COUNT(TLMSClassroom_Session.Id) OVER(PARTITION BY Classroom_Session_Instructor.InstructorId, GENClassrooms.Id), 0)
                
                WHEN Classroom_Session_Instructor.PriceInstructorType = 3 THEN 
                    ISNULL(Classroom_Session_Instructor.NetPrice, 0)
                
                WHEN Classroom_Session_Instructor.PriceInstructorType = 4 THEN 
                    (ISNULL(Classroom_Session_Instructor.NetPrice, 0) * (
                        SELECT COUNT(*) FROM GENClassroom_GENContact 
                        WHERE ClassroomId = GENClassrooms.Id AND BookingTypeId = 1
                    )) / NULLIF(COUNT(TLMSClassroom_Session.Id) OVER(PARTITION BY Classroom_Session_Instructor.InstructorId, GENClassrooms.Id), 0)
                
                ELSE 0 
            END AS decimal(18,2)) AS SessionPay
            ,PriceCat.Id as PriceCatId
            ,PriceCat.Name as PriceCatName
        FROM GENEmployees 
        INNER JOIN Classroom_Session_Instructor ON Classroom_Session_Instructor.InstructorId = GENEmployees.Id 
        INNER JOIN TLMSClassroom_Session ON Classroom_Session_Instructor.SessionId = TLMSClassroom_Session.Id 
        INNER JOIN GENClassrooms ON TLMSClassroom_Session.ClassroomId = GENClassrooms.Id
        LEFT JOIN GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id
        LEFT JOIN GENListValues on GENListValues.Id = GENEmployees.JobCategoryId
        LEFT JOIN GENListValues PriceCat on PriceCat.Id = GENListValues.ValueId1
        WHERE 
            ((CAST(GENClassrooms.FromDateTime AS DATE) >= CAST(@DateF AS DATE) AND CAST(GENClassrooms.FromDateTime AS DATE) <= CAST(@DateTo AS DATE)) OR (@DateF IS NULL))
            AND (GENEmployees.Id = @InstructorId OR @InstructorId IS NULL OR @InstructorId = 0)
            AND (GENClassrooms.Id = @VCRId OR @VCRId IS NULL OR @VCRId = 0)
            AND GENClassrooms.IsDeleted = 0 AND GENEmployees.IsActive = 1
            AND (@Cost IS NULL OR Classroom_Session_Instructor.NetPrice = @Cost)
            AND (@SessionId IS NULL OR GENItems.Id = @SessionId)

    )
    SELECT *, 
           -- ده اللي هتستخدمه First في الـ Group بتاع الـ Classroom
           SUM(SessionPay) OVER(PARTITION BY InstructorId, VCRId) AS ClassroomTotal,
           
           -- ده اللي هتستخدمه First في الـ Group بتاع الـ Instructor (الإجمالي العام الحقيقي)
           SUM(SessionPay) OVER(PARTITION BY InstructorId) AS InstructorTotal,
           
           -- الترقيم الجديد عشان نجمع اول قيمة بس من كل مدرب في الـ Header
           ROW_NUMBER() OVER(PARTITION BY InstructorId ORDER BY (SELECT NULL)) AS RowNum
           
    FROM MainData
    WHERE (@TotalCost IS NULL OR SessionPay = @TotalCost);
END
GO
/****** Object:  StoredProcedure [dbo].[Rpt_InstructorSessions]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_InstructorSessions] --[dbo].[Rpt_InstructorSessions] '2021-01-01','2026-12-31',null,null
	@DateF datetime=null,
	@DateTo datetime=null,
	@InstructorId bigint = null,
	@VCRId bigint = null,
	@classroomIds nvarchar(MAX) = null,
	@ClassRoomStatusIds nvarchar(MAX) = null,
	@GroupTypeIds nvarchar(MAX) = null,
	@ProsecutionIds nvarchar(MAX) = null,
	@CompanyIds nvarchar(MAX) = null,
	@courseIds nvarchar(MAX) = null,
	@SessionIds nvarchar(MAX) = null
AS
BEGIN
	SELECT 
		GENClassrooms.Id AS ClassroomId,
		GENClassrooms.Code AS ClassroomCode,
		GENClassrooms.Name AS ClassroomName,
		GENClassrooms.FromDateTime AS ClassroomFromDateTime,
		GENClassrooms.ToDateTime AS ClassroomToDateTime,
    
		-- إجمالي ساعات السيشنز بصيغة HH:MM على مستوى الـ Classroom
		CONCAT(
			ClassroomTotals.TotalClassroomMinutes / 60,
			':',
			FORMAT(ClassroomTotals.TotalClassroomMinutes % 60, '00')
		) AS VCRtotalCoursehours,

		GENEmployees.Id AS InstructorId,
		GENEmployees.IDNumber AS InstructorIDNumber,
		GENEmployees.Name AS InstructorName,
    
		-- هنا تم فك التجميع: إرجاع اسم السيشن الحالي في كل سطر
		TLMSClassroom_Session.Id AS SessionId,
		GENItems.name AS SessionName,
    SessionLang.Name as SessionLang,
		-- حساب إجمالي ساعات السيشنز للمحاضر داخل هذا الكلاس باستخدام (Window Functions)
		-- OVER(PARTITION BY ...) تحافظ على التجميع بدون الحاجة لـ GROUP BY في آخر الاستعلام
		CONCAT(
			SUM(DATEDIFF(MINUTE, TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime)) 
				OVER(PARTITION BY GENClassrooms.Id, GENEmployees.Id) / 60, 
			':', 
			FORMAT(SUM(DATEDIFF(MINUTE, TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime)) 
				OVER(PARTITION BY GENClassrooms.Id, GENEmployees.Id) % 60, '00')
		) AS TotalSessionsDuration,
		
		(
			SELECT COUNT(DISTINCT CSI_Inner.InstructorId)
			FROM Classroom_Session_Instructor CSI_Inner
			WHERE CSI_Inner.SessionId IN (
				-- نأتي بجميع الـ SessionIds التي تخص المحاضر الحالي داخل هذا الكلاس
				SELECT CSI_Sub.SessionId 
				FROM Classroom_Session_Instructor CSI_Sub
				INNER JOIN TLMSClassroom_Session TCS_Sub ON CSI_Sub.SessionId = TCS_Sub.Id
				WHERE CSI_Sub.InstructorId = GENEmployees.Id 
				AND TCS_Sub.ClassroomId = GENClassrooms.Id
			)
		) AS InstructorNumbers,
		
		PriceCat.Id as PriceCatId,
		PriceCat.Name as PriceCatName

	FROM GENEmployees 
	INNER JOIN Classroom_Session_Instructor ON Classroom_Session_Instructor.InstructorId = GENEmployees.Id
	INNER JOIN TLMSClassroom_Session ON Classroom_Session_Instructor.SessionId = TLMSClassroom_Session.Id	
	LEFT JOIN GENItems ON TLMSClassroom_Session.SessionId = GENItems.Id 
	LEFT JOIN GENListValues ON GENListValues.Id = GENEmployees.JobCategoryId
	LEFT JOIN GENListValues PriceCat ON PriceCat.Id = GENListValues.ValueId1
	INNER JOIN GENClassrooms ON TLMSClassroom_Session.ClassroomId = GENClassrooms.Id  
	LEFT JOIN GENListValues SessionLang ON SessionLang.Id = GENClassrooms.LanguageId 
	
	-- Subquery بتحسب إجمالي دقائق السيشنز على مستوى الـ Classroom بس
	INNER JOIN (
		SELECT 
			ClassroomId,
			SUM(DATEDIFF(MINUTE, FromDateTime, ToDateTime)) AS TotalClassroomMinutes
		FROM TLMSClassroom_Session
		WHERE TypeSession = 0
		GROUP BY ClassroomId
	) AS ClassroomTotals 
		ON GENClassrooms.Id = ClassroomTotals.ClassroomId

	WHERE (@DateF IS NULL OR cast(GENClassrooms.FromDateTime as date)  >= cast(@DateF as date) ) 
	AND (@DateTo IS NULL OR cast(GENClassrooms.ToDateTime as date) <= cast(@DateTo as date)) 
	AND (GENEmployees.Id = @InstructorId or @InstructorId is null or @InstructorId = 0 or len(@InstructorId) = 0)
	AND (GENClassrooms.Id = @VCRId or @VCRId is null or @VCRId = 0 or len(@VCRId) = 0) 
	AND GENClassrooms.IsDeleted=0 
	AND GENClassrooms.ProsecutionId = 0
	AND GENClassrooms.ClassRoomStatus=2 
	AND GENEmployees.IsDeleted = 0 
	AND GENEmployees.IsActive = 1 
	AND GENEmployees.EmployeeCategoryId = 1
	
	AND (@SessionIds IS NULL OR len(@SessionIds) =0 OR GENItems.Id IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@SessionIds, ',')))
	AND (@CompanyIds IS NULL OR len(@CompanyIds) =0 OR GENClassrooms.CompanyId IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@CompanyIds, ',')))
	AND (@courseIds IS NULL OR len(@courseIds) =0 OR GENClassrooms.CourseId IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@courseIds, ',')))
	AND (@ClassRoomStatusIds IS NULL OR len(@ClassRoomStatusIds) =0 OR GENClassrooms.ClassRoomStatus IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@ClassRoomStatusIds, ',')))
	AND (@GroupTypeIds IS NULL OR len(@GroupTypeIds) =0 OR GENClassrooms.GroupTypeId IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@GroupTypeIds, ',')))
	AND (@ProsecutionIds IS NULL OR len(@ProsecutionIds) =0 OR GENClassrooms.ProsecutionId IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@ProsecutionIds, ',')))
	AND (@classroomIds IS NULL OR len(@classroomIds) =0 OR GENClassrooms.Id IN (SELECT CAST(value AS BIGINT) FROM STRING_SPLIT(@classroomIds, ',')))
	
	-- تم إزالة الـ GROUP BY من هنا تماماً لأننا نستخدم OVER(PARTITION BY ...)
END
GO
/****** Object:  StoredProcedure [dbo].[Rpt_Offer]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_Offer]
@UserId nvarchar(128),
@WorkOrderId bigint
as
begin
select distinct C.Name as CompanyName ,E.Name as username,E.Position as EmployeeJob ,
(case when Co.SalutationName is null then Co.Name 
when RIGHT(Co.SalutationName,1) = '.' then Co.SalutationName + ' '+Co.Name else Co.SalutationName + '. ' +Co.Name end) as ContactName 
,Co.Position as ContactJob, WO.RichContent
 from GENEmployees E,TCRWorkOrders WO
 left join GENTCRs T on T.id = WO.TCRId
 left join CRMDeals D on D.Id = T.DealId 
 left join Contact_View Co on Co.id = D.ContactId
 left join GENCompanies C on C.id = D.CompanyId
 where E.UserId = @UserId and WO.Id = @WorkOrderId
end
GO
/****** Object:  StoredProcedure [dbo].[Rpt_SalesDeals]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Rpt_SalesDeals]
@ResponsiblePersonId bigint,
@StatusId bigint,
@DateFrom datetime,
@DateTo datetime,
@OpenDate bit,
@CloseDate bit,
@ExpectedCloseDate bit,
@DateCreated bit,
@DateUpdated bit
as
begin
select * from Deal_View
where (ResponsiblePersonId = @ResponsiblePersonId or @ResponsiblePersonId is null) 
and (ProcessId = @StatusId or @StatusId is null)
and (Cast(OpenDate as date) >= cast(@DateFrom as date) and cast(OpenDate as date) <= cast(@DateTo as date) or @OpenDate = 0)
and (Cast(CloseDate as date) >= cast(@DateFrom as date) and cast(CloseDate as date) <= cast(@DateTo as date) or @CloseDate = 0)
and (Cast(ExpectedCloseDate as date) >= cast(@DateFrom as date) and cast(ExpectedCloseDate as date) <= cast(@DateTo as date) or @ExpectedCloseDate = 0)
and (Cast(DateCreated as date) >= cast(@DateFrom as date) and cast(DateCreated as date) <= cast(@DateTo as date) or @DateCreated = 0)
and (Cast(DateUpdated as date) >= cast(@DateFrom as date) and cast(DateUpdated as date) <= cast(@DateTo as date) or @DateUpdated = 0)
end
GO
