/****** Object:  StoredProcedure [dbo].[Rpt_SelectExamGroupbyDimensionGroup]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create Proc [dbo].[Rpt_SelectExamGroupbyDimensionGroup] --Rpt_SelectExamGroupbyDimensionGroup  null,null ,null, null,null
(@StudentId bigint,@ExamId Bigint,@ClassroomId Bigint,@Date1 datetime,@Date2 datetime)
As
Begin
Select GENQuestionGroups.Id AS GENQuestionGroupId ,GENQuestionGroups.Name as GroupQuestionName,ExamId,ExamName,StudentId,StudentName,
IsNull(sum(GENExamAnswerDetails.Score),0)  as TotalScore
,COUNT(distinct PollCategoryandPolls.PollId) as CountQuestion,IsNull(sum(GENExamAnswerDetails.Weight),0) As AnsweWeight , 
IsNull((sum(GENExamAnswerDetails.Score) / sum(GENExamAnswerDetails.Weight)),0) As Perecentagem, GENExamAnswerHeaders.TotalQuestionsNumber
,GENExamAnswerHeaders.ClassroomName,GENExamAnswerHeaders.ClassroomId,GENExamAnswerHeaders.EndtDateTime
,count((case when GENExamAnswerDetails.Score > 0 then GENExamAnswerDetails.PollId else 0 end)) as AnsedQ,
(select top 1 GENPollCategories.Time from GENPollCategories where PollCategoryandPolls.PollCategoryId=GENPollCategories.Id ) as Time
,sum(isnull(GENExamAnswerDetails.AnswerFrequency,0)) as AnswerFrequency
from GENExamAnswerHeaders left join 
PollCategoryandPolls ON GENExamAnswerHeaders.ExamId=PollCategoryandPolls.PollCategoryId left join 
GENQuestionGroups ON PollCategoryandPolls.QuestionGroupId=GENQuestionGroups.Id left join 
GENExamAnswerDetails ON GENExamAnswerHeaders.Id = GENExamAnswerDetails.ExamAnswerHeaderId AND PollCategoryandPolls.PollId = GENExamAnswerDetails.PollId 
where PollCategoryandPolls.QuestionGroupId is not null and (StudentId=@StudentId or @StudentId is  null)  and
(GENExamAnswerHeaders.ExamId=@ExamId OR @ExamId is null) and (GENExamAnswerHeaders.ClassroomId is not null  or GENExamAnswerHeaders.ClassroomId= @ClassroomId)and 
 (((cast(GENExamAnswerHeaders.EndtDateTime as date) >= cast(@Date1 as date) and cast(GENExamAnswerHeaders.EndtDateTime as date) <= cast(@Date2 as date)))
or (@Date1 is null and @Date2 is null)
or (len(@Date1) = 0 and len(@Date2) = 0))
group by GENQuestionGroups.Name,ExamName,StudentId,StudentName,GENExamAnswerHeaders.TotalExamScore, GENQuestionGroups.Id,ExamId, GENExamAnswerHeaders.TotalQuestionsNumber,
GENExamAnswerHeaders.ClassroomName,GENExamAnswerHeaders.ClassroomId,GENExamAnswerHeaders.EndtDateTime,PollCategoryandPolls.PollCategoryId
End
GO
/****** Object:  StoredProcedure [dbo].[Rpt_VCRPollReport]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Rpt_VCRPollReport] --Rpt_VCRPollReport null,null,194
@DateF datetime = null
,@DateTo datetime = null
,@VCRId int
AS
SELECT * FROM
(SELECT distinct
null as DtlsId,
	VCR.Id as VCRId,
	null AS ExamId ,
	0 AS QuestionType,
	null AS Question,
	null AS Answer,
	VCR.Name as ClassroomName, 
	[Session].Id as SessionId, [Session].Name as SessionTitle, 
	Instructor.Name,
	GENRatings.Rating,
	GENRatings.Id AS RateId,
	Format(VCR.FromDateTime,'dd/MM/yyyy') AS VcrFromDate,Format(VCR.ToDateTime,'dd/MM/yyyy') AS VcrToDate,VCR.Code,
	Count(GENRatings.Id) AS NumberRaters
From TLMSClassroom_Session as [Session]
Inner Join GENClassrooms as VCR on [Session].ClassroomId=VCR.Id
Inner Join GENEmployees as Instructor on Instructor.Id=[Session].InstructorId
Inner Join GENRatings ON GENRatings.EntityId=[Session].Id AND GENRatings.BaseEntityId=198
 where ((cast(vcr.FromDateTime as date) >= cast(@DateF as date) and cast(VCR.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(VCR.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(VCR.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
 and (VCR.Id = @VCRId or @VCRId is null)
GROUP BY 
VCR.Id,VCR.Name,[Session].Id,Instructor.Name,GENRatings.Rating,[Session].Name ,GENRatings.Id,VCR.FromDateTime,VCR.ToDateTime,VCR.Code
UNION
SELECT distinct
    GENExamAnswerDetails.id as DtlsId,
	GENClassrooms.Id  AS VCRId ,
	GENPollCategories.Id AS ExamId ,
	GENPolls.QuestionType AS QuestionType,
	GENExamAnswerDetails.questionName AS Question,
	GENExamAnswerDetails.Article AS Answer,
	GENClassrooms.Name as ClassroomName, 
	null as SessionId,
	null as SessionTitle, 
	null as Name,
	GENPollAnswers.Weight as Rating,null AS RateId,
	Format(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDate,Format(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDate,
	GENClassrooms.Code, 0  AS NumberRaters
FROM GENClassrooms 
Inner Join GENExam_GENClassroom  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id 
INNER JOIN GENPollCategories ON GENExam_GENClassroom.ExamId=GENPollCategories.Id 
INNER JOIN GENExamAnswerHeaders ON GENPollCategories.Id=GENExamAnswerHeaders.ExamId and GENExamAnswerHeaders.ClassroomId = GENClassrooms.Id
INNER JOIN GENExamAnswerDetails ON GENExamAnswerHeaders.Id=GENExamAnswerDetails.ExamAnswerHeaderId
INNER JOIN GENPolls ON GENPolls.Id=GENExamAnswerDetails.PollId
left join GENPollAnswers on GENExamAnswerDetails.PollAnswerId = GENPollAnswers.Id
WHERE GENPollCategories.ExamType=12  and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
 and (GENClassrooms.Id = @VCRId or @VCRId is null)
) AS T 

order by case when T.QuestionType is null then 1 else 0 end, QuestionType
GO
/****** Object:  StoredProcedure [dbo].[Rpt_VCRPollReportNewRating]    Script Date: 7/1/2026 10:45:03 AM ******/
