CREATE PROCEDURE [dbo].[Rpt_VCRPollReportNewRating] --'01-01-2019','01-01-2026',null  --Rpt_VCRPollReportNewRating null,null,null
@DateF datetime = null
,@DateTo datetime = null
,@VCRId int
AS
SELECT *, (select count(distinct StudentId) from GENClassroom_GENContact where GENClassroom_GENContact.ClassroomId = VCRId ) AS NumberRaters
FROM
(SELECT distinct
1 as IType,
null as DtlsId,
	VCR.Id as VCRId,
	null AS ExamId ,
	0 AS QuestionType,
	null AS Question,
	null AS Answer,
	VCR.Name as ClassroomName, 
	[Session].Id as SessionId, [Session].Name as SessionTitle, 
	Instructor.Name,
	sum(case when GENRatings.Rating = 5 then 1 else 0 end) AS Exellent,
	sum(case when GENRatings.Rating = 4 then 1 else 0 end) as Good,
	sum(case when GENRatings.Rating = 3 then 1 else 0 end) as Normal,
	sum(case when GENRatings.Rating = 2 then 1 else 0 end) as Bad,
	sum(case when GENRatings.Rating = 1 then 1 else 0 end) as VeryBad,
	Format(VCR.FromDateTime,'dd/MM/yyyy') AS VcrFromDate
	,Format(VCR.ToDateTime,'dd/MM/yyyy') AS VcrToDate,
	VCR.Code
	,null as EntityId
	, null as Comment,
	    (CASE 
        WHEN SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END)
        WHEN SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END)
        WHEN SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END)
        WHEN SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 5 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 4 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 3 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENRatings.Rating = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENRatings.Rating = 2 THEN 1 ELSE 0 END)
        ELSE SUM(CASE WHEN GENRatings.Rating = 1 THEN 1 ELSE 0 END)
     END)  as RowMax 

From TLMSClassroom_Session as [Session]
Inner Join GENClassrooms as VCR on [Session].ClassroomId=VCR.Id
Inner Join GENEmployees as Instructor on Instructor.Id=[Session].InstructorId
Inner Join GENRatings ON GENRatings.EntityId=[Session].Id AND GENRatings.BaseEntityId=198 and EntityId2 is null
 where ((cast(vcr.FromDateTime as date) >= cast(@DateF as date) and cast(VCR.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(VCR.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) 
and cast(VCR.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
 and (VCR.Id = @VCRId or @VCRId is null)
GROUP BY 
VCR.Id,VCR.Name,[Session].Id,Instructor.Name,[Session].Name ,VCR.FromDateTime,VCR.ToDateTime,VCR.Code
union
SELECT distinct
2 as IType,
null as DtlsId,
	VCR.Id as VCRId,
	null AS ExamId ,
	0 AS QuestionType,
	null AS Question,
	null AS Answer,
	VCR.Name as ClassroomName, 
