        WHEN SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 5 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END)
        WHEN SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 5 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END)
        WHEN SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 5 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 4 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 3 THEN 1 ELSE 0 END) AND
             SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END) >= 
             SUM(CASE WHEN GENPollAnswers.Weight = 1 THEN 1 ELSE 0 END)
        THEN SUM(CASE WHEN GENPollAnswers.Weight = 2 THEN 1 ELSE 0 END)
        ELSE SUM(CASE WHEN GENPollAnswers.Weight = 1 THEN 1 ELSE 0 END)
     END) as RowMax
FROM GENClassrooms 
Inner Join GENExam_GENClassroom  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id 
INNER JOIN GENPollCategories ON GENExam_GENClassroom.ExamId=GENPollCategories.Id 
INNER JOIN GENExamAnswerHeaders ON GENPollCategories.Id=GENExamAnswerHeaders.ExamId and GENExamAnswerHeaders.ClassroomId = GENClassrooms.Id
INNER JOIN GENExamAnswerDetails ON GENExamAnswerHeaders.Id=GENExamAnswerDetails.ExamAnswerHeaderId
INNER JOIN GENPolls ON GENPolls.Id=GENExamAnswerDetails.PollId
left join GENPollAnswers on GENExamAnswerDetails.PollAnswerId = GENPollAnswers.Id
WHERE GENPollCategories.ExamType=12  
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0)) and (GENPolls.Question is null OR GENPolls.QuestionType = 0)
 and (GENClassrooms.Id = @VCRId or @VCRId is null)
 group by GENClassrooms.Id,GENPollCategories.Id,GENPolls.QuestionType,GENPolls.Question
 ,GENClassrooms.Name,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Code
 UNION
  SELECT 
6 as IType,
    null as DtlsId,
	GENClassrooms.Id  AS VCRId ,
	GENPollCategories.Id AS ExamId ,
	GENPolls.QuestionType AS QuestionType,
	GENPolls.Question AS Question,
	null AS Answer,
	GENClassrooms.Name as ClassroomName, 
	null as SessionId,
	null as SessionTitle, 
	null as Name,
	null AS Exellent,
	null as Good,
	null as Normal,
	null as Bad,
	null as VeryBad
	,
	Format(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDate
	,Format(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDate,
	GENClassrooms.Code
	,null as EntityId
	,GENPollAnswers.Answer as Comment,0 as RowMax
FROM GENClassrooms 
Inner Join GENExam_GENClassroom  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id 
INNER JOIN GENPollCategories ON GENExam_GENClassroom.ExamId=GENPollCategories.Id 
INNER JOIN GENExamAnswerHeaders ON GENPollCategories.Id=GENExamAnswerHeaders.ExamId and GENExamAnswerHeaders.ClassroomId = GENClassrooms.Id
INNER JOIN GENExamAnswerDetails ON GENExamAnswerHeaders.Id=GENExamAnswerDetails.ExamAnswerHeaderId
INNER JOIN GENPolls ON GENPolls.Id=GENExamAnswerDetails.PollId
left join GENPollAnswers on GENExamAnswerDetails.PollAnswerId = GENPollAnswers.Id
WHERE GENPollCategories.ExamType=12  
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0)) and (GENPolls.Question is null OR GENPolls.QuestionType = 0)
 and (GENClassrooms.Id = @VCRId or @VCRId is null)
 AND (GENPollAnswers.Weight = 0 or GENPollAnswers.Weight = 1)
 UNION 
 SELECT distinct
 7 as IType,
    GENExamAnswerDetails.id as DtlsId,
	GENClassrooms.Id  AS VCRId ,
	GENPollCategories.Id AS ExamId ,
	GENPolls.QuestionType AS QuestionType,
	GENExamAnswerDetails.questionName AS Question,
	GENExamAnswerDetails.Article AS Answer,
	GENClassrooms.Name as ClassroomName, 
	null as SessionId,
	null as SessionTitle, 
	null as Name,
	null AS Exellent,
	null as Good,
	null as Normal,
	null as Bad,
	null as VeryBad
	, Format(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDate
	,Format(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDate,
	GENClassrooms.Code
	,null as EntityId
	,null  as Comment,0 as RowMax
FROM GENClassrooms 
Inner Join GENExam_GENClassroom  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id 
INNER JOIN GENPollCategories ON GENExam_GENClassroom.ExamId=GENPollCategories.Id 
INNER JOIN GENExamAnswerHeaders ON GENPollCategories.Id=GENExamAnswerHeaders.ExamId and GENExamAnswerHeaders.ClassroomId = GENClassrooms.Id
INNER JOIN GENExamAnswerDetails ON GENExamAnswerHeaders.Id=GENExamAnswerDetails.ExamAnswerHeaderId
INNER JOIN GENPolls ON GENPolls.Id=GENExamAnswerDetails.PollId
left join GENPollAnswers on GENExamAnswerDetails.PollAnswerId = GENPollAnswers.Id
WHERE GENPollCategories.ExamType=12  and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
 and (GENClassrooms.Id = @VCRId or @VCRId is null) and GENPolls.QuestionType > 0
) AS T 

order by case when T.QuestionType is null then 1 else 0 end, QuestionType
GO
