create PROCEDURE [dbo].[Rpt_VCRPollReportQuestionRating] --Rpt_VCRPollReport null,null,null
@DateF datetime = null
,@DateTo datetime = null
,@VCRId int
AS
SELECT * FROM
(
SELECT distinct
    null as DtlsId,
	GENClassrooms.Id  AS VCRId ,
	GENPollCategories.Id AS ExamId ,
	GENPolls.QuestionType AS QuestionType,
	GENPolls.Question AS Question,
	null AS Answer,
	GENClassrooms.Name as ClassroomName, 
	null as SessionId,
	null as SessionTitle, 
	null as Name,
	sum(case when GENPollAnswers.Weight = 5 then 1 else 0 end) AS Exellent,
	sum(case when GENPollAnswers.Weight = 4 then 1 else 0 end) as Good,
	sum(case when GENPollAnswers.Weight = 3 then 1 else 0 end) as Normal,
	sum(case when GENPollAnswers.Weight = 2 then 1 else 0 end) as Bad,
	sum(case when GENPollAnswers.Weight = 1 then 1 else 0 end) as VeryBad
	,null AS RateId,
	Format(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDate,Format(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDate,
	GENClassrooms.Code, 0  AS NumberRaters
FROM GENClassrooms 
Inner Join GENExam_GENClassroom  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id 
INNER JOIN GENPollCategories ON GENExam_GENClassroom.ExamId=GENPollCategories.Id 
INNER JOIN GENExamAnswerHeaders ON GENPollCategories.Id=GENExamAnswerHeaders.ExamId and GENExamAnswerHeaders.ClassroomId = GENClassrooms.Id
INNER JOIN GENExamAnswerDetails ON GENExamAnswerHeaders.Id=GENExamAnswerDetails.ExamAnswerHeaderId
INNER JOIN GENPolls ON GENPolls.Id=GENExamAnswerDetails.PollId
left join GENPollAnswers on GENExamAnswerDetails.PollAnswerId = GENPollAnswers.Id
WHERE GENPollCategories.ExamType=12  
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
 and (GENClassrooms.Id = @VCRId or @VCRId is null)
 group by GENClassrooms.Id,GENPollCategories.Id,GENPolls.QuestionType,GENPolls.Question,GENClassrooms.Name,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Code
) AS T 

order by case when T.QuestionType is null then 1 else 0 end, QuestionType
GO
/****** Object:  StoredProcedure [dbo].[Rpt_VCRPollReportSessionRating]    Script Date: 7/1/2026 10:45:03 AM ******/
