CREATE PROC [dbo].[SearchData]  --[SearchData] N'مكافحة الفساد'  
@Name nvarchar(500)
AS
;WITH RecursiveCte AS
(
    SELECT  H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,H1.RichContent As Details,H1.Code AS String,H1.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H1.Id) as ImageCategory,H1.Description,IsNull(H1.ParentId,0)AS ParentId 
	,H1.Name as Path
	FROM GENTypeCategories H1
	where H1.ParentId is null
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name ,H2.RichContent As Details,H2.Code AS String,H2.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H2.Id) as ImageCategory,H2.Description,IsNull(H2.ParentId,0) AS ParentId
	,RCTE.Path 
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
SELECT GENTypes.Id,GENTypes.Name,GENTypes.Description,'GENType' AS Entity,RecursiveCte.Path  AS Type , dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image]
FROM GENTypes 
inner join  RecursiveCte ON GENTypes.TypeCategoryId=RecursiveCte.Id   
WHERE (GENTypes.Name like N'%' + @Name + '%' OR GENTypes.Description like N'%' + @Name + '%' 
OR GENTypes.String1 like N'%' + @Name + '%' OR GENTypes.String2 like N'%' + @Name + '%') AND GENTypes.IsActive = 1 AND GENTypes.IsPublish = 1

union

SELECT GENwikis.Id,GENwikis.Name,GENwikis.Description,'GENWiki' AS Entity,

 GENWikiCategories.Name AS Type,GENwikis.Image AS [Image]

FROM GENwikis
INNER JOIN dbo.GENWikiCategories ON dbo.GENWikiCategories.Id = GENwikis.WikiCategoryId
WHERE (GENwikis.Name like N'%' + @Name + '%' OR GENwikis.Description like N'%' + @Name + '%' OR GENWikiCategories.Name like N'%' + @Name + '%' OR GENWikiCategories.Description like N'%' + @Name + '%'
OR GENwikis.String1 like N'%' + @Name + '%' OR GENwikis.String2 like N'%' + @Name + '%' OR GENWikiCategories.String1 like N'%' + @Name + '%' OR GENWikiCategories.String2 like N'%' + @Name + '%')
AND GENwikis.IsPublish = 1

UNION

SELECT Wiki_TranslateView.WikiId AS Id,
dbo.fn_Wiki_Translate_ByKeyandId(Wiki_TranslateView.WikiId,'Name',Wiki_TranslateView.LanguageCode) AS Name ,
dbo.fn_Wiki_Translate_ByKeyandId(Wiki_TranslateView.WikiId,'Description',Wiki_TranslateView.LanguageCode) AS Description,
'GENWiki' AS Entity,
'TranslateWiki' AS Type,'' AS [Image]

FROM Wiki_TranslateView
LEFT JOIN dbo.GENWikiCategories ON dbo.GENWikiCategories.Id = Wiki_TranslateView.WikiCategoryId
WHERE (Wiki_TranslateView.Value like N'%' + @Name + '%' )
AND Wiki_TranslateView.IsActive = 1 AND Wiki_TranslateView.IsPublish = 1 AND GENWikiCategories.IsActive = 1 AND GENWikiCategories.IsPublish = 1

UNION 

SELECT Id,Name,Description,'GENWikiCategory' AS Entity
,'GENWikiCategory' AS Type,'' AS [Image] FROM GENWikiCategories
WHERE (GENWikiCategories.Name like N'%' + @Name + '%' OR GENWikiCategories.Description like N'%' + @Name + '%'
OR GENWikiCategories.String1 like N'%' + @Name + '%' OR GENWikiCategories.String2 like N'%' + @Name + '%') AND GENWikiCategories.IsActive = 1 AND GENWikiCategories.IsPublish = 1


UNION 

SELECT Type_TranslateView.TypeId AS Id,
dbo.fn_Type_Translate_ByKeyandId(Type_TranslateView.TypeId,'Name',Type_TranslateView.LanguageCode) AS Name ,
dbo.fn_Type_Translate_ByKeyandId(Type_TranslateView.TypeId,'Description',Type_TranslateView.LanguageCode) AS Description,
'GENType' AS Entity,'TranslateCourse' AS Type,'' AS [Image]
FROM Type_TranslateView
WHERE (Type_TranslateView.Value like N'%' + @Name + '%') AND Type_TranslateView.IsActive = 1 AND Type_TranslateView.IsPublish = 1
GO
