/****** Object:  StoredProcedure [dbo].[SelectPOPIndex]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create PROCEDURE [dbo].[SelectPOPIndex] 

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENPageOfPages.Id
	               ,GENPageOfPages.Code
	              ,GENBackendPages.URL as Url 
				  ,GENPageOfPages.Name
				  ,GENPageOfPages.DateUpdated
				  ,GENPageOfPages.DateCreated
	             ,GENPageOfPages.CreateType
				
				 ,(case when GENPageOfPages.EntityId is not null then BaseEntities.Name else '' end) as EntityName
		
				 ,(case GENPageOfPages.popTypeId  
				  when 0 then 'CRUD' 
				  when 1 then 'Search' 
				  when 3 then 'QuickAdd' 
				  when 4 then 'PopUp'
				  when 5 then 'CRUDQuick'
				  when 6 then 'CRUDDashboard'
				  when 7 then 'Report'  end) as PageofPageType
				 ,GENPageOfPages.BackendPageId
				 ,GENTypeStatus.Name as StatustypeName
				  ,(case GENPageOfPages.CreateType  
				  when 0 then 'Cols' 
				  when 1 then 'Rows' 
				  when 2 then 'Tabs'  end) as CreateTypeName
				  --CRUD = 0, Search = 1, QuickAdd = 3, PopUp = 4, CRUDQuick = 5, CRUDDashboard = 6, Report = 7
				,(case GENPageOfPages.popTypeId  
				  when 0 then 'CRUD' 
				  when 1 then 'Search' 
				  when 3 then 'QuickAdd' 
				  when 4 then 'PopUp'
				  when 5 then 'CRUDQuick'
				  when 6 then 'CRUDDashboard'
				  when 7 then 'Report'  end) as PageofPageTypeName
				 ,GENBackendPages.Name as BackendPageName
				 , FORMAT (GENPageOfPages.DateCreated, 'dd/MM/yyyy') as DateCreatedString
				  , FORMAT (GENPageOfPages.DateUpdated, 'dd/MM/yyyy') as DateUpdatedString
				
	from GENPageOfPages left join 
	GENBackendPages on GENPageOfPages.BackendPageId= GENBackendPages.Id left join 
	BaseEntities on GENPageOfPages.EntityId = BaseEntities.Id left join 
	GENTypeStatus on GENPageOfPages.TypeStatusId=GENTypeStatus.Id 
	order by GENPageOfPages.DateUpdated desc;

END
GO
