CREATE Proc [dbo].[SP_Add_ContactONClassroom]  --949,20450,0,1
(@ClassroomId BIGINT,@ContactId BIGINT,@PaymentStatus BIGINT,@BookingStatus BIGINT)
as
if((select COUNT(Id) from GENClassroom_GENContact where ClassroomId = @ClassroomId and StudentId = @ContactId) = 0)
begin
insert into GENClassroom_GENContact(ClassroomId,StudentId,IsConfirmed,StudentStatus,Note,PaymentTypeId,BookingTypeId)
values(@ClassroomId,@ContactId,1,0,NULL,@PaymentStatus,@BookingStatus)
end
else
begin
update GENClassroom_GENContact
set PaymentTypeId = @PaymentStatus
,BookingTypeId = @BookingStatus
where ClassroomId = @ClassroomId and StudentId = @ContactId
end 
GO
