/****** Object:  StoredProcedure [dbo].[SP_AddContactProgressCompletion]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 02/09/2020
-- Description:	Add Contact completion progress
-- =============================================
CREATE PROCEDURE [dbo].[SP_AddContactProgressCompletion]
	-- Add the parameters for the stored procedure here
	@CreatedById nvarchar(max),
	@LastUpdatedById nvarchar(max),
	@ContactId bigint,
	@ClassroomId bigint,
	@BaseEntityId bigint,
	@EntityId bigint
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @CompletionId BIGINT
    -- Insert statements for procedure here
	INSERT INTO [dbo].[GENContactProgressCompletions]
           ([DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById] ,[TotalRequiredProgressValue]
           ,[ContactId] ,[ClassroomId] ,[BaseEntityId] ,[EntityId])
     VALUES
           (GETDATE() ,GETDATE() ,@CreatedById ,@LastUpdatedById ,100
           ,@ContactId ,@ClassroomId ,@BaseEntityId,@EntityId)

	SET @CompletionId = SCOPE_IDENTITY()
	--Insert Videos of current item in progress details
	INSERT INTO [dbo].[GENContactProgressCompletionDetails]
           ([DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById] ,[TotalRequiredProgressValue]
           ,[TotalVideoDuration] ,[FirstVideoPlay],[NextVideoPlay],[TotalFilePages] ,[CurrentReadPages] ,[FileVideoDownloaded] ,[ContactProgressCompletionId]
           ,[BaseEntityId] ,[EntityId])
     SELECT
           GETDATE(),GETDATE() ,@CreatedById ,@LastUpdatedById, 100
           ,VideoDurationSeconds ,0,0 ,0 ,0 ,0 ,@CompletionId
           ,181 ,GENItemVideos.Id
		FROM GENItemVideos
		WHERE ItemId = @EntityId

	
	INSERT INTO [dbo].[GENContactProgressCompletionDetails]
           ([DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById] ,[TotalRequiredProgressValue]
           ,[TotalVideoDuration] ,[FirstVideoPlay],[NextVideoPlay] ,[TotalFilePages] ,[CurrentReadPages] ,[FileVideoDownloaded] ,[ContactProgressCompletionId]
           ,[BaseEntityId] ,[EntityId])
     SELECT
           GETDATE() ,GETDATE() ,@CreatedById ,@LastUpdatedById,100
           ,0 ,0,0 ,TotalPages ,0 ,0 ,@CompletionId
           ,182 ,GENItemFiles.Id
		FROM GENItemFiles
		WHERE ItemId = @EntityId
END
GO
