GO
CREATE Proc [dbo].[SP_AddExamHeader] (@Bool1 bit,@Bool2 bit,@Bool3 bit,@Bool4 bit,@Bool5 bit,@CheckoutBy nvarchar(128)
,@CheckoutDate datetime,@ClassroomEndTimeExam datetime,@ClassroomId bigint  = NULL,@ClassroomName nvarchar(Max)
,@ClassroomStartTimeExam datetime,@Code nvarchar(max)
,@CourseId bigint = NULL,@CourseName nvarchar(max),@CreatedById nvarchar(max),@DateCreated datetime,@DateUpdated datetime,
@EndtDateTime datetime,@ExamId bigint,@ExamName nvarchar(max)
,@ExamTime datetime,@ExamWeight int,@InstructorId bigint,
@InstructorName nvarchar(max),@IsCheckedOut bit,@LastUpdatedById nvarchar(128)
,@Name nvarchar(max),@ScoreDegree int,@StartDateTime datetime,@StudentId bigint
,@StudentName nvarchar(max),@Timeout int,@ExpectedExamEndDate datetime)
as
if((select COUNT(id) from GENExamAnswerHeaders where ExamId = @ExamId and ClassroomId =	@ClassroomId and StudentId = @StudentId) = 0)
begin
Insert into GENExamAnswerHeaders (Bool1,Bool2,Bool3,Bool4,Bool5,CheckoutBy,CheckoutDate,ClassroomEndTimeExam,ClassroomId,ClassroomName,ClassroomStartTimeExam,Code
,CourseId,CourseName,CreatedById,DateCreated,DateUpdated,EndtDateTime,ExamId,ExamName
,ExamTime,ExamWeight,InstructorId,InstructorName,IsCheckedOut,LastUpdatedById,Name,ScoreDegree,StartDateTime,StudentId
,StudentName,[Timeout],ExpectedExamEndDate)
values(
@Bool1,@Bool2,@Bool3,@Bool4,@Bool5,@CheckoutBy,@CheckoutDate,@ClassroomEndTimeExam,@ClassroomId,@ClassroomName,@ClassroomStartTimeExam,@Code
,@CourseId,@CourseName,@CreatedById,@DateCreated,@DateUpdated,@EndtDateTime,@ExamId,@ExamName
,@ExamTime,@ExamWeight,@InstructorId,@InstructorName,@IsCheckedOut,@LastUpdatedById,@Name,@ScoreDegree,@StartDateTime,@StudentId
,@StudentName,@Timeout,@ExpectedExamEndDate
)
SELECT CAST(SCOPE_IDENTITY() AS bigint) AS [NewId]
end
else 
begin
select id from GENExamAnswerHeaders where ExamId = @ExamId and ClassroomId =	@ClassroomId and StudentId = @StudentId
end
GO
