-- =============================================
CREATE PROCEDURE [dbo].[SP_AddMessageNotification]
	-- Add the parameters for the stored procedure here
	@MessageCode nvarchar(max) = NULL,
	@Image nvarchar(max) = NULL,
	@IconImg nvarchar(max) = NULL,
	@UserId nvarchar(max) = NULL,
	@PushId nvarchar(max) = NULL,
	@OS int = NULL,
	@Type int = NULL,
	@LastUpdatedById nvarchar(max) = NULL,
	@DateCreated datetime = NULL,
	@DateUpdated datetime = NULL,
	@CreatedById nvarchar(max) = NULL,
	@SendDateTime datetime = NULL,
	@NoOfRetry int = NULL,
	@GroupName nvarchar(max) = NULL,
	@Message nvarchar(max) = NULL,
	@EntityId bigint = NULL,
	@BaseEntityId bigint = NULL,
	@NotificationType int = NULL,
	@EventTypeId int = NULL,
	@Number int = NULL,
	@ActionTypeId bigint = NULL,
	@NotificationDate datetime = NULL,
	@IsNew bit = NULL,
	@StatusId bigint = NULL,
	@AttachmentURL nvarchar(max) = NULL,
	@Media_Ids nvarchar(max) = NULL,
	@Latitude real = NULL,
	@Longitude real = NULL,
	@PlaceId bigint = NULL,
	@SchedulerId bigint = NULL,
	@DisplayCoordinates bigint = NULL,
	@TrimUser bit = NULL,
	@IsRead bit = NULL,
	@IsSystemNotification bit = NULL,
	@ModuleId bigint = NULL,
	@ModuleName nvarchar(max) = NULL,
	@PageId bigint = NULL,
	@PageName nvarchar(max) = NULL,
	@FieldId bigint = NULL,
	@ToId bigint = NULL,
	@ToName nvarchar(max) = NULL,
	@FieldName nvarchar(max) = NULL,
	@StatusName nvarchar(max) = NULL,
	@CreatedByName nvarchar(max) = NULL,
	@Email nvarchar(max) = NULL,
	@Title nvarchar(max) = NULL,
	@URL nvarchar(max) = NULL,
	@IsSound bit = NULL,
	@Priority bit = NULL,
	@IsDelivered bit = NULL,
	@IsMail bit = NULL,
	@IsiPhone bit = NULL,
	@IsAndroid bit = NULL,
	@IsFacebook bit = NULL,
	@Isweb bit = NULL,
	@IsDeleted bit = NULL,
	@IsCanceled bit = NULL,
	@IsiPhoneSent bit = NULL,
	@IsAndroidSent bit = NULL,
	@IsFacbookSent bit = NULL,
	@IsTwitter bit = NULL,
	@IsTwitterSent bit = NULL,
	@IsEmail bit = NULL,
	@Sound nvarchar(max) = NULL,
	@DeletedTime datetime = NULL,
	@CanceledTime datetime = NULL,
	@ReadTime datetime = NULL,
	@ReadCount int = NULL,
	@DeliveredTime datetime = NULL,
	@NotificationReadTime datetime = NULL,
	@SnoozTime datetime = NULL,
	@TypeofNotification nvarchar(max) = NULL,
	@LangId bigint = NULL,
	@CompanyId bigint = NULL,
	@BulkPushNotificationId bigint = NULL,
	@Code nvarchar(max) = NULL,
	@Name nvarchar(max) = NULL,
	@Description nvarchar(max) = NULL, @ColorCode nvarchar(max) = NULL
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	INSERT INTO [dbo].[GENPushNotifications]
           ([MessageCode],[Image],[IconImg],[UserId],[PushId],[OS],[Type],[LastUpdatedById],[DateCreated],[DateUpdated],[CreatedById],[SendDateTime],[NoOfRetry],[GroupName]
           ,[Message],[EntityId],[BaseEntityId],[NotificationType],[EventTypeId],[Number],[ActionTypeId],[NotificationDate],[IsNew],[StatusId],[AttachmentURL],[Media_Ids]
           ,[Latitude],[Longitude],[PlaceId],[SchedulerId],[DisplayCoordinates],[TrimUser],[IsRead],[IsSystemNotification],[ModuleId],[ModuleName],[PageId],[PageName]
           ,[FieldId],[ToId],[ToName],[FieldName],[StatusName],[CreatedByName],[Email],[Title],[URL],[IsSound],[Priority],[IsDelivered],[IsMail],[IsiPhone],[IsAndroid]
           ,[IsFacebook],[Isweb],[IsDeleted],[IsCanceled],[IsiPhoneSent],[IsAndroidSent],[IsFacbookSent],[IsTwitter],[IsTwitterSent],[IsEmail],[Sound],[DeletedTime]
           ,[CanceledTime],[ReadTime],[ReadCount],[DeliveredTime],[NotificationReadTime],[SnoozTime],[TypeofNotification],[Bool6],[Bool7],[Bool8],[Bool9],[Bool10],[Bool11]
           ,[Bool12],[Bool13],[Bool14],[Bool15],[Bool16],[Bool17],[Bool18],[Bool19],[Bool20],[LangId],[CompanyId],[BulkPushNotificationId],[Code],[Name],[Description]
           ,[ColorCode],[IsCheckedOut],[CheckoutDate],[Timeout],[DisplayOrdering],[CheckoutBy],[IconId],[IsPosted],[Bool1],[Bool2],[Bool3],[Bool4],[Bool5])
     VALUES
