CREATE Proc [dbo].[SP_AllManagedById] (@employeeId Bigint)

as
with employee_cte as (
Select Id as MainEmployeeId,
EmployeeId as EmployeeId,
0 as Level_
from GENEmployees
where Id = @employeeId

union all

select p1.Id as MainEmployeeId,
 p1.EmployeeId as EmployeeId,
Level_ + 1
 
from employee_cte p2
inner join GENEmployees p1 on p1.EmployeeId =p2.MainEmployeeId
 
)
select MainEmployeeId from employee_cte
GO
