/****** Object:  StoredProcedure [dbo].[SP_AllParticipation_Diplom]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_AllParticipation_Diplom]--SP_AllParticipation_Diplom'2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
as
begin
truncate table TempGenTypeCategories
INSERT INTO TempGenTypeCategories
EXEC GetGenTypeCategoriesAndChildren @Id = 23;
select GENContacts.Name
from  GENContact_Talent inner join
	GENContacts ON GENContact_Talent.ContactId=GENContacts.Id  
	Where GENContact_Talent.TalentId   in (
select GENTalents.id
FROM TempGenTypeCategories 
inner join GENTalents on GENTalents.TalentBuilderId = TempGenTypeCategories.TalentBuilderId
--left join GENContact_Talent on GENContact_Talent.TalentBuilderId = GENTalents.id
where  GENTalents.isdeleted=0 and GENTalents.IsActive = 1
and  ((cast(GENTalents.DateCreated as date) >= cast(@DateF as date) and cast(GENTalents.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENTalents.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENTalents.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
)


end
GO
