/****** Object:  StoredProcedure [dbo].[SP_ApplyVoucher]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE proc [dbo].[SP_ApplyVoucher](@ContactId BIGINT, @Code nvarchar(500), @res bit output)
as
begin
	Declare @ContactToTalentID BIGINT = 0;
	Declare @VoucherID BIGINT = 0;
	set @ContactToTalentID = (select top 1 Id from [dbo].[GENContact_Talent] where ContactId = @ContactId and InProgress = 0 and VoucherId is null order by id desc);
	set @VoucherID = (SELECT Id FROM [dbo].[GENDiscountCards] where [Code] = @Code and IsUsed = 0 and IsTerminated = 0 and ExpiredDate <= GETDATE());
	if @ContactToTalentID > 0 and @VoucherID > 0
	begin
		update [dbo].[GENDiscountCards] set IsUsed = 1 where Id = @VoucherID;
		update[dbo].[GENContact_Talent] set VoucherId = @VoucherID where Id = @ContactToTalentID;
		set @res = 1;
	end
	else
	begin
		set @res = 0;
	end
end
GO
