CREATE Proc [dbo].[SP_AspNetUsers_UpdateForotToken] (@email nvarchar(250), @token nvarchar(max))
as
update AspNetUsers set ForgotPassword =@token



where email =@email

declare @UserId nvarchar(128)

select @UserId =  Id   from AspNetUsers  where email =@email
update GENContacts set ForgetPasswordRequestdate = GetDate()
WHERE UserId = @UserId

update GENEmployees set ForgetPasswordRequestdate = GetDate()
WHERE UserId = @UserId

