CREATE Proc [dbo].[SP_BK_ExportCourses]
AS
Begin
select GENTypes.Code AS CourseCode,GENTypes.Name AS CourseName,GENTypes.Int1 AS CourseTime,GENTypes.Int2 AS CourseDays,
(CASE WHEN dbo.GENTypes.CourseType = 0 THEN 
N'Classroom' ELSE CASE WHEN dbo.GENTypes.CourseType = 1 THEN N'SelfStudy' ELSE
CASE WHEN dbo.GENTypes.CourseType = 2 THEN N'Both' ELSE N'' END END END) AS CourseTypeString ,GENTypes.DateCreated,AspNetUsers.Name AS LastUpdatedByName
from GENTypes left join 
AspNetUsers ON GENTypes.LastUpdatedById =AspNetUsers.Id

where IsDeleted=0
--where GENTypes.TypeCategoryId=3
order by DateCreated desc
End
GO
