CREATE Proc [dbo].[SP_BK_ExportEvents] --  SP_BK_ExportEvents null,null,null,2
@FromDate datetime = null,
@ToDate datetime = null,
@Status int = null,
@ClassroomCategoryId int =null
AS
--select * from genclassrooms WHERE ClassroomCategoryId = 2 and IsDeleted = 0 ORDER BY DateUpdated DESC
--select GENNews.Code AS EventCode,GENNews.Name AS EventName,
--GENNews.DisplayDate ,GENNews.DateCreated,AspNetUsers.Name AS LastUpdatedByName
--from GENNews left join 
--AspNetUsers ON GENNews.LastUpdatedById =AspNetUsers.Id 
--order by DateCreated desc

Begin
SET DATEFIRST 6;   
 DEclare @WeekStartDate as DateTime;
 DEclare @WeekEndDate as DateTime;
 DEclare @WeekStartDateAdd as DateTime
 DEclare @WeekEndDateAdd as DateTime
 SELECT @WeekStartDate  =    DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));  
 SELECT @WeekEndDate   =  DATEADD(DAY, 7 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));
  SELECT @WeekStartDateAdd  =    DATEADD(DAY,7,@WeekStartDate);
  SELECT @WeekEndDateAdd  =    DATEADD(DAY,7, @WeekEndDate);

IF @Status = 2

select LV.Id GroupId, GENClassrooms.Id as ClassRoomId, LV.code AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
GENClassrooms.Int1 + isnull(dbo.fn_VcrStudentCount(GENClassrooms.id),0) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
inner join GENListValues LV  on LV.Id = GENClassrooms.EventTypeId and LV.isdeleted = 0 and LV.isActive = 1
WHERE
(@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR FromDateTime <= @ToDate)
AND(@Status IS NULL OR @Status=-1 OR GENClassrooms.ClassRoomStatus= @Status) and(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )
and GENClassrooms.IsDeleted=0
order by DateCreated desc

else if @Status =3


select  LV.Id GroupId, GENClassrooms.Id as ClassRoomId, LV.code AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
GENClassrooms.Int1+ isnull(dbo.fn_VcrStudentCount(GENClassrooms.id),0) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id  left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
inner join GENListValues LV  on LV.Id = GENClassrooms.EventTypeId and LV.isdeleted = 0 and LV.isActive = 1
WHERE
(@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR FromDateTime <= @ToDate)
AND(@Status IS NULL OR @Status=-1 OR GENClassrooms.ClassRoomStatus <> 2) 
and(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId ) 

and GENClassrooms.IsDeleted=0
order by DateCreated desc

else if @Status =4

select  LV.Id GroupId, GENClassrooms.Id as ClassRoomId, LV.code AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
GENClassrooms.Int1+ isnull(dbo.fn_VcrStudentCount(GENClassrooms.id),0) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.email left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
inner join GENListValues LV  on LV.Id = GENClassrooms.EventTypeId and LV.isdeleted = 0 and LV.isActive = 1
WHERE
(((Fromdatetime <= @WeekStartDate and ToDateTime >= @WeekStartDate) AND   (Fromdatetime <= @WeekEndDate and ToDateTime >= @WeekEndDate))  OR
(@WeekStartDate <= Fromdatetime AND @WeekStartDate >= Fromdatetime) OR (@WeekStartDate <= ToDateTime AND @WeekEndDate >= ToDateTime))  

and
(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )
and GENClassrooms.IsDeleted=0
order by DateCreated desc

else if @Status =5


select  LV.Id GroupId, GENClassrooms.Id as ClassRoomId, LV.code AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
 GENClassrooms.Int1+ isnull(dbo.fn_VcrStudentCount(GENClassrooms.id),0) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName --dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id)
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
inner join GENListValues LV  on LV.Id = GENClassrooms.EventTypeId and LV.isdeleted = 0 and LV.isActive = 1
WHERE
 (((Fromdatetime <= @WeekStartDateAdd and ToDateTime >= @WeekStartDateAdd) AND   (Fromdatetime <= @WeekEndDateAdd and ToDateTime >= @WeekEndDateAdd))
 OR (@WeekStartDateAdd <= Fromdatetime AND @WeekEndDateAdd >= Fromdatetime) 
 OR (@WeekStartDateAdd <= ToDateTime AND @WeekEndDateAdd >= ToDateTime))
and
(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )

and GENClassrooms.IsDeleted=0
order by DateCreated desc


else 

select  LV.Id GroupId, GENClassrooms.Id as ClassRoomId, LV.code AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
 GENClassrooms.int1+ isnull(dbo.fn_VcrStudentCount(GENClassrooms.id),0) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
left join GENListValues LV  on LV.Id = GENClassrooms.EventTypeId and LV.isdeleted = 0 and LV.isActive = 1
WHERE
(@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR FromDateTime <= @ToDate)
AND(@Status IS NULL OR @Status=-1 OR GENClassrooms.ClassRoomStatus <> @Status) and(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )
and GENClassrooms.IsDeleted=0
order by DateCreated desc

End

--select genclassrooms.EventTypeId,genclassrooms.Name,genclassrooms.FromDateTime,ToDateTime from genclassrooms WHERE ClassroomCategoryId = 2 and IsDeleted = 0 ORDER BY DateUpdated DESC
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_ExportFeedback]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_BK_ExportFeedback] (@FeedBackCategoryId bigint=null,
@ClassroomId bigint = null,
@FromDate Date=null,
@ToDate Date=null,
@Name nvarchar(MAX),
@Type nvarchar(MAX)
)
as
begin
select GENFeedBacks.*, GENTypes.Name AS CourseName
from GENFeedBacks left join
GENTypes ON GENFeedBacks.CourseId=GENTypes.Id
where GENFeedBacks.FeedBackCategoryId=@FeedBackCategoryId  and
 (@FromDate IS NULL OR len(@FromDate) = 0 OR  @FromDate<=cast(GENFeedBacks.DateCreated as date))
AND (@ToDate IS NULL OR len(@ToDate) = 0 OR  cast(GENFeedBacks.DateCreated as date)<=@ToDate)
AND (GENFeedBacks.Name like '%'+@Name+'%' or @Name is null or len(@Name) =0)
AND (@ClassroomId IS NULL OR GENFeedBacks.ClassroomId =@ClassroomId)
AND (GENFeedBacks.Subject like '%'+@Type+'%' or @Type is null or len(@Type) =0)
order by GENFeedBacks.DateUpdated desc
end
GO
