CREATE Proc [dbo].[SP_BK_ExportStudents] 
AS
Begin
select GENContacts.Name AS StudentName,GENContacts.DefaultEmail AS StudentEmail,GENContacts.DefaultAddress AS StudentAddress,GENContacts.Position AS StudentTitle,
GENContacts.IDNumber,GENContacts.DefaultPhone AS StudentPhone,GENContacts.DateCreated,AspNetUsers.Name AS LastUpdatedByName,
GENCompanies.Name AS CompanyName,Lang.Name AS LanguageName,Qualifi.Name AS QualificationName,GENContacts.String1 AS  BirthPlace ,MaritalStat.Name AS MaritalStatusName,
FORMAT(GENContacts.BirthDate,'dd/MM/yyyy') AS BirthDateString,GENContacts.CompanyAddressString,GENContacts.mobile1,GENContacts.mobile2,
GENContacts.string3 AS  FunctionalClass ,GENContacts.IsActive,GENContacts.Bool1 AS Private,GENContacts.Bool2 AS Governmental,GENContacts.Bool3 AS Intheclass,
GENContacts.Bool4 AS DistanceEducation,GENContacts.Bool5 AS Individually,GENContacts.Other AS Destinations,GENContacts.Training AS ResbonsiblePersonDestinations,
GENContacts.Other2 AS CivilSocity,dbo.fnCount_VcrsByContactId(GENContacts.Id)  as VCRCount
from GENContacts left join 
AspNetUsers ON GENContacts.LastUpdatedById =AspNetUsers.Id left join 
GENCompanies ON GENContacts.OrganizationId=GENCompanies.Id  left join 
GENListValues Lang  ON GENContacts.LanguageId=Lang.Id left join 
GENListValues Qualifi ON  GENContacts.QualificationId=Qualifi.Id left join 
GENListValues MaritalStat ON  GENContacts.MartialStatusId=MaritalStat.Id 
where GENContacts.IsDeleted=0
order by DateCreated desc
End
