CREATE Proc [dbo].[SP_BK_ExportTraineres] (@EmployeeCategoryId int =null)
AS
Begin
select GENEmployees.Id,GENEmployees.Name AS TrainerName,GENEmployees.Email AS TrainerEmail,GENEmployees.Address AS TrainerAddress,GENEmployees.Position AS TrainerTitle,
GENEmployees.Telephone AS TrainerPhone,GENEmployees.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENEmployees.Code as TrainerCode,GENEmployees.IsActive as TrainerActive
,GENEmployees.AccountNumber,GENEmployees.IDNumber,GENEmployees.JobCategoryId,GENListValues.Name as JobCategoryName,GENListValues.Code as JobCategoryCode
,Cat.Id as CatID,Cat.Name as CatName,Cat.Code as CatCode,
	TLMSClassroom_Session.Id AS SessionId,
		GENItems.name AS SessionName,
    SessionLang.Name as SessionLang
from GENEmployees left join 
AspNetUsers ON GENEmployees.LastUpdatedById =AspNetUsers.Id
LEFT JOIN GENListValues on GENListValues.Id = GENEmployees.JobCategoryId
LEFT JOIN GENListValues Cat on Cat.Id = GENListValues.ValueId1
LEFT JOIN Classroom_Session_Instructor ON Classroom_Session_Instructor.InstructorId = GENEmployees.Id
LEFT JOIN TLMSClassroom_Session ON Classroom_Session_Instructor.SessionId = TLMSClassroom_Session.Id	
LEFT JOIN GENItems ON TLMSClassroom_Session.SessionId = GENItems.Id 
LEFT JOIN GENClassrooms ON TLMSClassroom_Session.ClassroomId = GENClassrooms.Id  
LEFT JOIN GENListValues SessionLang ON SessionLang.Id = GENClassrooms.LanguageId 
where (@EmployeeCategoryId IS NULL OR GENEmployees.EmployeeCategoryId=@EmployeeCategoryId ) and GENEmployees.IsDeleted=0
order by DateCreated desc
End
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_ExportVCRS]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
