GO
CREATE Proc [dbo].[SP_BK_ExportVCRS] --SP_BK_ExportVCRS null,null,null,1
@FromDate datetime = null,
@ToDate datetime = null,
@Status int = null,
@ClassroomCategoryId int =null
AS
Begin
SET DATEFIRST 6;   
 DEclare @WeekStartDate as DateTime;
 DEclare @WeekEndDate as DateTime;
 DEclare @WeekStartDateAdd as DateTime
 DEclare @WeekEndDateAdd as DateTime
 SELECT @WeekStartDate  =    DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));  
 SELECT @WeekEndDate   =  DATEADD(DAY, 7 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));
  SELECT @WeekStartDateAdd  =    DATEADD(DAY,7,@WeekStartDate);
  SELECT @WeekEndDateAdd  =    DATEADD(DAY,7, @WeekEndDate);

IF @Status = 2

select (case when GENClassrooms.ClassroomCategoryId = 2 then LV.code else GENClassrooms.code end) AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
Left join GENListValues LV on GENClassrooms.EventTypeId = LV.id
WHERE
(@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR FromDateTime <= @ToDate)
AND(@Status IS NULL OR @Status=-1 OR GENClassrooms.ClassRoomStatus= @Status) and(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )
and GENClassrooms.IsDeleted=0
order by DateCreated desc

else if @Status =3


select (case when GENClassrooms.ClassroomCategoryId = 2 then LV.code else GENClassrooms.code end) AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id  left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
Left join GENListValues LV on GENClassrooms.EventTypeId = LV.id
WHERE
(@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR FromDateTime <= @ToDate)
AND(@Status IS NULL OR @Status=-1 OR GENClassrooms.ClassRoomStatus <> 2) 
and(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId = @ClassroomCategoryId ) 

and GENClassrooms.IsDeleted=0
order by DateCreated desc

else if @Status =4

select (case when GENClassrooms.ClassroomCategoryId = 2 then LV.code else GENClassrooms.code end) AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.email left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
Left join GENListValues LV on GENClassrooms.EventTypeId = LV.id
WHERE
(((Fromdatetime <= @WeekStartDate and ToDateTime >= @WeekStartDate) AND   (Fromdatetime <= @WeekEndDate and ToDateTime >= @WeekEndDate))  OR
(@WeekStartDate <= Fromdatetime AND @WeekStartDate >= Fromdatetime) OR (@WeekStartDate <= ToDateTime AND @WeekEndDate >= ToDateTime))  

and
(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )
and GENClassrooms.IsDeleted=0
order by DateCreated desc

else if @Status =5


select (case when GENClassrooms.ClassroomCategoryId = 2 then LV.code else GENClassrooms.code end) AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
 dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName --dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id)
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
Left join GENListValues LV on GENClassrooms.EventTypeId = LV.id
WHERE
 (((Fromdatetime <= @WeekStartDateAdd and ToDateTime >= @WeekStartDateAdd) AND   (Fromdatetime <= @WeekEndDateAdd and ToDateTime >= @WeekEndDateAdd))
 OR (@WeekStartDateAdd <= Fromdatetime AND @WeekEndDateAdd >= Fromdatetime) 
 OR (@WeekStartDateAdd <= ToDateTime AND @WeekEndDateAdd >= ToDateTime))
and
(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )

and GENClassrooms.IsDeleted=0
order by DateCreated desc


else 

select (case when GENClassrooms.ClassroomCategoryId = 2 then LV.code else GENClassrooms.code end) AS VCRCode,GENClassrooms.Name AS VCRName,
dbo.GETClassRoomStatusName(GENClassrooms.ClassRoomStatus,'ar') AS VCRStatus,
GENClassrooms.FromDateTime ,GENClassrooms.ToDateTime,GENClassrooms.DateCreated,AspNetUsers.Name AS LastUpdatedByName,GENListValues.Name AS LangName
,GENClassrooms.String1 AS Supervisor,GENRooms.Name AS RoomName,Created.Name AS CreatedByName,
 dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id) AS ConfirmedCount,GENGovernorates.Name AS GovernorateName,GENCities.Name AS CityName
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
Left join GENListValues LV on GENClassrooms.EventTypeId = LV.id
WHERE
(@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR FromDateTime <= @ToDate)
AND(@Status IS NULL OR @Status=-1 OR GENClassrooms.ClassRoomStatus <> @Status) and(@ClassroomCategoryId IS NULL OR GENClassrooms.ClassroomCategoryId=@ClassroomCategoryId )
and GENClassrooms.IsDeleted=0
order by DateCreated desc

End
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_GetAllAgenda]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_BK_GetAllAgenda]  (@LangCode nvarchar(MAX), @StartTime DateTime, @EndTime DateTime)
AS
Begin
SELECT  DISTINCT dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS title,
dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode ) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS EntityId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,'#FFF' AS textColor,'#1169b2' AS color, 
'Course' AS EventType, 'cast_for_education' AS EventIcon,FORMAT(dbo.GENTypes.DateCreated,'yyyy-MM-dd') AS FromDate,FORMAT(dbo.GENTypes.DateCreated,'yyyy-MM-dd') AS ToDate
FROM  dbo.GENTypes 
WHERE GENTypes.IsAgenda=1 and GENTypes.IsPublish=1 and GENTypes.IsDeleted=0 and ((dbo.GENTypes.DateCreated <= @StartTime OR dbo.GENTypes.DateCreated >= @StartTime) AND (dbo.GENTypes.DateCreated >= @EndTime OR dbo.GENTypes.DateCreated <= @EndTime) or (@StartTime is null or @EndTime is null))


UNION 



SELECT  DISTINCT dbo.fn_Wiki_Translate_ByKeyandId(  dbo.GENWikis.Id,'Name', @LangCode) AS title,
dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description', @LangCode ) AS CourseGoals, dbo.GENWikis.DisplayOrdering AS DisplayOrder, dbo.GENWikis.IsPublish, dbo.GENWikis.IsActive, 
GENWikis.Image AS CourseImage, dbo.GENWikis.Id AS EntityId, 0 AS LectureCount,'#FFF' AS textColor,'#1169b2' AS color, GENWikiCategories.Name AS EventType, 
'cast_for_education' AS EventIcon,FORMAT(dbo.GENWikis.Date1,'yyyy-MM-dd') AS FromDate,FORMAT(dbo.GENWikis.DateCreated,'yyyy-MM-dd') AS ToDate
FROM  dbo.GENWikis inner join 
GENWikiCategories ON GENWikis.WikiCategoryId=GENWikiCategories.Id
WHERE GENWikis.IsAgenda=1 and GENWikis.IsPublish=1  and ((dbo.GENWikis.Date1 <= @StartTime OR dbo.GENWikis.Date1 >= @StartTime) AND (dbo.GENWikis.DateCreated >= @EndTime OR dbo.GENWikis.DateCreated <= @EndTime) or (@StartTime is null or @EndTime is null))


UNION 



SELECT  DISTINCT dbo.fn_News_Translate_ByKeyandId(  dbo.GENNews.Id,'Name', @LangCode) AS title,
dbo.fn_News_Translate_ByKeyandId( dbo.GENNews.Id,'Description', @LangCode ) AS CourseGoals, dbo.GENNews.DisplayOrdering AS DisplayOrder, dbo.GENNews.IsPublish, dbo.GENNews.IsActive, 
GENNews.Image AS CourseImage, dbo.GENNews.Id AS EntityId, 0 AS LectureCount,'#FFF' AS textColor,'#1169b2' AS color,'Event-News' AS EventType, 'cast_for_education' AS EventIcon,
FORMAT(dbo.GENNews.DateCreated,'yyyy-MM-dd') AS FromDate,FORMAT(dbo.GENNews.DisplayDate,'yyyy-MM-dd') AS ToDate
FROM  dbo.GENNews
WHERE GENNews.IsAgenda=1 and GENNews.IsPublish=1  and ((dbo.GENNews.DateCreated <= @StartTime OR dbo.GENNews.DateCreated >= @StartTime) AND (dbo.GENNews.DisplayDate >= @EndTime OR dbo.GENNews.DisplayDate <= @EndTime) or (@StartTime is null or @EndTime is null))



UNION 



SELECT  DISTINCT dbo.fn_ClassRoom_Translate_ByKeyandId(  dbo.GENClassrooms.Id,'Name', @LangCode) AS title,
dbo.fn_ClassRoom_Translate_ByKeyandId( dbo.GENClassrooms.Id,'Description', @LangCode ) AS CourseGoals, dbo.GENClassrooms.DisplayOrdering AS DisplayOrder, dbo.GENClassrooms.IsPublish, dbo.GENClassrooms.IsActive, 
dbo.fn_FirstImage_BaseEntityEntityId(176, dbo.GENClassrooms.Id) AS CourseImage, dbo.GENClassrooms.Id AS EntityId, 0 AS LectureCount,'#FFF' AS textColor,'#1169b2' AS color,
GENClassroomCategories.Name AS EventType, 'cast_for_education' AS EventIcon,FORMAT(dbo.GENClassrooms.FromDateTime,'yyyy-MM-dd') AS FromDate,FORMAT(dbo.GENClassrooms.ToDateTime,'yyyy-MM-dd') AS ToDate

FROM  dbo.GENClassrooms inner join 
GENClassroomCategories ON GENClassrooms.ClassroomCategoryId=GENClassroomCategories.Id
WHERE GENClassrooms.IsAgenda=1 and GENClassrooms.IsPublish=1  and ((dbo.GENClassrooms.FromDateTime <= @StartTime OR dbo.GENClassrooms.FromDateTime >= @StartTime) AND (dbo.GENClassrooms.ToDateTime >= @EndTime OR dbo.GENClassrooms.ToDateTime <= @EndTime)  or (@StartTime is null or @EndTime is null))

END
GO
