CREATE Proc [dbo].[SP_BK_GetCustomFieldTabs_Pop] (@PopId Bigint,@LangId bigint )
as
begin
select (CASE WHEN Translate_PageOfPageCustomFieldTabs.[Value] IS NOT NULL THEN Translate_PageOfPageCustomFieldTabs.[Value] ELSE PageOfPageCustomFieldTabs.[Name] END) AS Name,
PageOfPageCustomFieldTabs.[Value] as Id,PageOfPageCustomFieldTabs.BackgroundColor,PageOfPageCustomFieldTabs.TextColor,GENStyles.Name AS StyleName ,GENStyles.StyleValue

from PageOfPageFeilds left join 

PageOfPageCustomFieldTabs ON PageOfPageFeilds.Id=PageOfPageCustomFieldTabs.FieldId left join 
GENStyles ON PageOfPageCustomFieldTabs.styleId=GENStyles.Id left join 
Translate_PageOfPageCustomFieldTabs ON PageOfPageCustomFieldTabs.Id=Translate_PageOfPageCustomFieldTabs.PageOfPageCustomFieldTabsId AND Translate_PageOfPageCustomFieldTabs.[LangId] = @LangId

where PageOfPageFeilds.pageofpageId=@PopId and PageOfPageFeilds.istab=1

END
