/****** Object:  StoredProcedure [dbo].[SP_BK_GETLogsByCompanyId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[SP_BK_GETLogsByCompanyId] (@CompanyId bigint, @Id bigint)
 as
  select N'قام '+responsibleperson.Name as P1,
  N'ب'+(case
  WHEN GENOperationsLogs.Action=N'Delete' then N'مسح '
  WHEN GENOperationsLogs.Action=N'Add' then N'اضافة '
  WHEN GENOperationsLogs.Action=N'Reminder' then N'تذكير '
  WHEN GENOperationsLogs.Action=N'Import' then N'رفع '
  WHEN GENOperationsLogs.Action=N'AddNew' then N'اضافة جديدة ل'
  END) as P2,
  (case
  WHEN GENOperationsLogs.number=0 then    gencontacts.name + N' المتدرب '
  WHEN GENOperationsLogs.number is null then   N' المتدرب ' + gencontacts.name 
  ELSE  N' عدد ' + CAST(number AS nvarchar) + N' متدرب '
  END) as P3,
  (case
  WHEN (GENOperationsLogs.vcrId IS NOT NULL AND GENOperationsLogs.vcrId>0) then    N' في قاعة '+genclassrooms.NAME
  ELSE ''
  END) as P4,
 GENOperationsLogs.createDate as createDate,format(GENOperationsLogs.createDate,'dd/MM/yyyy HH:MM') as CreateDateString
  from GENOperationsLogs
 left join gencontacts as responsibleperson on GENOperationsLogs.UserId=responsibleperson.Id
 left join gencontacts on gencontacts.Id=GENOperationsLogs.targetId
 left join genclassrooms on genclassrooms.Id=GENOperationsLogs.vcrId
 where ((number IS NOT NULL AND number >0) OR targetId IS NOT NULL)
 and GENOperationsLogs.CompanyId=@CompanyId and GENOperationsLogs.UserId =@Id
 order by GENOperationsLogs.Id DESC
GO
