/****** Object:  StoredProcedure [dbo].[SP_BK_SelectAllContacts_Push]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_BK_SelectAllContacts_Push]
 @DateF datetime = null
,@DateTo datetime = null
AS
Begin
select distinct  GENcontacts.Id AS ContactId ,GENcontacts.Name,GENcontacts.IDNumber,GENcontacts.Position,GENcontacts.DefaultAddress,
isnull(GENcontacts.DefaultEmail, '')DefaultEmail,isnull(GENcontacts.DefaultPhone, '') DefaultPhone,
(CASE WHEN (GENcontacts.DefaultEmail IS NULL or LEN(GENcontacts.DefaultEmail) = 0)  THEN N'red' ELSE N''END) AS ColorHandleEmail,
(CASE WHEN (GENcontacts.DefaultPhone IS NULL or LEN(GENcontacts.DefaultPhone) = 0)  THEN N'red' ELSE N''END) AS ColorHandlePhone,IsUser
,isnull(GENcontacts.Qualification_Name,'') QualificationName,isnull(GENCompanies.Name,'') DestinationName
,isnull(GENListValues.Name,N'Male') as GenderName,FORMAT(GENContacts.BirthDate ,'dd/MM/yyyy') as BirthDate
,cast(isnull(DATEDIFF(YEAR, BirthDate, GETDATE()) - 
    CASE 
        WHEN DATEADD(YEAR, DATEDIFF(YEAR, BirthDate, GETDATE()), BirthDate) > GETDATE() 
        THEN 1 
        ELSE 0 
    END ,'')as nvarchar(5)) AS Age
	,isnull(GENCities.Name,'') as CityName
	,isnull(GENCountries.Name,'') as CountryName
	,isnull(GENCompanyTypes.Name,'') as DestinationTypeName
from GENcontacts 
left join GENCompanies on GENCompanies.Id = GENcontacts.CompanyId
left join GENCompanyTypes on GENCompanyTypes.Id = GENCompanies.CompanyTypeId
left join GENListValues on GENListValues.Id = GENcontacts.GenderId
left join GENAddresses on GENAddresses.EntityId = GENcontacts.Id and GENAddresses.BaseEntityId = 47
left join GENCities on GENCities.Id = GENAddresses.CityId
left join GENCountries on GENCountries.Id = GENAddresses.CountryId
where GENcontacts.IsDeleted=0 and  (cast(GENcontacts.BirthDate as date) >=  cast(@DateF as date) and cast(GENcontacts.BirthDate as date) <=  cast(@DateTo as date)
or (@DateF is null and @DateTo is null))
END
GO
