/****** Object:  StoredProcedure [dbo].[SP_BK_SelectCalcPrecentageAttendance]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_BK_SelectCalcPrecentageAttendance] (@ClassroomId Bigint,@Precentage int)--SP_BK_SelectCalcPrecentageAttendance  41415,50
As
Begin 
select *,(case when BookingTypeId not in (1) then  N'الحالة خطأ' when exists(select 1 from Classroom_Attendance where Classroom_Attendance.StudentId = res.StudentId and Classroom_Attendance.ClassroomId = res.ClassroomId)
then CAST(cast(((cast(res.AttDur as dec(18,4))/cast(res.VCRDur as dec(18,4))) * 100.00) as decimal(18,2)) AS nvarchar(50)) else N'ليس له حضور وانصراف مسجل' end) AS totalVCR
from (
select GENClassroom_GENContact.StudentId,(count(distinct Classroom_Attendance.Id)) as AttDur
,(select count(distinct Id) as Dur from TLMSClassroom_Session 
where TLMSClassroom_Session.ClassroomId = GENClassroom_GENContact.ClassroomId and TLMSClassroom_Session.TypeSession =0 ) as VCRDur,
GENContacts.Name AS StudentName,GENClassroom_GENContact.ClassroomId,GENClassroom_GENContact.BookingTypeId
from GENClassroom_GENContact
inner join GENContacts ON GENClassroom_GENContact.StudentId = GENContacts.Id
left join TLMSClassroom_Session on  GENClassroom_GENContact.ClassroomId = TLMSClassroom_Session.ClassroomId
left join Classroom_Attendance ON TLMSClassroom_Session.SessionId = Classroom_Attendance.SessionId and
GENContacts.Id = Classroom_Attendance.StudentId and GENClassroom_GENContact.ClassroomId = Classroom_Attendance.ClassroomId
and ExecuseId IN (77113,77118)
where GENClassroom_GENContact.ClassroomId = @ClassroomId  
and GENClassroom_GENContact.StudentId IN (select ContactId from TempRPTBulks)
group by GENClassroom_GENContact.StudentId,GENClassroom_GENContact.ClassroomId,GENContacts.Name,GENClassroom_GENContact.BookingTypeId
) as res

where (CAST(((cast(res.AttDur as dec(18,4))/cast(res.VCRDur as dec(18,4))) * 100) AS DECIMAL(18,2)) <=@Precentage or  BookingTypeId not in (1))
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_SelectDashBoard]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create Proc [dbo].[SP_BK_SelectDashBoard]
as
begin

--أجمالي المسجلين
Select Count(GENContacts.Id) AS TotalStudents from GENContacts inner join AspNetUsers ON GENContacts.UserId=AspNetUsers.Id 
where GENContacts.IsDeleted=0 and ContactCategoryId=1



 -- طلبات الألتحاق

Select Count(GENClassroom_GENContact.Id) AS AdmissionApplications from GENClassroom_GENContact inner join 
GENContacts ON  GENClassroom_GENContact.StudentId=GENContacts.Id inner join 
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
where GENClassroom_GENContact.BookingTypeId=0 and GENContacts.IsDeleted=0 and GENClassrooms.IsDeleted=0





 --المسجلين

Select Count(GENClassroom_GENContact.Id) AS AllRegistered from GENClassroom_GENContact  
inner join 
GENContacts ON  GENClassroom_GENContact.StudentId=GENContacts.Id inner join 
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
where GENClassroom_GENContact.BookingTypeId in (1,6) and GENContacts.IsDeleted=0 and GENClassrooms.IsDeleted=0




--إجمالي مواد الألتحاق

select Count (GENTypes.Id) AS AdmissionMaterials 
from GENTypes inner join GENTypeCategories ON GENTypes.TypeCategoryId=GENTypeCategories.Id where GENTypes.IsDeleted=0

--إجمالي الدورات تمت

select Count(GENClassrooms.Id) AS TotalCoursesCompleted from GENClassrooms where (ToDateTime > GETDATE() and GENClassrooms.IsDeleted=0)




--إجمالي الدورات مستقبلية

select Count(GENClassrooms.Id) AS TotalFutureCourses from GENClassrooms where (FromDateTime > GETDATE() and GENClassrooms.IsDeleted=0)






--إجمالي الأمتحانات

select Count(GENExamAnswerHeaders.Id) AS TotalExams from GENExamAnswerHeaders 




--إجمالي الأخبار

select Count(GENWikis.Id) AS TotalNews from  GENWikis where WikiCategoryId=55


--إجمالي الأخبار الحالية

select Count(GENWikis.Id) AS TotalCurrentNews from  GENWikis where WikiCategoryId=55 and((cast(DateCreated as date) = cast( GETDATE() as date) or cast(DateUpdated as date)   = cast( GETDATE() as date)))



--إجمالي الصور slider

select Count(GENWikis.Id) AS TotalHomeSlider from  GENWikis where WikiCategoryId=53  


--إجمالي الصورslider  الحالية

select Count(GENWikis.Id) AS TotalCurrentHomeSlider from  GENWikis where WikiCategoryId=53 and ((cast(DateCreated as date) = cast( GETDATE() as date) or cast(DateUpdated as date)   = cast( GETDATE() as date)))


--إجمالي الحياة داخل الأكاديمية

select Count(GENWikis.Id) AS TotalLifeInAcademy from  GENWikis where WikiCategoryId=57  


--إجمالي الحياة داخل الأكاديمية الحالية

select Count(GENWikis.Id) AS TotalCurrentLifeInAcademy from  GENWikis where WikiCategoryId=57 and ((cast(DateCreated as date) = cast( GETDATE() as date) or cast(DateUpdated as date)   = cast( GETDATE() as date)))





--إجمالي  إشادات

select Count(GENWikis.Id) AS TotalTestemonials from  GENWikis where WikiCategoryId=58  


--إجمالي إشادات الحالية

select Count(GENWikis.Id) AS TotalCurrentTestemonials from  GENWikis where WikiCategoryId=58 and ((cast(DateCreated as date) = cast( GETDATE() as date) or cast(DateUpdated as date)   = cast( GETDATE() as date)))


------------------------------------------------------------------------------
--  المسجلين الحاليين
Select Count(GENContacts.Id) AS CurrentTotalStudents from GENContacts inner join AspNetUsers ON GENContacts.UserId=AspNetUsers.Id 
where GENContacts.IsDeleted=0 and ContactCategoryId=1 and ((cast(DateCreated as date) = cast( GETDATE() as date) or cast(DateUpdated as date)   = cast( GETDATE() as date)))
 






 -- مواد الألتحاق الحالية

select Count (GENTypes.Id) AS CurrentAdmissionMaterials 
from GENTypes inner join GENTypeCategories ON GENTypes.TypeCategoryId=GENTypeCategories.Id where GENTypes.IsDeleted=0   and ((cast(GENTypes.DateCreated as date) = cast( GETDATE() as date) or cast(GENTypes.DateUpdated as date)   = cast( GETDATE() as date)))



-- الدورات الحالية 

select Count(GENClassrooms.Id) AS CurrentVcrs from GENClassrooms where ((ToDateTime >= GETDATE()  and GENClassrooms.FromDateTime <= GETDATE()) and GENClassrooms.IsDeleted=0)











-- الأمتحانات الحالية

select Count(GENExamAnswerHeaders.Id) AS CurrentExams from GENExamAnswerHeaders where  ((cast(DateCreated as date) = cast( GETDATE() as date) or cast(DateUpdated as date)   = cast( GETDATE() as date)))









END
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_SelectDashBoard_Page]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_BK_SelectDashBoard_Page]
as
begin

--*إجمالي*--


--أجمالي المتدربين تدريب
Select Count(GENContacts.Id) AS TotalTraineesTrained 
from GENContacts 
where  GENContacts.IsDeleted=0 and  ContactCategoryId=1;





--أجمالي  المسجلين
Select Count(GENContacts.Id) AS TotalRegistered from GENContacts 
inner join AspNetUsers ON GENContacts.UserId=AspNetUsers.Id 
where GENContacts.IsDeleted=0 and ContactCategoryId=1;




--إجمالي  الحقائب التدربية
WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE H1.Id = 3
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
select Count(GENTypes.Id) as TotalTrainingCourses
from CourseCategories 
inner join  RecursiveCte ON CourseCategories.CategoryId =RecursiveCte.Id inner join 
GENTypes ON CourseCategories.CourseId=GENTypes.Id
where GENTypes.IsDeleted=0 and GENTypes.Isactive=1;



--إجمالي الدورات 
select Count(GENClassrooms.Id) AS TotalVcrs
from GENClassrooms 
where  GENClassrooms.IsDeleted=0 and GENClassrooms.IsActive=1 and GENClassrooms.ClassroomCategoryId=1;



--إجمالي الفعليات 
select Count(GENClassrooms.Id) AS TotalVcrEvents
from GENClassrooms 
where  GENClassrooms.IsDeleted=0 and GENClassrooms.IsActive=1 and GENClassrooms.ClassroomCategoryId=2;



--إجمالي الأعوام الدراسية 
select Count(GENTalents.Id) AS TotalYearsOfStudy
from GENTalents 
where  GENTalents.IsDeleted=0 and GENTalents.IsActive=1 ;





--إجمالي المقررات الدراسية 
select Count(GENTalents.Id) AS TotalCourses
from GENTalents_Generic inner join 
GENTalents ON GENTalents_Generic.TalentId=GENTalents.Id inner join 
GENClassrooms ON GENTalents_Generic.VcrId=GENClassrooms.Id
where  GENTalents.IsDeleted=0 and GENTalents.IsActive=1  and GENClassrooms.IsDeleted=0 and GENClassrooms.IsActive=1 ;






--إجمالي  الطلاب دراسات عليا 
select COUNT(Id) as TotalGraduateStudents from Talents_Requestes ;


--إجمالي  الطلاب العام الدراسي 
select COUNT(Id) as TotalStudentsForTheAcademicYear from Talents_Requestes 
where TalentStatus= 1 ;



--إجمالي المدربين 
select COUNT(Id) as TotalTrainers from GENEmployees 
where GENEmployees.IsActive= 1 and GENEmployees.Isdeleted=0  and GENEmployees.EmployeeCategoryId=1;




--إجمالي الموظفين 
select COUNT(Id) as TotalEmployees from GENEmployees 
where GENEmployees.IsActive= 1 and GENEmployees.Isdeleted=0  and GENEmployees.EmployeeCategoryId=2;



--إجمالي طلبات الأسترداد 
select COUNT(Id) as TotalReturnedOrders from GENReturnedOrders ;


--* إجمالي شهر سابق*--

--إجمالي  الحقائب التدربية شهر سابق
WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE H1.Id = 3
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
select Count(GENTypes.Id) as TotalTrainingCoursesBeforeMonth
from CourseCategories 
inner join  RecursiveCte ON CourseCategories.CategoryId =RecursiveCte.Id inner join 
GENTypes ON CourseCategories.CourseId=GENTypes.Id
where GENTypes.IsDeleted=0 and GENTypes.Isactive=1 and
((cast(GENTypes.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENTypes.DateCreated as date) <= cast(GETDATE() as date)));





--إجمالي الدورات شهر سابق
select Count(GENClassrooms.Id) AS TotalVcrsBeforeMonth
from GENClassrooms 
where  GENClassrooms.IsDeleted=0 and GENClassrooms.IsActive=1 and GENClassrooms.ClassroomCategoryId=1
and ((cast(GENClassrooms.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.DateCreated as date) <= cast(GETDATE() as date)));


--إجمالي المتدربين شهر سابق
Select Count(GENContacts.Id) AS TotalTraineesTrainedBeforeMonth
from GENContacts 
where  GENContacts.IsDeleted=0 and  ContactCategoryId=1
and ((cast(GENContacts.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENContacts.DateCreated as date) <= cast(GETDATE() as date)));


--إجمالي المدربين شهر سابق
select COUNT(Id) as TotalTrainersBeforeMonth from GENEmployees 
where GENEmployees.IsActive= 1 and GENEmployees.Isdeleted=0  and GENEmployees.EmployeeCategoryId=1
and ((cast(GENEmployees.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENEmployees.DateCreated as date) <= cast(GETDATE() as date)));

--*أحصائيات التقارير*--


-- تقرير الانجازالتفصيلي
select Count(Rpt_AchievementsDtls_View.Id) as TotalVcrAchievementsDtls,sum(Rpt_AchievementsDtls_View.CountStudents) TotalStudentsAchievementsDtls
from Rpt_AchievementsDtls_View;


-- تقرير الفعليات
SELECT Count (GENClassrooms.Id) AS TotalEventsActivitiesReport,Count(GENClassroom_GENContact.Id) AS TotalStudentActivitiesReport
FROM GENClassrooms left join 
GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
WHERE GENClassrooms.ClassroomCategoryId=2 and 
(GENClassrooms.IsActive =1) and (GENClassrooms.IsDeleted =0) and  (GENClassrooms.ClassRoomStatus =2 )



-- تقرير عدد المسجلين
SELECT Count (GENContacts.Id) AS TotalStudentsContactsVCRNotReg
	From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0
and (GENContacts.id not in (select distinct GENClassroom_GENContact.StudentId from GENClassroom_GENContact))



-- تقرير  طلبات الدورات
select Count(GENClassrooms.Id) AS TotalStudentsCoursesRequests
FROM GENClassrooms
inner join GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
where GENClassrooms.classroomcategoryId=1 and GENClassrooms.isdeleted=0 and GENClassroom_GENContact.BookingTypeId=0 




-- تقرير   أثر التدريبي
Select distinct Count(PreExHeader.Id) AS TotalExamPreandPost
From GENPollCategories Pre inner join 
GENExamAnswerHeaders PreExHeader ON Pre.Id =PreExHeader.ExamId and Pre.ExamType =9 
inner join GENContacts ON PreExHeader.StudentId = GENContacts.Id 
inner join GENClassrooms on GENClassrooms.Id = PreExHeader.ClassroomId
inner join GENPollCategories Post ON Pre.Id = Post.ParentId 
inner join GENExamAnswerHeaders PostExHeader ON Post.Id =PostExHeader.ExamId and Post.ExamType =10 and PostExHeader.StudentId = GENContacts.Id and PostExHeader.ClassroomId = GENClassrooms.Id



-- تقرير  دورات تم تنفيذها
select Count(GENTypes.Id) AS TotalClassroomsDetails 
FROM GENClassrooms
LEFT JOIN GENClassroom_GENContact ON GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
LEFT JOIN GENTypes ON GENClassrooms.CourseId = GENTypes.Id
where GENClassrooms.ClassroomCategoryId=1 and GENClassrooms.IsDeleted=0 and GENClassrooms.ClassRoomStatus = 2
and GENClassroom_GENContact.BookingTypeId = 1 and dbo.AttendanceCall(GENClassroom_GENContact.StudentId,GENClassroom_GENContact.ClassroomId) >= GENClassrooms.Int4





-- تقرير  قائمة الدورات
select Count(GENClassrooms.Id) AS TotalVcrReport
from GENClassrooms left join 
AspNetUsers ON GENClassrooms.LastUpdatedById =AspNetUsers.Id left join 
AspNetUsers Created ON GENClassrooms.CreatedById =Created.Id left join 
GENListValues ON GENClassrooms.LanguageId=GENListValues.Id left join 
GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id left join 
GENCities ON GENClassrooms.CityId =GENCities.Id 
WHERE GENClassrooms.IsDeleted=0;


