CREATE Proc [dbo].[SP_BK_SelectEmailHistory] (@wikiId bigint=null)
as
Begin
Select distinct TransmissionHistroys.*,GENcontacts.Id As StudentId,GENcontacts.Name as StudentName,
format(TransmissionHistroys.SendDateCreated,'dd/MM/yyyy hh:mm tt') as SendDateCreatedString,
format(TransmissionHistroys.SendDateUpdated,'dd/MM/yyyy hh:mm tt') as SendDateUpdatedString,
(case when TransmissionHistroys.responseStatus = 1 then N'Sucess' ELSE N'Fail' END ) AS ResponeStatusMSG
from TransmissionHistroys left join 
GENcontacts ON TransmissionHistroys.EntityId=GENcontacts.Id and TransmissionHistroys.BaseEntityId=47
where TransmissionHistroys.WikiId=@wikiId
order by TransmissionHistroys.SendDateUpdated desc
END
GO
