/****** Object:  StoredProcedure [dbo].[SP_BK_SelectFilesWithType]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_BK_SelectFilesWithType] (@ContactId Bigint ,@BaseEntityId Bigint,@Type Bigint)
AS
Begin
SELECT GENFiles.[Id]
      ,GENFiles.[FileName]
      ,(case when GENFiles.[AzureUri] like N'%http%' then GENFiles.[AzureUri] else concat( (select top 1 [Value] from [dbo].[GENConfigurations] where name = 'PathURLocal'),'/',REPLACE(GENFiles.[AzureUri], '\', '/'))end) as [AzureUri]
      ,GENFiles.[DateCreated]
      ,GENFiles.[DateUpdated]
      ,GENFiles.[CreatedById]
      ,GENFiles.[LastUpdatedById]
      ,GENFiles.[EntityId]
      ,GENFiles.[BaseEntityId]
      ,GENFiles.[DisplayOrder]
      ,GENFiles.[Description]
      ,GENFiles.[LanguageId]
      ,GENFiles.[TotalPages]
      ,GENFiles.[FileTypeId]
      ,GENFiles.[IsFolder],GENListValues.Name AS LanguageName,LV.Name As FileType, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt 
FROM GENFiles
LEFT JOIN GENListValues ON GENFiles.LanguageId = GENListValues.Id left join
GENListValues LV ON GENFiles.FileTypeId=LV.Id
 WHERE GENFiles.BaseEntityId = @BaseEntityId AND GENFiles.EntityId = @ContactId and GENFiles.IsFolder=0 and GENFiles.FileTypeId=@Type
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_SelectFilesWithTypeV2]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROC [dbo].[SP_BK_SelectFilesWithTypeV2] (@ContactId Bigint ,@BaseEntityId Bigint,@Type Bigint)
AS
Begin
SELECT GENFiles.[Id]
      ,GENFiles.[FileName]
      ,(case when GENFiles.[AzureUri] like N'%http%' then GENFiles.[AzureUri] else concat( (select top 1 [Value] from [dbo].[GENConfigurations] where name = 'PathURLocal'),'/',REPLACE(GENFiles.[AzureUri], '\', '/'))end) as [AzureUri]
      ,GENFiles.[DateCreated]
      ,GENFiles.[DateUpdated]
      ,GENFiles.[CreatedById]
      ,GENFiles.[LastUpdatedById]
      ,GENFiles.[EntityId]
      ,GENFiles.[BaseEntityId]
      ,GENFiles.[DisplayOrder]
      ,GENFiles.[Description]
      ,GENFiles.[LanguageId]
      ,GENFiles.[TotalPages]
      ,GENFiles.[FileTypeId]
      ,GENFiles.[IsFolder],GENListValues.Name AS LanguageName,LV.Name As FileType, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt ,LV.Code as FileTypeCode
FROM GENFiles
LEFT JOIN GENListValues ON GENFiles.LanguageId = GENListValues.Id left join
GENListValues LV ON GENFiles.FileTypeId=LV.Id
 WHERE GENFiles.BaseEntityId = @BaseEntityId AND GENFiles.EntityId = @ContactId and GENFiles.IsFolder=0 and (GENFiles.FileTypeId=@Type or @Type is null)
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_SelectIndexReturnedOrder]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE Proc [dbo].[SP_BK_SelectIndexReturnedOrder]  (@cateId int=null,@lang varchar(30)=null)
AS
Begin

Select GENReturnedOrders.*,GENContacts.Name AS ContactName,GENClassrooms.Name AS VcrName,
FORMAT(GENOrders.DateCreated,'dd/MM/yyyy') AS DateOfPaied,FORMAT(GENReturnedOrders.DateCreated,'dd/MM/yyyy') AS DateOfReturnedPaied,
'Visa' as PaymentMethod ,GENOrders.Id as  NumBill,GENOrders.TransactionId,
FORMAT(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDateString,FORMAT(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDateString,
GENOrders.TransactionCardNumber,GENOrders.TransactionContactCardNumber,GENOrders.TransactionId,
[dbo].[fn_ReturnOrderStatus_Color](GENReturnedOrders.ReturnedOrder) as StatusColor,
[dbo].[fn_ReturnOrderStatusName](GENReturnedOrders.ReturnedOrder,@lang) as ReturnedOrderName


From GENReturnedOrders left join 
GENOrders ON GENReturnedOrders.orderId=GENOrders.Id 
left join GENContacts ON GENOrders.ContactId=GENContacts.Id
left join GENClassrooms ON GENOrders.VcrId=GENClassrooms.Id

where GENReturnedOrders.Isdeleted=0 and( GENReturnedOrders.ReturnedOrder=@cateId or  @cateId is null)
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_SelectReturnedOrder_Id]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_BK_SelectReturnedOrder_Id] (@Id Bigint)
AS
Begin

Select GENReturnedOrders.*,GENContacts.Id as ContactId,GENContacts.Name AS ContactName,GENClassrooms.Id as VcrId,GENClassrooms.Name AS VcrName,
FORMAT(GENOrders.DateCreated,'dd/MM/yyyy') AS DateOfPaied,FORMAT(GENReturnedOrders.DateCreated,'dd/MM/yyyy') AS DateOfReturnedPaied,
'Visa' as PaymentMethod ,GENOrders.Id as  NumBill,GENOrders.TransactionId,
FORMAT(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDateString,FORMAT(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDateString,
GENOrders.TransactionCardNumber,GENOrders.TransactionContactCardNumber,
FORMAT(GENReturnedOrders.ReturnedOrderDate,'dd/MM/yyyy') AS ReturnedOrderDateString,
GENOrders.PaidPrice


From GENReturnedOrders left join 
GENOrders ON GENReturnedOrders.orderId=GENOrders.Id 
left join GENContacts ON GENOrders.ContactId=GENContacts.Id
left join GENClassrooms ON GENOrders.VcrId=GENClassrooms.Id


where GENReturnedOrders.Id=@Id
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BK_SelectVCRRateInstructorH_ByVcrId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
