GO
Create Proc [dbo].[SP_BK_SelectVCRRateInstructorH_ByVcrId] (@VcrId bigint)
AS
Begin
select distinct TLMSClassroom_Session.Id,TLMSClassroom_Session.InstructorId,GENEmployees.Name AS InstructorName,Count(GENRatings.Rating) AS CountRate,
AVG(GENRatings.Rating) AS AvgRate,count(GENRatings.Comment) AS CountReview
from GENRatings
inner join TLMSClassroom_Session ON GENRatings.EntityId=TLMSClassroom_Session.Id and GENRatings.BaseEntityId=198 inner join 
GENClassrooms ON TLMSClassroom_Session.ClassroomId=GENClassrooms.Id inner join 
GENEmployees ON TLMSClassroom_Session.InstructorId=GENEmployees.Id
where TLMSClassroom_Session.ClassroomId=@VcrId
group by GENEmployees.Name,TLMSClassroom_Session.InstructorId,TLMSClassroom_Session.Id
END
