/****** Object:  StoredProcedure [dbo].[SP_Calculate_ExamPolls]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_Calculate_ExamPolls] (@ExamId bigint)
as
declare @total decimal (18,2)
SELECT  @total=  CAST(  sum( poll.Weight) as  DECIMAL(18,2))
from
(SELECT distinct  dbo.GENPolls.Id ,dbo.GENPolls.Weight

FROM            dbo.PollCategoryandPolls LEFT OUTER JOIN
                         dbo.GENPolls ON dbo.PollCategoryandPolls.PollId = dbo.GENPolls.Id
	where dbo.PollCategoryandPolls.PollCategoryId =@ExamId)  poll


	update  GENPollCategories  set ActucalScore =@total
GO
