CREATE Proc [dbo].[SP_CheckOut]
as
update CRMDeals 
set IsCheckedOut = 0
where  dbo.CRMDeals.CheckoutDate <= GETDATE() and dbo.CRMDeals.IsCheckedOut =1;

update GENContacts
set IsCheckedOut = 0
where  dbo.GENContacts.CheckoutDate <= GETDATE() and dbo.GENContacts.IsCheckedOut =1;


update GENEmployees
set IsCheckedOut = 0
where  dbo.GENEmployees.CheckoutDate <= GETDATE() and dbo.GENEmployees.IsCheckedOut =1;

update GENCompanies 
set IsCheckedOut = 0
where  dbo.GENCompanies.CheckoutDate <= GETDATE() and dbo.GENCompanies.IsCheckedOut =1;

update CRMTickets
set IsCheckedOut = 0
where  dbo.CRMTickets.CheckoutDate <= GETDATE() and dbo.CRMTickets.IsCheckedOut =1;



update GENClassrooms
set IsCheckedOut = 0
where  dbo.GENClassrooms.CheckoutDate <= GETDATE() and dbo.GENClassrooms.IsCheckedOut =1;



update GENTypes
set IsCheckedOut = 0
where  dbo.GENTypes.CheckoutDate <= GETDATE() and dbo.GENTypes.IsCheckedOut =1;



update GENPollCategories
set IsCheckedOut = 0
where  dbo.GENPollCategories.CheckoutDate <= GETDATE() and dbo.GENPollCategories.IsCheckedOut =1;









