/****** Object:  StoredProcedure [dbo].[SP_ClassroomAttendanceFilter]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_ClassroomAttendanceFilter] --SP_ClassroomAttendanceFilter 242,null,20091,null,null
 (@ClassroomId Bigint
 ,@SessionId Bigint
 ,@StudentId Bigint
 ,@Date datetime
  ,@ExecuseId Bigint
 )
AS
Begin

Select Classroom_Attendance.Id,GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,GENItems.Id AS SessionId,GENItems.Code AS SessionCode,GENItems.Name AS SessionName,
FORMAT(TLMSClassroom_Session.SessionDateTime, 'MM/dd/yyyy') as SessionDate,
row_number() OVER (ORDER BY GENclassrooms.Id) Id2,GENClassrooms.Id AS ClassroomId,Classroom_Attendance.IsAttendance,
Classroom_Attendance.ExecuseId,GENListValues.Name as ExecuseName
From GENClassrooms left join 
GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId left join 
GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id Left join
TLMSClassroom_Session ON GENClassrooms.Id=TLMSClassroom_Session.ClassroomId inner join
GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id
left join Classroom_Attendance on Classroom_Attendance.SessionId = GENItems.Id and Classroom_Attendance.StudentId = GENContacts.Id and Classroom_Attendance.ClassroomId = GENClassrooms.Id
left join GENListValues on Classroom_Attendance.ExecuseId = GENListValues.Id
where GENClassrooms.Id=@ClassroomId and GENClassroom_GENContact.ClassroomId=@ClassroomId and TLMSClassroom_Session.ClassroomId=@ClassroomId
and(TLMSClassroom_Session.SessionId = @SessionId or @SessionId is null or @SessionId = 0)
and(GENClassroom_GENContact.StudentId = @StudentId or @StudentId is null)and(Classroom_Attendance.ExecuseId = @ExecuseId or @ExecuseId is null)
and(TLMSClassroom_Session.SessionDateTime = @Date or @Date is null)and GENClassroom_GENContact.BookingTypeId in (1,6)
END
GO
