      ,[ValueId2]
      ,[ValueId3]
      ,[ValueId4]
      ,[ValueId5]
      ,[IconId]
      ,[IsActive]
      ,[IsPublish]
      ,[ExamId]
      ,[ClassRoomStatus]
      ,[LanguageId]
      ,[IsPosted]
      ,[IsShowInteractiveMeeting]
      ,[RichContent]
      ,[Langeuage_Name]
      ,[Course_Name]
      ,[Instructor_Name]
      ,[Exam_Name]
      ,[RoomId]
      ,[PaymentTypeId]
      ,[BookingTypeId]
	  ,[ClassroomCategoryId]
	  ,[GroupTypeId]
	  ,[CompanyId]
	  ,[IsPlan]
	  ,IsAchievementRanking)



SELECT	
       GENClassrooms.[InteractiveMeetingURL]
      ,GENClassrooms.[InstructorInstructions]
      ,GENClassrooms.[ExamStartTime]
      ,GENClassrooms.[ExamEndTime]
      ,GENClassrooms.[FromDateTime]
      ,GENClassrooms.[ToDateTime]
      ,GENClassrooms.[InteractiveMeetingDateTime]
      ,GENClassrooms.[DisplayOrder]
      ,GENClassrooms.[CourseId]
      ,GENClassrooms.[InstructorId]
      ,(case when GENCompanies.id is not null and GENTypes.id is not null then GENTypes.code +'-'+(case when GroupTypeId = 0 then 'F'  when GroupTypeId = 1 then 'M' 
	  when GroupTypeId = 2 then 'P' when GroupTypeId = 3 then 'A' when GroupTypeId = 4 then 'G'end)+'-'+(case when IsPlan = 1 then 'IP' else 'OP' end) +'-'+GENCompanies.Code +'-'	
	  + cast([dbo].[fn_CountVCRsByCode](IsPlan,CompanyId,GroupTypeId,CourseId) + 1 as nvarchar(50))else GENClassrooms.Code end) as code
      ,GENClassrooms.[Name]
      ,GENClassrooms.[Description]
      ,GENClassrooms.[ColorCode]
      ,0
      ,getdate()
	  ,getdate()
      ,GENClassrooms.[CheckinDate]
      ,GENClassrooms.[CheckoutDate]
      ,GENClassrooms.[ExpectedCheckoutDate]
      ,GENClassrooms.[Timeout]
