		SELECT @con_value=GENConfigurations.Value from GENConfigurations where GENConfigurations.Name like N'ExamType';
		SET @con_value=REPLACE(@con_value, SUBSTRING(@ExamName, 1, CHARINDEX('-', @ExamName) - 1), @con_value);
		SET @ExamName= SUBSTRING(@ExamName, CHARINDEX('-', @ExamName) + 1, LEN(@ExamName));
