GO

CREATE proc [dbo].[Sp_ClonePop_TranslateFields] (@PopNewId bigint,@PopId bigint )
as
declare @TEMP table ([Id] [bigint],
	[Name] [nvarchar](255) NOT NULL,
	[Description] [nvarchar](max) NULL,
	[RichContent] [nvarchar](max) NULL,
	[PageOfPageFeildId] [bigint] NULL,
	[LangId] [bigint] NULL,
	FeildId [bigint])
		INSERT INTO @TEMP
Select dbo.GENTranslate_PageOfPageFeilds.*, PageOfPageFeilds.FeildId from dbo.GENTranslate_PageOfPageFeilds
LEFT JOIN  PageOfPageFeilds
 ON dbo.PageOfPageFeilds.Id = dbo.GENTranslate_PageOfPageFeilds.PageOfPageFeildId
 where PageOfPageFeilds.PageOfPageId=@PopId

 SELECT Name,Description,RichContent,PageOfPageFeilds.Id,[LangId] FROM @TEMP t
 LEFT JOIN PageOfPageFeilds
 ON t.FeildId = PageOfPageFeilds.FeildId
 where PageOfPageFeilds.PageOfPageId = @PopNewId
GO
