/****** Object:  StoredProcedure [dbo].[Sp_CloneTypeCategory]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
creATE proc [dbo].[Sp_CloneTypeCategory] (@NewId bigint,@OldId bigint)
as
begin
WITH HierarchicalCTE AS
(
SELECT Cat.Id,ParentId, Cat.Code, Cat.Name, 1 AS LEVEL ,
Cast(Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as Fullpath
FROM GENTypeCategories Cat
where cat.Id = @OldId
UNION ALL
SELECT Cat.Id,Cat.ParentId, Cat.Code, Cat.Name, cte.level+1 AS LEVEL ,
Cast(Cte.Fullpath + '-' + Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as FullPath
FROM HierarchicalCTE cte
inner join GENTypeCategories Cat ON Cat.ParentId = cte.id
)
select * from HierarchicalCTE

END
GO
