Create PROCEDURE [dbo].[SP_CommnetDistinctUsers]

AS
BEGIN

	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT COUNT( DISTINCT GENComments.UserId) as DISTINCTUsers
	from GENComments left join 
	AspNetUsers on GENComments.UserId=AspNetUsers.Id
END

GO
