/****** Object:  StoredProcedure [dbo].[SP_CompanyInfo_UpateById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_CompanyInfo_UpateById] (@companyId bigint)
as
DECLARE @Count bigint
SELECT @Count = COUNT(Id) FROM CompanyInfoes WHERE CompanyId = @companyId;
if(@Count > 0)
BEGIN
MERGE INTO CompanyInfoes
   USING (
          SELECT dbo.GENCompanies.Id AS CompanyId,
		 dbo.GENEmployees.Name AS ResponsiblePersonName, dbo.GENContacts.Name AS ContactName, dbo.GENCompanyTypes.Name AS CompanyTypeName, dbo.GENIndustries.Name AS IndustryName, 
                         dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENListValues.Name AS TypeName, dbo.GENStyles.StyleValue AS TypeIcon, dbo.GENListValues.ColorCode AS TypeColor, 
                         dbo.fn_LastActivityStatus_ByEntityandBaseEntityId(dbo.GENCompanies.Id, 158) AS ActivityType,
						  dbo.fn_LastActionType_ByEntityandBaseEntityId(dbo.GENCompanies.Id, 158) AS ActivityAction, 
                         dbo.fn_Company_CompanyDealCount(dbo.GENCompanies.Id) AS DealCount,
						   dbo.fn_Company_CompanyItemCount(dbo.GENCompanies.Id) 
                         AS ItemCount,
						  dbo.fn_LastDealStatus_ByCompanyId(dbo.GENCompanies.Id) AS LastDealStatus,
						     CONVERT(varchar, dbo.GENCompanies.DateCreated, 103) AS DateCreatedString, 
                         CONVERT(varchar, dbo.GENCompanies.DateCreated, 108) AS TimeCreatedString,
						 CONVERT(varchar, dbo.GENCompanies.DateUpdated, 103) AS DateUpdatedString, 
                         CONVERT(varchar, dbo.GENCompanies.DateUpdated, 108) AS TimeUpdatedString,
						  dbo.fn_Company_AccountItemCount(dbo.GENCompanies.Id) AS AccountItemCount
FROM            dbo.GENCompanyTypes RIGHT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENCompanyTypes.Id = dbo.GENCompanies.CompanyTypeId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENCompanies.ResponsiblePersonId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.GENIndustries ON dbo.GENCompanies.IndustryId = dbo.GENIndustries.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.GENCompanies.MainContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENListValues LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENListValues.IconId = dbo.GENStyles.Id ON dbo.GENCompanies.ValueId1 = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENCompanies.LastUpdatedById = dbo.AspNetUsers.Id
		WHERE dbo.GENCompanies.Id = @CompanyId
         ) Company
      ON CompanyInfoes.CompanyId = Company.CompanyId
WHEN MATCHED THEN
   UPDATE 
      SET 
	  
	  ResponsiblePersonName = Company.ResponsiblePersonName,
	  ContactName = Company.ContactName,
	  CompanyTypeName = Company.CompanyTypeName,
	  IndustryName = Company.IndustryName,
	  TypeName = Company.TypeName,
	  TypeIcon = Company.TypeIcon,
	  TypeColor = Company.TypeColor,
	  ActivityType = Company.ActivityType,
	  ActivityAction = Company.ActivityAction,
	  DealCount = Company.DealCount,
	 
	  ItemCount = Company.ItemCount,
	  LastDealStatus = Company.LastDealStatus,
	  DateCreatedString = Company.DateCreatedString,
	  TimeCreatedString = Company.TimeCreatedString,
	  DateUpdatedString = Company.DateUpdatedString,
	  TimeUpdatedString = Company.TimeUpdatedString,
	  AccountItemCount = Company.AccountItemCount;
 
  
--UPDATE
--    ContactInfoes
--SET
--    GovernrateName = dbo.fnContact_GovernorateString(@ContactId),
--	ProvinceName = dbo.fnContact_ProvinceString(@ContactId),
--    CountryName = dbo.fnContact_CountryString(@ContactId),
--    Address = dbo.fnContact_AddressString(@ContactId),
--    NoOfTickets = dbo.fnContact_TicketCount(@ContactId),
--    AmountPaid = dbo.fnContact_TicketAmountPaid(@ContactId),
--    Phone = dbo.fnContact_PhoneString(@ContactId)
--FROM
--    ContactInfoes
--WHERE
--    ContactInfoes.ContactId = @ContactId
END
ELSE
BEGIN
exec [dbo].[SP_CompanyInfoes_InsertNew] @companyId
END
GO
/****** Object:  StoredProcedure [dbo].[SP_CompanyInfoes_InsertNew]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create proc [dbo].[SP_CompanyInfoes_InsertNew](@companyId bigint)
as

insert into   CompanyInfoes( CompanyId, ResponsiblePersonName, ContactName, CompanyTypeName, IndustryName, LastUpdatedByName, TypeName, TypeIcon, TypeColor, ActivityType, ActivityAction, DealCount, 
                         ItemCount, LastDealStatus,DateCreatedString, TimeCreatedString, DateUpdatedString, TimeUpdatedString, AccountItemCount)

SELECT        
                        @companyId, dbo.GENEmployees.Name AS ResponsiblePersonName, dbo.GENContacts.Name AS ContactName, dbo.GENCompanyTypes.Name AS CompanyTypeName, dbo.GENIndustries.Name AS IndustryName, 
                         dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENListValues.Name AS TypeName, dbo.GENStyles.StyleValue AS TypeIcon, dbo.GENListValues.ColorCode AS TypeColor, 
                         dbo.fn_LastActivityStatus_ByEntityandBaseEntityId(dbo.GENCompanies.Id, 158) AS ActivityType, dbo.fn_LastActionType_ByEntityandBaseEntityId(dbo.GENCompanies.Id, 158) AS ActivityAction, 
                         dbo.fn_Company_CompanyDealCount(dbo.GENCompanies.Id) AS DealCount, dbo.fn_Company_CompanyItemCount(dbo.GENCompanies.Id) 
                         AS ItemCount, dbo.fn_LastDealStatus_ByCompanyId(dbo.GENCompanies.Id) AS LastDealStatus, CONVERT(varchar, dbo.GENCompanies.DateCreated, 103) AS DateCreatedString, 
                         CONVERT(varchar, dbo.GENCompanies.DateCreated, 108) AS TimeCreatedString, CONVERT(varchar, dbo.GENCompanies.DateUpdated, 103) AS DateUpdatedString, 
                         CONVERT(varchar, dbo.GENCompanies.DateUpdated, 108) AS TimeUpdatedString, dbo.fn_Company_AccountItemCount(dbo.GENCompanies.Id) AS AccountItemCount
FROM            dbo.GENCompanyTypes RIGHT OUTER JOIN
                         dbo.GENCompanies ON dbo.GENCompanyTypes.Id = dbo.GENCompanies.CompanyTypeId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENCompanies.ResponsiblePersonId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.GENIndustries ON dbo.GENCompanies.IndustryId = dbo.GENIndustries.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.GENCompanies.MainContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENListValues LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENListValues.IconId = dbo.GENStyles.Id ON dbo.GENCompanies.ValueId1 = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENCompanies.LastUpdatedById = dbo.AspNetUsers.Id

						 where dbo.GENCompanies.Id=@companyId
GO
/****** Object:  StoredProcedure [dbo].[SP_ComplainReservation]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[SP_ComplainReservation] 
@Creater nvarchar(max) = null ,
@ticket_Type bigint = null,
@Sources bigint = null,
@Brand bigint = null,
@DateCreatedS datetime = null,
@DateCreatedE datetime = null,
@OrderType bigint=null,
@OrderSource bigint=null,
@Complaint_Type bigint=null,
@Complaint_classification bigint=null,
@Satisfaction bigint=null,
@Escalated bigint = null,
@DateReservationS datetime =null,
@DateReservationE datetime =null,
@Status bigint =null,
@SingTO bigint =null,
@Operatior bit
-- =============================================
-- Author:		michael magdy
-- Create date: 17 June 2019
-- Description:	Complaint & Reservation Data
-- =============================================
as
begin
SET NOCOUNT ON;
with empolyee_cte as (
Select Id,Name
,EmployeeId,
0 as Level_,
UserId,
IsActive

from GENEmployees
where GENEmployees.UserId = @Creater

union all

select p1.Id,
p1.Name,
p1.EmployeeId,
Level_ + 1,
p1.UserId,
p1.IsActive
from empolyee_cte p2
inner join GENEmployees p1 on p1.EmployeeId =p2.Id	
where p2.IsActive=1
)

SELECT distinct CT.*  
FROM  CRMTicketView CT
inner join empolyee_cte cte on (CT.EmployeeId = cte.EmployeeId or CT.EscalatedTo = cte.EmployeeId or CT.CreatedById = cte.UserId)
WHERE 
--(CreatedById= @Creater or @Creater is null or len(@Creater) = 0) and
 ((TicketTypeId= @ticket_Type and @Operatior = 0) or ((TicketTypeId <> @ticket_Type OR TicketTypeId IS NULL) and @Operatior = 1) or @ticket_Type is null or len(@ticket_Type) = 0)
and (SourceId= @Sources or @Sources is null or len(@Sources) = 0)
and (BrandId= @Brand or @Brand is null or len(@Brand) = 0)
and ((DateCreated between @DateCreatedS  and @DateCreatedE )or @DateCreatedS is null or len(@DateCreatedS) = 0 or @DateCreatedE is null or len(@DateCreatedE) = 0 )
and (OrderTypeID= @OrderType or @OrderType is null or len(@OrderType) = 0)
and (OrderSourceID= @OrderSource or @OrderSource is null or len(@OrderSource) = 0)
and (ComplainType_id= @Complaint_Type or @Complaint_Type is null or len(@Complaint_Type) = 0)
and (ComplainClassif_Id= @Complaint_classification or @Complaint_classification is null or len(@Complaint_classification) = 0)
and (SatisfactionId= @Satisfaction or @Satisfaction is null or len(@Satisfaction) = 0)
and (StatusId= @Escalated or @Escalated is null or len(@Escalated) = 0)
and (ProcessId= @Status or @Status is null or len(@Status) = 0)
and (CT.EmployeeId= @SingTO or @SingTO is null or len(@SingTO) = 0)
and (CT.IsDeleted = 0)
and (CT.IsJunk = 0)
and ((OpenDate between @DateReservationS  and @DateReservationE )or @DateReservationS is null or len(@DateReservationS) = 0 or @DateReservationE is null or len(@DateReservationE) = 0 )
end
GO
/****** Object:  StoredProcedure [dbo].[SP_ComplainReservationWithNotEqual]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[SP_ComplainReservationWithNotEqual] 
@Creater nvarchar(max) = null ,
@ticket_Type bigint = null,
@Sources bigint = null,
@Brand bigint = null,
@DateCreatedS datetime = null,
@DateCreatedE datetime = null,
@OrderType bigint=null,
@OrderSource bigint=null,
@Complaint_Type bigint=null,
@Complaint_classification bigint=null,
@Satisfaction bigint=null,
@Escalated bigint = null,
@DateReservationS datetime null,
@DateReservationE datetime null,
@Status bigint null,
@SingTO bigint null

-- =============================================
-- Author:		michael magdy
-- Create date: 17 June 2019
-- Description:	Complaint & Reservation Data
-- =============================================
as
begin
SET NOCOUNT ON;

SELECT *  
FROM  CRMTicketView  
WHERE 
(CreatedById= @Creater or @Creater is null or len(@Creater) = 0) and
 (TicketTypeId <> @ticket_Type or TicketTypeId is null)
and (SourceId= @Sources or @Sources is null or len(@Sources) = 0)
and (BrandId= @Brand or @Brand is null or len(@Brand) = 0)
and ((DateCreated between @DateCreatedS  and @DateCreatedE )or @DateCreatedS is null or len(@DateCreatedS) = 0 or @DateCreatedE is null or len(@DateCreatedE) = 0 )
and (OrderTypeID= @OrderType or @OrderType is null or len(@OrderType) = 0)
and (OrderSourceID= @OrderSource or @OrderSource is null or len(@OrderSource) = 0)
and (ComplainType_id= @Complaint_Type or @Complaint_Type is null or len(@Complaint_Type) = 0)
and (ComplainClassif_Id= @Complaint_classification or @Complaint_classification is null or len(@Complaint_classification) = 0)
and (SatisfactionId= @Satisfaction or @Satisfaction is null or len(@Satisfaction) = 0)
and (StatusId= @Escalated or @Escalated is null or len(@Escalated) = 0)
and (ProcessId= @Status or @Status is null or len(@Status) = 0)
and (EmployeeId= @SingTO or @SingTO is null or len(@SingTO) = 0)
and ((OpenDate between @DateReservationS  and @DateReservationE )or @DateReservationS is null or len(@DateReservationS) = 0 or @DateReservationE is null or len(@DateReservationE) = 0 )
end
GO
