/****** Object:  StoredProcedure [dbo].[SP_ContactCertificateClassRoom]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_ContactCertificateClassRoom] --41387,10221 -- SP_ContactCertificateClassRoom 208,10221
	-- Add the parameters for the stored procedure here
	--@ContactId BIGINT,
	@ClassRoomId BIGINT,
	@WikiId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @PrecAtt int = cast((select Value from GENConfigurations where name  = 'PrecentageAttendance') as int)
    -- Insert statements for procedure here
	SELECT 
	--DISTINCT (CASE WHEN GENCertificates.ContactCode IS NOT NULL THEN GENCertificates.ContactCode ELSE  GENContacts.Code END) AS AttendeeCode, 
	distinct CASE 
        WHEN GENCertificates.ContactCode IS NOT NULL THEN GENCertificates.ContactCode 
        ELSE GENContacts.Code 
    END AS AttendeeCode,
	--(CASE WHEN GENCertificates.ContactName IS NOT NULL THEN GENCertificates.ContactName ELSE  GENContacts.Name END) AS AttendeeName, 
     CASE 
        WHEN gensalutations.id IS NULL AND (GENContacts.GenderId = 34616 or GENContacts.GenderId is null)
            THEN  (case when GENListValues.ShortCode = 'en' then 'That Mr.' else N'أن السيد ' end)  +'/ '+ (CASE WHEN GENCertificates.ContactName IS NOT NULL THEN GENCertificates.ContactName ELSE  GENContacts.Name END)
        WHEN gensalutations.id IS NULL AND GENContacts.GenderId != 34616 
            THEN  (case when GENListValues.ShortCode = 'en' then 'That Mrs.' else N'أن السيدة ' end)+'/ ' + (CASE WHEN GENCertificates.ContactName IS NOT NULL THEN GENCertificates.ContactName ELSE  GENContacts.Name END)
        WHEN gensalutations.Id IS NOT NULL 
            Then (case when GENListValues.ShortCode = 'en' then 'That ' else N'أن ' end)  +  dbo.fn_Salutation_Translate_ByKeyandId(gensalutations.id,'Name',GENListValues.ShortCode) +N'/ ' + (CASE WHEN GENCertificates.ContactName IS NOT NULL THEN GENCertificates.ContactName ELSE  GENContacts.Name END)
                
    END AS AttendeeName ,
	(CASE WHEN GENCertificates.ContactId IS NOT NULL THEN GENCertificates.ContactId ELSE  GENContacts.Id END) AS AttendeeId,
	GENClassrooms.CourseId  AS CourseId, GENTypes.Name AS CourseName, GENTypes.Code AS CourseCode,
	GENWikiCategories.Name AS CertificateType,
	wiki.Name AS CertificateName, wiki.String1 AS Signature1, wiki.String2 AS Signature1Title,wiki.String3 AS Signature2, wiki.String4 AS Signature2Title,
	wiki.String5 AS UnderName, wiki.Description AS UnderNameDescription,
	(CASE WHEN GENCertificates.SerialNo IS NOT NULL THEN GENCertificates.SerialNo ELSE Null END ) AS SerialNo ,
	(CASE WHEN GENCertificates.SerialNo IS NOT NULL THEN GENCertificates.SerialNo ELSE N'بجب الضغط علي أصدار' END ) AS SerialNoMSG
	,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,''  AS Image,GENClassrooms.Code as ClassroomCode,GENClassrooms.Name as ClassroomName
	,GENCities.Name as CityName,GENClassrooms.Id as ClassroomId
	,(case when GENListValues.ShortCode = 'en' then cast(FORMAT(GENClassrooms.FromDateTime,'dd/MM/yyyy') as nvarchar(50))  else [dbo].[FN_ConvertDatetoArabic](cast(FORMAT(GENClassrooms.FromDateTime,'yyyy/MM/dd') as nvarchar(50))) end )  as FromDateTimeString
	,(case when GENListValues.ShortCode = 'en' then  cast(FORMAT(GENClassrooms.ToDateTime,'dd/MM/yyyy') as nvarchar(50)) else [dbo].[FN_ConvertDatetoArabic](cast(FORMAT(GENClassrooms.ToDateTime,'yyyy/MM/dd') as nvarchar(50))) end ) as ToDateTimeString
	,GENContacts.GenderId,GENCertificates.DateCreated
	,FORMAT(GENCertificates.DateCreated,'yyyy/MM/ddHH:mm') AS DateCreatedString
	,'' AS CreatedDateEnc,
	GENCertificates.ImgSig_One,GENCertificates.ImgSig_Two,GENCertificationFrames.Path as RdlcName,GENWikis.Line1,GENWikis.Line2,GENWikis.Line3,GENWikis.Line4
	,GENWikis.BackgroundImg,GENWikis.BannerImg,GENWikis.OfficalLogoImg,GENWikis.GuestLogoImg,GENWikis.FirstSignatueImg,GENWikis.SecondSignatueImg,GENWikis.Base1
	,GENWikis.Base2,GENWikis.Base3, wiki.String5
	FROM GENClassroom_GENContact
	LEFT JOIN GENContacts ON GENClassroom_GENContact.StudentId = GENContacts.Id
	LEFT JOIN GENClassrooms ON GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
	left join GENTypes on GENTypes.Id = GENClassrooms.CourseId
	left join GENCities on GENCities.Id = GENClassrooms.CityId
	CROSS APPLY GENWikis as wiki LEFT JOIN GENWikiCategories ON wiki.WikiCategoryId = GENWikiCategories.Id
	LEFT JOIN GENCertificates ON GENCertificates.ContactId = GENContacts.Id AND GENCertificates.TemplateId = wiki.Id AND GENCertificates.BaseEntityId = 176 AND GENCertificates.EntityId = GENClassrooms.Id
	LEFT JOIN GENWikis On GENWikis.Id = GENClassrooms.WikiId
	Left join GENCertificationFrames on GENCertificationFrames.Id = GENWikis.CertFrameId
	left join GENListValues on GENListValues.Id = GENCertificationFrames.LangId
	left join gensalutations On gensalutations.Id = GENContacts.SalutationId

	WHERE GENContacts.Id in (select ContactId from TempRPTBulks) AND GENClassrooms.Id = @ClassRoomId AND (wiki.Id = @WikiId)--AND GENContact_Talent.Remaining = 0
	and GENClassroom_GENContact.BookingTypeId = 1 --and [dbo].[AttendanceCall](GENContacts.Id,GENClassrooms.Id) >= isnull(GENClassrooms.Int4,@PrecAtt)
END
GO
