CREATE PROCEDURE [dbo].[SP_ContactCertificateClassRoomPreview] --41340,10221 -- SP_ContactCertificateClassRoom 10,10221,10222
	@WikiId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT 
	--DISTINCT (CASE WHEN GENCertificates.ContactCode IS NOT NULL THEN GENCertificates.ContactCode ELSE  GENContacts.Code END) AS AttendeeCode, 
	distinct '001' as AttendeeCode,
   (case when GENListValues.ShortCode = 'en' then 'That Mr.'+'/ '+ N'Ahmed Mohamed Mohamed Khaled' else N'أن السيد '+'/ '+ N'احمد محمد محمد خالد' end)  AS AttendeeName ,cast(123 as bigint) AS AttendeeId,cast(456 as bigint) AS CourseId, N'برامج تدريبية للوافدين من الخارج' AS CourseName, '002' AS CourseCode,
	GENWikiCategories.Name AS CertificateType,
	wiki.Name AS CertificateName, wiki.String1 AS Signature1, wiki.String2 AS Signature1Title,wiki.String3 AS Signature2, wiki.String4 AS Signature2Title,
	wiki.String5 AS UnderName, wiki.Description AS UnderNameDescription,
	N'SerialNo' AS SerialNo , N'بجب الضغط علي أصدار' AS SerialNoMSG
	,dateadd(DAY,-1,GETDATE()) as FromDateTime,GETDATE() as ToDateTime,''  AS Image,N'TAC02-F-IP-T04-1' as ClassroomCode,(case when GENListValues.ShortCode = 'en' then N'The training program “Preventing And Combating Corruption”'  else N'البرنامج المتقدم فى مجال مكافحة الفساد'  end)as ClassroomName
	,(case when GENListValues.ShortCode = 'en' then N'Cairo' else N'القاهرة' end) as CityName,cast(789 as bigint) as ClassroomId
	,(case when GENListValues.ShortCode = 'ar' then [dbo].[FN_ConvertDatetoArabic](cast(FORMAT(dateadd(DAY,-1,GETDATE()),'yyyy/MM/dd') as nvarchar(50))) else cast(FORMAT(dateadd(DAY,-1,GETDATE()),'dd/MM/yyyy') as nvarchar(50)) end ) as FromDateTimeString
	,(case when GENListValues.ShortCode = 'ar' then [dbo].[FN_ConvertDatetoArabic](cast(FORMAT(dateadd(DAY,1,GETDATE()),'yyyy/MM/dd') as nvarchar(50))) else cast(FORMAT(dateadd(DAY,1,GETDATE()),'dd/MM/yyyy') as nvarchar(50)) end )  as ToDateTimeString
	,cast(34616 as bigint) as GenderId,(GETDATE())as DateCreated ,FORMAT(GETDATE(),'yyyy/MM/ddHH:mm') AS DateCreatedString,'' AS CreatedDateEnc,
	wiki.FirstSignatueImg as ImgSig_One,wiki.SecondSignatueImg as ImgSig_Two,GENCertificationFrames.Path as RdlcName,wiki.Line1,wiki.Line2,wiki.Line3,wiki.Line4
	,wiki.BackgroundImg,wiki.BannerImg,wiki.OfficalLogoImg,wiki.GuestLogoImg,wiki.FirstSignatueImg,wiki.SecondSignatueImg,wiki.Base1
	,wiki.Base2,wiki.Base3
	FROM GENWikis wiki
	left join GENCertificationFrames on  GENCertificationFrames.Id= wiki.CertFrameId
	LEFT JOIN GENWikiCategories ON wiki.WikiCategoryId = GENWikiCategories.Id
	left join GENListValues on GENListValues.Id = GENCertificationFrames.LangId
	WHERE (wiki.Id = @WikiId)
END
GO
/****** Object:  StoredProcedure [dbo].[SP_ContactCertificateCourse]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
