/****** Object:  StoredProcedure [dbo].[SP_ContactCertificateTalent]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 06/05/2021
-- Description:	Get Contact Data according to Talent for certificate
-- =============================================
CREATE PROCEDURE [dbo].[SP_ContactCertificateTalent]
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT,
	@TalentId BIGINT,
	@WikiId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT (CASE WHEN GENCertificates.ContactCode IS NOT NULL THEN GENCertificates.ContactCode ELSE  GENContacts.Code END) AS AttendeeCode, 
	(CASE WHEN GENCertificates.ContactName IS NOT NULL THEN GENCertificates.ContactName ELSE  GENContacts.Name END) AS AttendeeName, 
	(CASE WHEN GENCertificates.ContactId IS NOT NULL THEN GENCertificates.ContactId ELSE  GENContacts.Id END) AS AttendeeId,
	GENTalents.Id  AS TalentId, GENTalents.Name AS TalentName, GENTalents.Code AS TalentCode,
	GENWikiCategories.Name AS CertificateType,
	wiki.Name AS CertificateName, wiki.String1 AS Signature1, wiki.String2 AS Signature1Title,wiki.String3 AS Signature2, wiki.String4 AS Signature2Title,
	wiki.String5 AS UnderName, wiki.Description AS UnderNameDescription ,
	(CASE WHEN GENCertificates.SerialNo IS NOT NULL THEN GENCertificates.SerialNo ELSE NULL END ) AS SerialNo
	,GENContact_Talent.StartDate,GENContact_Talent.EndDate
	FROM GENContact_Talent
	LEFT JOIN GENContacts ON GENContact_Talent.ContactId = GENContacts.Id
	LEFT JOIN GENTalents ON GENContact_Talent.TalentId = GENTalents.Id
	CROSS APPLY GENWikis as wiki 
	LEFT JOIN GENWikiCategories ON wiki.WikiCategoryId = GENWikiCategories.Id
	LEFT JOIN GENCertificates ON GENCertificates.ContactId = GENContacts.Id AND GENCertificates.TemplateId = wiki.Id AND GENCertificates.BaseEntityId = 184 AND GENCertificates.EntityId = GENTalents.Id
	WHERE GENContacts.Id = @ContactId AND GENTalents.Id = @TalentId AND (wiki.Id = @WikiId)--AND GENContact_Talent.Remaining = 0
END
GO
/****** Object:  StoredProcedure [dbo].[SP_ContactCertificateTrack]    Script Date: 7/1/2026 10:45:03 AM ******/
