CREATE proc [dbo].[SP_ContactLogsData_Company_InsertNotExist](@typeId bigint , @CompanyType varchar(max) ='CompanyType')
  as
Begin
	if @CompanyType='Source' 
	begin
		INSERT INTO GENCompanies(Name, IsPublish, IsActive,SourceId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
		SELECT distinct ContactLogDatas.Company_Name,0,1,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from ContactLogDatas
		where ContactLogDatas.Company_Name is not null and ContactLogDatas.Company_Name not IN (SELECT DISTINCT sourcetable.Name
		FROM            dbo.GENCompanies AS sourcetable 
		WHERE          (@typeId is null or sourcetable.SourceId =@typeId))
	end
	else
	begin
		INSERT INTO GENCompanies(Name, IsPublish, IsActive,CompanyTypeId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
			SELECT distinct ContactLogDatas.Company_Name,0,1,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from ContactLogDatas
			where ContactLogDatas.Company_Name is not null and ContactLogDatas.Company_Name not IN (SELECT DISTINCT sourcetable.Name
		FROM            dbo.GENCompanies AS sourcetable 
		WHERE          (@typeId is null or sourcetable.CompanyTypeId =@typeId))
	end
End
