CREATE proc [dbo].[SP_ContactLogsData_UpdateCompanyLogsDataListValue4](@typeId bigint =null)
as
update ContactLogDatas 
set ContactLogDatas.ValueId4 = sourcetable.Id
from GENListValues sourcetable
join ContactLogDatas on sourcetable.Name COLLATE SQL_Latin1_General_CP1_CI_AS= ContactLogDatas.GENListValues4_Name COLLATE SQL_Latin1_General_CP1_CI_AS

