/****** Object:  StoredProcedure [dbo].[SP_ConvertGENDataToAnother]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 20/02/2020
-- Description:	Stored procedure to update generic data from entity to another
-- =============================================
CREATE PROCEDURE [dbo].[SP_ConvertGENDataToAnother] 
	-- Add the parameters for the stored procedure here
	@currentBaseEntityId bigint,  -- Current base entity id to select the data according to it
	@currentEntityId bigint,  -- Current entity id to select the data according to it
	@newBaseEntityId bigint,   -- new base entity id to convert to it
	@newEntityId bigint   -- new entity id to convert to it
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	--Update Files
	UPDATE GENFiles
	SET BaseEntityId = @newBaseEntityId,
	EntityId = @newEntityId
	WHERE BaseEntityId = @currentBaseEntityId AND EntityId = @currentEntityId;
    -- Update Images
	UPDATE GENImages
	SET BaseEntityId = @newBaseEntityId,
	EntityId = @newEntityId
	WHERE BaseEntityId = @currentBaseEntityId AND EntityId = @currentEntityId;
	--Update Generic Items
	UPDATE Items_Generic
	SET BaseEntityId = @newBaseEntityId,
	EntityId = @newEntityId
	WHERE BaseEntityId = @currentBaseEntityId AND EntityId = @currentEntityId;
	--Update Contacts Generic
	UPDATE GENContact_Generic
	SET BaseEntityId = @newBaseEntityId,
	EntityId = @newEntityId
	WHERE BaseEntityId = @currentBaseEntityId AND EntityId = @currentEntityId;
	--Update Attachments
	UPDATE GENFileAttachments
	SET BaseEntityId = @newBaseEntityId,
	EntityId = @newEntityId
	WHERE BaseEntityId = @currentBaseEntityId AND EntityId = @currentEntityId;
	--Update 3D Images
	UPDATE GEN3DImage
	SET BaseEntityId = @newBaseEntityId,
	EntityId = @newEntityId
	WHERE BaseEntityId = @currentBaseEntityId AND EntityId = @currentEntityId;
	

END
GO
