CREATE PROCEDURE [dbo].[SP_CountClassrooms]
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select isnull(GENTypes.Id,0) as Id,GENTypes.Name, COUNT(GENClassroom_GENContact.Id) AS CountAttendees FROM GENClassrooms
LEFT JOIN GENClassroom_GENContact ON GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
