/****** Object:  StoredProcedure [dbo].[SP_CoursesEffect]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[SP_CoursesEffect]    --    SP_CoursesEffect '01-01-2019','01-01-2030'
@DateF Datetime,
@DateTo Datetime
AS
BEGIN 
    DECLARE @NoFinalexame INT;
    DECLARE @Participation INT;
    DECLARE @Pos INT;
    DECLARE @ClassroomNameIsMostPositive NVARCHAR(max);
    DECLARE @ClassroomNameIsMostNegative NVARCHAR(max);
    DECLARE @Neg INT;

    -- Get the count of final exams
    SELECT @NoFinalexame = COUNT(*) from
		(SELECT Pre.Id ,Pre.Name
				 FROM GENExamAnswerHeaders PreExHeader
     inner JOIN GENPollCategories Pre ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9  and PreExHeader.IsPosted = 1
	 inner JOIN  GENPollCategories Post ON Pre.Id = Post.ParentId
	 inner JOIN  GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
	 inner JOIN  GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10  AND PostExHeader.ClassroomId = GENClassrooms.Id
	 where((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	 GROUP BY Pre.Id ,Pre.Name
union All 
SELECT Post.Id ,Post.Name
				 FROM GENExamAnswerHeaders PreExHeader
     inner JOIN GENPollCategories Pre ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9  and PreExHeader.IsPosted = 1
	 inner JOIN  GENPollCategories Post ON Pre.Id = Post.ParentId
	 inner JOIN  GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
	 inner JOIN  GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10  AND PostExHeader.ClassroomId = GENClassrooms.Id
	 where((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
     GROUP BY Post.Id ,Post.Name  )as res

    -- Get the count of distinct participants
    SELECT @Participation = COUNT(DISTINCT c.Id)
    FROM gencontacts c
    --INNER JOIN GENExamAnswerHeaders H ON H.StudentId = c.Id 
	 inner JOIN  GENExamAnswerHeaders PreExHeader ON  PreExHeader.StudentId = c.Id         --Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9
     inner JOIN GENPollCategories Pre ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9  and PreExHeader.IsPosted = 1
	 inner JOIN  GENPollCategories Post ON Pre.Id = Post.ParentId
	 inner JOIN  GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
	 inner JOIN  GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10 AND PostExHeader.StudentId = c.Id AND PostExHeader.ClassroomId = GENClassrooms.Id

	where((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

    -- Get the count of positive differences
    SELECT @Pos = COUNT(conttt)
    FROM (
        SELECT 
            CASE 
                WHEN ISNULL(PostExHeader.AnnouncedDegree, 0) = 0 THEN 
                    CAST((ISNULL(PostExHeader.TotalExamScore, 0) * ISNULL(PostExHeader.ExamWeight, 0)) / PostExHeader.TotalScore AS DECIMAL(18, 2))
                ELSE 
                    PostExHeader.AnnouncedDegree 
            END - 
            CASE 
                WHEN ISNULL(PreExHeader.AnnouncedDegree, 0) = 0 THEN 
                    CAST((ISNULL(PreExHeader.TotalExamScore, 0) * ISNULL(PreExHeader.ExamWeight, 0)) / PreExHeader.TotalScore AS DECIMAL(18, 2))
                ELSE 
                    PreExHeader.AnnouncedDegree 
            END AS conttt
        FROM 
            GENPollCategories Pre
        INNER JOIN 
            GENExamAnswerHeaders PreExHeader ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9
        INNER JOIN 
            GENContacts ON PreExHeader.StudentId = GENContacts.Id
        INNER JOIN 
            GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
        INNER JOIN 
            GENPollCategories Post ON Pre.Id = Post.ParentId
        INNER JOIN 
            GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10 AND PostExHeader.StudentId = GENContacts.Id AND PostExHeader.ClassroomId = GENClassrooms.Id
    where ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	) AS T
    WHERE conttt >= 0 ;

    -- Get the classroom name with the most positive score difference
    SELECT TOP 1 @ClassroomNameIsMostPositive = PreExHeader.ClassroomName
    FROM 
        GENPollCategories Pre
    INNER JOIN 
        GENExamAnswerHeaders PreExHeader ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9
    INNER JOIN 
        GENContacts ON PreExHeader.StudentId = GENContacts.Id
    INNER JOIN 
        GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
    INNER JOIN 
        GENPollCategories Post ON Pre.Id = Post.ParentId
    INNER JOIN 
        GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10 AND PostExHeader.StudentId = GENContacts.Id AND PostExHeader.ClassroomId = GENClassrooms.Id
   where ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	  and (  CASE 
            WHEN ISNULL(PostExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PostExHeader.TotalExamScore, 0) * ISNULL(PostExHeader.ExamWeight, 0)) / PostExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PostExHeader.AnnouncedDegree 
        END - 
        CASE 
            WHEN ISNULL(PreExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PreExHeader.TotalExamScore, 0) * ISNULL(PreExHeader.ExamWeight, 0)) / PreExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PreExHeader.AnnouncedDegree 
        END) >= 0
   ORDER BY
        CASE 
            WHEN ISNULL(PostExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PostExHeader.TotalExamScore, 0) * ISNULL(PostExHeader.ExamWeight, 0)) / PostExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PostExHeader.AnnouncedDegree 
        END - 
        CASE 
            WHEN ISNULL(PreExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PreExHeader.TotalExamScore, 0) * ISNULL(PreExHeader.ExamWeight, 0)) / PreExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PreExHeader.AnnouncedDegree 
        END DESC;

    -- Get the classroom name with the most negative score difference
    SELECT TOP 1 @ClassroomNameIsMostNegative = PreExHeader.ClassroomName
    FROM 
        GENPollCategories Pre
    INNER JOIN 
        GENExamAnswerHeaders PreExHeader ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9
    INNER JOIN 
        GENContacts ON PreExHeader.StudentId = GENContacts.Id
    INNER JOIN 
        GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
    INNER JOIN 
        GENPollCategories Post ON Pre.Id = Post.ParentId
    INNER JOIN 
        GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10 AND PostExHeader.StudentId = GENContacts.Id AND PostExHeader.ClassroomId = GENClassrooms.Id
    where ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0)) 
	 and (  CASE 
            WHEN ISNULL(PostExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PostExHeader.TotalExamScore, 0) * ISNULL(PostExHeader.ExamWeight, 0)) / PostExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PostExHeader.AnnouncedDegree 
        END - 
        CASE 
            WHEN ISNULL(PreExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PreExHeader.TotalExamScore, 0) * ISNULL(PreExHeader.ExamWeight, 0)) / PreExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PreExHeader.AnnouncedDegree 
        END) < 0
	ORDER BY
        CASE 
            WHEN ISNULL(PostExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PostExHeader.TotalExamScore, 0) * ISNULL(PostExHeader.ExamWeight, 0)) / PostExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PostExHeader.AnnouncedDegree 
        END - 
        CASE 
            WHEN ISNULL(PreExHeader.AnnouncedDegree, 0) = 0 THEN 
                CAST((ISNULL(PreExHeader.TotalExamScore, 0) * ISNULL(PreExHeader.ExamWeight, 0)) / PreExHeader.TotalScore AS DECIMAL(18, 2))
            ELSE 
                PreExHeader.AnnouncedDegree 
        END ASC;

    -- Get the count of negative differences
    SELECT @Neg = COUNT(conttt)
    FROM (
        SELECT 
            CASE 
                WHEN ISNULL(PostExHeader.AnnouncedDegree, 0) = 0 THEN 
                    CAST((ISNULL(PostExHeader.TotalExamScore, 0) * ISNULL(PostExHeader.ExamWeight, 0)) / PostExHeader.TotalScore AS DECIMAL(18, 2))
                ELSE 
                    PostExHeader.AnnouncedDegree 
            END - 
            CASE 
                WHEN ISNULL(PreExHeader.AnnouncedDegree, 0) = 0 THEN 
                    CAST((ISNULL(PreExHeader.TotalExamScore, 0) * ISNULL(PreExHeader.ExamWeight, 0)) / PreExHeader.TotalScore AS DECIMAL(18, 2))
                ELSE 
                    PreExHeader.AnnouncedDegree 
            END AS conttt
        FROM 
            GENPollCategories Pre
        INNER JOIN 
            GENExamAnswerHeaders PreExHeader ON Pre.Id = PreExHeader.ExamId AND Pre.ExamType = 9
        INNER JOIN 
            GENContacts ON PreExHeader.StudentId = GENContacts.Id
        INNER JOIN 
            GENClassrooms ON GENClassrooms.Id = PreExHeader.ClassroomId
        INNER JOIN 
            GENPollCategories Post ON Pre.Id = Post.ParentId
        INNER JOIN 
            GENExamAnswerHeaders PostExHeader ON Post.Id = PostExHeader.ExamId AND Post.ExamType = 10 AND PostExHeader.StudentId = GENContacts.Id AND PostExHeader.ClassroomId = GENClassrooms.Id
    where ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	) AS T
    WHERE conttt < 0 ;

    -- Select all variables in one row
    SELECT 
        @NoFinalexame AS NoFinalexame, 
        @Participation AS Participation, 
        @Pos AS Pos, 
        @ClassroomNameIsMostPositive AS ClassroomNameIsMostPositive, 
        @ClassroomNameIsMostNegative AS ClassroomNameIsMostNegative, 
        @Neg AS Neg,
		20  AS DataSetNo ;
END;
GO
/****** Object:  StoredProcedure [dbo].[SP_CRMDeal_GetById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--ALTER proc [dbo].[SP_CRMDeal_GetById] (@DealId bigint)
--as
--select * from Deal_View_Update

--where Id = @DealId


CREATE proc [dbo].[SP_CRMDeal_GetById] (@DealId bigint, @BaseEntityId bigint,@POPId bigint =null)
as
DECLARE @ContactId BIGINT = NULL
DECLARE @DefaultAddress NVARCHAR(MAX) = NULL
select @DefaultAddress= DefaultAddress from Deal_View_Update where Id = @DealId

select * from [dbo].[Deal_View_Update] where Id = @DealId

SELECT GENImages.*, GENImages.AzureUri AS Image FROM GENImages WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId

SELECT [dbo].[GENEntity_GENWiki].*, GENWikis.Name AS Name FROM [dbo].[GENEntity_GENWiki] 
LEFT JOIN GENWikis ON [dbo].[GENEntity_GENWiki].WikiId = GENWikis.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId

SELECT GENVideos.*,FORMAT(GENVideos.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,GENListValues.Name AS LanguageName
FROM GENVideos left join
  GENListValues ON GENVideos.LanguageId = GENListValues.Id 
WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId



SELECT GENFiles.*,GENListValues.Name AS LanguageName, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt 
FROM GENFiles
LEFT JOIN GENListValues ON GENFiles.LanguageId = GENListValues.Id
WHERE GENFiles.BaseEntityId = @BaseEntityId AND GENFiles.EntityId = @DealId




SElECT GENContact_Generic.Id,GENContacts.Name,GENContact_Generic.ContactId,GENContact_Generic.ContactUS, CASE
    WHEN GENContacts.Image is null THEN '/Content/images/User-Avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString,(CASE WHEN GENContacts.IsActive = 1 THEN 'True' ELSE 'False' END) AS IsActiveString,
	GENContact_Generic.RelativeRelationId,Relat.Name As RelativeRelationName,Assessment.Name As AssessmentName,CRMSources.Name As SourceName,GENContacts.IsActive,GENContact_Generic.EntityId,GENContact_Generic.BaseEntityId
from  GENContact_Generic left join

	GENContacts ON GENContact_Generic.ContactId=GENContacts.Id  left join
	GENListValues Relat ON GENContact_Generic.RelativeRelationId=Relat.Id left join
	GENListValues Assessment ON GENContacts.AssessmentId=Assessment.Id left join
	CRMSources ON GENContacts.SourceId=CRMSources.Id 
where  GENContact_Generic.EntityId=@DealId and GENContact_Generic.BaseEntityId=@BaseEntityId






 SELECT GENAddresses.*, GENRegions.Name AS RegionName,GENCountries.Name AS CountryName, GENProvinces.Name AS ProvinceName, 
GENGovernorates.Name AS GovernorateName, GENCities.Name AS CityName, GENDistricts.Name AS DistrictName,GENAddressZones.Name AS AddressZoneName, GENAreas.Name AS AreaName,
GENListValues.Name AS AddressTypeName,(CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN 'far fa-check-circle' ELSE '' END ) AS IsDefaultIcon
, (CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END ) AS IsDefault
FROM GENAddresses
LEFT JOIN GENRegions ON GENAddresses.RegionsId = GENRegions.Id
LEFT JOIN GENCountries ON GENAddresses.CountryId = GENCountries.Id
LEFT JOIN GENProvinces ON GENAddresses.ProvinceId = GENProvinces.Id
LEFT JOIN GENGovernorates ON GENAddresses.GovernorateId = GENGovernorates.Id
LEFT JOIN GENCities ON GENAddresses.CityId = GENCities.Id
LEFT JOIN GENDistricts ON GENAddresses.DistrictId = GENDistricts.Id
LEFT JOIN GENAddressZones ON GENAddresses.AddressZoneId = GENAddressZones.Id
LEFT JOIN GENAreas ON GENAddresses.AreaId = GENAreas.Id
LEFT JOIN GENListValues ON GENAddresses.AddressTypeId = GENListValues.Id
 WHERE EntityId = @DealId AND BaseEntityId = @BaseEntityId
 order by IsDefault desc





Select GENBranches.*
From GENBranches
Where GENBranches.BaseEntityId=@BaseEntityId and GENBranches.EntityId=@DealId


SELECT GENPhones.*,GENPhoneTypes.Name AS PhoneTypeName, GENPhones.PhoneNumber AS PhoneNumberPrimary, (CASE WHEN GENPhones.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENPhones
LEFT JOIN GENPhoneTypes ON GENPhones.PhoneTypeId = GENPhoneTypes.Id
WHERE GENPhones.BaseEntityId=@BaseEntityId and GENPhones.EntityId=@DealId
order by IsDefaultIcon desc



SELECT GENEmails.*,GENEmails.Id AS Id2,GENEmailTypes.Name AS EmailTypeName, GENEmails.Email AS EmailPrimary, (CASE WHEN GENEmails.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENEmails
LEFT JOIN GENEmailTypes ON GENEmails.EmailTypeId = GENEmailTypes.Id
WHERE GENEmails.BaseEntityId=@BaseEntityId and GENEmails.EntityId=@DealId
 order by IsDefaultIcon desc



SELECT GENEntityClassifications.*,GENClassifications.Name As ClassificationName
   FROM GENEntityClassifications 
   LEFT JOIN GENClassifications ON GENEntityClassifications.ClassificationId = GENClassifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId

SELECT GENEntitySpecifications.*,GENSpecifications.Name AS SpecificationName,GENUnits.Name As UnitName
   FROM GENEntitySpecifications left join
   GENSpecifications ON GENEntitySpecifications.SpecificationId=GENSpecifications.id left join
   GENUnits ON GENEntitySpecifications.UnitId=GENUnits.id
 WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId

SELECT GENNews.*
   FROM GENNews 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId

   
   
SELECT GenRoles.*,AspNetRoles.Name as RoleName
   FROM GenRoles 
   left join AspNetRoles ON GenRoles.RoleId=AspNetRoles.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId

SELECT GENPointers.*
   FROM GENPointers 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId


SELECT GENAudios.*,FORMAT(GENAudios.DateCreated, 'dd/MM/yyyy') AS DateCreatedString 
FROM GENAudios 
WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId



SELECT GENLinks.*,GENItem_LinkTypes.Name AS LinkTypeName
FROM GENLinks left join
GENItem_LinkTypes ON GENLinks.linkTypeId=GENItem_LinkTypes.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId


SELECT [dbo].[GENEntity_Tag].*, GENTags.Name AS TagName FROM [dbo].[GENEntity_Tag]
LEFT JOIN GENTags ON [dbo].[GENEntity_Tag].TagId = GENTags.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId



SELECT GENEntityPricings.*, GENCurrencies.Name AS CurrencyName, GENRegions.Name AS regionName, GENUnits.Name AS UnitName,
 FORMAT(GENEntityPricings.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString, 
 FORMAT(GENEntityPricings.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString FROM GENEntityPricings
LEFT JOIN GENCurrencies ON GENEntityPricings.CurrencyId = GENCurrencies.Id
LEFT JOIN GENRegions ON GENEntityPricings.RegionId = GENRegions.Id
LEFT JOIN GENUnits ON GENEntityPricings.UnitId = GENUnits.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @DealId 


Select CRMSentEmails.[To], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @DealId and CRMSentEmails.EmailEntityPoPId=@POPId


Select CRMSentEmails.[From], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @DealId and CRMSentEmails.EmailEntityPoPId=@POPId



Select CRMSentEmails.[Cc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @DealId and CRMSentEmails.EmailEntityPoPId=@POPId

Select CRMSentEmails.[Bcc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @DealId and CRMSentEmails.EmailEntityPoPId=@POPId


select AllActivitiesWithDetails.* from AllActivitiesWithDetails
LEFT JOIN [dbo].[Contact_View] ON ActivityContactId = [dbo].[Contact_View].Id OR AllActivitiesWithDetails.ContactPersonId = [dbo].[Contact_View].Id
WHERE AllActivitiesWithDetails.EntityId =@DealId  and AllActivitiesWithDetails.BaseEntityId=@BaseEntityId

exec SP_GetAllChatMessages @POPId,@DealId
GO
