@ColorCode Nvarchar(max),
@IsCheckedOut BIT,
@DateCreated datetime,
@DateUpdated datetime,
@CheckinDate datetime,
@CheckoutDate datetime,
@ExpectedCheckoutDate datetime,
@Timeout int,
@DisplayOrdering int,
@CreatedById Nvarchar(max),
@LastUpdatedById Nvarchar(max),
@CheckoutBy Nvarchar(max),
@String1 Nvarchar(max),
