@Decimal4 decimal(18,2),
@Decimal5 decimal(18,2),
@Bool1 bit,
@Bool2 bit,
@Bool3 bit,
@Bool4 bit,
@Bool5 bit,
@Date1 datetime,
@Date2 datetime,
@Date3 datetime,
@Date4 datetime,
@Date5 datetime,
@ValueId1 bigint,
@ValueId2 bigint,
@ValueId3 bigint,
@ValueId4 bigint,
@ValueId5 bigint,
@IconId bigint,
@IsPosted bit



)

as
INSERT INTO CRMSentEmails
    ( [To],
	[From], 
	Cc,
	Bcc,
	Subject,
	Body,
	ReplyTo,
	IsLater,
	DateSent,
	EmployeeId,
	Code,
	Name,
	Description,
	ColorCode,
	IsCheckedOut,
	DateCreated,
	DateUpdated,
	CheckinDate,
	CheckoutDate,
	ExpectedCheckoutDate,
	Timeout,
	DisplayOrdering,
	CreatedById,
	LastUpdatedById,
	CheckoutBy,
