VALUES 
(@To,@From,@CC,@BCC,@Subject,@Body,@ReplyTo,@IsLater,@DateSent,@EmployeeId,@Code,@Name,@Description,@ColorCode,@IsCheckedOut,@DateCreated,@DateUpdated,@CheckinDate,@CheckoutDate,
@ExpectedCheckoutDate,@Timeout,@DisplayOrdering,@CreatedById,@LastUpdatedById
,@CheckoutBy,@String1,@String2,@String3,@String4,@String5,@Int1,@Int2,@Int3,@Int4,@Int5,@Long1,@Long2,@Long3,@Long4,@Long5
,@Float1,@Float2,@Float3,@Float4,@Float5,@Decimal1,@Decimal2,@Decimal3,@Decimal4,@Decimal5,@Bool1,@Bool2,@Bool3,@Bool4,@Bool5,@Date1,@Date2,@Date3,@Date4,@Date5,
@ValueId1,@ValueId2,@ValueId3,@ValueId4,@ValueId5,@IconId,@IsPosted)


