/****** Object:  StoredProcedure [dbo].[SP_CRMSource_InsertNotExistSources]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE proc [dbo].[SP_CRMSource_InsertNotExistSources](@typeId bigint)
  as
INSERT INTO CRMSources(Name, IsPublish, IsActive,SourceTypeId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
 SELECT distinct CompanyLogDatas.CRMSources_Name,0,1,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from CompanyLogDatas
 where CompanyLogDatas.CRMSources_Name is not null and not EXISTS (SELECT DISTINCT dbo.CompanyLogDatas.CRMSources_Name
FROM            dbo.CompanyLogDatas INNER JOIN
                         dbo.CRMSources AS sourcetable ON dbo.CompanyLogDatas.Name = sourcetable.Name COLLATE Arabic_CI_AS
WHERE          (dbo.CompanyLogDatas.IsNew = 1) and (sourcetable.SourceTypeId is null or sourcetable.SourceTypeId =@typeId))
GO
/****** Object:  StoredProcedure [dbo].[SP_CRMSource_InsertNotExistSourcr]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

  CREATE proc [dbo].[SP_CRMSource_InsertNotExistSourcr](@typeId bigint)
  as
INSERT INTO CRMSources(Name, IsPublish, IsActive,SourceTypeId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
 SELECT CompanyLogDatas.CRMSources_Name,0,0,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from CompanyLogDatas
 where NOT EXISTS (SELECT CRMSources_Name from CRMSources sourcetable
join CompanyLogDatas on sourcetable.Name COLLATE SQL_Latin1_General_CP1_CI_AS= CompanyLogDatas.CRMSources_Name COLLATE SQL_Latin1_General_CP1_CI_AS

where CompanyLogDatas.IsNew = 1  and sourcetable.SourceTypeId is null or sourcetable.SourceTypeId =@typeId)
GO
