SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 23/06/2020
-- Description:	Deactivate user when login attempts exceed 5
-- =============================================
CREATE PROCEDURE [dbo].[SP_DeactivateUserContact]
	-- Add the parameters for the stored procedure here
	@userid nvarchar(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	UPDATE AspNetUsers 
	SET IsActive = 0
	WHERE Id = @userid;

	UPDATE GENContacts
	SET IsActive = 0
	WHERE UserId = @userid
END
GO
