/****** Object:  StoredProcedure [dbo].[SP_DealInfo_InsertNew]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_DealInfo_InsertNew] @DealId bigint
as
INSERT        
INTO              DealInfoes(DealId,SourceName,DealTypeName , CompanyName, DealStageName, CurrencyName, LastUpdatedByName, ContactName, ReasonName, StatusName, ResponsiblePersonName, AssessmentName, AssessmenColor, 
                         AssessmenIcon, PriortyName, PriortyColor, PriortyIcon, DateCreatedString, TimeCreatedString, DateUpdatedString, TimeUpdatedString, ContactEmail, ContactPhone, StatusIcon, StatusSuccessRate, CompanyEmail, 
                         CompanyPhone, ResponsiblePersonImage, StatusComplition, ProcessSuccessRate, ProcessName, IsFinal, IsFirst, IsClosed, StatusColor, ProcessId, TypeName, CreatedByName, ProcessDisplayOrdering, ProcessIcon, 
                         ExpectedCloseDateString, OpenDateString, CreatedByImage, LastUpdatedByImage, CreatedByFirstName, LastUpdatedByFirstName, ResponsiblePersonFirstName, ActivityCount, LastActivityStatus, LastActivityType, 
                         LastActivityTypeIcon, LastActivityDate, LastActivityDateString, LifeDate, LifeDateNumber, valueId1tName, valueId2tName, valueId3tName, valueId4tName, valueId5tName, Value1Style, Value1Color,EscalatedToName,IsMultiTCRS,EscalatedToPosition,CloseDateString,[QuoteName],IsFailure)

SELECT DISTINCT 
                        
                       
                      
                    @DealId, dbo.fn_SourceName_ById(dbo.CRMDeals.SourceId) AS SourceName, 
                      dbo.CRMDealTypes.Name AS DealTypeName, dbo.GENCompanies.Name AS CompanyName, 
                         dbo.CRMDealStages.Name AS DealStageName, dbo.GENCurrencies.Name AS CurrencyName, dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENContacts.Name AS ContactName, 
                         dbo.CRMSRVReasons.Name AS ReasonName, dbo.GENStatus.Name AS StatusName, dbo.GENEmployees.Name AS ResponsiblePersonName, GENListValues_1.Name AS AssessmentName, 
                         GENListValues_1.ColorCode AS AssessmenColor, dbo.fn_Icon_Style(GENListValues_1.IconId) AS AssessmenIcon, dbo.GENListValues.Name AS PriortyName, dbo.GENListValues.ColorCode AS PriortyColor, 
                         dbo.GENStyles.StyleValue AS PriortyIcon, CONVERT(varchar, dbo.CRMDeals.DateCreated, 103) AS DateCreatedString, CONVERT(varchar, dbo.CRMDeals.DateCreated, 108) AS TimeCreatedString, 
                          CONVERT(varchar, dbo.CRMDeals.DateUpdated, 103) AS DateUpdatedString, CONVERT(varchar, dbo.CRMDeals.DateUpdated, 108) AS TimeUpdatedString, 
                         dbo.GENContacts.DefaultEmail AS ContactEmail, dbo.GENContacts.DefaultPhone AS ContactPhone, dbo.fn_Icon_Style(dbo.GENStatus.IconId) AS StatusIcon, dbo.GENStatus.SuccessRate AS StatusSuccessRate, 
                         dbo.GENCompanies.DefaultEmail AS CompanyEmail, dbo.GENCompanies.DefaultPhone AS CompanyPhone, dbo.GENEmployees.Image AS ResponsiblePersonImage, Process.CompletionRate AS StatusComplition, 
                         Process.SuccessRate AS ProcessSuccessRate, Process.StatusName AS ProcessName, Process.IsFinal AS IsFinal, Process.IsFirst AS IsFirst, Process.IsMap AS IsClosed, Process.StatusColor AS StatusColor, 
                         Process.StatusId AS ProcessId, dbo.GENTypes.Name AS TypeName, Created.Name AS CreatedByName, 
                         Process.DisplayOrdering AS ProcessDisplayOrdering, Process.StatusStyle AS ProcessIcon, CONVERT(varchar, dbo.CRMDeals.ExpectedCloseDate, 103) AS ExpectedCloseDateString, CONVERT(varchar, dbo.CRMDeals.OpenDate, 103) AS OpenDateString, 
                         dbo.fn_UserImage_Employee(dbo.CRMDeals.CreatedById) AS CreatedByImage, dbo.fn_UserImage_Employee(dbo.CRMDeals.LastUpdatedById) AS LastUpdatedByImage, 
                         dbo.fn_GetEmployeeFirstNameBy_UserId(dbo.CRMDeals.CreatedById) AS CreatedByFirstName, dbo.fn_GetEmployeeFirstNameBy_UserId(dbo.CRMDeals.LastUpdatedById) AS LastUpdatedByFirstName, 
                         dbo.fn_GetEmployeeFirstNameBy_EmployeeId(dbo.CRMDeals.ResponsiblePersonId) AS ResponsiblePersonFirstName, dbo.fn_ActivityCount_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS ActivityCount, 
                         dbo.fn_LastActivityStatus_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS LastActivityStatus, dbo.fn_LastActivityType_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS LastActivityType, 
                         dbo.fn_LastActivityTypeIcon_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS LastActivityTypeIcon,(SELECT FORMAT(dbo.fn_LastActivityDate_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144),'MM/dd/yyyy hh:mm tt')) AS LastActivityDate, CONVERT(varchar, 
                         dbo.fn_LastActivityDate_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144), 103) AS LastActivityDateString, (cast(DATEDIFF(DAY, dbo.CRMDeals.DateCreated, GETDATE()) AS varchar) + ' Days') AS LifeDate, DATEDIFF(DAY, 
                         dbo.CRMDeals.DateCreated, GETDATE()) AS LifeDateNumber, dbo.fnListValue_ById(dbo.CRMDeals.ValueId1,null) AS valueId1tName, dbo.fnListValue_ById(dbo.CRMDeals.ValueId2,null) AS valueId2tName, 
                         dbo.fnListValue_ById(dbo.CRMDeals.ValueId3,null) AS valueId3tName, dbo.fnListValue_ById(dbo.CRMDeals.ValueId4,null) AS valueId4tName, dbo.fnListValue_ById(dbo.CRMDeals.ValueId5,null) AS valueId5tName, 
                         dbo.fn_Icon_Style(dbo.CRMDeals.ValueId1) AS Value1Style, dbo.fn_ListValueColor_ById(dbo.CRMDeals.ValueId1) AS Value1Color,dbo.fnEmployee_NameById(dbo.CRMDeals.EscalatedTo) as EscalatedToName,dbo.CRMDealTypes.IsMultiTCRS,dbo.fnEmployee_PosisionById(dbo.CRMDeals.EscalatedTo) as EscalatedToPosition, CONVERT(varchar, dbo.CRMDeals.CloseDate, 103) AS CloseDateString,dbo.CRMQuotes.Name as [QuoteName],
						 Process.IsFailure
FROM            dbo.CRMDealStages RIGHT OUTER JOIN
                         dbo.CRMDeals ON dbo.CRMDealStages.Id = dbo.CRMDeals.DealStageId LEFT OUTER JOIN
						     dbo.CRMQuotes  ON dbo.CRMQuotes.Id = dbo.CRMDeals.QuoteId LEFT OUTER JOIN
                         dbo.GENCurrencies ON dbo.CRMDeals.CurrencyId = dbo.GENCurrencies.Id LEFT OUTER JOIN
                         dbo.CRMSRVReasons ON dbo.CRMDeals.ReasonId = dbo.CRMSRVReasons.Id LEFT OUTER JOIN
                         dbo.CRMDealTypes ON dbo.CRMDeals.DealTypeId = dbo.CRMDealTypes.Id LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.CRMDeals.TypeId = dbo.GENTypes.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.CRMDeals.ContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.GENStatus.Id = dbo.CRMDeals.StatusId LEFT OUTER JOIN
                         dbo.GENStyles RIGHT OUTER JOIN
                         dbo.GENListValues ON dbo.GENListValues.IconId = dbo.GENStyles.Id ON dbo.GENListValues.Id = dbo.CRMDeals.PriortyId LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_1 ON GENListValues_1.Id = dbo.CRMDeals.AssessmentId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENEmployees.Id = dbo.CRMDeals.ResponsiblePersonId LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.CRMDeals.LastUpdatedById = dbo.AspNetUsers.Id LEFT JOIN
                         dbo.AspNetUsers Created ON dbo.CRMDeals.CreatedById = Created.Id LEFT JOIN
                         dbo.GENCompanies ON dbo.GENCompanies.Id = dbo.CRMDeals.CompanyId CROSS APPLY dbo.tfn_ProcessByEntity(dbo.CRMDeals.Id, 144) AS Process

						 where dbo.CRMDeals.Id =@DealId
GO
/****** Object:  StoredProcedure [dbo].[SP_DealInfo_UpateById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_DealInfo_UpateById] (@DealId bigint)
as
DECLARE @Count bigint
SELECT @Count = COUNT(Id) FROM DealInfoes WHERE DealId = @DealId;
if(@Count > 0)
BEGIN
MERGE INTO DealInfoes
   USING (
          SELECT dbo.CRMDeals.Id AS DealId,
		dbo.fn_SourceName_ById(dbo.CRMDeals.SourceId) AS SourceName, 
                      dbo.CRMDealTypes.Name AS DealTypeName, dbo.GENCompanies.Name AS CompanyName, 
                        dbo.GENCurrencies.Name AS CurrencyName, dbo.AspNetUsers.Name AS LastUpdatedByName, dbo.GENContacts.Name AS ContactName, 
                         dbo.CRMSRVReasons.Name AS ReasonName, dbo.GENStatus.Name AS StatusName, dbo.GENEmployees.Name AS ResponsiblePersonName, GENListValues_1.Name AS AssessmentName, 
                         GENListValues_1.ColorCode AS AssessmenColor, dbo.fn_Icon_Style(GENListValues_1.IconId) AS AssessmenIcon, dbo.GENListValues.Name AS PriortyName, dbo.GENListValues.ColorCode AS PriortyColor, 
                         dbo.GENStyles.StyleValue AS PriortyIcon, CONVERT(varchar, dbo.CRMDeals.DateCreated, 103) AS DateCreatedString, CONVERT(varchar, dbo.CRMDeals.DateCreated, 108) AS TimeCreatedString, 
                          CONVERT(varchar, dbo.CRMDeals.DateUpdated, 103) AS DateUpdatedString, CONVERT(varchar, dbo.CRMDeals.DateUpdated, 108) AS TimeUpdatedString, 
                         dbo.GENContacts.DefaultEmail AS ContactEmail, dbo.GENContacts.DefaultPhone AS ContactPhone, dbo.fn_Icon_Style(dbo.GENStatus.IconId) AS StatusIcon, dbo.GENStatus.SuccessRate AS StatusSuccessRate, 
                         dbo.GENCompanies.DefaultEmail AS CompanyEmail, dbo.GENCompanies.DefaultPhone AS CompanyPhone, dbo.GENEmployees.Image AS ResponsiblePersonImage, Process.CompletionRate AS StatusComplition, 
                         Process.SuccessRate AS ProcessSuccessRate, Process.StatusName AS ProcessName, Process.IsFinal AS IsFinal, Process.IsFirst AS IsFirst, Process.IsMap AS IsClosed, Process.StatusColor AS StatusColor, 
                         Process.StatusId AS ProcessId, dbo.GENTypes.Name AS TypeName, Created.Name AS CreatedByName, 
                         Process.DisplayOrdering AS ProcessDisplayOrdering, Process.StatusStyle AS ProcessIcon, CONVERT(varchar, dbo.CRMDeals.ExpectedCloseDate, 103) AS ExpectedCloseDateString, CONVERT(varchar, dbo.CRMDeals.OpenDate, 103) AS OpenDateString, 
                         dbo.fn_UserImage_Employee(dbo.CRMDeals.CreatedById) AS CreatedByImage, dbo.fn_UserImage_Employee(dbo.CRMDeals.LastUpdatedById) AS LastUpdatedByImage, 
                         dbo.fn_GetEmployeeFirstNameBy_UserId(dbo.CRMDeals.CreatedById) AS CreatedByFirstName, dbo.fn_GetEmployeeFirstNameBy_UserId(dbo.CRMDeals.LastUpdatedById) AS LastUpdatedByFirstName, 
                         dbo.fn_GetEmployeeFirstNameBy_EmployeeId(dbo.CRMDeals.ResponsiblePersonId) AS ResponsiblePersonFirstName, dbo.fn_ActivityCount_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS ActivityCount, 
                         dbo.fn_LastActivityStatus_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS LastActivityStatus, dbo.fn_LastActivityType_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS LastActivityType, 
                         dbo.fn_LastActivityTypeIcon_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144) AS LastActivityTypeIcon, (SELECT FORMAT(dbo.fn_LastActivityDate_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144),'MM/dd/yyyy hh:mm tt'))  AS LastActivityDate, CONVERT(varchar, 
                         dbo.fn_LastActivityDate_ByEntityandBaseEntityId(dbo.CRMDeals.Id, 144), 103) AS LastActivityDateString, (cast(DATEDIFF(DAY, dbo.CRMDeals.DateCreated, GETDATE()) AS varchar) + ' Days') AS LifeDate, DATEDIFF(DAY, 
                         dbo.CRMDeals.DateCreated, GETDATE()) AS LifeDateNumber, dbo.fnListValue_ById(dbo.CRMDeals.ValueId1,NULL) AS valueId1tName, dbo.fnListValue_ById(dbo.CRMDeals.ValueId2,NULL) AS valueId2tName, 
                         dbo.fnListValue_ById(dbo.CRMDeals.ValueId3,NULL) AS valueId3tName, dbo.fnListValue_ById(dbo.CRMDeals.ValueId4,NULL) AS valueId4tName, dbo.fnListValue_ById(dbo.CRMDeals.ValueId5,NULL) AS valueId5tName, 
                         dbo.fn_Icon_Style(dbo.CRMDeals.ValueId1) AS Value1Style, dbo.fn_ListValueColor_ById(dbo.CRMDeals.ValueId1) AS Value1Color,dbo.fnEmployee_NameById(dbo.CRMDeals.EscalatedTo) as EscalatedToName,dbo.CRMDealTypes.IsMultiTCRS,dbo.fnEmployee_PosisionById(dbo.CRMDeals.EscalatedTo) as EscalatedToPosition
						 , CONVERT(varchar, dbo.CRMDeals.CloseDate, 103) AS CloseDateString,dbo.CRMQuotes.Name as [QuoteName],Process.IsFailure
FROM           CRMDeals left join
                         dbo.CRMQuotes  ON dbo.CRMQuotes.Id = dbo.CRMDeals.QuoteId LEFT OUTER JOIN
                         dbo.GENCurrencies ON dbo.CRMDeals.CurrencyId = dbo.GENCurrencies.Id LEFT OUTER JOIN
                         dbo.CRMSRVReasons ON dbo.CRMDeals.ReasonId = dbo.CRMSRVReasons.Id LEFT OUTER JOIN
                         dbo.CRMDealTypes ON dbo.CRMDeals.DealTypeId = dbo.CRMDealTypes.Id LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.CRMDeals.TypeId = dbo.GENTypes.Id LEFT OUTER JOIN
                         dbo.GENContacts ON dbo.CRMDeals.ContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.GENStatus.Id = dbo.CRMDeals.StatusId LEFT OUTER JOIN
                         dbo.GENStyles RIGHT OUTER JOIN
                         dbo.GENListValues ON dbo.GENListValues.IconId = dbo.GENStyles.Id ON dbo.GENListValues.Id = dbo.CRMDeals.PriortyId LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_1 ON GENListValues_1.Id = dbo.CRMDeals.AssessmentId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENEmployees.Id = dbo.CRMDeals.ResponsiblePersonId LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.CRMDeals.LastUpdatedById = dbo.AspNetUsers.Id LEFT JOIN
                         dbo.AspNetUsers Created ON dbo.CRMDeals.CreatedById = Created.Id LEFT JOIN
						
                         dbo.GENCompanies ON dbo.GENCompanies.Id = dbo.CRMDeals.CompanyId CROSS APPLY dbo.tfn_ProcessByEntity(dbo.CRMDeals.Id, 144) AS Process
		WHERE dbo.CRMDeals.Id = @DealId
         ) Deal
      ON DealInfoes.DealId = Deal.DealId
WHEN MATCHED THEN
   UPDATE 
      SET 
	  
	  [QuoteName] = Deal.[QuoteName],
	 CloseDateString = Deal.CloseDateString,
	 IsFailure = Deal.IsFailure,
	 SourceName = Deal.SourceName,
	 EscalatedToName = Deal.EscalatedToName,
	 IsMultiTCRS = Deal.IsMultiTCRS,
	 EscalatedToPosition = Deal.EscalatedToPosition,
	 DealTypeName  = Deal.DealTypeName,
	  CompanyName= Deal.CompanyName,
	
	   CurrencyName= Deal.CurrencyName,
	    LastUpdatedByName= Deal.LastUpdatedByName,
		 ContactName= Deal.ContactName,
		  ReasonName= Deal.ReasonName,
		   StatusName= Deal.StatusName,
		    ResponsiblePersonName= Deal.ResponsiblePersonName,
			 AssessmentName= Deal.AssessmentName,
			  AssessmenColor= Deal.AssessmenColor, 
                         AssessmenIcon= Deal.AssessmenIcon,
						  PriortyName= Deal.PriortyName,
						   PriortyColor= Deal.PriortyColor, 
						   PriortyIcon= Deal.PriortyIcon,
						    DateCreatedString= Deal.DateCreatedString, 
							TimeCreatedString= Deal.TimeCreatedString,
							 DateUpdatedString= Deal.DateUpdatedString,
							  TimeUpdatedString= Deal.TimeUpdatedString,
							   ContactEmail= Deal.ContactEmail,
							    ContactPhone= Deal.ContactPhone,
								 StatusIcon= Deal.StatusIcon,
								  StatusSuccessRate= Deal.StatusSuccessRate, 
								  CompanyEmail= Deal.CompanyEmail,
								   
                         CompanyPhone= Deal.CompanyPhone, 
						 ResponsiblePersonImage= Deal.ResponsiblePersonImage, 
						 StatusComplition= Deal.StatusComplition,
						  ProcessSuccessRate= Deal.ProcessSuccessRate,
						   ProcessName= Deal.ProcessName,
						    IsFinal= Deal.IsFinal,
							 IsFirst= Deal.IsFirst,
							  IsClosed= Deal.IsClosed, 
							  StatusColor= Deal.StatusColor, 
							  ProcessId= Deal.ProcessId,
							   TypeName= Deal.TypeName,
							    CreatedByName= Deal.CreatedByName, 
								ProcessDisplayOrdering= Deal.ProcessDisplayOrdering,
								 ProcessIcon= Deal.ProcessIcon, 
                         ExpectedCloseDateString= Deal.ExpectedCloseDateString,
						  OpenDateString= Deal.OpenDateString, 
						  CreatedByImage= Deal.CreatedByImage, 
						  LastUpdatedByImage= Deal.LastUpdatedByImage,
						   CreatedByFirstName= Deal.CreatedByFirstName,
						    LastUpdatedByFirstName= Deal.LastUpdatedByFirstName,
							 ResponsiblePersonFirstName= Deal.ResponsiblePersonFirstName, 
							 ActivityCount= Deal.ActivityCount,
							  LastActivityStatus= Deal.LastActivityStatus,
							   LastActivityType= Deal.LastActivityType, 
                         LastActivityTypeIcon= Deal.LastActivityTypeIcon, 
						 LastActivityDate= Deal.LastActivityDate,
						  LastActivityDateString= Deal.LastActivityDateString, 
						  LifeDate= Deal.LifeDate,
						   LifeDateNumber= Deal.LifeDateNumber,
						    valueId1tName= Deal.valueId1tName, 
							valueId2tName= Deal.valueId2tName,
							 valueId3tName= Deal.valueId3tName,
							  valueId4tName= Deal.valueId4tName,
							   valueId5tName= Deal.valueId5tName,
							    Value1Style= Deal.Value1Style, 
								Value1Color= Deal.Value1Color;
 
  
--UPDATE
--    ContactInfoes
--SET
--    GovernrateName = dbo.fnContact_GovernorateString(@ContactId),
--	ProvinceName = dbo.fnContact_ProvinceString(@ContactId),
--    CountryName = dbo.fnContact_CountryString(@ContactId),
--    Address = dbo.fnContact_AddressString(@ContactId),
--    NoOfTickets = dbo.fnContact_TicketCount(@ContactId),
--    AmountPaid = dbo.fnContact_TicketAmountPaid(@ContactId),
--    Phone = dbo.fnContact_PhoneString(@ContactId)
--FROM
--    ContactInfoes
--WHERE
--    ContactInfoes.ContactId = @ContactId
END
ELSE
BEGIN
exec [dbo].[SP_DealInfo_InsertNew] @DealId
END
GO
