CREATE Proc [dbo].[SP_DealItems_ByDealId](@DealId bigint)
as
SELECT        dbo.CRMDealItems.ItemId, dbo.CRMDealItems.DealId, dbo.CRMDealItems.Price, dbo.CRMDealItems.Quantity, dbo.CRMDealItems.UnitId, dbo.CRMDealItems.Discount, dbo.CRMDealItems.Total, dbo.CRMDealItems.DateCreated, 
                         dbo.CRMDealItems.DateUpdated, dbo.CRMDealItems.CreatedById, dbo.CRMDealItems.IsPublish, dbo.CRMDealItems.IsActive, dbo.CRMDealItems.ProjectId, dbo.CRMDealItems.TotalPrice, dbo.CRMDealItems.OpreationId, 
                         dbo.CRMDealItems.DealBillQTY, dbo.CRMDealItems.DealWOQty, dbo.CRMDealItems.IsDeleted, dbo.CRMDealItems.QTYBalance, dbo.CRMDealItems.Id, dbo.GENItems.Name, dbo.GENItems.Image
						 ,(  case dbo.CRMDealItems.OpreationId  WHEN  1 then 'Percentage' when 2 then 'LE' when 0 then null end ) as OpreationName 
FROM            dbo.GENTypes RIGHT  JOIN
                         dbo.GENItems ON dbo.GENTypes.Id = dbo.GENItems.TypeId RIGHT  JOIN
                         dbo.CRMDealItems ON dbo.GENItems.Id = dbo.CRMDealItems.ItemId


						 where  dbo.CRMDealItems.DealId = @DealId
GO
