/****** Object:  StoredProcedure [dbo].[SP_DisplayUnit]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   Proc [dbo].[SP_DisplayUnit]
    --SP_DisplayUnit '2020-10-05', '2024-10-11'
@DateF Datetime ,
@DateTo Datetime 
as
WITH DateRange AS (
    SELECT @DateF AS SessionDate
    UNION ALL
    SELECT DATEADD(DAY, 1, SessionDate)
    FROM DateRange
    WHERE DATEADD(DAY, 1, SessionDate) <= @DateTo
)
select
ClassroomCategoryId,IsNull(VCRId,0)VCRId,VcrName,Code,SessionId,SessionName, Count(studentId)NoOfStudents 
,CAST(DateRange.SessionDate AS DATE) AS SelectedDate,date,FORMAT(DateRange.SessionDate, 'dddd', 'ar-SA') AS Day_Name
,RoomCode,RoomName,InstructorName,SessionFrom,SessionTo
,IsDeleted
from DateRange
left join (
					select   GENClassrooms.ClassroomCategoryId,genclassrooms.ID as VCRId,genclassrooms.Name VcrName, genclassrooms.Code ,TLMSClassroom_Session.Id SessionId,TLMSClassroom_Session.Name SessionName
							,GENClassroom_GENContact.studentId,genclassrooms.FromDateTime as date,TLMSClassroom_Session.FromDateTime,GENRooms.Code as RoomCode,GENRooms.Name as RoomName,Instructor.Name as InstructorName,TLMSClassroom_Session.FromDateTime as SessionFrom,TLMSClassroom_Session.ToDateTime as SessionTo
							,genclassrooms.IsDeleted,SessionDateTime
							 from TLMSClassroom_Session
							  left join GENEmployees as Instructor on Instructor.Id = TLMSClassroom_Session.InstructorId
							  left join genclassrooms on TLMSClassroom_Session.classroomId = genclassrooms.id 
							  left join GENRooms on GENRooms.Id = genclassrooms.RoomId
							  left join GENClassroom_GENContact on GENClassroom_GENContact.classroomid = genclassrooms.id 
																and GENClassroom_GENContact.studentId is not null and GENClassroom_GENContact.BookingTypeId = 1
							 where genclassrooms.IsDeleted = 0 and genclassrooms.IsActive = 1
									
									
		 ) as res  on cast(res.SessionDateTime as date) = CAST(DateRange.SessionDate as date)
group by ClassroomCategoryId, VCRId,VcrName,Code,SessionId,SessionName
,RoomCode,RoomName,InstructorName,SessionFrom,SessionTo
,IsDeleted,date,SessionDate
order by DateRange.SessionDate
option (maxrecursion 0)
GO
/****** Object:  StoredProcedure [dbo].[SP_DisplayUnitForEveryWeek]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE     Proc [dbo].[SP_DisplayUnitForEveryWeek]
    --SP_DisplayUnitForEveryWeek '2024-10-01', '2024-10-31'
@DateF Datetime ,
@DateTo Datetime
as
SET DATEFIRST 5;
Declare @FirstDateInWeek Datetime ;
Declare @LastDateInWeek Datetime ;
select @FirstDateInWeek =  DATEADD(DAY, 1 - DATEPART(WEEKDAY, @DateF), @DateF);
select @LastDateInWeek =  DATEADD(DAY, 7 - DATEPART(WEEKDAY, @DateTo), @DateTo);
WITH DateRange AS (
    SELECT @FirstDateInWeek AS SessionDate
    UNION ALL
    SELECT DATEADD(DAY, 1, SessionDate)
    FROM DateRange
    WHERE DATEADD(DAY, 1, SessionDate) <= @LastDateInWeek
)
select
ClassroomCategoryId,IsNull(VCRId,0)VCRId,VcrName,Code,SessionId,SessionName, Count(studentId)NoOfStudents 
,CAST(DateRange.SessionDate AS DATE) AS SelectedDate,date,FORMAT(DateRange.SessionDate, 'dddd', 'ar-SA') AS Day_Name
,RoomCode,RoomName,InstructorName,SessionFrom,SessionTo
,IsDeleted,cast((SELECT DATEPART(WEEK, SessionDate) - DATEPART(WEEK, DATEADD(MONTH, DATEDIFF(MONTH, 0, SessionDate), 0)) + 1 AS WeekOfMonth)as nvarchar(50)) + '-'+ cast(MONTH(SessionDate) as nvarchar(50)) AS NumberOfWeeks,
cast((SELECT DATEPART(WEEK, SessionDate) - DATEPART(WEEK, DATEADD(MONTH, DATEDIFF(MONTH, 0, SessionDate), 0)) + 1 AS WeekOfMonth)as nvarchar(50)) WeekNumber,
cast(MONTH(SessionDate) as nvarchar(50))as MonthNumber, DATEPART(week, CAST(DateRange.SessionDate AS DATE))AS WeekNumberInYear

--,CONVERT(TIME, genclassrooms.FromDateTime) AS SelectedTime 
from DateRange
left join (
					select   GENClassrooms.ClassroomCategoryId,genclassrooms.ID as VCRId,genclassrooms.Name VcrName, genclassrooms.Code ,TLMSClassroom_Session.Id SessionId,TLMSClassroom_Session.Name SessionName
							,GENClassroom_GENContact.studentId,genclassrooms.FromDateTime as date,TLMSClassroom_Session.FromDateTime,GENRooms.Code as RoomCode,GENRooms.Name as RoomName,Instructor.Name as InstructorName,TLMSClassroom_Session.FromDateTime as SessionFrom,TLMSClassroom_Session.ToDateTime as SessionTo
							,genclassrooms.IsDeleted,SessionDateTime
							 from TLMSClassroom_Session
							  left join GENEmployees as Instructor on Instructor.Id = TLMSClassroom_Session.InstructorId
							  left join genclassrooms on TLMSClassroom_Session.classroomId = genclassrooms.id 
							  left join GENRooms on GENRooms.Id = genclassrooms.RoomId
							  left join GENClassroom_GENContact on GENClassroom_GENContact.classroomid = genclassrooms.id 
																and GENClassroom_GENContact.studentId is not null
							 where genclassrooms.IsDeleted = 0 and genclassrooms.IsActive = 1 and genclassrooms.ProsecutionId = 0
									
									
		 ) as res  on cast(res.SessionDateTime as date) = CAST(DateRange.SessionDate as date)
--where genclassrooms.Name is not null
group by ClassroomCategoryId, VCRId,VcrName,Code,SessionId,SessionName
,RoomCode,RoomName,InstructorName,SessionFrom,SessionTo
,IsDeleted,date,SessionDate
order by DateRange.SessionDate,SessionFrom,SessionTo
OPTION (MAXRECURSION 0) -- Increase recursion limit if needed
GO
