CREATE Proc [dbo].[SP_Employee_SelectByAspuserEmail] (@Email nvarchar(250))
as
SELECT    TOP 1  GENEmployees.*
FROM            dbo.GENEmployees RIGHT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENEmployees.UserId = dbo.AspNetUsers.Id
WHERE        (dbo.AspNetUsers.UserName = @Email or dbo.GENEmployees.Email =  @Email) and dbo.GENEmployees.UserId is not null --and dbo.GENEmployees.EmployeeTypeId =1
