/****** Object:  StoredProcedure [dbo].[SP_EventsParticipation]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_EventsParticipation]  --SP_EventsParticipation '2019-01-01', '2026-01-01'
-- '2019-01-01', '2026-01-01'
@DateF Datetime,
@DateTo Datetime
As 
Begin
    select id,CategoriesName as CategoriesName, sum(Time_Execution) Time_Execution, Sum(Participations) as Participations, DataSetNo ----isnull(CategoriesName,N'أخري') as CategoriesName
    from (
        select GENListValues.id,  
               GENListValues.Name as CategoriesName, 
               count(distinct g.Id) as Time_Execution, 
               sum(g.int1) + isnull(dbo.fn_VcrStudentCount(g.id), 0) as Participations, 
               7 as DataSetNo
        from GenClassrooms g    
        left join GENListValues 
               on GENListValues.Id = g.EventTypeId 
               and GENListValues.isdeleted = 0 
               and GENListValues.isActive = 1
        left join GENCompanies on GENCompanies.Id = g.CompanyId
        where g.classroomcategoryId = 2 
        and g.IsDeleted = 0 
        and g.IsActive = 1 
		and g.classroomstatus = 2
        and (
              (cast(g.FromDateTime as date) >= cast(@DateF as date) 
              and cast(g.FromDateTime as date) <= cast(@DateTo as date)) 
              or 
              (@DateF is null and @DateTo is null 
              and (cast(g.FromDateTime as date) >= cast(DATEADD(month, -1, GETDATE()) as date) 
              and cast(g.FromDateTime as date) <= cast(GETDATE() as date)))
            )
        group by GENListValues.Name, GENListValues.id, g.id
    ) TT
    group by CategoriesName, id, Time_Execution,DataSetNo
	having TT.id is not null
    order by Time_Execution desc
End
GO
