/****** Object:  StoredProcedure [dbo].[SP_ExamParticipationCountsInfo]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create   PROCEDURE [dbo].[SP_ExamParticipationCountsInfo]
AS
BEGIN
    DECLARE @ExamsCount INT;
    DECLARE @ParticipationCount INT;

    -- Calculate the count of distinct exams
    SELECT @ExamsCount = Count(distinct PostExHeader.Id) 
From GENPollCategories Pre inner join 
GENExamAnswerHeaders PreExHeader ON Pre.Id =PreExHeader.ExamId 
inner join GENContacts ON PreExHeader.StudentId = GENContacts.Id 
inner join GENClassrooms on GENClassrooms.Id = PreExHeader.ClassroomId
inner join GENPollCategories Post ON Pre.Id = Post.ParentId 
inner join GENExamAnswerHeaders PostExHeader ON Post.Id =PostExHeader.ExamId  and PostExHeader.StudentId = GENContacts.Id and PostExHeader.ClassroomId = GENClassrooms.Id;

	

    -- Calculate the count of participations
    SELECT @ParticipationCount =  Count(GENContacts.Id) 
FROM 
        GENPollCategories
    INNER JOIN 
        GENExamAnswerHeaders ON GENPollCategories.Id = GENExamAnswerHeaders.ExamId
    INNER JOIN 
        GENContacts ON GENExamAnswerHeaders.StudentId = GENContacts.Id
    INNER JOIN 
        GENClassrooms ON GENClassrooms.Id = GENExamAnswerHeaders.ClassroomId;
	
    SELECT @ExamsCount AS Exams, @ParticipationCount AS Participation;
END               






----------------
GO
/****** Object:  StoredProcedure [dbo].[SP_ExamsInfo]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_ExamsInfo] --SP_ExamsInfo '2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
as
begin
select * from (
SELECT	distinct GENPollCategories.id, GENPollCategories.Name exams ,count(distinct GENExam_GENClassroom.classroomId) as NoOfPeriod ,COUNT(distinct GENExamAnswerHeaders.StudentId) AS TotalStudents,
			SUM(
        CASE 
            WHEN -GENPollCategories.successScore + (
                CASE 
                    WHEN ISNULL(GENExamAnswerHeaders.[AnnouncedDegree], 0) = 0 THEN 
                        CAST((ISNULL(GENExamAnswerHeaders.[TotalExamScore], 0) * ISNULL(GENExamAnswerHeaders.[ExamWeight], 0)) / GENExamAnswerHeaders.TotalScore AS decimal(18,2))
                    ELSE 
                        GENExamAnswerHeaders.[AnnouncedDegree] 
                END
            ) > 0 THEN 1
            ELSE 0
        END
    ) AS PassedStudents,
    CAST(
        100.0 * SUM(
            CASE 
                WHEN -GENPollCategories.successScore + (
                    CASE 
                        WHEN ISNULL(GENExamAnswerHeaders.[AnnouncedDegree], 0) = 0 THEN 
                            CAST((ISNULL(GENExamAnswerHeaders.[TotalExamScore], 0) * ISNULL(GENExamAnswerHeaders.[ExamWeight], 0)) / GENExamAnswerHeaders.TotalScore AS decimal(18,2))
                        ELSE 
                            GENExamAnswerHeaders.[AnnouncedDegree] 
                    END
                ) > 0 THEN 1
                ELSE 0
            END
        ) / COUNT(*) AS decimal(18, 2)
    ) AS PassPercentage
FROM            dbo.GENPollCategories 
				LEFT  JOIN dbo.PollCategoryandPolls ON dbo.GENPollCategories.Id = dbo.PollCategoryandPolls.PollCategoryId
				left Join GENExam_GENClassroom ON GENExam_GENClassroom.ExamId = GENPollCategories.id
				Left JOIN GENExamAnswerHeaders ON GENPollCategories.Id = GENExamAnswerHeaders.ExamId  
WHERE  isnull(GENPollCategories.ExamType,0)  not in (12,9,10) and 
	((cast(GENPollCategories.DateCreated as date) >= cast(@DateF as date) and cast(GENPollCategories.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENPollCategories.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENPollCategories.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
GROUP BY GENPollCategories.Id,GENPollCategories.Name
)t
order by PassPercentage desc
end
GO
