CREATE PROCEDURE [dbo].[SP_ExportQuestions] @Lang varchar(200)=null
AS
SELECT 
       [GENPolls].[Code]
	  ,[DisplayOrder]
      ,[Question]
      ,[GENPolls].[IsPublish]
      ,[GENPolls].[IsActive]
      ,[GENPolls].[Name] AS QuestionNumber
      ,[Time]
      ,[Weight] AS PassMark
      ,[dbo].[FN_GetQuestionType]([QuestionType],@Lang) AS QuestionType
      ,GENListValues.Name AS [Language]
      ,[dbo].[FN_GetQuestionLevel]([LevelQuestions],@Lang) AS QuestionLevel
      ,[Total]
  FROM [dbo].[GENPolls]
  LEFT JOIN GENListValues ON LanguageId=GENListValues.Id
GO
