	  ,[CRMTickets].[String1] AS EsclateTo
      ,[CRMTickets].[String2] AS SupportReply
      ,[CRMTickets].[String4] AS AssignedTo
      ,[CRMTickets].[String5] AS ShouldBe
	  ,Format([CRMTickets].[Date1],'dd/MM/yyyy') AS ReportingDate
	  ,Format([CRMTickets].[Date2],'dd/MM/yyyy') AS ExpectedDeliveryDate
      ,Format([CRMTickets].[Date3],'dd/MM/yyyy') AS ActualDeliveryDate
	 -- ,[StartDateDiff] AS CreationTime
	  --,[CRMTickets].[Timeout]
	  ,Format([CRMTickets].[DateCreated],'dd/MM/yyyy') as DateCreated
     -- ,[CRMTickets].[DateUpdated]
	  , AspNetUsers.Name AS [CreatedById]
   --   ,[CRMTickets].[LastUpdatedById]
	  --,[CRMTickets].ColorCode
	  --,TicketInfoes.PriortyColor
	  --,TicketInfoes.PriortyIcon
	  --,TicketInfoes.ManagerId
	  --,TicketInfoes.AssessmentName
	  --,TicketInfoes.CountCreated,
	  --TicketInfoes.TotalCountCreated,
	  --TicketInfoes.BrandName, 
	  --TicketInfoes.ActivityDate, 
	  --TicketInfoes.BranchName, 
	  --TicketInfoes.ComplainType_Name, 
	  --TicketInfoes.ComplainClassif_Name, 
	  --TicketInfoes.Satisfaction_Name,  
	  --TicketInfoes.ReservClassifi_Name, 

	  --TicketInfoes.DateReservString, 
	  --TicketInfoes.TimeReservString, 
	  --TicketInfoes.ActivityCount, 
	  --TicketInfoes.CallCount, 
	  --TicketInfoes.ListValueClassificationName, 
	  --TicketInfoes.ReasonTypeIcon, 
	  --TicketInfoes.ReasonTypeColor, 
	  --TicketInfoes.ReasonTypeName, 
	  --TicketInfoes.ReasonIcon, 
	  --TicketInfoes.ReasonColor, 
	  --TicketInfoes.ReasonName, 
	  --TicketInfoes.TicketTypeColor, 
	  --TicketInfoes.TicketTypeIcon, 
	  --TicketInfoes.ComplainClassifIcon,
	  --TicketInfoes.ComplainClassifColor, 
	  --TicketInfoes.ComplainTypeIcon, 
	  --TicketInfoes.ComplainTypeColor, 
	  --TicketInfoes.CurrencyName, 
	  --TicketInfoes.ContactCategoryName,
	  --TicketInfoes.EscalatedToName, 
	  --TicketInfoes.valueId5tName,
	  --TicketInfoes.valueId4tName, 
	  --TicketInfoes.valueId3tName,  
	  --TicketInfoes.numSet
	  FROM [dbo].[CRMTickets] 
  	  LEFT JOIN [CRMSRVTicketTypes] ON [CRMSRVTicketTypes].Id=[TicketTypeId]
	  LEFT JOIN [CRMSources] ON [CRMSources].Id=[SourceId]
	  LEFT JOIN TicketInfoes ON TicketInfoes.TIcketId=[CRMTickets].Id
	  LEFT JOIN GENStatus on TicketInfoes.ProcessId=GENStatus.Id
	  LEFT JOIN GENEmployees ON GENEmployees.Id=[CRMTickets].EmployeeId
	  LEFT JOIN AspNetUsers ON [CRMTickets].CreatedById=AspNetUsers.id
GO
