/****** Object:  StoredProcedure [dbo].[SP_FE_All_StudentCourses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_All_StudentCourses] --SP_FE_UserCourses 'd870812c-8ab3-4f97-b248-f2cffc7f0f84','ar',null
(@userId nvarchar(128) ,@LangCode nvarchar(500),@Id bigint= null,@FromCreate datetime=null,@ToCreate datetime=null )
as
WITH RecursiveCte AS
(
    SELECT  H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,H1.RichContent As Details,H1.Code AS String,H1.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H1.Id) as ImageCategory,H1.Description,IsNull(H1.ParentId,0) AS ParentId
	FROM GENTypeCategories H1
    WHERE H1.Id = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name ,H2.RichContent As Details,H2.Code AS String,H2.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H2.Id) as ImageCategory,H2.Description,IsNull(H2.ParentId,0) AS ParentId
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,
						 dbo.fn_TypeCategories_Translate_ByKeyandId(Field.Id,'Name',@LangCode ) AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId, GENClassrooms.Name AS ClassroomName, 
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			CAST((SUM((CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END)) / CAST((CASE WHEN COUNT(GENItems.Id) > 0 THEN COUNT(GENItems.Id) * 100 ELSE 1 END) AS decimal(18,2))) * 100 AS decimal(18,2) ) AS FinishedPercentge,dbo.GENTypes.Code AS CourseCode,dbo.GENClassrooms.Code AS ClassroomCode,
			dbo.GENTypes.Int1, dbo.GENTypes.Int2,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift
			,GENClassrooms.PaymentCondation,GENListValues.Name AS LangName,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
			,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,
			[dbo].[fn_VcrStudentCount](GENClassrooms.Id) AS TotalStudent
FROM            dbo.GENTypes
left join RecursiveCte on GENTypes.TypeCategoryId = RecursiveCte.Id
 RIGHT OUTER JOIN    GENTypeCategories as Field ON GENTypes.TypeCategoryId =Field.Id RIGHT OUTER JOIN
                         dbo.GENClassroom_GENContact RIGHT OUTER JOIN
                         dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN
			
		 GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
			LEFT JOIN Course_Session ON Course_Session.CourseId = GENTypes.Id
		  LEFT JOIN GENItems ON Course_Session.SessionId = GENItems.Id
		LEFT OUTER JOIN  dbo.TLMSClassroom_Session ON dbo.GENClassrooms.Id = dbo.TLMSClassroom_Session.ClassroomId LEFT JOIN
			dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id
WHERE        (dbo.GENContacts.UserId = @userId) and dbo.GENClassrooms.isActive =1 AND GENClassrooms.IsDeleted=0 AND GENTypes.IsDeleted=0  and  GENClassrooms.IsPublish=1 
and (RecursiveCte.Id is not null or @Id is null)  and GENClassrooms.DestinationsId is null and GENClassrooms.ProsecutionId=0 and GENClassroom_GENContact.BookingTypeId=1
and (GENClassrooms.IsPrivate=0 or GENClassrooms.IsPrivate is null) 
--and ((GENClassrooms.FromDateTime <= GETDATE() AND GENClassrooms.ToDateTime >= GETDATE()))



GROUP BY 
dbo.GENTypes.Id,  dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.GENClassrooms.ToDateTime,
                         dbo.GENClassrooms.FromDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 , dbo.GENClassrooms.Id,Field.Name, Field.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENListValues.shortCode,dbo.GENClassrooms.Code,GENTypes.Code,dbo.GENTypes.Int1, dbo.GENTypes.Int2,
			GENClassrooms.Date1,GENClassrooms.Date2,GENClassrooms.ClassRoomShift,GENClassrooms.PaymentCondation,GENListValues.Name
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_AllCoursesRelatedCat]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_AllCoursesRelatedCat] -- SP_FE_AllCoursesRelatedCat 'ar',null,'d870812c-8ab3-4f97-b248-f2cffc7f0f84'
(@LangCode nvarchar(500),@Id bigint= null,@UserId nvarchar(500) = null,@SrchValue nvarchar(500) = '')
AS
Begin

WITH RecursiveCte AS
(
    SELECT  H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,H1.RichContent As Details,H1.Code AS String,H1.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H1.Id) as ImageCategory,H1.Description,IsNull(H1.ParentId,0) AS ParentId
	FROM GENTypeCategories H1
    WHERE H1.Id = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name ,H2.RichContent As Details,H2.Code AS String,H2.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H2.Id) as ImageCategory,H2.Description,IsNull(H2.ParentId,0) AS ParentId
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
SELECT   distinct
   dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  
               
			dbo.fn_Type_Translate_ByKeyandId(dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, 
			dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
			dbo.GENTypes.IsPublish, 
			dbo.GENTypes.IsActive, 
            dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
			dbo.GENTypes.Id AS CourseId, 
			dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
			STRING_AGG(RecursiveCte.Name,'-') AS FieldName,
			cast(0 as bigint) AS FieldId,
			dbo.GENTypes.Code AS CourseCode
			,GENRatings.IsFavourite,(case when GENEntityPricings.id is not null then isnull(GENEntityPricings.NetPrice,0) else Cast(0 as decimal(18,4)) end) as defauiltCoursePrice

FROM        dbo.GENTypes 
			left join CourseCategories ON GENTypes.Id=CourseCategories.CourseId
            left join RecursiveCte on CourseCategories.categoryId = RecursiveCte.Id
			left join GENRatings on GENRatings.EntityId = dbo.GENTypes.Id and GENRatings.BaseEntityId = 28 and GENRatings.UserId = @UserId
			left join GENEntityPricings on GENEntityPricings.EntityId = dbo.GENTypes.Id and GENEntityPricings.BaseEntityId = 28 and GENEntityPricings.PriceType = 1
		  where GENTypes.IsDeleted=0 and GENTypes.IsPublish=1 and GENTypes.isactive=1 
		  and (RecursiveCte.Id is not null or @Id is null) 
		  and (dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) like N'%' + @SrchValue +'%' or @SrchValue is null or len(@SrchValue) = 0)
		  --and GENTypes.TypeCategoryId=(Select Value from GENConfigurations where Name=N'TrainingTypeCat')
		 -- order by dbo.GENTypes.Name
		 group by dbo.GENTypes.Id,dbo.GENTypes.DisplayOrdering,dbo.GENTypes.IsPublish,dbo.GENTypes.IsActive, dbo.GENTypes.Code,GENRatings.IsFavourite,GENEntityPricings.id,GENEntityPricings.NetPrice
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_AllEmployeeCourses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_AllEmployeeCourses] 
(@userId nvarchar(128) ,@LangCode nvarchar(500),@FromCreate datetime=null,@ToCreate datetime=null,
@courseName nvarchar(MAX)=null,@vcrName nvarchar(MAX)=null,@shiftId bigint=null,@langId bigint =null
)
--SP_FE_AllEmployeeCourses 'beae3111-fbb5-4506-a43a-b67fe5ae80f9','en',null,null,null,null,null,null
--SP_FE_AllEmployeeCourses '86b6be65-4c06-4bde-95fe-cd3102c3290e','ar',null,null
as
SELECT    DISTINCT  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, 
dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
            dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
			DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
			dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed,
			dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,'' AS FieldName, cast(0 as bigint) AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,
			COUNT(DISTINCT GENClassroom_GENContact.StudentId) AS StudentsCount,
			dbo.GENClassrooms.Name AS ClassroomName,
			(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift,
			FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,
			[dbo].[fn_VcrStudentCount](GENClassrooms.Id) AS TotalStudent,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays,
			GENListValues.Name AS LangName,GENRooms.Name AS RoomName,GENGovernorates.Name AS LocationTypeName

FROM        dbo.GENClassrooms inner  JOIN
            dbo.GENTypes ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId inner  JOIN
			dbo.TLMSClassroom_Session ON dbo.GENClassrooms.Id = dbo.TLMSClassroom_Session.ClassroomId inner  JOIN
            dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id  inner  JOIN
			dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id inner JOIN
            dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id inner JOIN
			coursecategories ON GENTypes.Id =coursecategories.courseId inner JOIN
			dbo.GENTypeCategories Field ON dbo.coursecategories.CategoryId = Field.Id left join 
			GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
			GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id

WHERE        (dbo.GENEmployees.UserId = @userId) and dbo.GENClassrooms.isActive =1 and GENClassrooms.IsDeleted=0 and GENTypes.IsDeleted=0  and 
GENClassrooms.ClassroomCategoryId=1 
and ((cast(GENClassrooms.FromDateTime as date) <= cast(@FromCreate as date) and cast(GENClassrooms.ToDateTime as date) >= cast(@ToCreate as date)) 
or (@FromCreate is null and @ToCreate is null and 
((cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date) and cast(GENClassrooms.ToDateTime as date) >= cast(GETDATE() as date)) ) )
or (len(@FromCreate) = 0 and len(@ToCreate) = 0)) AND  classroomStatus <> 1
and (GENTypes.Name like N'%'+@courseName+'%' or len(@courseName) = 0 or @courseName is null)
and (GENClassrooms.Name like N'%'+@vcrName+'%' or len(@vcrName) = 0 or @vcrName is null)
and (GENClassrooms.ClassRoomShift = @shiftId or @shiftId is null)
and (GENClassrooms.LanguageId = @langId or @langId is null) AND  classroomStatus is not null
GROUP By dbo.GENTypes.Id,dbo.GENClassrooms.ToDateTime,dbo.GENClassrooms.FromDateTime,dbo.GENClassroom_GENContact.IsConfirmed,dbo.GENTypes.int1,
dbo.GENClassrooms.Id,Field.Id,Field.Name, GENEmployees.Name,GENEmployees.Id, dbo.GENTypes.DisplayOrdering, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
GENListValues.ShortCode,dbo.GENClassrooms.Name,GENClassrooms.ClassRoomShift,GENListValues.Name,GENRooms.Name,
GENGovernorates.Name
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_AllEmployeeCoursesCancel]    Script Date: 7/1/2026 10:45:03 AM ******/
