CREATE Proc [dbo].[SP_FE_AllEmployeeCoursesCancel] (@userId nvarchar(128) ,@LangCode nvarchar(500),@FromCreate datetime=null,@ToCreate datetime=null

,
@courseName nvarchar(MAX)=null,@vcrName nvarchar(MAX)=null,@shiftId bigint=null,@langId bigint =null
)

--  SP_FE_AllEmployeeCoursesCancel N'86b6be65-4c06-4bde-95fe-cd3102c3290e','ar',null,null,null,null,null,null
as
SELECT    DISTINCT  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, 
dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
            dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
			DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
			dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed,
			dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,dbo.fn_ListValue_Translate_ByKeyandId(Field.Id,'Name', @LangCode) AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,
			COUNT(DISTINCT GENClassroom_GENContact.StudentId) AS StudentsCount,
			dbo.GENClassrooms.Name AS ClassroomName,
			(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift,
			FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,
			[dbo].[fn_VcrStudentCount](GENClassrooms.Id) AS TotalStudent,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays,
			GENListValues.Name AS LangName,GENRooms.Name AS RoomName,GENGovernorates.Name AS LocationTypeName
FROM        dbo.GENClassrooms inner  JOIN
            dbo.GENTypes ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId inner  JOIN
			dbo.TLMSClassroom_Session ON dbo.GENClassrooms.Id = dbo.TLMSClassroom_Session.ClassroomId inner  JOIN
            dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id  inner  JOIN
			dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id inner JOIN
            dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id inner JOIN
			coursecategories ON GENTypes.Id =coursecategories.courseId inner JOIN
			dbo.GENTypeCategories Field ON dbo.coursecategories.CategoryId = Field.Id left join 
			GENRooms ON GENClassrooms.RoomId=GENRooms.Id left join 
			GENGovernorates ON GENClassrooms.GovernorateId=GENGovernorates.Id
WHERE        (dbo.GENEmployees.UserId = @userId) and dbo.GENClassrooms.isActive =1 and GENClassrooms.IsDeleted=0 and GENTypes.IsDeleted=0  and 
GENClassrooms.ClassroomCategoryId=1 
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@FromCreate as date) and cast(GENClassrooms.ToDateTime as date) <= cast(@ToCreate as date)) 
or (len(@FromCreate) = 0 and len(@ToCreate) = 0)  or( @FromCreate  is null and @ToCreate is null )) 
AND  classroomStatus=1
and (GENTypes.Name like N'%'+@courseName+'%' or len(@courseName) = 0 or @courseName is null)
and (GENClassrooms.Name like N'%'+@vcrName+'%' or len(@vcrName) = 0 or @vcrName is null)
and (GENClassrooms.ClassRoomShift = @shiftId or @shiftId is null)
and (GENClassrooms.LanguageId = @langId or @langId is null)
GROUP By dbo.GENTypes.Id,dbo.GENClassrooms.ToDateTime,dbo.GENClassrooms.FromDateTime,dbo.GENClassroom_GENContact.IsConfirmed,dbo.GENTypes.int1,
dbo.GENClassrooms.Id,Field.Id,Field.Name, GENEmployees.Name,GENEmployees.Id, dbo.GENTypes.DisplayOrdering, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
GENListValues.ShortCode,dbo.GENClassrooms.Name,GENClassrooms.ClassRoomShift,GENListValues.Name,GENRooms.Name,GENGovernorates.Name
