GO
CREATE Proc [dbo].[SP_FE_AllUserCourses] (@userId nvarchar(128) ,@LangCode nvarchar(500))
as
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode)AS CourseName,  
			dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, 
			dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
			dbo.GENTypes.IsPublish, 
			dbo.GENTypes.IsActive, 
            dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
			dbo.GENTypes.Id AS CourseId, 
			dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
			DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
			dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, 
			dbo.GENClassroom_GENContact.IsConfirmed,
			dbo.GENTypes.int1 as CoueseHours, 
			dbo.GENClassrooms.Id AS ClassroomId,
			--dbo.fn_ListValue_Translate_ByKeyandId(Field.Id,'Name', @LangCode) AS FieldName, Field.Id AS FieldId,
			dbo.fn_TypeCategories_Translate_ByKeyandId(GENTypeCategories.Id ,'Name', @LangCode) AS FieldName,GENTypeCategories.Id AS FieldId,
			GENEmployees.Name AS InstructorName, 
			GENEmployees.Id AS InstructorId,
			dbo.GENTypes.Code AS CourseCode,
			dbo.GENClassrooms.Code AS ClassroomCode
FROM        dbo.GENTypes RIGHT OUTER JOIN
	      GENTypeCategories ON GENTypes.TypeCategoryId =GENTypeCategories.Id RIGHT OUTER JOIN
            dbo.GENClassroom_GENContact RIGHT OUTER JOIN
            dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
            dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId LEFT OUTER JOIN
			dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id LEFT JOIN
            dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT JOIN
			dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE        (dbo.GENContacts.UserId = @userId) and (dbo.GENClassrooms.isActive =1 OR dbo.GENClassrooms.Id IS NULL)
UNION 
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  
			dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, 
			dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
			dbo.GENTypes.IsPublish, 
			dbo.GENTypes.IsActive, 
            dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
			dbo.GENTypes.Id AS CourseId, 
			dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
			0 AS RestDays, 
			NULL AS FromDateTime, NULL AS ToDateTime, 
			'True' AS IsConfirmed,
			dbo.GENTypes.int1 as CoueseHours, 
			NULL AS ClassroomId,
			--dbo.fn_ListValue_Translate_ByKeyandId(Field.Id,'Name', @LangCode) AS FieldName, Field.Id AS FieldId,
			dbo.fn_TypeCategories_Translate_ByKeyandId(GENTypeCategories.Id ,'Name', @LangCode) AS FieldName,GENTypeCategories.Id AS FieldId,
			NULL AS InstructorName, 
			NULL AS InstructorId,
			dbo.GENTypes.Code AS CourseCode,
			NULL AS ClassroomCode
FROM        dbo.GENTypes LEFT OUTER JOIN
			GENTypeCategories ON GENTypes.TypeCategoryId =GENTypeCategories.Id RIGHT OUTER JOIN
            dbo.Contacts_Courses ON dbo.Contacts_Courses.CourseId = dbo.GENTypes.Id RIGHT OUTER JOIN
            dbo.GENContacts ON dbo.Contacts_Courses.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
			dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE        (dbo.GENContacts.UserId = @userId) and (dbo.Contacts_Courses.ClassRoomId IS NULL AND dbo.Contacts_Courses.CourseStatus = 0)
GO
