CREATE Proc [dbo].[SP_FE_AllUserCoursesOwned_AcaDegree] (@userId nvarchar(128) ,@LangCode nvarchar(500))
as
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  
			dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, 
			dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
			dbo.GENTypes.IsPublish, 
			dbo.GENTypes.IsActive, 
            dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
			dbo.GENTypes.Id AS CourseId, 
			dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
			0 AS RestDays, 
			NULL AS FromDateTime, NULL AS ToDateTime, 
			'True' AS IsConfirmed,
			dbo.GENTypes.int1 as CourseHours, 
			dbo.GENTypes.Int2 as CourseMinutes, 
			NULL AS ClassroomId,
			dbo.fn_ListValue_Translate_ByKeyandId(Field.Id,'Name', @LangCode) AS FieldName, Field.Id AS FieldId,
			NULL AS InstructorName, 
			NULL AS InstructorId,
			dbo.GENTypes.Code AS CourseCode,
			NULL AS ClassroomCode,
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			CAST((SUM((CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END)) / CAST((CASE WHEN COUNT(GENItems.Id) > 0 THEN COUNT(GENItems.Id) * 100 ELSE 1 END) AS decimal(18,2))) * 100 AS decimal(18,2) ) AS FinishedPercentge
FROM        dbo.GENTypes RIGHT OUTER JOIN
            dbo.Contacts_Courses ON dbo.Contacts_Courses.CourseId = dbo.GENTypes.Id RIGHT OUTER JOIN
            dbo.GENContacts ON dbo.Contacts_Courses.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
			dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id left join 
			GENClassrooms ON GENTypes.Id=GENClassrooms.CourseId 
			LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENItems ON GENItems.TypeId = GENTypes.Id
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.EntityId =  dbo.GENItems.Id  AND GENContactProgressCompletions.CourseId = dbo.GENTypes.Id
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
WHERE        dbo.GENContacts.UserId = @userId and dbo.GENTypes.isActive =1 AND (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) 
and GENClassrooms.ProsecutionId=1
GROUP BY dbo.GENTypes.Id, dbo.GENTypes.DisplayOrdering, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.GENTypes.int1, dbo.GENTypes.Int2, Field.Id, dbo.GENTypes.Code
