/****** Object:  StoredProcedure [dbo].[SP_FE_CalcDaysHoursInVCR]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_FE_CalcDaysHoursInVCR] (@StudentId bigint)
AS
Begin

select distinct GENClassrooms.Id,  DATEDIFF(day,  GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) + 1 AS DayinRegVCR,
DATEDIFF(HOUR,FORMAT(GENClassrooms.FromDateTime,'HH:mm'), FORMAT(GENClassrooms.ToDateTime,'HH:mm')) AS TimeinRegVCR,
(DATEDIFF(day,  GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) + 1)*(DATEDIFF(HOUR,FORMAT(GENClassrooms.FromDateTime,'HH:mm'), FORMAT(GENClassrooms.ToDateTime,'HH:mm'))) AS Res,
(GENTypes.Int1 * GENTypes.Int2) as TrainingHour
from GENClassrooms 
inner join  GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
inner join GENContacts on GENContacts.id = GENClassroom_GENContact.StudentId
inner Join  Contacts_Courses ON Contacts_Courses.StudentId = GENContacts.Id
inner Join GENTypes ON GENTypes.CourseType = Contacts_Courses.Id
where GENClassroom_GENContact.StudentId=@StudentId and GENClassrooms.IsActive=1 and GENClassrooms.IsPublish=1 and GENClassrooms.IsDeleted=0 
and GENClassroom_GENContact.BookingTypeId in (1,6)
END
