/****** Object:  StoredProcedure [dbo].[SP_FE_EmployeeCourses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_EmployeeCourses] (@EmployeeId bigint ,@LangCode nvarchar(500))
as
SELECT   dbo.fn_Type_Translate_ByKeyandId(dbo.GENTypes.Id,'Name', @LangCode)AS CourseName
      ,dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
       dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId
	  ,dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
	   DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
	   dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime,
	   dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,
	   GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId
	   ,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
				,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift,
			[dbo].[fn_VcrStudentCount](GENClassrooms.Id) AS TotalStudent, GENClassrooms.IsPrivate
			,dbo.fn_ClassRoom_Translate_ByKeyandId(dbo.GENClassrooms.Id,'Name', @LangCode)AS ClassroomName
			,dbo.fn_Item_Translate_ByKeyandId(dbo.GENItems.Id,'Name', @LangCode)AS SessionName
			,dbo.GENClassrooms.ClassRoomStatus
FROM dbo.GENTypes
       RIGHT JOIN dbo.GENClassrooms ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId 
	   LEFT JOIN dbo.TLMSClassroom_Session on dbo.TLMSClassroom_Session.ClassroomId = dbo.GENClassrooms.Id
	   LEFT JOIN dbo.GENEmployees ON dbo.TLMSClassroom_Session.InstructorId = GENEmployees.Id 
	   LEFT JOIN dbo.GENItems ON dbo.TLMSClassroom_Session.SessionId = GENItems.Id 
WHERE        (dbo.GENEmployees.Id = @EmployeeId) and dbo.GENClassrooms.isActive =1 
and dbo.GENClassrooms.IsDeleted = 0 and dbo.GENClassrooms.IsPublish = 1
GO
