/****** Object:  StoredProcedure [dbo].[SP_FE_EmployeeDashboardNumbers]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_FE_EmployeeDashboardNumbers]
	-- Add the parameters for the stored procedure here
	@Id BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select CASE WHEN (GENClassrooms.FromDateTime >= GETDATE() AND GENClassrooms.ToDateTime >= GETDATE())
THEN Count(DISTINCT GENClassroom_GENContact.Id) ELSE 0 END AS FutureStudents,
CASE WHEN (GENClassrooms.FromDateTime <= GETDATE() AND GENClassrooms.ToDateTime >= GETDATE())
THEN Count(DISTINCT GENClassroom_GENContact.Id) ELSE 0 END AS CurrentStudents,
CASE WHEN (GENClassrooms.FromDateTime <= GETDATE() AND GENClassrooms.ToDateTime <= GETDATE())
THEN Count(DISTINCT GENClassroom_GENContact.Id) ELSE 0 END AS PastStudents,
Count(DISTINCT GENClassroom_GENContact.Id) AS TotalStudents
FROM GENClassroom_GENContact 
inner JOIN GENClassrooms on GENClassroom_GENContact .ClassroomId = GENClassrooms.Id
inner Join TLMSClassroom_Session ON GENClassrooms.Id=TLMSClassroom_Session.ClassroomId
inner JOIN 	dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id 
WHERE GENEmployees.Id = @Id and GENClassrooms.IsDeleted=0 and GENEmployees.IsDeleted=0
GROUP BY GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Id


END
GO
