FROM            dbo.GENTypes RIGHT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = dbo.GENEmployees.Id
