/****** Object:  StoredProcedure [dbo].[SP_FE_EventsByInstructorId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_EventsByInstructorId] (@InstructorId bigint,@FromCreate datetime=null,@ToCreate datetime=null,
@LangCode nvarchar(500),@Current bit=null,@Done bit=null,@Cancelled bit=null)
as
SELECT    DISTINCT  
dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name',@LangCode)AS CourseName,  
dbo.GENClassrooms.Id AS ClassroomId,	
dbo.GENClassrooms.Name AS ClassroomName,
(CASE 
WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' 
WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  
ELSE N'' 
END ) AS ClassShift,
FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,
FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,
FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,
DATEDIFF(day, GENClassrooms.FromDateTime,GENClassrooms.ToDateTime) AS NDays,
[dbo].[fn_VcrStudentCount](GENClassrooms.Id) AS TotalStudent,
GENListValues.name AS LangName,GENClassrooms.CourseId
FROM        dbo.GENClassrooms 
left  JOIN dbo.GENTypes ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId
left  JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id
left  JOIN GENClassroom_GENContact ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
left join GENEmployees ON GENClassrooms.InstructorId= GENEmployees.Id
WHERE        dbo.GENClassrooms.isActive =1 and GENClassrooms.IsDeleted=0  and 
GENClassrooms.ClassroomCategoryId=2 and GENEmployees.Id=@InstructorId
and (@FromCreate IS null or @FromCreate='' or @FromCreate<=GENClassrooms.FromDateTime)
and (@ToCreate IS null or @ToCreate='' or DATEADD(Day, 1,@ToCreate)>=GENClassrooms.ToDateTime)
and ((  --Current Conditions
GENClassrooms.FromDateTime<=GETDATE() AND GENClassrooms.ToDateTime>=GETDATE()
) OR @Current IS NULL) 
and ((  --Done Conditions
GENClassrooms.ToDateTime<=GETDATE() AND GENClassrooms.ClassRoomStatus<>1
) OR @Done IS NULL) 
and ((  --Cancelled Conditions
GENClassrooms.ClassRoomStatus=1
) OR @Cancelled IS NULL)
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_Exam_ById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_FE_Exam_ById] @examId bigint,@StudentId bigint,@classroomId bigint
as
SELECT DISTINCT 
                         dbo.GENPolls.Id AS QuestionId, dbo.PollCategoryandPolls.PollCategoryId AS ExamId, dbo.GENPollCategories.Name AS ExamName, 
						 dbo.GENPolls.Question, dbo.GENPolls.DisplayOrdering, dbo.GENPolls.QuestionType, 
                         dbo.GENPolls.Weight, dbo.GENPolls.MinAnsNumber, dbo.GENPolls.MaxAnsNumber, 
						 dbo.GENPollAnswers.Answer, dbo.GENPollAnswers.IsCorrect, dbo.GENPollAnswers.DisplayOrdering AS AnswerDisplayOrder, 
                         dbo.GENPollAnswers.Id AS AnswerId, dbo.PollCategoryandPolls.QdOrder, dbo.GENPolls.Image AS QuestionImage, 
						 dbo.GENPolls.Video AS QuestionVideo, NULL AS QuestionVideoId,
						 dbo.GENPolls.Audio AS QuestionAudio, GENPollAnswers.Image AS AnswerImage,
						 dbo.GENPollAnswers.Name AS AnswerName,dbo.GENPolls.Name AS QuestionName,
						 dbo.GENPolls.[File] AS QuestionFile
						 ,dbo.GENTypes.Code AS CourseCode
						 , dbo.GENTypes.Name AS CourseName
						 , dbo.GENClassrooms.Code as ClassroomCode, 
                         dbo.GENClassrooms.Name as ClassroomName
						 ,dbo.GENPollCategories.Code  as ExamCode
						 ,dbo.GENPollCategories.QuestionDisplayType
						 ,dbo.GENPolls.Bool1 as IsMendatory
						 ,GENExamAnswerDetails.PollAnswerId
FROM            dbo.GENPollCategories RIGHT OUTER JOIN
                         dbo.PollCategoryandPolls ON dbo.GENPollCategories.Id = dbo.PollCategoryandPolls.PollCategoryId LEFT OUTER JOIN
                         dbo.GENPollAnswers RIGHT OUTER JOIN
                         dbo.GENPolls ON dbo.GENPollAnswers.PollId = dbo.GENPolls.Id ON dbo.PollCategoryandPolls.PollId = dbo.GENPolls.Id
						 left join dbo.GENClassrooms  on dbo.GENClassrooms.ExamId = dbo.GENPollCategories.Id
						 LEFT JOIN dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.ID
						 left join GENExamAnswerHeaders on GENExamAnswerHeaders.ExamId = dbo.GENPollCategories.Id 
						 and GENExamAnswerHeaders.StudentId = @StudentId and GENExamAnswerHeaders.ClassroomId = @classroomId
						 left join GENExamAnswerDetails on GENExamAnswerDetails.ExamAnswerHeaderId = GENExamAnswerHeaders.id 
						 and dbo.GENPolls.Id = GENExamAnswerDetails.PollId
WHERE        (dbo.PollCategoryandPolls.PollCategoryId = @examId) and dbo.GENPolls.IsActive=1 
						 ORDER BY dbo.PollCategoryandPolls.QdOrder
GO
