/****** Object:  StoredProcedure [dbo].[SP_FE_GetClassRoomSessionsByClassRoomId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE  [dbo].[SP_FE_GetClassRoomSessionsByClassRoomId] --  [SP_FE_GetClassRoomSessionsByClassRoomId] 52,N'ar'
	@ClassRoomId bigint,@LangCode nvarchar(MAX)
AS
BEGIN
	
	SET NOCOUNT ON;
	SELECT TLMSClassroom_Session.Id, GENItems.Name as SessionName, GENItems.Id as SessionId
    
    -- هنا تم استبدال الحقل القديم بالحقل المجمع من الـ OUTER APPLY بالأسفل
	,InstructorsData.AllInstructors as InstructorName

,GENClassrooms.Name as ClassroomName ,TLMSClassroom_Session.SessionDateTime,
	TLMSClassroom_Session.FromDateTime,TLMSClassroom_Session.ToDateTime,
   dbo.FN_ConvertDaystoArabic((' '+ Datename(weekday, TLMSClassroom_Session.SessionDateTime)  +CHAR(13)+CHAR(10)+
	FORMAT(TLMSClassroom_Session.SessionDateTime,'dd/MM/yyyy')),@LangCode) as SessionDateTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(TLMSClassroom_Session.FromDateTime,'hh:mm'),@LangCode) as FromDateTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(TLMSClassroom_Session.ToDateTime,'hh:mm'),@LangCode) as ToDateTimeString,
	GENClassrooms.FromDateTime as ClassroomFromDateTime,GENClassrooms.ToDateTime as ClassroomToDateTime
	,TLMSClassroom_Session.Name as Name,cast(res.RowNum as nvarchar(500)) as RowNum
	,TLMSClassroom_Session.TypeSession, dbo.FN_SessionsType(TLMSClassroom_Session.TypeSession,@LangCode) AS TypeSessionName
	,TLMSClassroom_Session.InstructorInstructions
	,TLMSClassroom_Session.InteractiveMeetingURL
	,GENClassrooms.InstructorInstructions as Remarks
	,Course.Name as CourseName
	,GENClassrooms.Code as ClassroomCode
	,Lang.Name as LangName
	,GENClassrooms.FromDateTime as ClassroomsFromDateTime
	,GENClassrooms.ToDateTime as ClassroomsToDateTime
	,Room.Name as RoomName
	,Room.Code as Roomcode
	,Emp.Name as EmpName
	,dbo.GENClassrooms.ClassRoomShift
	,(CASE WHEN dbo.GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' WHEN dbo.GENClassrooms.ClassRoomShift = 1 THEN N'مسائي' ELSE N'' END ) AS ClassRoomShiftString
	,datediff(MINUTE,TLMSClassroom_Session.FromDateTime,TLMSClassroom_Session.ToDateTime) as HourCount
	,datediff(Day,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime)+1 as ClassroomsDay,
   dbo.FN_ConvertNumbertoArabic((SELECT count(*) from GENClassroom_GENContact where ClassroomId = @ClassRoomId)) as ContactCount
     
     -- تم أخذ صورة أول محاضر متاح كمثال، أو يمكنك تعديلها حسب الحاجة
     ,InstructorsData.FirstInstructorImage as InstructorImage,

		 Zoom.Name AS ZoomMeeting,Zoom.interactiveMeetingURL AS ZoomInteractiveMeetingURL,Zoom.VideoURL AS ZoomVideoURL,
		  dbo.FN_ConvertDaystoArabic(FORMAT(Zoom.SessionDateTime,'hh:mm'),@LangCode) as ZoomFromTimeString,
		  dbo.FN_ConvertDaystoArabic (FORMAT(DATEADD(MINUTE,Zoom.ZoomDuration,Zoom.SessionDateTime),'hh:mm'),@LangCode) ZoomToTimeString,
	 dbo.FN_ConvertDaystoArabic((' '+ Datename(weekday, Zoom.SessionDateTime)  +CHAR(13)+CHAR(10)+
	FORMAT(Zoom.SessionDateTime,'dd/MM/yyyy')),@LangCode)  as ZoomSessionDateTimeString

	from TLMSClassroom_Session left join 
	GENItems on TLMSClassroom_Session.SessionId=GENItems.Id  Left join  
	GENClassrooms on TLMSClassroom_Session.ClassroomId=GENClassrooms.Id left join 
	(SELECT Datename(weekday, SessionDateTime)  +' '+
	FORMAT(SessionDateTime,'dd/MM')   as SessionDateTimeString,
	  ROW_NUMBER() OVER (ORDER BY SessionDateTime) as RowNum,SessionDateTime
	from TLMSClassroom_Session left join 
	GENItems on TLMSClassroom_Session.SessionId=GENItems.Id 
	where TLMSClassroom_Session.ClassroomId=@ClassRoomId
	group by SessionDateTime
	) res on res.SessionDateTime = TLMSClassroom_Session.SessionDateTime
	left join GENTypes Course on GENClassrooms.CourseId = Course.Id
	left join GENListValues Lang on GENClassrooms.LanguageId = Lang.Id
	left join [GENRooms] Room on GENClassrooms.RoomId = Room.Id
	left join [GENEmployees] Emp on GENClassrooms.InstructorId = Emp.Id
	left join 
    Zoom_Session Zoom ON TLMSClassroom_Session.SessionId=Zoom.SessionId and Zoom.VcrId=@ClassRoomId and Zoom.ZoomType=1
	
	-- استعلام فرعي لتجميع المحاضرين لكل جلسة بناءً على المعرف (SessionId) لعدم تكرار الصفوف
	OUTER APPLY (
		SELECT 
			-- إذا كان إصدار الـ SQL قديم (قبل 2017) استخدم طريقة FOR XML PATH المكتوبة بالأسفل
			STRING_AGG(
				Ltrim(SubString(EmpSub.Name,1,Isnull(Nullif(CHARINDEX(' ',EmpSub.Name),0),1000))) + ' ' +
				Ltrim(SUBSTRING(EmpSub.Name,CharIndex(' ',EmpSub.Name),CAse When (CHARINDEX(' ',EmpSub.Name,CHARINDEX(' ',EmpSub.Name)+1)-CHARINDEX(' ',EmpSub.Name))<=0 then 0
				else CHARINDEX(' ',EmpSub.Name,CHARINDEX(' ',EmpSub.Name)+1)-CHARINDEX(' ',EmpSub.Name) end ))
			, ' - ') AS AllInstructors,
			MAX(EmpSub.Image) AS FirstInstructorImage
		FROM Classroom_Session_Instructor CSI_Sub
		INNER JOIN GENEmployees EmpSub ON CSI_Sub.InstructorId = EmpSub.Id
		WHERE CSI_Sub.SessionId = TLMSClassroom_Session.Id
	) InstructorsData

	where TLMSClassroom_Session.ClassroomId=@ClassRoomId
	order by cast(TLMSClassroom_Session.SessionDateTime as date),cast(TLMSClassroom_Session.FromDateTime as time)
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetClassRoomSessionsByClassRoomId_AcaDegree]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE  [dbo].[SP_FE_GetClassRoomSessionsByClassRoomId_AcaDegree] --  [SP_FE_GetClassRoomSessionsByClassRoomId_AcaDegree] 372,'ar'
	@ClassRoomId bigint,@LangCode nvarchar(MAX)
AS
BEGIN
	
	SET NOCOUNT ON;
	SELECT TLMSClassroom_Session.Id, dbo.fn_Item_Translate_ByKeyandId(GENItems.Id,'Name',@LangCode) as SessionName
	,Ltrim(SubString(GENEmployees.Name,1,Isnull(Nullif(CHARINDEX(' ',GENEmployees.Name),0),1000))) + ' ' +
             Ltrim(SUBSTRING(GENEmployees.Name,CharIndex(' ',GENEmployees.Name),CAse When (CHARINDEX(' ',GENEmployees.Name,CHARINDEX(' ',GENEmployees.Name)+1)-CHARINDEX(' ',GENEmployees.Name))<=0 then 0
             else CHARINDEX(' ',GENEmployees.Name,CHARINDEX(' ',GENEmployees.Name)+1)-CHARINDEX(' ',GENEmployees.Name) end )) as InstructorName
,GENClassrooms.Name as ClassroomName ,TLMSClassroom_Session.SessionDateTime,
	TLMSClassroom_Session.FromDateTime,TLMSClassroom_Session.ToDateTime,
   dbo.FN_ConvertDaystoArabic((' '+ Datename(weekday, TLMSClassroom_Session.SessionDateTime)  +CHAR(13)+CHAR(10)+
	FORMAT(TLMSClassroom_Session.SessionDateTime,'dd/MM/yyyy')),@LangCode) as SessionDateTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(TLMSClassroom_Session.FromDateTime,'hh:mm'),@LangCode) as FromDateTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(TLMSClassroom_Session.ToDateTime,'hh:mm'),@LangCode) as ToDateTimeString,
	GENClassrooms.FromDateTime as ClassroomFromDateTime,GENClassrooms.ToDateTime as ClassroomToDateTime
	,TLMSClassroom_Session.Name as Name,cast(res.RowNum as nvarchar(500)) as RowNum
	,TLMSClassroom_Session.TypeSession, dbo.FN_SessionsType(TLMSClassroom_Session.TypeSession,@LangCode) AS TypeSessionName
	,TLMSClassroom_Session.InstructorInstructions
	,TLMSClassroom_Session.InteractiveMeetingURL
	,GENClassrooms.InstructorInstructions as Remarks
	,Course.Name as CourseName
	,GENClassrooms.Code as ClassroomCode
	,Lang.Name as LangName
	,GENClassrooms.FromDateTime as ClassroomsFromDateTime
	,GENClassrooms.ToDateTime as ClassroomsToDateTime
	,Room.Name as RoomName
	,Room.Code as Roomcode
	,Emp.Name as EmpName
	,dbo.GENClassrooms.ClassRoomShift
	,(CASE WHEN dbo.GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' WHEN dbo.GENClassrooms.ClassRoomShift = 1 THEN N'مسائي' ELSE N'' END ) AS ClassRoomShiftString
	,Course.Int2 as HourCount
	,datediff(Day,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime)+1 as ClassroomsDay,
	   dbo.FN_ConvertNumbertoArabic((SELECT count(*) from GENClassroom_GENContact where ClassroomId = @ClassRoomId)) as ContactCount
	     ,GENEmployees.Image as InstructorImage,
		  Zoom.Name AS ZoomMeeting,Zoom.interactiveMeetingURL AS ZoomInteractiveMeetingURL,Zoom.VideoURL AS ZoomVideoURL,
		  dbo.FN_ConvertDaystoArabic(FORMAT(Zoom.SessionDateTime,'hh:mm'),@LangCode) as ZoomFromTimeString,
		  dbo.FN_ConvertDaystoArabic (FORMAT(DATEADD(MINUTE,Zoom.ZoomDuration,Zoom.SessionDateTime),'hh:mm'),@LangCode) ZoomToTimeString,
	 dbo.FN_ConvertDaystoArabic((' '+ Datename(weekday, Zoom.SessionDateTime)  +CHAR(13)+CHAR(10)+
	FORMAT(Zoom.SessionDateTime,'dd/MM/yyyy')),@LangCode)  as ZoomSessionDateTimeString
	from TLMSClassroom_Session left join 
	GENItems on TLMSClassroom_Session.SessionId=GENItems.Id  left join 
	GENEmployees on TLMSClassroom_Session.InstructorId=GENEmployees.Id left join 
	GENClassrooms on TLMSClassroom_Session.ClassroomId=GENClassrooms.Id left join 
	(SELECT Datename(weekday, TLMSClassroom_Session.SessionDateTime)  +' '+
	FORMAT(TLMSClassroom_Session.SessionDateTime,'dd/MM')   as SessionDateTimeString,
	  ROW_NUMBER() OVER (ORDER BY SessionDateTime) as RowNum,SessionDateTime
	from TLMSClassroom_Session left join 
	GENItems on TLMSClassroom_Session.SessionId=GENItems.Id  left join 
	GENEmployees on TLMSClassroom_Session.InstructorId=GENEmployees.Id left join 
	GENClassrooms on TLMSClassroom_Session.ClassroomId=GENClassrooms.Id 
	where TLMSClassroom_Session.ClassroomId=@ClassRoomId and GENClassrooms.ProsecutionId=1
	group by SessionDateTime
	) res on res.SessionDateTime = TLMSClassroom_Session.SessionDateTime
	left join GENTypes Course on GENClassrooms.CourseId = Course.Id
	left join GENListValues Lang on GENClassrooms.LanguageId = Lang.Id
	left join [GENRooms] Room on GENClassrooms.RoomId = Room.Id
	left join [GENEmployees] Emp on GENClassrooms.InstructorId = Emp.Id
	left join 
    Zoom_Session Zoom ON TLMSClassroom_Session.SessionId=Zoom.SessionId and Zoom.VcrId=@ClassRoomId and Zoom.ZoomType=1
	where TLMSClassroom_Session.ClassroomId=@ClassRoomId --and GENClassrooms.ProsecutionId=1
	order by SessionDateTime
END
GO
