CREATE PROCEDURE [dbo].[SP_FE_GetContactClassroomSchedule]  --SP_FE_GetContactClassroomSchedule 19831,'ar','2023-10-29','2023-12-10'
	-- Add the parameters for the stored procedure here
	@Id BIGINT,@LangCode nvarchar(500), @StartTime DateTime, @EndTime DateTime
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT  DISTINCT dbo.fn_ClassRoom_Translate_ByKeyandId(dbo.GENClassrooms.Id,'Name', dbo.GENListValues.shortCode) + ' - ' + dbo.fn_Type_Translate_ByKeyandId(dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode) AS title,  
	GENClassrooms.Id AS id, FORMAT(GENClassrooms.FromDateTime, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(GENClassrooms.FromDateTime, 'yyyy-MM-ddTHH:mm:ss') AS [end], '/controlBoard/showCourses/' + CAST(GENClassrooms.Id AS nvarchar(MAX)) AS url,
	dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,'#FFF' AS textColor,'#1169b2' AS color, 'Classroom' AS EventType, 'cast_for_education' AS EventIcon
FROM  dbo.GENTypes 
RIGHT OUTER JOIN dbo.GENClassroom_GENContact 
RIGHT OUTER JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
LEFT OUTER JOIN dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId
LEFT OUTER JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
LEFT OUTER JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
LEFT JOIN dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE (dbo.GENContacts.Id = @Id) and dbo.GENClassrooms.isActive =1 AND (FromDateTime <= @StartTime OR FromDateTime >= @StartTime) AND (ToDateTime >= @EndTime OR ToDateTime <= @EndTime)


UNION 

SELECT  DISTINCT (CASE WHEN TLMSClassroom_Session.Name IS NOT NULL THEN (dbo.fn_Item_Translate_ByKeyandId(GENItems.Id,'Name',dbo.GENListValues.shortCode) + ' - ' +  TLMSClassroom_Session.Name) ELSE GENItems.Name END) AS title,  
	GENClassrooms.Id AS id, FORMAT(TLMSClassroom_Session.SessionDateTime, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(DATEADD(hour, 2,TLMSClassroom_Session.SessionDateTime), 'yyyy-MM-ddTHH:mm:ss') AS [end], 
	'/Account/SubscribedVCRCourse/' + CAST(GENTypes.Id AS nvarchar(MAX))+'?classId='+CAST(GENClassrooms.Id AS nvarchar(MAX)) AS url,
	dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, TLMSClassroom_Session.SessionDateTime AS FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,'#FFF' AS textColor,'#032652' AS color, 'Session' AS EventType, 'ondemand_video' AS EventIcon 

			FROM  dbo.TLMSClassroom_Session 
			inner JOIN GENItems ON TLMSClassroom_Session.SessionId = GENItems.Id
			inner JOIN dbo.GENClassrooms ON TLMSClassroom_Session.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENTypes ON GENClassrooms.CourseId = GENTypes.Id
			LEFT JOIN dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
			LEFT JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
			LEFT JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE (dbo.GENContacts.Id = @Id) and dbo.GENClassrooms.isActive =1 AND (GENClassrooms.FromDateTime <= @StartTime OR GENClassrooms.FromDateTime >= @StartTime) AND (GENClassrooms.ToDateTime >= @EndTime OR GENClassrooms.ToDateTime <= @EndTime)
AND TLMSClassroom_Session.SessionDateTime >= @StartTime AND TLMSClassroom_Session.SessionDateTime <= @EndTime
AND TLMSClassroom_Session.IsActive = 1

UNION 

SELECT  DISTINCT ([dbo].[fn_Calendar_Translate_ByKey]('Interactive Meeting', @LangCode) + ' - ' +  dbo.fn_ClassRoom_Translate_ByKeyandId(dbo.GENClassrooms.Id,'Name', dbo.GENListValues.shortCode)) AS title,  
	GENClassrooms.Id AS id, FORMAT(GENClassrooms.InteractiveMeetingDateTime, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(DATEADD(hour, 2,GENClassrooms.InteractiveMeetingDateTime), 'yyyy-MM-ddTHH:mm:ss') AS [end], 
	GENClassrooms.InteractiveMeetingURL AS url,
	dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
	dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
	dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount, DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
	GENClassrooms.InteractiveMeetingDateTime AS FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed,
	dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
	GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,'#FFF' AS textColor,'#032652' AS color, 'Meeting' AS EventType, 'cast_for_education' AS EventIcon
FROM  dbo.GENClassrooms
			LEFT JOIN dbo.GENTypes ON GENClassrooms.CourseId = GENTypes.Id
			LEFT JOIN dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
			LEFT JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
			LEFT JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE (dbo.GENContacts.Id = @Id) and dbo.GENClassrooms.isActive =1 AND (FromDateTime <= @StartTime OR FromDateTime >= @StartTime) AND (ToDateTime >= @EndTime OR ToDateTime <= @EndTime)
AND GENClassrooms.InteractiveMeetingDateTime >= @StartTime AND GENClassrooms.InteractiveMeetingDateTime <= @EndTime AND GENClassrooms.IsShowInteractiveMeeting = 1

UNION 

SELECT  DISTINCT (CASE WHEN TLMSClassroom_Session.Name IS NOT NULL THEN ([dbo].[fn_Calendar_Translate_ByKey]('Interactive Meeting', @LangCode) + ' - ' +  TLMSClassroom_Session.Name) ELSE 
([dbo].[fn_Calendar_Translate_ByKey]('Interactive Meeting', @LangCode) + ' - ' +  dbo.fn_Item_Translate_ByKeyandId(GENItems.Id,'Name',dbo.GENListValues.shortCode)) END) AS title,  
	GENClassrooms.Id AS id, FORMAT(TLMSClassroom_Session.SessionDateTime, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(DATEADD(hour, 2,TLMSClassroom_Session.SessionDateTime), 'yyyy-MM-ddTHH:mm:ss') AS [end], 
	TLMSClassroom_Session.InteractiveMeetingURL AS url,
	dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, TLMSClassroom_Session.SessionDateTime AS FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,'#FFF' AS textColor,'#032652' AS color, 'Meeting' AS EventType, 'cast_for_education' AS EventIcon  
			FROM  dbo.TLMSClassroom_Session 
			LEFT JOIN GENItems ON TLMSClassroom_Session.SessionId = GENItems.Id
			LEFT JOIN dbo.GENClassrooms ON TLMSClassroom_Session.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENTypes ON GENClassrooms.CourseId = GENTypes.Id
			LEFT JOIN dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
			LEFT JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
			LEFT JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE (dbo.GENContacts.Id = @Id) and dbo.GENClassrooms.isActive =1 AND (GENClassrooms.FromDateTime <= @StartTime OR GENClassrooms.FromDateTime >= @StartTime) AND (GENClassrooms.ToDateTime >= @EndTime OR GENClassrooms.ToDateTime <= @EndTime)
AND TLMSClassroom_Session.SessionDateTime >= @StartTime AND TLMSClassroom_Session.SessionDateTime <= @EndTime
AND TLMSClassroom_Session.IsActive = 1 AND TLMSClassroom_Session.InteractiveMeetingURL IS NOT NULL AND TLMSClassroom_Session.InteractiveMeetingURL <> ''

UNION 

SELECT  DISTINCT (dbo.FN_GetExamType(GENPollCategories.ExamType, @LangCode) + ' - ' +  GENPollCategories.Name) AS title,  
	GENClassrooms.Id AS id, FORMAT(GENEXam_GENClassroom.DisplayDateTime, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(DATEADD(hour, 2,GENEXam_GENClassroom.DisplayDateTime), 'yyyy-MM-ddTHH:mm:ss') AS [end], 
	('/Exam/Exam/' + CAST(GENPollCategories.Id AS nvarchar(MAX)) +'?classRoomId=' + CAST(GENClassrooms.Id AS nvarchar(MAX))) AS url,
	dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
	dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
	dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount, DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
	GENEXam_GENClassroom.DisplayDateTime AS FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed,
	dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
	GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,'#212121' AS textColor,'#fdaf17' AS color, 'Assignments' AS EventType, 'assignment' AS EventIcon 
FROM  dbo.GENPollCategories
LEFT JOIN GENEXam_GENClassroom ON GENEXam_GENClassroom.ExamId = GENPollCategories.Id
LEFT JOIN GENClassrooms ON GENEXam_GENClassroom.ClassroomId = GENClassrooms.Id
			LEFT JOIN dbo.GENTypes ON GENClassrooms.CourseId = GENTypes.Id
			LEFT JOIN dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
			LEFT JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
			LEFT JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE (dbo.GENContacts.Id = @Id) and dbo.GENClassrooms.isActive =1 AND (FromDateTime <= @StartTime OR FromDateTime >= @StartTime) AND (ToDateTime >= @EndTime OR ToDateTime <= @EndTime)
AND GENExam_GENClassroom.[DisplayDateTime] >= @StartTime AND GENEXam_GENClassroom.[DisplayDateTime] <= @EndTime AND GENEXam_GENClassroom.IsActive = 1

UNION 

SELECT  DISTINCT (dbo.FN_GetExamType(GENPollCategories.ExamType, @LangCode) + ' - ' +  GENPollCategories.Name) AS title,  
	GENClassrooms.Id AS id, FORMAT(GENClassrooms.ExamStartTime, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(GENClassrooms.ExamEndTime, 'yyyy-MM-ddTHH:mm:ss') AS [end], 
	('/Exam/Exam/' + CAST(GENPollCategories.Id AS nvarchar(MAX)) +'?classRoomId=' + CAST(GENClassrooms.Id AS nvarchar(MAX))) AS url,
	dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, 
	dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, 
	dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount, DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, 
	GENClassrooms.[ExamStartTime] AS FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed,
	dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
	GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId,'#FFF' AS textColor,'#c2185b' AS color, 'Exam' AS EventType, 'assessment' AS EventIcon 
FROM  dbo.GENPollCategories
LEFT JOIN GENClassrooms ON GENClassrooms.ExamId = GENPollCategories.Id
			LEFT JOIN dbo.GENTypes ON GENClassrooms.CourseId = GENTypes.Id
			LEFT JOIN dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id 
			LEFT JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
			LEFT JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
			LEFT JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN dbo.GENListValues Field ON dbo.GENTypes.ValueId1 = Field.Id
WHERE (dbo.GENContacts.Id = @Id) and dbo.GENClassrooms.isActive =1 AND (FromDateTime <= @StartTime OR FromDateTime >= @StartTime) AND (ToDateTime >= @EndTime OR ToDateTime <= @EndTime)
AND (GENClassrooms.[ExamStartTime] <= @StartTime OR GENClassrooms.[ExamStartTime] >= @StartTime) AND (GENClassrooms.[ExamEndTime] >= @EndTime OR GENClassrooms.[ExamEndTime] <= @EndTime) 


UNION 


SELECT  DISTINCT (CASE WHEN GENNews.Name IS NOT NULL THEN (dbo.fn_News_Translate_ByKeyandId(dbo.GENNews.Id,'Name', @LangCode)) ELSE dbo.fn_News_Translate_ByKeyandId(dbo.GENNews.Id,'Name', @LangCode) END) AS title,  
	GENNews.Id AS id, FORMAT(GENNews.DisplayDate, 'yyyy-MM-ddTHH:mm:ss') AS [start],
	FORMAT(DATEADD(hour, 2,GENNews.DisplayDate), 'yyyy-MM-ddTHH:mm:ss') AS [end], 
	GENNews.VideoUrl AS url,
	'' AS CourseGoals, dbo.GENNews.DisplayOrdering AS DisplayOrder, dbo.GENNews.IsPublish, dbo.GENNews.IsActive, 
                        '' AS CourseImage, dbo.GENNews.Id AS CourseId, '' AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENNews.DisplayDate
                        ) AS RestDays, GENNews.DisplayDate AS FromDateTime, dbo.GENNews.DisplayDate, 1 AS IsConfirmed
						 ,0 as CoueseHours, dbo.GENNews.Id AS ClassroomId,'' AS FieldName, 50 AS FieldId,
			'Ali' AS InstructorName, 2 AS InstructorId,'#FFF' AS textColor,'#032652' AS color, 'Public Event' AS EventType, 'event_available' AS EventIcon 

			FROM  dbo.GENContact_News
			inner join GENNews ON GENContact_News.NewsId=GENNews.Id
WHERE  dbo.GENNews.isActive =1  and GENContact_News.ContactId=@Id
AND GENNews.DisplayDate >= @StartTime AND GENNews.DisplayDate <= @EndTime
	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetContactTalents]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
