-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 15/06/2021
-- Description:	Get all talents for contact
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_GetContactTalents]
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT GENTalents.* FROM GENContact_Talent
	LEFT JOIN GENContacts on GENContact_Talent.ContactId = GENContacts.Id
	LEFT JOIN GENTalents ON GENContact_Talent.TalentId = GENTalents.Id
	WHERE GENContact_Talent.ContactId = @ContactId
	ORDER BY GENTalents.DisplayOrdering
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetContactTalents_byContactId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
