GO
CREATE PROCEDURE [dbo].[SP_FE_GetContactTalents_byContactId]
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT,@Langcode nvarchar(MAX) 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT  GENTalents.Id,dbo.fn_Talent_Translate_ByKeyandId(GENTalents.Id,'Name',@Langcode) AS Name,dbo.fn_FirstImage_BaseEntityEntityId(184,GENTalents.Id) as [Image],
	dbo.fn_Talent_Translate_ByKeyandId(GENTalents.Id,'Description',@Langcode) AS Description,GENTalents.CoursesNo
	FROM GENContact_Talent
	LEFT JOIN GENContacts on GENContact_Talent.ContactId = GENContacts.Id
	LEFT JOIN GENTalents ON GENContact_Talent.TalentId = GENTalents.Id
	WHERE GENContact_Talent.ContactId = @ContactId 
	--AND (GENContact_Talent.EndDate >= GETDATE()) 
	and GENTalents.IsPublish = 1 	and GENTalents.IsDeleted = 0 and GENTalents.IsActive=1
	ORDER BY GENTalents.DisplayOrdering
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetContactTalentsWithPercentage]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 15/06/2021
-- Description:	Get all talents for contact
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_GetContactTalentsWithPercentage]
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT TalentData.Id,TalentData.DisplayOrdering,TalentData.Name,
ROUND((SUM(TalentData.TalentPercentage) / (SUM(TalentData.ItemsCount) * 100) * 100),2) AS TalentPercentage,SUM(TalentData.CoursesCount) AS CourseCounts,
SUM(TalentData.ItemsCount) AS ItemsCount
FROM (SELECT DISTINCT GENTalents.Id,GENTalents.Name,GENTalents.DisplayOrdering,
Count(DISTINCT Course.Id) AS CoursesCount,
--(TalentPercentage.SumPercentage/(Count(DISTINCT Course.Id) * 100)) * 100,
--SUM(CASE WHEN TalentPercentage.SumPercentage IS NULL THEN 0 ELSE TalentPercentage.SumPercentage END),
(CASE WHEN TalentPercentage.SumPercentage IS NULL THEN 0 ELSE  TalentPercentage.SumPercentage END) AS TalentPercentage,
COUNT(GENItems.Id) AS ItemsCount
--((SUM(TalentPercentage.SumPercentage))
FROM GENTalents
INNER JOIN GENTalents_Generic ON GENTalents_Generic.TalentId = GENTalents.Id
INNER JOIN GENContact_Talent ON GENContact_Talent.TalentId = GENTalents_Generic.TalentId
INNER JOIN GENContacts ON GENContact_Talent.ContactId = GENContacts.Id
INNER JOIN GENTypes Course ON GENTalents_Generic.EntityId = Course.Id AND GENTalents_Generic.BaseEntityId = 28
LEFT JOIN Contacts_Courses ON GENContacts.Id = Contacts_Courses.StudentId AND Contacts_Courses.CourseId = Course.Id
LEFT JOIN GENClassrooms ON GENClassrooms.Id = Contacts_Courses.ClassRoomId
LEFT JOIN dbo.GENItems ON Course.Id = GENItems.TypeId
CROSS APPLY (
select SUM(CASE WHEN GENContactProgressCompletions.Id IS NULL THEN 0 ELSE GENContactProgressCompletions.CompletionPercentage END) AS SumPercentage FROM GENContactProgressCompletions
LEFT JOIN GENItems ON GENItems.Id = GENContactProgressCompletions.EntityId AND GENContactProgressCompletions.BaseEntityId = dbo.FN_GetBaseEntityIdByName('GENItem')
LEFT JOIN GENTypes ON GENItems.TypeId = GENTypes.Id
WHERE GENContactProgressCompletions.ContactId = @ContactId 
						AND  (GENTypes.Id = Course.Id OR GENContactProgressCompletions.ClassroomId = GENClassrooms.Id)
) TalentPercentage
	WHERE GENContacts.Id = @ContactId
	GROUP BY GENTalents.Id,GENTalents.Name,GENTalents.DisplayOrdering,TalentPercentage.SumPercentage) TalentData
	GROUP BY TalentData.Id,TalentData.DisplayOrdering,TalentData.Name
	ORDER BY TalentData.DisplayOrdering
END
GO
