CREATE PROCEDURE [dbo].[SP_FE_GetCourseRatings] --53865,'1722d4fd-925f-4f6c-b687-f94b38dd6804',198
	-- Add the parameters for the stored procedure here
	@CourseId BIGINT,@UserId nvarchar(500), @BaseEntityId BIGINT,@EntityId2 bigint = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select COUNT(Id) AS Counts, Rating,EntityId,Id,IsFavourite FROM GENRatings
	WHERE BaseEntityId = @BaseEntityId AND EntityId = @CourseId AND UserId=@UserId
	and ((@EntityId2 is null and (EntityId2 IS null or EntityId2 = 0)) or EntityId2 = @EntityId2)
	GROUP BY Rating, EntityId,IsFavourite,Id
END
GO
