/****** Object:  StoredProcedure [dbo].[SP_FE_GetEmpStudetsRateing]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create PROC [dbo].[SP_FE_GetEmpStudetsRateing] (@StudentId bigint,@BaseId bigint)
AS
Begin

Select distinct GENRatings.*,GENContacts.Name As StudentName,GENContacts.Id as StudentId,
GENEmployees.Name AS InstName,GENEmployees.Id as InstId
from GENRatings inner join 
GENClassroom_GENContact ON GENRatings.EntityId=GENClassroom_GENContact.Id  inner join 
GENEmployees ON GENRatings.createdById=GENEmployees.UserId inner join 
GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id
where GENRatings.BaseEntityId=@BaseId and GENContacts.Id=@StudentId

END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetExamData_ContactIdandExamId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_FE_GetExamData_ContactIdandExamId] --[dbo].[SP_FE_GetExamData_ContactIdandExamId] '3a104912-ab29-48da-bbf2-7ab86e97ffdc',10218,950,'ar'
(@UserId nvarchar(128) , @ExamId bigint,@ClassRoomId bigint, @LangCode nvarchar(500))
as
SELECT distinct dbo.GENClassrooms.Id, dbo.GENClassrooms.InteractiveMeetingURL, dbo.GENClassrooms.InstructorInstructions, 
(CASE WHEN dbo.GENExam_GENClassroom.DisplayDateTime IS NOT NULL THEN dbo.GENExam_GENClassroom.DisplayDateTime ELSE dbo.GENClassrooms.ExamStartTime END ) AS ExamStartTime,
(CASE WHEN dbo.GENExam_GENClassroom.DisplayDateTime IS NOT NULL THEN NULL ELSE dbo.GENClassrooms.ExamEndTime END) ExamEndTime, dbo.GENClassrooms.FromDateTime, 
                         dbo.GENClassrooms.ToDateTime, dbo.GENClassrooms.InteractiveMeetingDateTime, dbo.GENClassrooms.DisplayOrder, 
						 dbo.GENClassrooms.CourseId, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.Code, 
                         dbo.GENClassrooms.Name, dbo.GENClassrooms.Description, dbo.GENClassrooms.ColorCode, dbo.GENClassrooms.IsCheckedOut, dbo.GENClassrooms.DateCreated, dbo.GENClassrooms.DateUpdated, 
                         dbo.GENClassrooms.CheckinDate, dbo.GENClassrooms.CheckoutDate, dbo.GENClassrooms.ExpectedCheckoutDate, dbo.GENClassrooms.Timeout, dbo.GENClassrooms.DisplayOrdering, dbo.GENClassrooms.CreatedById, 
                         dbo.GENClassrooms.LastUpdatedById, dbo.GENClassrooms.CheckoutBy, dbo.GENClassrooms.String1, dbo.GENClassrooms.String2, dbo.GENClassrooms.String3, dbo.GENClassrooms.String4, dbo.GENClassrooms.String5, 
                         (case when GENExam_GENType.ExamId is not null then GENExam_GENType.ExamId when GENExam_GENItem.ExamId is not null then GENExam_GENItem.ExamId else dbo.GENPollCategories.Id end)  AS ExamId, 
						 dbo.GENEmployees.Name AS InstractorName, dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS CourseName, dbo.GENClassroom_GENContact.StudentId, dbo.GENContacts.Name AS StudentName, 
                         dbo.GENContacts.DefaultEmail, dbo.GENContacts.DefaultPhone, dbo.fn_Exam_QuestionCount( (case when GENExam_GENType.ExamId is not null then GENExam_GENType.ExamId when GENExam_GENItem.ExamId is not null then GENExam_GENItem.ExamId else dbo.GENPollCategories.Id end)) AS QuestionCount
						 , dbo.fn_Exam_TotalQuestion( (case when GENExam_GENType.ExamId is not null then GENExam_GENType.ExamId when GENExam_GENItem.ExamId is not null then GENExam_GENItem.ExamId else dbo.GENPollCategories.Id end)) AS QuestionTotalDegree, 
						 (case when GENExam_GENItem.ExamId is not null then GENExam_GENItemPollCategories.Name when GENExam_GENType.ExamId is not null then GENExam_GENTypePollCategories.Name else dbo.GENPollCategories.Name end)
						  AS ExamName, 
                           (case when GENExam_GENItem.ExamId is not null then GENExam_GENItemPollCategories.Code when GENExam_GENType.ExamId is not null then GENExam_GENTypePollCategories.Code else dbo.GENPollCategories.Code end)
						  AS ExamCode, 
						  (case when  GENExam_GENItem.ExamId is not null then GENExam_GENItemPollCategories.Time when GENExam_GENType.ExamId is not null then GENExam_GENTypePollCategories.Time else dbo.GENPollCategories.Time end)
						   as ExamTime,
						   dbo.fn_UserExamQuestions(dbo.GENClassroom_GENContact.StudentId
						   ,(case when GENExam_GENType.ExamId is not null then GENExam_GENType.ExamId 
						   when GENExam_GENItem.ExamId is not null then GENExam_GENItem.ExamId else dbo.GENPollCategories.Id end),dbo.GENClassrooms.Id)
						  as IsStarted,
						 dbo.GENContacts.Code as StudentCode,dbo.GENTypes.Code AS CourseCode, 
						 (case when  GENExam_GENItem.ExamId is not null then GENExam_GENItemPollCategories.Time when GENExam_GENType.ExamId is not null then GENExam_GENTypePollCategories.Time else dbo.GENPollCategories.Time end) AS [Time], 
						 (case when  GENExam_GENItem.ExamId is not null then GENExam_GENItemPollCategories.ExamType when GENExam_GENType.ExamId is not null then GENExam_GENTypePollCategories.ExamType else dbo.GENPollCategories.ExamType end) AS ExamType,
						 dbo.FN_GetExamType(dbo.GENPollCategories.ExamType, @LangCode) AS ExamTypeName
						 ,(select top 1 IsPosted from GENExamAnswerHeaders where StudentId = GENContacts.Id and ExamId = @ExamId and ClassroomId = @ClassRoomId order by GENExamAnswerHeaders.DateCreated desc) as ExamIsPosted
from dbo.GENClassrooms --ON dbo.GENExam_GENClassroom.ClassroomId =  dbo.GENClassrooms.Id OR dbo.GENClassrooms.ExamId = dbo.GENPollCategories.Id 
  LEFT JOIN dbo.GENExam_GENClassroom ON (dbo.GENExam_GENClassroom.ClassroomId = dbo.GENClassrooms.Id)
LEFT JOIN dbo.GENPollCategories on dbo.GENExam_GENClassroom.ExamId = dbo.GENPollCategories.Id
  LEFT JOIN dbo.GENClassroom_GENContact ON dbo.GENClassrooms.Id = dbo.GENClassroom_GENContact.ClassroomId LEFT JOIN  
dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT JOIN
dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = dbo.GENEmployees.Id LEFT JOIN
dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.ID
left join Course_Session on Course_Session.CourseId = dbo.GENTypes.Id
LEFT JOIN dbo.GENItems ON dbo.GENItems.Id = Course_Session.SessionId 
LEFT JOIN dbo.GENExam_GENItem ON ((dbo.GENItems.Id = GENExam_GENItem.SessionId AND GENExam_GENItem.ExamId = @ExamId) OR GENExam_GENItem.ExamId = GENPollCategories.Id) 
LEFT JOIN dbo.GENExam_GENType ON ((dbo.GENTypes.Id = GENExam_GENType.CourseId AND GENExam_GENType.ExamId = @ExamId) OR GENExam_GENType.ExamId = GENPollCategories.Id)
left join dbo.GENPollCategories as GENExam_GENItemPollCategories on GENExam_GENItem.ExamId = GENExam_GENItemPollCategories.Id
left join dbo.GENPollCategories as GENExam_GENTypePollCategories on GENExam_GENType.ExamId = GENExam_GENTypePollCategories.Id
 LEFT JOIN TLMSClassroom_Session ON dbo.GENItems.Id = TLMSClassroom_Session.SessionId AND TLMSClassroom_Session.ClassroomId = dbo.GENClassrooms.Id
						 where (dbo.GENContacts.UserId = @UserId OR @UserId IS NULL) 
						 and ( dbo.GENPollCategories.Id = @ExamId or GENExam_GENItem.ExamId = @ExamId or GENExam_GENType.ExamId = @ExamId or GENExam_GENClassroom.ExamId = @ExamId)
						 and  (dbo.GENClassrooms.Id = @ClassRoomId OR @ClassRoomId IS NULL)
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetExamDegrees]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Procedure [dbo].[SP_FE_GetExamDegrees] @ExamId bigint
AS
select 
(CASE 
WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 
THEN CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) 
ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] 
END) 
as AnnouncedDegree
,ExamWeight AS Total
,StudentName
from GENExamAnswerHeaders where ExamId=@ExamId
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetExamsWithQuestions]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Procedure [dbo].[SP_FE_GetExamsWithQuestions] --N'44e9c4f3-f2dd-4701-ba3d-9b0c2bb5aaad'
@UserId nvarchar(max)
AS
select 
GENPollCategories.Id AS ExamId,GENPollCategories.Name AS ExamName,[dbo].[FN_GetExamType](GENPollCategories.ExamType,N'ar') AS ExamType,
GENPollCategories.Weight AS ExamMark,GENPollCategories.Date1 AS ExamDate,
PollCategoryandPolls.Id AS QuestionId,genpolls.Question,genpolls.Name as QuestionNumber,genpolls.Weight as Mark,
[dbo].[FN_GetQuestionType](genpolls.questionType,N'ar') as QuestionType 
from GENPollCategories
left JOIN PollCategoryandPolls On GENPollCategories.Id=PollCategoryandPolls.PollCategoryId
left join genpolls on genpolls.Id=PollCategoryandPolls.PollId 
where GENPollCategories.createdbyId = @UserId
order by GENPollCategories.Id
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetFileAttachments]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_FE_GetFileAttachments] @langCode nvarchar(500), @ContactId bigint=null,@EmployeeId bigint=null
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
    -- Insert statements for procedure here
	SELECT distinct GENFileAttachments.*,dbo.fn_Section_Translate_ByKeyandId( dbo.GENSections.Id,'Name',@langCode) AS SectionName, 
	CASE WHEN dbo.fn_FirstImage_BaseEntityEntityId(96,GENFileAttachments.Id) IS NOT NULL THEN
	dbo.fn_FirstImage_BaseEntityEntityId(96,GENFileAttachments.Id)
	ELSE '/assets/images/e-learning-book.jpg' END AS FileImage,'' AS BookingTypeName,'' AS AccessRightName,GENEmployees.Name AS EmployeeName , GENTalents.Name as TalentName, 
	GENClassrooms.Name AS VCRName, '' AS ClassroomCategoryName,GENTypes.Name AS CourseName
	FROM GENFileAttachments
	LEFT JOIN GENSections ON GENFileAttachments.SectionId = GENSections.Id
		left join GENClassrooms ON GENFileAttachments.ClassroomId= GENClassrooms.Id
			left join GENTalents ON GENFileAttachments.TalentId= GENTalents.Id
				left join GENEmployees ON GENFileAttachments.EmployeeId= GENEmployees.Id
								left join GENTypes ON GENFileAttachments.courseId= GENTypes.Id
	WHERE GENFileAttachments.IsPublish = 1 AND 
	(GENFileAttachments.AccessRight=0 OR  GENFileAttachments.AccessRight IS NULL
	OR (GENFileAttachments.AccessRight=2 and @ContactId IS NOT NULL) 
	OR (GENFileAttachments.AccessRight=3 and @EmployeeId IS NOT NULL) 
	OR (GENFileAttachments.AccessRight=1 AND 
			(
			(@ContactId IS NOT NULL AND dbo.isStudentConnected(@ContactId,GENClassrooms.Id,GENTypes.Id,GENTalents.Id)=1)
			)
			OR 
			(
			(@EmployeeId IS NOT NULL AND dbo.isInstructorConnected(@EmployeeId,GENClassrooms.Id,GENTypes.Id,GENTalents.Id)=1)
			)
		)
	)
	END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetFinalExamStatus]    Script Date: 7/1/2026 10:45:03 AM ******/
