    Create proc [dbo].[SP_FE_GetFinalExamStatus]
	@ContactId bigint,
	@TalentId bigint
	as
	begin
    SELECT distinct GENTypes.Id,GENPollCategories.ExamType,CAST(MAX(CAST(isnull(t.IsSuccess,0) as INT)) AS BIT) IsSucess
	from GENPollCategories  
	left join GENExam_GENItem on GENPollCategories.Id = GENExam_GENItem.ExamId 
	left join GENExamAnswerHeaders on GENPollCategories.Id  = GENExamAnswerHeaders.ExamId
	left join GENExam_GENType on GENExam_GENType.ExamId = GENExamAnswerHeaders.ExamId 
    left join GENItems on GENItems.Id = GENExam_GENItem.SessionId
	left join GENTypes on (GENTypes.Id = GENItems.TypeId or GENExam_GENType.CourseId = GENTypes.Id)
	left join GENContacts  on GENContacts.Id=GENExamAnswerHeaders.StudentId 
	left join GENTalents_Generic on GENTalents_Generic.BaseEntityId = 28 and GENTalents_Generic.EntityId = GENTypes.Id
	left join (select ROW_NUMBER() OVER (PARTITION BY ExamType order by ExamType,Score desc) as RowNum,* from (
	select  GENPollCategories.ExamType,GENExamAnswerHeaders.ExamId,GENExamAnswerHeaders.DateCreated,Max((CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) 
	  ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END)) as Score 
	  ,cast([dbo].[fn_UserExamQuestionsDeagree](GENExamAnswerHeaders.StudentId,dbo.GENPollCategories.Id,GENExamAnswerHeaders.CourseId) as bit) as IsSuccess
	  from GENExamAnswerHeaders inner join GENPollCategories on GENPollCategories.Id  = GENExamAnswerHeaders.ExamId 
	  where GENExamAnswerHeaders.StudentId = @ContactId
	  group by GENPollCategories.ExamType,GENExamAnswerHeaders.ExamId,GENExamAnswerHeaders.DateCreated,GENExamAnswerHeaders.StudentId,dbo.GENPollCategories.Id,GENExamAnswerHeaders.CourseId
	  )as res) as t on t.ExamId = GENExamAnswerHeaders.ExamId and t.RowNum = 1 
	where  GENTalents_Generic.TalentId = @TalentId and GENPollCategories.ExamType = 0
	group by GENTypes.Id,GENPollCategories.ExamType
	end
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetInstructorCurrentClassroomPercentage]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 23/09/2020
-- Description:	Get all Current classroom with progress
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_GetInstructorCurrentClassroomPercentage] 
	-- Add the parameters for the stored procedure here
	@Id BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENClassrooms.Id, GENClassrooms.Code, GENClassrooms.Name,Count(GENClassroom_GENContact.Id) AS Attendees, FORMAT(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS FromDate, FORMAT(GENClassrooms.ToDateTime,'dd/MM/yyyy')  AS ToDate,
	DATEDIFF(day,GETDATE(), GENClassrooms.ToDateTime) AS RemainingDays,
	(CAST(((CAST(DATEDIFF(day,GENClassrooms.FromDateTime, GETDATE()) AS decimal(10,2))/ CAST(DATEDIFF(day,GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) AS decimal(10,2))) * 100) AS Decimal(10,0)))
	AS FinishedPercentage
	FROM GENClassrooms
	inner Join TLMSClassroom_Session ON GENClassrooms.Id=TLMSClassroom_Session.ClassroomId
	inner JOIN GENClassroom_GENContact ON GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
	inner JOIN 	dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id 
	--INNER JOIN [CRMSRVTicket_Comment] ON [CRMSRVTicket_Comment].EntityId = GENClassrooms.Id  AND BaseEntityId = 176
	WHERE GENClassrooms.FromDateTime <= GETDATE() AND GENClassrooms.ToDateTime >= GETDATE() AND GENEmployees.Id = @Id
	GROUP BY GENClassrooms.Code, GENClassrooms.Name,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Id
END
GO
