CREATE Procedure [dbo].[SP_FE_GetInstructorStudents]
@UserId nvarchar(max),@ClassroomId bigint
AS SELECT DISTINCT [GENClassroom_GENContact].Id as GCCId ,GENContacts.Name from GENContacts
Inner Join [GENClassroom_GENContact] ON GENContacts.Id=[GENClassroom_GENContact].StudentId
inner join [TLMSClassroom_Session] on [GENClassroom_GENContact].ClassroomId=[TLMSClassroom_Session].ClassroomId
Inner Join genemployees on  [TLMSClassroom_Session].InstructorId=genemployees.Id
where genemployees.UserId=@UserId AND [GENClassroom_GENContact].ClassroomId=@ClassroomId
