CREATE Procedure [dbo].[SP_FE_GetInstructorStudentsRatings] 
@UserId nvarchar(max),@ClassroomId bigint=null
AS select  GENRatings.Id,[GENClassroom_GENContact].Id AS GCCId,GENClassrooms.Name as VCRName,GENContacts.Name as StudentName, Rating,Comment from GENRatings
