-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 23/09/2020
-- Description:	Get Top 5 courses
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_GetInstructorTopCourses]
	-- Add the parameters for the stored procedure here
	@Id BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT TOP 5 Count(GENClassroom_GENContact.Id) AS CourseCount, GENTypes.Id, GENTypes.Name,dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image] ,
	GENClassrooms.Id as VcrId
	FROM GENClassroom_GENContact 

	inner JOIN GENClassrooms ON GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
	inner Join TLMSClassroom_Session ON GENClassrooms.Id=TLMSClassroom_Session.ClassroomId
	inner JOIN 	dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id 
	inner JOIN GENTypes ON GENClassrooms.CourseId = GENTypes.Id
	WHERE GENEmployees.Id = @Id and GENTypes.IsDeleted=0 and GENClassrooms.IsDeleted=0
	GROUP BY GENTypes.Id, GENTypes.Name,GENClassrooms.Id
	ORDER BY Count(GENClassroom_GENContact.Id) DESC
END
GO
