/****** Object:  StoredProcedure [dbo].[SP_FE_GETLogsByCompanyId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE procedure [dbo].[SP_FE_GETLogsByCompanyId] @CompanyId bigint,@userId bigint,@FromCreate Datetime , @ToCreate DateTime,@Action nvarchar(100)
 as
  select N'قام '+responsibleperson.Name as p1,
  N'ب'+(case
  WHEN GENOperationsLogs.Action=N'Delete' then N'مسح '
  WHEN GENOperationsLogs.Action=N'Add' then N'اضافة '
  WHEN GENOperationsLogs.Action=N'Reminder' then N'تذكير '
  WHEN GENOperationsLogs.Action=N'Import' then N'رفع '
  WHEN GENOperationsLogs.Action=N'AddNew' then N'اضافة جديدة ل'
  END) as p2,
  (case
  WHEN GENOperationsLogs.number=0 then    gencontacts.name + N' المتدرب '
  WHEN GENOperationsLogs.number is null then   N' المتدرب ' + gencontacts.name 
  ELSE  N' عدد ' + CAST(number AS nvarchar) + N' متدرب '
  END) as p3,
  (case
  WHEN (GENOperationsLogs.vcrId IS NOT NULL AND GENOperationsLogs.vcrId>0) then    N' في قاعة '+genclassrooms.NAME
  ELSE ''
  END) as p4,
 GENOperationsLogs.createDate as createDate
  from GENOperationsLogs
 left join gencontacts as responsibleperson on GENOperationsLogs.UserId=responsibleperson.Id
 left join gencontacts on gencontacts.Id=GENOperationsLogs.targetId
 left join genclassrooms on genclassrooms.Id=GENOperationsLogs.vcrId
 where ((number IS NOT NULL AND number >0) OR targetId IS NOT NULL)
 and GENOperationsLogs.CompanyId=@CompanyId 
 and GENOperationsLogs.userId=@userId
 and (@Action='' or @Action IS NULL OR @Action=GENOperationsLogs.Action OR (@Action='-1' and (GENOperationsLogs.Action='Add' OR GENOperationsLogs.Action='Import' OR GENOperationsLogs.Action='AddNew'))  )
and (@FromCreate IS null or @FromCreate='' or @FromCreate<= GENOperationsLogs.createDate)
and (@ToCreate IS null or @ToCreate='' or DATEADD(Day, 1,@ToCreate)>= GENOperationsLogs.createDate)
 order by GENOperationsLogs.Id DESC
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetMandatoryFields_Registrations_ByPopId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_GetMandatoryFields_Registrations_ByPopId]  (@PopId bigint=NULL,@LangId Bigint=NULL)
AS
Begin


select distinct BaseEntityFields.DBField AS Field ,'Fields' as Type,GENTranslate_PageOfPageFeilds.Name AS TransName from PageOfPageFeilds left join
BaseEntityFields ON PageOfPageFeilds.FeildId=BaseEntityFields.Id left join 
GENTranslate_PageOfPageFeilds ON PageOfPageFeilds.Id=GENTranslate_PageOfPageFeilds.PageOfPageFeildId and 
GENTranslate_PageOfPageFeilds.LangId=@LangId 

where PageOfPageId=@PopId and IsMandatory=1 and IsActive=1

union all
select distinct PageOfPageRelations.EntityName AS Field ,'Relations' as Type ,GENTranslate_PageOfPageRelation.Name AS TransName from PageOfPageRelations
left join 
GENTranslate_PageOfPageRelation ON PageOfPageRelations.Id=GENTranslate_PageOfPageRelation.PageOfPageRelationId and GENTranslate_PageOfPageRelation.LangId=@LangId and GENTranslate_PageOfPageRelation.PageOfPageId=@PopId

where PageOfPageRelations.PageOfPageId=@PopId and IsMandatory=1 and IsActive=1
End
GO
