/****** Object:  StoredProcedure [dbo].[SP_FE_GetRecentActivity]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 17/09/2020
-- Description:	Get Contact Activity with data
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_GetRecentActivity]
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT,@UserId NVARCHAR(250), @DateFrom DATETIME, @DateTo DATETIME,@LangCode nvarchar(500)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT GENOrderDetails.ItemName AS Name,GENOrderDetails.ItemPrice AS Price, GENOrderDetails.Description AS Description, 
	 DateCreated AS ActionDate,'' AS UserImage,'Purchase' AS ActivityType FROM GENOrderDetails
	INNER JOIN GENOrders ON GENOrderDetails.OrderId = GENOrders.Id
	WHERE GENOrders.[DateCreated] >= @DateFrom AND GENOrders.[DateCreated] <= @DateTo AND GENOrders.IsPaid = 1 AND GENOrders.ContactId = @ContactId
	UNION
	SELECT DISTINCT (CASE WHEN TLMSClassroom_Session.Name IS NOT NULL AND TLMSClassroom_Session.Name <> '' THEN TLMSClassroom_Session.Name ELSE 
	dbo.fn_Item_Translate_ByKeyandId(GENItems.Id,'Name',@LangCode)  END) AS Name,
	0 AS Price,(CASE WHEN TLMSClassroom_Session.Description IS NOT NULL AND TLMSClassroom_Session.Description <>'' THEN 
	TLMSClassroom_Session.Description ELSE dbo.fn_Item_Translate_ByKeyandId(GENItems.Id,'Description',@LangCode) END) AS Description, 
	TLMSClassroom_Session.SessionDateTime AS ActionDate, 
	'' AS UserImage,
	'Lessons' AS ActivityType FROM TLMSClassroom_Session
	INNER JOIN GENItems ON GENItems.Id = TLMSClassroom_Session.SessionId
	INNER JOIN GENClassrooms ON TLMSClassroom_Session.ClassroomId = GENClassrooms.Id 
	INNER JOIN GENClassroom_GENContact ON GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
	WHERE TLMSClassroom_Session.SessionDateTime >= @DateFrom AND TLMSClassroom_Session.SessionDateTime <= @DateTo AND GENClassroom_GENContact.StudentId = @ContactId
	AND TLMSClassroom_Session.IsActive = 1
END
GO
