/****** Object:  StoredProcedure [dbo].[SP_FE_GetSelfExamData_ContactIdandExamId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[SP_FE_GetSelfExamData_ContactIdandExamId](@UserId nvarchar(128) , @ExamId bigint,@CourseId bigint, @LangCode nvarchar(500))
as
SELECT        dbo.GENTypes.Id,  
						 dbo.GENTypes.Code, 
                         dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS Name,
						 dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS Description, 
						 dbo.GENTypes.ColorCode, dbo.GENTypes.IsCheckedOut, dbo.GENTypes.DateCreated, dbo.GENTypes.DateUpdated, 
                         dbo.GENTypes.CheckinDate, dbo.GENTypes.CheckoutDate, dbo.GENTypes.ExpectedCheckoutDate, dbo.GENTypes.Timeout, 
						 dbo.GENTypes.DisplayOrdering, dbo.GENTypes.CreatedById, 
                         dbo.GENTypes.LastUpdatedById, dbo.GENTypes.CheckoutBy, dbo.GENTypes.String1, 
						 dbo.GENTypes.String2, dbo.GENTypes.String3, dbo.GENTypes.String4, dbo.GENTypes.String5, 
                         dbo.GENPollCategories.Id AS ExamId, 
						 dbo.Contacts_Courses.StudentId, dbo.GENContacts.Name AS StudentName, 
                         dbo.GENContacts.DefaultEmail, dbo.GENContacts.DefaultPhone, dbo.fn_Exam_QuestionCount(dbo.GENPollCategories.Id) AS QuestionCount, dbo.fn_Exam_TotalQuestion(dbo.GENPollCategories.Id) AS QuestionTotalDegree, 
						 dbo.GENPollCategories.Name
						  AS ExamName, 
                         dbo.GENPollCategories.Code
						  AS ExamCode, 
						  dbo.GENPollCategories.Time
						   as ExamTime,
						   dbo.fn_UserExamQuestions(dbo.Contacts_Courses.StudentId,dbo.GENPollCategories.Id,dbo.GENTypes.Id)
						  as IsStarted,
						 dbo.GENContacts.Code as StudentCode,dbo.GENTypes.Code AS CourseCode, 
						  dbo.GENPollCategories.Time AS [Time], 
						 dbo.GENPollCategories.ExamType AS ExamType,
						 dbo.FN_GetExamType(dbo.GENPollCategories.ExamType, @LangCode) AS ExamTypeName
FROM        
dbo.GENTypes LEFT JOIN 
dbo.Contacts_Courses ON dbo.GENTypes.Id = dbo.Contacts_Courses.CourseId LEFT JOIN  
dbo.GENContacts ON dbo.Contacts_Courses.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
dbo.GENItems ON dbo.GENItems.TypeId = dbo.GENTypes.Id LEFT JOIN
dbo.GENExam_GENItem ON (dbo.GENItems.Id = GENExam_GENItem.SessionId  AND GENExam_GENItem.ExamId = @ExamId) LEFT JOIN 
dbo.GENExam_GENType ON (dbo.GENTypes.Id = GENExam_GENType.CourseId AND GENExam_GENType.ExamId = @ExamId) LEFT JOIN 
dbo.GENPollCategories ON (GENExam_GENType.ExamId = GENPollCategories.Id OR GENExam_GENItem.ExamId = GENPollCategories.Id)
where dbo.GENContacts.UserId = @UserId and   dbo.GENPollCategories.Id = @ExamId and  dbo.GENTypes.Id = @CourseId
GO
