CREATE Proc [dbo].[SP_FE_GetStudentDestinations] @DestId bigint,@UserId nvarchar(250)=null,@SearchString nvarchar(500)=null,@FromCreate datetime=null,@ToCreate datetime=null
--SP_FE_GetStudentDestinations 128,'d870812c-8ab3-4f97-b248-f2cffc7f0f84',null,null,null
AS
Begin

select distinct GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,FORMAT(GENContacts.DateCreated,'dd/MM/yyyy') AS StudentCreated ,
count(GENClassrooms.Id) AS CountRegisterCourses ,GENContacts.IdNumber AS StudentNationalId,GENContacts.DefaultEmail,GENContacts.Position,GENContacts.DefaultPhone,
[dbo].[fnLastDate_Dest_VcrsByContactId](GENContacts.Id) AS LastVcrDate,
[dbo].[fnLastStatus_Dest_VcrsByContactId](GENContacts.Id) AS LastVcrStatus,
[dbo].[fnLastCourse_ByContactId](GENContacts.Id) AS LastCourse,
dbo.[fnLastCourseDate_ByContactId](GENContacts.Id) AS LastCourseDate,
GENClassrooms.Name as VcrName,
GENTypes.Name AS CourseName,
GENTypes.Code AS CourseCode,
CASE
    WHEN ClassRoomStatus=0 THEN N'بدأت'
    WHEN ClassRoomStatus=1 THEN N'Dropped'
    WHEN ClassRoomStatus=2 THEN N'أنتهت'
	WHEN ClassRoomStatus=3 THEN N'مخططة'
    ELSE N'لا يوجد'
END As CourseStatus,
FORMAT(GENClassrooms.FromDateTime,'hh:mm tt') AS [FromtTime],
FORMAT(GENClassrooms.ToDateTime,'hh:mm tt') AS [ToTime],
FORMAT(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS [From],
FORMAT(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS [To],[dbo].[AttendanceCall](GENContacts.Id,GENClassrooms.Id) AS AttenPercentage,GENClassrooms.Code AS VcrCode,
dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudent,
(CASE WHEN dbo.GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' WHEN dbo.GENClassrooms.ClassRoomShift = 1 THEN N'مسائي' ELSE N'' END)AS ClassRoomShiftString,
DATEDIFF(day, GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) AS NumberOfDays ,lang.name AS LangName,GENClassrooms.Id as VcrId,
dbo.getTotalVCRs(GENContacts.Id) AS TotalVCRs,
dbo.getCurrentlVCRs(GENContacts.Id) AS CurrentVcrs,
		CASE
    WHEN GENClassroom_GENContact.BookingTypeId=0 THEN N'Requested'
    WHEN  GENClassroom_GENContact.BookingTypeId=1 THEN N'Confirmed'
    WHEN  GENClassroom_GENContact.BookingTypeId=2 THEN N'Rejected'
	WHEN  GENClassroom_GENContact.BookingTypeId=3 THEN N'Blocked'
	WHEN  GENClassroom_GENContact.BookingTypeId=4 THEN N'Canceled'
    WHEN  GENClassroom_GENContact.BookingTypeId=5 THEN N'Waiting'
	WHEN  GENClassroom_GENContact.BookingTypeId=6 THEN N'Added'
    ELSE N''
END As BookingType,
dbo.fnCount_DestVcrs_ByDestResponsible(GENContacts.Id,@UserId) as DestVcrNumber

from GENContacts 
left join GENClassroom_GENContact ON GENContacts.Id=GENClassroom_GENContact.StudentId 
left join GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id and GENClassrooms.isdeleted =0   and GENClassrooms.ispublish=1 and GENClassrooms.isactive=1 
and GENClassrooms.DestinationsId=@DestId
left join GENListValues lang ON GENClassrooms.LanguageId=lang.Id
left join GENTypes ON GENClassrooms.CourseId=GENTypes.Id


where 
(GENContacts.OrganizationId =@DestId or GENContacts.CompanyId =@DestId or  (GENContacts.createdbyid=@UserId 
and (GENContacts.CompanyId is null or GENContacts.OrganizationId is null))) 
and GENContacts.IsActive=1  and GENContacts.isdeleted=0 --and GENClassrooms.DestinationsId=@DestId
and (@SearchString IS null or @SearchString='' or GENContacts.Name like N'%'+@SearchString+'%' or GENContacts.DefaultPhone like N'%'+@SearchString+'%' or GENContacts.IDNumber like N'%'+@SearchString+'%')
and (@FromCreate IS null or @FromCreate='' or @FromCreate<=GENContacts.DateCreated)
and (@ToCreate IS null or @ToCreate='' or DATEADD(Day, 1,@ToCreate)>=GENContacts.DateCreated)
group by  GENContacts.Id, GENContacts.Name,GENContacts.DateCreated,GENClassrooms.Name ,GENTypes.Name,GENTypes.Code ,ClassRoomStatus,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime ,
GENContacts.IdNumber,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.Position,GENClassrooms.Id,
GENClassrooms.Code,GENClassrooms.ClassRoomShift,lang.Name,lang.Id,GENClassroom_GENContact.BookingTypeId



end
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetStudentsVCRSByCompany]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[SP_FE_GetStudentsVCRSByCompany] @CompanyId bigint=null,@ClassroomId bigint=null,@UserId nvarchar(250)=null
-- SP_FE_GetStudentsVCRSByCompany 128,789,'d870812c-8ab3-4f97-b248-f2cffc7f0f84'
AS
select distinct GENContacts.Id as contactId, GENContacts.Name,DefaultPhone,IDNumber,DefaultEmail,dbo.getTotalVCRs(GENContacts.Id) AS TotalVCRs,
dbo.getCurrentlVCRs(GENContacts.Id) AS CurrentVcrs,

		CASE
    WHEN GENClassroom_GENContact.BookingTypeId=0 THEN N'Requested'
    WHEN  GENClassroom_GENContact.BookingTypeId=1 THEN N'Confirmed'
    WHEN  GENClassroom_GENContact.BookingTypeId=2 THEN N'Rejected'
	WHEN  GENClassroom_GENContact.BookingTypeId=3 THEN N'Blocked'
	WHEN  GENClassroom_GENContact.BookingTypeId=4 THEN N'Canceled'
    WHEN  GENClassroom_GENContact.BookingTypeId=5 THEN N'Waiting'
	WHEN  GENClassroom_GENContact.BookingTypeId=6 THEN N'Added'
    ELSE N''
END As BookingType
,GENClassrooms.Name AS ClassroomName ,GENClassrooms.FromDateTime, GENClassrooms.ToDateTime  ,GENClassrooms.Id as ClassroomId,GENClassroom_GENContact.Id as GCC
,GENClassrooms.DestinationsId as classDestId
from GENContacts
left join GENClassroom_GENContact  ON GENContacts.Id=GENClassroom_GENContact.StudentId  
left join GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id and GENClassrooms.isdeleted =0   and GENClassrooms.ispublish=1 and GENClassrooms.isactive=1 
--and GENClassrooms.DestinationsId=@DestId
and GENClassrooms.IsActive=1 and GENClassrooms.ispublish=1 and
GENClassrooms.ClassRoomStatus<> 2 and GENClassrooms.ClassRoomStatus<>1 
AND GENClassrooms.IsDeleted=0 
and GENClassrooms.ToDateTime>=GETDATE() 
where (GENContacts.OrganizationId =@CompanyId or GENContacts.CompanyId =@CompanyId or 
(GENContacts.createdbyid=@UserId and (GENContacts.CompanyId is null or GENContacts.OrganizationId is null)))
GO
