Create PROCEDURE [dbo].[SP_FE_GetTalentCourseRatings]
	-- Add the parameters for the stored procedure here
	@CourseId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select COUNT(Id) AS Counts, Rating,EntityId FROM GENRatings
	WHERE BaseEntityId = 28 AND EntityId = @CourseId
	GROUP BY Rating, EntityId
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetUserUnRegistered_Courses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_FE_GetUserUnRegistered_Courses] --SP_FE_GetUserUnRegistered_Courses 'd870812c-8ab3-4f97-b248-f2cffc7f0f84','ar',null

(@userId nvarchar(128),@LangCode nvarchar(500),@Id bigint = null)
as

SELECT     distinct dbo.GENTypes.Id,       dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)  as Name, 
 dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) as Description,
 dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount
						 ,dbo.GENTypes.int1 as CoueseHours,Field.Name AS FieldName, Field.Id AS FieldId,
						 CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount,dbo.GENTypes.Code AS CourseCode,
						 GENClassroom_GENContact.BookingTypeId,GENClassrooms.Id AS ClassroomId,
						 CAST((SUM((CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END)) / CAST((CASE WHEN COUNT(GENItems.Id) > 0 THEN COUNT(GENItems.Id) * 100 ELSE 1 END) AS decimal(18,2))) * 100 AS decimal(18,2) ) AS FinishedPercentge
FROM            dbo.GENTypes left JOIN 
CourseCategories ON GENTypes.Id=CourseCategories.CourseId
 left JOIN    GENTypeCategories as Field ON CourseCategories.CategoryId =Field.Id 
 inner JOIN dbo.GENClassroom_GENContact 
						 inner JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id
						 inner JOIN dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id AND GENClassrooms.IsDeleted=0 and dbo.GENClassrooms.isActive =1 ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId 
						 LEFT  JOIN
						 dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT JOIN
			dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
			LEFT JOIN Course_Session ON Course_Session.CourseId = GENTypes.Id
		  LEFT JOIN GENItems ON Course_Session.SessionId = GENItems.Id 
WHERE        (dbo.GENContacts.UserId = @userId) 
AND GENTypes.IsDeleted=0 AND((FromDateTime <= GETDATE()) OR (FromDateTime >= GETDATE()))
 and GENClassroom_GENContact.BookingTypeId NOT IN (2,3,4) 
GROUP BY
dbo.GENTypes.Id,  dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.GENClassrooms.ToDateTime,
                         dbo.GENClassrooms.FromDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 , dbo.GENClassrooms.Id,Field.Name, Field.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENListValues.shortCode,dbo.GENClassrooms.Code,GENTypes.Code,dbo.GENTypes.Int1, dbo.GENTypes.Int2,
			 GENClassroom_GENContact.BookingTypeId
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetUserUnRegistered_Courses_VCR]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_GetUserUnRegistered_Courses_VCR] (@userId nvarchar(128) ,@LangCode nvarchar(500))-- SP_FE_GetUserUnRegistered_Courses_VCR '96d8c852-8574-400d-90b2-669d9b9f28d5','ar'
as
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId, GENClassrooms.Name AS ClassroomName, 
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			((SUM(GENContactProgressCompletions.CompletionValue) / (COUNT(GENItems.Id) * 100)) * 100 ) AS FinishedPercentge,dbo.GENTypes.Code AS CourseCode,dbo.GENClassrooms.Code AS ClassroomCode,
			dbo.GENTypes.Int1,dbo.GENTypes.Int2,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate
			,GENClassrooms.PaymentCondation,GENListValues.Name AS LangName,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
				,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift


FROM            dbo.GENTypes RIGHT OUTER JOIN
                         dbo.GENClassroom_GENContact RIGHT OUTER JOIN
                         dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId
						 LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN
			dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id LEFT JOIN
			dbo.GENTypeCategories Field ON dbo.GENTypes.TypeCategoryId = Field.Id
			LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
			LEFT JOIN GENItems ON GENItems.TypeId = GENTypes.Id
WHERE        (dbo.GENContacts.UserId = @userId) and dbo.GENClassrooms.isActive =1 AND  GENClassroom_GENContact.BookingTypeId=0
and (GENClassrooms.IsPrivate=0 or GENClassrooms.IsPrivate is null)
GROUP BY    dbo.GENTypes.Id,dbo.GENListValues.shortCode,dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         
						  dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1, dbo.GENClassrooms.Id,Field.Name, Field.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENTypes.Code,dbo.GENClassrooms.Code,dbo.GENTypes.Int1,dbo.GENTypes.Int2,GENClassrooms.Date1
			,GENClassrooms.Date2,GENClassrooms.ClassRoomShift,GENClassrooms.PaymentCondation,GENListValues.Name
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_GetUserUnRegistered_Courses_VcrEvents]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_GetUserUnRegistered_Courses_VcrEvents] (@userId nvarchar(128) ,@LangCode nvarchar(500))
-- SP_FE_GetUserUnRegistered_Courses_VcrEvents 'd870812c-8ab3-4f97-b248-f2cffc7f0f84','ar'
as
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,Field.Name AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId, GENClassrooms.Name AS ClassroomName, 
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			((SUM(GENContactProgressCompletions.CompletionValue) / (COUNT(GENItems.Id) * 100)) * 100 ) AS FinishedPercentge,dbo.GENTypes.Code AS CourseCode,dbo.GENClassrooms.Code AS ClassroomCode,
			dbo.GENTypes.Int1,dbo.GENTypes.Int2,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift
			,GENClassrooms.PaymentCondation,GENListValues.Name AS LangName,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
			,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo

FROM            dbo.GENTypes  LEFT JOIN
                         dbo.GENClassroom_GENContact  LEFT JOIN
                         dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id  LEFT JOIN
                         dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId
						  LEFT JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id  LEFT JOIN
			dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id LEFT JOIN
			CourseCategories ON GENTypes.Id=CourseCategories.CourseId LEFT JOIN
			dbo.GENTypeCategories Field ON dbo.CourseCategories.CategoryId = Field.Id
			
			LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
			LEFT JOIN GENItems ON GENItems.TypeId = GENTypes.Id
WHERE        (dbo.GENContacts.UserId = @userId) and dbo.GENClassrooms.isActive =1 
AND  GENClassroom_GENContact.BookingTypeId = 1 and  
(GENClassrooms.ProsecutionId <> 0 and GENClassrooms.ProsecutionId <> 1) 
--and dbo.GENClassrooms.FromDateTime <= GETDATE() AND dbo.GENClassrooms.ToDateTime <= GETDATE()
GROUP BY    dbo.GENTypes.Id,dbo.GENListValues.shortCode,dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         
						  dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1, dbo.GENClassrooms.Id,Field.Name, Field.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENTypes.Code,dbo.GENClassrooms.Code,dbo.GENTypes.Int1,dbo.GENTypes.Int2
			,dbo.GENClassrooms.Date1,dbo.GENClassrooms.Date2,dbo.GENClassrooms.ClassRoomShift,dbo.GENClassrooms.PaymentCondation,dbo.GENListValues.Name
GO
