CREATE PROCEDURE [dbo].[SP_FE_InstructorAllStudents] 
	-- Add the parameters for the stored procedure here
	@id BIGINT, @LangCode nvarchar(500),@StudentName nvarchar(500)=null,@StudentEmail nvarchar(500)=null,@StudentNId nvarchar(500)=null,
	@StudentPhone  nvarchar(500)=null,@VcrId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT GENContacts.Name AS StudentName, GENContacts.Id AS StudentId, GENContacts.DefaultEmail AS StudentEmail, dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS  MainCourseName,
	'' AS MajorFieldName, GENContacts.Code AS StudentCode, GENClassrooms.FromDateTime, GENContacts.Image,GENContacts.DefaultPhone AS DefaultPhone,
		GENClassrooms.Name AS VcrName,'' AS SessionName
	FROM GENContacts 
	inner JOIN GENClassroom_GENContact ON GENContacts.Id = GENClassroom_GENContact.StudentId
	inner JOIN GENClassrooms ON GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
	inner JOIN GENTypes ON GENClassrooms.CourseId = GENTypes.Id
    inner Join TLMSClassroom_Session ON GENClassrooms.Id=TLMSClassroom_Session.ClassroomId
    inner JOIN 	dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id 
	inner join GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id
	WHERE GENEmployees.Id = @id AND GENClassroom_GENContact.BookingTypeId in (0,1,5,6) and dbo.GENClassrooms.isActive =1 and GENClassrooms.IsDeleted=0 
and GENContacts.IsUser = 1   and GENClassrooms.ProsecutionId=0
and (@StudentName IS null or @StudentName='' or GENContacts.Name like N'%'+@StudentName+'%')
and (@StudentEmail IS null or @StudentEmail='' or GENContacts.defaultEmail like N'%'+@StudentEmail+'%')
and (@StudentNId IS null or @StudentNId='' or GENContacts.IDNumber like N'%'+@StudentNId+'%')
and (@StudentPhone IS null or @StudentPhone='' or GENContacts.DefaultPhone like N'%'+@StudentPhone+'%')
and (@VcrId IS null or @VcrId='' or GENClassrooms.Id =@VcrId )
order by GENContacts.Name asc
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_InstructorAllStudents_Events]    Script Date: 7/1/2026 10:45:03 AM ******/
