CREATE Proc [dbo].[SP_FE_InstructorClassWithITems] 
(@ClassroomId BIGINT,@InstructorId BIGINT,@LangCode NVARCHAR(128))
as
    SELECT DISTINCT dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, CAST (dbo.GENItems.DisplayOrder AS INT ) AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                    dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
					 DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.ExamId, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, 
                    dbo.GENClassrooms.InteractiveMeetingURL, dbo.fn_Type_Translate_ByKeyandId(  dbo.GENClassrooms.Id,'InstructorInstructions',@LangCode)AS InstructorInstructions, dbo.GENClassrooms.ExamStartTime, dbo.GENClassrooms.ExamEndTime, dbo.GENClassrooms.InteractiveMeetingDateTime, 
                    dbo.GENItems.Id AS ItemId,dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Name' ,@LangCode) AS ItemName, 
					dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Description', @LangCode)  AS ItemDescription, dbo.GENItemFiles.AzureUri AS FileURL, dbo.GENItemVideos.AzureUri AS VideoURL, 
                    dbo.GENPollCategories.IsActive AS ExamActive, dbo.GENPollCategories.IsPosted ,iif(dbo.GENItems.int1 is null,0,dbo.GENItems.int1) as LectureHourse, iif(dbo.GENTypes.int1 is null,0,dbo.GENTypes.int1) as CoueseHours,
					 iif(dbo.GENTypes.Int2 is null,0,dbo.GENTypes.Int2) as CourseMinutes,
					dbo.GENItems.IsActive as ItemActive,dbo.GENItems.IsPublish as ItemPublish	 ,iif(dbo.GENItems.int2 is null,0,dbo.GENItems.int2) as TableDisplayOrder,dbo.GENClassrooms.Id as ClassRoomId,
					dbo.GENClassrooms.LanguageId as ClassRoomLanguageId ,GENItemFiles.LanguageId as FileLanguageId , dbo.GENItemVideos.LanguageId as VideoLanguageId,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'RichContent', @LangCode) AS RichContent,dbo.GENItemVideos.Name AS VideoName,
					GENItemFiles.FileName AS FileName,dbo.GENPollCategories.Name AS ExamName,dbo.GENItemVideos.Id AS VideoId, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String1', @LangCode)  AS CourseString1,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String2', @LangCode)  AS CourseString2, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String3', @LangCode)  AS CourseString3, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String4', @LangCode)  AS CourseString4, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String5', @LangCode)  AS CourseString5,
					Assessments.[Id] AS AssessmentId ,Assessments.[DisplayOrder] AS AssessmentDisplayOrder ,Assessments.[Code] AS AssessmentCode ,Assessments.[Name] AS AssessmentName
				,Assessments.[Description] AS AssessmentDescription ,Assessments.[DisplayOrdering]  AS AssessmentDisplayOrdering ,Assessments.[Image] AS AssessmentImage
				,Assessments.[Video] AS AssessmentVideo ,Assessments.[Audio] AS AssessmentAudio ,Assessments.[File] AS AssessmentFile ,Assessments.[Time] AS AssessmentTime
				,Assessments.[Weight] AS AssessmentWeight ,Assessments.[ActucalScore] AS AssessmentActualScore ,Assessments.[SuccessScore] AS AssessmentSuccessScore
				,Assessments.[LanguageId] AS AssessmentLanguageId ,Assessments.[ExamType] AS AssessmentExamType,dbo.FN_GetExamType(Assessments.[ExamType],@LangCode) AS AssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS AssessmentDateTime,
			     
				 ClassroomAssessments.[Id] AS ClassroomAssessmentId ,ClassroomAssessments.[DisplayOrder] AS ClassroomAssessmentDisplayOrder ,
				 ClassroomAssessments.[Code] AS ClassroomAssessmentCode ,ClassroomAssessments.[Name] AS ClassroomAssessmentName
				,ClassroomAssessments.[Description] AS ClassroomAssessmentDescription ,ClassroomAssessments.[DisplayOrdering]  AS ClassroomAssessmentDisplayOrdering ,
				ClassroomAssessments.[Image] AS ClassroomAssessmentImage
				,ClassroomAssessments.[Video] AS ClassroomAssessmentVideo ,ClassroomAssessments.[Audio] AS ClassroomAssessmentAudio ,ClassroomAssessments.[File] AS ClassroomAssessmentFile 
				,ClassroomAssessments.[Time] AS ClassroomAssessmentTime
				,ClassroomAssessments.[Weight] AS ClassroomAssessmentWeight,ClassroomAssessments.[ActucalScore] AS ClassroomAssessmentActualScore ,
				ClassroomAssessments.[SuccessScore] AS ClassroomAssessmentSuccessScore
				,ClassroomAssessments.[LanguageId] AS ClassroomAssessmentLanguageId ,ClassroomAssessments.[ExamType] AS ClassroomAssessmentExamType, 
				dbo.FN_GetExamType(ClassroomAssessments.[ExamType],@LangCode) AS ClassroomAssessmentsExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS ClassroomAssessmentDateTime,
				3 AS ItemBaseEntityId,176 AS ClassroomBaseEntityId,
				129 AS ExamBaseEntityId,28 AS CourseBaseEntityId,
				182 AS FileBaseEntityId,181 AS VideoBaseEntityId,
				CourseAssessment.[Id] AS CourseAssessmentId ,CourseAssessment.[DisplayOrder] AS CourseAssessmentDisplayOrder ,
				 CourseAssessment.[Code] AS CourseAssessmentCode ,CourseAssessment.[Name] AS CourseAssessmentName
				,CourseAssessment.[Description] AS CourseAssessmentDescription ,CourseAssessment.[DisplayOrdering]  AS CourseAssessmentDisplayOrdering ,
					CourseAssessment.[Image] AS CourseAssessmentImage
				,CourseAssessment.[Video] AS CourseAssessmentVideo ,CourseAssessment.[Audio] AS CourseAssessmentAudio ,CourseAssessment.[File] AS CourseAssessmentFile 
				,CourseAssessment.[Time] AS CourseAssessmentTime
				,CourseAssessment.[Weight] AS CourseAssessmentWeight,CourseAssessment.[ActucalScore] AS CourseAssessmentActualScore ,
				CourseAssessment.[SuccessScore] AS CourseAssessmentSuccessScore
				,CourseAssessment.[LanguageId] AS CourseAssessmentLanguageId ,CourseAssessment.[ExamType] AS CourseAssessmentExamType, 
				dbo.FN_GetExamType(CourseAssessment.[ExamType],@LangCode) AS CourseAssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS CourseAssessmentDateTime,
				  FORMAT( TLMSClassroom_Session.FromDateTime, 'HH:mm') AS SessionFromTime, FORMAT( TLMSClassroom_Session.ToDateTime, 'HH:mm') AS SessionToTime,
				  TLMSClassroom_Session.SessionDateTime AS SessionDate
FROM
GENClassrooms left JOIN
 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT JOIN
						 Course_Session ON Course_Session.CourseId = GENTypes.Id   inner JOIN
						 TLMSClassroom_Session ON Course_Session.SessionId=TLMSClassroom_Session.SessionId Left join
                          [dbo].[GENExam_GENClassroom] ON dbo.[GENExam_GENClassroom].ClassroomId = dbo.GENClassrooms.Id AND [GENExam_GENClassroom].IsActive = 1 LEFT JOIN
                          dbo.GENPollCategories ON  GENPollCategories.Id = dbo.[GENExam_GENClassroom].ExamId LEFT OUTER JOIN
						      dbo.GENItems  ON TLMSClassroom_Session.SessionId = dbo.GENItems.Id and  dbo.GENItems.IsDeleted=0  and TLMSClassroom_Session.ClassroomId = GENClassrooms.Id   LEFT JOIN
                         dbo.GENItemVideos ON dbo.GENItems.Id = dbo.GENItemVideos.ItemId  LEFT OUTER JOIN
                         dbo.GENItemFiles ON dbo.GENItems.Id = dbo.GENItemFiles.ItemId LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT JOIN
						 [dbo].[GENExam_GENItem] ON [GENExam_GENItem].SessionId = dbo.GENItems.Id AND [GENExam_GENItem].IsActive = 1  LEFT JOIN
						 [dbo].[GENExam_GENType]  ON [GENExam_GENType].CourseId = dbo.GENTypes.Id AND [GENExam_GENType].IsActive = 1  LEFT JOIN
