						 dbo.GENPollCategories CourseAssessment ON [GENExam_GENType].ExamId = CourseAssessment.Id 
WHERE        (GENEmployees.Id = @InstructorId) and dbo.GENClassrooms.Id = @ClassroomId and GENClassrooms.IsDeleted=0 and GENClassrooms.ClassroomCategoryId=2
