	Left join GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id
	WHERE GENEmployees.Id = @id AND GENClassroom_GENContact.BookingTypeId = 1 and 
	 GENClassrooms.IsDeleted=0 and dbo.GENClassrooms.isActive =1 and GENClassrooms.ClassroomCategoryId=2
and GENContacts.IsUser = 1 
and (@StudentName IS null or @StudentName='' or GENContacts.Name like N'%'+@StudentName+'%')
and (@StudentEmail IS null or @StudentEmail='' or GENContacts.defaultEmail like N'%'+@StudentEmail+'%')
and (@StudentNId IS null or @StudentNId='' or GENContacts.IDNumber like N'%'+@StudentNId+'%')
and (@StudentPhone IS null or @StudentPhone='' or GENContacts.DefaultPhone like N'%'+@StudentPhone+'%')
and (@VcrId IS null or @VcrId='' or GENClassrooms.Id =@VcrId)
order by GENContacts.Name asc

END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_MyStudentPreviousCourses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_MyStudentPreviousCourses] 
(@userId nvarchar(128) ,@LangCode nvarchar(500),@Id bigint= null,@EmpId bigint=null,@FromCreate datetime=null,@ToCreate datetime=null )
--SP_FE_MyStudentPreviousCourses 'b2b125a5-50f9-4b59-896f-4f05f8d05c7a','ar',null,20099,null,null
as
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,'' AS FieldName, CAST(0 as bigint) AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId, GENClassrooms.Name AS ClassroomName, 
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			CAST(0 as float) AS FinishedPercentge,dbo.GENTypes.Code AS CourseCode,dbo.GENClassrooms.Code AS ClassroomCode,
			dbo.GENTypes.Int1,dbo.GENTypes.Int2,GENClassrooms.PaymentCondation,GENListValues.Name AS LangName,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
				,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift,
			[dbo].[fn_VcrStudentCount](GENClassrooms.Id) AS TotalStudent
FROM             dbo.GENClassrooms inner  JOIN
           dbo.GENTypes ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId inner  JOIN
		   dbo.GENClassroom_GENContact ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id  inner  JOIN
			dbo.TLMSClassroom_Session ON dbo.GENClassrooms.Id = dbo.TLMSClassroom_Session.ClassroomId inner  JOIN
             dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
               dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN

		  
			 GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
				 LEFT JOIN
			dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id
WHERE      
(dbo.GENContacts.UserId = @userId) and dbo.GENClassrooms.isActive =1 AND GENClassrooms.IsDeleted=0 AND GENTypes.IsDeleted=0

 
and GENClassrooms.DestinationsId is null and GENClassrooms.ProsecutionId=0 and GENClassroom_GENContact.BookingTypeId=1
and (GENClassrooms.IsPrivate=0 or GENClassrooms.IsPrivate is null)
and (@EmpId IS null  or GENEmployees.Id  = @EmpId) and GENClassrooms.ClassroomCategoryId=1
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@FromCreate as date) and cast(GENClassrooms.ToDateTime as date) <= cast(@ToCreate as date)) 
or (@FromCreate is null and @ToCreate is null and 
((cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date) and cast(GENClassrooms.ToDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@FromCreate) = 0 and len(@ToCreate) = 0))
GROUP BY    dbo.GENTypes.Id,dbo.GENListValues.shortCode,dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         
						  dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1, dbo.GENClassrooms.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENTypes.Code,dbo.GENClassrooms.Code,dbo.GENTypes.Int1,dbo.GENTypes.Int2,GENClassrooms.ClassRoomShift,GENClassrooms.PaymentCondation,GENListValues.Name
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_OrderDetailsHeaderById]    Script Date: 7/1/2026 10:45:03 AM ******/
