-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 10/08/2020
-- Description:	Get Order history By Contact
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_OrderDetailsHeaderById]
	-- Add the parameters for the stored procedure here
	@Id BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENOrderDetails.*,Format(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFrom,Format(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrTo,
	DATEDIFF(day, GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) AS VcrNumDay,GENClassrooms.Name AS VcrName
	FROM GENOrderDetails 
	left join GENOrders ON GENOrderDetails.OrderId=GENOrders.Id
	Left JOIN GENClassrooms ON GENOrders.VcrId = GENClassrooms.Id
	WHERE GENOrderDetails.OrderId = @Id
END
GO
