GO
CREATE PROCEDURE [dbo].[SP_FE_OrderHeaderById]
	-- Add the parameters for the stored procedure here
	@Id BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENOrders.*,GENContacts.Name AS ContactName, GENContacts.DefaultEmail AS ContactEmail, GENContacts.DefaultPhone AS ContactPhone,
	GENContacts.DefaultAddress AS ContactAddress ,GENClassrooms.Name AS VcrName,GENReturnedOrders.DateCreated AS ReturnedOrdersCreatedDate,
	DATEADD(DAY,  -(GENClassrooms.Int1), GENClassrooms.FromDateTime) AS VcrRegisterEndDate ,GENClassrooms.FromDateTime as VcrStartDate
	FROM GENOrders 
	INNER JOIN GENContacts ON GENOrders.ContactId = GENContacts.Id
	Left JOIN GENClassrooms ON GENOrders.VcrId = GENClassrooms.Id
	Left JOIN GENReturnedOrders ON GENOrders.Id = GENReturnedOrders.orderId
	WHERE GENOrders.Id = @Id
END
GO
