CREATE PROCEDURE [dbo].[SP_FE_OrderListByContactId]
	-- Add the parameters for the stored procedure here
	@Id BIGINT
AS
BEGIN
	SET NOCOUNT ON;
	 	SELECT GENOrders.Id,GENOrders.Name,GENOrders.TransactionId,GENOrders.DateCreated ,GENOrders.PaidPrice,GENOrders.IsPaid,GENOrders.PaymentType,
	 (case when GENReturnedOrders.Id is not null and GENReturnedOrders.Refund = 1 then 'Returned' Else 'Order' END) AS Type,GENReturnedOrders.Reason
	FROM GENOrders left join 
	GENReturnedOrders ON GENOrders.Id=GENReturnedOrders.orderId
