CREATE Proc [dbo].[Sp_FE_SelectAllCourses] (@langCode nvarchar(500))
AS
Begin
SELECT dbo.GENTypes.Id,dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name',@langCode) as Name, 
                         dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Description',@langCode) as Description,
						 dbo.GENTypes.Bool2 AS IsFree, 					
						 dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image], dbo.fn_GetPriceString_ById(28,dbo.GENTypes.Id,@langCode,0) as PriceString,
						 dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						 CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount,
						 GENClassrooms.Name AS ClassroomName,GENClassrooms.Id AS ClassroomId,dbo.GENTypes.Code AS Coursecode,
						 dbo.fn_TypeCategories_Translate_ByKeyandId(GENTypeCategories.Id ,'Name', @LangCode) AS FieldName,GENTypeCategories.Id AS FieldId
FROM  GENTypes LEFT JOIN 
	GENTypeCategories ON GENTypes.TypeCategoryId =GENTypeCategories.Id RIGHT OUTER JOIN
GENClassrooms ON GENTypes.Id=GENClassrooms.CourseId and GENClassrooms.CompanyId is null  LEFT JOIN 
GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
WHERE dbo.GENTypes.IsActive = 1 AND dbo.GENTypes.IsPublish = 1  
GROUP BY    dbo.GENTypes.Id, dbo.GENTypes.Bool2,GENClassrooms.Name,GENTypes.Code,GENTypeCategories.Id,GENClassrooms.Id
end
GO
