/****** Object:  StoredProcedure [dbo].[SP_FE_SelectCoursesByTalentId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_SelectCoursesByTalentId] (@TalentId bigint,@LangCode nvarchar(500))
AS
Begin
select  GENTypes.Id,dbo.fn_Type_Translate_ByKeyandId(GENTypes.Id,'Name',@LangCode) AS Name ,GENTalents_Generic.TalentId,
dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image],dbo.fn_Type_Translate_ByKeyandId(GENTypes.Id,'Description',@LangCode) AS Description,GENTalents_Generic.VcrId
from GENTalents
left join GENTalents_Generic ON GENTalents.Id=GENTalents_Generic.TalentId left join 
GENTypes ON GENTalents_Generic.EntityId=GENTypes.Id
where GENTalents_Generic.BaseEntityId=28 and GENTalents_Generic.TalentId=@TalentId and GENTypes.IsActive=1 
and GENTypes.IsDeleted = 0 and GENTalents.IsDeleted = 0 and GENTypes.IsActive = 1 and GENTypes.IsPublish = 1 
--and (GENTalents.ToDateTime>GETDATE() or GENTalents.ToDateTime is null)
order by GENTypes.DisplayOrdering
End
