CREATE Proc [dbo].[SP_FE_SelectCurrentStudents_TalentReg_Accepted] (@InstructorId bigint
,@StudentName nvarchar(500)=null,@StudentEmail nvarchar(500)=null,@StudentNId nvarchar(500)=null,
	@StudentPhone  nvarchar(500)=null,@VcrId BIGINT
)
AS
Begin
select distinct GENContacts.Id , GENContacts.Name ,GENContacts.DefaultPhone,GENClassrooms.Name AS VcrName,GENContacts.DefaultEmail
from GENContact_Talent left join 
GENTalents ON GENContact_Talent.TalentId=GENTalents.Id inner join 
Talents_Requestes ON GENTalents.Id=Talents_Requestes.TalentId left join 
GENContacts ON GENContact_Talent.ContactId=GENContacts.Id left join 
GENTalents_Generic ON GENContact_Talent.TalentId=GENTalents_Generic.TalentId left JOIN
 [TLMSClassroom_Session] on [TLMSClassroom_Session].[ClassroomId] = GENTalents_Generic.VcrId left join 
 GENClassrooms ON GENTalents_Generic.VcrId=GENClassrooms.Id
where [TLMSClassroom_Session].InstructorId=@InstructorId
and Talents_Requestes.talentStatus =2 
and (@StudentName IS null or @StudentName='' or GENContacts.Name like N'%'+@StudentName+'%')
and (@StudentEmail IS null or @StudentEmail='' or GENContacts.defaultEmail like N'%'+@StudentEmail+'%')
and (@StudentNId IS null or @StudentNId='' or GENContacts.IDNumber like N'%'+@StudentNId+'%')
and (@StudentPhone IS null or @StudentPhone='' or GENContacts.DefaultPhone like N'%'+@StudentPhone+'%')
and (@VcrId IS null or @VcrId='' or GENClassrooms.Id =@VcrId)
END
GO
