/****** Object:  StoredProcedure [dbo].[SP_FE_SelectExamByTalent]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROC [dbo].[SP_FE_SelectExamByTalent]  (
   @TalentId bigint
)
as
begin

SELECT Distinct

GENPollCategories.Name as ExamName,cast(GENPollCategories.Weight as dec(18,2)) as ExamWeight,GENTypes.Name AS CourseName,'' as SessionName,isnull(GENExam_GENType.ExamWeightedPrecentage,0) as ExamWeightedPrecentage,
Max((CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) 
	  ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END)) as Score ,count(distinct PollCategoryandPolls.PollId) AS QuCount
FROM GENPollCategories  
left join PollCategoryandPolls ON GENPollCategories.Id=PollCategoryandPolls.PollCategoryId
	left join GENExam_GENItem on GENPollCategories.Id = GENExam_GENItem.ExamId 
	left join GENItems on GENItems.Id = GENExam_GENItem.SessionId
	left join GENTypes on GENTypes.Id = GENItems.TypeId 
	left join GENTalents_Generic on GENTalents_Generic.BaseEntityId = 28 and GENTalents_Generic.EntityId = GENTypes.Id
	 inner join GENContact_Talent on GENTalents_Generic.TalentId = GENContact_Talent.TalentId
	left join GENExamAnswerHeaders on GENPollCategories.Id  = GENExamAnswerHeaders.ExamId
	left join GENContacts  on GENContacts.Id=GENExamAnswerHeaders.StudentId 
	left join GENExam_GENType on GENExam_GENType.ExamId = GENExamAnswerHeaders.ExamId 
 where
 GENTalents_Generic.TalentId = @TalentId  and GENContact_Talent.TalentId=@TalentId
 GRoup by  GENPollCategories.Name,GENPollCategories.Weight,GENTypes.Name,GENExam_GENType.ExamWeightedPrecentage

UNION 
SELECT  Distinct
GENPollCategories.Name as ExamName,cast(GENPollCategories.Weight as dec(18,2)) as ExamWeight,'' as CousreName,GENItems.Name AS SessionName,isnull(GENExam_GENItem.ExamWeightedPrecentage,0) as ExamWeightedPrecentage,
Max((CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) 
	  ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END)) as Score ,count(distinct PollCategoryandPolls.PollId) AS QuCount
FROM GENPollCategories  
left join PollCategoryandPolls ON GENPollCategories.Id=PollCategoryandPolls.PollCategoryId
	left join GENExam_GENItem on GENPollCategories.Id = GENExam_GENItem.ExamId 
	left join GENItems on GENItems.Id = GENExam_GENItem.SessionId
	left join GENTypes on GENTypes.Id = GENItems.TypeId 
	left join GENTalents_Generic on GENTalents_Generic.BaseEntityId = 28 and GENTalents_Generic.EntityId = GENTypes.Id
    inner join GENContact_Talent on GENTalents_Generic.TalentId = GENContact_Talent.TalentId 
	left join GENExamAnswerHeaders on GENPollCategories.Id  = GENExamAnswerHeaders.ExamId
	left join GENContacts  on GENContacts.Id=GENExamAnswerHeaders.StudentId 
	left join GENExam_GENType on GENExam_GENType.ExamId = GENExamAnswerHeaders.ExamId 
where
GENTalents_Generic.TalentId = @TalentId  and GENContact_Talent.TalentId=@TalentId
 GRoup by  GENPollCategories.Name,GENPollCategories.Weight,GENItems.Name,GENExam_GENItem.ExamWeightedPrecentage

END
GO
