CREATE Proc [dbo].[SP_FE_SelectFilesRelatedCourse] (@CourseId bigint)
AS
Begin
SELECT GENFiles.*,GENListValues.Name AS LanguageName,LV.Name As FileType, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt 
FROM GENFiles
