/****** Object:  StoredProcedure [dbo].[SP_FE_SelectQuestionContribution]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_FE_SelectQuestionContribution]
	-- Add the parameters for the stored procedure here
	@QuestionId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT GENPollAnswers.Answer AS AnswerName,GENExamAnswerDetails.PollAnswerId, COUNT(GENExamAnswerDetails.PollAnswerId) AS AnswersCount,
	(SELECT Count(GENExamAnswerDetails.PollId) FROM GENExamAnswerDetails WHERE PollId = @QuestionId) AS TotalAnswersCount, 
	CAST((CAST(COUNT(GENExamAnswerDetails.PollAnswerId) AS decimal(18,2)) / (SELECT CAST(Count(GENExamAnswerDetails.PollId) AS decimal(18,2)) FROM GENExamAnswerDetails WHERE PollId = @QuestionId) * 100) AS decimal(10,0)) AS AnswerPercentage
	FROM GENExamAnswerDetails 
	left join 
      GENPollAnswers on GENExamAnswerDetails.PollAnswerId=GENPollAnswers.Id
	WHERE GENExamAnswerDetails.PollId =@QuestionId

	GROUP BY GENExamAnswerDetails.AnswerName,GENExamAnswerDetails.PollAnswerId, GENExamAnswerDetails.PollAnswerId,GENPollAnswers.Answer
END
GO
