Create PROC [dbo].[SP_FE_SelectRateDash_ByCourseId] (@CourseId bigint)
AS
Begin
select count(GENRatings.UserId) AS CountPepole,avg(GENRatings.Rating) AS CountRate,COUNT(GENRatings.Comment) AS CountReview from GENClassrooms inner join 
GENTypes ON GENClassrooms.CourseId=GENTypes.Id inner join 
GENRatings ON GENClassrooms.Id=GENRatings.EntityId and GENRatings.BaseEntityId=176
where GENTypes.Id=@CourseId and (GENClassrooms.IsActive=1 and GENClassrooms.IsPublish=1 ) and GENClassrooms.IsDeleted=0 and GENClassrooms.ProsecutionId=0
END
