CREATE PROC [dbo].[SP_FE_SelectSessionsVCR_ByInstructor] (@VCRId bigint,@InstructorId bigint)
AS
Begin
select TLMSClassroom_Session.Id,TLMSClassroom_Session.SessionId, GENClassrooms.name AS VCRName ,GENItems.Name  AS SessionName,TLMSClassroom_Session.SessionDateTime,
Format(TLMSClassroom_Session.SessionDateTime,'yyyy/MM/dd') AS SessionDate,ROW_NUMBER() OVER (ORDER BY TLMSClassroom_Session.Id) row_num,
dbo.fn_ItemCount_AttendanceInSessions(TLMSClassroom_Session.SessionId,TLMSClassroom_Session.ClassroomId,TLMSClassroom_Session.InstructorId) AS CountStudents,DATEDIFF(HOUR,TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime) AS SessionTime
from TLMSClassroom_Session inner join 
GENClassrooms ON TLMSClassroom_Session.ClassroomId=GENClassrooms.Id inner join 
GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id 
where TLMSClassroom_Session.ClassroomId= @VCRId and TLMSClassroom_Session.InstructorId=@InstructorId and GENClassrooms.IsActive=1 and GENClassrooms.IsDeleted=0

END
