CREATE PROC [dbo].[SP_FE_SelectTopFiveNews] (@LangCode nvarchar(MAX))
AS
Begin
declare @con_value nvarchar(max);
SELECT @con_value=GENConfigurations.Value from GENConfigurations where GENConfigurations.Name like N'MainRedirectLink';
select Top(5) dbo.fn_Wiki_Translate_ByKeyandId(GENWikis.Id,'Name',@LangCode) as Name,GENWikis.Date1,@con_value+'news-details/'+ CAST(GENWikis.Id AS nvarchar(MAX)) AS LiveURL  from GENWikis where WikiCategoryId=55 and  IsActive=1 and ispublish=1
order by Date1 desc
END
GO
