CREATE PROC  [dbo].[SP_FE_SelectVCRTalentRegistered_ByStudentId]  (@StudentId bigint,@Langcode nvarchar(MAX) ) 
AS
Begin

select distinct GENClassrooms.Id,dbo.fn_ClassRoom_Translate_ByKeyandId(GENClassrooms.Id,'Name',@Langcode) as Name,dbo.fn_FirstImage_BaseEntityEntityId(28,GENClassrooms.CourseId) as [Image]
,GENTypes.Description as CourseDescription,GENClassrooms.CourseId,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
from GENClassrooms inner join 
GENTalents_Generic ON GENClassrooms.Id=GENTalents_Generic.VcrId and GENTalents_Generic.TalentId is not null inner join 
GENContact_Talent ON GENTalents_Generic.TalentId=GENContact_Talent.TalentId inner join 
GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId and GENClassroom_GENContact.StudentId=@StudentId

left join GENTypes on GENTypes.id = GENClassrooms.CourseId
where GENContact_Talent.ContactId=@StudentId  and GENClassrooms.IsActive=1 
and GENClassrooms.IsPublish=1  and GENClassrooms.IsDeleted=0 and
(GENClassrooms.ClassRoomStatus<>1  or GENClassrooms.ClassRoomStatus is null)
END
GO
