CREATE proc [dbo].[SP_FE_SelectZoom_DType_VCRId] (@VCRId bigint,@LangCode nvarchar(500))
AS
Begin
select Zoom_Session.Name AS ZoomMeeting,Zoom_Session.interactiveMeetingURL,
dbo.fn_ClassRoom_Translate_ByKeyandId(GENClassrooms.Id,'Name',@LangCode) AS VCRName
,Zoom_Session.SessionDateTime,Zoom_Session.VideoURL,
 dbo.FN_ConvertDaystoArabic(FORMAT(Zoom_Session.SessionDateTime,'hh:mm'),@LangCode) as FromTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(DATEADD( MINUTE,Zoom_Session.ZoomDuration,Zoom_Session.SessionDateTime),'hh:mm'),@LangCode) as ToTimeString,
