--[dbo].[SP_FE_UserCourseOwnedWithITemsWithPercentageForCoursePage] 2,'f5eb427c-026b-4aba-bbb7-97abacdf105a'
CREATE Proc [dbo].[SP_FE_UserCourseOwnedWithITemsWithPercentageForCoursePage] (@ItemTypeId bigint ,@UserId nvarchar(128))
as
SELECT DISTINCT   
dbo.GENItems.Id AS ItemId, 
dbo.GENItems.Description AS ItemDescription, dbo.GENItemFiles.AzureUri AS FileURL, dbo.GENItemVideos.AzureUri AS VideoURL, 
dbo.GENItems.IsActive as ItemActive,
dbo.GENItems.IsPublish as ItemPublish,
Assessments.[Id] AS AssessmentId ,Assessments.[DisplayOrder] AS AssessmentDisplayOrder ,Assessments.[Code] AS AssessmentCode ,Assessments.[Name] AS AssessmentName,
Assessments.[Description] AS AssessmentDescription ,Assessments.[DisplayOrdering]  AS AssessmentDisplayOrdering ,Assessments.[Image] AS AssessmentImage,
Assessments.[Video] AS AssessmentVideo ,Assessments.[Audio] AS AssessmentAudio ,Assessments.[File] AS AssessmentFile ,Assessments.[Time] AS AssessmentTime,
Assessments.[Weight] AS AssessmentWeight ,Assessments.[ActucalScore] AS AssessmentActualScore ,Assessments.[SuccessScore] AS AssessmentSuccessScore,
Assessments.[LanguageId] AS AssessmentLanguageId ,Assessments.[ExamType] AS AssessmentExamType, Assessments.[ExamType] as AssessmentExamTypeName,
dbo.FN_ProgressDone_Owned(GENContacts.Id, GENItems.Id, 3) AS IsSessionFinished,
CourseAssessment.[Id] AS CourseAssessmentId ,CourseAssessment.[DisplayOrder] AS CourseAssessmentDisplayOrder ,GENItems.ShortLink AS LinkScorm,
CourseAssessment.[Code] AS CourseAssessmentCode ,CourseAssessment.[Name] AS CourseAssessmentName,
CourseAssessment.[Description] AS CourseAssessmentDescription ,CourseAssessment.[DisplayOrdering]  AS CourseAssessmentDisplayOrdering ,
CourseAssessment.[Image] AS CourseAssessmentImage,
CourseAssessment.[Video] AS CourseAssessmentVideo ,CourseAssessment.[Audio] AS CourseAssessmentAudio ,CourseAssessment.[File] AS CourseAssessmentFile,
CourseAssessment.[Time] AS CourseAssessmentTime,
CourseAssessment.[Weight] AS CourseAssessmentWeight,CourseAssessment.[ActucalScore] AS CourseAssessmentActualScore ,
CourseAssessment.[SuccessScore] AS CourseAssessmentSuccessScore,
CourseAssessment.[LanguageId] AS CourseAssessmentLanguageId ,CourseAssessment.[ExamType] AS CourseAssessmentExamType, 
CourseAssessment.[ExamType]  CourseAssessmentExamTypeName,
CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount,
				(CASE WHEN GENContactProgressCompletionDetails.FirstVideoPlay = GENContactProgressCompletionDetails.TotalVideoDuration 
					AND GENContactProgressCompletionDetails.NextVideoPlay > 0
				THEN GENContactProgressCompletionDetails.NextVideoPlay ELSE GENContactProgressCompletionDetails.FirstVideoPlay END) AS CurrentVideoDuration, 
				GENContactProgressCompletionDetails.CompletionPercentage,
				(CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE ROUND(GENContactProgressCompletions.CompletionPercentage,2) END) AS SessionPercentage,
				GENContactProgressCompletionDetails.BaseEntityId AS DetailBaseEntityId,GENContactProgressCompletionDetails.EntityId AS DetailEntityId,
				dbo.GENTalents.Name  ProgramName,GENTalents.Id AS ProgramId
FROM dbo.GENItems 
LEFT JOIN  dbo.GENTypes ON dbo.GENItems.TypeId = dbo.GENTypes.Id 
inner join GENTalents_Generic ON GENTypes.Id =GENTalents_Generic.EntityId and  GENTalents_Generic.BaseEntityId=28
inner join GENTalents ON GENTalents_Generic.TalentId=GENTalents.Id
LEFT JOIN dbo.GENItemVideos ON dbo.GENItemVideos.ItemId = dbo.GENItems.Id 
LEFT JOIN dbo.GENItemFiles ON dbo.GENItems.Id = dbo.GENItemFiles.ItemId  and dbo.GENItemFiles.IsFolder=0
LEFT JOIN dbo.Contacts_Courses ON dbo.GENTypes.Id = dbo.Contacts_Courses.CourseId
LEFT JOIN dbo.GENContacts ON dbo.Contacts_Courses.StudentId = dbo.GENContacts.Id
LEFT JOIN [dbo].[GENExam_GENItem] ON [GENExam_GENItem].SessionId = dbo.GENItems.Id AND [GENExam_GENItem].IsActive = 1  
LEFT JOIN [dbo].[GENExam_GENType]  ON [GENExam_GENType].CourseId = dbo.GENTypes.Id AND [GENExam_GENType].IsActive = 1  
LEFT JOIN dbo.GENPollCategories Assessments ON [GENExam_GENItem].ExamId = Assessments.Id 
LEFT JOIN dbo.GENPollCategories CourseAssessment ON [GENExam_GENType].ExamId = CourseAssessment.Id 						 
LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
LEFT JOIN GENContactProgressCompletions ON dbo.GENItems.Id = GENContactProgressCompletions.EntityId AND GENContactProgressCompletions.BaseEntityId = 3 AND
						 GENContactProgressCompletions.CourseId = GENTypes.Id AND dbo.GENContacts.Id = GENContactProgressCompletions.ContactId LEFT JOIN
						 GENContactProgressCompletionDetails ON dbo.GENContactProgressCompletions.Id = GENContactProgressCompletionDetails.ContactProgressCompletionId AND 
						 ((GENContactProgressCompletionDetails.EntityId = GENItemVideos.Id AND GENContactProgressCompletionDetails.BaseEntityId = 181)
						 OR (GENContactProgressCompletionDetails.EntityId = GENItemFiles.Id AND GENContactProgressCompletionDetails.BaseEntityId = 182))
WHERE        (dbo.GENContacts.UserId = @UserId) and dbo.GENTypes.Id = @ItemTypeId AND (dbo.Contacts_Courses.CourseStatus = 4) AND (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2)
GROUP BY dbo.GENItems.Description, dbo.GENItems.Name, dbo.GENTypes.Description, dbo.GENTypes.Name, dbo.GENTypes.Id, dbo.GENItems.DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
dbo.GENItems.Id, dbo.GENItemFiles.AzureUri, dbo.GENItemVideos.AzureUri, dbo.GENItems.int1, 
dbo.GENTypes.int1,dbo.GENTypes.Int2,
dbo.GENItems.IsActive,dbo.GENItems.IsPublish,
GENItemFiles.LanguageId , dbo.GENItemVideos.LanguageId,dbo.GENItemVideos.Name,
GENItemFiles.FileName, dbo.GENItemVideos.Id, 
Assessments.[Id] ,Assessments.[DisplayOrder] ,Assessments.[Code],Assessments.[Name],
Assessments.[Description],Assessments.[DisplayOrdering],Assessments.[Image],
Assessments.[Video] ,Assessments.[Audio],Assessments.[File],Assessments.[Time],
Assessments.[Weight],Assessments.[ActucalScore],Assessments.[SuccessScore],
Assessments.[LanguageId],Assessments.[ExamType],
CourseAssessment.[Id] ,CourseAssessment.[DisplayOrder],
CourseAssessment.[Code],CourseAssessment.[Name],
CourseAssessment.[Description],CourseAssessment.[DisplayOrdering],
CourseAssessment.[Image],
CourseAssessment.[Video],CourseAssessment.[Audio],CourseAssessment.[File],
CourseAssessment.[Time],
CourseAssessment.[Weight],CourseAssessment.[ActucalScore],
CourseAssessment.[SuccessScore],
CourseAssessment.[LanguageId],CourseAssessment.[ExamType],GENContacts.Id,dbo.GENItems.int2,
GENItemFiles.Id,GENContactProgressCompletionDetails.FirstVideoPlay,
GENContactProgressCompletionDetails.TotalVideoDuration,
GENContactProgressCompletionDetails.NextVideoPlay,
GENContactProgressCompletionDetails.BaseEntityId,
GENContactProgressCompletionDetails.EntityId,
GENContactProgressCompletionDetails.CompletionPercentage,
GENContactProgressCompletions.CompletionPercentage,
GENTalents.name,GENTalents.id,GENItems.ShortLink
