Create Proc [dbo].[SP_FE_UserCourses_Current_Avaliable_Destinations] -- SP_FE_UserCourses_Current_Destinations N'd870812c-8ab3-4f97-b248-f2cffc7f0f84','ar',null
(@userId nvarchar(128) ,@LangCode nvarchar(500),@Id bigint= null)
as
WITH RecursiveCte AS
(
    SELECT  H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,H1.RichContent As Details,H1.Code AS String,H1.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H1.Id) as ImageCategory,H1.Description,IsNull(H1.ParentId,0) AS ParentId
	FROM GENTypeCategories H1
    WHERE H1.Id = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name ,H2.RichContent As Details,H2.Code AS String,H2.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H2.Id) as ImageCategory,H2.Description,IsNull(H2.ParentId,0) AS ParentId
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,
						 dbo.fn_ListValue_Translate_ByKeyandId(Field.Id,'Name',@LangCode ) AS FieldName, Field.Id AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId, GENClassrooms.Name AS ClassroomName, 
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			CAST((SUM((CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END)) / CAST((CASE WHEN COUNT(GENItems.Id) > 0 THEN COUNT(GENItems.Id) * 100 ELSE 1 END) AS decimal(18,2))) * 100 AS decimal(18,2) ) AS FinishedPercentge,dbo.GENTypes.Code AS CourseCode,dbo.GENClassrooms.Code AS ClassroomCode,
			dbo.GENTypes.Int1, dbo.GENTypes.Int2,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift
			,GENClassrooms.PaymentCondation,GENListValues.Name AS LangName,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
			,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,GENRooms.SeatsNumber,
			COUNT(GENClassroom_GENContact.Id) As CountStudentVcr
			,
			[dbo].[fnLastDate_Dest_VcrsByContactId](GENContacts.Id) AS LastVcrDate,
[dbo].[fnLastStatus_Dest_VcrsByContactId](GENContacts.Id) AS LastVcrStatus,
[dbo].[fnLastCourse_ByContactId](GENContacts.Id) AS LastCourse,
dbo.[fnLastCourseDate_ByContactId](GENContacts.Id) AS LastCourseDate,
						GENClassrooms.Name as VcrName,
--GENTypes.Name AS CourseName,
--GENTypes.Code AS CourseCode,
CASE
    WHEN ClassRoomStatus=0 THEN N'بدأت'
    WHEN ClassRoomStatus=1 THEN N'Dropped'
    WHEN ClassRoomStatus=2 THEN N'أنتهت'
	WHEN ClassRoomStatus=3 THEN N'مخططة'
    ELSE N'لا يوجد'
END As CourseStatus,[dbo].[AttendanceCall](GENContacts.Id,GENClassrooms.Id) AS AttenPercentage,GENClassrooms.Code AS VcrCode,dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudent,
DATEDIFF(day, GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) AS NumberOfDays ,GENClassrooms.Id as VcrId,
 GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,FORMAT(GENContacts.DateCreated,'dd/MM/yyyy') AS StudentCreated ,
count(GENClassrooms.Id) AS CountRegisterCourses ,GENContacts.IdNumber AS StudentNationalId,GENContacts.DefaultEmail,GENContacts.Position,GENContacts.DefaultPhone
,CASE
    WHEN GENClassroom_GENContact.BookingTypeId=0 THEN N'Requested'
    WHEN  GENClassroom_GENContact.BookingTypeId=1 THEN N'Confirmed'
    WHEN  GENClassroom_GENContact.BookingTypeId=2 THEN N'Rejected'
	WHEN  GENClassroom_GENContact.BookingTypeId=3 THEN N'Blocked'
	WHEN  GENClassroom_GENContact.BookingTypeId=4 THEN N'Canceled'
    WHEN  GENClassroom_GENContact.BookingTypeId=5 THEN N'Waiting'
	WHEN  GENClassroom_GENContact.BookingTypeId=6 THEN N'Added'
    ELSE N''
END As BookingType







FROM            dbo.GENTypes
left join RecursiveCte on GENTypes.TypeCategoryId = RecursiveCte.Id
 RIGHT OUTER JOIN    GENTypeCategories as Field ON GENTypes.TypeCategoryId =Field.Id RIGHT OUTER JOIN
                         dbo.GENClassroom_GENContact RIGHT OUTER JOIN
                         dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT OUTER JOIN
			dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
			LEFT JOIN Course_Session ON Course_Session.CourseId = GENTypes.Id
		  LEFT JOIN GENItems ON Course_Session.SessionId = GENItems.Id
		  LEFT JOIN GENRooms ON GENClassrooms.RoomId = GENRooms.Id
WHERE   dbo.GENClassrooms.isActive =1 AND GENClassrooms.IsDeleted=0 AND GENTypes.IsDeleted=0
--AND((FromDateTime <= GETDATE() AND ToDateTime >= GETDATE()))
and GENClassrooms.Date1<=GETDATE() and GENClassrooms.Date2>=GETDATE() 
and GENClassrooms.ClassRoomStatus<>2 and GENClassrooms.ClassRoomStatus<>1
and (GENRooms.SeatsNumber >= dbo.fn_VcrStudentCount(GENClassrooms.Id))
and (RecursiveCte.Id is not null or @Id is null) and (dbo.GENContacts.companyId = GENClassrooms.DestinationsId or dbo.GENContacts.OrganizationId = GENClassrooms.DestinationsId)

GROUP BY
dbo.GENTypes.Id,  dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.GENClassrooms.ToDateTime,
                         dbo.GENClassrooms.FromDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 , dbo.GENClassrooms.Id,Field.Name, Field.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENListValues.shortCode,dbo.GENClassrooms.Code,GENTypes.Code,dbo.GENTypes.Int1, dbo.GENTypes.Int2,
			GENClassrooms.Date1,GENClassrooms.Date2,GENClassrooms.ClassRoomShift,GENClassrooms.PaymentCondation,GENListValues.Name,GENRooms.SeatsNumber,
				GENTypes.Name,GENClassrooms.ClassRoomStatus,GENContacts.Id,GENContacts.Name,GENContacts.DefaultEmail,GENContacts.DefaultPhone,
			GENContacts.DateCreated,GENContacts.IDNumber,GENContacts.Position,GENClassroom_GENContact.BookingTypeId
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_UserCourses_Current_Destinations]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_FE_UserCourses_Current_Destinations] 
-- SP_FE_UserCourses_Current_Destinations N'd870812c-8ab3-4f97-b248-f2cffc7f0f84','ar',0,null,'01/01/2020','01/01/2026',null,null,null
(@userId nvarchar(128) ,@LangCode nvarchar(500),@available bit=null,@Id bigint= null,@FromCreate datetime=null,@ToCreate datetime=null,@status int=null, @shift int=null,@SearchString nvarchar(500)=null)
as

SELECT      dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', dbo.GENListValues.shortCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
						  DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime
                        ) AS RestDays, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 as CoueseHours, dbo.GENClassrooms.Id AS ClassroomId,
						 '' AS FieldName, null AS FieldId,
			GENEmployees.Name AS InstructorName, GENEmployees.Id AS InstructorId, GENClassrooms.Name AS ClassroomName, 
			CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount, 
			CAST((SUM((CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END)) / CAST((CASE WHEN COUNT(GENItems.Id) > 0 THEN COUNT(GENItems.Id) * 100 ELSE 1 END) AS decimal(18,2))) * 100 AS decimal(18,2) ) AS FinishedPercentge,dbo.GENTypes.Code AS CourseCode,dbo.GENClassrooms.Code AS ClassroomCode,
			dbo.GENTypes.Int1, dbo.GENTypes.Int2,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate
			,(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift
			,GENClassrooms.PaymentCondation,GENListValues.Name AS LangName,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays
			,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo
			,FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,GENRooms.SeatsNumber,
			COUNT(GENClassroom_GENContact.Id) As CountStudentVcr
			,
			[dbo].[fnLastDate_Dest_VcrsByContactId](GENContacts.Id) AS LastVcrDate,
[dbo].[fnLastStatus_Dest_VcrsByContactId](GENContacts.Id) AS LastVcrStatus,
[dbo].[fnLastCourse_ByContactId](GENContacts.Id) AS LastCourse,
dbo.[fnLastCourseDate_ByContactId](GENContacts.Id) AS LastCourseDate,
						GENClassrooms.Name as VcrName,
--GENTypes.Name AS CourseName,
--GENTypes.Code AS CourseCode,
CASE
    WHEN ClassRoomStatus=0 THEN N'بدأت'
    WHEN ClassRoomStatus=1 THEN N'Dropped'
    WHEN ClassRoomStatus=2 THEN N'أنتهت'
	WHEN ClassRoomStatus=3 THEN N'مخططة'
	WHEN ClassRoomStatus=4 THEN N'مفتوحة'
    ELSE N'لا يوجد'
END As CourseStatus,[dbo].[AttendanceCall](GENContacts.Id,GENClassrooms.Id) AS AttenPercentage,GENClassrooms.Code AS VcrCode,dbo.fn_VcrStudentCount(GENClassrooms.Id) AS CountStudent,
DATEDIFF(day, GENClassrooms.FromDateTime, GENClassrooms.ToDateTime) AS NumberOfDays ,GENClassrooms.Id as VcrId,
 GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,FORMAT(GENContacts.DateCreated,'dd/MM/yyyy') AS StudentCreated ,
dbo.getTotalVCRs(GENContacts.Id) AS CountRegisterCourses ,GENContacts.IdNumber AS StudentNationalId,GENContacts.DefaultEmail,GENContacts.Position,GENContacts.DefaultPhone
,CASE
    WHEN GENClassroom_GENContact.BookingTypeId=0 THEN N'Requested'
    WHEN  GENClassroom_GENContact.BookingTypeId=1 THEN N'Confirmed'
    WHEN  GENClassroom_GENContact.BookingTypeId=2 THEN N'Rejected'
	WHEN  GENClassroom_GENContact.BookingTypeId=3 THEN N'Blocked'
	WHEN  GENClassroom_GENContact.BookingTypeId=4 THEN N'Canceled'
    WHEN  GENClassroom_GENContact.BookingTypeId=5 THEN N'Waiting'
	WHEN  GENClassroom_GENContact.BookingTypeId=6 THEN N'Added'
    ELSE N''
END As BookingType
, GENClassroom_GENContact.BookingTypeId
,[dbo].fn_GetStudentVCRAttendance(GENContacts.Id,GENClassrooms.Id) as AttendanceNumber




FROM            dbo.GENTypes
LEFT JOIN dbo.GENClassrooms ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId 
						left JOIN dbo.GENClassroom_GENContact  ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id 
						 left  JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id 
						 --and 
						 --((select companyId from gencontacts where UserId=@UserId) =GENContacts.companyId))
						 LEFT OUTER JOIN dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
						 LEFT OUTER JOIN dbo.GENEmployees ON dbo.GENClassrooms.InstructorId = GENEmployees.Id 
			LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
			LEFT JOIN GENContactProgressCompletions on GENContactProgressCompletions.ClassroomId =  GENClassrooms.Id 
			AND GENContactProgressCompletions.ContactId = GENContacts.Id AND GENContactProgressCompletions.BaseEntityId = 3
			LEFT JOIN Course_Session ON Course_Session.CourseId = GENTypes.Id
		  LEFT JOIN GENItems ON Course_Session.SessionId = GENItems.Id
		  LEFT JOIN GENRooms ON GENClassrooms.RoomId = GENRooms.Id
WHERE 
dbo.GENClassrooms.isActive =1 
AND GENClassrooms.IsDeleted=0 
AND GENTypes.IsDeleted=0
AND((@available=1 and (FromDateTime <= GETDATE() AND ToDateTime >= GETDATE())) --current VCRs
or ((@available IS NULL OR @available=0)
and (GENClassrooms.Date1<=GETDATE() and GENClassrooms.Date2>=GETDATE())
) --Available VCRs
)
and GENClassrooms.ClassRoomStatus<>2 and GENClassrooms.ClassRoomStatus<>1

and (GENRooms.SeatsNumber >= dbo.fn_VcrStudentCount(GENClassrooms.Id))

and ((select companyId from gencontacts where UserId=@UserId) = GENClassrooms.DestinationsId or 
(select OrganizationId from gencontacts where UserId=@UserId) = GENClassrooms.DestinationsId)

and (@FromCreate IS null or @FromCreate='' or @FromCreate<=FromDateTime)
and (@ToCreate IS null or @ToCreate='' or DATEADD(Day, 1,@ToCreate)>=ToDateTime)
and (@status IS null or @status=-1 or @status=GENClassrooms.ClassRoomStatus)
and (@shift IS null or @shift=-1 or @shift=GENClassrooms.ClassRoomShift)
and (@SearchString IS null or @SearchString='' or GENClassrooms.Name like N'%'+@SearchString+'%' or GENClassrooms.Code like N'%'+@SearchString+'%' or GENTypes.Name like N'%'+@SearchString+'%')
GROUP BY
dbo.GENTypes.Id,  dbo.GENTypes.DisplayOrdering , dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, dbo.GENClassrooms.ToDateTime,
                         dbo.GENClassrooms.FromDateTime, dbo.GENClassroom_GENContact.IsConfirmed
						 ,dbo.GENTypes.int1 , dbo.GENClassrooms.Id,
			GENEmployees.Name, GENEmployees.Id, GENClassrooms.Name,dbo.GENListValues.shortCode,dbo.GENClassrooms.Code,GENTypes.Code,dbo.GENTypes.Int1, dbo.GENTypes.Int2,
			GENClassrooms.Date1,GENClassrooms.Date2,GENClassrooms.ClassRoomShift,GENClassrooms.PaymentCondation,GENListValues.Name,GENRooms.SeatsNumber,
				GENTypes.Name,GENClassrooms.ClassRoomStatus,GENContacts.Id,GENContacts.Name,GENContacts.DefaultEmail,GENContacts.DefaultPhone,
			GENContacts.DateCreated,GENContacts.IDNumber,GENContacts.Position,GENClassroom_GENContact.BookingTypeId
GO
