CREATE Proc [dbo].[SP_FE_UserPreviousCoursesCount] (@userId nvarchar(128))
as
SELECT      COUNT(DISTINCT dbo.GENTypes.Id)
FROM            dbo.GENTypes RIGHT OUTER JOIN
                         dbo.GENClassroom_GENContact RIGHT OUTER JOIN
                         dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId
						 LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id
WHERE        (dbo.GENContacts.UserId = @userId) and dbo.GENClassrooms.isActive =1 AND dbo.GENClassrooms.FromDateTime <= GETDATE() AND dbo.GENClassrooms.ToDateTime <= GETDATE()
