/****** Object:  StoredProcedure [dbo].[SP_FE_UserTalentTimeLine]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 14/06/2021
-- Description:	Get all the courses timeline for talents according to the contact
-- =============================================
CREATE PROCEDURE [dbo].[SP_FE_UserTalentTimeLine]
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT, @TalentId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select DISTINCT GENTypes.*,dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS MediaURL,
	dbo.fn_FirstVideo_BaseEntityEntityId(28, dbo.GENTypes.Id) AS VideoURL,
(CASE WHEN GENClassrooms.FromDateTime IS NULL 
--AND (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) 
THEN 
DATEADD(DAY, ISNULL(DepCourse.DurationDays,0), GENContact_Talent.DateCreated )
ELSE GENClassrooms.FromDateTime END) AS [StartDate],(CASE WHEN GENClassrooms.ToDateTime IS NULL 
--AND (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) 
THEN DATEADD(DAY, GENTalents_Generic.DurationDays + ISNULL(DepCourse.DurationDays,0) , GENContact_Talent.DateCreated )
ELSE GENClassrooms.ToDateTime END) AS [EndDate],
(CASE WHEN GENClassrooms.Id IS NOT NULL THEN 
CONCAT('/Account/SubscribedCourse/',GENTypes.Id)
 ELSE 
 CASE WHEN (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) AND Contacts_Courses.CourseStatus = 4 THEN
 CONCAT('/Account/SelfStudyCourse/', GENTypes.Id)
 ELSE 
 CONCAT('/Courses/Details/', GENTypes.Id) END
 END) AS CourseURL, GENTalents_Generic.PassScore, GENTalents_Generic.Mandatory,GENTalents_Generic.DisplayOrder, ExamHeaderResults.AnnouncedDegree,
 DepCourse.DepCount,GENTalents_Generic.TabAppearanceType
FROM GENContact_Talent
INNER JOIN GENContacts ON GENContact_Talent.ContactId = GENContacts.Id
INNER JOIN Contacts_Courses ON GENContacts.Id = Contacts_Courses.StudentId
INNER JOIN GENTalents ON Contacts_Courses.TalentId = GENTalents.Id
INNER JOIN GENTypes ON Contacts_Courses.CourseId = GENTypes.Id
INNER JOIN GENTalents_Generic ON GENContact_Talent.TalentId = GENTalents_Generic.TalentId AND GENTalents_Generic.EntityId = GENTypes.Id AND GENTalents_Generic.BaseEntityId = 28
LEFT JOIN GENClassrooms ON GENClassrooms.Id = Contacts_Courses.ClassRoomId
LEFT JOIN ExamHeaderResults ON GENClassrooms.ExamId = ExamHeaderResults.ExamId AND GENClassrooms.Id = ExamHeaderResults.ClassroomId AND 
ExamHeaderResults.StudentId = GENContacts.Id
OUTER APPLY (SELECT DISTINCT GENTalents_Generic.TalentId, SUM(GENTalents_Generic.DurationDays) AS DurationDays, COUNT(GENType_Course.DependencyCourseId) AS DepCount FROM GENType_Course 
INNER JOIN GENTalents_Generic ON GENType_Course.MainCourseId = GENTalents_Generic.EntityId AND GENTalents_Generic.BaseEntityId = 28
INNER JOIN GENTypes Dep ON GENType_Course.DependencyCourseId = Dep.Id
Where MainCourseId = GENTypes.Id
GROUP BY GENTalents_Generic.TalentId) DepCourse
WHERE GENContact_Talent.ContactId = @ContactId and Contacts_Courses.TalentId = @TalentId
ORDER BY GENTalents_Generic.DisplayOrder
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_UserTalentTimeLineWithPercentage]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_FE_UserTalentTimeLineWithPercentage] --42,1,'ar'
	-- Add the parameters for the stored procedure here
	@ContactId BIGINT, @TalentId BIGINT,@LangCode nvarchar(500)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select DISTINCT GENTypes.Id,dbo.fn_Type_Translate_ByKeyandId(GENTypes.Id,'Name',@LangCode) AS Name,
	GENTypes.Description,GENTypes.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS MediaURL,
	dbo.fn_FirstVideo_BaseEntityEntityId(28, dbo.GENTypes.Id) AS VideoURL,
(CASE WHEN GENClassrooms.FromDateTime IS NULL 
--AND (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) 
THEN 
DATEADD(DAY, ISNULL(DepCourse.DurationDays,0), GENContact_Talent.DateCreated )
ELSE GENClassrooms.FromDateTime END) AS [StartDate],(CASE WHEN GENClassrooms.ToDateTime IS NULL 
--AND (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) 
THEN DATEADD(DAY, GENTalents_Generic.DurationDays + ISNULL(DepCourse.DurationDays,0) , GENContact_Talent.DateCreated )
ELSE GENClassrooms.ToDateTime END) AS [EndDate],
(CASE WHEN GENClassrooms.Id IS NOT NULL THEN 
CONCAT('/Account/SubscribedCourse/',GENTypes.Id)
 ELSE 
 CASE WHEN (GENTypes.CourseType = 1 OR GENTypes.CourseType = 2) AND Contacts_Courses.CourseStatus = 4 THEN
 CONCAT('/Account/SelfStudyCourse/', GENTypes.Id)
 ELSE 
 CONCAT('/Courses/Details/', GENTypes.Id) END
 END) AS CourseURL, GENTalents_Generic.PassScore, GENTalents_Generic.Mandatory,GENTalents_Generic.DisplayOrder, ExamHeaderResults.AnnouncedDegree,
 DepCourse.DepCount,GENTalents_Generic.TabAppearanceType,
-- SUM(GENContactProgressCompletions.CompletionPercentage) AS MainPercentage
cast((CASE WHEN (((SUM(GENContactProgressCompletions.CompletionPercentage)) /(COUNT( GENItems.Id) * 100))*100) IS NULL THEN 0 
ELSE (((SUM(GENContactProgressCompletions.CompletionPercentage)) /(COUNT( GENItems.Id) * 100))*100) END) as decimal(18,2)) AS MainPercentage,
(CASE WHEN (((SUM(GENContactProgressCompletions.CompletionPercentage)) /(COUNT( GENItems.Id) * 100))*100) = 100 THEN 'bg-success' ELSE
CASE WHEN (((SUM(GENContactProgressCompletions.CompletionPercentage)) /(COUNT( GENItems.Id) * 100))*100) >= 50 THEN 'bg-warning' ELSE 'bg-danger' END END) AS PercentageColor,
(GENTalents.DurationDays - DATEDIFF(DAy,GENContact_Talent.DateCreated,getdate())) AS RemainingTime
FROM GENTalents_Generic 
INNER JOIN GENTalents ON GENTalents_Generic.TalentId = GENTalents.Id
INNER JOIN GENContact_Talent ON GENContact_Talent.TalentId = GENTalents_Generic.TalentId
INNER JOIN GENContacts ON GENContact_Talent.ContactId = GENContacts.Id
INNER JOIN GENTypes ON GENTalents_Generic.EntityId = GENTypes.Id AND GENTalents_Generic.BaseEntityId = 28
LEFT JOIN Contacts_Courses ON GENContacts.Id = Contacts_Courses.StudentId AND Contacts_Courses.CourseId = GENTypes.Id
LEFT JOIN GENClassrooms ON GENClassrooms.Id = Contacts_Courses.ClassRoomId
LEFT JOIN ExamHeaderResults ON GENClassrooms.ExamId = ExamHeaderResults.ExamId AND GENClassrooms.Id = ExamHeaderResults.ClassroomId AND 
ExamHeaderResults.StudentId = GENContacts.Id
	LEFT JOIN Course_Session ON GENTypes.Id=Course_Session.CourseId
LEFT JOIN dbo.GENItems ON Course_Session.SessionId = GENItems.Id and (dbo.GENItems.IsDeleted = 0 or dbo.GENItems.IsDeleted is null) and dbo.GENItems.IsActive = 1 and dbo.GENItems.IsPublish = 1
LEFT JOIN dbo.GENItemVideos ON dbo.GENItemVideos.ItemId = dbo.GENItems.Id 
LEFT JOIN dbo.GENItemFiles ON dbo.GENItems.Id = dbo.GENItemFiles.ItemId and IsFolder = 0
LEFT JOIN GENContactProgressCompletions ON dbo.GENItems.Id = GENContactProgressCompletions.EntityId AND GENContactProgressCompletions.BaseEntityId = dbo.FN_GetBaseEntityIdByName('GENItem')
						AND dbo.GENContacts.Id = GENContactProgressCompletions.ContactId AND
						 (GENContactProgressCompletions.CourseId = GENTypes.Id OR GENContactProgressCompletions.ClassroomId = GENClassrooms.Id)
LEFT JOIN GENContactProgressCompletionDetails ON dbo.GENContactProgressCompletions.Id = GENContactProgressCompletionDetails.ContactProgressCompletionId AND 
						 ((GENContactProgressCompletionDetails.EntityId = GENItemVideos.Id AND GENContactProgressCompletionDetails.BaseEntityId = dbo.FN_GetBaseEntityIdByName('GENItemVideos'))
						 OR (GENContactProgressCompletionDetails.EntityId = GENItemFiles.Id AND GENContactProgressCompletionDetails.BaseEntityId = dbo.FN_GetBaseEntityIdByName('GENItemFiles')))
OUTER APPLY (SELECT DISTINCT GENTalents_Generic.TalentId, SUM(GENTalents_Generic.DurationDays) AS DurationDays, COUNT(GENType_Course.DependencyCourseId) AS DepCount FROM GENType_Course 
INNER JOIN GENTalents_Generic ON GENType_Course.MainCourseId = GENTalents_Generic.EntityId AND GENTalents_Generic.BaseEntityId = 28
INNER JOIN GENTypes Dep ON GENType_Course.DependencyCourseId = Dep.Id
Where MainCourseId = GENTypes.Id
GROUP BY GENTalents_Generic.TalentId) DepCourse
WHERE GENContacts.Id = @ContactId and GENTalents.Id = @TalentId
GROUP BY GENTypes.Id,GENTypes.Name,GENTypes.Description,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENClassrooms.Id
,GENTalents_Generic.PassScore, GENTalents_Generic.Mandatory,GENTalents_Generic.DisplayOrder, ExamHeaderResults.AnnouncedDegree,
 DepCourse.DepCount,GENTalents_Generic.TabAppearanceType,DepCourse.DurationDays,GENContact_Talent.DateCreated,
 GENTalents_Generic.DurationDays,GENTypes.CourseType,Contacts_Courses.CourseStatus,GENTypes.DisplayOrdering,GENTalents.DurationDays
ORDER BY GENTypes.DisplayOrdering desc
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FE_UserVCRCourseWithITemsWithPercentage]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
