				cast(182 as bigint) AS FileBaseEntityId,cast(181 as bigint) AS VideoBaseEntityId,
				(CASE WHEN GENContactProgressCompletions.CompletionPercentage = 100 THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END) AS IsSessionFinished,
				CourseAssessment.[Id] AS CourseAssessmentId ,CourseAssessment.[DisplayOrder] AS CourseAssessmentDisplayOrder ,
				 CourseAssessment.[Code] AS CourseAssessmentCode ,CourseAssessment.[Name] AS CourseAssessmentName
				,CourseAssessment.[Description] AS CourseAssessmentDescription ,CourseAssessment.[DisplayOrdering]  AS CourseAssessmentDisplayOrdering ,
					CourseAssessment.[Image] AS CourseAssessmentImage
				,CourseAssessment.[Video] AS CourseAssessmentVideo ,CourseAssessment.[Audio] AS CourseAssessmentAudio ,CourseAssessment.[File] AS CourseAssessmentFile 
				,CourseAssessment.[Time] AS CourseAssessmentTime
				,CourseAssessment.[Weight] AS CourseAssessmentWeight,CourseAssessment.[ActucalScore] AS CourseAssessmentActualScore ,
				CourseAssessment.[SuccessScore] AS CourseAssessmentSuccessScore
				,CourseAssessment.[LanguageId] AS CourseAssessmentLanguageId ,CourseAssessment.[ExamType] AS CourseAssessmentExamType, 
				dbo.FN_GetExamType(CourseAssessment.[ExamType],@LangCode) AS CourseAssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS CourseAssessmentDateTime,
				(CASE WHEN GENContactProgressCompletionDetails.FirstVideoPlay = GENContactProgressCompletionDetails.TotalVideoDuration 
					AND GENContactProgressCompletionDetails.NextVideoPlay > 0
				THEN GENContactProgressCompletionDetails.NextVideoPlay ELSE GENContactProgressCompletionDetails.FirstVideoPlay END) AS CurrentVideoDuration, 
				GENContactProgressCompletionDetails.CompletionPercentage,
				(CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END) AS SessionPercentage,
				GENContactProgressCompletionDetails.BaseEntityId AS DetailBaseEntityId,GENContactProgressCompletionDetails.EntityId AS DetailEntityId,

				 Folders.Id AS FolderId,Folders.FolderName AS FolderName,Folders.AzureUri AS FoldersURI,TLMSClassroom_Session.SessionDateTime AS SessionDate,
				  FORMAT( TLMSClassroom_Session.FromDateTime, 'HH:mm') AS SessionFromTime, FORMAT( TLMSClassroom_Session.ToDateTime, 'HH:mm') AS SessionToTime,
				  TLMSClassroom_Session.Id AS EmpSesId ,GENEmployees.Name AS EmsessName,GENEmployees.Id AS EmsessId
FROM           dbo.GENClassrooms WITH(NOLOCK)   
LEFT JOIN dbo.GENPollCategories ON dbo.GENPollCategories.Id = dbo.GENClassrooms.ExamId inner JOIN
						 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT JOIN
						 Course_Session ON Course_Session.CourseId = GENTypes.Id   LEFT JOIN
						 TLMSClassroom_Session ON Course_Session.SessionId=TLMSClassroom_Session.SessionId Left join 
						 Classroom_Session_Instructor on TLMSClassroom_Session.Id = Classroom_Session_Instructor.SessionId Left join
						  GENEmployees ON Classroom_Session_Instructor.InstructorId=GENEmployees.Id Left join
						 dbo.GENItems  ON TLMSClassroom_Session.SessionId = dbo.GENItems.Id and  dbo.GENItems.IsDeleted=0  and TLMSClassroom_Session.ClassroomId = GENClassrooms.Id   LEFT JOIN
                         dbo.GENItemVideos ON dbo.GENItemVideos.ItemId = dbo.GENItems.Id LEFT JOIN
                         dbo.GENItemFiles ON dbo.GENItems.Id = dbo.GENItemFiles.ItemId and dbo.GENItemFiles.IsFolder=0 
						 AND (dbo.GENItemFiles.LanguageId = @Langid OR @Langid IS NULL OR dbo.GENItemFiles.LanguageId IS NULL)
						 LEFT JOIN dbo.GENItemFiles Folders ON dbo.GENItems.Id = Folders.ItemId  and Folders.IsFolder=1 and  Folders.Name like '%Story%'
						 inner JOIN dbo.GENClassroom_GENContact 
						 inner JOIN dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id ON dbo.GENClassrooms.Id = dbo.GENClassroom_GENContact.ClassroomId LEFT JOIN
						 GENContactProgressCompletions ON dbo.GENItems.Id = GENContactProgressCompletions.EntityId AND GENContactProgressCompletions.BaseEntityId = 3 AND
						 GENContactProgressCompletions.ClassroomId = GENClassrooms.Id AND dbo.GENContacts.Id = GENContactProgressCompletions.ContactId LEFT JOIN
						 GENContactProgressCompletionDetails ON dbo.GENContactProgressCompletions.Id = GENContactProgressCompletionDetails.ContactProgressCompletionId AND 
						 ((GENContactProgressCompletionDetails.EntityId = GENItemVideos.Id AND GENContactProgressCompletionDetails.BaseEntityId = 181)
						 OR (GENContactProgressCompletionDetails.EntityId = GENItemFiles.Id AND GENContactProgressCompletionDetails.BaseEntityId = 182)) LEFT JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT JOIN
						 [dbo].[GENExam_GENItem] ON [GENExam_GENItem].SessionId = dbo.GENItems.Id AND [GENExam_GENItem].IsActive = 1  LEFT JOIN
						 [dbo].[GENExam_GENType]  ON [GENExam_GENType].CourseId = dbo.GENTypes.Id AND [GENExam_GENType].IsActive = 1  LEFT JOIN
						 dbo.GENPollCategories Assessments ON [GENExam_GENItem].ExamId = Assessments.Id LEFT JOIN
						 [dbo].[GENExam_GENClassroom] ON [GENExam_GENClassroom].ClassroomId = dbo.GENClassrooms.Id AND [GENExam_GENClassroom].IsActive = 1 LEFT JOIN
						 --AND [GENExam_GENClassroom].DisplayDateTime < GETDATE() LEFT JOIN
						 dbo.GENPollCategories ClassroomAssessments ON [GENExam_GENClassroom].ExamId = ClassroomAssessments.Id LEFT JOIN
						 dbo.GENPollCategories CourseAssessment ON [GENExam_GENType].ExamId = CourseAssessment.Id 
WHERE        (dbo.GENContacts.UserId = @UserId) and dbo.GENTypes.Id = @ItemTypeId and GENClassrooms.Id=@ClassId
GO
