                    (CASE WHEN dbo.GENPollCategories.IsActive IS NULL THEN CAST(0 AS BIT) ELSE dbo.GENPollCategories.IsActive END) AS ExamActive, (CASE WHEN dbo.GENPollCategories.IsActive IS NULL THEN CAST(0 AS BIT) ELSE dbo.GENPollCategories.IsActive END) AS IsPosted ,iif(dbo.GENItems.int1 is null,0,dbo.GENItems.int1) as LectureHourse, iif(dbo.GENTypes.int1 is null,0,dbo.GENTypes.int1) as CoueseHours,
