				[GENExam_GENClassroom].DisplayDateTime AS ClassroomAssessmentDateTime,
				cast(3 as bigint)AS ItemBaseEntityId,cast(176 as bigint)AS ClassroomBaseEntityId,
				cast(129 as bigint)AS ExamBaseEntityId,cast(28 as bigint) AS CourseBaseEntityId,
