				,CourseAssessment.[Description] AS CourseAssessmentDescription ,CourseAssessment.[DisplayOrdering]  AS CourseAssessmentDisplayOrdering ,
					CourseAssessment.[Image] AS CourseAssessmentImage
				,CourseAssessment.[Video] AS CourseAssessmentVideo ,CourseAssessment.[Audio] AS CourseAssessmentAudio ,CourseAssessment.[File] AS CourseAssessmentFile 
				,CourseAssessment.[Time] AS CourseAssessmentTime
				,CourseAssessment.[Weight] AS CourseAssessmentWeight,CourseAssessment.[ActucalScore] AS CourseAssessmentActualScore ,
				CourseAssessment.[SuccessScore] AS CourseAssessmentSuccessScore
				,CourseAssessment.[LanguageId] AS CourseAssessmentLanguageId ,CourseAssessment.[ExamType] AS CourseAssessmentExamType, 
				dbo.FN_GetExamType(CourseAssessment.[ExamType],@LangCode) AS CourseAssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS CourseAssessmentDateTime,
				(CASE WHEN GENContactProgressCompletionDetails.FirstVideoPlay = GENContactProgressCompletionDetails.TotalVideoDuration 
					AND GENContactProgressCompletionDetails.NextVideoPlay > 0
				THEN GENContactProgressCompletionDetails.NextVideoPlay ELSE GENContactProgressCompletionDetails.FirstVideoPlay END) AS CurrentVideoDuration, 
				GENContactProgressCompletionDetails.CompletionPercentage,
				(CASE WHEN GENContactProgressCompletions.CompletionPercentage IS NULL THEN  0 ELSE GENContactProgressCompletions.CompletionPercentage END) AS SessionPercentage,
				GENContactProgressCompletionDetails.BaseEntityId AS DetailBaseEntityId,GENContactProgressCompletionDetails.EntityId AS DetailEntityId,

				 null AS FolderId,null AS FolderName,null AS FoldersURI,TLMSClassroom_Session.SessionDateTime AS SessionDate,
				  FORMAT( TLMSClassroom_Session.FromDateTime, 'HH:mm') AS SessionFromTime, FORMAT( TLMSClassroom_Session.ToDateTime, 'HH:mm') AS SessionToTime,
				  TLMSClassroom_Session.Id AS EmpSesId ,GENEmployees.Name AS EmsessName
FROM           dbo.GENClassrooms
inner  JOIN dbo.GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId =  dbo.GENClassrooms.Id
inner join  dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id and dbo.GENClassrooms.Id = dbo.GENClassroom_GENContact.ClassroomId
 LEFT JOIN   dbo.GENPollCategories ON dbo.GENPollCategories.Id = dbo.GENClassrooms.ExamId LEFT JOIN
						 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT JOIN
						 Course_Session ON Course_Session.CourseId = GENTypes.Id  LEFT JOIN
						 TLMSClassroom_Session ON Course_Session.SessionId=TLMSClassroom_Session.SessionId Left join
						  GENEmployees ON TLMSClassroom_Session.InstructorId=GENEmployees.Id Left join

						 dbo.GENItems  ON TLMSClassroom_Session.SessionId = dbo.GENItems.Id and  dbo.GENItems.IsDeleted=0  
						 and TLMSClassroom_Session.ClassroomId = GENClassrooms.Id LEFT JOIN

                         dbo.GENItemFiles ON dbo.GENItems.Id = dbo.GENItemFiles.ItemId and dbo.GENItemFiles.IsFolder=0 
						 
						 LEFT JOIN GENContactProgressCompletions ON dbo.GENItems.Id = GENContactProgressCompletions.EntityId AND GENContactProgressCompletions.BaseEntityId = 3 AND
						 GENContactProgressCompletions.ClassroomId = GENClassrooms.Id AND dbo.GENContacts.Id = GENContactProgressCompletions.ContactId
						 LEFT JOIN GENContactProgressCompletionDetails ON dbo.GENContactProgressCompletions.Id = GENContactProgressCompletionDetails.ContactProgressCompletionId AND 
						 ((GENContactProgressCompletionDetails.EntityId = GENItemFiles.Id AND GENContactProgressCompletionDetails.BaseEntityId = 182)) LEFT JOIN

                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
						 LEFT JOIN [dbo].[GENExam_GENItem] ON [GENExam_GENItem].SessionId = dbo.GENItems.Id AND [GENExam_GENItem].IsActive = 1  LEFT JOIN
						 [dbo].[GENExam_GENType]  ON [GENExam_GENType].CourseId = dbo.GENTypes.Id AND [GENExam_GENType].IsActive = 1  LEFT JOIN
						 dbo.GENPollCategories Assessments ON [GENExam_GENItem].ExamId = Assessments.Id LEFT JOIN
						 [dbo].[GENExam_GENClassroom] ON [GENExam_GENClassroom].ClassroomId = dbo.GENClassrooms.Id AND [GENExam_GENClassroom].IsActive = 1 LEFT JOIN
						 --AND [GENExam_GENClassroom].DisplayDateTime < GETDATE() LEFT JOIN
						 dbo.GENPollCategories ClassroomAssessments ON [GENExam_GENClassroom].ExamId = ClassroomAssessments.Id LEFT JOIN
						 dbo.GENPollCategories CourseAssessment ON [GENExam_GENType].ExamId = CourseAssessment.Id 
WHERE        (dbo.GENContacts.UserId = @UserId) and dbo.GENTypes.Id = @ItemTypeId and GENClassrooms.Id=@ClassId  and GENClassrooms.ProsecutionId=1

union all 
 SELECT DISTINCT dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, CAST (dbo.GENItems.DisplayOrder AS INT ) AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                    dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
					 DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.ExamId, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, 
                    dbo.GENClassrooms.InteractiveMeetingURL, dbo.fn_Type_Translate_ByKeyandId(  dbo.GENClassrooms.Id,'InstructorInstructions',@LangCode)AS InstructorInstructions, dbo.GENClassrooms.ExamStartTime, dbo.GENClassrooms.ExamEndTime, dbo.GENClassrooms.InteractiveMeetingDateTime, 
                    dbo.GENItems.Id AS ItemId,dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Name' ,@LangCode) AS ItemName, 
					dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Description', @LangCode)  AS ItemDescription, null AS FileURL, null AS VideoURL, 
                    (CASE WHEN dbo.GENPollCategories.IsActive IS NULL THEN CAST(0 AS BIT) ELSE dbo.GENPollCategories.IsActive END) AS ExamActive, (CASE WHEN dbo.GENPollCategories.IsActive IS NULL THEN CAST(0 AS BIT) ELSE dbo.GENPollCategories.IsActive END) AS IsPosted ,iif(dbo.GENItems.int1 is null,0,dbo.GENItems.int1) as LectureHourse, iif(dbo.GENTypes.int1 is null,0,dbo.GENTypes.int1) as CoueseHours,
					 iif(dbo.GENTypes.Int2 is null,0,dbo.GENTypes.Int2) as CourseMinutes,
					dbo.GENItems.IsActive as ItemActive,dbo.GENItems.IsPublish as ItemPublish	 ,iif(dbo.GENItems.int2 is null,0,dbo.GENItems.int2) as TableDisplayOrder,dbo.GENClassrooms.Id as ClassRoomId,
					dbo.GENClassrooms.LanguageId as ClassRoomLanguageId ,null as FileLanguageId , null as VideoLanguageId,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'RichContent', @LangCode) AS RichContent,null AS VideoName,
					null AS FileName, null AS FileId, dbo.GENPollCategories.Name AS ExamName,null AS VideoId,  GENItems.ShortLink AS LinkScorm,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String1', @LangCode)  AS CourseString1,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String2', @LangCode)  AS CourseString2, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String3', @LangCode)  AS CourseString3, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String4', @LangCode)  AS CourseString4, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String5', @LangCode)  AS CourseString5,
					Assessments.[Id] AS AssessmentId ,Assessments.[DisplayOrder] AS AssessmentDisplayOrder ,Assessments.[Code] AS AssessmentCode ,Assessments.[Name] AS AssessmentName
				,Assessments.[Description] AS AssessmentDescription ,Assessments.[DisplayOrdering]  AS AssessmentDisplayOrdering ,Assessments.[Image] AS AssessmentImage
				,Assessments.[Video] AS AssessmentVideo ,Assessments.[Audio] AS AssessmentAudio ,Assessments.[File] AS AssessmentFile ,Assessments.[Time] AS AssessmentTime
				,Assessments.[Weight] AS AssessmentWeight ,Assessments.[ActucalScore] AS AssessmentActualScore ,Assessments.[SuccessScore] AS AssessmentSuccessScore
				,Assessments.[LanguageId] AS AssessmentLanguageId ,Assessments.[ExamType] AS AssessmentExamType,dbo.FN_GetExamType(Assessments.[ExamType],@LangCode) AS AssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS AssessmentDateTime,
				 ClassroomAssessments.[Id] AS ClassroomAssessmentId ,ClassroomAssessments.[DisplayOrder] AS ClassroomAssessmentDisplayOrder ,
				 ClassroomAssessments.[Code] AS ClassroomAssessmentCode ,ClassroomAssessments.[Name] AS ClassroomAssessmentName
				,ClassroomAssessments.[Description] AS ClassroomAssessmentDescription ,ClassroomAssessments.[DisplayOrdering]  AS ClassroomAssessmentDisplayOrdering ,
				ClassroomAssessments.[Image] AS ClassroomAssessmentImage
				,ClassroomAssessments.[Video] AS ClassroomAssessmentVideo ,ClassroomAssessments.[Audio] AS ClassroomAssessmentAudio ,ClassroomAssessments.[File] AS ClassroomAssessmentFile 
				,ClassroomAssessments.[Time] AS ClassroomAssessmentTime
				,ClassroomAssessments.[Weight] AS ClassroomAssessmentWeight,ClassroomAssessments.[ActucalScore] AS ClassroomAssessmentActualScore ,
				ClassroomAssessments.[SuccessScore] AS ClassroomAssessmentSuccessScore
				,ClassroomAssessments.[LanguageId] AS ClassroomAssessmentLanguageId ,ClassroomAssessments.[ExamType] AS ClassroomAssessmentExamType, 
				dbo.FN_GetExamType(ClassroomAssessments.[ExamType],@LangCode) AS ClassroomAssessmentsExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS ClassroomAssessmentDateTime,
				cast(3 as bigint)AS ItemBaseEntityId,cast(176 as bigint)AS ClassroomBaseEntityId,
				cast(129 as bigint)AS ExamBaseEntityId,cast(28 as bigint) AS CourseBaseEntityId,
				cast(182 as bigint) AS FileBaseEntityId,cast(181 as bigint)  AS VideoBaseEntityId,CAST(0 AS BIT) AS IsSessionFinished,
				CourseAssessment.[Id] AS CourseAssessmentId ,CourseAssessment.[DisplayOrder] AS CourseAssessmentDisplayOrder ,
				 CourseAssessment.[Code] AS CourseAssessmentCode ,CourseAssessment.[Name] AS CourseAssessmentName
				,CourseAssessment.[Description] AS CourseAssessmentDescription ,CourseAssessment.[DisplayOrdering]  AS CourseAssessmentDisplayOrdering ,
					CourseAssessment.[Image] AS CourseAssessmentImage
				,CourseAssessment.[Video] AS CourseAssessmentVideo ,CourseAssessment.[Audio] AS CourseAssessmentAudio ,CourseAssessment.[File] AS CourseAssessmentFile 
				,CourseAssessment.[Time] AS CourseAssessmentTime
				,CourseAssessment.[Weight] AS CourseAssessmentWeight,CourseAssessment.[ActucalScore] AS CourseAssessmentActualScore ,
				CourseAssessment.[SuccessScore] AS CourseAssessmentSuccessScore
				,CourseAssessment.[LanguageId] AS CourseAssessmentLanguageId ,CourseAssessment.[ExamType] AS CourseAssessmentExamType, 
				dbo.FN_GetExamType(CourseAssessment.[ExamType],@LangCode) AS CourseAssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS CourseAssessmentDateTime,null AS CurrentVideoDuration, 
				null as CompletionPercentage,0 AS SessionPercentage,
				null AS DetailBaseEntityId,null AS DetailEntityId,

				 Folders.Id AS FolderId,Folders.FolderName AS FolderName,Folders.AzureUri AS FoldersURI,TLMSClassroom_Session.SessionDateTime AS SessionDate,
				  FORMAT( TLMSClassroom_Session.FromDateTime, 'HH:mm') AS SessionFromTime, FORMAT( TLMSClassroom_Session.ToDateTime, 'HH:mm') AS SessionToTime,
				  TLMSClassroom_Session.Id AS EmpSesId ,GENEmployees.Name AS EmsessName
FROM           dbo.GENClassrooms WITH(NOLOCK) 
inner  JOIN dbo.GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId =  dbo.GENClassrooms.Id
inner join  dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id and dbo.GENClassrooms.Id = dbo.GENClassroom_GENContact.ClassroomId
 LEFT JOIN   dbo.GENPollCategories ON dbo.GENPollCategories.Id = dbo.GENClassrooms.ExamId LEFT JOIN
						 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT JOIN
						 Course_Session ON Course_Session.CourseId = GENTypes.Id  LEFT JOIN
						 TLMSClassroom_Session ON Course_Session.SessionId=TLMSClassroom_Session.SessionId Left join
						  GENEmployees ON TLMSClassroom_Session.InstructorId=GENEmployees.Id Left join

						 dbo.GENItems  ON TLMSClassroom_Session.SessionId = dbo.GENItems.Id and  dbo.GENItems.IsDeleted=0  
						 and TLMSClassroom_Session.ClassroomId = GENClassrooms.Id 
						 LEFT JOIN dbo.GENItemFiles Folders ON dbo.GENItems.Id = Folders.ItemId  and Folders.IsFolder=1 and  Folders.Name like '%Story%'
						  LEFT JOIN  dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id 
						 LEFT JOIN [dbo].[GENExam_GENItem] ON [GENExam_GENItem].SessionId = dbo.GENItems.Id AND [GENExam_GENItem].IsActive = 1  LEFT JOIN
						 [dbo].[GENExam_GENType]  ON [GENExam_GENType].CourseId = dbo.GENTypes.Id AND [GENExam_GENType].IsActive = 1  LEFT JOIN
						 dbo.GENPollCategories Assessments ON [GENExam_GENItem].ExamId = Assessments.Id LEFT JOIN
						 [dbo].[GENExam_GENClassroom] ON [GENExam_GENClassroom].ClassroomId = dbo.GENClassrooms.Id AND [GENExam_GENClassroom].IsActive = 1 LEFT JOIN
						 --AND [GENExam_GENClassroom].DisplayDateTime < GETDATE() LEFT JOIN
						 dbo.GENPollCategories ClassroomAssessments ON [GENExam_GENClassroom].ExamId = ClassroomAssessments.Id LEFT JOIN
						 dbo.GENPollCategories CourseAssessment ON [GENExam_GENType].ExamId = CourseAssessment.Id 
WHERE        (dbo.GENContacts.UserId = @UserId) and dbo.GENTypes.Id = @ItemTypeId and GENClassrooms.Id=@ClassId  and GENClassrooms.ProsecutionId=1
GO
/****** Object:  StoredProcedure [dbo].[SP_FEUserCourseWithITems]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_FEUserCourseWithITems](@ItemTypeId bigint ,@UserId nvarchar(128) ,@LangCode nvarchar(500))
as

DECLARE @Langid BIGINT = NULL
SELECT @Langid = Id FROM GENListValues WHERE ShortCode = @LangCode
    SELECT DISTINCT dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode) AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, CAST (dbo.GENItems.DisplayOrder AS INT ) AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                    dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount,
					 DATEDIFF(day, getdate(),dbo.GENClassrooms.ToDateTime) AS RestDays, dbo.GENClassrooms.InstructorId, dbo.GENClassrooms.ExamId, dbo.GENClassrooms.FromDateTime, dbo.GENClassrooms.ToDateTime, 
                    dbo.GENClassrooms.InteractiveMeetingURL, dbo.fn_Type_Translate_ByKeyandId(  dbo.GENClassrooms.Id,'InstructorInstructions',@LangCode)AS InstructorInstructions, dbo.GENClassrooms.ExamStartTime, dbo.GENClassrooms.ExamEndTime, dbo.GENClassrooms.InteractiveMeetingDateTime, 
                    dbo.GENItems.Id AS ItemId,dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Name' ,@LangCode) AS ItemName, 
					dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Description', @LangCode)  AS ItemDescription, dbo.GENItemFiles.AzureUri AS FileURL, dbo.GENItemVideos.AzureUri AS VideoURL, 
                    dbo.GENPollCategories.IsActive AS ExamActive, dbo.GENPollCategories.IsPosted ,iif(dbo.GENItems.int1 is null,0,dbo.GENItems.int1) as LectureHourse, iif(dbo.GENTypes.int1 is null,0,dbo.GENTypes.int1) as CoueseHours,
					 iif(dbo.GENTypes.Int2 is null,0,dbo.GENTypes.Int2) as CourseMinutes,
					dbo.GENItems.IsActive as ItemActive,dbo.GENItems.IsPublish as ItemPublish	 ,iif(dbo.GENItems.int2 is null,0,dbo.GENItems.int2) as TableDisplayOrder,dbo.GENClassrooms.Id as ClassRoomId,
					dbo.GENClassrooms.LanguageId as ClassRoomLanguageId ,GENItemFiles.LanguageId as FileLanguageId , dbo.GENItemVideos.LanguageId as VideoLanguageId,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'RichContent', @LangCode) AS RichContent,dbo.GENItemVideos.Name AS VideoName,
					GENItemFiles.FileName AS FileName,dbo.GENPollCategories.Name AS ExamName,dbo.GENItemVideos.Id AS VideoId, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String1', @LangCode)  AS CourseString1,
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String2', @LangCode)  AS CourseString2, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String3', @LangCode)  AS CourseString3, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String4', @LangCode)  AS CourseString4, 
					dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'String5', @LangCode)  AS CourseString5,
					Assessments.[Id] AS AssessmentId ,Assessments.[DisplayOrder] AS AssessmentDisplayOrder ,Assessments.[Code] AS AssessmentCode ,Assessments.[Name] AS AssessmentName
				,Assessments.[Description] AS AssessmentDescription ,Assessments.[DisplayOrdering]  AS AssessmentDisplayOrdering ,Assessments.[Image] AS AssessmentImage
				,Assessments.[Video] AS AssessmentVideo ,Assessments.[Audio] AS AssessmentAudio ,Assessments.[File] AS AssessmentFile ,Assessments.[Time] AS AssessmentTime
				,Assessments.[Weight] AS AssessmentWeight ,Assessments.[ActucalScore] AS AssessmentActualScore ,Assessments.[SuccessScore] AS AssessmentSuccessScore
				,Assessments.[LanguageId] AS AssessmentLanguageId ,Assessments.[ExamType] AS AssessmentExamType,dbo.FN_GetExamType(Assessments.[ExamType],@LangCode) AS AssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS AssessmentDateTime,
			     
				 ClassroomAssessments.[Id] AS ClassroomAssessmentId ,ClassroomAssessments.[DisplayOrder] AS ClassroomAssessmentDisplayOrder ,
				 ClassroomAssessments.[Code] AS ClassroomAssessmentCode ,ClassroomAssessments.[Name] AS ClassroomAssessmentName
				,ClassroomAssessments.[Description] AS ClassroomAssessmentDescription ,ClassroomAssessments.[DisplayOrdering]  AS ClassroomAssessmentDisplayOrdering ,
				ClassroomAssessments.[Image] AS ClassroomAssessmentImage
				,ClassroomAssessments.[Video] AS ClassroomAssessmentVideo ,ClassroomAssessments.[Audio] AS ClassroomAssessmentAudio ,ClassroomAssessments.[File] AS ClassroomAssessmentFile 
				,ClassroomAssessments.[Time] AS ClassroomAssessmentTime
				,ClassroomAssessments.[Weight] AS ClassroomAssessmentWeight,ClassroomAssessments.[ActucalScore] AS ClassroomAssessmentActualScore ,
				ClassroomAssessments.[SuccessScore] AS ClassroomAssessmentSuccessScore
				,ClassroomAssessments.[LanguageId] AS ClassroomAssessmentLanguageId ,ClassroomAssessments.[ExamType] AS ClassroomAssessmentExamType, 
				dbo.FN_GetExamType(ClassroomAssessments.[ExamType],@LangCode) AS ClassroomAssessmentsExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS ClassroomAssessmentDateTime,
				dbo.FN_GetBaseEntityIdByName('GENItem') AS ItemBaseEntityId,dbo.FN_GetBaseEntityIdByName('GENClassroom') AS ClassroomBaseEntityId,
				dbo.FN_GetBaseEntityIdByName('GENPollCategory') AS ExamBaseEntityId,dbo.FN_GetBaseEntityIdByName('GENType') AS CourseBaseEntityId,
				dbo.FN_GetBaseEntityIdByName('GENItemFiles') AS FileBaseEntityId,dbo.FN_GetBaseEntityIdByName('GENItemVideos') AS VideoBaseEntityId,
				dbo.FN_ProgressDone(GENClassrooms.Id, GENContacts.Id, GENItems.Id, 3) AS IsSessionFinished,
				CourseAssessment.[Id] AS CourseAssessmentId ,CourseAssessment.[DisplayOrder] AS CourseAssessmentDisplayOrder ,
				 CourseAssessment.[Code] AS CourseAssessmentCode ,CourseAssessment.[Name] AS CourseAssessmentName
				,CourseAssessment.[Description] AS CourseAssessmentDescription ,CourseAssessment.[DisplayOrdering]  AS CourseAssessmentDisplayOrdering ,
					CourseAssessment.[Image] AS CourseAssessmentImage
				,CourseAssessment.[Video] AS CourseAssessmentVideo ,CourseAssessment.[Audio] AS CourseAssessmentAudio ,CourseAssessment.[File] AS CourseAssessmentFile 
				,CourseAssessment.[Time] AS CourseAssessmentTime
				,CourseAssessment.[Weight] AS CourseAssessmentWeight,CourseAssessment.[ActucalScore] AS CourseAssessmentActualScore ,
				CourseAssessment.[SuccessScore] AS CourseAssessmentSuccessScore
				,CourseAssessment.[LanguageId] AS CourseAssessmentLanguageId ,CourseAssessment.[ExamType] AS CourseAssessmentExamType, 
				dbo.FN_GetExamType(CourseAssessment.[ExamType],@LangCode) AS CourseAssessmentExamTypeName,
				[GENExam_GENClassroom].DisplayDateTime AS CourseAssessmentDateTime
FROM           dbo.GENPollCategories RIGHT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENPollCategories.Id = dbo.GENClassrooms.ExamId LEFT OUTER JOIN
						 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id RIGHT OUTER JOIN
						 dbo.GENItems  ON dbo.GENItems.TypeId = dbo.GENTypes.Id LEFT JOIN
                         dbo.GENItemVideos ON dbo.GENItemVideos.ItemId = dbo.GENItems.Id AND (dbo.GENItemVideos.LanguageId = @Langid OR @Langid IS NULL OR dbo.GENItemVideos.LanguageId IS NULL) LEFT OUTER JOIN
                         dbo.GENItemFiles ON dbo.GENItems.Id = dbo.GENItemFiles.ItemId AND (dbo.GENItemFiles.LanguageId = @Langid OR @Langid IS NULL OR dbo.GENItemFiles.LanguageId IS NULL) RIGHT OUTER JOIN
                         dbo.GENClassroom_GENContact RIGHT OUTER JOIN
                         dbo.GENContacts ON dbo.GENClassroom_GENContact.StudentId = dbo.GENContacts.Id ON dbo.GENClassrooms.Id = dbo.GENClassroom_GENContact.ClassroomId RIGHT OUTER JOIN
                         dbo.GENListValues ON dbo.GENClassrooms.LanguageId = dbo.GENListValues.Id LEFT JOIN
						 [dbo].[GENExam_GENItem] ON [GENExam_GENItem].SessionId = dbo.GENItems.Id AND [GENExam_GENItem].IsActive = 1  LEFT JOIN
						 [dbo].[GENExam_GENType]  ON [GENExam_GENType].CourseId = dbo.GENTypes.Id AND [GENExam_GENType].IsActive = 1  LEFT JOIN
						 dbo.GENPollCategories Assessments ON [GENExam_GENItem].ExamId = Assessments.Id LEFT JOIN
						 [dbo].[GENExam_GENClassroom] ON [GENExam_GENClassroom].ClassroomId = dbo.GENClassrooms.Id AND [GENExam_GENClassroom].IsActive = 1 LEFT JOIN
						 --AND [GENExam_GENClassroom].DisplayDateTime < GETDATE() LEFT JOIN
						 dbo.GENPollCategories ClassroomAssessments ON [GENExam_GENClassroom].ExamId = ClassroomAssessments.Id LEFT JOIN
						 dbo.GENPollCategories CourseAssessment ON [GENExam_GENType].ExamId = CourseAssessment.Id 
WHERE        (dbo.GENContacts.UserId = @UserId) and dbo.GENTypes.Id = @ItemTypeId
GO
