CREATE Proc [dbo].[SP_FEUserCourseWithITemsByItemId](@ItemId bigint ,@LangCode nvarchar(500) )
as
SELECT          dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)AS CourseName,  dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Description', @LangCode) AS CourseGoals, dbo.GENTypes.DisplayOrdering AS DisplayOrder, dbo.GENTypes.IsPublish, dbo.GENTypes.IsActive, 
                         dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage, dbo.GENTypes.Id AS CourseId, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount, 
                      dbo.GENItems.Id AS ItemId,dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Name' ,@LangCode) AS ItemName, 
						dbo.fn_Item_Translate_ByKeyandId( dbo.GENItems.Id,'Description', @LangCode)  AS ItemDescription, dbo.GENItems.int1 AS LectureHour
						  ,iif(dbo.GENItems.int2 is null,0,dbo.GENItems.int2) as TableDisplayOrder
FROM            dbo.GENItems LEFT OUTER JOIN
                         dbo.GENTypes ON dbo.GENItems.TypeId = dbo.GENTypes.Id
WHERE        (dbo.GENItems.Id = @ItemId)
GO
/****** Object:  StoredProcedure [dbo].[SP_FEUserCourseWithITemsWithPercentage]    Script Date: 7/1/2026 10:45:03 AM ******/
