-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 04/07/2021
-- Description:	Get Final Exam Value
-- =============================================
CREATE PROCEDURE [dbo].[SP_FinalExamByStudentAndClassroom]
	-- Add the parameters for the stored procedure here
	@StudentId BIGINT, 
	@ClassroomId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select GENExamAnswerHeaders.*,(CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END) as FinalScore,
	  GENPollCategories.SuccessScore
	FROM GENExamAnswerHeaders
	INNER JOIN GENClassrooms ON GENExamAnswerHeaders.ClassroomId = GENClassrooms.Id
	INNER JOIN GENContacts ON GENExamAnswerHeaders.StudentId = GENContacts.Id
	INNER JOIN GENPollCategories ON GENExamAnswerHeaders.ExamId = GENPollCategories.Id
	WHERE ExamType = 0 AND GENExamAnswerHeaders.StudentId = @StudentId AND GENExamAnswerHeaders.ClassroomId = @ClassroomId
	AND GENExamAnswerHeaders.StartDateTime IS NOT NULL AND GENExamAnswerHeaders.EndtDateTime IS NOT NULL
END
GO
