/****** Object:  StoredProcedure [dbo].[SP_FinalExamsByStudentAndTalent]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 04/07/2021
-- Description:	Get Final Exams for talent
-- =============================================
CREATE PROCEDURE [dbo].[SP_FinalExamsByStudentAndTalent]
	-- Add the parameters for the stored procedure here
	@StudentId BIGINT, 
	@TalentId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select  GENExamAnswerHeaders.*,(CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2)) ELSE [dbo].[GENExamAnswerHeaders].[AnnouncedDegree] END) as FinalScore,
	  GENPollCategories.SuccessScore,
	  (CASE WHEN ISNULL([dbo].[GENExamAnswerHeaders].[AnnouncedDegree], 0) = 0 
	  AND (CAST((ISNULL([dbo].[GENExamAnswerHeaders].[TotalExamScore],0) * ISNULL([dbo].[GENExamAnswerHeaders].[ExamWeight], 0)) / [dbo].[GENExamAnswerHeaders].TotalScore AS decimal(18,2))) >= GENPollCategories.SuccessScore
	  THEN 
	  CAST('true' AS bit)
	  ELSE CAST('false' AS bit) END) Passed
	FROM GENTalents_Generic
	LEFT JOIN GENExamAnswerHeaders ON GENTalents_Generic.EntityId = GENExamAnswerHeaders.CourseId AND GENTalents_Generic.BaseEntityId = 28
	LEFT JOIN GENPollCategories ON GENExamAnswerHeaders.ExamId = GENPollCategories.Id
	LEFT JOIN GENContacts ON GENExamAnswerHeaders.StudentId = GENContacts.Id
	WHERE GENPollCategories.ExamType = 0 AND TalentId = @TalentId AND GENExamAnswerHeaders.StudentId = @StudentId
	AND GENExamAnswerHeaders.StartDateTime IS NOT NULL AND GENExamAnswerHeaders.EndtDateTime IS NOT NULL
END
GO
