CREATE procedure [dbo].[SP_FontReport] @LangRep varchar(2) 
-- =============================================
-- Author:		michael magdy
-- Create date: 13 June 2019
-- last update: 7 July 2019
-- Description:	font FontSettings for Report
-- =============================================
as
begin
DECLARE @ReportBasic_F nvarchar(max)
DECLARE @ReportBasic_FS decimal(18, 4)
DECLARE @ReportBasic_FC nvarchar(max)
DECLARE @ReportBasic_BC nvarchar(max)
 -----------------------------------------
DECLARE @ReportColH_F nvarchar(max)
DECLARE @ReportColH_FS decimal(18, 4)
DECLARE @ReportColH_FC nvarchar(max)
DECLARE @ReportColH_BC nvarchar(max)
-----------------------------------------
DECLARE @ReportField_F nvarchar(max)
DECLARE @ReportField_FS decimal(18, 4)
DECLARE @ReportField_FC nvarchar(max)
DECLARE @ReportField_BC nvarchar(max)
-----------------------------------------
DECLARE @ReportSection_F nvarchar(max)
DECLARE @ReportSection_FS decimal(18, 4)
DECLARE @ReportSection_FC nvarchar(max)
DECLARE @ReportSection_BC nvarchar(max)
-----------------------------------------
DECLARE @ReportSub_F nvarchar(max)
DECLARE @ReportSub_FS decimal(18, 4)
DECLARE @ReportSub_FC nvarchar(max)
DECLARE @ReportSub_BC nvarchar(max)
 ;
SET NOCOUNT ON;

Select @ReportBasic_F=FontFamilyName,@ReportBasic_FC=FontColor,@ReportBasic_FS=FontSize,@ReportBasic_BC=BackgroundColor
From FontSettings 
Where GroupName= 'ReportBasic'and lang =@LangRep

SET NOCOUNT ON;
Select @ReportColH_F=FontFamilyName,@ReportColH_FC=FontColor,@ReportColH_FS=FontSize,@ReportColH_BC=BackgroundColor
From FontSettings 
Where GroupName= 'ReportColH' and lang =@LangRep

SET NOCOUNT ON;
Select @ReportField_F=FontFamilyName,@ReportField_FC=FontColor,@ReportField_FS=FontSize,@ReportField_BC=BackgroundColor
From FontSettings 
Where GroupName= 'ReportField' and lang =@LangRep

SET NOCOUNT ON;
Select @ReportSection_F=FontFamilyName,@ReportSection_FC=FontColor,@ReportSection_FS=FontSize,@ReportSection_BC=BackgroundColor
From FontSettings 
Where GroupName= 'ReportSection' and lang =@LangRep

SET NOCOUNT ON;
Select @ReportSub_F=FontFamilyName,@ReportSub_FC=FontColor,@ReportSub_FS=FontSize,@ReportSub_BC=BackgroundColor
From FontSettings 
Where GroupName= 'ReportSub' and lang =@LangRep

SELECT	@ReportBasic_F as N'ReportBasic_F',
        @ReportBasic_FC as N'ReportBasic_FC',
		@ReportBasic_FS as N'ReportBasic_FS',
		@ReportBasic_BC as N'ReportBasic_BC',
		@ReportColH_F as N'ReportColH_F',
		@ReportColH_FC as N'ReportColH_FC',
		@ReportColH_FS as N'ReportColH_FS',
		@ReportColH_BC as N'ReportColH_BC',
		@ReportField_F as N'ReportField_F',
		@ReportField_FC as N'ReportField_FC',
		@ReportField_FS as N'ReportField_FS',
		@ReportField_BC as N'ReportField_BC',
		@ReportSection_F as N'ReportSection_F',
		@ReportSection_FC as N'ReportSection_FC',
		@ReportSection_FS as N'ReportSection_FS',
		@ReportSection_BC as N'ReportSection_BC',
		@ReportSub_F as N'ReportSub_F',
		@ReportSub_FC as N'ReportSub_FC',
		@ReportSub_FS as N'ReportSub_FS',
		@ReportSub_BC as N'ReportSub_BC'
end
GO
/****** Object:  StoredProcedure [dbo].[SP_FullBagsInfo]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   Proc [dbo].[SP_FullBagsInfo]  --SP_FullBagsInfo'2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
As
Begin

WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE H1.Id = 3
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
),
UniqueGENTypes AS (
    SELECT DISTINCT GENTypes.* 
    FROM CourseCategories 
    INNER JOIN RecursiveCte ON CourseCategories.CategoryId = RecursiveCte.Id 
    INNER JOIN GENTypes ON CourseCategories.CourseId = GENTypes.Id
)
select * from (
select UniqueGENTypes.id, UniqueGENTypes.Name,count(distinct GENClassrooms.id) as TimeExecution, sum(dbo.fn_VcrBookingStudentCount_Confirmed(GENClassrooms.Id)) as participation 
from  UniqueGENTypes 
left join GENClassrooms on UniqueGENTypes.id=GENClassrooms.CourseId and GENClassrooms.ClassroomCategoryId = 1 and GENClassrooms.IsDeleted=0 and GENClassrooms.IsActive = 1 and GENClassrooms.ClassRoomStatus = 2
where UniqueGENTypes.IsDeleted = 0 and UniqueGENTypes.IsActive = 1 and ((cast(UniqueGENTypes.DateCreated as date) >= cast(@DateF as date) and cast(UniqueGENTypes.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(UniqueGENTypes.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(UniqueGENTypes.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
group by UniqueGENTypes.id, UniqueGENTypes.Name
) as res
order by TimeExecution desc;
End
--,count(distinct g.Id)as TimeExecution
--,count(g.Id)
GO
