CREATE proc [dbo].[SP_GeAllMenu] (@langCode nvarchar(500))
as
SELECT       dbo.fn_ListValue_Translate_ByKeyandId( dbo.GENListValues.Id ,'Name',@langCode)AS SectionName,dbo.fn_WikiCategory_Translate_ByKeyandId(dbo.GENWikiCategories.Id,'Name',@langCode ) as Name , dbo.GENListValues.Id,(dbo.GENWikiCategories.String1+'/'+cast( dbo.GENWikiCategories.id as nvarchar(200)) + (CASE WHEN dbo.GENWikiCategories.String2 IS NOT NULL AND dbo.GENWikiCategories.String2 <> '' THEN dbo.GENWikiCategories.String2 ELSE ''  END)) as URL, dbo.GENListValues.DisplayOrdering
,dbo.GENListValues.String1 as MainURL, dbo.GENWikiCategories.DisplayOrdering as SubMenuOrder
FROM            dbo.GENListValues LEFT OUTER JOIN
                         dbo.GENWikiCategories ON dbo.GENListValues.Id = dbo.GENWikiCategories.ValueId1 RIGHT OUTER JOIN
                         dbo.GENListValuesTypes ON dbo.GENListValues.GENListValuesTypeId = dbo.GENListValuesTypes.Id
						
WHERE        (dbo.GENListValuesTypes.Name = N'Menu section') AND (dbo.GENListValues.IsActive = 1) and  dbo.GENWikiCategories.Name is not null
and dbo.GENWikiCategories.IsMenu =1


 union
						 SELECT        dbo.fn_ListValue_Translate_ByKeyandId( dbo.GENListValues.Id ,'Name',@langCode)AS SectionName,dbo.fn_FeedBackCategory_Translate_ByKeyandId( dbo.GENFeedBackCategories.Id,'Name',@langCode )as Name, dbo.GENListValues.Id,(dbo.GENFeedBackCategories.String1+'/'+cast( dbo.GENFeedBackCategories.id as nvarchar(200))) as URL, dbo.GENListValues.DisplayOrdering
						 ,dbo.GENListValues.String1 as MainURL, dbo.GENFeedBackCategories.DisplayOrdering as SubMenuOrder
FROM            dbo.GENListValues LEFT OUTER JOIN
                         dbo.GENFeedBackCategories ON dbo.GENListValues.Id = dbo.GENFeedBackCategories.ValueId1 RIGHT OUTER JOIN
                         dbo.GENListValuesTypes ON dbo.GENListValues.GENListValuesTypeId = dbo.GENListValuesTypes.Id
						 WHERE        (dbo.GENListValuesTypes.Name = N'Menu section') AND (dbo.GENListValues.IsActive = 1) and dbo.GENFeedBackCategories.Name is not null
GO
