CREATE proc [dbo].[SP_GeAllSliders]  @LangCode nvarchar(500)
as
SELECT        Id, DisplayOrder, IsActive, IsPublish, Image, Width, Height, SectionId, HomeSliderCategoryId, Code, dbo.fn_HomeSlider_Translate_ByKeyandId(  Id,'Name', @LangCode) as Name, Description, ColorCode, IsCheckedOut, DateCreated, DateUpdated, CheckinDate, CheckoutDate, Timeout, 
                         DisplayOrdering, CreatedById, LastUpdatedById, CheckoutBy,dbo.fn_HomeSlider_Translate_ByKeyandId(  Id,'String1', @LangCode) as String1,
						 dbo.fn_HomeSlider_Translate_ByKeyandId(  Id,'String2', @LangCode) as String2,
						  dbo.fn_HomeSlider_Translate_ByKeyandId(  Id,'String3', @LangCode) as String3, 
						   dbo.fn_HomeSlider_Translate_ByKeyandId(  Id,'String4', @LangCode)  as String4,
						     dbo.fn_HomeSlider_Translate_ByKeyandId(  Id,'String5', @LangCode) as String5, Int1, Int2, Int3, Int4, Int5, Long1, Long2, Long3, Long4, Long5, Float1, Float2, Float3, Float4, Float5, Decimal1, Decimal2, 
                         Decimal3, Decimal4, Decimal5, Bool1, Bool2, Bool3, Bool4, Bool5, Date1, Date2, Date3, Date4, Date5, ValueId1, ValueId2, ValueId3, ValueId4, ValueId5, IconId, ExpectedCheckoutDate, IsPosted
FROM            dbo.GENHomeSliders
WHERE GENHomeSliders.IsPublish = 1
ORDER BY GENHomeSliders.DisplayOrdering
