CREATE PROCEDURE [dbo].[SP_GENClassroom_GetById]
	-- Add the parameters for the stored procedure here
	@ClassroomId BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select Classroom_View.*,GENEntityPricings.netprice AS CoursePrice,
GENCurrencies.Name As CurrencyName ,(cast(GENEntityPricings.netprice as nvarchar(max)) +' '+  GENCurrencies.Name) AS DefaultCoursePrice,dbo.fn_FirstImage_BaseEntityEntityId(28,Classroom_View.CourseId) as CourseImage
from Classroom_View 
	 left join GENEntityPricings on Classroom_View.CourseId=GENEntityPricings.EntityId and GENEntityPricings.BaseEntityId=28 and GENEntityPricings.isdefault=1
	 left join GENCurrencies ON GENEntityPricings.CurrencyId=GENCurrencies.Id
	WHERE Classroom_View.Id = @ClassroomId
END
