/****** Object:  StoredProcedure [dbo].[SP_GENContacts_UpdateDuplicateInSheet]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_GENContacts_UpdateDuplicateInSheet](@WhereCondition nvarchar(Max),@Columns nvarchar(max))
as
DECLARE @SelectAll nvarchar(MAX)

set @SelectAll= 'update ContactImport set IsDuplicated=1
WHERE  ContactImport.id in 
 ( 
 select res.Id
 from(
   SELECT '+@Columns+',row_number() over(partition by '+@Columns+' order by new.Id desc) as roworder,new.Id as Id
   FROM ContactImport new
   WHERE '+@WhereCondition+'
   and new.Id <> ContactImport.Id
   )as res
   where roworder > 1
 ) '

 EXEC(@SelectAll)
GO
