      ,'' as [IsDoneActivities]
      ,'' as [ActivityIcon]
      ,'' as [CommentTypeName]
      ,'' as [NextActionName]
      ,'' as [ActivityEmployeeName]
      ,'' as [StatusName]
      ,'' as [EmployeeCode]
      ,'' as [EmployeeImage]
      ,'' as [ContactId]
      ,'' as [ContactPersonDefaultPhone]
      ,'' as [ContactPersonImage]
      ,'' as [ContactPersonAddress]
      ,'' as [ContactName]
      ,'' as [EmployeeName]
      ,'' as [ContactPersonName]
      ,'' as [Expr1]
      ,'' as [ActivityContactId]
      ,'' as [ContactPersonId]
      ,'' as [EmployeeId]
      ,'' as [CreatedByImage]
      ,'' as [NotificationDate]
      ,'' as [NotificationNumber]
      ,'' as [NotId]
      ,'' as [ActivityNotificationName]
      ,'' as [NotificationString]
      ,'' as [NotificationEventTypeId]
      ,'' as [PreviousActionName]
      ,'' as [NextActionIcon]
      ,'' as [PreviousActionIcon]
      ,'' as [NextActionColor]
      ,'' as [PreviousActionColor]
      ,'' as [CRMTicketId]
      ,'' as [FieldName]
      ,'' as [LastUpdatedByName]
	  from AchievementsOpenBals where 1 = 2
--select AllActivitiesWithDetails.* from AllActivitiesWithDetails
--LEFT JOIN [dbo].[Contact_View] ON ActivityContactId = [dbo].[Contact_View].Id OR AllActivitiesWithDetails.ContactPersonId = [dbo].[Contact_View].Id
--WHERE AllActivitiesWithDetails.EntityId =@EmployeeId  and AllActivitiesWithDetails.BaseEntityId=@BaseEntityId


select Distinct  GENClassrooms.Id,GENClassrooms.Name as ClassroomName,GENClassrooms.Code AS ClassroomCode
, (CASE WHEN GENClassrooms.ClassRoomStatus = 0 THEN 'Started' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 1 THEN 'Dropped' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 2 THEN 'Done' ELSE '' END END END) AS ClassRoomStatusString 
,GENClassrooms.FromDateTime,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString,COUNT(GENClassroom_GENContact.StudentId)  AS StudentCount, 
GENClassrooms.ToDateTime, FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString,GENRooms.Name as RoomName,dbo.fn_ItemCount_ClassId(GENClassrooms.Id) as SessionCount
FROM TLMSClassroom_Session 
inner join Classroom_Session_Instructor on Classroom_Session_Instructor.SessionId = TLMSClassroom_Session.Id
inner JOIN GENItems ON TLMSClassroom_Session.SessionId = GENItems.Id
inner JOIN GENClassrooms on GENClassrooms.Id = TLMSClassroom_Session.ClassroomId  
LEFT JOIN GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId 
LEFT JOIN GENRooms ON GENRooms.Id = GENClassrooms.RoomId
where Classroom_Session_Instructor.InstructorId = @EmployeeId
GROUP BY   GENClassrooms.Id,GENClassrooms.Name,GENClassrooms.Code,GENClassrooms.ClassRoomStatus,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime,GENRooms.Name



select  Distinct GENTypes.Id,GENTypes.Code As CourseCode, GENTypes.Name As CourseName,
(CASE WHEN GENTypes.Int1 IS NOT NULL AND GENTypes.Int2 IS NOT NULL THEN
CAST(GENTypes.Int1 AS nvarchar(MAX)) + ':' +CAST(GENTypes.Int2 AS nvarchar(MAX)) ELSE 
CASE WHEN GENTypes.Int1 IS NOT NULL THEN CAST(GENTypes.Int1 AS nvarchar(MAX)) + ':00' ELSE 
CASE WHEN GENTypes.Int2 IS NOT NULL THEN '00:' +CAST(GENTypes.Int2 AS nvarchar(MAX)) ELSE '' END END END) AS CourseTime,
GENTypes.Int2 AS CourseTime,GENTypes.Int1 AS CourseTimeHours,
GENTypes.Int2 AS CourseTimeMinutes,GENTypes.DisplayOrdering,GENTypes.IsActive
FROM            GENClassrooms inner JOIN
               GENTypes ON GENClassrooms.CourseId=GENTypes.Id
where GENClassrooms.InstructorId=@EmployeeId

select GENItems.Id,GENItems.Name AS SessionName,GENItems.Code As SessionCode,GENItems.Int1 As SessionTime,GENItems.DisplayOrder,TLMSClassroom_Session.SessionDateTime
, FORMAT(TLMSClassroom_Session.SessionDateTime, 'dd/MM/yyyy') AS SessionDateTimeString,TLMSClassroom_Session.FromDateTime,
FORMAT(TLMSClassroom_Session.FromDateTime, 'hh:mm tt') AS FromDateTimeString,TLMSClassroom_Session.ToDateTime,
FORMAT(TLMSClassroom_Session.ToDateTime, 'hh:mm tt') AS ToDateTimeString,COUNT(GENClassroom_GENContact.StudentId)  AS StudentCount
,GENRooms.Name as RoomName,GENClassrooms.Name as ClassroomName
FROM TLMSClassroom_Session 
inner join Classroom_Session_Instructor on Classroom_Session_Instructor.SessionId = TLMSClassroom_Session.Id
inner JOIN GENItems ON TLMSClassroom_Session.SessionId = GENItems.Id
inner JOIN GENClassrooms on GENClassrooms.Id = TLMSClassroom_Session.ClassroomId  
LEFT JOIN GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
LEFT JOIN GENRooms ON GENRooms.Id = GENClassrooms.RoomId
where Classroom_Session_Instructor.InstructorId=@EmployeeId
GROUP BY GENItems.Id,GENItems.Name,GENItems.Code,GENItems.Int1,GENItems.DisplayOrder,TLMSClassroom_Session.SessionDateTime,FORMAT(TLMSClassroom_Session.SessionDateTime, 'dd/MM/yyyy hh:mm tt')
,TLMSClassroom_Session.FromDateTime, FORMAT(TLMSClassroom_Session.FromDateTime, 'hh:mm tt'),TLMSClassroom_Session.ToDateTime,FORMAT(TLMSClassroom_Session.ToDateTime, 'hh:mm tt'),GENRooms.Name,GENClassrooms.Name


SELECT DISTINCT GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,GENTypes.Name As CourseName,GENClassrooms.Name AS ClassroomName,
GENExamAnswerHeaders.TotalExamScore,GENExamAnswerHeaders.ExamName,GENClassrooms.Id,GENExamAnswerHeaders.ExamId,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
	FROM GENContacts 
	LEFT JOIN GENClassroom_GENContact ON GENContacts.Id = GENClassroom_GENContact.StudentId
	LEFT JOIN GENClassrooms ON GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
	inner JOIN GENTypes ON GENClassrooms.courseId = GENTypes.Id 
	left join GENExam_GENType ON GENTypes.Id =GENExam_GENType.CourseId
	LEFT Join GENExamAnswerHeaders ON  GENExamAnswerHeaders.StudentId=GENContacts.ID and GENExamAnswerHeaders.InstructorId = @EmployeeId
	LEFT JOIN GENPollCategories ON GENExamAnswerHeaders.ExamId = GENPollCategories.Id
	WHERE GENClassrooms.InstructorId = @EmployeeId AND ((GENPollCategories.ExamType <> 6 AND  GENPollCategories.ExamType <> 7) OR GENPollCategories.ExamType IS NULL)
	GROUP BY GENContacts.Id ,GENContacts.Name,GENTypes.Name,GENClassrooms.Name,
GENExamAnswerHeaders.TotalExamScore,GENExamAnswerHeaders.ExamName,GENClassrooms.Id,GENExamAnswerHeaders.ExamId,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime


select GENPollCategories.Name AS ExamName,(CASE WHEN GENPollCategories.ExamType = 0 THEN 'FinalExam' ELSE CASE WHEN GENPollCategories.ExamType = 1 THEN 'MidExam' ELSE CASE WHEN GENPollCategories.ExamType = 2 THEN 'Quiz' ELSE CASE WHEN GENPollCategories.ExamType = 3 THEN 'Exercise' 
ELSE CASE WHEN GENPollCategories.ExamType = 4 THEN 'Assessment' ELSE CASE WHEN GENPollCategories.ExamType = 5 THEN 'Assignment' 
ELSE CASE WHEN GENPollCategories.ExamType = 6 THEN 'Questionaire' ELSE CASE WHEN GENPollCategories.ExamType = 7 THEN 'Poll' 
 ELSE '' END END END END END END END END) AS ExamTypeString,GENPollCategories.Time AS ExamTime,GENPollCategories.Weight,GENPollCategories.ActucalScore
FROM           GENPollCategories  LEFT JOIN
              GENClassrooms  ON GENPollCategories.Id=GENClassrooms.ExamId
where GENClassrooms.InstructorId=@EmployeeId
UNION 
select  GENPollCategories.Name AS ExamName,(CASE WHEN GENPollCategories.ExamType = 0 THEN 'FinalExam' ELSE CASE WHEN GENPollCategories.ExamType = 1 THEN 'MidExam' ELSE CASE WHEN GENPollCategories.ExamType = 2 THEN 'Quiz' ELSE CASE WHEN GENPollCategories.ExamType = 3 THEN 'Exercise' 
ELSE CASE WHEN GENPollCategories.ExamType = 4 THEN 'Assessment' ELSE CASE WHEN GENPollCategories.ExamType = 5 THEN 'Assignment' 
ELSE CASE WHEN GENPollCategories.ExamType = 6 THEN 'Questionaire' ELSE CASE WHEN GENPollCategories.ExamType = 7 THEN 'Poll' 
 ELSE '' END END END END END END END END) AS ExamTypeString,GENPollCategories.Time AS ExamTime,GENPollCategories.Weight,GENPollCategories.ActucalScore
FROM            GENPollCategories LEFT JOIN
               GENExam_GENClassroom ON GENPollCategories.Id=GENExam_GENClassroom.ExamId  LEFT JOIN
			   GENClassrooms  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id
where GENClassrooms.InstructorId=@EmployeeId



exec SP_GetAllChatMessages @POPId,@EmployeeId




select GENContacts.Id, GENContacts.Name,CASE
    WHEN GENContacts.Image is null THEN '/Content/images/User-Avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString,(CASE WHEN GENContacts.IsActive = 1 THEN 'True' ELSE 'False' END) AS IsActiveString,CRMSources.Name As SourceName,GENContacts.IsActive
 from GENContacts   left join
	GENListValues Assessment ON GENContacts.AssessmentId=Assessment.Id left join
	CRMSources ON GENContacts.SourceId=CRMSources.Id 
where   GENContacts.ResponsiblePersonId=@EmployeeId







Select Id,Name ,Image,FORMAT(GENCertifications.DateCertification, 'dd/MM/yyyy') AS DateCertificationString,GENCertifications.Destination
From GENCertifications
where GENCertifications.EmployeeId=@EmployeeId




Select Id,Name ,Position,IsWorked,Description,FORMAT(GENProfessionalExperiences.StartDate, 'dd/MM/yyyy') AS StartDateString,
FORMAT(GENProfessionalExperiences.EndDate, 'dd/MM/yyyy') AS EndDateString,GENProfessionalExperiences.Destination
From GENProfessionalExperiences
where GENProfessionalExperiences.EmployeeId=@EmployeeId




Select CandidateEmployees.*
From CandidateEmployees
where CandidateEmployees.EmployeeId=@EmployeeId
GO
