/****** Object:  StoredProcedure [dbo].[SP_GenerateSheetClassroomAttendance]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_GenerateSheetClassroomAttendance] --126
 (@ClassroomId Bigint)
AS
Begin

Select Classroom_Attendance.Id,GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,GENItems.Id AS SessionId,GENItems.Code AS SessionCode,GENItems.Name AS SessionName,FORMAT(TLMSClassroom_Session.SessionDateTime, 'MM/dd/yyyy') as SessionDate,
row_number() OVER (ORDER BY GENclassrooms.Id) Id2,GENClassrooms.Id AS ClassroomId,Classroom_Attendance.IsAttendance,
Classroom_Attendance.ExecuseId,GENListValues.Name as ExecuseName, dbo.FN_SessionsType(TLMSClassroom_Session.TypeSession,N'ar') as TypeSessionName
From GENClassrooms left join 
GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId left join 
GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id Left join
TLMSClassroom_Session ON GENClassrooms.Id=TLMSClassroom_Session.ClassroomId   inner join
GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id

left join Classroom_Attendance on Classroom_Attendance.SessionId = GENItems.Id and Classroom_Attendance.StudentId = GENContacts.Id and Classroom_Attendance.ClassroomId = GENClassrooms.Id
left join GENListValues on Classroom_Attendance.ExecuseId = GENListValues.Id
where GENClassrooms.Id=@ClassroomId and GENClassroom_GENContact.ClassroomId=@ClassroomId and TLMSClassroom_Session.ClassroomId=@ClassroomId and GENClassroom_GENContact.BookingTypeId =1
END
GO
