/****** Object:  StoredProcedure [dbo].[SP_GENIndustries_InsertNotExistIndustry]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 Create proc [dbo].[SP_GENIndustries_InsertNotExistIndustry](@typeId bigint)
  as
INSERT INTO GENIndustries(Name, IsPublish, IsActive,IndustryCategoryId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
 SELECT distinct CompanyLogDatas.GENIndustries_Name,0,1,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from CompanyLogDatas
 where CompanyLogDatas.GENIndustries_Name is not null and not EXISTS (SELECT DISTINCT dbo.CompanyLogDatas.GENIndustries_Name
FROM            dbo.CompanyLogDatas INNER JOIN
                         dbo.GENIndustries AS sourcetable ON dbo.CompanyLogDatas.GENIndustries_Name = sourcetable.Name COLLATE Arabic_CI_AS
WHERE          (dbo.CompanyLogDatas.IsNew = 1) and (sourcetable.IndustryCategoryId is null or sourcetable.IndustryCategoryId =@typeId))
GO
