/****** Object:  StoredProcedure [dbo].[SP_GENItems_GetById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_GENItems_GetById] (@ItemId bigint, @BaseEntityId bigint,@POPId bigint =null)
as
DECLARE @DefaultAddress NVARCHAR(MAX) = NULL
DECLARE @CompanyId BIGINT = NULL

select @DefaultAddress= DefaultAddress from Items_View where Id = @ItemId
select TOP(1) @CompanyId = [dbo].[Items_View].CompanyId from [dbo].[Items_View] where Id = @ItemId

select * from Items_View
where id =@ItemId

select TOP(1) *  from Company_View_Update where Id = @CompanyId

SELECT TOP(1) GENStatus.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN GENStyles ON GENStatus.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @ItemId
ORDER BY [dbo].[GENProcesses].Id Desc

SELECT NextStat.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN [dbo].[GENNextStatus] ON GENStatus.Id = [dbo].[GENNextStatus].CurrentStatusId
LEFT JOIN GENStatus NextStat ON NextStat.Id = [dbo].[GENNextStatus].NextStatusId
LEFT JOIN GENStyles ON NextStat.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @ItemId
ORDER BY [dbo].[GENNextStatus].Id Desc


SELECT GENGalleryAlbumImages.*, GENGalleryAlbumImages.AzureUri AS Image, GENGalleryAlbums.Name AS GalleryAlbumName FROM GENGalleryAlbumImages
LEFT JOIN GENGalleryAlbums ON GENGalleryAlbumImages.GalleryAlbumId = GENGalleryAlbums.Id
 WHERE GENGalleryAlbumImages.BaseEntityId = @BaseEntityId AND GENGalleryAlbumImages.EntityId = @ItemId

Select GENBranches.*
From GENBranches
Where GENBranches.BaseEntityId=@BaseEntityId and GENBranches.EntityId=@ItemId

SELECT GENPhones.*,GENPhoneTypes.Name AS PhoneTypeName, GENPhones.PhoneNumber AS PhoneNumberPrimary, (CASE WHEN GENPhones.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENPhones
LEFT JOIN GENPhoneTypes ON GENPhones.PhoneTypeId = GENPhoneTypes.Id
WHERE GENPhones.BaseEntityId=@BaseEntityId and GENPhones.EntityId=@ItemId



SELECT GENEmails.*,GENEmails.Id AS Id2,GENEmailTypes.Name AS EmailTypeName, GENEmails.Email AS EmailPrimary, (CASE WHEN GENEmails.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENEmails
LEFT JOIN GENEmailTypes ON GENEmails.EmailTypeId = GENEmailTypes.Id
WHERE GENEmails.BaseEntityId=@BaseEntityId and GENEmails.EntityId=@ItemId


SELECT GENPaymentPlans.*,FORMAT(GENPaymentPlans.DeliveryDate, 'dd/MM/yyyy') AS DeliveryDateString
FROM GENPaymentPlans
WHERE GENPaymentPlans.BaseEntityId=@BaseEntityId and GENPaymentPlans.EntityId=@ItemId

--SELECT GENImages.*, GENImages.AzureUri AS Image FROM GENImages WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId

 SELECT GENItemImages.* FROM GENItemImages
 WHERE  GENItemImages.ItemId = @ItemId


  SELECT GENTranslate_Items.*, (CASE WHEN GENTranslate_Items.FieldId  IS NOT NULL THEN(PageOfPageFeilds.DisplayName) ELSE '' END) AS FieldDisplayName,
  GENListValues.Name AS LanguageName
   FROM GENTranslate_Items Left join 
   PageOfPageFeilds ON GENTranslate_Items.FieldId=PageOfPageFeilds.id left join
   BaseEntityFields ON GENTranslate_Items.BaseEntityFieldId =BaseEntityFields.id left join
   GENListValues ON GENTranslate_Items.LangId = GENListValues.Id
  WHERE  GENTranslate_Items.ItemId = @ItemId

  SELECT GENAddresses.*, GENRegions.Name AS RegionName,GENCountries.Name AS CountryName, GENProvinces.Name AS ProvinceName, 
GENGovernorates.Name AS GovernorateName, GENCities.Name AS CityName, GENDistricts.Name AS DistrictName,GENAddressZones.Name AS AddressZoneName, GENAreas.Name AS AreaName,
GENListValues.Name AS AddressTypeName,(CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN 'far fa-check-circle' ELSE '' END ) AS IsDefaultIcon
, (CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END ) AS IsDefault
FROM GENAddresses
LEFT JOIN GENRegions ON GENAddresses.RegionsId = GENRegions.Id
LEFT JOIN GENCountries ON GENAddresses.CountryId = GENCountries.Id
LEFT JOIN GENProvinces ON GENAddresses.ProvinceId = GENProvinces.Id
LEFT JOIN GENGovernorates ON GENAddresses.GovernorateId = GENGovernorates.Id
LEFT JOIN GENCities ON GENAddresses.CityId = GENCities.Id
LEFT JOIN GENDistricts ON GENAddresses.DistrictId = GENDistricts.Id
LEFT JOIN GENAddressZones ON GENAddresses.AddressZoneId = GENAddressZones.Id
LEFT JOIN GENAreas ON GENAddresses.AreaId = GENAreas.Id
LEFT JOIN GENListValues ON GENAddresses.AddressTypeId = GENListValues.Id
 WHERE EntityId = @ItemId AND BaseEntityId = @BaseEntityId

   SELECT GENItemCategory_Item.*, GENItemCategories.Name AS CategoryName, GENItemCategories.Name AS ItemCategoryName
   FROM GENItemCategory_Item Left join 
   GENItemCategories ON GENItemCategory_Item.ItemCategoryId=GENItemCategories.id
  WHERE  GENItemCategory_Item.ItemId = @ItemId

 SELECT GENLinks.*,GENItem_LinkTypes.Name AS LinkTypeName
 FROM GENLinks left join
 GENItem_LinkTypes ON GENLinks.linkTypeId=GENItem_LinkTypes.Id
 WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId

   SELECT GENItemGroup_Item.*,GENItemGroups.Name As ItemGroupName
   FROM GENItemGroup_Item left join 
   GENItemGroups ON GENItemGroup_Item.ItemGroupId=GENItemGroups.Id
   WHERE  GENItemGroup_Item.ItemId = @ItemId
  
SELECT [dbo].[GENEntity_Tag].*, GENTags.Name AS TagName FROM [dbo].[GENEntity_Tag]
LEFT JOIN GENTags ON [dbo].[GENEntity_Tag].TagId = GENTags.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId

SELECT GENItem_Bundle.*,GENItems.Name As  ItemBundleName
   FROM GENItem_Bundle left join 
   GENItems ON  GENItem_Bundle.ItemBundleId =GENItems.Id
   WHERE  GENItem_Bundle.ItemId = @ItemId

   SELECT GENItemAttachments.*,GENItems.Name As ItemAttachmentName
   FROM GENItemAttachments left join
   GENItems ON GENItemAttachments.ItemAttachmentId=GENItems.Id
   WHERE  GENItemAttachments.ItemId = @ItemId
  
   SELECT GENItemPromotions.*,FORMAT(GENItemPromotions.DateFrom, 'dd/MM/yyyy') AS FromDateTimeString,
   FORMAT(GENItemPromotions.DateTo, 'dd/MM/yyyy') AS ToDateTimeString
   FROM GENItemPromotions 
   WHERE  GENItemPromotions.ItemId = @ItemId

   SELECT GENItemPackings.* ,GENUnits.Name as UnitName 
   FROM GENItemPackings left join
   GENUnits ON GENItemPackings.MainUnitId=GENUnits.Id
   WHERE  GENItemPackings.ItemId = @ItemId

   
   --SELECT GENFiles.*,GENListValues.Name AS LanguageName, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,
   -- REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt ,FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString
   --FROM GENFiles left join
   --GENListValues ON GENFiles.LanguageId = GENListValues.Id
   -- WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId

   --SELECT GENAudios.*,FORMAT(GENAudios.DateCreated, 'dd/MM/yyyy') AS DateCreatedString 
   --FROM GENAudios 
   --WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId

   -- SELECT GENVideos.*,FORMAT(GENVideos.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,GENListValues.Name AS LanguageName
   --FROM GENVideos left join
   --GENListValues ON GENVideos.LanguageId = GENListValues.Id 
   --WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId

 SELECT GENItemFiles.*,GENListValues.Name AS LanguageName,
   GENListValues.Name AS LanguageName, FORMAT(GENItemFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,
    REVERSE(LEFT(REVERSE(GENItemFiles.AzureUri), CHARINDEX('.', REVERSE(GENItemFiles.AzureUri)) - 1)) AS FileExt ,FORMAT(GENItemFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString
   FROM GENItemFiles left join	
   GENListValues ON GENItemFiles.LanguageId = GENListValues.Id
   WHERE  GENItemFiles.ItemId = @ItemId and GENItemFiles.IsFolder=0

   SELECT GENItemAudios.*
   FROM GENItemAudios 
   WHERE  GENItemAudios.ItemId = @ItemId

    SELECT GENItemVideos.*,GENListValues.Name AS LanguageName
   FROM GENItemVideos left join
   GENListValues ON GENItemVideos.LanguageId = GENListValues.Id
   WHERE  GENItemVideos.ItemId = @ItemId

     SELECT GENItemToItemPointers.*,GENItems.Name As ItemToItemPointerName,GENItemToItemPointerTypes.Name AS ItemToItemPointerTypeName
   FROM GENItemToItemPointers left join
   GENItems ON GENItemToItemPointers.ItemToItemPointerId = GENItems.Id left join 
   GENItemToItemPointerTypes ON GENItemToItemPointers.ItemToItemPointerTypeId=GENItemToItemPointerTypes.id
   WHERE  GENItemToItemPointers.ItemId = @ItemId

  SELECT GENEntityPricings.*, GENCurrencies.Name AS CurrencyName, GENRegions.Name AS regionName, GENUnits.Name AS UnitName,
 FORMAT(GENEntityPricings.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString, 
 FORMAT(GENEntityPricings.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString FROM GENEntityPricings
LEFT JOIN GENCurrencies ON GENEntityPricings.CurrencyId = GENCurrencies.Id
LEFT JOIN GENRegions ON GENEntityPricings.RegionId = GENRegions.Id
LEFT JOIN GENUnits ON GENEntityPricings.UnitId = GENUnits.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @ItemId 


Select CRMSentEmails.[To], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ItemId and CRMSentEmails.EmailEntityPoPId=@POPId


Select CRMSentEmails.[From], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ItemId and CRMSentEmails.EmailEntityPoPId=@POPId



Select CRMSentEmails.[Cc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ItemId and CRMSentEmails.EmailEntityPoPId=@POPId

Select CRMSentEmails.[Bcc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ItemId and CRMSentEmails.EmailEntityPoPId=@POPId


