    REVERSE(LEFT(REVERSE(GENItemFiles.AzureUri), CHARINDEX('.', REVERSE(GENItemFiles.AzureUri)) - 1)) AS FileExt ,FORMAT(GENItemFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString
   FROM GENItemFiles left join	
   GENListValues ON GENItemFiles.LanguageId = GENListValues.Id
