FORMAT(GENDualLinkAttachments.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENDualLinkAttachments.AzureUri), CHARINDEX('.', REVERSE(GENDualLinkAttachments.AzureUri)) - 1)) AS FileExt 
