CREATE proc [dbo].[SP_GENRawDatas_UpdateDuplicate](@WhereCondition nvarchar(Max),@Columns nvarchar(max))
as
DECLARE @SelectAll nvarchar(MAX)

set @SelectAll= 'update ImportLogDatas set ErrorStatus='''+'DataBase Duplicate'+' : '+@Columns+''' , ReasonContent ='''+''+'''
 
WHERE  EXISTS
 ( 
   SELECT '+@Columns+'
   FROM GENRawDatas
   WHERE '+@WhereCondition+'
     
 ) '

 EXEC(@SelectAll)
GO
