/****** Object:  StoredProcedure [dbo].[SP_GENWikiLogDatas_GENStyles_InsertNotExist]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_GENWikiLogDatas_GENStyles_InsertNotExist]
  as
INSERT INTO GENStyles(StyleValue,DateCreated,DateUpdated) 
                    SELECT distinct GENWikiLogDatas.Icon_Name,GETDATE(),GETDATE() from GENWikiLogDatas 
                    where GENWikiLogDatas.Icon_Name is not null and GENWikiLogDatas.Icon_Name not IN(
					SELECT DISTINCT sourcetable.StyleValue 
                    FROM dbo.GENStyles AS sourcetable )
GO
/****** Object:  StoredProcedure [dbo].[SP_GENWikiLogDatas_ListValue1_InsertNotExistListValue1]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_GENWikiLogDatas_ListValue1_InsertNotExistListValue1](@typeId bigint)
  as
INSERT INTO GENListValues(Name, IsPublish, IsActive,GENListValuesTypeId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
 SELECT distinct GENWikiLogDatas.GENListValues1_Name,0,1,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from GENWikiLogDatas
 where GENWikiLogDatas.GENListValues1_Name is not null and GENWikiLogDatas.GENListValues1_Name not IN (SELECT DISTINCT sourcetable.Name
FROM            dbo.GENListValues AS sourcetable
WHERE          (@typeId is null or sourcetable.GENListValuesTypeId =@typeId))
GO
