/****** Object:  StoredProcedure [dbo].[SP_GetAllBlogsAndComment]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_GetAllBlogsAndComment] -- [SP_GetAllBlogsAndComment] 0
(
 @Id nvarchar(500)
    
)
AS
BEGIN
    SET NOCOUNT ON
   SELECT   GENBlogs.Id,
   GENBlogs.UserId,
        GENBlogs.Text as BlogText,
        GENBlogs.Title as BlogTitle,
        GENBlogs.Image as BlogImage,
        GENBlogs.Video as BlogVideo,
        GENBlogs.Url as BlogUrl,
        GENBlogs.LikesNumber,
        GENBlogs.DisLikesNumber,
        GENBlogs.Pinned,
        GENBlogs.CreatedDate,
        GENBlogs.UpdatedDate,
        GENBlogs.CreatedById,
        GENBlogs.TalentId,
		GENTalents.Name as TalentName,
		GENBlogs.CourseId,
		GENTypes.Name as CourseName,
        AspNetUsers.Name as UserName,
        FORMAT(GENBlogs.CreatedDate,'dd/MM/yyyy hh:mm tt') as DateCreatedString,
        FORMAT(GENBlogs.UpdatedDate,'dd/MM/yyyy hh:mm tt') as DateUpdatedString,
		GENComments.Id as CommentID,
        GENComments.CommentText,
		GENComments.Video as CommentVideo,
		GENComments.Url as CommentUrl,
		GENComments.Image as CommentImage,
        GENComments.CreatedDate as commentCreatedDate,
        GENComments.UpdatedDate as commentUpdatedDate,
        GENComments.CreatedById as CommentCreatedById,
        GENComments.LastUpdatedById as CommentLastUpdatedById,
		GENComments.UserId as CommentUserId,	
		CommentUser.Name as CommpentUserName,
		FORMAT(GENComments.CreatedDate,'dd/MM/yyyy hh:mm tt')as CommentCreatedDateString,
		FORMAT(GENComments.UpdatedDate,'dd/MM/yyyy hh:mm tt')as CommentUpdatedDateString,
		GENReacts.Id as ObjectId,
		GENReacts.BlogId as ReactBlogId,
		GENReacts.UserId  as ReactUserId,
		GENReacts.ReactId,
		(case when GENReacts.ReactId=1 then 'like'  when GENReacts.ReactId=2 then 'dislike' end) as ReactName,
		GENReacts.CreatedDate ,
		GENReacts.UpdatedDate ,
		ReactUser.Name as ReactUserName,
		GENBlogs.Text as ReactBlogName,
		FORMAT(GENReacts.CreatedDate,'dd/MM/yyyy hh:mm tt')as ReactCreatedDateString,
		FORMAT(GENReacts.UpdatedDate,'dd/MM/yyyy hh:mm tt')as ReactUpdatedDateString
from GENBlogs 
left join AspNetUsers on GENBlogs.UserId = AspNetUsers.Id
left join GENComments on GENComments.BlogId = GENBlogs.Id and GENComments.ParentId IS NULL and GENComments.DeletedDate is null
left join  AspNetUsers CommentUser on GENComments.UserId=AspNetUsers.Id
left join GENReacts on GENBlogs.Id=GENReacts.BlogId
left join  AspNetUsers ReactUser on GENReacts.UserId=ReactUser.Id
left join GENTalents on GENBlogs.TalentId = GENTalents.Id
left join GENTypes on GENBlogs.CourseId = GENTypes.Id
 where GENBlogs.IsDeleted=0 and  GENBlogs.IsActive = 1 and GENBlogs.IsPublish = 1 and (GENBlogs.TalentId is null or GENBlogs.TalentId in (select TalentId from GENContact_Talent inner join GENContacts on GENContacts.Id = GENContact_Talent.ContactId 
 where UserId = @Id))



END
