CREATE PROCEDURE [dbo].[SP_GetAllBlogsAndComments]
(
 @Id bigint
    
)
AS
BEGIN

    SET NOCOUNT ON

   SELECT  GENBlogs.Id,
        GENBlogs.Text as BlogText,
        GENBlogs.Title as BlogTitle,
        GENBlogs.Image as BlogImage,
        GENBlogs.Video as BlogVideo,
        GENBlogs.Url as BlogUrl,
        GENBlogs.LikesNumber,
        GENBlogs.DisLikesNumber,
        GENBlogs.Pinned,
        GENBlogs.CreatedDate,
        GENBlogs.UpdatedDate,
        GENBlogs.CreatedById,
        AspNetUsers.Name as UserName,
        FORMAT(GENBlogs.CreatedDate,'dd/MM/yyyy') as DateCreatedString,
        FORMAT(GENBlogs.UpdatedDate,'dd/MM/yyyy') as DateUpdatedString,
		GENComments.Id as CommentID,
        GENComments.CommentText,
		GENComments.Video as CommentVideo,
		GENComments.Url as CommentUrl,
		GENComments.Image as CommentImage,
        GENComments.CreatedDate as commentCreatedDate,
        GENComments.UpdatedDate as commentUpdatedDate,
        GENComments.CreatedById as CommentCreatedById,
        GENComments.LastUpdatedById as CommentLastUpdatedById,
		CommentUser.Name as CommpentUserName,
		FORMAT(GENComments.CreatedDate,'dd/MM/yyyy')as CreatedDateString,
		FORMAT(GENComments.UpdatedDate,'dd/MM/yyyy')as UpdatedDateString
from GENBlogs 
left join AspNetUsers on GENBlogs.UserId = AspNetUsers.Id
left join GENComments on GENComments.BlogId = GENBlogs.Id and GENComments.ParentId IS NULL
left join  AspNetUsers CommentUser on GENComments.UserId=AspNetUsers.Id
END
GO
