CREATE PROCEDURE [dbo].[SP_GetAllByHeaderId] --[SP_GetAllByHeaderId] 10119,'ar'
(@Id bigint, @LangCode nvarchar(500))
AS
BEGIN
	SET NOCOUNT ON;
	SELECT e.*,GENPollCategories.ExamType,[dbo].[FN_GetExamType]( GENPollCategories.ExamType, @LangCode) AS ExamTypeName, GENPollCategories.SuccessScore
	,CONVERT(varchar, DATEADD(second, DATEDIFF(SECOND,e.EndtDateTime,e.StartDateTime), 0), 108) as ExamPeriod
	from dbo.GENExamAnswerHeaders e
	LEFT JOIN GENPollCategories ON e.ExamId = GENPollCategories.Id
	where e.Id = @Id
END
GO
