CREATE proc [dbo].[Sp_GetAllChatedContacts] --  Sp_GetAllChatedContacts '96d8c852-8574-400d-90b2-669d9b9f28d5','',1
@UserId nvarchar(256),@searchtext nvarchar(50),@EnableVcr bit =null
AS
Begin
Select DISTINCT GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,GENContacts.Position,
us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,cs.SubStatus ,count(LastMsg.Id) as countMessages, cs.MainStatusId,isnull(ss.DisplayOrdering,0) as DisplayOrdering
, CASE
    WHEN GENContacts.Image is null THEN null
	else GENContacts.Image
  end as Image, 'Contact' AS UserType, isnull(max(GENChatMessages.MessageTime),GETDATE()) AS LastChatMessage
from 
GENContacts 
LEFT JOIN AspNetUsers us on GENContacts.UserId=us.Id
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
inner join GENChatMessages on  (UserSenderId = @UserId AND UserReceiverId = us.Id) OR (UserSenderId = us.Id AND UserReceiverId = @UserId)
left join GENChatMessages as LastMsg on ( (LastMsg.UserSenderId = us.Id AND LastMsg.UserReceiverId = @UserId)) and isnull(LastMsg.IsSeen,0) = 0
Left JOIN GENClassroom_GENContact allStudentVCR ON GENContacts.Id=allStudentVCR.StudentId and (allStudentVCR.ClassroomId 
in (select ClassroomId From
GENClassroom_GENContact
inner join GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id
where GENContacts.UserId =@UserId)
 or 
 (allStudentVCR.ClassroomId in (select ClassroomId From
TLMSClassroom_Session inner join GENEmployees ON TLMSClassroom_Session.InstructorId=GENEmployees.Id
where GENEmployees.UserId = @UserId))


)

Left Join GENClassrooms ON allStudentVCR.ClassroomId=GENClassrooms.Id
where GENContacts.IsActive = 1 AND (GENContacts.Name like  '%'+@searchtext+'%' or @searchtext IS NULL ) And (us.Id!=@UserId) AND GENContacts.UserId=us.Id 
and ((allStudentVCR.ClassroomId is not null and GENClassrooms.ToDateTime >= GETDATE()) or @EnableVcr is null or @EnableVcr =0)
group by GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,GENContacts.Position,us.Id,us.Name,us.UserName,ss.Name,ss.ColorCode
,cs.SubStatus,cs.MainStatusId,ss.DisplayOrdering,GENContacts.Image

UNION 

Select DISTINCT GENEmployees.Email AS DefaultEmail,GENEmployees.Telephone AS DefaultPhone,GENEmployees.Address AS DefaultAddress,GENEmployees.Position, 
 us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,cs.SubStatus ,count(LastMsg.Id) as countMessages , cs.MainStatusId,isnull(ss.DisplayOrdering,0) as DisplayOrdering
, CASE
    WHEN GENEmployees.Image is null THEN null
	else GENEmployees.Image
  end as Image, 'Employee' AS UserType, isnull(max(GENChatMessages.MessageTime),GETDATE()) AS LastChatMessage
from 
GENEmployees 
LEFT JOIN AspNetUsers us on GENEmployees.UserId=us.Id
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
inner join GENChatMessages on(UserSenderId = @UserId AND UserReceiverId = us.Id) OR (UserSenderId = us.Id AND UserReceiverId = @UserId)
left join GENChatMessages as LastMsg on ((LastMsg.UserSenderId = us.Id AND LastMsg.UserReceiverId = @UserId)) and isnull(LastMsg.IsSeen,0) = 0
Left Join TLMSClassroom_Session ALLInstructorVCR ON GENEmployees.Id =ALLInstructorVCR.InstructorId and  (ALLInstructorVCR.ClassroomId 
in (select ClassroomId From
GENClassroom_GENContact
inner join GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id
where GENContacts.UserId =@UserId)
 or 
 (ALLInstructorVCR.ClassroomId in (select ClassroomId From
TLMSClassroom_Session inner join GENEmployees ON TLMSClassroom_Session.InstructorId=GENEmployees.Id
where GENEmployees.UserId = @UserId))

)
Left Join GENClassrooms ON ALLInstructorVCR.ClassroomId=GENClassrooms.Id
where  GENEmployees.IsActive = 1 AND (GENEmployees.Name like  '%'+@searchtext+'%' or @searchtext IS NULL ) And (us.Id!=@UserId)  AND GENEmployees.UserId=us.Id
and ((ALLInstructorVCR.ClassroomId is not null and GENClassrooms.ToDateTime >= GETDATE()) or @EnableVcr is null or @EnableVcr =0)
group by GENEmployees.Email ,GENEmployees.Telephone ,GENEmployees.Address,GENEmployees.Position, us.Id,us.Name,us.UserName,ss.Name,ss.ColorCode,cs.SubStatus 
, cs.MainStatusId,ss.DisplayOrdering,GENEmployees.Image
End
GO
