CREATE proc [dbo].[Sp_GetAllColleaguesContacts] @UserId nvarchar(256),@searchtext nvarchar(50)
AS
Begin
Select DISTINCT GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,GENContacts.Position,
us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,cs.SubStatus ,dbo.countMessages(us.Id,@UserId) as countMessages, cs.MainStatusId,ss.DisplayOrdering
, CASE
    WHEN GENContacts.Image is null THEN null
	else GENContacts.Image
  end as Image, 'Contact' AS UserType, LastChat.MessageTime AS LastChatMessage
from 
GENContacts 
LEFT JOIN AspNetUsers us on GENContacts.UserId=us.Id
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
OUTER APPLY (SELECT TOP 1 * FROM GENChatMessages WHERE (UserSenderId = @UserId AND UserReceiverId = us.Id) OR (UserSenderId = us.Id AND UserReceiverId = @UserId) ORDER BY Id DESC) 
AS LastChat
where GENContacts.IsActive = 1 AND (GENContacts.Name like  '%'+@searchtext+'%' or @searchtext IS NULL ) And (us.Id!=@UserId) AND GENContacts.UserId=us.Id
UNION 
Select DISTINCT GENEmployees.Email AS DefaultEmail,GENEmployees.Telephone AS DefaultPhone,GENEmployees.Address AS DefaultAddress,GENEmployees.Position, 
 us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,cs.SubStatus ,dbo.countMessages(us.Id,@UserId) as countMessages, cs.MainStatusId,ss.DisplayOrdering
, CASE
    WHEN GENEmployees.Image is null THEN null
	else GENEmployees.Image
  end as Image, 'Employee' AS UserType, LastChat.MessageTime AS LastChatMessage
from 
GENEmployees 
LEFT JOIN AspNetUsers us on GENEmployees.UserId=us.Id
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
OUTER APPLY (SELECT TOP 1 * FROM GENChatMessages WHERE (UserSenderId = @UserId AND UserReceiverId = us.Id) OR (UserSenderId = us.Id AND UserReceiverId = @UserId) ORDER BY Id DESC) 
AS LastChat
where  GENEmployees.IsActive = 1 AND (GENEmployees.Name like  '%'+@searchtext+'%' or @searchtext IS NULL ) And (us.Id!=@UserId)  AND GENEmployees.UserId=us.Id

End
GO
