CREATE  proc [dbo].[Sp_GetAllCourses_ByCategoryId]  --Sp_GetAllCourses_ByCategoryId 3,'ar' 
(@Id bigint=null,@langCode nvarchar(500) )
as  
Begin
WITH RecursiveCte AS
(
    SELECT  H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,H1.RichContent As Details,H1.Code AS String,H1.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H1.Id) as ImageCategory,H1.Description,IsNull(H1.ParentId,0) AS ParentId
	FROM GENTypeCategories H1
    WHERE H1.Id = @Id   
	--and Id not in (@Id)
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name ,H2.RichContent As Details,H2.Code AS String,H2.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H2.Id) as ImageCategory,H2.Description,IsNull(H2.ParentId,0) AS ParentId
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
select res.*,ISNULL(GENTypes.Id,Cast(0 as  bigint)) As CourseId,dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [ImageCourse],GENTypes.Description,GENTypes.DisplayOrdering as DisplayOrderCourse ,dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name','ar') As CourseName from (
select RecursiveCte.*,
Count(distinct GENTypes.Id) AS Countcourses,cast(sum(int1 * 60 + Int2) / 60 as int) as TotalHours
from RecursiveCte 
left join GENTypes ON RecursiveCte.Id =GENTypes.TypeCategoryId and (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) 
group by RecursiveCte.Id,Parent,RecursiveCte.Name,Details,RecursiveCte.DisplayOrdering,String,ImageCategory,RecursiveCte.Description,RecursiveCte.ParentId
) as res
left join GENTypes ON res.Id =GENTypes.TypeCategoryId and (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) and GENTypes.TypeCategoryId <> @Id
order by Id
end
GO
/****** Object:  StoredProcedure [dbo].[SP_GetALLDataFromGenWiki]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_GetALLDataFromGenWiki] -- [SP_GetALLDataFromGenWiki]'2019-01-01', '2026-01-01'
@DateF Datetime,
@DateTo Datetime
AS
BEGIN
    -- Set NOCOUNT ON to stop the message about the number of rows affected
  
    SELECT 
        (SELECT COUNT(*) 
		FROM GENWikis 
		WHERE WikiCategoryId = 55 And
		((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) 
		and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		And GENWikis.IsActive = 1 And GENWikis.IsPublish = 1 
        or (@DateF is null and @DateTo is null
		and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date)
		and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0)))As News,
        (SELECT COUNT(*) 
		FROM GENWikis WHERE WikiCategoryId = 94 
		And GENWikis.IsActive = 1 And GENWikis.IsPublish = 1 
		And ((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))) AS Activity,
        (SELECT COUNT(*) FROM GENWikis
		WHERE WikiCategoryId = 75
		And GENWikis.IsActive = 1 And GENWikis.IsPublish = 1 
		And ((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))) AS Agreements,
        (SELECT COUNT(*) 
		FROM GENWikis WHERE WikiCategoryId = 70
		and IsActive = 1 And GENWikis.IsPublish = 1 
		And ((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))) As Seminars,
        (SELECT COUNT(*) FROM GENWikis 
		WHERE WikiCategoryId = 93 
		and GENWikis.IsActive = 1 And GENWikis.IsPublish = 1 
		And ((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))) As DeterminationPepoles,
        (SELECT COUNT(*) FROM GENWikis 
		WHERE WikiCategoryId = 72 
		and IsActive = 1 And GENWikis.IsPublish = 1 
		And ((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))) As Conferences,
        (SELECT COUNT(*) FROM GENWikis
		WHERE WikiCategoryId = 68 
		And GENWikis.IsActive = 1 And GENWikis.IsPublish = 1 
		And ((cast(GENWikis.DateCreated as date) >= cast(@DateF as date) and cast(GENWikis.DateCreated as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(GENWikis.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENWikis.DateCreated as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))) As Visits,
        (SELECT COUNT(*) FROM GENFeedBacks WHERE FeedBackCategoryId = 5 And ((cast(GENFeedBacks.DateCreated as date) >= cast(@DateF as date) and cast(GENFeedBacks.DateCreated as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENFeedBacks.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENFeedBacks.DateCreated as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))) As NoCoo_Operate,
		(SELECT count(*) FROM GENFeedBacks WHERE FeedBackCategoryId = 5 And bool2 = 1   And((cast(GENFeedBacks.DateCreated as date) >= cast(@DateF as date) and cast(GENFeedBacks.DateCreated as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENFeedBacks.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENFeedBacks.DateCreated as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))) As Response,
		1 as DataSetNo
END;

--select * from GENFeedBackCategories where id = 5
--SELECT count(*) FROM GENFeedBacks WHERE IsClosed = 1
GO
/****** Object:  StoredProcedure [dbo].[SP_GetAllExamAnswerDetailsByExamHeaderId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_GetAllExamAnswerDetailsByExamHeaderId] (@Id bigint)
AS
BEGIN
	SET NOCOUNT ON;
	SELECT   Distinct    
	dbo.GENExamAnswerDetails.Id,dbo.GENExamAnswerDetails.Id AS Id2, dbo.GENExamAnswerDetails.DateCreated, dbo.GENExamAnswerDetails.DateUpdated, 
	dbo.GENExamAnswerDetails.PollAnswerId, dbo.GENExamAnswerDetails.PollId, 
                         dbo.GENExamAnswerDetails.CreatedById, dbo.GENExamAnswerDetails.LastUpdatedById, dbo.GENExamAnswerDetails.Email, 
						 dbo.GENExamAnswerDetails.IsRevised, dbo.GENExamAnswerDetails.ExamAnswerHeaderId, 
                         dbo.GENExamAnswerDetails.Score, dbo.GENExamAnswerDetails.Weight, dbo.GENExamAnswerDetails.QuestionName, 
						 dbo.GENExamAnswerDetails.QuestionCorrectedAnswer, dbo.GENExamAnswerDetails.AnswerName, 
                         dbo.GENExamAnswerDetails.Article, dbo.GENExamAnswerDetails.Value, dbo.GENPolls.QuestionType, dbo.GENPolls.Code,
						 dbo.GENPolls.DisplayOrder,dbo.GENPolls.DisplayOrdering,
						  dbo.GENQuestionGroups.Id AS GroupQuestionId ,dbo.GENQuestionGroups.Name as GroupQuestionName
						 ,(CASE WHEN dbo.GENPollAnswers.IsCorrect IS  NULL THEN CAST(0 AS BIT) ELSE dbo.GENPollAnswers.IsCorrect END)  AS IsCorrect
					
FROM            dbo.GENExamAnswerDetails LEFT OUTER JOIN
						GENExamAnswerHeaders ON GENExamAnswerDetails.ExamAnswerHeaderId =GENExamAnswerHeaders.Id left join
                         dbo.GENPolls ON dbo.GENExamAnswerDetails.PollId = dbo.GENPolls.Id left join  
						 dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId  LEFT join 
						 GENQuestionGroups ON GENQuestionGroups.Id=dbo.PollCategoryandPolls.QuestionGroupId and 
						 PollCategoryandPolls.PollcategoryId =GENExamAnswerHeaders.ExamId
						  left join
						 
						  
						 dbo.GENPollAnswers  ON  dbo.GENExamAnswerDetails.PollAnswerId= dbo.GENPollAnswers.Id 

WHERE        (dbo.GENExamAnswerDetails.ExamAnswerHeaderId = @Id)
END
GO
