    -- Insert statements for procedure here
	select DISTINCT GENFiles.Id, GENFiles.FileName, GENFiles.AzureUri,GENFiles.BaseEntityId FROM GENFiles
	LEFT JOIN GENChatMessages ON GENChatMessages.Id = GENFiles.EntityId AND GENFiles.BaseEntityId = @BaseEntityId
	where GENChatMessages.ChatGroupId = @GroupId
END
