/****** Object:  StoredProcedure [dbo].[SP_GetAllQuestionAnswersById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[SP_GetAllQuestionAnswersById] (@Id bigint)
AS
BEGIN
	SET NOCOUNT ON;
	SELECT  distinct CAST(0 AS bigint) AS Id, (CASE WHEN dbo.GENPollAnswers.Id IS NOT NULL THEN dbo.GENPollAnswers.Id ELSE dbo.GENPolls.Id END)  AS Id2, getdate() AS DateCreated,getdate() AS DateUpdated,null AS PollAnswerId, dbo.GENPolls.Id AS PollId,CAST(0 AS BIT) AS IsRevised,
	CAST(0 AS bigint) AS ExamAnswerHeaderId, null AS Article, CAST(0 AS float) AS Value, dbo.GENPolls.QuestionType,dbo.GENPolls.Code, dbo.GENPolls.DisplayOrder,dbo.GENPolls.DisplayOrdering
	,dbo.GENPolls.Weight, CAST(0 AS float) AS Score,dbo.GENPolls.Question,dbo.fn_Correct_QuestionAnswers(dbo.GENPolls.Id) AS QuestionCorrectedAnswer,GENPollAnswers.Id AS AnswerId,GENPollAnswers.Answer,
	dbo.GENQuestionGroups.Id AS GroupQuestionId ,dbo.GENQuestionGroups.Name as GroupQuestionName,dbo.GENPolls.Name As QNumber,
	dbo.GENPolls.Question AS QuestionName,dbo.GENPolls.IncreasePointsPerValue,dbo.GENPolls.DecreasePointsPerValue,
	(CASE WHEN dbo.GENPollAnswers.IsCorrect IS  NULL THEN CAST(0 AS BIT) ELSE dbo.GENPollAnswers.IsCorrect END)  AS IsCorrect,dbo.GENPolls.DisplayOrder as QDisplayOrder
FROM dbo.GENPolls 
RIGHT OUTER JOIN dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId 
LEFT JOIN GENPollAnswers ON GENPollAnswers.PollId = GENPolls.Id
LEFT JOIN GENQuestionGroups ON GENQuestionGroups.Id=dbo.PollCategoryandPolls.QuestionGroupId
WHERE (dbo.PollCategoryandPolls.PollCategoryId = @Id) and dbo.GENPolls.IsActive =1
END
GO
