CREATE proc [dbo].[SP_GetAllStyles]  @fetchNumber int, @fetchStart int, @orderBy nvarchar(MAX),
@Name nvarchar(MAX) = NULL
as
begin
select * From GENStyles
WHERE (Name like '%'+@Name+'%' OR @Name IS NULL)
ORDER BY ''+@orderBy+''	
OFFSET @fetchStart ROWS
FETCH NEXT @fetchNumber ROWS ONLY;
End

GO
