GO
CREATE  proc [dbo].[Sp_GetAllTrainingMenu_ByCategoryId]  --Sp_GetAllTrainingMenu_ByCategoryId 3,'ar' 
(@Id bigint=null,@langCode nvarchar(500) )
as  
Begin
WITH RecursiveCte AS
(
    SELECT  H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,H1.RichContent As Details,H1.Code AS String,H1.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H1.Id) as ImageCategory,H1.Description,IsNull(H1.ParentId,0) AS ParentId
	FROM GENTypeCategories H1
    WHERE H1.Id = @Id   and H1.IsActive = 1
	--and Id not in (@Id)
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name ,H2.RichContent As Details,H2.Code AS String,H2.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,H2.Id) as ImageCategory,H2.Description,IsNull(H2.ParentId,0) AS ParentId
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id 
	WHERE H2.IsActive = 1
)

select res.* from (
 SELECT  'C-'+cast(RecursiveCte.Id as nvarchar(500)) as Id, (case when Parent <> '#' and RecursiveCte.Id <> @Id then 'C-'+RecursiveCte.Parent else null end ) as Parent
 ,RecursiveCte.Name, RecursiveCte.Details,RecursiveCte.String, RecursiveCte.DisplayOrdering,RecursiveCte.ImageCategory,RecursiveCte.Description,
Count(distinct GENTypes.Id) AS Countcourses,cast(sum(int1 * 60 + Int2) / 60 as int) as TotalHours
,RecursiveCte.Id as RealID,0 AS DOinMenu
from RecursiveCte 
left join GENTypes ON RecursiveCte.Id =GENTypes.TypeCategoryId and (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) 
group by RecursiveCte.Id,Parent,RecursiveCte.Name,Details,RecursiveCte.DisplayOrdering,String,ImageCategory,RecursiveCte.Description,RecursiveCte.ParentId

union all 

select 'T-'+cast(GENTypes.Id as nvarchar(500)) as Id,'C-'+cast(RecursiveCte.Id as nvarchar(500)) as Parent,GENTypes.Name
,GENTypes.RichContent as Details,GENTypes.Code as String,GENTypes.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as ImageCategory
,GENTypes.Description as Description,null as Countcourses,null as TotalHours
,GENTypes.Id as RealID,GENTypes.Int5 AS DOinMenu
from RecursiveCte 
inner join GENTypes ON RecursiveCte.Id =GENTypes.TypeCategoryId
and (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) and (GENTypes.Bool1 =1) and GENTypes.TypeCategoryId <> @Id
) as res
where Parent is not null
order by res.Id
end
GO
