CREATE PROCEDURE [dbo].[SP_GetAllTypeExamAnswerHeadersAllByContactId]  (@userId nvarchar(128), @IsJunk bit,@LangCode nvarchar(500))
AS
BEGIN
	SET NOCOUNT ON;
	SELECT        COUNT(GENExamAnswerHeaders.Id) ExamTypeCount,GENPollCategories.ExamType,dbo.FN_GetExamType(dbo.GENPollCategories.ExamType, @LangCode) AS ExamTypeName
FROM            dbo.GENExamAnswerHeaders LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENExamAnswerHeaders.ClassroomId = dbo.GENClassrooms.Id LEFT JOIN
						 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT JOIN
						 GENContacts ON dbo.GENExamAnswerHeaders.StudentId = GENContacts.Id LEFT JOIN
						 GENPollCategories ON dbo.GENExamAnswerHeaders.ExamId = GENPollCategories.Id
						 where dbo.GENExamAnswerHeaders.IsJunk = @IsJunk AND GENContacts.UserId = @userId and GENClassrooms.IsDeleted=0
GROUP BY ExamType
END
GO
