CREATE proc [dbo].[SP_GetAllTypes_ByValueId2]  (@ListValue2 bigint ,@langCode nvarchar(500),@IsLocal bit)
as
 SELECT dbo.GENTypes.Id, dbo.GENTypes.RichContent, dbo.GENTypes.Code,dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name',@langCode) as Name, 
                         dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Description',@langCode) as Description, dbo.GENTypes.ColorCode, dbo.GENTypes.IsCheckedOut, 
						 dbo.GENTypes.DateCreated, dbo.GENTypes.DateUpdated, dbo.GENTypes.CheckinDate, dbo.GENTypes.CheckoutDate, dbo.GENTypes.Timeout, 
                         dbo.GENTypes.DisplayOrdering, dbo.GENTypes.CreatedById, dbo.GENTypes.LastUpdatedById, dbo.GENTypes.CheckoutBy,
						 dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String1',@langCode)   as String1, 
						 dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String2',@langCode) as String2, 
						 dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String3',@langCode) as String3, 
						 dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String4',@langCode) as String4, 
                         dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String5',@langCode) as String5, 
						 dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS Int1, dbo.GENTypes.Int1 AS Int2, dbo.GENTypes.Int3, dbo.GENTypes.Int4, dbo.GENTypes.Int5, dbo.GENTypes.Long1, dbo.GENTypes.Long2, 
						 dbo.GENTypes.Long3, dbo.GENTypes.Long4, 
                         dbo.GENTypes.Long5, dbo.GENTypes.Float1, dbo.GENTypes.Float2, dbo.GENTypes.Float3, dbo.GENTypes.Float4, dbo.GENTypes.Float5, 
						 dbo.GENTypes.Decimal1, dbo.GENTypes.Decimal2, dbo.GENTypes.Decimal3, 
                         dbo.GENTypes.Decimal4, dbo.GENTypes.Decimal5, dbo.GENTypes.Bool1, dbo.GENTypes.Bool2, dbo.GENTypes.Bool3, dbo.GENTypes.Bool4, 
						 dbo.GENTypes.Bool5, dbo.GENTypes.Date1, dbo.GENTypes.Date2, 
                         dbo.GENTypes.Date3, dbo.GENTypes.Date4, dbo.GENTypes.Date5, dbo.GENTypes.ValueId1, dbo.GENTypes.ValueId2, dbo.GENTypes.ValueId3, 
						 dbo.GENTypes.ValueId4, dbo.GENTypes.ValueId5, dbo.GENTypes.IconId, 
                        dbo.GENTypes.IsActive, dbo.GENTypes.IsPublish, dbo.GENTypes.ExpectedCheckoutDate,dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image], 
						dbo.fnListValue_ById(GENTypes.ValueId1,@langCode) as ValueName,dbo.fnListValue_ById(GENTypes.ValueId2,@langCode) as Value2Name,
						 dbo.fn_GetPriceString_ById(28,dbo.GENTypes.Id,@langCode,@IsLocal) as PriceString, GENListValues.ColorCode AS Value1Color,
						 Value2.ColorCode AS Value2Color,
						 CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate,
	dbo.fn_FirstVideo_BaseEntityEntityId(28, dbo.GENTypes.Id) AS Video
FROM  GENTypes
LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
LEFT JOIN GENListValues ON GENTypes.ValueId1 = GENListValues.Id
LEFT JOIN GENListValues Value2 ON GENTypes.ValueId2 = Value2.Id
WHERE GENTypes.IsPublish = 1 AND GENTypes.IsActive = 1 and GENTypes.ValueId2 = @ListValue2
GROUP BY dbo.GENTypes.Id, dbo.GENTypes.RichContent, dbo.GENTypes.Code, dbo.GENTypes.ColorCode, dbo.GENTypes.IsCheckedOut, dbo.GENTypes.DateCreated, dbo.GENTypes.DateUpdated, dbo.GENTypes.CheckinDate, dbo.GENTypes.CheckoutDate, dbo.GENTypes.Timeout, 
                         dbo.GENTypes.DisplayOrdering, dbo.GENTypes.CreatedById, dbo.GENTypes.LastUpdatedById, dbo.GENTypes.CheckoutBy,
                         dbo.GENTypes.Int1, dbo.GENTypes.Int2, dbo.GENTypes.Int3, dbo.GENTypes.Int4, dbo.GENTypes.Int5, dbo.GENTypes.Long1, dbo.GENTypes.Long2, dbo.GENTypes.Long3, dbo.GENTypes.Long4, 
                         dbo.GENTypes.Long5, dbo.GENTypes.Float1, dbo.GENTypes.Float2, dbo.GENTypes.Float3, dbo.GENTypes.Float4, dbo.GENTypes.Float5, dbo.GENTypes.Decimal1, dbo.GENTypes.Decimal2, dbo.GENTypes.Decimal3, 
                         dbo.GENTypes.Decimal4, dbo.GENTypes.Decimal5, dbo.GENTypes.Bool1, dbo.GENTypes.Bool2, dbo.GENTypes.Bool3, dbo.GENTypes.Bool4, dbo.GENTypes.Bool5, dbo.GENTypes.Date1, dbo.GENTypes.Date2, 
                         dbo.GENTypes.Date3, dbo.GENTypes.Date4, dbo.GENTypes.Date5, dbo.GENTypes.ValueId1, dbo.GENTypes.ValueId2, dbo.GENTypes.ValueId3, dbo.GENTypes.ValueId4, dbo.GENTypes.ValueId5, dbo.GENTypes.IconId, 
                        dbo.GENTypes.IsActive, dbo.GENTypes.IsPublish, dbo.GENTypes.ExpectedCheckoutDate,GENListValues.ColorCode,Value2.ColorCode
ORDER BY DisplayOrdering
GO
