GO

CREATE proc [dbo].[SP_GetAllUsers] @id nvarchar(256) 
as
begin
select us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,emp.Position,cs.SubStatus
 ,dbo.countMessages(us.Id,@id) as countMessages,dbo.fnEventDate(us.UserName) as EventDate
 ,dbo.fnEventDateString(us.UserName) as EventDateString , cs.MainStatusId
, CASE
    WHEN emp.Image is null THEN '/assets/img/Avatar.webp'
	else emp.Image
  end as Image
from  AspNetUsers us
LEFT JOIN GENEmployees emp on emp.UserId = us.Id
left join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
where us.Id=@id
end
GO
/****** Object:  StoredProcedure [dbo].[SP_GetAnswerHeadersByClassroomAndExamAndInstructor]    Script Date: 7/1/2026 10:45:03 AM ******/
