GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_GetAnswerHeadersByClassroomAndExamAndInstructor] @exam_id BIGINT, @classroom_id BIGINT, @instructor_id BIGINT
AS
BEGIN
	SELECT 
	[Id]
      ,[StudentId]
      ,[StudentName]
      ,[ExamId]
      ,[ExamName]
      ,[ExamWeight]
      ,[ExamTime]
      ,[CourseId]
      ,[CourseName]
      ,[StartDateTime]
      ,[EndtDateTime]
	  ,(CASE WHEN ISNULL([AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL([TotalExamScore],0) * ISNULL([ExamWeight], 0)) / TotalScore AS decimal(18,2)) ELSE [AnnouncedDegree] END)
	  AS AnnouncedDegree
      ,[ScoreDegree]
      ,[InstructorId]
      ,[InstructorName]
      ,[TotalQuestionsNumber]
      ,[TotalExamScore]
      ,[TotalScore]
      ,[TotalNeedRevisedQuestions]
      ,[TotalNeedRevisedQuestionsScore]
      ,[TotalNoNeedRevisedQuestions]
      ,[TotalNoNeedRevisedQuestionsScore]
      ,[Code]
      ,[Name]
      ,[Description]
      ,[ColorCode]
      ,[IsCheckedOut]
      ,[DateCreated]
      ,[DateUpdated]
      ,[CheckinDate]
      ,[CheckoutDate]
      ,[ExpectedCheckoutDate]
      ,[Timeout]
      ,[DisplayOrdering]
      ,[CreatedById]
      ,[LastUpdatedById]
      ,[CheckoutBy]
      ,[String1]
      ,[String2]
      ,[String3]
      ,[String4]
      ,[String5]
      ,[Int1]
      ,[Int2]
      ,[Int3]
      ,[Int4]
      ,[Int5]
      ,[Long1]
      ,[Long2]
      ,[Long3]
      ,[Long4]
      ,[Long5]
      ,[Float1]
      ,[Float2]
      ,[Float3]
      ,[Float4]
      ,[Float5]
      ,[Decimal1]
      ,[Decimal2]
      ,[Decimal3]
      ,[Decimal4]
      ,[Decimal5]
      ,[Bool1]
      ,[Bool2]
      ,[Bool3]
      ,[Bool4]
      ,[Bool5]
      ,[Date1]
      ,[Date2]
      ,[Date3]
      ,[Date4]
      ,[Date5]
      ,[ValueId1]
      ,[ValueId2]
      ,[ValueId3]
      ,[ValueId4]
      ,[ValueId5]
      ,[IconId]
      ,[ClassroomId]
      ,[ClassroomName]
      ,[ClassroomStartTimeExam]
      ,[ClassroomEndTimeExam]
      ,[IsJunk]
      ,[ReasonString]
      ,[SubmitionStudentName]
      ,[ExpectedExamEndDate]
      ,[IsClosedByService]
      ,[IsPosted]
      ,[IP]
      ,[MACAddress]
      ,[ExamAnswerType]
      ,[TotalCorrectAnswers]
      ,[TotalWrongAnswers]
	 FROM GENExamAnswerHeaders
	WHERE GENExamAnswerHeaders.ExamId = @exam_id AND GENExamAnswerHeaders.ClassroomId = @classroom_id AND GENExamAnswerHeaders.InstructorId = @instructor_id
END
GO
