/****** Object:  StoredProcedure [dbo].[SP_GetAssessmentAnswerHeadersAllByContactId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_GetAssessmentAnswerHeadersAllByContactId](@userId nvarchar(128), @IsJunk bit,@LangCode nvarchar(500))
AS
BEGIN
	SET NOCOUNT ON;
	SELECT        dbo.GENExamAnswerHeaders.Id, dbo.GENExamAnswerHeaders.StudentId, dbo.GENExamAnswerHeaders.StudentName, dbo.GENExamAnswerHeaders.ExamId, dbo.GENExamAnswerHeaders.ExamName, 
                         dbo.GENExamAnswerHeaders.ExamWeight, dbo.GENExamAnswerHeaders.ExamTime, dbo.GENExamAnswerHeaders.CourseId, dbo.GENExamAnswerHeaders.CourseName, dbo.GENExamAnswerHeaders.StartDateTime, 
                         dbo.GENExamAnswerHeaders.EndtDateTime, (CASE
    WHEN  dbo.GENExamAnswerHeaders.AnnouncedDegree is null THEN 0
   
    ELSE dbo.GENExamAnswerHeaders.AnnouncedDegree
END
) as AnnouncedDegree,
 (CASE
    WHEN dbo.GENExamAnswerHeaders.EndtDateTime is null THEN [dbo].[FN_GetExamResultType](3, @LangCode)
   
    ELSE [dbo].[FN_GetExamResultType](4, @LangCode)
END
) as ExamStatus
,
 (CASE
    WHEN dbo.GENExamAnswerHeaders.EndtDateTime is null THEN 'red'
   
    ELSE 'green'
END
) as ExamStatusColor,
(CASE
    WHEN dbo.GENExamAnswerHeaders.EndtDateTime is null THEN cast( 0 as bit)
   
    ELSE cast(1 as bit)
END
) as CanCorrectExam, dbo.GENExamAnswerHeaders.ScoreDegree, dbo.GENExamAnswerHeaders.InstructorId, 
                         dbo.GENExamAnswerHeaders.InstructorName, dbo.GENExamAnswerHeaders.TotalQuestionsNumber, dbo.GENExamAnswerHeaders.TotalExamScore, dbo.GENExamAnswerHeaders.TotalScore, 
                         dbo.GENExamAnswerHeaders.TotalNeedRevisedQuestions, dbo.GENExamAnswerHeaders.TotalNeedRevisedQuestionsScore, dbo.GENExamAnswerHeaders.TotalNoNeedRevisedQuestions, 
                         dbo.GENExamAnswerHeaders.TotalNoNeedRevisedQuestionsScore, dbo.GENExamAnswerHeaders.Code, dbo.GENExamAnswerHeaders.Name, dbo.GENExamAnswerHeaders.Description, 
                         dbo.GENExamAnswerHeaders.ColorCode, dbo.GENExamAnswerHeaders.IsCheckedOut, dbo.GENExamAnswerHeaders.DateCreated, dbo.GENExamAnswerHeaders.DateUpdated, dbo.GENExamAnswerHeaders.CheckinDate, 
                         dbo.GENExamAnswerHeaders.CheckoutDate, dbo.GENExamAnswerHeaders.ExpectedCheckoutDate, dbo.GENExamAnswerHeaders.Timeout, dbo.GENExamAnswerHeaders.DisplayOrdering, 
                         dbo.GENExamAnswerHeaders.CreatedById, dbo.GENExamAnswerHeaders.LastUpdatedById, dbo.GENExamAnswerHeaders.CheckoutBy, dbo.GENExamAnswerHeaders.String1, dbo.GENExamAnswerHeaders.String2, 
                         dbo.GENExamAnswerHeaders.String3, dbo.GENExamAnswerHeaders.String4, dbo.GENExamAnswerHeaders.String5, dbo.GENExamAnswerHeaders.Int1, dbo.GENExamAnswerHeaders.Int2, dbo.GENExamAnswerHeaders.Int3, 
                         dbo.GENExamAnswerHeaders.Int4, dbo.GENExamAnswerHeaders.Int5, dbo.GENExamAnswerHeaders.Long1, dbo.GENExamAnswerHeaders.Long2, dbo.GENExamAnswerHeaders.Long3, dbo.GENExamAnswerHeaders.Long4, 
                         dbo.GENExamAnswerHeaders.Long5, dbo.GENExamAnswerHeaders.Float1, dbo.GENExamAnswerHeaders.Float2, dbo.GENExamAnswerHeaders.Float3, dbo.GENExamAnswerHeaders.Float4, 
                         dbo.GENExamAnswerHeaders.Float5, dbo.GENExamAnswerHeaders.Decimal1, dbo.GENExamAnswerHeaders.Decimal2, dbo.GENExamAnswerHeaders.Decimal3, dbo.GENExamAnswerHeaders.Decimal4, 
                         dbo.GENExamAnswerHeaders.Decimal5, dbo.GENExamAnswerHeaders.Bool1, dbo.GENExamAnswerHeaders.Bool2, dbo.GENExamAnswerHeaders.Bool3, dbo.GENExamAnswerHeaders.Bool4, 
                         dbo.GENExamAnswerHeaders.Bool5, dbo.GENExamAnswerHeaders.Date1, dbo.GENExamAnswerHeaders.Date2, dbo.GENExamAnswerHeaders.Date3, dbo.GENExamAnswerHeaders.Date4, dbo.GENExamAnswerHeaders.Date5,
                          dbo.GENExamAnswerHeaders.ValueId1, dbo.GENExamAnswerHeaders.ValueId2, dbo.GENExamAnswerHeaders.ValueId3, dbo.GENExamAnswerHeaders.ValueId4, dbo.GENExamAnswerHeaders.ValueId5, 
                         dbo.GENExamAnswerHeaders.IconId, dbo.GENExamAnswerHeaders.ClassroomId, dbo.GENExamAnswerHeaders.ClassroomName, dbo.GENExamAnswerHeaders.ClassroomStartTimeExam, 
                         dbo.GENExamAnswerHeaders.ClassroomEndTimeExam, dbo.Diff_BetweenDates_HoursAndMin(dbo.GENExamAnswerHeaders.StartDateTime, dbo.GENExamAnswerHeaders.EndtDateTime) AS DurationString, 
                        FORMAT(dbo.GENExamAnswerHeaders.StartDateTime, 'dd/MM/yyyy') AS StartDateTimeString,
						     FORMAT(dbo.GENExamAnswerHeaders.StartDateTime, 'hh:mm:s tt') AS StartDateTimeStringTime, FORMAT(dbo.GENExamAnswerHeaders.EndtDateTime, 'dd/MM/yyyy') AS EndDateTimeString, 
							 FORMAT(dbo.GENExamAnswerHeaders.EndtDateTime, 'hh:mm:s tt') AS EndDateTimeStringTime ,
                        (CASE
    WHEN  dbo.GENClassrooms.ClassRoomStatus =0 THEN [dbo].[FN_GetExamResultType](0, @LangCode)
    WHEN  dbo.GENClassrooms.ClassRoomStatus =1 THEN [dbo].[FN_GetExamResultType](1, @LangCode)
    WHEN  dbo.GENClassrooms.ClassRoomStatus =2 THEN [dbo].[FN_GetExamResultType](2, @LangCode)
    ELSE ''
END
)  as ClassRoomStatus, dbo.fn_Type_Translate_ByKeyandId(  dbo.GENTypes.Id,'Name', @LangCode)  as CourseName1, 
 dbo.fn_Type_Translate_ByKeyandId(dbo.GENTypes.Id,'Description', @LangCode) as CourseDescription,dbo.fn_FirstImage_BaseEntityEntityId(28, dbo.GENTypes.Id) AS CourseImage,
 dbo.GENTypes.Id AS CourseId1, dbo.fn_ItemCount_TypeId(dbo.GENTypes.Id) AS LectureCount
						 ,dbo.GENTypes.Int1 as CourseHours,  GENPollCategories.ExamType,[dbo].[FN_GetExamType]( GENPollCategories.ExamType, @LangCode) AS ExamTypeName
FROM            dbo.GENExamAnswerHeaders LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENExamAnswerHeaders.ClassroomId = dbo.GENClassrooms.Id LEFT JOIN
						 dbo.GENTypes ON dbo.GENClassrooms.CourseId = dbo.GENTypes.Id LEFT JOIN
						 GENContacts ON dbo.GENExamAnswerHeaders.StudentId = GENContacts.Id LEFT JOIN
						 GENPollCategories ON dbo.GENExamAnswerHeaders.ExamId = GENPollCategories.Id


	where dbo.GENExamAnswerHeaders.IsJunk = @IsJunk AND GENContacts.UserId = @userId AND (GENPollCategories.ExamType <> 0 OR GENPollCategories.ExamType IS NULL)
	order by DateUpdated desc

END
GO
/****** Object:  StoredProcedure [dbo].[SP_GetBlogById]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create proc [dbo].[SP_GetBlogById]    @Id bigint 
AS
Begin

select					 GENBlogs.Id,
						 GENBlogs.LikesNumber,
						 GENBlogs.DisLikesNumber,
                         GENBlogs.Text as BlogText,
                         GENBlogs.Title as BlogTitle,
                         GENBlogs.Image as BlogImage,
                         GENBlogs.Video as BlogVideo,
                         GENBlogs.Url as BlogUrl,
                        GENBlogs.Pinned,
                        GENBlogs.CreatedDate,
                        GENBlogs.UpdatedDate,
                        GENBlogs.CreatedById,
						AspNetUsers.Name as UserName,
						FORMAT(GENBlogs.CreatedDate,'dd/MM/yyyy') as DateCreatedString,
						FORMAT(GENBlogs.UpdatedDate,'dd/MM/yyyy') as DateUpdatedString ,GENTalents.Id AS TalentId ,GENTalents.Name AS TalentName

from GENBlogs inner join 

GENTalents ON GENBlogs.TalentId=GENTalents.Id left join 
AspNetUsers on GENBlogs.UserId=AspNetUsers.Id

where GENBlogs.Id=@Id

END
GO
/****** Object:  StoredProcedure [dbo].[SP_GetBlogByIdWithComments]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



create proc [dbo].[SP_GetBlogByIdWithComments]   @Id bigint  
AS
Begin

select GENBlogs.Id, GENBlogs.Text as BlogText,GENBlogs.Title as BlogTitle,GENBlogs.Image as BlogImage,
GENBlogs.Video as BlogVideo,    GENBlogs.Url as BlogUrl,GENBlogs.Pinned,GENBlogs.CreatedDate,GENBlogs.UpdatedDate,
GENBlogs.CreatedById,FORMAT(GENBlogs.CreatedDate,'dd/MM/yyyy') as DateCreatedString,
FORMAT(GENBlogs.UpdatedDate,'dd/MM/yyyy') as DateUpdatedString ,GENTalents.Id AS TalentId ,GENTalents.Name AS TalentName
from GENBlogs inner join 
GENTalents ON GENBlogs.TalentId=GENTalents.Id
where GENBlogs.Id=@Id

SELECT   GENComments.Id, GENComments.CommentText,GENComments.Video as CommentVideo,
	 GENComments.Url as CommentUrl,  GENComments.Image as CommentImage,GENComments.CreatedDate,
      GENComments.UpdatedDate,GENComments.CreatedById,GENComments.LastUpdatedById, GENBlogs.Text as BlogName,
     GENComments.ParentId, FORMAT(GENComments.CreatedDate,'dd/MM/yyyy')as CreatedDateString,
	 FORMAT(GENComments.UpdatedDate,'dd/MM/yyyy')as UpdatedDateString     
	from GENComments left join 
	GENBlogs on GENComments.BlogId=GENBlogs.Id
	where GENComments.BlogId=@Id

SELECT   GENComments.Id, GENComments.CommentText,GENComments.Video as CommentVideo,
	 GENComments.Url as CommentUrl,  GENComments.Image as CommentImage,GENComments.CreatedDate,
      GENComments.UpdatedDate,GENComments.CreatedById,GENComments.LastUpdatedById, GENBlogs.Text as BlogName,
     GENComments.ParentId, FORMAT(GENComments.CreatedDate,'dd/MM/yyyy')as CreatedDateString,
	 FORMAT(GENComments.UpdatedDate,'dd/MM/yyyy')as UpdatedDateString     
	from GENComments left join 
	GENBlogs on GENComments.BlogId=GENBlogs.Id inner join 
	GENComments comm on GENComments.Id=comm.ParentId
	where GENComments.BlogId=@Id 
	


End
GO
