/****** Object:  StoredProcedure [dbo].[Sp_GetChild_Courses_ByCategoryId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  proc [dbo].[Sp_GetChild_Courses_ByCategoryId]    (@Id bigint=null,@langCode nvarchar(500) )
as  
Begin
WITH RecursiveCte AS
(
    SELECT H1.Id as CourseId,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    , dbo.fn_TypeCategories_Translate_ByKeyandId(H1.Id,'Name',@langCode) AS CourseName,IsActive,IsPublish,H1.ParentId,H1.ID as GrandParent,H1.DisplayOrdering FROM GENTypeCategories H1
    WHERE H1.Id = @Id and IsDeleted = 0
    UNION ALL
    SELECT H2.Id as CourseId,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,dbo.fn_TypeCategories_Translate_ByKeyandId(H2.Id,'Name',@langCode) AS CourseName ,H2.IsActive,H2.IsPublish,H2.ParentId,RCTE.ParentId as GrandParent,H2.DisplayOrdering FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.CourseId
	where  IsDeleted = 0
)
select RecursiveCte.* from RecursiveCte 
where (RecursiveCte.IsActive =1) AND (RecursiveCte.IsPublish =1)  and ParentId <> @Id  and CourseId <> @Id
order by DisplayOrdering,CourseId

end
