CREATE   PROCEDURE [dbo].[SP_GetClassroomsByInstructorId]
    @InstructorId BIGINT
AS
BEGIN
    SELECT DISTINCT c.Id, c.Code, c.Name
    FROM GENClassrooms c
    INNER JOIN TLMSClassroom_Session s ON s.ClassroomId = c.Id
    WHERE c.IsActive = 1
    AND c.IsDeleted = 0
    AND s.InstructorId = @InstructorId
	and c.IsPublish = 1
END;
