/****** Object:  StoredProcedure [dbo].[SP_GetClassRoomSessionsByClassRoomId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE  [dbo].[SP_GetClassRoomSessionsByClassRoomId] --  [SP_GetClassRoomSessionsByClassRoomId] 42580
	@ClassRoomId bigint
AS
BEGIN
	
	SET NOCOUNT ON;
	SELECT TLMSClassroom_Session.Id, GENItems.Name as SessionName,(SELECT STRING_AGG(E.Name + '(' + E.Position + ')', ' - ') 
         FROM Classroom_Session_Instructor SI
         JOIN GENEmployees E ON SI.InstructorId = E.Id
         WHERE SI.SessionId = TLMSClassroom_Session.Id) as InstructorName,GENClassrooms.Name as ClassroomName ,TLMSClassroom_Session.SessionDateTime,
	TLMSClassroom_Session.FromDateTime,TLMSClassroom_Session.ToDateTime,'' AS EmpPostion,
   dbo.FN_ConvertDaystoArabic((' '+ Datename(weekday, TLMSClassroom_Session.SessionDateTime)  +CHAR(13)+CHAR(10)+
	FORMAT(TLMSClassroom_Session.SessionDateTime,'dd/MM/yyyy')),'ar') as SessionDateTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(TLMSClassroom_Session.FromDateTime,'hh:mm'),'ar') as FromDateTimeString,
	 dbo.FN_ConvertDaystoArabic(FORMAT(TLMSClassroom_Session.ToDateTime,'hh:mm'),'ar') as ToDateTimeString,
	GENClassrooms.FromDateTime as ClassroomFromDateTime,GENClassrooms.ToDateTime as ClassroomToDateTime
	,TLMSClassroom_Session.Name as Name,cast(res.RowNum as nvarchar(500)) as RowNum,cast(res.RowNum as nvarchar(500)) as [LineNo]
	,TLMSClassroom_Session.TypeSession
	,TLMSClassroom_Session.InstructorInstructions
	,TLMSClassroom_Session.InteractiveMeetingURL
	,GENClassrooms.InstructorInstructions as Remarks
	,Course.Name as CourseName
	,GENClassrooms.Code as ClassroomCode
	,Lang.Name as LangName
	,GENClassrooms.FromDateTime as ClassroomsFromDateTime
	,GENClassrooms.ToDateTime as ClassroomsToDateTime
	,Room.Name as RoomName
	,Room.Code as Roomcode
	,GENClassrooms.String1 as EmpName
	,dbo.GENClassrooms.ClassRoomShift
	,(CASE WHEN dbo.GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' WHEN dbo.GENClassrooms.ClassRoomShift = 1 THEN N'مسائي' ELSE N'' END ) AS ClassRoomShiftString
	,isnull(Course.Int2,0) as HourCount
	,datediff(Day,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime)+1 as ClassroomsDay,
	   dbo.FN_ConvertNumbertoArabic((SELECT count(*) from GENClassroom_GENContact where ClassroomId = @ClassRoomId and BookingTypeId =1)+ isnull(GENClassrooms.int1,0))  as ContactCount,
ROUND((case when GENEntityPricings.PriceType = 1 and (PaymentCondation = 0 or ClassroomCategoryId = 2) then isnull(GENEntityPricings.NetPrice,0)
when GENEntityPricings.PriceType = 1 and (PaymentCondation = 1 or ClassroomCategoryId = 2) 
then isnull(GENEntityPricings.NetPrice,0) else Cast(0 as decimal(18,4)) end)
* (isnull(ClassroomContact.StudentCount,0) + isnull(GENClassrooms.int1,0) ),2)  AS ClassRoomPay
	from TLMSClassroom_Session left join 
	GENItems on TLMSClassroom_Session.SessionId=GENItems.Id left join 
	GENClassrooms on TLMSClassroom_Session.ClassroomId=GENClassrooms.Id left join 
	(SELECT Datename(weekday, TLMSClassroom_Session.SessionDateTime)  +' '+
	FORMAT(TLMSClassroom_Session.SessionDateTime,'dd/MM')   as SessionDateTimeString,
	  ROW_NUMBER() OVER (ORDER BY SessionDateTime) as RowNum,SessionDateTime
	from TLMSClassroom_Session left join 
	GENItems on TLMSClassroom_Session.SessionId=GENItems.Id left join 
	GENClassrooms on TLMSClassroom_Session.ClassroomId=GENClassrooms.Id 
	where TLMSClassroom_Session.ClassroomId=@ClassRoomId
	group by SessionDateTime
	) res on res.SessionDateTime = TLMSClassroom_Session.SessionDateTime
	left join (
	select GENClassroom_GENContact.ClassroomId,count(distinct case when GENClassroom_GENContact.BookingTypeId = 1 then GENClassroom_GENContact.StudentId end) as StudentCount from GENClassroom_GENContact
	where GENClassroom_GENContact.ClassroomId=@ClassRoomId 
		group by GENClassroom_GENContact.ClassroomId
	) as ClassroomContact on ClassroomContact.ClassroomId = GENClassrooms.id
	left join GENTypes Course on GENClassrooms.CourseId = Course.Id
	left join GENListValues Lang on GENClassrooms.LanguageId = Lang.Id
	left join [GENRooms] Room on GENClassrooms.RoomId = Room.Id
	left join [GENEmployees] Emp on GENClassrooms.InstructorId = Emp.Id
	left join GENEntityPricings on GENEntityPricings.EntityId = GENClassrooms.id and BaseEntityId = 176 and GENEntityPricings.PriceType = 1
	where TLMSClassroom_Session.ClassroomId=@ClassRoomId
	order by cast(TLMSClassroom_Session.SessionDateTime as date ),TLMSClassroom_Session.FromDateTime,TLMSClassroom_Session.ToDateTime
END
GO
