END;

	 CREATE TABLE #LanguagePercentage (
    Id INT,
    Name NVARCHAR(255),  -- Adjust the length based on your actual data needs
    TotalStudent INT,
    Percentage NVARCHAR(50)  -- Adjust the length based on your actual data needs
);
truncate table LanguagePercentage
INSERT INTO LanguagePercentage (Id, Name, TotalStudent, Percentage)
SELECT 
    GENListValues.Id,
    GENListValues.Name,
    COUNT(DISTINCT GENcontacts.Id) AS TotalStudent,
    CONCAT(
        CAST(
            CAST(
                CAST(
                    (CAST(COUNT(DISTINCT GENcontacts.Id) AS DECIMAL(18,4)) / 
                    (SELECT COUNT(DISTINCT GENcontacts.Id) 
                     FROM GENcontacts 
                     INNER JOIN GENListValues ON GENcontacts.LanguageId = GENListValues.Id
                     WHERE GENcontacts.isdeleted = 0)
                    ) AS DECIMAL(18,4)
                ) * CAST(100 AS DECIMAL(18,4)) AS DECIMAL(18,2)
            ) AS NVARCHAR(MAX)
        ), '%' 
    ) AS Percentage
FROM 
    GENcontacts
INNER JOIN 
    GENListValues ON GENcontacts.LanguageId = GENListValues.Id
WHERE 
    GENcontacts.isdeleted = 0 
GROUP BY 
    GENListValues.Id, GENListValues.Name
having GENListValues.Name != '';
	
SELECT TOP 1 @MostLangCount = percentage, @MostLangName = Name
FROM LanguagePercentage  -- Assuming #LanguagePercentage is your temporary table
ORDER BY percentage DESC;


SELECT TOP 1 @LessLanguageCount = percentage,@LessLanguageName = Name
FROM LanguagePercentage  -- Assuming #LanguagePercentage is your temporary table
ORDER BY percentage ASC ;
	 
	 select @Contact_HaveVCR = count(distinct c.Id)
from GenClassrooms g   
