     or (len(@DateF) = 0 and len(@DateTo) = 0))

	--select @Contact_HaveVCR =  count(distinct dbo.GENContacts.Id) 
	--FROM
	-- dbo.GENContacts
	-- WHERE dbo.GENContacts.id in (select dbo.GENClassroom_GENContact.StudentId from  GENClassroom_GENContact
	--  inner join GENClassrooms on GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
	--  where GENClassroom_GENContact.BookingTypeId=1 and GENClassrooms.IsDeleted = 0 and GENClassrooms.ClassRoomStatus = 2 and GENClassrooms.ClassroomCategoryId = 1)
	--AND 
	--((cast(GENContacts.DateCreated as date) >= cast(@DateF as date) and cast(GENContacts.DateCreated as date) <= cast(@DateTo as date)) 
 --    or (@DateF is null and @DateTo is null and ((cast(GENContacts.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENContacts.DateCreated as date) <= cast(GETDATE() as date)) ) )
 --    or (len(@DateF) = 0 and len(@DateTo) = 0));

	--	select @Contact_NotHaveVCR =  count(*) 
	--FROM
	-- dbo.GENContacts
	-- WHERE  GENContacts.IsDeleted = 0 and IsResponsibleDestinations = 0 
	-- and dbo.GENContacts.id not in (select dbo.GENClassroom_GENContact.StudentId from  GENClassroom_GENContact where GENClassroom_GENContact.BookingTypeId=1)
	--AND 
	--((cast(GENContacts.DateCreated as date) >= cast(@DateF as date) and cast(GENContacts.DateCreated as date) <= cast(@DateTo as date)) 
 --    or (@DateF is null and @DateTo is null and ((cast(GENContacts.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENContacts.DateCreated as date) <= cast(GETDATE() as date)) ) )
 --    or (len(@DateF) = 0 and len(@DateTo) = 0));
 
		 select @Contact_NotHaveVCR =count(distinct GENContacts.Id)
from GENContacts  
where GENContacts.id not in (select c.Id
from GenClassrooms g   
inner join GENClassroom_GENContact cc on cc.classroomId = g.Id and cc.BookingTypeId = 1
inner join GENContacts c on c.Id = cc.StudentId 
where g.ClassroomCategoryId = 1 and g.IsDeleted = 0 and g.ClassRoomStatus = 2 and  c.IsDeleted = 0 and C.IsResponsibleDestinations = 0  --and cc.IsConfirmed =1 
and
((cast(g.FromDateTime as date) >= cast(@DateF as date) and cast(g.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(g.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(g.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0)))and  GENContacts.IsDeleted = 0 and GENContacts.IsResponsibleDestinations = 0 


	-- from(
	--select C.id,dbo.fnCount_VcrsByContactId(c.Id) as VCRCount from GenContacts C 
	--where c.IsDeleted = 0 and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
 --    or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
 --    or (len(@DateF) = 0 and len(@DateTo) = 0))
	--) as res
	--where VCRCount = 0 ;

select top 1 @MostDirectionFrequentlyName =  isnull(gencompanyTypes.Name,N'أخري'),  
@MostDirectionFrequentlyCount = count(distinct GENcontacts.Id)  
from GENcontacts 
left join GENCompanies on GENcontacts.CompanyId = GENCompanies.Id
left join GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id
where GENcontacts.isdeleted=0 
and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) 
or (@DateF is null and @DateTo is null and ((cast(GENCompanies.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENCompanies.DateCreated as date) <= cast(GETDATE() as date)) 
or (cast(GENCompanies.DateCreated as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENCompanies.DateCreated as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)))
group by gencompanyTypes.Name
ORDER BY count(distinct GENcontacts.Id)   DESC,gencompanyTypes.Name ASC;
---------------------------------------
select top 1 @LessDirectionFrequentlyName =  isnull(gencompanyTypes.Name,N'أخري'),  
@LessDirectionFrequentlyCount = count(distinct GENcontacts.Id)  
from GENcontacts 
left join GENCompanies on GENcontacts.CompanyId = GENCompanies.Id
left join GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id
where GENcontacts.isdeleted=0 
and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) 
or (@DateF is null and @DateTo is null and ((cast(GENCompanies.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENCompanies.DateCreated as date) <= cast(GETDATE() as date)) 
or (cast(GENCompanies.DateCreated as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENCompanies.DateCreated as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)))
group by gencompanyTypes.Name
ORDER BY count(GENCompanies.Id) ASC,gencompanyTypes.Name ASC;
	
    SELECT @AllNoRegister = COUNT(*) FROM GENContacts c WHERE IsDeleted = 0 and IsResponsibleDestinations = 0  and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

    SELECT @EgyptianRegister =  COUNT(*) from GEnContacts c
    inner join GENAddresses on GENAddresses.entityid = c.id and GENAddresses.baseentityid = 47 
	inner join GENCountries on GENCountries.id = GENAddresses.CountryId and GENAddresses.CountryId = 1
	WHERE c.IsDeleted = 0
	and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))

	SELECT @Male = COUNT(*) FROM GENContacts c 
	WHERE c.IsDeleted = 0  and GenderId = 34616 
	and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))

	SELECT @Female = COUNT(*) FROM GENContacts c WHERE IsDeleted = 0  and GenderId = 34681 
	and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))

	 ----------------------------------------------------
	 IF OBJECT_ID('tempdb..#AgeGroupContacts') IS NOT NULL
BEGIN
    DROP TABLE #AgeGroupContacts;
END;

CREATE TABLE #AgeGroupContacts (
    AgeGroup NVARCHAR(10),
    Percentage DECIMAL(10, 2)
);
truncate table AgeGroupContacts
INSERT INTO AgeGroupContacts (AgeGroup, Percentage)
SELECT
    CASE
         WHEN Age <= 30 THEN '20-30'
        WHEN Age <= 40 THEN '30-40'
        WHEN Age <= 60 THEN '40-60'
        ELSE '> 60'
    END AS AgeGroup,
    ROUND(CAST(count(age) * 100.0 / SUM(count(age)) OVER() AS DECIMAL(10, 2)), 2) AS Percentage
FROM
    (SELECT
        DATEDIFF(YEAR, c.BirthDate, GETDATE()) - 
        CASE 
            WHEN DATEADD(YEAR, DATEDIFF(YEAR, BirthDate, GETDATE()), BirthDate) > GETDATE() 
            THEN 1 
            ELSE 0 
        END AS Age
    FROM
        GENcontacts c
    WHERE c.isdeleted = 0 AND BirthDate IS NOT NULL  and 
	((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
    ) AS AgeQuery
GROUP BY
    CASE
        WHEN Age <= 30 THEN '20-30'
        WHEN Age <= 40 THEN '30-40'
        WHEN Age <= 60 THEN '40-60'
        ELSE '> 60'
    END;

-- Optional: Select data from the temporary table to verify the results

	 ----------------------------------------------------

	SELECT top 1 @MostAgeGroupName =  AgeGroup ,@MostAgeGroupPercentage =  Percentage
	FROM AgeGroupContacts
	ORDER BY Percentage DESC;


	SELECT top 1 @LessAgeGroupPercentage = Percentage,@LessAgeGroupName =  AgeGroup 
	FROM AgeGroupContacts
	ORDER BY Percentage Asc;
   

  SELECT TOP 1
        @HigherQualificationCount = COUNT(*),
        @HigherQualificationName = GENListValues.Name
    FROM 
        GENContacts c
    INNER JOIN 
        GENListValues ON GENListValues.Id = c.QualificationId
    WHERE c.isdeleted = 0 and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
    GROUP BY 
        QualificationId, GENListValues.Name
    ORDER BY 
        COUNT(*) DESC,GENListValues.Name;
--******************************
	SELECT TOP 1
        @LowerQualificationCount = COUNT(*),
        @LowerQualificationName = GENListValues.Name
    FROM 
        GENContacts c
    INNER JOIN 
        GENListValues ON GENListValues.Id = c.QualificationId
    WHERE c.isdeleted = 0 and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
    GROUP BY 
        QualificationId, GENListValues.Name
    ORDER BY 
        COUNT(*) ASC,GENListValues.Name asc;
		--**************************
	SELECT TOP 1 
		@HigherGovernorateName = GenCities.Name
	From
		GENContacts c
	INNER JOIN GENAddresses ON GENAddresses.entityid = c.id 
	INNER JOIN GenCities ON GenCities.Id = GENAddresses.CityId
	WHERE GENAddresses.baseentityid = 47 and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	GROUP BY GENAddresses.CityId, GenCities.Name
	ORDER By COUNT(*) DESC;
	--********************************
	SELECT TOP 1 
		@LowerGovernorateName = GenCities.Name
	From
		GENContacts c
	INNER JOIN GENAddresses ON GENAddresses.entityid = c.id 
	INNER JOIN GenCities ON GenCities.Id = GENAddresses.CityId
	WHERE GENAddresses.baseentityid = 47 and ((cast(c.DateCreated as date) >= cast(@DateF as date) and cast(c.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	GROUP BY GENAddresses.CityId, GenCities.Name
	ORDER By COUNT(*) ASC;

	SELECT 
        @AllNoRegister AS AllNoRegister,
        @EgyptianRegister AS EgyptianRegister,
          CASE 
        WHEN @AllNoRegister = 0 THEN '0%'
        ELSE CONCAT(Round(CAST(@EgyptianRegister AS FLOAT) / @AllNoRegister * 100,2), '%')
    END AS RegisterRatio,
    
    CASE 
        WHEN (@Male + @Female) = 0 THEN '0%'
        ELSE CONCAT(Round(CAST(@Male AS FLOAT) / (@Male + @Female)  * 100,2), '%')
    END AS MalePercentage,
    
    CASE 
        WHEN (@Male + @Female) = 0 THEN '0%'
        ELSE CONCAT(Round(CAST(@Female AS FLOAT) / (@Male + @Female) * 100,2), '%')
    END AS FemalePercentage,
    
    @MostAgeGroupName as MostAgeGroupName,
    @LessAgeGroupName as LessAgeGroupName,
    @MostAgeGroupPercentage as MostAgeGroupPercentage,
    @LessAgeGroupPercentage as LessAgeGroupPercentage , 
		@MostLangCount as MostLangCount,
		@MostLangName as MostLangName,
		@LessLanguageName as LessLanguageName,
		@LessLanguageCount as LessLanguageCount,
        @HigherQualificationName AS HigherQualification,
		 CONCAT(Round(CAST(@HigherQualificationCount AS FLOAT) / 
		(select count(distinct GENcontacts.Id) from GENcontacts 
			inner join GENListValues on GENcontacts.QualificationId = GENListValues.Id
			where GENcontacts.isdeleted=0)*100
		,2), '%')AS HigherQualificationPercentage,
		CONCAT(Round(CAST(@LowerQualificationCount AS FLOAT) / 
		(select count(distinct GENcontacts.Id) from GENcontacts 
			inner join GENListValues on GENcontacts.QualificationId = GENListValues.Id
			where GENcontacts.isdeleted=0)*100
		,2), '%') AS LowerQualificationPercentage,
        @LowerQualificationName AS LowerQualification,
        @LowerQualificationCount AS LowerQualificationCount,

		@HigherGovernorateName As HigherGovernorateName,

		@LowerGovernorateName As LowerGovernorateName, 
	    @MostDirectionFrequentlyName as MostDirectionFrequentlyName,
	    @MostDirectionFrequentlyCount as MostDirectionFrequentlyCount,
	    @LessDirectionFrequentlyName as LessDirectionFrequentlyName ,
	    @LessDirectionFrequentlyCount as LessDirectionFrequentlyCount,
	    @Contact_HaveVCR as  Contact_HaveVCR,
	    @Contact_NotHaveVCR as Contact_NotHaveVCR ,
	    2 as DataSetNo;




END
GO
