/****** Object:  StoredProcedure [dbo].[SP_GetCountsRegisterStudents_Dest]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_GetCountsRegisterStudents_Dest]
AS
Begin

Select Count(GENContacts.Id) AS TotalDest 
from GENContacts inner join 
--GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 
--GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id inner join 
GENCompanies ON GENContacts.CompanyId=GENCompanies.Id 
where GENContacts.isdeleted=0 
--and GENClassrooms.isdeleted=0



Select Count(GENCompanies.Id) AS EgyptionsDest
from GENContacts inner join 
GENCompanies ON GENContacts.CompanyId=GENCompanies.Id inner join
GENAddresses nation ON GENContacts.Id=nation.entityId and nation.baseEntityId=47 inner join 

GENCountries ON nation.countryId=GENCountries.Id
where GENContacts.isdeleted=0 and  nation.CountryId=1




Select Count(GENCompanies.Id) AS ForeignDest 
from GENContacts inner join 
GENCompanies ON GENContacts.CompanyId=GENCompanies.Id inner join
GENAddresses nation ON GENContacts.Id=nation.entityId and nation.baseEntityId=47 inner join 

GENCountries ON nation.countryId=GENCountries.Id
where GENContacts.isdeleted=0 and  nation.CountryId<>1




Select Count(GENCompanies.Id) AS CountGovernmental 
from GENContacts inner join 

GENAddresses nation ON GENContacts.Id=nation.entityId and nation.baseEntityId=47 inner join 
GENCompanies ON GENContacts.CompanyId=GENCompanies.Id inner join
GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id inner join
GENListValues ON GENCompanyTypes.ValueId1=GENListValues.Id
where GENContacts.isdeleted=0 and  GENListValues.Id =77227







Select Count(GENCompanies.Id) AS CountPrivate
from GENContacts inner join 

GENCompanies ON GENContacts.CompanyId=GENCompanies.Id inner JOIN 
GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id inner join
GENListValues ON GENCompanyTypes.ValueId1=GENListValues.Id
where GENContacts.isdeleted=0 and GENListValues.Id =77226



Select Count(GENCompanies.Id) AS CountCivilSociety
from GENContacts inner join 
GENCompanies ON GENContacts.CompanyId=GENCompanies.Id inner JOIN 
GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id inner join
GENListValues ON GENCompanyTypes.ValueId1=GENListValues.Id
where GENContacts.isdeleted=0 and  GENListValues.Id =77229


END
GO
