AND (@CompanyId IS NULL OR GENContacts.CompanyId =@CompanyId)
AND (@CompanyTypeId IS NULL OR GENCompanyTypes.Id =@CompanyTypeId)
AND (@QualificationId IS NULL OR GENContacts.QualificationId =@QualificationId)
AND (@FromDate IS NULL OR len(@FromDate) = 0 OR  @FromDate<=cast(GENContacts.DateCreated as date))
AND (@ToDate IS NULL OR len(@ToDate) = 0 OR  cast(GENContacts.DateCreated as date)<=@ToDate)
AND (GENContacts.Name like '%'+@StudentName+'%' or @StudentName is null or len(@StudentName) =0)
AND (GENContacts.DefaultPhone like '%'+@StudentMobile+'%' or @StudentMobile is null or len(@StudentMobile) =0)
AND (GENContacts.DefaultEmail like '%'+@StudentEmail+'%' or @StudentEmail is null or len(@StudentEmail) =0)
AND (GENContacts.Position like '%'+@StudentPostion+'%' or @StudentPostion is null or len(@StudentPostion) =0)
AND (GENContacts.DefaultAddress like '%'+@StudentAddress+'%' or @StudentAddress is null or len(@StudentAddress) =0)
AND (GENContacts.Qualification_Name like '%'+@StudentQualificationName+'%' or @StudentQualificationName is null or len(@StudentQualificationName) =0)

AND (@CompanyTypeIds IS NULL OR  len(@CompanyTypeIds) =0 or GENCompanyTypes.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CompanyTypeIds, ',')))
AND (@QualificationIds IS NULL OR len(@QualificationIds) =0 or GENContacts.QualificationId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@QualificationIds, ',')))
AND (@NationalityIds IS NULL OR len(@NationalityIds) =0 or GENCountries.Id IN (SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@NationalityIds, ',')))


	END
GO
/****** Object:  StoredProcedure [dbo].[Sp_GetCourses_ByCategoryId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  proc [dbo].[Sp_GetCourses_ByCategoryId]   (@Id bigint=null,@langCode nvarchar(500) )
as  
Begin

WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE H1.Id = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
select RecursiveCte.*,GENTypes.Id As CourseId,GENTypes.Int5 As DOinMenu,dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name',@langCode) As CourseName from RecursiveCte 
inner join GENTypes ON RecursiveCte.Id =GENTypes.TypeCategoryId
where (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) AND (GENTypes.Bool1 =1)
order by Id
end
GO
/****** Object:  StoredProcedure [dbo].[Sp_GetCoursesByCategoryId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  proc [dbo].[Sp_GetCoursesByCategoryId]   (@Id bigint=null)
as  
Begin

WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE H1.Id = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
select distinct GENTypes.*,
GENTypes.Name,GENTypes.Code,GENTypes.Int2,GENTypes.Description,
GENTypes.RichContent,GENTypes.IsActive,GENTypes.IsPublish,GENTypes.CreatedById,FORMAT(GENTypes.DateCreated,'dd/MM/yyyy') as DateCreatedString,
FORMAT(GENTypes.DateUpdated,'dd/MM/yyyy') as DateUpdatedString,FORMAT(GENTypes.DateCreated,'hh:mm tt') as TimeCreatedString
,FORMAT(GENTypes.DateUpdated,'hh:mm tt') as TimeUpdatedString,
GENTypes.Description,GENTypes.Description,CourseCategories.CategoryId as CategoryId 
from CourseCategories 
inner join  RecursiveCte ON CourseCategories.CategoryId =RecursiveCte.Id inner join 
GENTypes ON CourseCategories.CourseId=GENTypes.Id
where (@Id = 0 or CourseCategories.CategoryId = @Id)
--where (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1)  and GENTypes.isdeleted=0
order by Id

end
GO
/****** Object:  StoredProcedure [dbo].[Sp_GetCoursesByCategoryId_ArchiveCourses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create  proc [dbo].[Sp_GetCoursesByCategoryId_ArchiveCourses]   (@Id bigint=null)
as  
Begin

WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name FROM GENTypeCategories H1
    WHERE H1.Id = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H2.Name FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
)
select GENTypes.*,
GENTypes.Name,GENTypes.Code,GENTypes.Int2,GENTypes.Description,
GENTypes.RichContent,GENTypes.IsActive,GENTypes.IsPublish,GENTypes.CreatedById,FORMAT(GENTypes.DateCreated,'dd/MM/yyyy') as DateCreatedString,
FORMAT(GENTypes.DateUpdated,'dd/MM/yyyy') as DateUpdatedString,FORMAT(GENTypes.DateCreated,'hh:mm tt') as TimeCreatedString
,FORMAT(GENTypes.DateUpdated,'hh:mm tt') as TimeUpdatedString,
GENTypes.Description,GENTypes.Description
from CourseCategories 
inner join  RecursiveCte ON CourseCategories.CategoryId =RecursiveCte.Id inner join 
GENTypes ON CourseCategories.CourseId=GENTypes.Id
where (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1)  and GENTypes.isdeleted=1
order by Id

end
