Create Proc [dbo].[Sp_GetDefaultPrice](@LangCode nvarchar(500),@BaseEntityId bigint,@EntityId bigint)

as
SELECT top(1)  *,dbo.fn_Currency_Translate_ByKeyandId(CurrencyId,'Name',@LangCode) as CurrencyName
