GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_GetDistinctTalentTypesByProsecutionId]
    @ProsecutionId BIGINT
AS
BEGIN
    SELECT DISTINCT gt.Id, gt.Code, gt.Name
    FROM gentypes gt
    INNER JOIN genclassrooms gc ON gc.CourseId = gt.Id
    WHERE gc.ProsecutionId = @ProsecutionId;
END;
GO
