CREATE proc [dbo].[SP_GetGroupMessages] @GroupId BIGINT,@BaseEntityId bigint
as 
begin
--create view Last20Messages as
Declare @tempMessages table(id bigint,MessageTime datetime,MessageText nvarchar(max),UserSenderId nvarchar(max),UserReceiverId nvarchar(max),
usernameRE nvarchar(max),UsernameSe nvarchar(max),ticketId BIGINT,IsReceived bit,IsSeen bit,Image nvarchar(max),ChatEntityId bigint,ChatEntityPoPId bigint,ChatEntityUrl nvarchar(max),
IsForwarded BIT,IsReply BIT,IsReceiverDeleted BIT,IsSenderDeleted BIT, OriginalMessageId BIGINT, ReplyMessageText nvarchar(max), ReplyMessageSenderId nvarchar(max), ReplyMessageSenderName nvarchar(max))



insert into @tempMessages 
select m.Id Id ,m.MessageTime ,m.MessageText ,m.UserSenderId,m.UserReceiverId ,users.Name usernameRE ,userSEnder.Name UsernameSe,M.ticketId ticketId,
m.IsReceived,m.IsSeen, GENEmployees.Image ,m.ChatEntityId,m.ChatEntityPoPId,m.ChatEntityUrl,m.IsForwarded,m.IsReply,m.IsReceiverDeleted,m.IsSenderDeleted, m.OriginalMessageId,
rm.MessageText AS ReplyMessageText, rm.UserSenderId AS ReplyMessageSenderId, senderUser.Name AS ReplyMessageSenderName
from GENChatMessages m
left join AspNetUsers users on users.Id=m.UserReceiverId 
left join AspNetUsers userSEnder on userSEnder.Id=m.UserSenderId 
LEFT JOIN GENEmployees on userSEnder.Id = GENEmployees.UserId
LEFT JOIN GENChatMessages rm on rm.Id = m.OriginalMessageId
LEFT JOIN AspNetUsers senderUser on senderUser.Id = rm.UserSenderId
where m.ChatGroupId = @GroupId

ORDER BY m.Id DESC;

select  tm.Id Id ,[dbo].[fn_MessageTime](tm.MessageTime) as MessageTimeString, FORMAT(tm.MessageTime,'hh:mm tt') as OneMessageTime,tm.MessageTime as MessageTime,tm.MessageText ,tm.UserSenderId,tm.UserReceiverId ,tm.usernameRE UsernameRE ,tm.UsernameSe UsernameSe,TM.ticketId AS TicketId, 
tm.IsReceived,tm.IsSeen,gi.AzureUri,gi.EntityId,gi.Id as ImageId, gi.Name,gf.AzureUri FileAzureUri,gf.BaseEntityId FileBaseEntityId,gf.Id as FileId ,gf.FileName FileName, tm.Image,tm.ChatEntityId,tm.ChatEntityPoPId,tm.ChatEntityUrl
,tm.IsForwarded,tm.IsReply,tm.IsReceiverDeleted,tm.IsSenderDeleted, tm.OriginalMessageId,
tm.ReplyMessageText, tm.ReplyMessageSenderId, tm.ReplyMessageSenderName,rgi.AzureUri AS ReplyAzureUri, rgi.Name AS ReplyImageName,
rgf.AzureUri ReplyFileAzureUri,rgf.FileName ReplyFileName
from @tempMessages tm
LEFT JOIN GENImages gi ON gi.BaseEntityId=@BaseEntityId and gi.EntityId=tm.id
LEFT JOIN GENFiles gf ON gf.BaseEntityId=@BaseEntityId and gf.EntityId=tm.id
OUTER APPLY 
(SELECT TOP 1 AzureUri, Name
 FROM GENImages 
 WHERE BaseEntityId=@BaseEntityId AND EntityId = tm.OriginalMessageId
 ORDER BY Id DESC
) AS rgi
OUTER APPLY 
(SELECT TOP 1 AzureUri, FileName
 FROM GENFiles 
 WHERE BaseEntityId=@BaseEntityId AND EntityId = tm.OriginalMessageId
 ORDER BY Id DESC
) AS rgf
order by tm.id asc;
end
GO
