/****** Object:  StoredProcedure [dbo].[Sp_GetInstructorsAttendees]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[Sp_GetInstructorsAttendees] @UserId nvarchar(256),@Id bigint,@searchtext nvarchar(50)
AS
Begin
Select DISTINCT GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,GENContacts.Position,
us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,cs.SubStatus ,dbo.countMessages(us.Id,@UserId) as countMessages,[dbo].[tfn_fnEventDate].EventDate,
[dbo].[tfn_fnEventDate].EventDateString , cs.MainStatusId
, CASE
    WHEN GENContacts.Image is null THEN null
	else GENContacts.Image
  end as Image, 'Contact' AS UserType
from 
GENContacts LEFT OUTER JOIN
GENClassroom_GENContact ON GENClassroom_GENContact.StudentId=GENContacts.Id LEFT OUTER JOIN
GENClassrooms ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
LEFT JOIN AspNetUsers us on GENContacts.UserId=us.Id
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
CROSS APPLY [dbo].[tfn_fnEventDate](us.UserName)
where GENContacts.Id <> @Id and  FromDateTime < GETDATE() and ToDateTime > GETDATE() AND GENClassrooms.IsActive = 1 AND GENClassrooms.Id IN (SELECT ClassroomId FROM GENClassroom_GENContact WHERE StudentId = @Id AND IsConfirmed = 1)and (GENContacts.Name like  '%'+@searchtext+'%' or @searchtext IS NULL ) And (us.Id!=@UserId)

UNION 

Select DISTINCT GENEmployees.Email AS DefaultEmail,GENEmployees.Telephone AS DefaultPhone,GENEmployees.Address AS DefaultAddress,GENEmployees.Position, 
 us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,cs.SubStatus ,dbo.countMessages(us.Id,@UserId) as countMessages,[dbo].[tfn_fnEventDate].EventDate,
[dbo].[tfn_fnEventDate].EventDateString , cs.MainStatusId
, CASE
    WHEN GENEmployees.Image is null THEN null
	else GENEmployees.Image
  end as Image, 'Employee' AS UserType
from 
GENEmployees LEFT OUTER JOIN
GENClassrooms ON GENClassrooms.InstructorId=GENEmployees.Id LEFT JOIN
GENClassroom_GENContact ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
LEFT JOIN AspNetUsers us on GENEmployees.UserId=us.Id
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
CROSS APPLY [dbo].[tfn_fnEventDate](us.UserName)
where  FromDateTime < GETDATE() and ToDateTime > GETDATE() AND GENClassrooms.IsActive = 1 AND GENClassrooms.Id IN (SELECT ClassroomId FROM GENClassroom_GENContact WHERE StudentId = @Id  AND IsConfirmed = 1) and (GENEmployees.Name like  '%'+@searchtext+'%' or @searchtext IS NULL ) And (us.Id!=@UserId)  

End
GO
