CREATE proc [dbo].[Sp_GetInstructorsAttendeesEmail] @Id bigint
AS
Begin
Select DISTINCT GENContacts.DefaultEmail,GENContacts.Name,GENContacts.DefaultPhone,GENContacts.DefaultAddress,GENContacts.Position, dbo.GENContacts.Image
from 
GENContacts LEFT OUTER JOIN
GENClassroom_GENContact ON GENClassroom_GENContact.StudentId=GENContacts.Id LEFT OUTER JOIN
GENClassrooms ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
where GENContacts.Id <> @Id and  FromDateTime < GETDATE() and ToDateTime >= GETDATE() AND 
GENClassrooms.IsActive = 1 AND GENClassrooms.Id IN (SELECT ClassroomId FROM GENClassroom_GENContact WHERE StudentId = @Id AND IsConfirmed = 1)

UNION 

Select DISTINCT GENEmployees.Email AS DefaultEmail,GENEmployees.Name,GENEmployees.Telephone AS DefaultPhone,GENEmployees.Address AS DefaultAddress,GENEmployees.Position, 
dbo.GENEmployees.Image
from 
GENEmployees LEFT OUTER JOIN
GENClassrooms ON GENClassrooms.InstructorId=GENEmployees.Id LEFT JOIN
GENClassroom_GENContact ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
where FromDateTime < GETDATE() and ToDateTime >= GETDATE() AND GENClassrooms.IsActive = 1 AND GENClassrooms.Id IN (SELECT ClassroomId FROM GENClassroom_GENContact WHERE StudentId = @Id  AND IsConfirmed = 1)

End



GO
