SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_GetOneBranch]  (@LangCode nvarchar(500))
as
SELECT        dbo.GENBranches.Id, dbo.GENBranches.RichContent, dbo.fn_Branch_Translate_ByKeyandId(dbo.GENBranches.Id,'Address',@LangCode)  as Address,
 Latitude, Longitude, dbo.GENBranches.Image, dbo.GENBranches.DisplayOrder, dbo.GENBranches.IsActive, dbo.GENBranches.IsPublish, Email, Mobile, Telephone, Fax, GENBranches.DateCreated, 
 GENBranches.DateUpdated, GENBranches.CreatedById, GENBranches.LastUpdatedById, RoleId, RegionId, 
                         BrandId, BranchTypeId, GENCompany_Id, CRMSRVRequester_Id, BranchCategoryId, GENBranches.Code,
						 dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'Name',@LangCode)  as Name, dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'Description',@LangCode) as Description, 
						 GENBranches.ColorCode, GENBranches.IsCheckedOut, GENBranches.CheckinDate, GENBranches.CheckoutDate, GENBranches.Timeout, GENBranches.DisplayOrdering, GENBranches.CheckoutBy,
						 dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'String1',@LangCode) as String1,
						 dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'String2',@LangCode) as String2, 
                      dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'String3',@LangCode) as   String3,
					dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'String4',@LangCode) as    String4,
					dbo.fn_Branch_Translate_ByKeyandId(GENBranches.Id,'String5',@LangCode) as  String5, 
					GENBranches.Int1, GENBranches.Int2, GENBranches.Int3, GENBranches.Int4, GENBranches.Int5, GENBranches.Long1, GENBranches.Long2, GENBranches.Long3, GENBranches.Long4, 
					GENBranches.Long5, GENBranches.Float1, GENBranches.Float2, GENBranches.Float3, GENBranches.Float4, GENBranches.Float5, GENBranches.Decimal1, GENBranches.Decimal2, 
					GENBranches.Decimal3, GENBranches.Decimal4, GENBranches.Decimal5, GENBranches.Bool1, GENBranches.Bool2, GENBranches.Bool3, GENBranches.Bool4, GENBranches.Bool5, 
					GENBranches.Date1, GENBranches.Date2, 
                    GENBranches.Date3, GENBranches.Date4, GENBranches.Date5, GENBranches.ValueId1, GENBranches.ValueId2, GENBranches.ValueId3, GENBranches.ValueId4, GENBranches.ValueId5, 
					GENBranches.IconId, GENBranches.ExpectedCheckoutDate, EmployeeId, GENBranches.IsPosted,
					GENBranchTypes.Name AS BranchTypeName
FROM            dbo.GENBranches
LEFT JOIN GENBranchTypes ON GENBranches.BranchTypeId = GENBranchTypes.Id
WHERE        (dbo.GENBranches.IsPublish = 1)
ORDER BY dbo.GENBranches.DisplayOrder
GO
/****** Object:  StoredProcedure [dbo].[SP_GetPageOfPageFeildsByID]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_GetPageOfPageFeildsByID] @id bigint
as
begin
select POPF.Id Id,POPF.Value,POPF.FeildId,POPF.PageOfPageId,
POPF.FilterName,POPF.FilterValue,POPF.FilterEntityId,
BEF.DBField,POPF.DisplayName,case when BEF.IsmandatoryField= 1 then BEF.IsmandatoryField else POPF.IsMandatory END as IsMandatory,POPF.IsActive,
POPF.RegEx,POPF.RegExMessage,POPF.DisplayOrder,POPF.Cols,
POPF.IsIndex,POPF.IsPrimaryKey,POPF.IsIdentity,POPF.AllowEditing,
POPF.AllowFiltering,POPF.IsTemplateColumn,POPF.Visible,POPF.Width,
POPF.TextAlign,POPF.Format,POPF.Type,POPF.TemplateID,POPF.Field,
POPF.InputType
from PageOfPageFeilds POPF
left JOIN BaseEntityFields BEF ON POPF.FeildId= BEF.Id 
where @id=POPF.PageOfPageId
Order bY POPF.DisplayOrder;

end
GO
