      ,l.[AllowEditing]AS [RAllowEditing]
      ,l.[AllowFiltering]AS [RAllowFiltering]
      ,l.[IsTemplateColumn] AS [RIsTemplateColumn]
      ,l.[Visible]AS [RVisible]
      ,l.[Width]AS [RWidth]
      ,l.[TemplateID]AS [RTemplateID]
      ,l.[Format]AS [RFormat]
      ,l.[Field]AS [RField]
      ,l.[TextAlign] AS [RTextAlign]
      ,l.[Type] AS [RType]
      ,l.[DisplayOrder] AS [RDisplayOrder]
      ,l.[IsMandatory] AS [RIsMandatory]
      ,l.[FilterEntityId] AS [RFilterEntityId]
      ,l.[EntityApi] AS [REntityApi]
      ,l.[InputType] AS [RInputType]
      ,l.[RegEx] AS [RRegEx]
      ,l.[RegExMessage] AS [RRegExMessage]
      ,l.[FilterValue] AS [RFilterValue]
      ,l.[IsImport] AS [RIsImport]
FROM GENPageOfPages
LEFT JOIN BaseEntities on GENPageOfPages.EntityId=BaseEntities.Id
LEFT JOIN HTMLTemplates on GENPageOfPages.HTMLTemplateId=HTMLTemplates.Id
LEFT JOIN GENBackendPages on GENPageOfPages.BackendPageId=GENBackendPages.Id
LEFT JOIN GENTypeStatus on GENPageOfPages.TypeStatusId=GENTypeStatus.Id
left join
     (select [BaseEntityFields].DBField,f.*, row_number() over (partition by f.pageofpageId order by (select NULL)) as seqnum
      from PageOfPageFeilds as f
	  Left Join [BaseEntityFields] ON [BaseEntityFields].Id=f.FeildId 
     ) as f 
     on f.PageOfPageId = GENPageOfPages.Id
	 left join
     (select l.*, row_number() over (partition by l.pageofpageId order by (select NULL)) as seqnum
      from PageOfPageRelations as l
     ) as l
     on f.PageOfPageId = l.PageOfPageId and f.seqnum = l.seqnum
GO
