CREATE Proc [dbo].[SP_GetPassportExistBefore] -- SP_GetPassportExistBefore 19,'1989-01-30','trtr4545'
(@NationalId bigint=NULL,@BirthDate Datetime=NULL,@IDNumber Nvarchar(MAX)=NULL,@ID bigint = 0)
as
begin
select IDNumber from GENContacts 
left  join GENAddresses ON GENContacts.Id =GENAddresses.EntityId and GENAddresses.BaseEntityId=47
WHERE  GENAddresses.CountryId = @NationalId  and IDNumber=@IDNumber and GENContacts.BirthDate=@BirthDate and GENContacts.Id <> @ID
GROUP BY IDNumber
HAVING COUNT(*) >= 1;
END
GO
