CREATE PROCEDURE [dbo].[SP_GetPollAnsewersByPollId] 
@Id int 
AS
BEGIN
    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET NOCOUNT ON

  
   select GENPolls.Id as PollID,GENPolls.Question,GENPollAnswers.Answer,
   GENPollAnswers.Id as AnswerID,
   COUNT(GENExamAnswerDetails.Id) as AnswerCount
   from GENPolls  left join 
   GENPollAnswers on GENPolls.Id=GENPollAnswers.PollId  left join 
   GENExamAnswerDetails on GENPollAnswers.Id=GENExamAnswerDetails.PollAnswerId
   where GENPolls.Id=@Id  
   group by GENPolls.Question,GENPollAnswers.Answer,GENPolls.Id ,GENPollAnswers.Id
END
