/****** Object:  StoredProcedure [dbo].[Sp_GetTrainingMenu_ByCategoryId]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Sp_GetTrainingMenu_ByCategoryId] --Sp_GetTrainingMenu_ByCategoryId 3,'ar'
(@Id bigint=null,@langCode nvarchar(500) )
AS
Begin
WITH RecursiveCte AS
(
    SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    , dbo.fn_TypeCategories_Translate_ByKeyandId( H1.Id,'Name',@langCode) AS Name, 1 as lvl,CAST('' as NVARCHAR(500)) as ParentName,0 as ParentLvl
	,DisplayOrdering
	FROM GENTypeCategories H1
    WHERE ParentId  = @Id
    UNION ALL
    SELECT H2.Id as Id,
    (CASE WHEN  CAST(H2.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H2.ParentId AS NVARCHAR(MAX)) END) AS Parent
    , dbo.fn_TypeCategories_Translate_ByKeyandId( H2.Id,'Name',@langCode) AS Name,lvl + 1 as lvl,CAST(RCTE.Name as NVARCHAR(500)) as ParentName,lvl as ParentLvl
	,H2.DisplayOrdering
	FROM GENTypeCategories H2
    INNER JOIN RecursiveCte RCTE ON H2.ParentId = RCTE.Id
	where H2.IsPublish = 1 and H2.IsActive = 1
)
select * from(

select RecursiveCte.Parent as Id,RecursiveCte.Parent,RecursiveCte.ParentName as Name,GENTypes.Id as CourseId,GENTypes.Int5 As DOinMenu
,dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name',@langCode) As CourseName,ParentLvl as lvl,GENTypes.DisplayOrdering from RecursiveCte 
left join GENTypes ON RecursiveCte.Id =GENTypes.TypeCategoryId and (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) AND (GENTypes.Bool1 =1)
where len(RecursiveCte.ParentName) > 0 AND (GENTypes.IsDeleted =0)

union all

select RecursiveCte.Id,RecursiveCte.Parent,RecursiveCte.Name,GENTypes.Id as CourseId,GENTypes.Int5 As DOinMenu,dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name',@langCode) As CourseName,lvl
,GENTypes.DisplayOrdering from RecursiveCte 
left join GENTypes ON RecursiveCte.Id =GENTypes.TypeCategoryId and (GENTypes.IsActive =1) AND (GENTypes.IsPublish =1) AND (GENTypes.Bool1 =1)AND (GENTypes.IsDeleted =0)
union all

select RecursiveCte.Id,RecursiveCte.Parent,RecursiveCte.Name,GENTypeCategories.Id as CourseId,isnull(GENTypeCategories.DisplayOrdering,0) As DOinMenu
,dbo.fn_TypeCategories_Translate_ByKeyandId( dbo.GENTypeCategories.Id,'Name',@langCode) As CourseName,lvl,RecursiveCte.DisplayOrdering from RecursiveCte 
left join GENTypeCategories ON RecursiveCte.Id =GENTypeCategories.ParentId and (GENTypeCategories.IsActive =1)  and (GENTypeCategories.IsPublish =1) 
) as res
where Parent <> '#'  and len(CourseName) > 0 and lvl = 1
order by res.Id
END
GO
