/****** Object:  StoredProcedure [dbo].[Sp_GETTreeItems]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[Sp_GETTreeItems]
as
Begin
WITH HierarchicalCTE AS
(
SELECT CAST(Cat.Id AS NVARCHAR(MAX)) AS Id,ParentId, Cat.Code, Cat.Name, 1 AS LEVEL ,
Cast(Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as Fullpath
FROM GENItemCategories Cat
where parentID is null
UNION ALL
SELECT CAST(Cat.Id AS NVARCHAR(MAX)) AS Id,Cat.ParentId, Cat.Code, Cat.Name, cte.level+1 AS LEVEL ,
Cast(Cte.Fullpath + '-' + Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as FullPath
FROM HierarchicalCTE cte
inner join GENItemCategories Cat ON Cat.ParentId = cte.id
)
select * from HierarchicalCTE
End
GO
