GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_GetTuesDayDateFrom_Period]   (@FromDate Datetime=null,@ToDate Datetime=null)
AS
Begin
WITH CTE(date_list) AS (
      SELECT @FromDate
      UNION ALL
      SELECT DATEADD(day,1,date_list) FROM CTE
      WHERE date_list<=@ToDate
)

(SELECT date_list as DateSessions
FROM CTE WHERE DATENAME(weekday ,date_list) IN ('Tuesday'))
OPTION (MAXRECURSION 500);

 

END
GO
