     or (@DateF is null and @DateTo is null and ((cast(GENTalents.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENTalents.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

