/****** Object:  StoredProcedure [dbo].[SP_GroupMessages_UpdateSeen]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE proc [dbo].[SP_GroupMessages_UpdateSeen] @GroupId BIGINT ,@ToUserId nvarchar(max)
as 
begin
--create view Last20Messages as
UPDATE GENChatGroupMessages
SET IsSeen = 1, IsReceived = 1
Where IsSeen = 0 AND UserReceiverId = @ToUserId AND ChatMessageId in (SELECT Id FROM GENChatMessages WHERE ChatGroupId = @GroupId and IsSeen = 0)

UPDATE GENChatMessages
SET IsReceived = 1
WHERE IsReceived = 0 AND (SELECT COUNT(Id) From GENChatGroupMessages Where ChatMessageId = GENChatMessages.Id) = (SELECT COUNT(Id) From GENChatGroupMessages Where IsReceived = 1 AND ChatMessageId = GENChatMessages.Id)

UPDATE GENChatMessages
SET IsSeen = 1, IsReceived = 1
WHERE IsSeen = 0 AND (SELECT COUNT(Id) From GENChatGroupMessages Where ChatMessageId = GENChatMessages.Id) = (SELECT COUNT(Id) From GENChatGroupMessages Where IsSeen = 1 AND ChatMessageId = GENChatMessages.Id)

end
GO
