                         @TotalQuestionsNumber int, @TotalExamScore float, @TotalScore float, @TotalNeedRevisedQuestions int, @TotalNeedRevisedQuestionsScore float, @TotalNoNeedRevisedQuestions int, @TotalNoNeedRevisedQuestionsScore float, @Code nvarchar(500), @Name nvarchar(500), @Description nvarchar(500), 
                       @CreatedById nvarchar(128), 
