VALUES        (@StudentId, @StudentName, @ExamId, @ExamName, @ExamWeight, @ExamTime, @CourseId, @CourseName, @StartDateTime, @EndtDateTime,0,0, @InstructorId, @InstructorName, @Code, @Name, @Description, 
