/****** Object:  StoredProcedure [dbo].[SP_ImplementedCourses]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_ImplementedCourses] -- SP_ImplementedCourses'2018-01-01','2030-12-31'
@DateF Datetime,
@DateTo Datetime
as
begin
WITH CourseData AS (
	select count(cc.studentId)as Trainees,count(distinct g.Id)as count_Execution ,g.Name,g.FromDateTime,g.ToDateTime,5 DataSetNo 
	from GenClassrooms g   
	left join GENClassroom_GENContact cc on cc.classroomId = g.Id and cc.BookingTypeId = 1
	--left join GENContacts c on c.Id = cc.StudentId --and  c.IsDeleted = 0 --and IsResponsibleDestinations = 0 
	where g.ClassroomCategoryId = 1 and g.IsDeleted = 0 and g.IsActive = 1 and g.ClassRoomStatus = 2 --and cc.IsConfirmed =1 
	and
	((cast(g.FromDateTime as date) >= cast(@DateF as date) and cast(g.FromDateTime as date) <= cast(@DateTo as date)) 
		 or (@DateF is null and @DateTo is null and ((cast(g.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(g.FromDateTime as date) <= cast(GETDATE() as date)) ) )
		 or (len(@DateF) = 0 and len(@DateTo) = 0))
	group by  g.Id,g.name,g.FromDateTime,g.ToDateTime),
	TotalSumTable AS (
        SELECT SUM(Trainees) AS TotalSumOfTrainees FROM CourseData
    )
select Trainees,count_Execution,Name,FromDateTime,ToDateTime,(select TotalSumOfTrainees from TotalSumTable)TotalSumOfTrainees,DataSetNo 
from CourseData
--group by  Trainees,count_Execution,Name,FromDateTime,ToDateTime,DataSetNo
order by Trainees desc
end



--					select * from Classroom_View
--					WHERE ClassroomCategoryId = 1 and IsDeleted = 0  
--					--and ClassRoomStatus = 2 
--					ORDER BY DateUpdated DESC
GO
