Create Proc [dbo].[SP_ImportCompanyLogDatas_UpdateCount](@ImportedId bigint)
as
Declare @SuccessCount int =(select count(Id) from CompanyLogDatas where CompanyLogDatas.ImportLogId = @ImportedId and  CompanyLogDatas.ErrorStatus LIKE '%Success%')
Declare @ErrorStatusCount int =(select count(Id) from CompanyLogDatas where CompanyLogDatas.ImportLogId = @ImportedId and  CompanyLogDatas.ErrorStatus LIKE'%Database Error%')
Declare @DuplicatedStatusCount int =(select count(Id) from CompanyLogDatas where CompanyLogDatas.ImportLogId = @ImportedId and  CompanyLogDatas.ErrorStatus LIKE'%Sheet Duplicated%')
Declare @DataBaseDuplicatedStatusCount int =(select count(Id) from CompanyLogDatas where CompanyLogDatas.ImportLogId = @ImportedId and  CompanyLogDatas.ErrorStatus LIKE'%DataBase Duplicate%')

update ImportLogs set SuccessStatusCount = @SuccessCount,ErrorStatusCount =@ErrorStatusCount ,
DuplicatedStatusCount =@DuplicatedStatusCount,
DataBaseDuplicatedStatusCount = @DataBaseDuplicatedStatusCount
where Id  = @ImportedId
GO
