/****** Object:  StoredProcedure [dbo].[SP_ImportLog_ClearAll]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_ImportLog_ClearAll] (@popId bigint)
as
DELETE ImportLogDatas 
FROM ImportLogDatas
JOIN ImportLogs 
ON ImportLogDatas.ImportLogId = ImportLogs.id
AND ImportLogs.PageofPageId  =@popId

DELETE CompanyLogDatas 
FROM CompanyLogDatas
JOIN ImportLogs 
ON CompanyLogDatas.ImportLogId = ImportLogs.id
AND ImportLogs.PageofPageId  =@popId

 

 DELETE ContactLogDatas 
FROM ContactLogDatas
JOIN ImportLogs 
ON ContactLogDatas.ImportLogId = ImportLogs.id
AND ImportLogs.PageofPageId  =@popId

delete from ImportLogs where PageofPageId = @popId
GO
