CREATE Proc [dbo].[SP_ImportLog_ClearAllByLogId](@LogId bigint)
as
delete from ImportLogDatas where ImportLogId =@LogId
delete from CompanyLogDatas where ImportLogId =@LogId
delete from ContactLogDatas where ImportLogId =@LogId
delete from ImportLogs where Id = @LogId
