as
Declare @SuccessCount int =(select count(Id) from TypeLogDatas where TypeLogDatas.ImportLogId = @ImportedId and  TypeLogDatas.ErrorStatus LIKE '%Success%'); 
                    Declare @ErrorStatusCount int = (select count(Id) from TypeLogDatas where TypeLogDatas.ImportLogId = @ImportedId and TypeLogDatas.ErrorStatus LIKE'%Database Error%'); 
                    Declare @DuplicatedStatusCount int = (select count(Id) from TypeLogDatas where TypeLogDatas.ImportLogId = @ImportedId and TypeLogDatas.ErrorStatus LIKE'%Sheet Duplicated%'); 
                    Declare @DataBaseDuplicatedStatusCount int = (select count(Id) from TypeLogDatas where TypeLogDatas.ImportLogId = @ImportedId and TypeLogDatas.ErrorStatus LIKE'%DataBase Duplicate%'); 
                    update ImportLogs set SuccessStatusCount = @SuccessCount, ErrorStatusCount = @ErrorStatusCount, DuplicatedStatusCount = @DuplicatedStatusCount, DataBaseDuplicatedStatusCount = @DataBaseDuplicatedStatusCount 
                    where Id = @ImportedId
GO
/****** Object:  StoredProcedure [dbo].[SP_ImportVCRContactTab]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc 
[dbo].[SP_ImportVCRContactTab] --SP_ImportVCRContactTab 1,'b77c70d1-95ee-4d37-a808-d6b7276caefe','Name,DefaultPhone,DefaultEmail,Position,IDNumber','VCRContactImport.StudentName ,VCRContactImport.StudentPhone ,VCRContactImport.StudentEmail ,VCRContactImport.StudentPostion ,VCRContactImport.StudentNID , ',10
@TypeID int
,@UserId nvarchar(250)
,@ContactFeildName nvarchar(250)
,@columnstringWithDataType nvarchar(250)
,@ClassId bigint
,@PageofPageId int
,@FileName nvarchar(250)
,@ImportDtlsCol nvarchar(250)
,@SheetColumnsName nvarchar(250)
,@VCRContactImportcolumn nvarchar(250)
as
begin
update VCRContactImport
set Error = 'No Name'
where StudentName is null or len(StudentName) = 0

IF EXISTS(
  SELECT TOP 1 1
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE 
    [TABLE_NAME] = 'VCRContactImport'
    AND [COLUMN_NAME] = 'StudentNID')
BEGIN
update VCRContactImport
set Error = 'Repeted NID'
from VCRContactImport
inner join  (SELECT
    ID,StudentNID,ROW_NUMBER() OVER (PARTITION BY StudentNID ORDER BY ID) as RowNum
FROM VCRContactImport) as res on res.ID = VCRContactImport.Id and RowNum > 1
and  (Error is null or len(Error) = 0)

update VCRContactImport
set Error = 'No NID'
where StudentNID is null or len(StudentNID) = 0
and (Error is null or len(Error) = 0)

update VCRContactImport
set Error = 'Error StudentNID'
where (ISNUMERIC(StudentNID) = 0) 
and  (Error is null or len(Error) = 0)
END

IF EXISTS(
  SELECT TOP 1 1
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE 
    [TABLE_NAME] = 'VCRContactImport'
    AND [COLUMN_NAME] = 'StudentPhone')
BEGIN
update VCRContactImport
set Error = 'Repeted StudentPhone in Excel'
from VCRContactImport
inner join  (SELECT
    ID,StudentPhone,ROW_NUMBER() OVER (PARTITION BY StudentPhone ORDER BY ID) as RowNum
FROM VCRContactImport) as res on res.ID = VCRContactImport.Id and RowNum > 1
and  (Error is null or len(Error) = 0) and ((select IsDuplicated from VCRContactImportFields where DBField = 'StudentPhone') = 1)

update VCRContactImport
set Error = 'Repeted StudentPhone in Database'
from VCRContactImport
where (Error is null or len(Error) = 0) and ((select IsDuplicated from VCRContactImportFields where DBField = 'StudentPhone') = 1) 
and (VCRContactImport.StudentPhone in (select DefaultPhone from GENContacts))

update VCRContactImport
set Error = 'Error StudentPhone'
where (ISNUMERIC(StudentPhone) = 0) 
and  (Error is null or len(Error) = 0)
END

IF EXISTS(
  SELECT TOP 1 1
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE 
    [TABLE_NAME] = 'VCRContactImport'
    AND [COLUMN_NAME] = 'StudentEmail')
BEGIN
update VCRContactImport
set Error = 'Repeted StudentEmail in Excel'
from VCRContactImport
inner join  (SELECT
    ID,StudentEmail,ROW_NUMBER() OVER (PARTITION BY StudentEmail ORDER BY ID) as RowNum
FROM VCRContactImport) as res on res.ID = VCRContactImport.Id and RowNum > 1
and  (Error is null or len(Error) = 0) and ((select IsDuplicated from VCRContactImportFields where DBField = 'StudentEmail') = 1)

update VCRContactImport
set Error = 'Repeted StudentEmail in Database'
from VCRContactImport
where (Error is null or len(Error) = 0) and ((select IsDuplicated from VCRContactImportFields where DBField = 'StudentEmail') = 1) 
and (VCRContactImport.StudentEmail in (select DefaultEmail from GENContacts))

END

IF EXISTS(
  SELECT TOP 1 1
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE 
    [TABLE_NAME] = 'VCRContactImport'
    AND [COLUMN_NAME] = 'StudentPosition')
BEGIN
update VCRContactImport
set Error = 'Repeted StudentPosition in Excel'
from VCRContactImport
inner join  (SELECT
    ID,StudentPostion,ROW_NUMBER() OVER (PARTITION BY StudentPostion ORDER BY ID) as RowNum
FROM VCRContactImport) as res on res.ID = VCRContactImport.Id and RowNum > 1
and  (Error is null or len(Error) = 0) and ((select IsDuplicated from VCRContactImportFields where DBField = 'StudentPostion') = 1)

END


update VCRContactImport
set ContactID = GENContacts.Id
from VCRContactImport
inner join GENContacts on IDNumber = StudentNID  and GENContacts.IsActive = 1 and GENContacts.IsDeleted = 0
where (Error is null or len(Error) = 0)

DECLARE @sqlCommand Nvarchar(1000)
SET @sqlCommand = 'insert into GENContacts('+@ContactFeildName+',[IsActive],[IsPublish],IsUser,IsJunk,Other,IsDeleted,DateCreated'
 +' ,CreatedById,DateUpdated,LastUpdatedById,CheckoutDate,Timeout,Bool1,Bool2,Bool3,Bool4,Bool5,IsCheckedOut)'
+'SELECT distinct '+@columnstringWithDataType+'1,1,1,0,0,0,GETDATE(),'''+@UserId+''',GETDATE(),'''+@UserId+'''
,GETDATE(),0,0,0,0,0,0,0 
FROM VCRContactImport
where (Error is null or len(Error) = 0) AND	(VCRContactImport.ContactID is null or len(VCRContactImport.ContactID) = 0)'
print @sqlCommand
EXEC (@sqlCommand)


update VCRContactImport
set ContactID = GENContacts.Id
from VCRContactImport
inner join GENContacts on IDNumber = StudentNID and GENContacts.IsActive = 1 and GENContacts.IsDeleted = 0
where (Error is null or len(Error) = 0) and (VCRContactImport.ContactID is null or len(VCRContactImport.ContactID) = 0)

update VCRContactImport
set Error = 'IsExist'
from VCRContactImport
inner join GENContacts on IDNumber = StudentNID
inner join GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId= @ClassId and GENContacts.Id = GENClassroom_GENContact.StudentId
where (Error is null or len(Error) = 0)

insert into GENClassroom_GENContact([ClassroomId],[StudentId],[IsConfirmed],[StudentStatus],[Note],[PaymentTypeId],[BookingTypeId])
SELECT distinct @ClassId,GENContacts.ID,1,0,null,1,6 FROM VCRContactImport
inner join GENContacts on IDNumber = VCRContactImport.StudentNID 
where (Error is null or len(Error) = 0) AND	VCRContactImport.ContactID is not null and GENContacts.IsActive = 1 and GENContacts.IsDeleted = 0


insert into [ImportLogs]([PageofPageId],[FileName],[CreatedById],[CreatedDate],[FileLocation],[SuccessStatusCount],[ErrorStatusCount],[DuplicatedStatusCount]
      ,[DataBaseDuplicatedStatusCount],[Importing],[Imported])
select @PageofPageId,@FileName,@UserId,GETDATE(),'Uploaded',(select count(*) from VCRContactImport where (Error is null or len(Error) = 0))
,(select count(*) from VCRContactImport where (Error is not null and len(Error) > 0)),0,0,0,1
declare @LogID int = @@IDENTITY

update VCRContactImport
set ImportLogId = @LogID

DECLARE @sqlCommandLog Nvarchar(1000)
SET @sqlCommandLog = 'insert into VCRContactImportDatas('+@ImportDtlsCol+'[Error],[HeaderId])'
+'SELECT distinct '+@SheetColumnsName+'''Error'','+cast(@LogID as nvarchar(50))
print @sqlCommandLog
EXEC (@sqlCommandLog)

SET @sqlCommandLog = 'insert into VCRContactImportDatas('+@ImportDtlsCol+'[Error],[HeaderId],DateCreated)'
+'SELECT distinct '+@VCRContactImportcolumn+'Error,'+cast(@LogID as nvarchar(50))+',getdate() FROM VCRContactImport
where (Error is not null or len(Error) > 0) '
print @sqlCommandLog
EXEC (@sqlCommandLog)



end
GO
