CREATE proc [dbo].[SP_InitialUserQuestionAnswers]
( @ExamId bigint,@CreatedById nvarchar(128) , @Email nvarchar(MAX)
, @ExamAnswerHeaderId bigint)
as
INSERT INTO GENExamAnswerDetails
                         (PollId,DateCreated, DateUpdated, PollAnswerId, CreatedById, LastUpdatedById, Email, IsRevised, ExamAnswerHeaderId, Score, Weight, QuestionName, QuestionCorrectedAnswer, AnswerName, Article, Value)
SELECT  distinct   dbo.GENPolls.Id,getdate(),getdate(),null,@CreatedById,@CreatedById,@Email ,(SELECT
  CASE 
    WHEN dbo.GENPolls.QuestionType >2 THEN 0
 WHEN dbo.GENPolls.QuestionType <3 THEN 1
     
  END), @ExamAnswerHeaderId,0, dbo.GENPolls.Weight,dbo.GENPolls.Question,dbo.fn_Correct_QuestionAnswers(dbo.GENPolls.Id),null,null,0
FROM            dbo.GENPolls RIGHT OUTER JOIN
                         dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId 
WHERE        (dbo.PollCategoryandPolls.PollCategoryId = @ExamId) and dbo.GENPolls.IsActive =1 and concat(@ExamAnswerHeaderId,dbo.GENPolls.Id) not in (select concat(GENExamAnswerDetails.ExamAnswerHeaderId,GENExamAnswerDetails.PollId) from GENExamAnswerDetails)
GO
/****** Object:  StoredProcedure [dbo].[SP_InserSessionVcr_New]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_InserSessionVcr_New] 
@FromDate Datetime=null,@ToDate Datetime=null,@fromTime Datetime = null,@ClassroomId bigint ,@SessionID bigint
AS
Begin
declare @IdentityOutput table ( ToTime Datetime );
WITH CTE(date_list) AS (
      SELECT @FromDate
      UNION ALL
      SELECT DATEADD(day,1,date_list) FROM CTE
      WHERE date_list<=@ToDate
)
insert into TLMSClassroom_Session(ClassroomId,SessionId,SessionDateTime,FromDateTime,ToDateTime,IsActive,Name)
output inserted.ToDateTime into  @IdentityOutput
select @ClassroomId,GENItems.Id,DateSessions,@fromTime, DATEADD(MINUTE,GENItems.int1,@fromTime),0,GENItems.Name from GENItems
cross apply
(SELECT date_list as DateSessions
FROM CTE WHERE DATENAME(weekday ,date_list) IN ('Tuesday')) as res
where Id = @SessionID
OPTION (MAXRECURSION 500)

select top 1 ToTime from @IdentityOutput

END
GO
