-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 19/04/20201
-- Description:	Add Courses to Contacts according to talent selected
-- =============================================
CREATE PROCEDURE [dbo].[SP_InsertContactCoursesByTalent]
	-- Add the parameters for the stored procedure here
	@TalentId BIGINT, @UserId NVARCHAR(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	INSERT INTO [dbo].[Contacts_Courses]
           ([CourseId]
           ,[StudentId]
           ,[CourseStatus]
           ,[CreatedDate]
           ,[UpdatedDate]
           ,[CreatedById]
           ,[UpdatedById]
           ,[ClassRoomId]
           ,[OrderId]
           ,[TalentCourseStatus]
		   ,[TalentId])
	SELECT EntityId, GENContact_Talent.ContactId,
	(CASE WHEN GENTypes.CourseType = 1 THEN 4 ELSE 0 END), GETDATE(),GETDATE(),@UserId,@UserId,NULL, NULL, 0,@TalentId
	FROM GENTalents_Generic LEFT JOIN 
		GENContact_Talent ON GENTalents_Generic.TalentId =  GENContact_Talent.TalentId LEFT JOIN
		GENTypes ON GENTalents_Generic.EntityId =GENTypes.Id 
		WHERE GENTalents_Generic.TalentId = @TalentId AND BaseEntityId = 28 AND GENContact_Talent.ContactId NOT IN 
		(SELECT StudentId  From Contacts_Courses WHERE CourseId = GENTalents_Generic.EntityId)
END
