/****** Object:  StoredProcedure [dbo].[SP_LecturesActiveState]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_LecturesActiveState]--'2022-01-01', '2026-01-01'
@DateF Datetime,
@DateTo Datetime
as
begin 
	declare @LecturesRecorded  int , @LecturesActive int
    select @LecturesRecorded =  Count(distinct GENItems.Id )
	from GENItems 
	WHERE GENItems.IsDeleted = 0  And ((cast(GENItems.DateCreated as date) >= cast(@DateF as date) and cast(GENItems.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENItems.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENItems.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));
    select @LecturesActive =  Count(distinct GENItems.Id )
	from GENItems 
	inner join GENTypes on GENTypes.id = GENItems.TypeId
	inner join GENClassrooms on GENClassrooms.CourseId = GENTypes.Id
	WHERE GENItems.IsDeleted = 0  and GENItems.IsActive =1  And ((cast(GENItems.DateCreated as date) >= cast(@DateF as date) and cast(GENItems.DateCreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENItems.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENItems.DateCreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

	 select @LecturesRecorded  as LecturesRecorded ,  @LecturesActive  as LecturesActive
end
GO
/****** Object:  StoredProcedure [dbo].[SP_LecturesInfo]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_LecturesInfo] --SP_LecturesInfo '2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
as
begin

WITH StudentCounts AS (
    SELECT 
        GENClassroom_GENContact.ClassroomId,
        COUNT(DISTINCT GENClassroom_GENContact.StudentId) AS InstructorCount
    FROM 
        GENClassroom_GENContact
    WHERE 
        GENClassroom_GENContact.BookingTypeId = 1
    GROUP BY 
        GENClassroom_GENContact.ClassroomId
),
RatingsCount AS (
    SELECT 
        TLMSClassroom_Session.Id,
        COUNT(CASE WHEN GENRatings.Rating IN (4, 5) THEN 1 END) AS ExecAndVeryGoodCount
    FROM 
        TLMSClassroom_Session
    LEFT JOIN 
        GENRatings ON TLMSClassroom_Session.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 198
    GROUP BY 
        TLMSClassroom_Session.Id
)
select I.Name, count(distinct TLMSClassroom_Session.ClassroomId)as Time_execution
,count(distinct TLMSClassroom_Session.InstructorId) as Instructor
,sum(InstructorCount) as TotalTrainers , 
 sum(RatingsCount.ExecAndVeryGoodCount) execAndVeryGood,
  CASE 
            WHEN sum(InstructorCount) = 0 THEN 0
            ELSE cast((((cast(sum(RatingsCount.ExecAndVeryGoodCount) as dec(18,2))) / (cast(sum(InstructorCount) as dec(18,2))) ) * 100) as decimal(18 ,2))
        END AS SatisfactionPercentage 
 --cast(COUNT(CASE WHEN GENRatings.Rating IN (4, 5) THEN 1 ELSE NULL END)*1.00 /count(distinct c.id)*1.00 as decimal(3,2)) as SatisfactionPercentage 
from GENItems  I
	inner join TLMSClassroom_Session  on I.id = TLMSClassroom_Session.sessionId
	inner join GENClassrooms on GENClassrooms.id = TLMSClassroom_Session.ClassroomId and GENClassrooms.IsDeleted = 0 and GENClassrooms.IsActive = 1
	 LEFT JOIN RatingsCount 
        ON RatingsCount.id = TLMSClassroom_Session.id 
 LEFT JOIN StudentCounts AS TotalInstructors 
        ON TotalInstructors.ClassroomId = TLMSClassroom_Session.ClassroomId
			where ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	group by I.Name  
	order by count(distinct TLMSClassroom_Session.ClassroomId) desc;

--select I.Name, count(distinct TLMSClassroom_Session.ClassroomId)as Time_execution
--,count(distinct TLMSClassroom_Session.InstructorId) as Instructor
--,sum(dbo.fn_VcrBookingStudentCount_Confirmed(TLMSClassroom_Session.ClassroomId)) as TotalTrainers , 
-- COUNT(CASE WHEN GENRatings.Rating IN (4, 5) THEN 1 ELSE NULL END) execAndVeryGood,
--  CASE 
--            WHEN sum(dbo.fn_VcrBookingStudentCount_Confirmed(TLMSClassroom_Session.ClassroomId)) = 0 THEN 0
--            ELSE cast(((cast(COUNT(CASE WHEN GENRatings.Rating IN (4, 5) THEN 1 ELSE NULL END) as dec(18,2))) / (cast(sum(dbo.fn_VcrBookingStudentCount_Confirmed(TLMSClassroom_Session.ClassroomId)) as dec(18,2))) ) as decimal(18 ,2))
--        END AS SatisfactionPercentage 
-- --cast(COUNT(CASE WHEN GENRatings.Rating IN (4, 5) THEN 1 ELSE NULL END)*1.00 /count(distinct c.id)*1.00 as decimal(3,2)) as SatisfactionPercentage 
--from GENItems  I
--	inner join TLMSClassroom_Session  on I.id = TLMSClassroom_Session.sessionId
--	inner join GENClassrooms on GENClassrooms.id = TLMSClassroom_Session.ClassroomId and GENClassrooms.IsDeleted = 0 and GENClassrooms.IsActive = 1
--	left join GENRatings on GENRatings.BaseEntityId = 198 AND TLMSClassroom_Session.Id = GENRatings.EntityId 


--	group by I.Name  
--	order by count( TLMSClassroom_Session.ClassroomId) desc;

end;
GO
