CREATE PROCEDURE [dbo].[SP_LEcturesWithoutFiles]
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select GENTypes.Id AS CourseId,GENTypes.Name AS CourseName, GENItems.Name AS LectureName, GENItems.Id As LectureId 
	FROM GENItems

	left join TLMSClassroom_Session ON GENItems.Id=TLMSClassroom_Session.SessionId
	left join GENClassrooms ON TLMSClassroom_Session.ClassroomId=GENClassrooms.Id
LEFT JOIN GENTypes ON GENClassrooms.CourseId = GENTypes.Id
WHERE GENItems.Id NOT IN (SELECT ItemId FROM GENItemFiles) AND GENItems.Id NOT IN (SELECT ItemId FROM GENItemVideos)
AND GENTypes.IsPublish = 1	and GENClassrooms.ProsecutionId=0
--AND GENListValuesTypeId = 20054
--AND GENListValues.IsActive = 1 And GENListValues.IsPublish = 1 

END
