create  Proc [dbo].[SP_Link_DeleteLink](@Id Decimal(18,0))

as
	delete  from GENLinks
    WHERE Id = @Id;
	 IF @@ROWCOUNT > 0
    BEGIN
        -- If a row was deleted, return 1
