SELECT       dbo.GENListValues.id, dbo.GENListValues.Value, dbo.GENListValues.IsActive, dbo.GENListValues.IsPublish, IsDefault, ShortCode, GENListValuesTypeId, dbo.GENListValues.Code, dbo.fn_ListValue_Translate_ByKeyandId(dbo.GENListValues.Id,'Name',@LangCode) as Name, dbo.GENListValues.Description,dbo.GENListValues.ColorCode, dbo.GENListValues.IsCheckedOut, dbo.GENListValues.DateCreated, dbo.GENListValues.DateUpdated, dbo.GENListValues.CheckinDate, dbo.GENListValues.CheckoutDate, dbo.GENListValues.Timeout, dbo.GENListValues.DisplayOrdering, 
                         dbo.GENListValues.CreatedById,
						  dbo.GENListValues.LastUpdatedById, dbo.GENListValues.CheckoutBy, dbo.GENListValues.String1,
						  dbo.GENListValues.String2, dbo.GENListValues.String3, dbo.GENListValues.String4, dbo.GENListValues.String5,
						   dbo.GENListValues.Int1, dbo.GENListValues.Int2, dbo.GENListValues.Int3, dbo.GENListValues.Int4, dbo.GENListValues.Int5,
						    dbo.GENListValues.Long1, dbo.GENListValues.Long2, dbo.GENListValues.Long3, dbo.GENListValues.Long4,
							 dbo.GENListValues.Long5, dbo.GENListValues.Float1, dbo.GENListValues.Float2, dbo.GENListValues.Float3,
							  dbo.GENListValues.Float4, dbo.GENListValues.Float5, dbo.GENListValues.Decimal1, dbo.GENListValues.Decimal2, 
							  dbo.GENListValues.Decimal3, 
                         dbo.GENListValues.Decimal4, dbo.GENListValues.Decimal5, dbo.GENListValues.Bool1, dbo.GENListValues.Bool2, dbo.GENListValues.Bool3, dbo.GENListValues.Bool4, dbo.GENListValues.Bool5,
						  dbo.GENListValues.Date1, dbo.GENListValues.Date2, dbo.GENListValues.Date3, 
						  dbo.GENListValues.Date4
                         DateTimeTo
FROM            dbo.GENListValues LEFT OUTER JOIN
                      
                         dbo.GENListValuesTypes ON dbo.GENListValues.GENListValuesTypeId = dbo.GENListValuesTypes.Id

						 WHERE        GENListValues.IsPublish=1  AND (dbo.GENListValuesTypes.Name = @TypeName)
GO
