CREATE  Proc [dbo].[SP_ListValue_Translate_ByKeyandId]
( @id bigint,
   @Key nvarchar(500),
   @langCode nvarchar(500))

as
declare @Value nvarchar(MAX) 
 
 if @Key ='Name'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = Name from ListValue_TranslateView where Id =@id
end
 end
  if @Key ='Description'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = [Description] from ListValue_TranslateView where Id =@id
end
 end
 if @Key ='String1'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)   @Value = String1 from ListValue_TranslateView where Id =@id
end
 end

 if @Key ='String2'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)   @Value = String2 from ListValue_TranslateView where Id =@id
end
 end

 if @Key ='String3'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = String3 from ListValue_TranslateView where Id =@id
end
 end
 if @Key ='String4'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)   @Value = String4 from ListValue_TranslateView where Id =@id
end
 end

 if @Key ='String5'

 begin
select top(1)  @Value= value from ListValue_TranslateView 

where GENListValuesId = @id and FieldName =@Key and LanguageCode = @langCode

if @Value is null 

begin
select top(1)  @Value = String5 from ListValue_TranslateView where Id =@id
end
 end
 select  @Value as Result
GO
