CREATE proc [dbo].[SP_ListValue1_InsertNotExistListValue1](@typeId bigint)
  as
INSERT INTO GENListValues(Name, IsPublish, IsActive,GENListValuesTypeId,IsCheckedOut,DateCreated,DateUpdated,CheckoutDate,[Timeout],Bool1,Bool2,Bool3,Bool4,Bool5)
 SELECT distinct CompanyLogDatas.GENListValues1_Name,0,1,@typeId,0,GETDATE(),GETDATE(),GETDATE(),0,0,0,0,0,0 from CompanyLogDatas
 where CompanyLogDatas.GENListValues1_Name is not null and not EXISTS (SELECT DISTINCT dbo.CompanyLogDatas.GENListValues1_Name
FROM            dbo.CompanyLogDatas INNER JOIN
                         dbo.GENListValues AS sourcetable ON dbo.CompanyLogDatas.GENListValues1_Name = sourcetable.Name COLLATE Arabic_CI_AS
WHERE          (dbo.CompanyLogDatas.IsNew = 1) and (sourcetable.GENListValuesTypeId is null or sourcetable.GENListValuesTypeId =@typeId))
GO
