-- =============================================
-- Author:      <Author, , Name>
-- Create Date: <Create Date, , >
-- Description: <Description, , >
-- =============================================
create     PROCEDURE [dbo].[SP_ListVcrs] 
(@CurrentEmployeeId bigint)
AS
BEGIN
Select distinct GENClassrooms.Id,GENClassrooms.Code,GENClassrooms.Name from GENClassrooms 
                Inner join TLMSClassroom_Session ON TLMSClassroom_Session.ClassroomId = GENClassrooms.Id
                where GENClassrooms.IsActive = 1 AND GENClassrooms.IsDeleted = 0 AND TLMSClassroom_Session.InstructorId = @CurrentEmployeeId
END
GO
/****** Object:  StoredProcedure [dbo].[Sp_LockFullExam]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create proc [dbo].[Sp_LockFullExam] @pollCategoryId bigint
as

update dbo.GENPollCategories set IsPosted =1

where Id = @pollCategoryId

update dbo.PollCategoryandPolls set IsPosted =1

where PollCategoryId = @pollCategoryId


update dbo.GENPolls  set IsPosted =1
FROM            dbo.PollCategoryandPolls LEFT OUTER JOIN
                         dbo.GENPolls ON dbo.PollCategoryandPolls.PollId = dbo.GENPolls.Id
where PollCategoryId = @pollCategoryId


update dbo.GENPollAnswers  set IsPosted =1
FROM            dbo.GENPollAnswers RIGHT OUTER JOIN
                         dbo.GENPolls ON dbo.GENPollAnswers.PollId = dbo.GENPolls.Id RIGHT OUTER JOIN
                         dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId

						 where PollCategoryId = @pollCategoryId
GO
/****** Object:  StoredProcedure [dbo].[SP_Messages_getLass20]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[SP_Messages_getLass20] @UserId nvarchar(max),@ReUserId nvarchar(max),@BaseEntityId bigint
as 
begin
--create view Last20Messages as
Declare @tempMessages table(id bigint,MessageTime datetime,MessageText nvarchar(max),UserSenderId nvarchar(max),UserReceiverId nvarchar(max),
usernameRE nvarchar(max),UsernameSe nvarchar(max),ticketId BIGINT,IsReceived bit,IsSeen bit,Image nvarchar(max),ChatEntityId bigint,ChatEntityPoPId bigint,ChatEntityUrl nvarchar(max),
IsForwarded BIT,IsReply BIT,IsReceiverDeleted BIT,IsSenderDeleted BIT, OriginalMessageId BIGINT, ReplyMessageText nvarchar(max), ReplyMessageSenderId nvarchar(max), ReplyMessageSenderName nvarchar(max))



insert into @tempMessages 
select m.Id Id ,m.MessageTime ,m.MessageText ,m.UserSenderId,m.UserReceiverId ,users.Name usernameRE ,userSEnder.Name UsernameSe,M.ticketId ticketId,
m.IsReceived,m.IsSeen, GENEmployees.Image ,m.ChatEntityId,m.ChatEntityPoPId,m.ChatEntityUrl,m.IsForwarded,m.IsReply,m.IsReceiverDeleted,m.IsSenderDeleted, m.OriginalMessageId,
rm.MessageText AS ReplyMessageText, rm.UserSenderId AS ReplyMessageSenderId, senderUser.Name AS ReplyMessageSenderName
from GENChatMessages m
left join AspNetUsers users on users.Id=m.UserReceiverId 
left join AspNetUsers userSEnder on userSEnder.Id=m.UserSenderId 
LEFT JOIN GENEmployees on userSEnder.Id = GENEmployees.UserId
LEFT JOIN GENChatMessages rm on rm.Id = m.OriginalMessageId
LEFT JOIN AspNetUsers senderUser on senderUser.Id = rm.UserSenderId
where(m.UserReceiverId = @UserId and m.UserSenderId = @ReUserId) or (m.UserSenderId = @Userid and m.UserReceiverId = @ReUserId) 

ORDER BY m.Id DESC;

select  tm.Id Id ,[dbo].[fn_MessageTime](tm.MessageTime) as MessageTimeString, FORMAT(tm.MessageTime,'hh:mm tt') as OneMessageTime,tm.MessageTime as MessageTime,tm.MessageText ,tm.UserSenderId,tm.UserReceiverId ,tm.usernameRE UsernameRE ,tm.UsernameSe UsernameSe,TM.ticketId AS TicketId, 
tm.IsReceived,tm.IsSeen,gi.AzureUri,gi.EntityId,gi.Id as ImageId, gi.Name,gf.AzureUri FileAzureUri,gf.BaseEntityId FileBaseEntityId,gf.Id as FileId ,gf.FileName FileName, tm.Image,tm.ChatEntityId,tm.ChatEntityPoPId,tm.ChatEntityUrl
,tm.IsForwarded,tm.IsReply,tm.IsReceiverDeleted,tm.IsSenderDeleted, tm.OriginalMessageId,
tm.ReplyMessageText, tm.ReplyMessageSenderId, tm.ReplyMessageSenderName,rgi.AzureUri AS ReplyAzureUri, rgi.Name AS ReplyImageName,
rgf.AzureUri ReplyFileAzureUri,rgf.FileName ReplyFileName
from @tempMessages tm
LEFT JOIN GENImages gi ON gi.BaseEntityId=@BaseEntityId and gi.EntityId=tm.id
LEFT JOIN GENFiles gf ON gf.BaseEntityId=@BaseEntityId and gf.EntityId=tm.id
OUTER APPLY 
(SELECT TOP 1 AzureUri, Name
 FROM GENImages 
 WHERE BaseEntityId=@BaseEntityId AND EntityId = tm.OriginalMessageId
 ORDER BY Id DESC
) AS rgi
OUTER APPLY 
(SELECT TOP 1 AzureUri, FileName
 FROM GENFiles 
 WHERE BaseEntityId=@BaseEntityId AND EntityId = tm.OriginalMessageId
 ORDER BY Id DESC
) AS rgf
order by tm.id asc;
end
GO
/****** Object:  StoredProcedure [dbo].[SP_Messages_getLast]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_Messages_getLast] @UserId nvarchar(max),@ReUserId nvarchar(max)
as 
begin
--create view Last20Messages as
Declare @tempMessages table(id bigint,MessageTime datetime,MessageText nvarchar(max),UserSenderId nvarchar(max),UserReceiverId nvarchar(max),
usernameRE nvarchar(max),UsernameSe nvarchar(max),ticketId BIGINT,IsReceived bit,IsSeen bit,Image nvarchar(max),ChatEntityId bigint,ChatEntityPoPId bigint,ChatEntityUrl nvarchar(max),
ChatGroupId BIGINT)


insert into @tempMessages 
select top 1 m.Id Id ,m.MessageTime ,m.MessageText ,m.UserSenderId,m.UserReceiverId ,users.Name usernameRE ,userSEnder.Name UsernameSe,M.ticketId ticketId,
m.IsReceived,m.IsSeen, GENEmployees.Image ,m.ChatEntityId,m.ChatEntityPoPId,m.ChatEntityUrl,m.ChatGroupId
from GENChatMessages m
left join AspNetUsers users on users.Id=m.UserReceiverId 
left join AspNetUsers userSEnder on userSEnder.Id=m.UserSenderId 
LEFT JOIN GENEmployees on userSEnder.Id = GENEmployees.UserId
where(m.UserReceiverId = @UserId and m.UserSenderId = @ReUserId) or (m.UserSenderId = @Userid and m.UserReceiverId = @ReUserId) 

ORDER BY m.Id DESC;

select  tm.Id Id ,[dbo].[fn_MessageTime](tm.MessageTime) as MessageTimeString,tm.MessageTime as MessageTime,tm.MessageText ,tm.UserSenderId,tm.UserReceiverId ,tm.usernameRE UsernameRE ,tm.UsernameSe UsernameSe,TM.ticketId AS TicketId, 
tm.IsReceived,tm.IsSeen,gi.AzureUri,gi.EntityId,gi.Id as ImageId, gi.Name,gf.AzureUri FileAzureUri,gf.BaseEntityId FileBaseEntityId,gf.Id as FileId ,gf.FileName FileName, tm.Image,tm.ChatEntityId,tm.ChatEntityPoPId,tm.ChatEntityUrl,
tm.ChatGroupId
from @tempMessages tm
LEFT JOIN GENImages gi ON gi.BaseEntityId=177 and gi.EntityId=tm.id
LEFT JOIN GENFiles gf ON gf.BaseEntityId=177 and gf.EntityId=tm.id

order by tm.id asc;
end

--SP_Messages_getLast 'ad3473e9-a4af-4f87-a2ff-86940327afee','baf3e4ac-b462-4ef3-aeda-6e710af3d689'
--format(tm.MessageTime,'ddd hh:mm tt')

--SP_Messages_getLast 'ad3473e9-a4af-4f87-a2ff-86940327afee','baf3e4ac-b462-4ef3-aeda-6e710af3d689'
GO
