/****** Object:  StoredProcedure [dbo].[SP_MYvcrs]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:      <Author, , Name>
-- Create Date: <Create Date, , >
-- Description: <Description, , >
-- =============================================
CREATE   PROCEDURE [dbo].[SP_MYvcrs]
(@CurrentEmployeeId bigint)
AS
BEGIN
    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET NOCOUNT ON
	Select distinct GENClassrooms.Id,GENClassrooms.Code,GENClassrooms.Name from GENClassrooms 
               Inner join TLMSClassroom_Session ON TLMSClassroom_Session.ClassroomId = GENClassrooms.Id
                where GENClassrooms.IsActive = 1 AND GENClassrooms.IsDeleted = 0 and GENClassrooms.ClassroomCategoryId=2 AND TLMSClassroom_Session.InstructorId =@CurrentEmployeeId
END
GO
