/****** Object:  StoredProcedure [dbo].[SP_NumOfTraineeActiveAndNotActive]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_NumOfTraineeActiveAndNotActive]
@DateF Datetime,
@DateTo Datetime
as
 DECLARE @Trainees INT;
 DECLARE @TraineesActive INT;
 DECLARE @TraineesNotActive INT;
SELECT 
    @Trainees = COUNT(DISTINCT E.id),
    @TraineesActive = COUNT(DISTINCT CASE WHEN Classroom_Session_Instructor.SessionId IS NOT NULL THEN E.id END),
    @TraineesNotActive = COUNT(DISTINCT CASE WHEN Classroom_Session_Instructor.SessionId IS NULL THEN E.id END)
FROM 
    GENEmployees E
LEFT JOIN 
    Classroom_Session_Instructor ON E.Id = Classroom_Session_Instructor.InstructorId
WHERE 
    E.EmployeeCategoryId = 1 
    AND E.IsDeleted = 0 
    AND E.IsActive = 1
    AND (
        (CAST(E.datecreated AS DATE) BETWEEN CAST(@DateF AS DATE) AND CAST(@DateTo AS DATE))
        OR (@DateF IS NULL AND @DateTo IS NULL AND 
            CAST(E.datecreated AS DATE) BETWEEN CAST(DATEADD(MONTH, -1, GETDATE()) AS DATE) AND CAST(GETDATE() AS DATE))
        OR (LEN(@DateF) = 0 AND LEN(@DateTo) = 0)
    );
	select @Trainees Trainees,@TraineesActive TraineesActive,@TraineesNotActive TraineesNotActive




GO
/****** Object:  StoredProcedure [dbo].[SP_Order_CreateNew]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Order_CreateNew](@OrderPrice decimal(18,2)
,@PaidPrice decimal(18,2) ,@UserName nvarchar(500)
,@PhoneNumber nvarchar(500),@UserId nvarchar(500)
,@Name nvarchar(500),@CurrencyId bigint,@ContactId bigint
,@TransactionRequest nvarchar(500) = NULL, @IsPaid BIT,@TypeId bigint,@VcrId bigint,@TalentId bigint)
as

insert into GENOrders(OrderPrice, PaidPrice, RemainingPrice, PaymentType, StatusDateTime, DeliveryDateTime, UserName, PhoneNumber,Langitude,Latitude, UserId, 
                           Name, IsCheckedOut, DateCreated, DateUpdated, CheckoutDate, Timeout, ExpectedCheckoutDate, IsPosted, CurrencyId, ContactId,Bool1,Bool2,Bool3,Bool4,Bool5
						   , TransactionId, IsPaid,TypeId,VcrId,TalentId)
         
values                 (@OrderPrice, @PaidPrice, 0,1, getdate(), Getdate(), @UserName, @PhoneNumber,0,0, @UserId, 
                           @Name, 0, GetDate(), GetDate(), GetDate(), 0, GetDate(), 0, @CurrencyId, @ContactId,0,0,0,0,0
						   , @TransactionRequest, @IsPaid,@TypeId,@VcrId,@TalentId)

						   SELECT cast( SCOPE_IDENTITY() as bigint) as Id
GO
/****** Object:  StoredProcedure [dbo].[SP_Order_Update]    Script Date: 7/1/2026 10:45:03 AM ******/
