GO
CREATE  Proc [dbo].[SP_Order_Update](@orderId bigint,@transactionId nvarchar(MAX),@cardNumber nvarchar(MAX),@contactCardNumber nvarchar(MAX))
as
begin
UPDATE GENOrders
SET IsPaid = 1,
TransactionId = @transactionId,
TransactionCardNumber=@cardNumber,
TransactionContactCardNumber=@contactCardNumber
WHERE Id = @orderId
end
GO
