GO
CREATE Proc [dbo].[SP_OrderDetails_InsertNew](
@OrderId bigint, @ItemName nvarchar(max), @ItemPrice decimal(18, 2), @ItemDiscountPrice decimal(18, 2),
 @ItemTotalPrice decimal(18, 2), @ItemUnitName nvarchar(max), @Quantity int, @CreatedById nvarchar(128),
  @LastUpdatedById nvarchar(128), @Description nvarchar(max), @BaseEntityId bigint,
   @EntityId bigint, @UnitId bigint, @CurrencyId bigint
)
as
INSERT        
INTO   GENOrderDetails( OrderId, ItemName, ItemPrice, ItemDiscountPrice, ItemTotalPrice, ItemUnitName, Quantity, CreatedById, LastUpdatedById, [Description], BaseEntityId, EntityId, UnitId, CurrencyId)
VALUES                 (@OrderId, @ItemName, @ItemPrice, @ItemDiscountPrice, @ItemTotalPrice, @ItemUnitName, @Quantity, @CreatedById, @LastUpdatedById, @Description, @BaseEntityId, @EntityId, @UnitId, @CurrencyId)
SELECT cast( SCOPE_IDENTITY() as bigint) as Id
