SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[SP_OrderRpt] -- SP_OrderRpt null,null,null,null,null,null,null

@ContactId bigint = null,
@VCRId bigint = null,
@FromOrderDate Date=null,
@ToOrderDate Date=null,
@FromVCRDate Date=null,
@ToVCRDate Date=null,
@Type int=null
AS
select
GENOrders.TransactionCardNumber CardNumber,
GENOrders.TransactionContactCardNumber CardName,
GENOrders.Id OrderId,
gencontacts.Name as Trainee,
GENClassrooms.Name as Course,
FORMAT (GENClassrooms.FromDateTime, 'dd-MM-yyyy')  as VCRstartDate,
FORMAT (GENOrders.DateCreated, 'dd-MM-yyyy') as OrderDate,
(CASE 
WHEN GENOrders.paymentType=1 THEN N'Visa' 
ELSE  '' 
END) As Payment,
OrderPrice AS Price
,GENOrders.TransactionId ,FORMAT (GENReturnedOrders.ReturnedOrderDate, 'dd-MM-yyyy') as ReturnedOrderDate,GENOrders.PaidPrice,GENOrders.VcrId,
GENOrders.ContactId,isnull(GENReturnedOrders.PaidPrice,0) as ReturnPaidPrice
from GENOrders
left join gencontacts on GENOrders.ContactId=gencontacts.Id
LEFT JOIN GENClassrooms on GENClassrooms.Id=VcrId
LEFT JOIN GENReturnedOrders on GENOrders.Id=GENReturnedOrders.orderId
WHERE (@ContactId IS NULL OR @ContactId=gencontacts.Id)
AND (@VCRId IS NULL OR @VCRId=GENClassrooms.Id)
AND (@FromOrderDate IS NULL OR len(@FromOrderDate) = 0 OR  @FromOrderDate<=cast(GENOrders.DateCreated as date))
AND (@ToOrderDate IS NULL OR len(@ToOrderDate) = 0 OR  cast(GENOrders.DateCreated as date)<=@ToOrderDate)
AND (@FromVCRDate IS NULL OR len(@FromVCRDate) = 0 OR  @FromVCRDate<=cast(GENClassrooms.FromDateTime as date))
AND (@ToVCRDate IS NULL OR len(@ToVCRDate) = 0 OR  cast(GENClassrooms.FromDateTime as date)<=@ToVCRDate) and GENOrders.TransactionId is not null
GO
/****** Object:  StoredProcedure [dbo].[SP_OrderRpt_ReturnedOrder]    Script Date: 7/1/2026 10:45:03 AM ******/
