/****** Object:  StoredProcedure [dbo].[SP_ParticipatingTrainees]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_ParticipatingTrainees]  --'2019-01-01', '2026-01-01'
@DateF Datetime,
@DateTo Datetime
as
begin


   SELECT 
        GenClassrooms.Id,GenClassrooms.Name AS Experimental_Activity_VCR, 
		(case when GenClassrooms.ClassroomCategoryId = 1 then  isnull(dbo.fn_VcrBookingStudentCount_Confirmed(GenClassrooms.id), 0) when GenClassrooms.ClassroomCategoryId = 2 then GenClassrooms.int1 + isnull(dbo.fn_VcrBookingStudentCount_Confirmed(GenClassrooms.id), 0) end) as Participation
    ,CAST(ROUND(DATEDIFF(MINUTE, CAST(GenClassrooms.FromDateTime AS TIME), CAST(GenClassrooms.ToDateTime AS TIME)), 0)/60.00 AS decimal(18,0))
	*(DATEDIFF(day, CAST(GenClassrooms.FromDateTime AS date), CAST(GenClassrooms.ToDateTime AS date)) + 1)
	AS TotalHours,
	GenClassrooms.FromDateTime ,GenClassrooms.ToDateTime,9 DataSetNo
    FROM  GenClassrooms 
	where ((cast(GenClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GenClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(GenClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GenClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0)) and
	 (GenClassrooms.ClassroomCategoryId = 1 or GenClassrooms.ClassroomCategoryId = 2 )and  GenClassrooms.IsDeleted = 0 and GenClassrooms.ClassRoomStatus = 2 and GenClassrooms.IsActive = 1
    
ORDER BY 
    (case when GenClassrooms.ClassroomCategoryId = 1 then  isnull(dbo.fn_VcrBookingStudentCount_Confirmed(GenClassrooms.id), 0) when GenClassrooms.ClassroomCategoryId = 2 then GenClassrooms.int1 + isnull(dbo.fn_VcrBookingStudentCount_Confirmed(GenClassrooms.id), 0) end)desc;



end
--select count(distinct c.id)as Participation , R.Name  Experimental_Activity_VCR from GenClassrooms R  
--inner join GENClassroom_GENContact cc on cc.classroomId = R.Id
--inner join GenContacts c on cc.studentId = c.Id
--group by  R.Name 


--select  GenClassrooms.Name,sum(DATEDIFF(MINUTE,TLMSClassroom_Session.FromDateTime ,TLMSClassroom_Session.ToDateTime)/60.0)from TLMSClassroom_Session
--inner join GenClassrooms on GenClassrooms.id = TLMSClassroom_Session.classroomid
--group by GenClassrooms.Name
GO
