CREATE Proc [dbo].[Sp_PollCaT_POLLSelectById] (@Id bigint)
as
DECLARE @ProsectionId int=NULL
SELECT @ProsectionId=ProsecutionId from GENPollCategories where Id=@Id
 SELECT DISTINCT GENPolls.*,PollCategoryandPolls.QdOrder, CONVERT(bit, 1) as IsServer ,GENQuestionGroups.Name AS QuestionGroupName,GENQuestionGroups.Id As QuestionGroupId
 from PollCategoryandPolls
 left join
 GENPolls ON GENPolls.Id=PollCategoryandPolls.PollId left join
 GENQuestionGroups ON GENQuestionGroups.Id=PollCategoryandPolls.QuestionGroupId
 where PollCategoryandPolls.PollCategoryId=@Id
GO
