/****** Object:  StoredProcedure [dbo].[SP_ProcessHistory]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		YAHIA ZAKARIA
-- Create date: 04/12/2019
-- Description:	Getting the history 
-- =============================================
CREATE PROCEDURE [dbo].[SP_ProcessHistory] 
	-- Add the parameters for the stored procedure here
	@BaseEntityId bigint, 
	@EntityId bigint
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT *,
	dbo.Diff_BetweenDates(LEAD(Proces.DateCreated) OVER (ORDER BY Proces.DateCreated DESC), Proces.DateCreated) AS AgePrevious FROM 
	(SELECT Proce.[Id]
      ,Proce.[BaseEntityId]
      ,Proce.[ProcessId]
      ,Proce.[UserEntityId]
      ,Proce.[EntityId]
      ,Proce.[DateCreated]
      ,Proce.[DateUpdated]
      ,GENEmployees.Id AS CreatedById, GENStatus.Name AS ProcessName,GENStatus.ColorCode AS ProcessColor,GENStyles.StyleValue AS ProcessIcon,
GENEmployees.Name AS CreatedByName,
FORMAT(Proce.DateCreated, 'dd/MM/yyyy hh:mm:tt') AS DateCreatedString, GENEmployees.[Image] AS CreatedByImage,
Proce.Comment
,Proce.ListValueId
	  ,GENListValues.Name AS ListValueName
FROM GENProcesses as Proce 
INNER JOIN GENStatus ON GENStatus.Id = Proce.ProcessId
LEFT JOIN GENEmployees ON GENEmployees.UserId = Proce.CreatedById
LEFT JOIN GENStyles ON GENStyles.Id = GENStatus.IconId
LEFT JOIN GENListValues ON GENListValues.Id = Proce.ListValueId
WHERE Proce.EntityId = @EntityId AND Proce.BaseEntityId = @BaseEntityId
UNION SELECT 
	   Proce.[Id]
      ,GENProcessHistories.[BaseEntityId]
      ,Proce.[ProcessId]
      ,[UserEntityId]
      ,GENProcessHistories.[EntityId]
      ,GENProcessHistories.[DateCreated]
      ,Proce.[DateUpdated]
      ,GENProcessHistories.[CreatedById], 
	  (CASE WHEN GENProcessHistories.ProcessHistoryType = 1 THEN 'Escalated' ELSE 'Overdue' END) AS ProcessName,
	  (CASE WHEN GENProcessHistories.ProcessHistoryType = 1 THEN '#b51313' ELSE '#ff6600' END) AS ProcessColor,
	  (CASE WHEN GENProcessHistories.ProcessHistoryType = 1 THEN 'fas fa-arrow-up' ELSE 'far fa-clock' END) AS ProcessIcon,
	  (CASE WHEN GENEmployees.Name IS NOT NULL THEN GENEmployees.Name ELSE 'Auto' END) AS CreatedByName,
FORMAT(GENProcessHistories.DateCreated, 'dd/MM/yyyy hh:mm:tt') AS DateCreatedString, GENEmployees.[Image] AS CreatedByImage,
Proce.Comment
,Proce.ListValueId
	  ,GENListValues.Name AS ListValueName
FROM GENProcessHistories
INNER JOIN GENProcesses Proce ON GENProcessHistories.ProcessId = Proce.Id
INNER JOIN GENStatus ON GENStatus.Id = Proce.ProcessId
LEFT JOIN GENEmployees ON GENEmployees.Id = GENProcessHistories.CreatedById
LEFT JOIN GENEmployees EscalatTo ON EscalatTo.Id = GENProcessHistories.CreatedToId
LEFT JOIN GENStyles ON GENStyles.Id = GENStatus.IconId
LEFT JOIN GENListValues ON GENListValues.Id = Proce.ListValueId
WHERE Proce.EntityId = @EntityId AND Proce.BaseEntityId = @BaseEntityId) Proces
ORDER BY DateCreated DESC
	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_Quote_QuoteItems]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Quote_QuoteItems](@quoteId bigint)
as
SELECT        dbo.CRMQuoteItems.Id, dbo.CRMQuoteItems.ItemId, dbo.CRMQuoteItems.DealId, dbo.CRMQuoteItems.DealItemId, dbo.CRMQuoteItems.QuoteId, dbo.CRMQuoteItems.Price, dbo.CRMQuoteItems.Quantity, 
                         dbo.CRMQuoteItems.DealBillQTY, dbo.CRMQuoteItems.DealWOQty, dbo.CRMQuoteItems.UnitId, dbo.CRMQuoteItems.Discount, dbo.CRMQuoteItems.TotalPrice, dbo.CRMQuoteItems.Total, dbo.CRMQuoteItems.OpreationId,(  case dbo.CRMQuoteItems.OpreationId  WHEN  1 then '%' when 2 then 'LE' when 0 then null end ) as OpreationName ,
                         dbo.CRMQuoteItems.DateCreated, dbo.CRMQuoteItems.DateUpdated, dbo.CRMQuoteItems.CreatedById, dbo.CRMQuoteItems.IsPublish, dbo.CRMQuoteItems.IsActive, dbo.CRMQuoteItems.ProjectId, 
                         dbo.CRMDealItems.Quantity AS Dealquantity, dbo.ItemFlatDatas.Name, dbo.ItemFlatDatas.ClassificationName, dbo.ItemFlatDatas.TypeName
FROM            dbo.CRMQuoteItems LEFT  JOIN
                         dbo.CRMDealItems ON dbo.CRMQuoteItems.DealItemId = dbo.CRMDealItems.Id LEFT  JOIN
                         dbo.ItemFlatDatas ON dbo.CRMQuoteItems.Id = dbo.ItemFlatDatas.QuoteItemId


						 where  dbo.CRMQuoteItems.QuoteId = @quoteId
GO
