/****** Object:  StoredProcedure [dbo].[SP_RPT_ActivitiesReport]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE  [dbo].[SP_RPT_ActivitiesReport]  -- SP_RPT_ActivitiesReport '01-01-2020', '01/06/2026',null,null
@DateF datetime = null
,@DateTo datetime = null
,@EventTypeId int
,@ClassRoomStatus int = 2
,@EventTypeIds nvarchar(MAX) = null
,@ClassRoomStatusIds nvarchar(MAX) = null
AS
BEGIN
	SELECT
	GENClassrooms.Id as ClassRoomId,
GENListValues.code as code,
DateDiff(minute,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime) AS [Min],
GENClassrooms.name as ActivityTitle,
GENClassrooms.Instructor_Name as ActivityResponsiblePerson,
GENCompanies.Name as TargetedAudience,
GENClassrooms.[Description],GENRooms.name AS RoomName,
GENClassrooms.FromDateTime  ,GENClassrooms.ToDateTime ,
(GENClassrooms.Int1) + isnull(dbo.fn_VcrStudentCount(GENClassrooms.id),0) as NumberOfParticipants
FROM GENClassrooms 
left join GENListValues on GENClassrooms.EventTypeId = GENListValues.id
left Join GENCompanies 
ON CompanyId=GENCompanies.Id left join GENRooms ON GENClassrooms.RoomId=GENRooms.Id and GENClassrooms.ClassRoomStatus = 2
WHERE GENClassrooms.ClassroomCategoryId=2 and GENClassrooms.IsDeleted=0 and GENClassrooms.IsActive =1 and GENClassrooms.ClassRoomStatus = 2 --AND GENCompanies.CompanyTypeId=5
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null 
and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) )
 or (cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (GENClassrooms.EventTypeId = @EventTypeId or @EventTypeId is null or @EventTypeId = 0) 
and (GENClassrooms.IsDeleted =0) and  (GENClassrooms.ClassRoomStatus = @ClassRoomStatus or @ClassRoomStatus is null or @ClassRoomStatus = -1)

AND (@EventTypeIds IS NULL OR  len(@EventTypeIds) =0 or GENClassrooms.EventTypeId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@EventTypeIds, ',')))

AND (@ClassRoomStatusIds IS NULL OR  len(@ClassRoomStatusIds) =0 or GENClassrooms.ClassRoomStatus IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@ClassRoomStatusIds, ',')))

End
--select  (cast(GENClassrooms.FromDateTime as date)) from GENClassrooms
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_Age_Dashboard]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_Rpt_Age_Dashboard] 
@DateF datetime = null
,@DateTo datetime = null
AS
Begin

	SELECT
	 DATEDIFF(YEAR, BirthDate, GETDATE()) - 
    CASE 
        WHEN DATEADD(YEAR, DATEDIFF(YEAR, BirthDate, GETDATE()), BirthDate) > GETDATE() 
        THEN 1 
        ELSE 0 
    END AS Age

	from GENcontacts 
	where GENcontacts.isdeleted=0 and BirthDate is not null and
	((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )))
	end
GO
/****** Object:  StoredProcedure [dbo].[SP_RPT_ASAGetCourseFieldsandCoursesandClassrooms]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[SP_RPT_ASAGetCourseFieldsandCoursesandClassrooms] --1
(@IsActive bit)
as
begin

 Select Distinct GENClassroom_GENContact.ClassroomId,GENClassroom_GENContact.StudentId,GENTypes.Id As CourseId,
  Format(GENClassrooms.FromDateTime,'dd/MM/yyyy') As FromDateTimeString,Format(GENClassrooms.ToDateTime,'dd/MM/yyyy') As ToDateTimeString,
  GENClassrooms.Name as ClassroomName,GENEmployees.Name As InstructorName,GENEmployees.Id AS InstructorId,
 GENTypes.Name as CourseName,GENTypes.Code as CourseCode,GENClassrooms.Code As ClassroomCode,GENTypeCategories.Code as FieldCode,
 GENContacts.Name as StudentName ,GENTypeCategories.Name as FieldName,GENTypeCategories.Id As FieldId,GENContacts.Position as StudentPosition
from GENClassroom_GENContact 
Left Join GENContacts on  GENClassroom_GENContact.StudentId=GENContacts.Id
Left Join GENClassrooms on GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
Left Join GENEmployees on GENClassrooms.InstructorId=GENEmployees.Id
Left Join GENTypes on GENClassrooms.CourseId= GENTypes.Id
left join CourseCategories on GENTypes.Id = CourseCategories.CourseId
Left Join GENTypeCategories on CourseCategories.CategoryId=GENTypeCategories.Id and GENTypeCategories.IsDeleted=0
--where GENClassrooms.IsDeleted=0 and  GENClassrooms.ClassRoomStatus=2 and GENClassrooms.IsActive=1 and GENClassrooms.IsPublish=1
where 
--((GENTypes.IsActive =@IsActive and GENTypes.IsDeleted=0 and GENClassrooms.IsDeleted=0 and 
--GENContacts.IsDeleted=0 and GENTypeCategories.IsActive=1  and GENTypes.IsActive=1 and GENTypes.IsPublish=1) 
--or @IsActive is null and
( GENTypes.IsDeleted=0 and GENClassrooms.IsDeleted=0 and 
GENContacts.IsDeleted=0and GENTypeCategories.IsActive=1and GENTypes.IsActive=1 )
and GENClassrooms.ClassRoomStatus=2   
--and  ([dbo].[AttendanceCall]([GENClassroom_GENContact].StudentId,GENClassrooms.Id) >=GENClassrooms.Int4) 
End
GO
/****** Object:  StoredProcedure [dbo].[Sp_rpt_CalculateAge_groups_during_themonth]    Script Date: 7/1/2026 10:45:03 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create proc [dbo].[Sp_rpt_CalculateAge_groups_during_themonth] (@GenderID bigint, @DateF datetime,@DateTo datetime)
 as
 begin
Select GENContacts.Id,CRMSources.Name AS SourceName,GENContacts.ContactTypeId,
GENContactTypes.Name As ContactTypeName,GENContacts.GenderId,GENContacts.SourceId,GENListValues.Name As GenderName,GENContacts.DateCreated,
CAST(DATEDIFF(yy, GENContacts.birthdate, getdate()) AS varchar(4)) AS AgeYear
, CAST(DATEDIFF(mm, DATEADD(yy, DATEDIFF(yy,GENContacts.birthdate, getdate()),GENContacts.birthdate), getdate()) AS varchar(2)) AS AgeMonth
,CAST(DATEDIFF(dd, DATEADD(mm, DATEDIFF(mm, DATEADD(yy, DATEDIFF(yy,GENContacts.birthdate, getdate()),GENContacts.birthdate), getdate()), DATEADD(yy, DATEDIFF(yy,GENContacts.birthdate, getdate()),GENContacts.birthdate)), getdate()) AS varchar(2)) as AgeDay
,GENContacts.Birthdate
From GENContacts Left join
CRMSources ON GENContacts.SourceId=CRMSources.Id Left Join
GENContactTypes ON GENContacts.ContactTypeId=GENContactTypes.Id  Left join
GENListValues ON GENContacts.GenderId =GENListValues.Id
where (GENContacts.GenderId = @GenderID or @GenderID is null or @GenderID = 0)
and ((cast(GENContacts.DateCreated as date) >= cast(@DateF as date) and cast(GENContacts.DateCreated as date) <= cast(@DateTo as date)))
End
GO
