CREATE Proc [dbo].[SP_Rpt_City_Dashboard] 
@DateF datetime = null
,@DateTo datetime = null
AS
Begin

select distinct GENcities.Id,GENcities.Name as Name,count(distinct GENcontacts.Id) as TotalStudent,
MONTH(GENcontacts.DateCreated) AS NumMonth
from GENcontacts 
inner join GENAddresses on GENcontacts.Id = GENAddresses.entityId and GENAddresses.baseEntityId=47
inner join GENCountries ON GENAddresses.CountryId=GENCountries.Id
inner join GENcities ON GENAddresses.CityId=GENcities.Id
where GENcontacts.isdeleted=0 and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) 
)
group by GENcities.Id,GENcities.Name ,MONTH(GENcontacts.DateCreated)

END
GO
