CREATE PROCEDURE [dbo].[SP_Rpt_ContactsReg] --  SP_Rpt_ContactsReg null,null,null,null,null,null,null
@GenderId bigint = null,
@CompanyId bigint = null,
@NationalityId bigint = null,
@CompanyTypeId bigint = null,
@QualificationId bigint = null,
@StudentName nvarchar(MAX),
@FromDate Date=null,
@ToDate Date=null,
@StudentMobile nvarchar(MAX),
@StudentEmail nvarchar(MAX),
@StudentPostion nvarchar(MAX),
@StudentAddress nvarchar(MAX),
@StudentQualificationName nvarchar(MAX),
@NationalityIds  nvarchar(MAX),
@CompanyTypeIds  nvarchar(MAX),
@QualificationIds  nvarchar(MAX)


AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT * From Contact_View_Rpt
	

	WHERE
(@GenderId IS NULL OR @GenderId =-1 OR Contact_View_Rpt.GENderId =@GenderId)
AND (@NationalityId IS NULL OR Contact_View_Rpt.CountryId =@NationalityId)
AND (@CompanyId IS NULL OR Contact_View_Rpt.CompanyId =@CompanyId)
AND (@CompanyTypeId IS NULL OR Contact_View_Rpt.DestionationTypeId =@CompanyTypeId)
AND (@QualificationId IS NULL OR Contact_View_Rpt.QualificationId =@QualificationId)
AND (@FromDate IS NULL OR len(@FromDate) = 0 OR  @FromDate<=cast(Contact_View_Rpt.DateCreated as date))
AND (@ToDate IS NULL OR len(@ToDate) = 0 OR  cast(Contact_View_Rpt.DateCreated as date)<=@ToDate)
AND (Contact_View_Rpt.Name like '%'+@StudentName+'%' or @StudentName is null or len(@StudentName) =0)
AND (Contact_View_Rpt.Mobile like '%'+@StudentMobile+'%' or @StudentMobile is null or len(@StudentMobile) =0)
AND (Contact_View_Rpt.DefaultEmail like '%'+@StudentEmail+'%' or @StudentEmail is null or len(@StudentEmail) =0)
AND (Contact_View_Rpt.Position like '%'+@StudentPostion+'%' or @StudentPostion is null or len(@StudentPostion) =0)
AND (Contact_View_Rpt.DefaultAddress like '%'+@StudentAddress+'%' or @StudentAddress is null or len(@StudentAddress) =0)
AND (Contact_View_Rpt.Qualification_Name like '%'+@StudentQualificationName+'%' or @StudentQualificationName is null or len(@StudentQualificationName) =0)

AND (@CompanyTypeIds IS NULL OR  len(@CompanyTypeIds) =0 or Contact_View_Rpt.DestionationTypeId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CompanyTypeIds, ',')))
AND (@QualificationIds IS NULL OR len(@QualificationIds) =0 or Contact_View_Rpt.QualificationId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@QualificationIds, ',')))
AND (@NationalityIds IS NULL OR len(@NationalityIds) =0 or Contact_View_Rpt.CountryId IN (SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@NationalityIds, ',')))

  order by Contact_View_Rpt.DateCreated desc
END
GO
