CREATE PROCEDURE [dbo].[SP_Rpt_ContactsVCRNotReg] --null,null,null
@Search nvarchar(500)
,@DateF datetime = null
,@DateTo datetime = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENContacts.Name,IDNumber,DefaultPhone,DefaultEmail,Position
	From GENContacts
	where (GENContacts.Name like N'%'+@Search+'%' or GENContacts.DefaultPhone like N'%'+@Search+'%' or GENContacts.DefaultEmail like N'%'+@Search+'%' or GENContacts.IDNumber like N'%'+@Search+'%' or @Search is null or len(@Search) = 0)
	 and ((cast(GENContacts.DateCreated as date) >= cast(@DateF as date) and cast(GENContacts.DateCreated as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENContacts.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENContacts.DateCreated as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0)) 
and (GENContacts.id not in (select distinct GENClassroom_GENContact.StudentId from GENClassroom_GENContact))
    order by GENContacts.DateCreated desc

END
