CREATE PROCEDURE [dbo].[SP_Rpt_ContactsVCRReg]
@Search nvarchar(500)
,@ClassroomsId bigint
,@DateF datetime = null
,@DateTo datetime = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENContacts.Name,IDNumber,DefaultPhone,DefaultEmail,Position,GENClassrooms.Code as ClassroomCode,GENClassrooms.Name as ClassroomName,GENClassrooms.FromDateTime
	,GENClassrooms.ToDateTime
	From GENContacts
	inner join GENClassroom_GENContact on GENClassroom_GENContact.StudentId = GENContacts.Id
	inner join GENClassrooms on GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
	inner join GENTypes on GENClassrooms.CourseId = GENTypes.Id
	where (GENContacts.Name like N'%'+@Search+'%' or GENContacts.DefaultPhone like N'%'+@Search+'%' or GENContacts.DefaultEmail like N'%'+@Search+'%'
	                        or GENContacts.IDNumber like N'%'+@Search+'%' or len(@Search) = 0 or @Search is null)
	 and (GENClassrooms.Id = @ClassroomsId or @ClassroomsId is null)
	 and ((cast(GENContacts.DateCreated as date) >= cast(@DateF as date) and cast(GENContacts.DateCreated as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENContacts.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENContacts.DateCreated as date) <= cast(GETDATE() as date)) ) )
--or (@DateF is null and @DateTo is null)
or (len(@DateF) = 0 and len(@DateTo) = 0)) and  ([dbo].[AttendanceCall]([GENContacts].Id,GENClassrooms.Id) >=isnull(GENClassrooms.Int4,GENTypes.int3)) 
and GENClassrooms.ClassRoomStatus = 2
and GENTypes.IsDeleted = 0 and GENClassrooms.IsDeleted = 0 and GENContacts.IsDeleted = 0
    order by GENContacts.DateCreated desc

END
GO
