/****** Object:  StoredProcedure [dbo].[SP_Rpt_DailyAnalysis_Dashboard]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Rpt_DailyAnalysis_Dashboard]
@DateF datetime = null
,@DateTo datetime = null
AS
Begin
SELECT
distinct
 FORMAT(DateCreated, 'dddd', 'ar-eg') AS DayInArabic, 
    count(GENcontacts.Id) As TotalStudents
FROM
    GENcontacts
WHERE 
(cast(GENcontacts.DateCreated as date) between  DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE)) and  
DATEADD(DAY, 7 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE)))
--and GENcontacts.IsUser=1 and GENcontacts.IsDeleted=0
and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) )
group by FORMAT(DateCreated, 'dddd', 'ar-eg')

END
GO
