CREATE Proc [dbo].[SP_Rpt_DestType_Dashboard] 
@DateF datetime = null
,@DateTo datetime = null
AS
Begin

Select GENCompanyTypes.Id,GENCompanyTypes.Name as Name,count(distinct GENcontacts.Id) as TotalStudent
from GENcontacts 
inner join GENCompanies on GENcontacts.CompanyId = GENCompanies.Id
inner join GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id
where GENcontacts.isdeleted=0 and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) 
or (@DateF is null and @DateTo is null and ((cast(GENCompanies.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENCompanies.DateCreated as date) <= cast(GETDATE() as date)) 
or (cast(GENCompanies.DateCreated as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENCompanies.DateCreated as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0))

or (@DateF is null and @DateTo is null and ((cast(GENCompanyTypes.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENCompanyTypes.DateCreated as date) <= cast(GETDATE() as date)) 
or (cast(GENCompanyTypes.DateCreated as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENCompanyTypes.DateCreated as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)))
group by GENCompanyTypes.Id,GENCompanyTypes.Name

END
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_Evaluate_Teatcher_And_Lecture]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create   proc [dbo].[SP_Rpt_Evaluate_Teatcher_And_Lecture]
@DateF datetime = null
,@DateTo datetime = null
,@VCRId int
as
begin 
IF OBJECT_ID('tempdb..TempVCRPollReport') IS NOT NULL
    BEGIN
        DROP TABLE TempVCRPollReport;
    END
 CREATE TABLE TempVCRPollReport (
        IType int,
        DtlsId int,
        VCRId int,
        ExamId int,
        QuestionType int,
        Question nvarchar(max),
        Answer nvarchar(max),
        ClassroomName nvarchar(max),
        SessionId int,
        SessionTitle nvarchar(max),
        Name nvarchar(max),
        Exellent int,
        Good int,
        Normal int,
        Bad int,
        VeryBad int,
        VcrFromDate nvarchar(10),
        VcrToDate nvarchar(10),
        Code nvarchar(max),
        NumberRaters int,
        Comment nvarchar(max),

    );

TRUNCATE TABLE TempVCRPollReport;
INSERT INTO TempVCRPollReport
EXEC [Rpt_VCRPollReportNewRating] @DateF, @DateTo, @VCRId;

select IType,name,SessionTitle,comment from TempVCRPollReport
where TempVCRPollReport.Bad > 0
end
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_Gender_Dashboard]    Script Date: 7/1/2026 10:45:04 AM ******/
