CREATE Proc [dbo].[SP_Rpt_Gender_Dashboard] 
@DateF datetime = null
,@DateTo datetime = null
AS
Begin
Select GENListValues.Id,dbo.fn_ListValue_Translate_ByKeyandId(GENListValues.Id,'Name','ar') as Name,count(distinct GENcontacts.Id) as TotalStudent
,
( CAST((CAST(count(distinct GENcontacts.Id) AS decimal(18,4)) / (select count(distinct GENcontacts.Id) from GENcontacts 
inner join GENListValues on GENcontacts.QualificationId = GENListValues.Id
where GENcontacts.isdeleted=0) ) AS decimal(18,4)) * cast(100 as decimal(18,4)) ) as Precentage,

concat( dbo.fn_ListValue_Translate_ByKeyandId(GENListValues.Id,'Name','ar'),' (','%', Cast( cast( CAST((CAST(count(distinct GENcontacts.Id) AS decimal(18,4)) / (select count(distinct GENcontacts.Id) from GENcontacts 
inner join GENListValues on GENcontacts.GenderId = GENListValues.Id
where GENcontacts.isdeleted=0) ) AS decimal(18,4)) * cast(100 as decimal(18,4))as decimal(18,2) ) as nvarchar(MAX)),') ',Cast (Count(Distinct GENContacts.Id) as nvarchar(MAX) )  ) as LabelName
from GENcontacts 
inner join GENListValues on GENcontacts.GenderId = GENListValues.Id
where GENcontacts.isdeleted=0 and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) 


or (@DateF is null and @DateTo is null and ((cast(GENListValues.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENListValues.DateCreated as date) <= cast(GETDATE() as date)) 
or (cast(GENListValues.DateCreated as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENListValues.DateCreated as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)))
group by GENListValues.Id,GENListValues.Name
END
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_GetClassroomData]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 30/11/2020
-- Description:	Get Classrooms
-- =============================================
CREATE PROCEDURE [dbo].[SP_Rpt_GetClassroomData]
	-- Add the parameters for the stored procedure here
	@FromDate DATETIME = NULL,--This is Start date for classroom
	@ToDate DATETIME = NULL, -- This is to date for classrom
	@FinalExamStartDateTime DATETIME = NULL,--This is exam Start date for final exam in classroom
	@FinalExamEndDateTime DATETIME = NULL,--This is exam end date for final exam in classroom
	@ClassroomId BIGINT = NULL, -- Classroom Id to select data according to classroom
	@CourseId	 BIGINT = NULL,-- Course Id to select data according to course Id
	@StudentId	 BIGINT = NULL, -- Student Id to select Data According to Student Id
	@ContactTypeId	 BIGINT = NULL -- Student Id to select Data According to Student Id
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT * FROM Classroom_View_Rpt 
	WHERE (@FromDate IS NULL OR FromDateTime >= @FromDate) AND (@ToDate IS NULL OR ToDateTime <= @ToDate)
	AND (@FinalExamStartDateTime IS NULL OR ExamStartTime >= @FinalExamStartDateTime) AND (@FinalExamEndDateTime IS NULL OR ExamEndTime <= @FinalExamEndDateTime)
	AND (@ClassroomId IS NULL OR Id = @ClassroomId) AND (@CourseId IS NULL OR CourseId = @CourseId) AND (@StudentId IS NULL OR StudentId = @StudentId)
	AND (@ContactTypeId IS NULL OR ContactTypeId = @ContactTypeId)
END
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_GetClassroomExamResults]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_Rpt_GetClassroomExamResults]--SP_Rpt_GetClassroomExamResults 42987,69
	@longId1 BIGINT = NULL,
	@longId2 BIGINT = NULL, 
	@longId3 BIGINT = NULL
AS
BEGIN
	SET NOCOUNT ON;

	SELECT distinct
        -- كل الأعمدة المطلوبة كما هي من الجدول الرئيسي
	    EHR.[Id], EHR.[StudentId], EHR.[StudentName], EHR.[ExamId],
        GPC.Name as [ExamName], EHR.[ExamWeight], EHR.[ExamTime], EHR.[CourseId],
        EHR.[CourseName], EHR.[StartDateTime], EHR.[EndtDateTime],
        EHR.[ScoreDegree], EHR.[InstructorId], EHR.[InstructorName], EHR.[TotalQuestionsNumber],
        EHR.[TotalExamScore], EHR.[TotalScore], EHR.[TotalNeedRevisedQuestions], EHR.[TotalNeedRevisedQuestionsScore],
        EHR.[TotalNoNeedRevisedQuestions], EHR.[TotalNoNeedRevisedQuestionsScore], EHR.[Code],
        EHR.[Name], EHR.[Description], EHR.[ColorCode], EHR.[IsCheckedOut],
        EHR.[DateCreated], EHR.[DateUpdated], EHR.[CheckinDate], EHR.[CheckoutDate],
        EHR.[ExpectedCheckoutDate], EHR.[Timeout], EHR.[DisplayOrdering], EHR.[CreatedById],
        EHR.[LastUpdatedById], EHR.[CheckoutBy], EHR.[String1], EHR.[String2],
        EHR.[String3], EHR.[String4], EHR.[String5], EHR.[Int1],
        EHR.[Int2], EHR.[Int3], EHR.[Int4], EHR.[Int5], EHR.[Long1],
        EHR.[Long2], EHR.[Long3], EHR.[Long4], EHR.[Long5], EHR.[Float1],
        EHR.[Float2], EHR.[Float3], EHR.[Float4], EHR.[Float5], EHR.[Decimal1],
        EHR.[Decimal2], EHR.[Decimal3], EHR.[Decimal4], EHR.[Decimal5], EHR.[Bool1],
        EHR.[Bool2], EHR.[Bool3], EHR.[Bool4], EHR.[Bool5], EHR.[Date1],
        EHR.[Date2], EHR.[Date3], EHR.[Date4], EHR.[Date5], EHR.[ValueId1],
        EHR.[ValueId2], EHR.[ValueId3], EHR.[ValueId4], EHR.[ValueId5], EHR.[IconId],
        EHR.[ClassroomId], EHR.[ClassroomName], 
        GGC.DisplayDateTime as [ClassroomStartTimeExam],
	    DATEADD(MINUTE, GPC.Time, GGC.DisplayDateTime) as [ClassroomEndTimeExam],
        EHR.[IsJunk], EHR.[ReasonString], EHR.[SubmitionStudentName], EHR.[ExpectedExamEndDate],
        EHR.[IsClosedByService], EHR.[IsPosted], EHR.[IP], EHR.[MACAddress],
        EHR.[ClassroomFromDateTime], EHR.[ClassroomToDateTime], EHR.[ClassroomCode], EHR.[ExamAnswerType],
        EHR.[ExamStartTime], EHR.[ExamEndTime], EHR.[ClassroomExamId],
	
        -- الحسابات المعتمدة على الـ Logic بتاعك
	    (CASE WHEN ISNULL(EHR.[AnnouncedDegree], 0) = 0 OR (EHR.[TotalExamScore] > 0 AND EHR.[AnnouncedDegree] = 0) THEN 
	        CAST((ISNULL(EHR.[TotalExamScore],0) * ISNULL(EHR.[ExamWeight], GPC.Weight)) / NULLIF(EHR.TotalScore, 0) AS decimal(18,2)) 
        ELSE EHR.[AnnouncedDegree] END) AS AnnouncedDegree,

	    (CASE WHEN ISNULL(EHR.[AnnouncedDegree], 0) = 0 OR (EHR.[TotalExamScore] > 0 AND EHR.[AnnouncedDegree] = 0) THEN 
	        CAST((ISNULL(EHR.[TotalExamScore],0) ) / NULLIF(EHR.TotalScore, 0) AS decimal(18,2)) 
        ELSE EHR.[AnnouncedDegree] END) AS AnnouncedDegreeOrder,

	    '' AS StudentCode, '' AS InstructorCode, '' AS CourseCode, GPC.Code AS ExamCode,
	    GPC.Time AS ExamPeriodTime, GPC.SuccessScore, Sessions.SessionsCount AS SessionsCount,
	    EHR.[TotalQuestionsNumber] AS QuestionsCount, 
        
        -- سحب البيانات المحسوبة من الـ Sub-Query
        QStats.QuestionsTotalWeight,
	    (SELECT COUNT(DISTINCT StudentId) FROM [dbo].[ExamHeaderResults] WHERE ExamId = EHR.ExamId AND IsPosted = 1) AS ExaminersCount, 
        (EHR.TotalExamScore) AS AverageTotalScore, -- ملحوظة: لو محتاج متوسط حقيقي لكل الطلاب شيل EHR وحط Subquery
	    CAST(EHR.AnnouncedDegree AS DECIMAL(18,2)) AS AverageAnnouncedScore,
	    (QStats.TotalQuestionsInBank - EHR.[TotalQuestionsNumber]) AS TotalNotAnswerQuestions,
	    EHR.TotalCorrectAnswers, EHR.TotalWrongAnswers

	FROM [dbo].[ExamHeaderResults] EHR
	LEFT JOIN GENExam_GENClassroom GGC ON EHR.ClassroomId = GGC.ClassroomId AND GGC.ExamId = EHR.ExamId
	LEFT JOIN GENPollCategories GPC ON EHR.ExamId = GPC.Id
    -- الـ Sub-query ده بيحسب أوزان الأسئلة مرة واحدة لكل امتحان بدل ما يكرر الصفوف
    LEFT JOIN (
        SELECT cp.PollCategoryId, 
               SUM(ISNULL(p.Weight, 0)) as QuestionsTotalWeight,
               COUNT(DISTINCT cp.Id) as TotalQuestionsInBank
        FROM PollCategoryandPolls cp
        JOIN GENPolls p ON cp.PollId = p.Id
        GROUP BY cp.PollCategoryId
    ) QStats ON GPC.Id = QStats.PollCategoryId
	 LEFT JOIN (
        SELECT ts.ClassroomId, 
               COUNT(DISTINCT ts.Id) as SessionsCount
        FROM TLMSClassroom_Session ts
        GROUP BY ts.ClassroomId
    ) Sessions ON EHR.ClassroomId = Sessions.ClassroomId
	LEFT JOIN TLMSClassroom_Session ON TLMSClassroom_Session.ClassroomId = EHR.ClassroomId
	WHERE (EHR.ClassroomId = @longId1 OR @longId1 IS NULL OR @longId1 = 0) 
      AND (EHR.ExamId = @longId2 OR @longId2 IS NULL OR @longId2 = 0) 
      AND (EHR.StudentId = @longId3 OR @longId3 IS NULL OR @longId3 = 0) 
      AND EHR.IsPosted = 1

	ORDER BY AnnouncedDegreeOrder DESC
    OPTION (RECOMPILE); 
END
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_Lang_Dashboard]    Script Date: 7/1/2026 10:45:04 AM ******/
