/****** Object:  StoredProcedure [dbo].[SP_Rpt_RegisterOrNot_Dashboard]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Rpt_RegisterOrNot_Dashboard] 
@DateF datetime = null
,@DateTo datetime = null
AS
Begin

SELECT N'ملتحقين' AS Name,Count (GENContacts.Id) AS TotalStudent

,
( CAST((CAST(count(distinct GENcontacts.Id) AS decimal(18,4)) / (select count(distinct GENcontacts.Id) From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0) ) AS decimal(18,4)) * cast(100 as decimal(18,4)) ) as Precentage,


	concat(  N'ملتحقين',' (','%', Cast( cast( CAST((CAST(count(distinct GENcontacts.Id) AS decimal(18,4)) / (select count(distinct GENcontacts.Id) From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0) ) AS decimal(18,4)) * cast(100 as decimal(18,4))as decimal(18,2) ) as nvarchar(MAX)),') ',Cast (Count(Distinct GENContacts.Id) as nvarchar(MAX) )  ) as LabelName





	From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0

and

(GENContacts.id  in (select distinct GENClassroom_GENContact.StudentId 
from GENClassroom_GENContact inner join GENClassrooms ON GENClassroom_GENContact.ClassroomId = 
GENClassrooms.Id where GENClassrooms.Isdeleted=0 ))
and 
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) )



union
SELECT N'غير ملتحقين' AS Name,Count (GENContacts.Id) AS TotalStudent
,
( CAST((CAST(count(distinct GENcontacts.Id) AS decimal(18,4)) / (select count(distinct GENcontacts.Id) From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0) ) AS decimal(18,4)) * cast(100 as decimal(18,4)) ) as Precentage,


	concat(   N'غير ملتحقين',' (','%', Cast( cast( CAST((CAST(count(distinct GENcontacts.Id) AS decimal(18,4)) / (select count(distinct GENcontacts.Id) From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0) ) AS decimal(18,4)) * cast(100 as decimal(18,4))as decimal(18,2) ) as nvarchar(MAX)),') ',Cast (Count(Distinct GENContacts.Id) as nvarchar(MAX) )  ) as LabelName


	From GENContacts
	where GENContacts.IsActive=1 and GENContacts.IsDeleted=0

and 


(GENContacts.id NOT in (select distinct GENClassroom_GENContact.StudentId 
from GENClassroom_GENContact inner join GENClassrooms ON GENClassroom_GENContact.ClassroomId = 
GENClassrooms.Id where GENClassrooms.Isdeleted=0 ))

and 
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) )


END
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_RequestesUsers]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Rpt_RequestesUsers]
(
@FromDate Date=null,
@ToDate Date=null,
@TicketTypeId bigint = null,
@StatusId bigint = null,
@ProsecutionId int = null,
@SectionId bigint = null,
@PriorityId bigint = null,
@Search nvarchar(MAX),
@SourceId bigint = null)
AS
Begin


Select CRMTicket_View_Update.Id,CRMTicket_View_Update.TicketTypeId,CRMTicket_View_Update.TicketTypeName,CRMTicket_View_Update.StatusId,CRMTicket_View_Update.StatusName,
(case when CRMTicket_View_Update.ProsecutionId = 2 then N'بحوث' when CRMTicket_View_Update.ProsecutionId = 4 then N'الامين العام'
when CRMTicket_View_Update.ProsecutionId = 1 then N'الدراسات العليا' when CRMTicket_View_Update.ProsecutionId = 3 then N'الاتصالات والعلاقات الدولية' when CRMTicket_View_Update.ProsecutionId = 0 then N'التخطيط والتدريب' end)as Prosecution,
CRMTicket_View_Update.valueId2tName AS SectionName,CRMTicket_View_Update.PriortyName,Name,SourceName,Date1String AS ReportingDateString,CloseDateString,Description,
String2 AS SupportReply,Date3String


from CRMTicket_View_Update

Where 
(@TicketTypeId IS NULL OR @TicketTypeId =-1 OR CRMTicket_View_Update.TicketTypeId =@TicketTypeId)
AND (@StatusId IS NULL OR CRMTicket_View_Update.StatusId =@StatusId)
AND (@ProsecutionId IS NULL OR CRMTicket_View_Update.ProsecutionId =@ProsecutionId)
AND (@FromDate IS NULL OR len(@FromDate) = 0 OR  @FromDate<=cast(CRMTicket_View_Update.DateCreated as date))
AND (@ToDate IS NULL OR len(@ToDate) = 0 OR  cast(CRMTicket_View_Update.DateCreated as date)<=@ToDate)
AND( (CRMTicket_View_Update.Description like '%'+@Search+'%' or @Search is null or len(@Search) =0)
or (CRMTicket_View_Update.String2 like '%'+@Search+'%' or @Search is null or len(@Search) =0))
AND (@SectionId IS NULL OR CRMTicket_View_Update.ValueId2 =@SectionId)
AND (@PriorityId IS NULL OR CRMTicket_View_Update.PriortyId =@PriorityId)
AND (@SourceId IS NULL OR CRMTicket_View_Update.SourceId =@SourceId)
END
GO
