/****** Object:  StoredProcedure [dbo].[SP_Rpt_SectorsSections_Dashboard]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Rpt_SectorsSections_Dashboard] 
@DateF datetime = null
,@DateTo datetime = null
AS
Begin
Select GENListValues.Id,dbo.fn_ListValue_Translate_ByKeyandId(GENListValues.Id,'Name','ar') as Name,count(distinct GENcontacts.Id) as TotalStudent
from GENcontacts 
inner join GENCompanies on GENcontacts.CompanyId = GENCompanies.Id
inner join GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id
inner join GENListValues ON GENCompanyTypes.ValueId1=GENListValues.Id
where GENcontacts.isdeleted=0 and
((((cast(GENcontacts.DateCreated as date) <= @DateF and cast(GENcontacts.DateCreated as date) >= @DateF) AND   (cast(GENcontacts.DateCreated as date) <= @DateTo and cast(GENcontacts.DateCreated as date) >= @DateTo))  OR
(@DateF <= cast(GENcontacts.DateCreated as date) AND @DateF >= cast(GENcontacts.DateCreated as date)) OR (@DateF <= cast(GENcontacts.DateCreated as date) AND @DateTo >= cast(GENcontacts.DateCreated as date) )) 


or (@DateF is null and @DateTo is null and ((cast(GENListValues.DateCreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENListValues.DateCreated as date) <= cast(GETDATE() as date)) 
or (cast(GENListValues.DateCreated as date) >= cast(DATEADD(month,1,GETDATE()) as date) and cast(GENListValues.DateCreated as date) <= cast(GETDATE() as date)))
or (len(@DateF) = 0 and len(@DateTo) = 0)))
group by GENListValues.Id,GENListValues.Name
END
GO
/****** Object:  StoredProcedure [dbo].[SP_RPT_SelectExams_PreandPost]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_RPT_SelectExams_PreandPost]
@DateF datetime
,@DateTo datetime
,@ClassroomId int
,@CourseId int
,@classroomIds nvarchar(MAX) = null
,@courseIds nvarchar(MAX) = null
AS
Begin
Select distinct Pre.Id AS PreExamId,Pre.Name AS PreExamName,(CASE WHEN ISNULL(PreExHeader.[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL(PreExHeader.[TotalExamScore],0) * ISNULL(PreExHeader.[ExamWeight], 0)) / PreExHeader.TotalScore AS decimal(18,2)) 
	  ELSE PreExHeader.[AnnouncedDegree] END) AS PreExamScore
	  ,PreExHeader.DateCreated AS PreExDateCreated 
	  ,PostExHeader.DateCreated AS PostExDateCreated 
	  ,Post.Id AS PostExamId
	  ,Pre.Name AS PostExamName,(CASE WHEN ISNULL(PostExHeader.[AnnouncedDegree], 0) = 0 THEN 
	  CAST((ISNULL(PostExHeader.[TotalExamScore],0) * ISNULL(PostExHeader.[ExamWeight], 0)) / PostExHeader.TotalScore AS decimal(18,2)) 
	  ELSE PostExHeader.[AnnouncedDegree] END) as PostExamScore,
	  GENContacts.Name AS StudentName,
	  PreExHeader.StudentId,PreExHeader.ExamWeight AS ExamWeight,PreExHeader.ClassroomName as ClassroomName
	  ,PreExHeader.CourseName as CourseName,GENClassrooms.code as ClassroomCode
From GENPollCategories Pre inner join 
GENExamAnswerHeaders PreExHeader ON Pre.Id =PreExHeader.ExamId and Pre.ExamType =9 
inner join GENContacts ON PreExHeader.StudentId = GENContacts.Id 
inner join GENClassrooms on GENClassrooms.Id = PreExHeader.ClassroomId
inner join GENPollCategories Post ON Pre.Id = Post.ParentId 
inner join GENExamAnswerHeaders PostExHeader ON Post.Id =PostExHeader.ExamId and Post.ExamType =10 and PostExHeader.StudentId = GENContacts.Id and PostExHeader.ClassroomId = GENClassrooms.Id
where ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null and ((cast(GENClassrooms.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(GENClassrooms.FromDateTime as date) <= cast(GETDATE() as date)) ) )
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (PreExHeader.ClassroomId = @ClassroomId or @ClassroomId is null or @ClassroomId = -1)
and (PreExHeader.CourseId = @CourseId or @CourseId is null or @CourseId = -1)

AND (@courseIds IS NULL OR  len(@courseIds) =0 or GENClassrooms.CourseId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@courseIds, ',')))

AND (@classroomIds IS NULL OR  len(@classroomIds) =0 or GENClassrooms.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@classroomIds, ',')))

--inner join GENExamAnswerDetails ON PreExHeader.Id=GENExamAnswerDetails.ExamAnswerHeaderId
--inner join GENExamAnswerDetails PostDegree ON PostExHeader.Id=PostDegree.ExamAnswerHeaderId and PostDegree.PollId = GENExamAnswerDetails.PollId
End
GO
/****** Object:  StoredProcedure [dbo].[SP_RPT_SelectGeneratedAttendance]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  Proc [dbo].[SP_RPT_SelectGeneratedAttendance] --126

(@ClassroomId Bigint,@SessionId Bigint
 ,@ContactId Bigint
 ,@Date datetime
  ,@ExecuseId Bigint)
AS
Begin
Select distinct  GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,GENItems.Id AS SessionId,GENItems.Code AS SessionCode,GENItems.Name AS SessionName,FORMAT(TLMSClassroom_Session.SessionDateTime, 'MM/dd/yyyy') as SessionDate,
Classroom_Attendance.Id AS Id,Classroom_Attendance.ClassroomId,Classroom_Attendance.IsAttendance,row_number() OVER (ORDER BY GENclassrooms.Id) Id2
,Classroom_Attendance.ExecuseId,GENListValues.Name as ExecuseName,Classroom_Attendance.Notes,GENClassrooms.Name AS VcrName,GENClassrooms.Code AS VcrCode,
TLMSClassroom_Session.SessionDateTime
From Classroom_Attendance 
inner join GENClassrooms ON Classroom_Attendance.ClassroomId =  GENClassrooms.Id  
inner join GENClassroom_GENContact ON Classroom_Attendance.ClassroomId=GENClassroom_GENContact.ClassroomId 
and Classroom_Attendance.StudentId= GENClassroom_GENContact.StudentId
inner join GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id 
inner join TLMSClassroom_Session ON Classroom_Attendance.ClassroomId=TLMSClassroom_Session.ClassroomId and  Classroom_Attendance.SessionId= TLMSClassroom_Session.SessionId 
inner join GENItems ON TLMSClassroom_Session.SessionId=GENItems.Id
left join GENListValues on Classroom_Attendance.ExecuseId = GENListValues.Id
where Classroom_Attendance.ClassroomId=@ClassroomId and (TLMSClassroom_Session.SessionId = @SessionId or @SessionId is null or @SessionId = 0)
and(GENClassroom_GENContact.StudentId = @ContactId or @ContactId is null or @ContactId = 0)and(Classroom_Attendance.ExecuseId = @ExecuseId or @ExecuseId is null or @ExecuseId = 0)
and(TLMSClassroom_Session.SessionDateTime = @Date or @Date is null )


END
GO
/****** Object:  StoredProcedure [dbo].[SP_RPT_SelectVcrContactsWithNationality]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_RPT_SelectVcrContactsWithNationality] (@contactId bigint=null,@vcrId bigint=null,@NationalityId bigint=null,@DateF datetime = null
,@DateTo datetime = null,@ageLowerLimit int=null , @ageUpperLimit int=null,@GenderId bigint=null,@OrganizationId bigint=null)
AS
Begin

Select GENClassrooms.Id AS VcrId,GENClassrooms.Name AS VcrName,GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,
GENContacts.IdNumber,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,
nation.countryId AS NationalityId,GENCountries.Name As NationalityName,GENCompanies.Name AS SideName,GENCompanies.Id AS SideId,
GENClassrooms.Code AS VcrCode
from GENClassroom_GENContact inner join 
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 
GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id left join 
GENAddresses nation ON GENContacts.Id=nation.entityId and nation.baseEntityId=47 left join 
GENCountries ON nation.countryId=GENCountries.Id left join 
GENCompanies ON GENContacts.OrganizationId=GENCompanies.Id
where  (@contactId IS NULL OR GENClassroom_GENContact.StudentId=@contactId ) 
and (@vcrId IS NULL OR GENClassroom_GENContact.ClassroomId=@vcrId ) 
and ((@NationalityId IS NULL OR nation.CountryId=@NationalityId ))
and GENContacts.IsDeleted=0 and GENContacts.contactCategoryId=1 and GENClassrooms.IsDeleted=0
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null)
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (@ageLowerLimit is null OR @ageLowerLimit<((CONVERT(int,CONVERT(char(8),GETDATE(),112))-CONVERT(char(8),GENContacts.BirthDate,112))/10000))
and (@ageUpperLimit is null OR @ageUpperLimit>((CONVERT(int,CONVERT(char(8),GETDATE(),112))-CONVERT(char(8),GENContacts.BirthDate,112))/10000))
AND (@GenderId IS NULL OR GENContacts.GenderId=@GenderId or @GenderId = -1 ) 
and ((@OrganizationId IS NULL OR GENContacts.OrganizationId=@OrganizationId ))

END
GO
