CREATE Proc [dbo].[SP_RPT_SelectVcrContactsWithSides] (@contactId bigint=null,@vcrId bigint=null,@OrganizationId bigint=null,@DateF datetime = null
,@DateTo datetime = null,@GenderId bigint=null,@ageLowerLimit int=null , @ageUpperLimit int=null ,@NationalityId bigint=null)
AS
Begin

Select distinct GENClassrooms.Id AS VcrId,GENClassrooms.Name AS VcrName,GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,
GENContacts.IdNumber,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,
nation.countryId AS NationalityId,GENCountries.Name As NationalityName,GENCompanies.Name AS SideName,GENCompanies.Id AS SideId,GENClassrooms.Code AS VcrCode,

Qualification.Name AS QualificationName,[GENContacts].Qualification_Name,
dbo.getCurrentlVCRs(GENContacts.Id) AS CurrentVcrs,Gender.Name AS GenderName,[GENContacts].QualificationId,[GENContacts].GenderId ,
GENCompanyTypes.Name AS DestionationType,GENContacts.DateCreated,GENContacts.Position


from GENClassroom_GENContact inner join 
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 

GENContacts ON GENClassroom_GENContact.StudentId=GENContacts.Id left join 

GENAddresses nation ON GENContacts.Id=nation.entityId and nation.baseEntityId=47 left join 

GENCountries ON nation.countryId=GENCountries.Id left join 

GENCompanies ON GENContacts.CompanyId=GENCompanies.Id LEFT JOIN 
GENListValues Qualification ON [GENContacts].QualificationId  = Qualification.Id  LEFT JOIN
GENListValues Gender ON [GENContacts].GENderId  = Gender.Id inner JOIN 

GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id




where  (@contactId IS NULL OR GENClassroom_GENContact.StudentId=@contactId ) 
and (@vcrId IS NULL OR GENClassroom_GENContact.ClassroomId=@vcrId ) 
and ((@OrganizationId IS NULL OR GENContacts.OrganizationId=@OrganizationId ))
and GENContacts.IsDeleted=0 and  GENClassrooms.IsDeleted=0
and ((cast(GENClassrooms.FromDateTime as date) >= cast(@DateF as date) and cast(GENClassrooms.FromDateTime as date) <= cast(@DateTo as date)) 
or (@DateF is null and @DateTo is null)
or (len(@DateF) = 0 and len(@DateTo) = 0))
and (@ageLowerLimit is null OR @ageLowerLimit<((CONVERT(int,CONVERT(char(8),GETDATE(),112))-CONVERT(char(8),GENContacts.BirthDate,112))/10000))
and (@ageUpperLimit is null OR @ageUpperLimit>((CONVERT(int,CONVERT(char(8),GETDATE(),112))-CONVERT(char(8),GENContacts.BirthDate,112))/10000))
AND (@GenderId IS NULL OR GENContacts.GenderId=@GenderId or @GenderId = -1 ) 
AND (@NationalityId IS NULL OR GENCountries.Id=@NationalityId or @NationalityId = -1) 
END
GO
/****** Object:  StoredProcedure [dbo].[SP_RPT_SelectVcrContactsWithSides_V2]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
