CREATE Proc [dbo].[SP_RPT_SelectVcrContactsWithSides_V2] (
@GenderId bigint = null,
@CompanyId bigint = null,
@NationalityId bigint = null,
@CompanyTypeId bigint = null,
@QualificationId bigint = null,
@StudentName nvarchar(MAX),
@FromDate Date=null,
@ToDate Date=null,
@StudentMobile nvarchar(MAX),
@StudentEmail nvarchar(MAX),
@StudentPostion nvarchar(MAX),
@StudentAddress nvarchar(MAX),
@StudentQualificationName nvarchar(MAX),
@NationalityIds  nvarchar(MAX),
@CompanyTypeIds  nvarchar(MAX),
@QualificationIds  nvarchar(MAX),
@CompanyIds  nvarchar(MAX)
)
AS
Begin

Select distinct GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,
GENContacts.IdNumber,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.DefaultAddress,
nation.countryId AS NationalityId,GENCountries.Name As NationalityName,GENCompanies.Name AS SideName,GENCompanies.Id AS SideId,

Qualification.Name AS QualificationName,[GENContacts].Qualification_Name,
dbo.getCurrentlVCRs(GENContacts.Id) AS CurrentVcrs,Gender.Name AS GenderName,[GENContacts].QualificationId,[GENContacts].GenderId ,
GENCompanyTypes.Name AS DestionationType,GENContacts.DateCreated,GENContacts.Position,GENCompanyTypes.Id AS DestionationTypeId,
DestOther.Id as DesttId


from GENContacts left join 

GENAddresses nation ON GENContacts.Id=nation.entityId and nation.baseEntityId=47 left join 

GENCountries ON nation.countryId=GENCountries.Id left join 

GENCompanies ON GENContacts.CompanyId=GENCompanies.Id LEFT JOIN 
GENListValues Qualification ON [GENContacts].QualificationId  = Qualification.Id  LEFT JOIN
GENListValues Gender ON [GENContacts].GENderId  = Gender.Id inner JOIN 


GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id inner join
GENListValues DestOther ON GENCompanyTypes.ValueId1=DestOther.Id



where 
(@GenderId IS NULL OR @GenderId =-1 OR GENContacts.GenderId =@GenderId)
AND (@NationalityId IS NULL OR nation.CountryId =@NationalityId)
AND (@CompanyId IS NULL OR GENContacts.CompanyId =@CompanyId)
AND (@CompanyTypeId IS NULL OR GENCompanyTypes.Id =@CompanyTypeId)
AND (@QualificationId IS NULL OR GENContacts.QualificationId =@QualificationId)
AND (@FromDate IS NULL OR len(@FromDate) = 0 OR  @FromDate<=cast(GENContacts.DateCreated as date))
AND (@ToDate IS NULL OR len(@ToDate) = 0 OR  cast(GENContacts.DateCreated as date)<=@ToDate)
AND (GENContacts.Name like '%'+@StudentName+'%' or @StudentName is null or len(@StudentName) =0)
AND (GENContacts.DefaultPhone like '%'+@StudentMobile+'%' or @StudentMobile is null or len(@StudentMobile) =0)
AND (GENContacts.DefaultEmail like '%'+@StudentEmail+'%' or @StudentEmail is null or len(@StudentEmail) =0)
AND (GENContacts.Position like '%'+@StudentPostion+'%' or @StudentPostion is null or len(@StudentPostion) =0)
AND (GENContacts.DefaultAddress like '%'+@StudentAddress+'%' or @StudentAddress is null or len(@StudentAddress) =0)
AND (GENContacts.Qualification_Name like '%'+@StudentQualificationName+'%' or @StudentQualificationName is null or len(@StudentQualificationName) =0)
AND GENContacts.IsDeleted=0 

AND (@CompanyIds IS NULL OR  len(@CompanyIds) =0 or GENCompanies.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CompanyIds, ',')))

AND (@CompanyTypeIds IS NULL OR  len(@CompanyTypeIds) =0 or GENCompanyTypes.Id IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@CompanyTypeIds, ',')))
AND (@QualificationIds IS NULL OR len(@QualificationIds) =0 or GENContacts.QualificationId IN ( SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@QualificationIds, ',')))
AND (@NationalityIds IS NULL OR len(@NationalityIds) =0 or nation.CountryId IN (SELECT CAST(value AS BIGINT)
    FROM STRING_SPLIT(@NationalityIds, ',')))
--(@contactId IS NULL OR GENContacts.Id=@contactId ) 
--and ((@OrganizationId IS NULL OR GENContacts.CompanyId=@OrganizationId ))
--and

--and  GENClassrooms.IsDeleted=0

--or (@DateF is null and @DateTo is null)
--or (len(@DateF) = 0 and len(@DateTo) = 0))
--and (@ageLowerLimit is null OR @ageLowerLimit<((CONVERT(int,CONVERT(char(8),GETDATE(),112))-CONVERT(char(8),GENContacts.BirthDate,112))/10000))
--and (@ageUpperLimit is null OR @ageUpperLimit>((CONVERT(int,CONVERT(char(8),GETDATE(),112))-CONVERT(char(8),GENContacts.BirthDate,112))/10000))
--AND (@GenderId IS NULL OR GENContacts.GenderId=@GenderId or @GenderId = -1 ) 
--AND (@NationalityId IS NULL OR GENCountries.Id=@NationalityId or @NationalityId = -1) 
END
GO
/****** Object:  StoredProcedure [dbo].[Sp_rpt_Statisticalcasesbysource]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[Sp_rpt_Statisticalcasesbysource]  (@SourceID bigint, @DateF datetime,@DateTo datetime,@NumberOfYears bigint = null,@GenderId bigint = null)
 as
 begin
 select * from (
Select GENContacts.Id,CRMSources.Name AS SourceName,GENContacts.ContactTypeId,GENContactTypes.Name As ContactTypeName,GENContacts.GenderId,GENContacts.SourceId,GENListValues.Name As GenderName,GENContacts.DateCreated
,Diff.years as Ageyears,Diff.Months as AgeMonths,Diff.Days as AgeDays 
From GENContacts Left join
CRMSources ON GENContacts.SourceId=CRMSources.Id Left Join
GENContactTypes ON GENContacts.ContactTypeId=GENContactTypes.Id  Left join
GENListValues ON GENContacts.GenderId =GENListValues.Id
CROSS APPLY [dbo].[FindDateDiff](isnull(BirthDate,GETDATE()),GETDATE(),1) as Diff
where (GENContacts.SourceId = @SourceID or @SourceID is null or @SourceID = 0or len(@SourceID) = 0) 
and (GENContacts.GenderId = @GenderId or @GenderId is null or @GenderId = 0)  and GENContacts.IsDeleted =0
and ((cast(GENContacts.DateCreated as date) >= cast(@DateF as date) and cast(GENContacts.DateCreated as date) <= cast(@DateTo as date)))
) as res
where 
((@NumberOfYears = 0 and Ageyears <= 5) or 
       (@NumberOfYears = 1 and Ageyears > 5 and Ageyears < 13) or
	   (@NumberOfYears = 2 and Ageyears > 12 and Ageyears < 19) or
	   (@NumberOfYears = 3 and Ageyears > 18 and Ageyears < 31) or
	   (@NumberOfYears = 4 and Ageyears > 30 and Ageyears < 41) or
	   (@NumberOfYears = 5 and Ageyears > 40 and Ageyears < 51) or
	   (@NumberOfYears = 6 and Ageyears > 50 and Ageyears < 61) or
	   (@NumberOfYears = 7 and Ageyears > 60 and Ageyears < 71) or
	   @NumberOfYears is null or @NumberOfYears = -1)
End
GO
/****** Object:  StoredProcedure [dbo].[SP_Rpt_VcrStudents_Export]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_Rpt_VcrStudents_Export] --SP_Rpt_VcrStudents_Export 194

(@ClassroomId Bigint)
AS
Begin
select DISTINCT GENContacts.Id,GENContacts.Image,GENListValues.Name as Lang_Name,FORMAT(GENContacts.DateCreated,'dd/MM/yyyy') as DateCreatedString,Position
     
	,GENContacts.Name,GENContacts.DefaultPhone,GENContacts.DefaultEmail,GENClassroom_GENContact.StudentStatus as StudentStatusValue,GENContacts.IDNumber ,

	(CASE
    WHEN GENClassroom_GENContact.StudentStatus =1 THEN 'Regular'
    WHEN GENClassroom_GENContact.StudentStatus =2 THEN 'Ban'
   WHEN GENClassroom_GENContact.StudentStatus =3 THEN 'Stopped'
   WHEN GENClassroom_GENContact.StudentStatus =4 THEN 'Dropped'
    ELSE ''
END)as StudentStatus,GENClassroom_GENContact.IsConfirmed,

	(CASE
    WHEN GENClassroom_GENContact.PaymentTypeId = 0 THEN 'Paid'
    WHEN GENClassroom_GENContact.PaymentTypeId = 1 THEN 'NotPaid'
   WHEN GENClassroom_GENContact.PaymentTypeId = 2 THEN 'Returned'
    ELSE ''
END)as PaymentType,GENClassroom_GENContact.PaymentTypeId,

	(CASE
    WHEN GENClassroom_GENContact.BookingTypeId = 0 THEN 'Requested'
    WHEN GENClassroom_GENContact.BookingTypeId = 1 THEN 'Confirmed'
   WHEN GENClassroom_GENContact.BookingTypeId = 2 THEN 'Rejected'
   WHEN GENClassroom_GENContact.BookingTypeId = 3 THEN 'Blocked'
   WHEN GENClassroom_GENContact.BookingTypeId = 4 THEN 'Canceled'
   WHEN GENClassroom_GENContact.BookingTypeId = 5 THEN 'Waiting'
   WHEN GENClassroom_GENContact.BookingTypeId = 6 THEN 'Added'
    ELSE ''
END)as BookingType,GENClassroom_GENContact.BookingTypeId,GENClassroom_GENContact.Id as ClassRoomContactId,
--(select count(distinct ClassroomId) from GENClassroom_GENContact VCRContact  inner join 
--GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 
--GENTypes ON GENClassrooms.CourseId=GENTypes.Id
--where ClassroomId <> @ClassroomId and VCRContact.StudentId = GENClassroom_GENContact.StudentId and VCRContact.BookingTypeId =1 and 
--dbo.AttendanceCall(GENClassroom_GENContact.StudentId,GENClassrooms.Id) >= GENClassrooms.Int4
--) as VCRCount
GENClassrooms.Name AS VcrName,FORMAT(GENClassrooms.FromDateTime,'dd/MM/yyyy') AS VcrFromDate,FORMAT(GENClassrooms.ToDateTime,'dd/MM/yyyy') AS VcrToDate,
GENContacts.CompanyAddressString,vcrDest.Name AS VcrDestnationName,StudentDest.Name AS StudentDestnationName
from GENClassroom_GENContact left join 
   GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id
	left JOIN GENContacts ON GENClassroom_GENContact.StudentId = GENContacts.Id
	left JOIN GENListValues ON GENContacts.LanguageId = GENListValues.Id
	Left join GENCompanies vcrDest ON GENClassrooms.DestinationsId=vcrDest.Id
	Left join GENCompanies StudentDest ON GENContacts.CompanyId=StudentDest.Id
	 WHERE GENClassroom_GENContact.ClassroomId = @ClassroomId

	 group by GENContacts.Id,GENContacts.Image,GENListValues.Name,GENContacts.DateCreated,Position
     
	,GENContacts.Name,GENContacts.DefaultPhone,GENContacts.DefaultEmail,GENClassroom_GENContact.StudentStatus ,GENContacts.IDNumber ,GENClassroom_GENContact.IsConfirmed,
	GENClassroom_GENContact.PaymentTypeId,GENClassroom_GENContact.BookingTypeId,GENClassroom_GENContact.Id,GENClassrooms.Name,GENClassrooms.FromDateTime,
	GENClassrooms.ToDateTime,GENContacts.CompanyAddressString,vcrDest.Name,StudentDest.Name
 END
GO
/****** Object:  StoredProcedure [dbo].[SP_SearchAllChatMessages]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
