CREATE PROCEDURE [dbo].[SP_SearchAllChatMessages] @PopId BIGINT = NULL, @EntityId BIGINT = NULL, 
@SenderId NVARCHAR(MAX) = NULL, @ReceiverId NVARCHAR(MAX) = NULL,@FromDate DATETIME = NULL, @ToDate DATETIME = NULL,
@Message NVARCHAR(MAX) = NULL, @HasFileAttach BIT = NULL,@HasImgAttach BIT = NULL,@HasAudioAttach BIT = NULL,@HasVideoAttach BIT = NULL,
@HasAttach BIT = NULL
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT GENChatMessages.*, gi.Id AS ImageId, gi.AzureUri AS AzureUri, gi.Name As ImageName, 
	gf.AzureUri AS FileAzureUri, gf.FileName As FileName,gf.Id AS FileId,
	ReceiverEmployee.Name AS ReceiverName, ReceiverEmployee.Image AS ReceiverImage,
	SenderEmployee.Name AS SenderName, SenderEmployee.Image AS SenderImage,
	(SELECT TOP(1) CM.UserSenderId FROM GENChatMessages CM WHERE 
	((CM.UserSenderId = GENChatMessages.UserSenderId AND CM.UserReceiverId = GENChatMessages.UserReceiverId) 
	OR (CM.UserSenderId = GENChatMessages.UserReceiverId AND CM.UserReceiverId = GENChatMessages.UserSenderId)) AND
	(CM.ChatEntityPoPId = @PopId OR @PopId IS NULL) AND 
	(CM.ChatEntityId = @EntityId OR @EntityId IS NULL) AND 
	(CM.[UserSenderId] = @SenderId OR @SenderId IS NULL) AND 
	(CM.[UserReceiverId] = @ReceiverId OR @ReceiverId IS NULL) AND 
	(CM.[MessageTime] >=  @FromDate OR @FromDate IS NULL) AND 
	(CM.[MessageTime] <=  @ToDate OR @ToDate IS NULL) AND 
	(CM.MessageText like '%'+@Message+'%' OR @Message IS NULL) ORDER BY CM.Id) AS MainSenderId
	FROM GENChatMessages 
	INNER JOIN GENEmployees ReceiverEmployee on GENChatMessages.UserReceiverId = ReceiverEmployee.UserId
	INNER JOIN GENEmployees SenderEmployee on GENChatMessages.UserSenderId = SenderEmployee.UserId
	LEFT JOIN GENImages gi ON gi.BaseEntityId=184 and gi.EntityId=GENChatMessages.id
	LEFT JOIN GENFiles gf ON gf.BaseEntityId=184 and gf.EntityId=GENChatMessages.id
	LEFT JOIN GENAudios ga ON ga.BaseEntityId=184 and ga.EntityId=GENChatMessages.id
	LEFT JOIN GENVideos gv ON gv.BaseEntityId=184 and gv.EntityId=GENChatMessages.id
	WHERE (ChatEntityPoPId = @PopId OR @PopId IS NULL) AND 
	(ChatEntityId = @EntityId OR @EntityId IS NULL) AND 
	([UserSenderId] = @SenderId OR @SenderId IS NULL) AND 
	([UserReceiverId] = @ReceiverId OR @ReceiverId IS NULL) AND 
	([MessageTime] >=  @FromDate OR @FromDate IS NULL) AND 
	([MessageTime] <=  @ToDate OR @ToDate IS NULL) AND 
	(MessageText like '%'+@Message+'%' OR @Message IS NULL) AND
	((gf.Id IS NOT NULL AND @HasFileAttach = 1) OR @HasFileAttach = 0 OR @HasFileAttach IS NULL) AND
	((gi.Id IS NOT NULL AND @HasImgAttach = 1) OR @HasImgAttach = 0 OR @HasImgAttach IS NULL) AND
	((ga.Id IS NOT NULL AND @HasAudioAttach = 1) OR @HasAudioAttach = 0 OR @HasAudioAttach IS NULL) AND
	((gv.Id IS NOT NULL AND @HasVideoAttach = 1) OR @HasVideoAttach = 0 OR @HasVideoAttach IS NULL) AND
	(((gf.Id IS NOT NULL OR gi.Id IS NOT NULL OR ga.Id IS NOT NULL OR gv.Id IS NOT NULL) AND @HasAttach = 1) OR @HasAttach = 0 OR @HasAttach IS NULL)


	UNION

	SELECT DISTINCT GENChatMessages.*, gi.Id AS ImageId, gi.AzureUri AS AzureUri, gi.Name As ImageName, 
	gf.AzureUri AS FileAzureUri, gf.FileName As FileName,gf.Id AS FileId,
	ReceiverEmployee.Name AS ReceiverName, ReceiverEmployee.Image AS ReceiverImage,
	SenderEmployee.Name AS SenderName, SenderEmployee.Image AS SenderImage,
	(SELECT TOP(1) CM.UserSenderId FROM GENChatMessages CM WHERE 
	((CM.UserSenderId = GENChatMessages.UserSenderId AND CM.UserReceiverId = GENChatMessages.UserReceiverId) 
	OR (CM.UserSenderId = GENChatMessages.UserReceiverId AND CM.UserReceiverId = GENChatMessages.UserSenderId)) AND
	(CM.ChatEntityPoPId = @PopId OR @PopId IS NULL) AND 
	(CM.ChatEntityId = @EntityId OR @EntityId IS NULL) AND 
	(CM.[UserSenderId] = @SenderId OR @SenderId IS NULL) AND 
	(CM.[UserReceiverId] = @ReceiverId OR @ReceiverId IS NULL) AND 
	(CM.[MessageTime] >=  @FromDate OR @FromDate IS NULL) AND 
	(CM.[MessageTime] <=  @ToDate OR @ToDate IS NULL) AND 
	(CM.MessageText like '%'+@Message+'%' OR @Message IS NULL) ORDER BY CM.Id) AS MainSenderId
	FROM GENChatMessages 
	INNER JOIN GENContacts ReceiverEmployee on GENChatMessages.UserReceiverId = ReceiverEmployee.UserId
	INNER JOIN GENContacts SenderEmployee on GENChatMessages.UserSenderId = SenderEmployee.UserId
	LEFT JOIN GENImages gi ON gi.BaseEntityId=184 and gi.EntityId=GENChatMessages.id
	LEFT JOIN GENFiles gf ON gf.BaseEntityId=184 and gf.EntityId=GENChatMessages.id
	LEFT JOIN GENAudios ga ON ga.BaseEntityId=184 and ga.EntityId=GENChatMessages.id
	LEFT JOIN GENVideos gv ON gv.BaseEntityId=184 and gv.EntityId=GENChatMessages.id
	WHERE (ChatEntityPoPId = @PopId OR @PopId IS NULL) AND 
	(ChatEntityId = @EntityId OR @EntityId IS NULL) AND 
	([UserSenderId] = @SenderId OR @SenderId IS NULL) AND 
	([UserReceiverId] = @ReceiverId OR @ReceiverId IS NULL) AND 
	([MessageTime] >=  @FromDate OR @FromDate IS NULL) AND 
	([MessageTime] <=  @ToDate OR @ToDate IS NULL) AND 
	(MessageText like '%'+@Message+'%' OR @Message IS NULL) AND
	((gf.Id IS NOT NULL AND @HasFileAttach = 1) OR @HasFileAttach = 0 OR @HasFileAttach IS NULL) AND
	((gi.Id IS NOT NULL AND @HasImgAttach = 1) OR @HasImgAttach = 0 OR @HasImgAttach IS NULL) AND
	((ga.Id IS NOT NULL AND @HasAudioAttach = 1) OR @HasAudioAttach = 0 OR @HasAudioAttach IS NULL) AND
	((gv.Id IS NOT NULL AND @HasVideoAttach = 1) OR @HasVideoAttach = 0 OR @HasVideoAttach IS NULL) AND
	(((gf.Id IS NOT NULL OR gi.Id IS NOT NULL OR ga.Id IS NOT NULL OR gv.Id IS NOT NULL) AND @HasAttach = 1) OR @HasAttach = 0 OR @HasAttach IS NULL)





	ORDER BY ID
END
GO
