CREATE Proc [dbo].[SP_Select_CourseContacts] (@CoursId bigint)
as
SELECT      distinct  dbo.Contact_View.*, dbo.Contacts_Courses.CourseId, dbo.Contacts_Courses.CourseStatus
FROM            dbo.Contacts_Courses LEFT OUTER JOIN
                         dbo.Contact_View ON dbo.Contacts_Courses.StudentId = dbo.Contact_View.Id

						 where    NOT EXISTS (SELECT        dbo.GENClassroom_GENContact.StudentId
FROM            dbo.GENClassroom_GENContact LEFT OUTER JOIN
                         dbo.GENClassrooms ON dbo.GENClassroom_GENContact.ClassroomId = dbo.GENClassrooms.Id
WHERE        (dbo.GENClassrooms.CourseId =dbo.Contacts_Courses.CourseId) AND (dbo.GENClassroom_GENContact.StudentId = dbo.Contact_View.Id)) and dbo.Contacts_Courses.CourseId = @CoursId and dbo.Contacts_Courses.CourseStatus =0
GO
