CREATE Proc [dbo].[SP_Select_TypeCategory_ById]-- 4,'ar'
(@Id bigint,@langCode  NVARCHAR(MAX))
	 AS
	 Begin
	 
	 
	 SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,dbo.fn_TypeCategories_Translate_ByKeyandId(H1.Id,'Name',@langCode) AS Name,IsActive,IsPublish,H1.ParentId,H1.ID as GrandParent
	FROM GENTypeCategories H1
    WHERE H1.ParentId = @Id and IsDeleted = 0 and IsActive = 1 and IsPublish = 1

	end
GO
