/****** Object:  StoredProcedure [dbo].[SP_Select_WikiCategoryId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_Select_WikiCategoryId]--SP_Select_WikiCategoryId 102,'ar'
	@CategoryId bigint,@langCode nvarchar(500)
AS
BEGIN
	SET NOCOUNT ON;
SELECT dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as VideoURL, 
   dbo.GENWikis.AudioURL, dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'RichContent',@langCode) as RichContent,
     dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'TargetUrl',@langCode) as TargetUrl,
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Name',@langCode) as Name, 
                         dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description',@langCode) as Description,
                         dbo.GENWikis.DisplayOrdering,
						 dbo.GENWikis.LastUpdatedById, dbo.GENWikis.CheckoutBy,dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String1',@langCode)   as String,
						FORMAT(dbo.GENWikis.Date1, 'dd/MM/yyyy hh:mm tt') AS Date1String,	FORMAT(dbo.GENWikis.Date1, 'yyyy') AS [Year],
                         (CASE WHEN (dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Image',@langCode) IS NULL OR dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Image',@langCode) = '') THEN '/assets/images/Default.png' ELSE dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Image',@langCode) END) AS Image,
						 dbo.GENWikis.IsActive,
						 dbo.GENWikis.IsPublish
						  ,GENWikis.ValueId1 as CatId,GENWikis.WikiCategory_Name as CatName,
		(select Top 1 AzureUri from GENFiles left join GENListValues on GENListValues.Id = GENFiles.LanguageId where GENFiles.BaseEntityId = 6 and  GENFiles.EntityId = dbo.GENWikis.Id and (GENListValues.ShortCode = isnull(@langCode,'ar') or (GENFiles.LanguageId is null and GENFiles.IsDefault = 1)) ) as TapFileURL,
		(select Top 1 AzureUri from GENVideos left join GENListValues on GENListValues.Id = GENVideos.LanguageId where GENVideos.BaseEntityId = 6 and  GENVideos.EntityId = dbo.GENWikis.Id and (GENListValues.ShortCode = isnull(@langCode,'ar') or (GENVideos.LanguageId is null and GENVideos.IsDefault = 1))) as TapVideoURL
FROM            dbo.GENWikis
WHERE        (dbo.GENWikis.WikiCategoryId = @CategoryId) AND (dbo.GENWikis.IsPublish = 1) AND (dbo.GENWikis.IsActive = 1)  AND (dbo.GENWikis.IsDeleted = 0) 
AND((dbo.fn_Wiki_Translate_ByKeyandId_If_LangIsEnOrFr(dbo.GENWikis.Id,'Name',@langCode) IS NOT NULL 
and dbo.fn_Wiki_Translate_ByKeyandId_If_LangIsEnOrFr(dbo.GENWikis.Id,'Name',@langCode) not in ('')) or (@langCode is null or @langCode = 'ar'))
ORDER BY dbo.GENWikis.Date1 desc,dbo.GENWikis.DisplayOrdering asc
end
GO
