CREATE PROCEDURE [dbo].[SP_Select_Wikis_ById] --20991,'ar'
	-- Add the parameters for the stored procedure here
	@WikiId bigint,@langCode nvarchar(500)
AS
BEGIN
SET NOCOUNT ON;
SELECT dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as VideoURL, 
   dbo.GENWikis.AudioURL, dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'RichContent',@langCode) as RichContent,
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'TargetUrl',@langCode) as TargetUrl,
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Name',@langCode) as Name, 
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description',@langCode) as Description,
   dbo.GENWikis.DisplayOrdering,
   FORMAT(dbo.GENWikis.Date1, 'dd/MM/yyyy hh:mm tt') AS Date1String,
   (CASE WHEN (dbo.GENWikis.Image IS NULL OR dbo.GENWikis.Image = '') THEN '/assets/images/Default.png' ELSE dbo.fn_Wiki_Translate_ByKeyandId(dbo.GENWikis.Id,'Image',@langCode) END) AS Image,
   dbo.GENWikis.IsActive,
   dbo.GENWikis.IsPublish,
			(select Top 1 AzureUri from GENFiles left join GENListValues on GENListValues.Id = GENFiles.LanguageId where GENFiles.BaseEntityId = 6 and  GENFiles.EntityId = dbo.GENWikis.Id and (GENListValues.ShortCode = isnull(@langCode,'ar') or (GENFiles.LanguageId is null and GENFiles.IsDefault = 1)) ) as TapFileURL,
		(select Top 1 AzureUri from GENVideos left join GENListValues on GENListValues.Id = GENVideos.LanguageId where GENVideos.BaseEntityId = 6 and  GENVideos.EntityId = dbo.GENWikis.Id and (GENListValues.ShortCode = isnull(@langCode,'ar') or (GENVideos.LanguageId is null and GENVideos.IsDefault = 1))) as TapVideoURL
FROM dbo.GENWikis        
WHERE (dbo.GENWikis.Id = @WikiId) 
end
GO
