CREATE PROCEDURE [dbo].[SP_Select_Wikis_ByValueId1andWikicatId] 
	-- Add the parameters for the stored procedure here
	@ValueId1 bigint,@WikiCategoryId bigint,@langCode nvarchar(500)
AS
BEGIN
SELECT           dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as VideoURL, 
   dbo.GENWikis.AudioURL, dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'RichContent',@langCode) as RichContent,
   dbo.GENWikis.TargetUrl,
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Name',@langCode) as Name, 
                         dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description',@langCode) as Description,
                         dbo.GENWikis.DisplayOrdering,
						FORMAT(dbo.GENWikis.Date1, 'dd/MM/yyyy hh:mm tt') AS Date1String,
                         (CASE WHEN (dbo.GENWikis.Image IS NULL OR dbo.GENWikis.Image = '') THEN '/assets/images/Default.png' ELSE dbo.GENWikis.Image END) AS Image
						 ,GENWikis.ValueId1 as CatId,GENWikis.WikiCategory_Name as CatName
						
FROM            dbo.GENWikis      

where ValueId1=@ValueId1 and WikiCategoryId=@WikiCategoryId AND (dbo.GENWikis.IsPublish = 1) AND (dbo.GENWikis.IsActive = 1) AND (dbo.GENWikis.IsDeleted = 0) 
order by Date1 desc, DisplayOrdering asc
