/****** Object:  StoredProcedure [dbo].[SP_SelectActivityDataById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectActivityDataById] (@Id Bigint, @BaseEntityId bigint)
as
select * from AllActivitiesWithDetails
where Id = @Id

DECLARE @CompanyId BIGINT = NULL
select TOP(1) @CompanyId = [dbo].[AllActivitiesWithDetails].EntityId from [dbo].[AllActivitiesWithDetails] 
LEFT JOIN BaseEntities ON [dbo].[AllActivitiesWithDetails].BaseEntityId = BaseEntities.Id AND BaseEntities.Name = 'GENCompany'
where [AllActivitiesWithDetails].Id = @Id 

DECLARE @ContactId BIGINT = NULL
select TOP(1) * from Company_View_Update where Id = @CompanyId
select @ContactId = ContactId from Company_View_Update where Id = @CompanyId

if(@ContactId IS NOT NULL)
BEGIN
select TOP(1) * from Contact_View where Id = @ContactId
END
ELSE 
BEGIN
select TOP(1) @ContactId = [dbo].[AllActivitiesWithDetails].MainContactId from [dbo].[AllActivitiesWithDetails] where Id = @Id
select TOP(1) * from Contact_View where Id = @ContactId
END


SELECT GENImages.*, GENImages.AzureUri AS Image FROM GENImages WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id

SELECT GENGalleryAlbumImages.*, GENGalleryAlbumImages.AzureUri AS Image, GENGalleryAlbums.Name AS GalleryAlbumName FROM GENGalleryAlbumImages
LEFT JOIN GENGalleryAlbums ON GENGalleryAlbumImages.GalleryAlbumId = GENGalleryAlbums.Id
 WHERE GENGalleryAlbumImages.BaseEntityId = @BaseEntityId AND GENGalleryAlbumImages.EntityId = @Id

SELECT GENGalleryAlbums.* FROM GENGalleryAlbums WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id



SELECT GENFiles.*,GENListValues.Name AS LanguageName, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt 
FROM GENFiles
LEFT JOIN GENListValues ON GENFiles.LanguageId = GENListValues.Id
 WHERE GENFiles.BaseEntityId = @BaseEntityId AND GENFiles.EntityId = @Id

SELECT GENAudios.* FROM GENAudios WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id

SELECT GENVideos.* FROM GENVideos WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id

SELECT GENLinks.* FROM GENLinks WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id

SELECT [dbo].[GENEntity_Tag].*, GENTags.Name AS TagName FROM [dbo].[GENEntity_Tag]
LEFT JOIN GENTags ON [dbo].[GENEntity_Tag].TagId = GENTags.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id

SELECT [dbo].[GENEntity_GENWiki].*, GENWikis.Name AS Name FROM [dbo].[GENEntity_GENWiki] 
LEFT JOIN GENWikis ON [dbo].[GENEntity_GENWiki].WikiId = GENWikis.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id

SELECT EmployeeEscalations.*, GENEmployees.Name, GENEmployees.Position, GENEmployees.Image FROM EmployeeEscalations
LEFT JOIN GENEmployees ON EmployeeEscalations.EmployeeId = GENEmployees.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id ORDER BY EmployeeEscalations.DisplayOrder

SELECT GENEntityPricings.*, GENCurrencies.Name AS CurrencyName, GENRegions.Name AS regionName, GENUnits.Name AS UnitName,
 FORMAT(GENEntityPricings.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString, 
 FORMAT(GENEntityPricings.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString FROM GENEntityPricings
LEFT JOIN GENCurrencies ON GENEntityPricings.CurrencyId = GENCurrencies.Id
LEFT JOIN GENRegions ON GENEntityPricings.RegionId = GENRegions.Id
LEFT JOIN GENUnits ON GENEntityPricings.UnitId = GENUnits.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @Id
GO
