CREATE PROCEDURE [dbo].[SP_SelectAllAssessmentVCR] @LangCode NVARCHAR(20),@PollId BIGINT,@ClassId Bigint,@contactId bigint
	-- Add the parameters for the stored procedure here  SP_SelectAllAssessmentVCR 'ar',10109,18
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
    -- Insert statements for procedure here
	SELECT DISTINCT 
                         dbo.GENPolls.Id AS QuestionId, GENPollCategories.Id AS ExamId, GENPollCategories.Name AS ExamName, dbo.GENPolls.Question, dbo.GENPolls.DisplayOrdering, dbo.GENPolls.QuestionType, 
                         dbo.GENPolls.Weight, dbo.GENPolls.MinAnsNumber, dbo.GENPolls.MaxAnsNumber, dbo.GENPollAnswers.Answer, dbo.GENPollAnswers.IsCorrect, dbo.GENPollAnswers.DisplayOrdering AS AnswerDisplayOrder, 
                         dbo.GENPollAnswers.Id AS AnswerId, dbo.PollCategoryandPolls.QdOrder, dbo.GENPolls.Image AS QuestionImage, dbo.GENVideos.AzureUri AS QuestionVideo, dbo.GENVideos.Id AS QuestionVideoId,
						 dbo.GENPolls.Audio AS QuestionAudio, GENPollAnswers.Image AS AnswerImage
						 ,(case when dbo.[AllPollsHasAnswer](@contactId,@ClassId,@PollId) = 1 
						 and dbo.[AllRatingVCRLecture](@contactId,@ClassId) = 1and dbo.[AllRatingVCRLectureInstructor](@contactId,@ClassId) = 1 THEN cast(1 as bit) else cast(0 as bit) END)  as SurveyAnswered
						 ,dbo.GENPollAnswers.Weight as AnswersWeight
						 ,GENPolls.Bool1 as IsMendatory
FROM      dbo.GENPolls      
LEFT JOIN dbo.GENPollAnswers  ON dbo.GENPollAnswers.PollId = dbo.GENPolls.Id 
LEFT JOIN dbo.GENVideos ON dbo.GENVideos.EntityId = dbo.GENPolls.Id AND dbo.GENVideos.BaseEntityId = 83
LEFT JOIN dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId
LEFT JOIN dbo.GENExam_GENClassroom ON dbo.PollCategoryandPolls.PollCategoryId = dbo.GENExam_GENClassroom.ExamId
LEFT JOIN dbo.GENClassrooms ON dbo.GENExam_GENClassroom.ClassroomId = dbo.GENClassrooms.Id
LEFT JOIN dbo.GENPollCategories ON dbo.GENPollCategories.Id = dbo.PollCategoryandPolls.PollCategoryId
LEFT JOIN GENListValues ON dbo.GENPolls.LanguageId = GENListValues.Id
left join GENExamAnswerHeaders on GENExamAnswerHeaders.StudentId = @contactId and GENExamAnswerHeaders.ExamId = GENPollCategories.Id and GENExamAnswerHeaders.ClassroomId = @ClassId
left join GENExamAnswerDetails on GENExamAnswerDetails.PollId = dbo.GENPolls.Id and GENExamAnswerDetails.ExamAnswerHeaderId = GENExamAnswerHeaders.Id
left join GENRatings on GENRatings.EntityId = dbo.GENClassrooms.id and GENRatings.BaseEntityId = 176 and GENRatings.UserId = (select UserId from GENContacts where GENContacts.ID = @contactId)
	WHERE  dbo.GENPolls.IsActive=1 AND dbo.GENPollCategories.ExamType = 12 AND (GENListValues.ShortCode= @LangCode OR @LangCode IS NULL OR @LangCode = 'ar')
	AND dbo.GENPollCategories.IsActive = 1  AND dbo.GENPollCategories.IsPosted = 1 AND GENPollCategories.Id = @PollId AND GENClassrooms.Id =@ClassId

						 ORDER BY dbo.PollCategoryandPolls.QdOrder 
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectAllAssessmentVCR_AcaDegree]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
