CREATE Proc [dbo].[SP_SelectAllCourseCategories]
AS
Begin
	 SELECT H1.Id as Id,
    (CASE WHEN  CAST(H1.ParentId AS NVARCHAR(MAX)) is null THEN '#' ELSE CAST(H1.ParentId AS NVARCHAR(MAX)) END) AS Parent
    ,H1.Name,IsActive,IsPublish,H1.ParentId,H1.ID as GrandParent
