CREATE proc [dbo].[SP_SelectAllCoursesByIsActive] @IsActive bit
as
begin
select GENTypes.Id AS CourseId,GENTypes.Name AS CourseName,GENTypes.Code AS CourseCode ,GENTypeCategories.Name as FieldName ,
(CASE WHEN GENTypes.IsActive = 1 THEN N'نشط' ELSE N'غير نشط' END) AS IsActive
from GENTypes 
left join GENTypeCategories ON GENTypes.TypeCategoryId=GENTypeCategories.Id
where (GENTypes.IsActive=@IsActive OR @IsActive is null) and GENTypes.IsDeleted=0
end;
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectAllCoursessTrack_ByListValueId1]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_SelectAllCoursessTrack_ByListValueId1] (@ListValueId1 bigint)
as
begin
select  Distinct GENTypes.Id,GENTypes.Code As CourseCode, GENTypes.Name As CourseName,
(CASE WHEN GENTypes.Int1 IS NOT NULL AND GENTypes.Int2 IS NOT NULL THEN
CAST(GENTypes.Int1 AS nvarchar(MAX)) + ':' +CAST(GENTypes.Int2 AS nvarchar(MAX)) ELSE 
CASE WHEN GENTypes.Int1 IS NOT NULL THEN CAST(GENTypes.Int1 AS nvarchar(MAX)) + ':00' ELSE 
CASE WHEN GENTypes.Int2 IS NOT NULL THEN '00:' +CAST(GENTypes.Int2 AS nvarchar(MAX)) ELSE '' END END END) AS CourseTime,GENTypes.DisplayOrdering,GENTypes.IsActive
,COUNT(GENItems.Id)  AS NumberOfSessions
FROM             GENTypes  left join
                 GENItems ON GENTypes.Id=GENItems.TypeId
where GENTypes.ValueId1=@ListValueId1
GROUP BY  GENTypes.Id,GENTypes.Name,GENTypes.Code,GENTypes.Int2,GENTypes.DisplayOrdering,GENTypes.IsActive,GENTypes.Int1

End
GO
