CREATE PROCEDURE [dbo].[SP_SelectAllNews] @LangCode NVARCHAR(20)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT [Id]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'Name', @LangCode) AS [Name]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'RichContent', @LangCode) AS [RichContent]
      ,(CASE WHEN [Image] IS NULL OR [Image] = '' THEN '/assets/images/Default.png' ELSE [Image] END) AS Image
      ,[IsPublish]
      ,[IsActive]
      ,[Order]
      ,[DisplayDate]
      ,[EndDate]
      ,[SectionsId]
      ,[IsEvent]
      ,[VideoUrl]
      ,[NewsCategoryId]
      ,[Code]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'Description', @LangCode) AS [Description]
      ,[ColorCode]
      ,[IsCheckedOut]
      ,[DateCreated]
      ,[DateUpdated]
      ,[CheckinDate]
      ,[CheckoutDate]
      ,[Timeout]
      ,[DisplayOrdering]
      ,[CreatedById]
      ,[LastUpdatedById]
      ,[CheckoutBy]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'String1', @LangCode) AS [String1]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'String2', @LangCode) AS [String2]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'String3', @LangCode) AS [String3]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'String4', @LangCode) AS [String4]
      ,dbo.fn_News_Translate_ByKeyandId(GENNews.Id, 'String5', @LangCode) AS [String5]
      ,[Int1]
      ,[Int2]
      ,[Int3]
      ,[Int4]
      ,[Int5]
      ,[Long1]
      ,[Long2]
      ,[Long3]
      ,[Long4]
      ,[Long5]
      ,[Float1]
      ,[Float2]
      ,[Float3]
      ,[Float4]
      ,[Float5]
      ,[Decimal1]
      ,[Decimal2]
      ,[Decimal3]
      ,[Decimal4]
      ,[Decimal5]
      ,[Bool1]
