GO
CREATE PROCEDURE [dbo].[SP_SelectAllPollsListByExamTypeId] --6,'en',null
@ExamType int,@LangCode NVARCHAR(20),@StudentId bigint = null
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
    -- Insert statements for procedure here
	SELECT DISTINCT GENPollCategories.* , COUNT(PollCategoryandPolls.Id) AS QuestionsAnswered,
    GENExamAnswerHeaders.TotalQuestionsNumber,
    CASE 
        WHEN GENExamAnswerHeaders.TotalQuestionsNumber = 0 OR GENExamAnswerHeaders.TotalQuestionsNumber IS NULL THEN cast(0 as decimal(18,4))
        ELSE cast(( GENExamAnswerHeaders.TotalQuestionsNumber* 100.0 /COUNT(PollCategoryandPolls.Id)) as decimal(18,4))
    END AS PercentageAnswer
FROM dbo.GENPollCategories 
left join PollCategoryandPolls on PollCategoryandPolls.PollCategoryId = GENPollCategories.Id
LEFT JOIN GENListValues ON dbo.GENPollCategories.LanguageId = GENListValues.Id
left join GENExamAnswerHeaders on GENExamAnswerHeaders.ExamId = GENPollCategories.Id and StudentId = @StudentId
WHERE  dbo.GENPollCategories.ExamType = @ExamType AND (GENListValues.ShortCode= @LangCode OR @LangCode IS NULL OR @LangCode = 'ar')
AND dbo.GENPollCategories.IsActive = 1 AND dbo.GENPollCategories.IsPosted = 1 and ExamPrivacyTypeId = 1
group by dbo.GENPollCategories.[Id],dbo.GENPollCategories.[DisplayOrder],dbo.GENPollCategories.[IsActive],dbo.GENPollCategories.[IsPublish],dbo.GENPollCategories.[Code],dbo.GENPollCategories.[Name]
,dbo.GENPollCategories.[Description],dbo.GENPollCategories.[ColorCode],dbo.GENPollCategories.[IsCheckedOut],dbo.GENPollCategories.[DateCreated],dbo.GENPollCategories.[DateUpdated],dbo.GENPollCategories.[CheckinDate]
,dbo.GENPollCategories.[CheckoutDate],dbo.GENPollCategories.[Timeout],dbo.GENPollCategories.[DisplayOrdering],dbo.GENPollCategories.[CreatedById],dbo.GENPollCategories.[LastUpdatedById]
,dbo.GENPollCategories.[CheckoutBy],dbo.GENPollCategories.[String1],dbo.GENPollCategories.[String2],dbo.GENPollCategories.[String3],dbo.GENPollCategories.[String4],dbo.GENPollCategories.[String5]
,dbo.GENPollCategories.[Int1],dbo.GENPollCategories.[Int2],dbo.GENPollCategories.[Int3],dbo.GENPollCategories.[Int4],dbo.GENPollCategories.[Int5],dbo.GENPollCategories.[Long1],dbo.GENPollCategories.[Long2]
,dbo.GENPollCategories.[Long3],dbo.GENPollCategories.[Long4],dbo.GENPollCategories.[Long5],dbo.GENPollCategories.[Float1],dbo.GENPollCategories.[Float2],dbo.GENPollCategories.[Float3],dbo.GENPollCategories.[Float4]
,dbo.GENPollCategories.[Float5],dbo.GENPollCategories.[Decimal1],dbo.GENPollCategories.[Decimal2],dbo.GENPollCategories.[Decimal3],dbo.GENPollCategories.[Decimal4],dbo.GENPollCategories.[Decimal5]
,dbo.GENPollCategories.[Bool1],dbo.GENPollCategories.[Bool2],dbo.GENPollCategories.[Bool3],dbo.GENPollCategories.[Bool4],dbo.GENPollCategories.[Bool5],dbo.GENPollCategories.[Date1],dbo.GENPollCategories.[Date2]
,dbo.GENPollCategories.[Date3],dbo.GENPollCategories.[Date4],dbo.GENPollCategories.[Date5],dbo.GENPollCategories.[ValueId1],dbo.GENPollCategories.[ValueId2],dbo.GENPollCategories.[ValueId3]
,dbo.GENPollCategories.[ValueId4],dbo.GENPollCategories.[ValueId5],dbo.GENPollCategories.[IconId],dbo.GENPollCategories.[ExpectedCheckoutDate],dbo.GENPollCategories.[Image],dbo.GENPollCategories.[Video]
,dbo.GENPollCategories.[Audio],dbo.GENPollCategories.[File],dbo.GENPollCategories.[Time],dbo.GENPollCategories.[Weight],dbo.GENPollCategories.[ActucalScore],dbo.GENPollCategories.[SuccessScore]
,dbo.GENPollCategories.[LanguageId],dbo.GENPollCategories.[IsPosted],dbo.GENPollCategories.[ExamType],dbo.GENPollCategories.[ExamAutoGeneratorId],dbo.GENPollCategories.[RichContent],dbo.GENPollCategories.[ParentId]
,dbo.GENPollCategories.[QuestionDisplayType],dbo.GENPollCategories.[IsDeleted],dbo.GENPollCategories.[IsShuffled],dbo.GENPollCategories.[IsAgenda],dbo.GENPollCategories.[ProsecutionId]
,dbo.GENPollCategories.[ExamPrivacyTypeId],GENExamAnswerHeaders.TotalQuestionsNumber
ORDER BY dbo.GENPollCategories.DisplayOrdering
END
GO
