CREATE PROC [dbo].[SP_SelectAllPushMSG]
As
Begin

Select PushMSGs.Id,Title,Body,Description,[Type],FORMAT(Date, 'dd/MM/yyyy') AS DateString,FORMAT(DateCreated, 'dd/MM/yyyy') AS DateCreatedString,
FORMAT(DateUpdated, 'dd/MM/yyyy') AS DateUpdatedString,
(CASE WHEN [Type] = 1 THEN N'Email' ELSE 
CASE WHEN [Type] = 2 THEN N'SMS' 
ELSE CASE WHEN [Type] = 3 THEN 
N'Notify' ELSE N'' END END END) AS TypeString,AspNetUsers.Name AS LastUpdatedByName
From PushMSGs left join 
AspNetUsers ON PushMSGs.LastUpdatedById=AspNetUsers.Id


END
GO
