CREATE Proc [dbo].[SP_SelectAttendeesDetailsExam_ByExamId] --SP_SelectAttendeesDetailsExam_ByExamId 10015,'ar'
(@ExamId bigint,@LangCode nvarchar(MAX))
as
begin
select GENContacts .name as StudentName,TotalExamScore,ExamWeight,
dbo.Diff_BetweenDates_HoursAndMin_Lang(GENExamAnswerHeaders.StartDateTime, GENExamAnswerHeaders.EndtDateTime,@LangCode) AS ExamTimeString,
CourseName,FORMAT(StartDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
FORMAT(EndtDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString
FROM             GENExamAnswerHeaders
left join GENContacts on GENContacts.Id = GENExamAnswerHeaders.StudentId
where GENExamAnswerHeaders.ExamId=@ExamId
End
