/****** Object:  StoredProcedure [dbo].[SP_SelectCalculationFields_ByPollId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectCalculationFields_ByPollId] (@PollId bigint)
as
begin
select  Count(GENExamAnswerDetails.PollId) AS CountQuestions
FROM            GENExamAnswerDetails

where GENExamAnswerDetails.PollId=@PollId
				 
select Count(GENExamAnswerDetails.Id) AS CountQuestionAnswers
			FROM            GENExamAnswerDetails
			
where GENExamAnswerDetails.PollId=@PollId and (GENExamAnswerDetails.AnswerName IS NOT NULL or GENExamAnswerDetails.Article IS NOT NULL or  GENExamAnswerDetails.Value IS NOT NULL )

select Count(GENExamAnswerDetails.QuestionCorrectedAnswer) AS CountCorrectAnswer
			FROM            GENExamAnswerDetails
			
where  GENExamAnswerDetails.Score>0   and GENExamAnswerDetails.PollId=@PollId


select Count(GENExamAnswerDetails.Id) AS CountWrongAnswer
			FROM            GENExamAnswerDetails 
			
where GENExamAnswerDetails.IsRevised=1 and  GENExamAnswerDetails.Score=0 and GENExamAnswerDetails.PollId=@PollId


select Count(GENExamAnswerDetails.Id) AS CountLeftAnswer
			FROM            GENExamAnswerDetails 
			
where  GENExamAnswerDetails.Score=0 and  GENExamAnswerDetails.AnswerName Is NULL and GENExamAnswerDetails.Article Is NULL and 
GENExamAnswerDetails.Value=0 and GENExamAnswerDetails.PollId=@PollId


select Count(GENExamAnswerHeaders.StudentId) AS StudentRun from GENExamAnswerHeaders
where  GENExamAnswerHeaders.ExamId IN (Select PollCategoryId From PollCategoryandPolls where PollCategoryandPolls.PollId =@PollId)

select Count(GENExam_GENType.ExamId) AS ExamRunType
from GENExam_GENType where GENExam_GENType.ExamId IN (Select PollCategoryId From PollCategoryandPolls where PollCategoryandPolls.PollId =@PollId)

select Count(GENExam_GENItem.ExamId) AS ExamRunSession
from GENExam_GENItem where GENExam_GENItem.ExamId IN (Select PollCategoryId From PollCategoryandPolls where PollCategoryandPolls.PollId =@PollId)

select Count(GENExam_GENClassroom.ExamId) AS ExamRunClassroom
from GENExam_GENClassroom left join
GENClassrooms ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id
 where GENExam_GENClassroom.ExamId IN (Select PollCategoryId From PollCategoryandPolls where PollCategoryandPolls.PollId =@PollId)  and GENClassrooms.ExamStartTime IS NULL

select Count(GENExamAnswerHeaders.ExamId) AS ExamRunContact
from GENExamAnswerHeaders where GENExamAnswerHeaders.ExamId IN (Select PollCategoryId From PollCategoryandPolls where PollCategoryandPolls.PollId =@PollId) and GENExamAnswerHeaders.StartDateTime IS NULL

End
GO
