/****** Object:  StoredProcedure [dbo].[SP_SelectClassroom_GroupbyCourse]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_SelectClassroom_GroupbyCourse] --SP_SelectClassroom_GroupbyCourse 'ar','87db5527-4a30-4ac4-9756-1692315a8c40'
(@LangCode nvarchar(500),@UserId nvarchar(500))
AS
Begin
Select  dbo.fn_Type_Translate_ByKeyandId(GENClassrooms.CourseId,'Name',@LangCode) AS CourseName,dbo.fn_ClassRoom_Translate_ByKeyandId(GENClassrooms.Id,'Name',@LangCode) AS ClassName,GENClassrooms.Id AS ClassId,GENClassrooms.CourseId,
FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo,GENClassrooms.PaymentCondation,
FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate,
 (CASE WHEN  GENTypes.CourseType = 0 THEN N'داخل القاعة' ELSE  CASE WHEN  GENTypes.CourseType = 1 THEN N'دراسة ذاتية' ELSE CASE WHEN  GENTypes.CourseType = 2 THEN N'اون لاين' ELSE N'' END END END) AS CourseType,
(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift,
GENListValues.Name AS LangName,GENClassrooms.LanguageId,GENRatings.IsFavourite,GENTypes.Description AS CourseDesc,GENClassrooms.DateUpdated
,DATEDIFF(DAY,cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date)) + 1 as NoOfDays,GENEntityPricings.netprice AS CoursePrice,
GENCurrencies.Name As CurrencyName ,(cast(GENEntityPricings.netprice as nvarchar(max)) +' '+  GENCurrencies.Name) AS DefaultCoursePrice
From GENClassrooms Inner Join
GENTypes ON GENClassrooms.CourseId=GENTypes.Id Inner join
GENListValues ON GENClassrooms.LanguageId =GENListValues.Id left  join 
GENRatings ON GENTypes.Id=GENRatings.EntityId and GENRatings.BaseEntityId=28 and GENRatings.UserId=@UserId left join 
GENEntityPricings on GENTypes.Id=GENEntityPricings.EntityId and GENEntityPricings.BaseEntityId=28 and GENEntityPricings.isdefault=1 left join 
GENCurrencies ON GENEntityPricings.CurrencyId=GENCurrencies.Id left join 
GENContacts ON GENContacts.UserId=@UserId
where (GENClassrooms.IsActive=1 and GENClassrooms.IsPublish=1 and GENClassrooms.ToDateTime > GETDATE())
and GENClassrooms.IsDeleted=0 and GENClassrooms.ProsecutionId=0 and 
(
--GENClassrooms.DestinationsId = GENContacts.OrganizationId 
--or GENClassrooms.DestinationsId = GENContacts.CompanyId or
 GENClassrooms.DestinationsId is null) 
and (GENClassrooms.IsPrivate =0 or  GENClassrooms.IsPrivate is null) 
and (GENClassrooms.ClassRoomStatus <> 1  or GENClassrooms.ClassRoomStatus is null)
order by cast(GENClassrooms.FromDateTime as date),cast(GENClassrooms.ToDateTime as date) 
End
GO
