CREATE Proc [dbo].[SP_SelectClassroomCourse_ByCourseId] (@CourseId bigint)
as
begin
select GENClassrooms.Id,GENClassrooms.Name AS ClassroomName,GENClassrooms.Code AS ClassroomCode, (CASE WHEN ClassRoomStatus = 0 THEN 'Started' ELSE CASE WHEN ClassRoomStatus = 1 THEN 'Dropped' ELSE CASE WHEN ClassRoomStatus = 2 THEN 'Done' ELSE '' END END END) AS ClassRoomStatusString ,FromDateTime,FORMAT(FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString,COUNT(GENClassroom_GENContact.StudentId)  AS StudentCount, 
ToDateTime, FORMAT(ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString
