GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_SelectClassroomExam_ByExamId] (@ExamId bigint)
as
begin
select GENClassrooms.Id,GENClassrooms.Name as ClassroomName,GENClassrooms.Code AS ClassroomCode, (CASE WHEN GENClassrooms.ClassRoomStatus = 0 THEN 'Started' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 1 THEN 'Dropped' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 2 THEN 'Done' ELSE '' END END END) AS ClassRoomStatusString ,GENClassrooms.FromDateTime,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString,COUNT(GENClassroom_GENContact.StudentId)  AS StudentCount, 
GENClassrooms.ToDateTime, FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString
FROM            GENClassrooms LEFT JOIN
                 GENExam_GENClassroom ON GENClassrooms.Id=GENExam_GENClassroom.ClassroomId left join
				 GENPollCategories ON GENExam_GENClassroom.ExamId=GENPollCategories.Id Left Join
				  GENClassroom_GENContact ON GENClassrooms.Id = GENClassroom_GENContact.ClassroomId
				
				

where GENClassrooms.ExamId=@ExamId
GROUP BY  GENClassrooms.Id,GENClassrooms.Name,GENClassrooms.Code,GENClassrooms.ClassRoomStatus,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime

End
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectClassroomExams_ByCourseId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_SelectClassroomExams_ByCourseId] (@CourseId bigint,@langCode nvarchar(500) )
as
begin
select Distinct GENPollCategories.Name AS ExamName,GENPollCategories.Id As ExamId
,GENPollCategories.Id As Id2,dbo.FN_GetExamType(GENPollCategories.ExamType,@langCode) AS ExamTypeName
FROM            GENExam_GENType LEFT JOIN
                GENTypes on GENExam_GENType.CourseId = GENTypes.Id left join 
				GENPollCategories ON GENExam_GENType.ExamId = GENPollCategories.Id
where GENExam_GENType.CourseId=@CourseId

Union

select Distinct GENPollCategories.Name AS ExamName,GENPollCategories.Id As ExamId,GENPollCategories.Id As Id2,dbo.FN_GetExamType(GENPollCategories.ExamType,@langCode) AS ExamTypeName
FROM            GENExam_GENItem  LEFT JOIN
				GENItems ON GENExam_GENItem.SessionId=GENItems.Id left join
				GENPollCategories ON GENExam_GENItem.ExamId = GENPollCategories.Id left join
				GENTypes ON GENItems.TypeId=GENTypes.Id
where GENTypes.Id=@CourseId
End

GO
/****** Object:  StoredProcedure [dbo].[SP_SelectClassroomFav_GroupbyCourse]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_SelectClassroomFav_GroupbyCourse] (  @LangCode nvarchar(500),@UserId nvarchar(500))
AS
Begin
Select  dbo.fn_Type_Translate_ByKeyandId(GENClassrooms.CourseId,'Name',@LangCode) AS CourseName,dbo.fn_ClassRoom_Translate_ByKeyandId(GENClassrooms.Id,'Name',@LangCode) AS ClassName,GENClassrooms.Id AS ClassId,GENClassrooms.CourseId,
FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS DateFrom,FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS DateTo,GENClassrooms.PaymentCondation,
FORMAT(GENClassrooms.FromDateTime, 'HH:mm') AS TimeFrom,FORMAT(GENClassrooms.ToDateTime, 'HH:mm') AS TimeTo,GENClassrooms.Date1 AS RegisterStartDate,GENClassrooms.Date2 AS RegisterEndDate,
 (CASE WHEN  GENTypes.CourseType = 0 THEN N'داخل القاعة' ELSE  CASE WHEN  GENTypes.CourseType = 1 THEN N'دراسة ذاتية' ELSE CASE WHEN  GENTypes.CourseType = 2 THEN N'اون لاين' ELSE N'' END END END) AS CourseType,
(CASE WHEN  GENClassrooms.ClassRoomShift = 0 THEN N'صباحي' ELSE  CASE WHEN   GENClassrooms.ClassRoomShift = 1 THEN N'مسائي'  ELSE N'' END END) AS ClassShift,
GENListValues.Name AS LangName,GENClassrooms.LanguageId,GENRatings.IsFavourite,
GENEntityPricings.netprice AS CoursePrice,
GENCurrencies.Name As CurrencyName ,(cast(GENEntityPricings.netprice as nvarchar(max)) +' '+  GENCurrencies.Name) AS DefaultCoursePrice
From GENRatings Inner Join
GENTypes ON GENRatings.EntityId=GENTypes.Id and GENRatings.BaseEntityId=28 Inner join
GENClassrooms ON GENTypes.id=GENClassrooms.CourseId left join 
GENListValues ON GENClassrooms.LanguageId =GENListValues.Id  left join 
GENEntityPricings on GENTypes.Id=GENEntityPricings.EntityId and GENEntityPricings.BaseEntityId=28 and GENEntityPricings.isdefault=1 left join 
GENCurrencies ON GENEntityPricings.CurrencyId=GENCurrencies.Id
where (GENClassrooms.IsActive=1 and GENClassrooms.IsPublish=1 and GENClassrooms.ToDateTime > GETDATE() and GENRatings.IsFavourite=1 and GENRatings.UserId=@UserId)
order by GENClassrooms.Id
End
GO
