where (GENClassrooms.IsActive=1 and GENClassrooms.IsPublish=1 and GENClassrooms.ToDateTime > GETDATE() and GENRatings.IsFavourite=1 and GENRatings.UserId=@UserId)
and  (GENClassrooms.ProsecutionId <> 0 and GENClassrooms.ProsecutionId <> 1)
order by GENClassrooms.Id
End
