/****** Object:  StoredProcedure [dbo].[SP_SelectClassroomInstructors]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 29/07/2020
-- Description:	Getting all instructors for current or next classrooms according to course
-- =============================================
CREATE PROCEDURE [dbo].[SP_SelectClassroomInstructors]
	-- Add the parameters for the stored procedure here
	@id BIGINT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENEmployees.[Id] ,[InteractiveMeetingURL] ,[InstructorInstructions] ,[ExamStartTime] ,[ExamEndTime]
      ,[FromDateTime] ,[ToDateTime] ,[InteractiveMeetingDateTime] ,[DisplayOrder] ,[CourseId] ,[InstructorId],GENEmployees.[Name]
      ,GENEmployees.[Position] ,GENEmployees.[Description] AS InstructorDescription ,GENClassrooms.[Description] ,GENClassrooms.[DisplayOrdering] ,GENClassrooms.[IsActive]
      ,GENClassrooms.[IsPublish] ,GENClassrooms.[ExamId] ,GENClassrooms.[ClassRoomStatus] ,GENClassrooms.[LanguageId] ,GENClassrooms.[IsPosted],GENEmployees.[Image]
  FROM GENEmployees
  LEFT JOIN GENClassrooms ON GENEmployees.Id =[dbo].[GENClassrooms].InstructorId
  WHERE GENClassrooms.CourseId = @id AND ((FromDateTime <= GETDATE() AND ToDateTime >= GETDATE()) OR (FromDateTime >= GETDATE())) AND GENClassrooms.IsActive = 1
  ORDER By FromDateTime
END
GO
