	 AspNetUsers.Name as UserName,
	GENComments.IsActive,
	GENComments.IsPublish,
	FORMAT(GENComments.CreatedDate,'dd/MM/yyyy')as CreatedDateString,
	FORMAT(GENComments.CreatedDate,'dd/MM/yyyy')as UpdatedDateString,
	AspNetUsers.Name as UserName,
	GENBlogs.Text as BlogName
	
	from GENComments left join 

	AspNetUsers on GENComments.CreatedById=AspNetUsers.Id left join 
	GENBlogs on GENComments.BlogId=GENBlogs.Id left join 
	 EmogyUserReplies on GENComments.Id=EmogyUserReplies.CommentId
	where GENComments.Id=@Id 
		group by GENComments.Id, GENComments.BlogId, GENComments.CommentText, GENComments.Video, GENComments.Url,
	 GENComments.Image, GENComments.CreatedDate, GENComments.UpdatedDate, GENComments.CreatedById, GENComments.LastUpdatedById,
	  GENBlogs.Text,GENComments.ParentId,AspNetUsers.Name,GENComments.IsActive,GENComments.IsPublish

END
GO
