Where CRMSentEmails.EmailEntityId= @CompanyId and CRMSentEmails.EmailEntityPoPId=@POPId


Select CRMSentEmails.[From], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @CompanyId and CRMSentEmails.EmailEntityPoPId=@POPId



Select CRMSentEmails.[Cc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @CompanyId and CRMSentEmails.EmailEntityPoPId=@POPId

Select CRMSentEmails.[Bcc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @CompanyId and CRMSentEmails.EmailEntityPoPId=@POPId



   SELECT GENTranslate_Company.*, (CASE WHEN GENTranslate_Company.FieldId  IS NOT NULL THEN(PageOfPageFeilds.DisplayName) ELSE '' END) AS FieldDisplayName,
  GENListValues.Name AS LanguageName
   FROM GENTranslate_Company Left join 
   PageOfPageFeilds ON GENTranslate_Company.FieldId=PageOfPageFeilds.id left join
   BaseEntityFields ON GENTranslate_Company.BaseEntityFieldId =BaseEntityFields.id left join
   GENListValues ON GENTranslate_Company.LangId = GENListValues.Id
  WHERE  GENTranslate_Company.CompanyId = @CompanyId


     
   SELECT GenRoles.*,AspNetRoles.Name as RoleName
   FROM GenRoles 
   left join AspNetRoles ON GenRoles.RoleId=AspNetRoles.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @CompanyId


   
SELECT GENCompanyPhones.*,GENPhoneTypes.Name AS PhoneTypeName, GENCompanyPhones.PhoneNumber AS PhoneNumberPrimary, (CASE WHEN GENCompanyPhones.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENCompanyPhones
LEFT JOIN GENPhoneTypes ON GENCompanyPhones.PhoneTypeId = GENPhoneTypes.Id
WHERE CompanyId = @CompanyId
order by GENCompanyPhones.IsDefault desc

SELECT GENCompanyEmails.*,GENCompanyEmails.Id As Id2,GENEmailTypes.Name AS EmailTypeName, GENCompanyEmails.Email AS EmailPrimary, (CASE WHEN GENCompanyEmails.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENCompanyEmails
LEFT JOIN GENEmailTypes ON GENCompanyEmails.EmailTypeId = GENEmailTypes.Id
WHERE CompanyId = @CompanyId
order by GENCompanyEmails.IsDefault desc

SELECT GENAddresses.*, GENAddresses.Id AS Id2,GENRegions.Name AS RegionName,GENCountries.Name AS CountryName, GENProvinces.Name AS ProvinceName, 
GENGovernorates.Name AS GovernorateName, GENCities.Name AS CityName, GENDistricts.Name AS DistrictName,GENAddressZones.Name AS AddressZoneName, GENAreas.Name AS AreaName,
GENListValues.Name AS AddressTypeName,(CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN 'far fa-check-circle' ELSE '' END ) AS IsDefaultIcon
, (CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END ) AS IsDefault
FROM GENAddresses
LEFT JOIN GENRegions ON GENAddresses.RegionsId = GENRegions.Id
LEFT JOIN GENCountries ON GENAddresses.CountryId = GENCountries.Id
LEFT JOIN GENProvinces ON GENAddresses.ProvinceId = GENProvinces.Id
LEFT JOIN GENGovernorates ON GENAddresses.GovernorateId = GENGovernorates.Id
LEFT JOIN GENCities ON GENAddresses.CityId = GENCities.Id
LEFT JOIN GENDistricts ON GENAddresses.DistrictId = GENDistricts.Id
LEFT JOIN GENAddressZones ON GENAddresses.AddressZoneId = GENAddressZones.Id
LEFT JOIN GENAreas ON GENAddresses.AreaId = GENAreas.Id
LEFT JOIN GENListValues ON GENAddresses.AddressTypeId = GENListValues.Id
 WHERE EntityId = @CompanyId AND BaseEntityId = @BaseEntityId
 order by IsDefault desc




select GENContact_Generic.Id,GENContacts.Name,GENContact_Generic.ContactId, CASE
    WHEN GENContacts.Image is null THEN '/Content/images/avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString,(CASE WHEN GENContacts.IsActive = 1 THEN 'True' ELSE 'False' END) AS IsActiveString,
	GENContact_Generic.RelativeRelationId,Relat.Name As RelativeRelationName,Assessment.Name As AssessmentName,CRMSources.Name As SourceName,GENContacts.IsActive,GENContact_Generic.EntityId,GENContact_Generic.BaseEntityId

from  GENContact_Generic left join

	GENContacts ON GENContact_Generic.ContactId=GENContacts.Id  left join
	GENListValues Relat ON GENContact_Generic.RelativeRelationId=Relat.Id left join
	GENListValues Assessment ON GENContacts.AssessmentId=Assessment.Id left join
	CRMSources ON GENContacts.SourceId=CRMSources.Id 
where  GENContact_Generic.EntityId=@CompanyId and GENContact_Generic.BaseEntityId=@BaseEntityId



Select GENBranches.*
From GENBranches
Where GENBranches.BaseEntityId=@BaseEntityId and GENBranches.EntityId=@CompanyId

SELECT GENEntityClassifications.*,GENClassifications.Name As ClassificationName
   FROM GENEntityClassifications 
   LEFT JOIN GENClassifications ON GENEntityClassifications.ClassificationId = GENClassifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @CompanyId

   SELECT GENEntitySpecifications.*,GENSpecifications.Name As SpecificationName
   FROM GENEntitySpecifications 
   LEFT JOIN GENSpecifications ON GENEntitySpecifications.SpecificationId = GENSpecifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @CompanyId


   SELECT GENNews.*
   FROM GENNews 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @CompanyId

   
   
   SELECT GenRoles.*,AspNetRoles.Name as RoleName
   FROM GenRoles 
   left join AspNetRoles ON GenRoles.RoleId=AspNetRoles.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @CompanyId

   SELECT GENPointers.*
   FROM GENPointers 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @CompanyId

 SELECT GENPaymentPlans.*,FORMAT(GENPaymentPlans.DeliveryDate, 'dd/MM/yyyy') AS DeliveryDateString
FROM GENPaymentPlans
WHERE GENPaymentPlans.BaseEntityId=@BaseEntityId and GENPaymentPlans.EntityId=@CompanyId


select GENRequests.*
FROM            GENRequests
where GENRequests.CompanyId=@CompanyId

Select CRMDeals.Id,CRMDeals.Name,CRMDeals.Code,FORMAT(CRMDeals.OpenDate, 'dd/MM/yyyy') AS OpenDateString,FORMAT(CRMDeals.CloseDate, 'dd/MM/yyyy') AS CloseDateString,
FORMAT(CRMDeals.ExpectedCloseDate, 'dd/MM/yyyy') AS ExpectedCloseDateString,CRMDealTypes.Name as DealTypeName,GENCompanies.Name As CompanyName,
GENStatus.Name as StatusName,CRMSources.Name As SourceName,GENListValues.Name as PriortyName
From CRMDeals left join
CRMDealTypes ON CRMDeals.DealTypeId=CRMDealTypes.Id left join
GENCompanies ON CRMDeals.CompanyId=GENCompanies.Id left join
GENStatus ON CRMDeals.StatusId=GENStatus.Id left join
CRMSources ON CRMDeals.SourceId=CRMSources.Id left join
GENListValues ON CRMDeals.PriortyId=GENListValues.Id 
Where CRMDeals.CompanyId=@CompanyId



Select GENProjects.* ,GENCompanies.Name As CompanyName,AspNetUsers.Name As LastUpdatedByName
from GENProjects left join
GENCompanies ON GENProjects.CompanyId=GENCompanies.Id left join 
AspNetUsers ON GENProjects.LastUpdatedById=AspNetUsers.Id

where GENProjects.CompanyId=@CompanyId



select GENItems.*,FORMAT(GENItems.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,GENProjects.Name As ProjectName,AspNetUsers.Name As LastUpdatedByName

from GENItems left join

GENProjects ON GENItems.ProjectId=GENProjects.Id left join
AspNetUsers ON GENItems.LastUpdatedById=AspNetUsers.Id

where GENItems.CompanyId=@CompanyId



Select GENVehicles.*

from GENVehicles

where GENVehicles.GENCompany_Id=@CompanyId


Select CRMQuotes.*,CRMDeals.Name As DealName,CRMDealTypes.Name As DealTypeName,FORMAT(CRMQuotes.ContractDate, 'dd/MM/yyyy') AS ContractDateString
from CRMQuotes left join
CRMDeals ON CRMQuotes.DealId=CRMDeals.Id left join
CRMDealTypes ON CRMQuotes.DealTypeId=CRMDealTypes.Id
Where CRMQuotes.CompanyId=@CompanyId



Select GENTCRs.Id,GENTCRs.Name,GENTCRs.Code,FORMAT(GENTCRs.ContractDate, 'dd/MM/yyyy') AS ContractDateString,CRMDealTypes.Name As DealTypeName,CRMDeals.Name As DealName
from GENTCRs  left join
CRMDeals ON GENTCRs.DealId=CRMDeals.Id left join
CRMDealTypes ON GENTCRs.DealTypeId=CRMDealTypes.Id
where GENTCRs.DealCompanyId=@CompanyId



select TCRItems.Name, TCRItems.IsActive,GENTCRs.Name As Bill,GENItems.Name AS Item,CRMDeals.Name As Deal,GENProjects.Name AS Project
from  TCRItems left join
GENTCRs ON TCRItems.TCRId=GENTCRs.Id left join
GENItems ON TCRItems.ItemId =GENItems.Id left join
CRMDeals ON TCRItems.DealId =CRMDeals.Id left join 
GENProjects ON TCRItems.ProjectId=GENProjects.Id
where GENTCRs.DealCompanyId=@CompanyId

exec SP_GetAllChatMessages @POPId,@CompanyId
GO
