CREATE PROC [dbo].[SP_SelectCompayData_ByCode] (@Code nvarchar(MAX))
AS
Begin
select GENCompanies.Code AS CompanyCode,GENCompanies.Id AS CompanyId,GENCompanies.Name AS CompanyName,GENCompanyTypes.Name AS CompanyTypeName,GENCompanyTypes.Id AS CompanyTypeId
from GENCompanies inner join GENCompanyTypes ON GENCompanies.CompanyTypeId=GENCompanyTypes.Id
where GENCompanies.Code=@Code and GENCompanies.IsActive = 1 and GENCompanies.IsPublish = 1
END
