CREATE Proc [dbo].[SP_SelectContact_ByEmailandIdNumber] --'ashraf_samy@yahoo.com',27809300104032 
(@Email nvarchar(250),@IDNumber nvarchar(250))
as
Begin
select IDNumber,DefaultEmail 
FROM            dbo.GENContacts inner JOIN
                         dbo.AspNetUsers ON dbo.GENContacts.UserId = dbo.AspNetUsers.Id
WHERE        (dbo.AspNetUsers.Email = @Email or dbo.GENContacts.DefaultEmail =  @Email) and dbo.GENContacts.IDNumber=@IDNumber 
and dbo.GENContacts.UserId is not null and dbo.GENContacts.IsDeleted  =0
end
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectContactById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
