SELECT [dbo].[Employee_View].* FROM [dbo].[Employee_View]
INNER JOIN GENContacts ON GENContacts.ResponsiblePersonId = [Employee_View].Id
 WHERE GENContacts.Id = @ContactId

SELECT TOP(1) GENStatus.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN GENStyles ON GENStatus.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @ContactId
ORDER BY [dbo].[GENProcesses].Id Desc

SELECT NextStat.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN [dbo].[GENNextStatus] ON GENStatus.Id = [dbo].[GENNextStatus].CurrentStatusId
LEFT JOIN GENStatus NextStat ON NextStat.Id = [dbo].[GENNextStatus].NextStatusId
LEFT JOIN GENStyles ON NextStat.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @ContactId
ORDER BY [dbo].[GENNextStatus].Id Desc

SELECT CRMDealItems.*,'Deal' AS TypeName, GENProjects.Name AS ProjectName,GENItems.IsActive,GENItems.IsPublish,GENItems.Name As ItemName, GENItems.Image As ItemImage 
FROM CRMDealItems
LEFT JOIN CRMDeals ON CRMDealItems.DealId = CRMDeals.Id
LEFT JOIN GENItems ON CRMDealItems.ItemId = GENItems.Id
LEFT JOIN GENProjects ON GENItems.ProjectId = GENProjects.Id
WHERE CRMDeals.ContactId = @ContactId

SELECT * FROM Courses_Requestes WHERE StudentId = @ContactId

DECLARE @DrugId BIGINT,@InvestigationId BIGINT
SELECT @DrugId = CAST(Value AS BIGINT) FROM GENConfigurations WHERE Name = 'DrugId'
SELECT @InvestigationId = CAST(Value AS BIGINT) FROM GENConfigurations WHERE Name = 'InvestigationId'
SELECT DISTINCT CRMTickets.Id, CRMTickets.DateCreated, GENStatus.Name AS StatusName, CRMSRVTicketTypes.Name AS TicketTypeName,
COUNT(Investigation.Id) AS InvestigationCount, COUNT(Drugs.Id) AS DrugCount,
COUNT(SpinalInjection.Id) AS SpinalInjectionCount, COUNT(Physio.Id) AS PhysoCount FROM CRMTickets 
LEFT JOIN CRMSRVTicketTypes ON CRMTickets.TicketTypeId = CRMSRVTicketTypes.Id
LEFT JOIN GENStatus ON CRMTickets.StatusId = GENStatus.Id
LEFT JOIN Items_Generic AS Drugs ON Drugs.TicketId = CRMTickets.Id AND Drugs.ListValueId = @DrugId
LEFT JOIN Items_Generic AS Investigation ON Investigation.TicketId = CRMTickets.Id AND Investigation.ListValueId = @InvestigationId
LEFT JOIN CRMSRVTicket_Comment AS SpinalInjection ON SpinalInjection.CRMTicketId = CRMTickets.Id
LEFT JOIN GENCommentTypes AS Spinal ON SpinalInjection.CommentTypeId = Spinal.Id AND Spinal.Name = 'Spinal Injection'
LEFT JOIN CRMSRVTicket_Comment AS Physio ON Physio.CRMTicketId = CRMTickets.Id
LEFT JOIN GENCommentTypes AS PhysioType ON Physio.CommentTypeId = PhysioType.Id AND PhysioType.Name = 'Session'
WHERE CRMTickets.ContactId = @ContactId
GROUP BY CRMTickets.Id, CRMTickets.DateCreated, GENStatus.Name, CRMSRVTicketTypes.Name

SELECT CRMTickets.Id,CRMSRVTicketTypes.Name As CRMTicketName, CRMTickets.DateCreated AS TicketActionDate, CRMSRVTicket_Comment.ActionDate,
 GENCommentTypes.Name AS CommentTypeName, CRMSRVTicket_Comment.Comment, GENItems.Name AS ItemName FROM CRMSRVTicket_Comment
INNER JOIN CRMTickets ON CRMSRVTicket_Comment.CRMTicketId = CRMTickets.Id
LEFT JOIN CRMSRVTicketTypes ON CRMTickets.TicketTypeId = CRMSRVTicketTypes.Id
LEFT JOIN GENItems ON CRMSRVTicket_Comment.ItemId = GENItems.Id
LEFT JOIN GENCommentTypes ON CRMSRVTicket_Comment.CommentTypeId = GENCommentTypes.Id
 WHERE CRMSRVTicket_Comment.MainContactId = @ContactId AND CRMSRVTicket_Comment.IsDeleted = 0

SELECT (CASE WHEN CRMTickets.Id  IS NOT NULL THEN(CRMTickets.Id) ELSE Items_Generic.Id END) AS Id, CRMSRVTicketTypes.Name AS CRMTicketName, CRMTickets.DateCreated AS TicketActionDate,
GENStatus.Name AS StatusName, [dbo].[Items_Generic].DateCreated, GENTypes.Name AS ItemTypeName, GENItemCategories.Name AS ItemCategoryName,
ItemListVal.Name AS ItemListValueName, GENListValues.Name AS ListValueName,GENItems.Description AS ItemDescription, GENItems.Name AS ItemName  FROM [dbo].[Items_Generic]
LEFT JOIN GENItems ON Items_Generic.ItemId = GENItems.Id
LEFT JOIN GENTypes ON GENItems.TypeId = GENTypes.Id
LEFT JOIN GENListValues ItemListVal ON [Items_Generic].ItemListValueId = ItemListVal.Id
LEFT JOIN GENListValues ON [Items_Generic].ListValueId = GENListValues.Id
LEFT JOIN GENItemCategory_Item ON [dbo].[GENItemCategory_Item].ItemId = GENItems.Id
LEFT JOIN GENItemCategories ON [dbo].[GENItemCategory_Item].ItemCategoryId = GENItemCategories.Id
LEFT JOIN CRMTickets ON Items_Generic.TicketId = CRMTickets.Id
LEFT JOIN CRMSRVTicketTypes ON CRMTickets.TicketTypeId = CRMSRVTicketTypes.Id
LEFT JOIN GENStatus ON CRMTickets.StatusId = GENStatus.Id
 WHERE [Items_Generic].ContactId = @ContactId


select GENPollCategories.Id,GENExamAnswerHeaders.StudentName,GENExamAnswerHeaders.ExamName,FORMAT(GENExamAnswerHeaders.ExamTime, 'dd/MM/yyyy hh:mm tt') AS ExamTimeString,
GENExamAnswerDetails.AnswerName,GENExamAnswerDetails.QuestionCorrectedAnswer
FROM            GENPollCategories LEFT JOIN
dbo.GenRoles on dbo.GENPollCategories.Id = dbo.GenRoles.EntityId AND dbo.GenRoles.BaseEntityId = 129 LEFT JOIN
                GENExamAnswerHeaders ON GENPollCategories.Id = GENExamAnswerHeaders.ExamId LEFT JOIN
				GENExamAnswerDetails ON GENExamAnswerHeaders.Id =GENExamAnswerDetails.ExamAnswerHeaderId
where GENExamAnswerHeaders.StudentId=@ContactId AND (@RoleId IS NULL OR dbo.GenRoles.RoleId IS NULL OR (dbo.GenRoles.RoleId = @RoleId AND (dbo.GenRoles.IsReadOnly = 1 OR dbo.GenRoles.IsEdit = 1)))

select GENExamAnswerHeaders.CourseName,FORMAT(GENExamAnswerHeaders.StartDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
GENExamAnswerHeaders.EndtDateTime,FORMAT(GENExamAnswerHeaders.EndtDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString,
GENExamAnswerHeaders.ClassroomName
FROM            GENTypes LEFT JOIN
                GENExamAnswerHeaders ON GENTypes.Id = GENExamAnswerHeaders.CourseId
where GENExamAnswerHeaders.StudentId=@ContactId

select GENOrders.*
FROM            GENOrders 
where GENOrders.ContactId=@ContactId


Select CRMSentEmails.[To], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ContactId and CRMSentEmails.EmailEntityPoPId=@POPId


Select CRMSentEmails.[From], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ContactId and CRMSentEmails.EmailEntityPoPId=@POPId



Select CRMSentEmails.[Cc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ContactId and CRMSentEmails.EmailEntityPoPId=@POPId

Select CRMSentEmails.[Bcc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]
From CRMSentEmails
Where CRMSentEmails.EmailEntityId= @ContactId and CRMSentEmails.EmailEntityPoPId=@POPId


Select GENBranches.*
From GENBranches
Where GENBranches.BaseEntityId=@BaseEntityId and GENBranches.EntityId=@ContactId

SELECT GENEntityClassifications.*,GENClassifications.Name As ClassificationName
   FROM GENEntityClassifications 
   LEFT JOIN GENClassifications ON GENEntityClassifications.ClassificationId = GENClassifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   SELECT GENEntitySpecifications.*,GENSpecifications.Name As SpecificationName
   FROM GENEntitySpecifications 
   LEFT JOIN GENSpecifications ON GENEntitySpecifications.SpecificationId = GENSpecifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId


   SELECT GENNews.*
   FROM GENNews 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   
   
   SELECT GenRoles.*,AspNetRoles.Name as RoleName
   FROM GenRoles 
   left join AspNetRoles ON GenRoles.RoleId=AspNetRoles.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   SELECT GENPointers.*,Parent.Name as ParentName
   FROM GENPointers 
   left join GENTypeCategories on GENTypeCategories.Id = GENPointers.EntityIdPointerTo
   left join GENTypeCategories Parent on Parent.Id = GENTypeCategories.ParentId
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   SELECT GENPaymentPlans.*
FROM GENPaymentPlans
WHERE GENPaymentPlans.BaseEntityId=@BaseEntityId and GENPaymentPlans.EntityId=@ContactId


    SELECT GENTranslate_Contact.*, (CASE WHEN GENTranslate_Contact.FieldId  IS NOT NULL THEN(PageOfPageFeilds.DisplayName) ELSE '' END) AS FieldDisplayName,
  GENListValues.Name AS LanguageName
   FROM GENTranslate_Contact Left join 
   PageOfPageFeilds ON GENTranslate_Contact.FieldId=PageOfPageFeilds.id left join
   BaseEntityFields ON GENTranslate_Contact.BaseEntityFieldId =BaseEntityFields.id left join
   GENListValues ON GENTranslate_Contact.LangId = GENListValues.Id
  WHERE  GENTranslate_Contact.ContactId = @ContactId


select distinct GENExamAnswerHeaders.Id, ExamName,InstructorName,StudentName,TotalExamScore,TotalScore,FORMAT(ExamTime, 'dd/MM/yyyy hh:mm tt') AS ExamTimeString,CourseName,FORMAT(StartDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
FORMAT(EndtDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString
FROM            GENExamAnswerHeaders   LEFT JOIN
dbo.GenRoles on dbo.GENExamAnswerHeaders.ExamId = dbo.GenRoles.EntityId AND dbo.GenRoles.BaseEntityId = 129
where GENExamAnswerHeaders.StudentId=@ContactId  AND (@RoleId IS NULL OR dbo.GenRoles.RoleId IS NULL OR (dbo.GenRoles.RoleId = @RoleId AND (dbo.GenRoles.IsReadOnly = 1 OR dbo.GenRoles.IsEdit = 1)))


select GENContact_Generic.Id,GENContacts.Name,GENContact_Generic.ContactId,GENContact_Generic.Contactus, CASE
    WHEN GENContacts.Image is null THEN '/Content/images/User-Avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.Code,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString,(CASE WHEN GENContacts.IsActive = 1 THEN 'True' ELSE 'False' END) AS IsActiveString,GENContacts.IsActive,
	GENContact_Generic.RelativeRelationId,Relat.Name As RelativeRelationName,Assessment.Name As AssessmentName,CRMSources.Name As SourceName,GENContacts.IsActive,GENContact_Generic.EntityId,GENContact_Generic.BaseEntityId
from  GENContact_Generic left join
	GENContacts ON GENContact_Generic.ContactId=GENContacts.Id  left join
	GENListValues Relat ON GENContact_Generic.RelativeRelationId=Relat.Id left join
	GENListValues Assessment ON GENContacts.AssessmentId=Assessment.Id left join
	CRMSources ON GENContacts.SourceId=CRMSources.Id 
where  GENContact_Generic.EntityId=@ContactId and GENContact_Generic.BaseEntityId=@BaseEntityId



select GENClassrooms.Id,GENClassrooms.IsActive,GENClassrooms.Name AS ClassroomName,GENClassrooms.Code As ClassroomCode,GENTypes.Name As CourseName,GENEmployees.Name As InstructorName,
(CASE WHEN GENClassrooms.ClassRoomStatus = 0 THEN 'Started' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 1 THEN 'Dropped' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 2 THEN 'Done' ELSE '' END END END) AS ClassRoomStatusString
,GENClassrooms.FromDatetime,FORMAT(GENClassrooms.FromDatetime, 'dd/MM/yyyy') AS FromDatetimeString,GENClassrooms.ToDatetime,FORMAT(GENClassrooms.ToDatetime, 'dd/MM/yyyy') AS ToDatetimeString
FROM GENClassroom_GENContact inner join
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 
GENTypes ON GENClassrooms.CourseId=GENTypes.Id left join 
GENEmployees ON GENClassrooms.InstructorId =GENEmployees.Id
where GENClassroom_GENContact.StudentId=@ContactId and GENClassrooms.Isdeleted=0 and GENTypes.IsDeleted=0 and 
 ([dbo].[AttendanceCall]([GENClassroom_GENContact].StudentId,GENClassrooms.Id) >=isnull(GENClassrooms.Int4,GENTypes.int3))
 and  GENClassroom_GENContact.BookingTypeId=1 



Select CRMDeals.Id,CRMDeals.Name,CRMDeals.Code,FORMAT(CRMDeals.OpenDate, 'dd/MM/yyyy') AS OpenDateString,FORMAT(CRMDeals.CloseDate, 'dd/MM/yyyy') AS CloseDateString,
FORMAT(CRMDeals.ExpectedCloseDate, 'dd/MM/yyyy') AS ExpectedCloseDateString,CRMDealTypes.Name as DealTypeName,GENCompanies.Name As CompanyName,
GENStatus.Name as StatusName,CRMSources.Name As SourceName,GENListValues.Name as PriortyName
From CRMDeals left join
CRMDealTypes ON CRMDeals.DealTypeId=CRMDealTypes.Id left join
GENCompanies ON CRMDeals.CompanyId=GENCompanies.Id left join
GENStatus ON CRMDeals.StatusId=GENStatus.Id left join
CRMSources ON CRMDeals.SourceId=CRMSources.Id left join
GENListValues ON CRMDeals.PriortyId=GENListValues.Id 
Where CRMDeals.ContactId=@ContactId


exec SP_GetAllChatMessages @POPId,@ContactId

select GENContact_Talent.*,GENTalents.Name AS TalentName,GENContact_Talent.TalentId AS EntityId, CAST(0 AS bit) AS Contactus, IsActive
from  GENContact_Talent 
LEFT JOIN GENTalents ON GENContact_Talent.TalentId = GENTalents.Id 
WHERE GENContact_Talent .ContactId = @ContactId


Select Items_Generic.Id,Items_Generic.ItemId,GENItems.Name As ItemName,GENItems.CategoryName,Items_Generic.Closed,
FORMAT(GENItems.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,Items_Generic.Description, GENItems.TypeId As ItemTypeId
From  Items_Generic left Join
GENItems ON Items_Generic.ItemId=GENItems.Id
where Items_Generic.ContactId=@ContactId

SELECT GENWikis.*,FORMAT(GENWikis.DateCreated, 'dd/MM/yyyy hh:mm tt') AS DateCreatedString,FORMAT(GENWikis.DateUpdated, 'dd/MM/yyyy hh:mm tt') AS DateUpdatedString, 
GENWikiCategories.Name AS CategoryName, GENWikiCategories.Name AS WikiCatName,
GENContacts.Name AS ContactName, AspNetUsers.Name As LastUpdatedByName FROM GENWikis
LEFT JOIN GENWikiCategories ON GENWikis.WikiCategoryId = GENWikiCategories.Id
LEFT JOIN AspNetUsers ON GENWikis.LastUpdatedById = AspNetUsers.Id
LEFT JOIN GENContacts ON GENWikis.ContactId= GENContacts.Id
Where GENWikis.ContactId = @ContactId




SELECT GENWikis.Id ,P.Name as ParentName ,GENWikiCategories.Name AS WikiCategoryName, GENWikiCategories.Id As WikiCategoryId,GENWikiCategories.ParentId As ParentId ,
GENWikis.Description,GENWikis.ContactId,GENWikis.valueId1,GENWikis.valueId2,GENListValues.Name As ValueId1Name,Lv2.Name AS ValueId2Name
FROM GENWikis
LEFT JOIN GENWikiCategories ON GENWikis.WikiCategoryId = GENWikiCategories.Id  left join
GENWikiCategories P ON GENWikiCategories.ParentId=p.ID left join 
GENListValues ON GENWikis.valueId1 = GENListValues.Id left join 
GENListValues Lv2 ON GENWikis.valueId2 = Lv2.Id
Where GENWikis.ContactId = @ContactId



Select distinct GENTypes.Id AS CourseId,GENTypes.Name AS CourseName,GENTypes.Code AS CourseCode,GENTypeCategories.name AS CatName
FROM     GENClassroom_GENContact inner join
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 
GENTypes ON GENClassrooms.CourseId=GENTypes.Id left join 
CourseCategories ON GENTypes.Id=CourseCategories.CourseId left join 
GENTypeCategories ON GENTypes.TypeCategoryId=GENTypeCategories.Id
where GENClassroom_GENContact.StudentId=@ContactId and GENClassrooms.Isdeleted=0 and GENTypes.IsDeleted=0




SELECT GENDualLinkAttachments.*,GENListValues.Name AS LanguageName,LV.Name As FileType, FORMAT(GENDualLinkAttachments.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENDualLinkAttachments.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENDualLinkAttachments.AzureUri), CHARINDEX('.', REVERSE(GENDualLinkAttachments.AzureUri)) - 1)) AS FileExt 
FROM GENDualLinkAttachments
LEFT JOIN GENListValues ON GENDualLinkAttachments.LanguageId = GENListValues.Id left join
GENListValues LV ON GENDualLinkAttachments.FileTypeId=LV.Id
 WHERE 
 GENDualLinkAttachments.BaseEntityIdTo =@BaseEntityId and GENDualLinkAttachments.EntityIdTo =@ContactId
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectContactByIdFromUserId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create proc [dbo].[SP_SelectContactByIdFromUserId](@ContactId bigint, @BaseEntityId bigint)
as
DECLARE @PopId BIGINT = NULL
DECLARE @CompanyId BIGINT = NULL
DECLARE @DefaultAddress NVARCHAR(MAX) = NULL
select TOP(1) @CompanyId = [dbo].[Contact_View].CompanyId from [dbo].[Contact_View] where Id = @ContactId

select @DefaultAddress= DefaultAddress from [dbo].[Contact_View] where Id = @ContactId
select TOP(1) *, (CASE WHEN [dbo].[Contact_View].CompanyId IS NOT NULL THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END) AS IsSelectedCompany from [dbo].[Contact_View] where Id = @ContactId

select TOP(1) *  from Company_View_Update where Id = @CompanyId

SELECT GENImages.*, GENImages.AzureUri AS Image FROM GENImages WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

SELECT GENGalleryAlbumImages.*, GENGalleryAlbumImages.AzureUri AS Image, GENGalleryAlbums.Name AS GalleryAlbumName FROM GENGalleryAlbumImages
LEFT JOIN GENGalleryAlbums ON GENGalleryAlbumImages.GalleryAlbumId = GENGalleryAlbums.Id
 WHERE GENGalleryAlbumImages.BaseEntityId = @BaseEntityId AND GENGalleryAlbumImages.EntityId = @ContactId

SELECT GENGalleryAlbums.* FROM GENGalleryAlbums WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId



SELECT GENFiles.*,GENListValues.Name AS LanguageName,LV.Name As FileType, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt 
FROM GENFiles
LEFT JOIN GENListValues ON GENFiles.LanguageId = GENListValues.Id left join
GENListValues LV ON GENFiles.FileTypeId=LV.Id
 WHERE GENFiles.BaseEntityId = @BaseEntityId AND GENFiles.EntityId = @ContactId

SELECT GENAudios.* FROM GENAudios WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

SELECT GENVideos.*,FORMAT(GENVideos.DateCreated, 'dd/MM/yyyy') AS DateCreatedString
 FROM GENVideos WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

SELECT GENLinks.* FROM GENLinks WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

SELECT [dbo].[GENEntity_Tag].*, GENTags.Name AS TagName FROM [dbo].[GENEntity_Tag]
LEFT JOIN GENTags ON [dbo].[GENEntity_Tag].TagId = GENTags.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

SELECT [dbo].[GENEntity_GENWiki].*, GENWikis.Name AS Name FROM [dbo].[GENEntity_GENWiki] 
LEFT JOIN GENWikis ON [dbo].[GENEntity_GENWiki].WikiId = GENWikis.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

SELECT EmployeeEscalations.*, GENEmployees.Name, GENEmployees.Position, GENEmployees.Image FROM EmployeeEscalations
LEFT JOIN GENEmployees ON EmployeeEscalations.EmployeeId = GENEmployees.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId ORDER BY EmployeeEscalations.DisplayOrder

SELECT GENEntityPricings.*, GENCurrencies.Name AS CurrencyName, GENRegions.Name AS regionName, GENUnits.Name AS UnitName,
 FORMAT(GENEntityPricings.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString, 
 FORMAT(GENEntityPricings.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString FROM GENEntityPricings
LEFT JOIN GENCurrencies ON GENEntityPricings.CurrencyId = GENCurrencies.Id
LEFT JOIN GENRegions ON GENEntityPricings.RegionId = GENRegions.Id
LEFT JOIN GENUnits ON GENEntityPricings.UnitId = GENUnits.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId 

SELECT GENContactPhones.*,GENPhoneTypes.Name AS PhoneTypeName, GENContactPhones.PhoneNumber AS PhoneNumberPrimary, (CASE WHEN GENContactPhones.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENContactPhones
LEFT JOIN GENPhoneTypes ON GENContactPhones.PhoneTypeId = GENPhoneTypes.Id
WHERE ContactId = @ContactId

SELECT GENContactEmails.*,GENContactEmails.Id As Id2,GENEmailTypes.Name AS EmailTypeName, GENContactEmails.Email AS EmailPrimary, (CASE WHEN GENContactEmails.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENContactEmails
LEFT JOIN GENEmailTypes ON GENContactEmails.EmailTypeId = GENEmailTypes.Id
WHERE ContactId = @ContactId

SELECT GENAddresses.*, GENRegions.Name AS RegionName,GENCountries.Name AS CountryName, GENProvinces.Name AS ProvinceName, 
GENGovernorates.Name AS GovernorateName, GENCities.Name AS CityName, GENDistricts.Name AS DistrictName,GENAddressZones.Name AS AddressZoneName, GENAreas.Name AS AreaName,
GENListValues.Name AS AddressTypeName,(CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN 'far fa-check-circle' ELSE '' END ) AS IsDefaultIcon
, (CASE WHEN GENAddresses.StreetBuilding =@DefaultAddress THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END ) AS IsDefault
FROM GENAddresses
LEFT JOIN GENRegions ON GENAddresses.RegionsId = GENRegions.Id
LEFT JOIN GENCountries ON GENAddresses.CountryId = GENCountries.Id
LEFT JOIN GENProvinces ON GENAddresses.ProvinceId = GENProvinces.Id
LEFT JOIN GENGovernorates ON GENAddresses.GovernorateId = GENGovernorates.Id
LEFT JOIN GENCities ON GENAddresses.CityId = GENCities.Id
LEFT JOIN GENDistricts ON GENAddresses.DistrictId = GENDistricts.Id
LEFT JOIN GENAddressZones ON GENAddresses.AddressZoneId = GENAddressZones.Id
LEFT JOIN GENAreas ON GENAddresses.AreaId = GENAreas.Id
LEFT JOIN GENListValues ON GENAddresses.AddressTypeId = GENListValues.Id
 WHERE EntityId = @ContactId AND BaseEntityId = @BaseEntityId

select AllActivitiesWithDetails.* from AllActivitiesWithDetails
LEFT JOIN [dbo].[Contact_View] ON ActivityContactId = [dbo].[Contact_View].Id OR AllActivitiesWithDetails.ContactPersonId = [dbo].[Contact_View].Id
WHERE [dbo].[Contact_View].CompanyId = @ContactId AND (AllActivitiesWithDetails.ActivityContactId =  @ContactId OR AllActivitiesWithDetails.ContactPersonId = @ContactId)

SELECT [dbo].[Employee_View].* FROM [dbo].[Employee_View]
INNER JOIN GENContacts ON GENContacts.ResponsiblePersonId = [Employee_View].Id
 WHERE GENContacts.Id = @ContactId

SELECT TOP(1) GENStatus.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN GENStyles ON GENStatus.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @ContactId
ORDER BY [dbo].[GENProcesses].Id Desc

SELECT NextStat.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN [dbo].[GENNextStatus] ON GENStatus.Id = [dbo].[GENNextStatus].CurrentStatusId
LEFT JOIN GENStatus NextStat ON NextStat.Id = [dbo].[GENNextStatus].NextStatusId
LEFT JOIN GENStyles ON NextStat.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @ContactId and NextStat.id is not null
ORDER BY [dbo].[GENNextStatus].Id Desc

SELECT CRMDealItems.*,'Deal' AS TypeName, GENProjects.Name AS ProjectName,GENItems.IsActive,GENItems.IsPublish,GENItems.Name As ItemName, GENItems.Image As ItemImage 
FROM CRMDealItems
LEFT JOIN CRMDeals ON CRMDealItems.DealId = CRMDeals.Id
LEFT JOIN GENItems ON CRMDealItems.ItemId = GENItems.Id
LEFT JOIN GENProjects ON GENItems.ProjectId = GENProjects.Id
WHERE CRMDeals.ContactId = @ContactId

SELECT * FROM Courses_Requestes WHERE StudentId = @ContactId

DECLARE @DrugId BIGINT,@InvestigationId BIGINT
SELECT @DrugId = CAST(Value AS BIGINT) FROM GENConfigurations WHERE Name = 'DrugId'
SELECT @InvestigationId = CAST(Value AS BIGINT) FROM GENConfigurations WHERE Name = 'InvestigationId'
SELECT DISTINCT CRMTickets.Id, CRMTickets.DateCreated, GENStatus.Name AS StatusName, CRMSRVTicketTypes.Name AS TicketTypeName,
COUNT(Investigation.Id) AS InvestigationCount, COUNT(Drugs.Id) AS DrugCount,
COUNT(SpinalInjection.Id) AS SpinalInjectionCount, COUNT(Physio.Id) AS PhysoCount FROM CRMTickets 
LEFT JOIN CRMSRVTicketTypes ON CRMTickets.TicketTypeId = CRMSRVTicketTypes.Id
LEFT JOIN GENStatus ON CRMTickets.StatusId = GENStatus.Id
LEFT JOIN Items_Generic AS Drugs ON Drugs.TicketId = CRMTickets.Id AND Drugs.ListValueId = @DrugId
LEFT JOIN Items_Generic AS Investigation ON Investigation.TicketId = CRMTickets.Id AND Investigation.ListValueId = @InvestigationId
LEFT JOIN CRMSRVTicket_Comment AS SpinalInjection ON SpinalInjection.CRMTicketId = CRMTickets.Id
LEFT JOIN GENCommentTypes AS Spinal ON SpinalInjection.CommentTypeId = Spinal.Id AND Spinal.Name = 'Spinal Injection'
LEFT JOIN CRMSRVTicket_Comment AS Physio ON Physio.CRMTicketId = CRMTickets.Id
LEFT JOIN GENCommentTypes AS PhysioType ON Physio.CommentTypeId = PhysioType.Id AND PhysioType.Name = 'Session'
WHERE CRMTickets.ContactId = @ContactId
GROUP BY CRMTickets.Id, CRMTickets.DateCreated, GENStatus.Name, CRMSRVTicketTypes.Name

SELECT CRMTickets.Id,CRMSRVTicketTypes.Name As CRMTicketName, CRMTickets.DateCreated AS TicketActionDate, CRMSRVTicket_Comment.ActionDate,
 GENCommentTypes.Name AS CommentTypeName, CRMSRVTicket_Comment.Comment, GENItems.Name AS ItemName FROM CRMSRVTicket_Comment
INNER JOIN CRMTickets ON CRMSRVTicket_Comment.CRMTicketId = CRMTickets.Id
LEFT JOIN CRMSRVTicketTypes ON CRMTickets.TicketTypeId = CRMSRVTicketTypes.Id
LEFT JOIN GENItems ON CRMSRVTicket_Comment.ItemId = GENItems.Id
LEFT JOIN GENCommentTypes ON CRMSRVTicket_Comment.CommentTypeId = GENCommentTypes.Id
 WHERE CRMSRVTicket_Comment.MainContactId = @ContactId AND CRMSRVTicket_Comment.IsDeleted = 0

SELECT (CASE WHEN CRMTickets.Id  IS NOT NULL THEN(CRMTickets.Id) ELSE Items_Generic.Id END) AS Id, CRMSRVTicketTypes.Name AS CRMTicketName, CRMTickets.DateCreated AS TicketActionDate,
GENStatus.Name AS StatusName, [dbo].[Items_Generic].DateCreated, GENTypes.Name AS ItemTypeName, GENItemCategories.Name AS ItemCategoryName,
ItemListVal.Name AS ItemListValueName, GENListValues.Name AS ListValueName,GENItems.Description AS ItemDescription, GENItems.Name AS ItemName  FROM [dbo].[Items_Generic]
LEFT JOIN GENItems ON Items_Generic.ItemId = GENItems.Id
LEFT JOIN GENTypes ON GENItems.TypeId = GENTypes.Id
LEFT JOIN GENListValues ItemListVal ON [Items_Generic].ItemListValueId = ItemListVal.Id
LEFT JOIN GENListValues ON [Items_Generic].ListValueId = GENListValues.Id
LEFT JOIN GENItemCategory_Item ON [dbo].[GENItemCategory_Item].ItemId = GENItems.Id
LEFT JOIN GENItemCategories ON [dbo].[GENItemCategory_Item].ItemCategoryId = GENItemCategories.Id
LEFT JOIN CRMTickets ON Items_Generic.TicketId = CRMTickets.Id
LEFT JOIN CRMSRVTicketTypes ON CRMTickets.TicketTypeId = CRMSRVTicketTypes.Id
LEFT JOIN GENStatus ON CRMTickets.StatusId = GENStatus.Id
 WHERE [Items_Generic].ContactId = @ContactId


select GENPollCategories.Id,GENExamAnswerHeaders.StudentName,GENExamAnswerHeaders.ExamName,FORMAT(GENExamAnswerHeaders.ExamTime, 'dd/MM/yyyy hh:mm tt') AS ExamTimeString,
GENExamAnswerDetails.AnswerName,GENExamAnswerDetails.QuestionCorrectedAnswer
FROM            GENPollCategories LEFT JOIN
	dbo.GenRoles on dbo.GENPollCategories.Id = dbo.GenRoles.EntityId AND dbo.GenRoles.BaseEntityId = 129 LEFT JOIN
                GENExamAnswerHeaders ON GENPollCategories.Id = GENExamAnswerHeaders.ExamId LEFT JOIN
				GENExamAnswerDetails ON GENExamAnswerHeaders.Id =GENExamAnswerDetails.ExamAnswerHeaderId
where GENExamAnswerHeaders.StudentId=@ContactId 

select GENExamAnswerHeaders.CourseName,FORMAT(GENExamAnswerHeaders.StartDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
GENExamAnswerHeaders.EndtDateTime,FORMAT(GENExamAnswerHeaders.EndtDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString,
GENExamAnswerHeaders.ClassroomName
FROM            GENTypes LEFT JOIN
                GENExamAnswerHeaders ON GENTypes.Id = GENExamAnswerHeaders.CourseId
			

where GENExamAnswerHeaders.StudentId=@ContactId

select GENOrders.*
FROM            GENOrders 
			

where GENOrders.ContactId=@ContactId


Select CRMSentEmails.[To], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @ContactId 


Select CRMSentEmails.[From], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @ContactId



Select CRMSentEmails.[Cc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @ContactId

Select CRMSentEmails.[Bcc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @ContactId


Select GENBranches.*
From GENBranches
Where GENBranches.BaseEntityId=@BaseEntityId and GENBranches.EntityId=@ContactId

SELECT GENEntityClassifications.*,GENClassifications.Name As ClassificationName
   FROM GENEntityClassifications 
   LEFT JOIN GENClassifications ON GENEntityClassifications.ClassificationId = GENClassifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   SELECT GENEntitySpecifications.*,GENSpecifications.Name As SpecificationName
   FROM GENEntitySpecifications 
   LEFT JOIN GENSpecifications ON GENEntitySpecifications.SpecificationId = GENSpecifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId


   SELECT GENNews.*
   FROM GENNews 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   
   
   SELECT GenRoles.*,AspNetRoles.Name as RoleName
   FROM GenRoles 
   left join AspNetRoles ON GenRoles.RoleId=AspNetRoles.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   SELECT GENPointers.*
   FROM GENPointers 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @ContactId

   SELECT GENPaymentPlans.*
FROM GENPaymentPlans
WHERE GENPaymentPlans.BaseEntityId=@BaseEntityId and GENPaymentPlans.EntityId=@ContactId


    SELECT GENTranslate_Contact.*, (CASE WHEN GENTranslate_Contact.FieldId  IS NOT NULL THEN(PageOfPageFeilds.DisplayName) ELSE '' END) AS FieldDisplayName,
  GENListValues.Name AS LanguageName
   FROM GENTranslate_Contact Left join 
   PageOfPageFeilds ON GENTranslate_Contact.FieldId=PageOfPageFeilds.id left join
   BaseEntityFields ON GENTranslate_Contact.BaseEntityFieldId =BaseEntityFields.id left join
   GENListValues ON GENTranslate_Contact.LangId = GENListValues.Id
  WHERE  GENTranslate_Contact.ContactId = @ContactId


select distinct Id, ExamName,InstructorName,StudentName,TotalExamScore,TotalScore,ExamWeight,FORMAT(ExamTime, 'dd/MM/yyyy hh:mm tt') AS ExamTimeString,CourseName,FORMAT(StartDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
FORMAT(EndtDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString
FROM            GENExamAnswerHeaders   
where GENExamAnswerHeaders.StudentId=@ContactId


select GENContact_Generic.Id,GENContacts.Name,GENContact_Generic.ContactId,GENContact_Generic.Contactus, CASE
    WHEN GENContacts.Image is null THEN '/Content/images/User-Avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,GENContacts.Code,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString,(CASE WHEN GENContacts.IsActive = 1 THEN 'True' ELSE 'False' END) AS IsActiveString,GENContacts.IsActive,
	GENContact_Generic.RelativeRelationId,Relat.Name As RelativeRelationName,Assessment.Name As AssessmentName,CRMSources.Name As SourceName,GENContacts.IsActive,GENContact_Generic.EntityId,GENContact_Generic.BaseEntityId

from  GENContact_Generic left join

	GENContacts ON GENContact_Generic.ContactId=GENContacts.Id  left join
	GENListValues Relat ON GENContact_Generic.RelativeRelationId=Relat.Id left join
	GENListValues Assessment ON GENContacts.AssessmentId=Assessment.Id left join
	CRMSources ON GENContacts.SourceId=CRMSources.Id 
where  GENContact_Generic.EntityId=@ContactId and GENContact_Generic.BaseEntityId=@BaseEntityId



select GENClassrooms.Id,GENClassrooms.IsActive,GENClassrooms.Name AS ClassroomName,GENClassrooms.Code As ClassroomCode,GENTypes.Name As CourseName,GENEmployees.Name As InstructorName,
(CASE WHEN GENClassrooms.ClassRoomStatus = 0 THEN 'Started' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 1 THEN 'Dropped' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 2 THEN 'Done' ELSE '' END END END) AS ClassRoomStatusString
FROM     GENClassroom_GENContact left join
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id left join 
GENTypes ON GENClassrooms.CourseId=GENTypes.Id left join 
GENEmployees ON GENClassrooms.InstructorId =GENEmployees.Id
where GENClassroom_GENContact.StudentId=@ContactId



Select CRMDeals.Id,CRMDeals.Name,CRMDeals.Code,FORMAT(CRMDeals.OpenDate, 'dd/MM/yyyy') AS OpenDateString,FORMAT(CRMDeals.CloseDate, 'dd/MM/yyyy') AS CloseDateString,
FORMAT(CRMDeals.ExpectedCloseDate, 'dd/MM/yyyy') AS ExpectedCloseDateString,CRMDealTypes.Name as DealTypeName,GENCompanies.Name As CompanyName,
GENStatus.Name as StatusName,CRMSources.Name As SourceName,GENListValues.Name as PriortyName
From CRMDeals left join
CRMDealTypes ON CRMDeals.DealTypeId=CRMDealTypes.Id left join
GENCompanies ON CRMDeals.CompanyId=GENCompanies.Id left join

GENStatus ON CRMDeals.StatusId=GENStatus.Id left join
CRMSources ON CRMDeals.SourceId=CRMSources.Id left join
GENListValues ON CRMDeals.PriortyId=GENListValues.Id 
Where CRMDeals.ContactId=@ContactId


exec SP_GetAllChatMessages @POPId,@ContactId




Select Items_Generic.Id,Items_Generic.ItemId,GENItems.Name As ItemName,GENItems.CategoryName,Items_Generic.Closed,
FORMAT(GENItems.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,Items_Generic.Description, GENItems.TypeId As ItemTypeId
From  Items_Generic left Join
GENItems ON Items_Generic.ItemId=GENItems.Id
where Items_Generic.ContactId=@ContactId

SELECT GENWikis.*,FORMAT(GENWikis.DateCreated, 'dd/MM/yyyy hh:mm tt') AS DateCreatedString,FORMAT(GENWikis.DateUpdated, 'dd/MM/yyyy hh:mm tt') AS DateUpdatedString, 
GENWikiCategories.Name AS CategoryName, GENWikiCategories.Name AS WikiCatName,
GENContacts.Name AS ContactName, AspNetUsers.Name As LastUpdatedByName FROM GENWikis
LEFT JOIN GENWikiCategories ON GENWikis.WikiCategoryId = GENWikiCategories.Id
LEFT JOIN AspNetUsers ON GENWikis.LastUpdatedById = AspNetUsers.Id
LEFT JOIN GENContacts ON GENWikis.ContactId= GENContacts.Id
Where GENWikis.ContactId = @ContactId




SELECT GENWikis.Id ,P.Name as ParentName ,GENWikiCategories.Name AS WikiCategoryName, GENWikiCategories.Id As WikiCategoryId,GENWikiCategories.ParentId As ParentId ,
GENWikis.Description,GENWikis.ContactId,GENWikis.valueId1,GENWikis.valueId2,GENListValues.Name As ValueId1Name,Lv2.Name AS ValueId2Name
FROM GENWikis
LEFT JOIN GENWikiCategories ON GENWikis.WikiCategoryId = GENWikiCategories.Id  left join
GENWikiCategories P ON GENWikiCategories.ParentId=p.ID left join 
GENListValues ON GENWikis.valueId1 = GENListValues.Id left join 
GENListValues Lv2 ON GENWikis.valueId2 = Lv2.Id
Where GENWikis.ContactId = @ContactId
GO
