CREATE Proc [dbo].[SP_SelectContactClassroom_ByCourseId] (@CourseId bigint)
as
begin
select Distinct GENClassroom_GENContact.Id, GENContacts.Name,GENContacts.Code,GENContacts.DefaultPhone,GENClassrooms.Name As ClassRoomName,GENClassrooms.Code As ClassRoomCode,GENClassrooms.FromDateTime,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS StartFrom,
