/****** Object:  StoredProcedure [dbo].[SP_SelectContactTab_Talent]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_SelectContactTab_Talent] (@TalentId bigint)
as
begin
select GENContact_Talent.*,GENContacts.Name, CASE
    WHEN GENContacts.Image is null THEN '/Content/images/User-Avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString
	,FORMAT(GENContact_Talent.EndDate, 'dd/MM/yyyy') AS EndDateString,GENContact_Talent.BookingTypeId,GENContact_Talent.PaymentTypeId,
	 (CASE WHEN dbo.GENContact_Talent.PaymentTypeId = 0 THEN N'Paied' ELSE 
						 CASE WHEN dbo.GENContact_Talent.PaymentTypeId = 1 THEN N'NotPaid' ELSE CASE WHEN dbo.GENContact_Talent.PaymentTypeId = 2 THEN N'Returned' ELSE N'' END END END) AS PaymentType,

						 (CASE WHEN dbo.GENContact_Talent.BookingTypeId = 0 THEN N'Requested' WHEN dbo.GENContact_Talent.BookingTypeId = 1 THEN N'Confirmed'  WHEN dbo.GENContact_Talent.BookingTypeId = 2 THEN N'Rejected'  WHEN dbo.GENContact_Talent.BookingTypeId = 3 THEN N'Blocked'
						 WHEN dbo.GENContact_Talent.BookingTypeId = 4 THEN N'Canceled' WHEN dbo.GENContact_Talent.BookingTypeId = 5 THEN N'Waiting'
						 WHEN dbo.GENContact_Talent.BookingTypeId = 6 THEN N'Added'
						  ELSE N'' END) AS BookingType,GENContact_Talent.Description
from  GENContact_Talent left join
	GENContacts ON GENContact_Talent.ContactId=GENContacts.Id  
	Where GENContact_Talent.TalentId  = @TalentId
End
GO
