CREATE proc [dbo].[SP_SelectCountRate] (@EntityId bigint,@BaseEntityId bigint,@EntityId2 bigint = null)
as
begin
select GENRatings.EntityId,count(GENRatings.Rating) AS CountRate,COUNT(GENRatings.Comment) AS CountReview
from 
GENRatings 
where GENRatings.EntityId=@EntityId and GENRatings.BaseEntityId=@BaseEntityId and (@EntityId2 is null and EntityId2 is null or EntityId2 = @EntityId2)
group by GENRatings.EntityId

end
