/****** Object:  StoredProcedure [dbo].[Sp_SelectCourse_ByCatId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Sp_SelectCourse_ByCatId]  (@CatId bigint,@langCode nvarchar(500))
AS 
Begin
 SELECT distinct dbo.GENTypes.Id, 
dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Name',@langCode) as Name, 
                         dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'Description',@langCode) as Description,
						 dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'RichContent',@langCode) as RichContent,
       --                  dbo.GENTypes.DisplayOrdering, dbo.fn_Type_Translate_ByKeyandId(dbo.GENTypes.Id,'String1',@langCode)   as String1,
						 --dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String2',@langCode) as String2,
						 --dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String3',@langCode) as String3,
						 --dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String4',@langCode) as String4, 
       --                  dbo.fn_Type_Translate_ByKeyandId( dbo.GENTypes.Id,'String5',@langCode) as String5,
						 dbo.GENTypes.Int1, dbo.GENTypes.Int1 as [Hour],dbo.GENTypes.Int2,
						 dbo.GENTypes.Int2 AS [Subject],
						 --dbo.GENTypes.Int3,
						 --dbo.GENTypes.Int4, dbo.GENTypes.Int5, dbo.GENTypes.Long1,
						 --dbo.GENTypes.Long2, dbo.GENTypes.Long3, dbo.GENTypes.Long4, 
       --                  dbo.GENTypes.Long5, dbo.GENTypes.Float1, dbo.GENTypes.Float2, dbo.GENTypes.Float3,
						 --dbo.GENTypes.Float4, dbo.GENTypes.Float5, dbo.GENTypes.Decimal1, 
						 --dbo.GENTypes.Decimal2, dbo.GENTypes.Decimal3, 
       --                  dbo.GENTypes.Decimal4, dbo.GENTypes.Decimal5, dbo.GENTypes.Bool1,
						 --dbo.GENTypes.Bool2, 
						 --dbo.GENTypes.Bool3, dbo.GENTypes.Bool4, dbo.GENTypes.Bool5,
						 FORMAT(dbo.GENTypes.Date1, 'dd/MM/yyyy') AS DateFromString
						 , FORMAT(dbo.GENTypes.Date2, 'dd/MM/yyyy') AS DateToString,
                         dbo.GENTypes.IsActive, dbo.GENTypes.IsPublish,
						 dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image],
						  dbo.fn_GetPriceString_ById(28,dbo.GENTypes.Id,@langCode,0) as PriceString,DisplayOrdering
FROM  GENTypes
inner join CourseCategories on GENTypes.Id = CourseCategories.CourseId
WHERE CourseCategories.CategoryId = @CatId and GENTypes.IsActive=1 and GENTypes.IsPublish=1 and IsDeleted=0

order by DisplayOrdering 
end
GO
