/****** Object:  StoredProcedure [dbo].[SP_SelectCourses_byCatId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectCourses_byCatId]  (@CatId bigint)
AS
Begin
select GENTypes.Id ,GENTypes.Name  from GENTypes inner join 
CourseCategories ON GENTypes.Id=CourseCategories.CourseId
where CourseCategories.CategoryId=@CatId and GENTypes.IsActive =1 and GENTypes.IsDeleted=0 
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectCourses_ByExamId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectCourses_ByExamId] (@ExamId bigint)
as
begin
select Distinct GENTypes.Name As CourseName,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString,
GENClassrooms.Name As ClassroomName
FROM            GENTypes LEFT JOIN
                GENExam_GENType ON GENTypes.Id = GENExam_GENType.CourseId left join 
				GENClassrooms ON GENTypes.Id = GENClassrooms.CourseId
where GENClassrooms.ExamId=@ExamId

End
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectCourses_byQuestionId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_SelectCourses_byQuestionId] (@QuestionId bigint)
AS
Begin
select Course_Question.Id,GENTypes.Id AS  CourseId,GENTypes.Name AS CourseName,GENItems.Id as SessionId,GENItems.Name AS SessionName
From Course_Question  left join 
GENTypes ON Course_Question.CourseId=GENTypes.Id left join
GENItems ON Course_Question.SessionId=GENItems.Id
where Course_Question.QuestionId=@QuestionId and GENTypes.IsActive=1
End
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectCourses_byTalentBuilderId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectCourses_byTalentBuilderId] (@TalentBuilderId bigint) 
AS
Begin
select GENTalents_Generic.id AS Id2,GENTypes.Name AS EntityName,GENTalents_Generic.EntityId AS EntityId,'GENType' AS BaseEntityName,GENTalents_Generic.BaseEntityId,GENTalents_Generic.DisplayOrder,
GENTalents_Generic.PassScore,GENTalents_Generic.Mandatory,GENTalents_Generic.DurationDays,GENTalents_Generic.PostCourseBreakInDays,GENTalents_Generic.TabAppearanceType,
(CASE WHEN dbo.GENTalents_Generic.TabAppearanceType = 0 THEN N'Text' WHEN dbo.GENTalents_Generic.TabAppearanceType = 1 THEN N'ImageText' 
WHEN dbo.GENTalents_Generic.TabAppearanceType = 2 THEN N'BackgroundText' WHEN dbo.GENTalents_Generic.TabAppearanceType = 3 THEN N'VideoText' 
WHEN dbo.GENTalents_Generic.TabAppearanceType = 4 THEN N'BackgroundImageText'  WHEN dbo.GENTalents_Generic.TabAppearanceType = 5 THEN N'BackgroundVideoText' 
ELSE N'' END) AS TabAppearanceTypeName
from  GENTalents_Generic inner join 
GENTypes ON GENTalents_Generic.EntityId=GENTypes.Id and GENTalents_Generic.BaseEntityId=28 
WHERE GENTalents_Generic.TalentBuilderId=@TalentBuilderId

END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectCourses_ByTalentId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



Create Proc [dbo].[SP_SelectCourses_ByTalentId] (@TalentId bigint)
AS
Begin
Select GENTypes.Name ,GENTypes.Id
From GENTalents_Generic left join 
GENTypes ON GENTalents_Generic.EntityId =GENTypes.Id and GENTalents_Generic.BaseEntityId=28
Where GENTalents_Generic.TalentId =@TalentId  
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectCoursesContact_ByContactId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectCoursesContact_ByContactId] (@ContactId bigint)
as
begin
select GENExamAnswerHeaders.CourseName,FORMAT(GENExamAnswerHeaders.StartDateTime, 'dd/MM/yyyy hh:mm tt') AS StartDateTimeString,
GENExamAnswerHeaders.EndtDateTime,FORMAT(GENExamAnswerHeaders.EndtDateTime, 'dd/MM/yyyy hh:mm tt') AS EndtDateTimeString,
GENExamAnswerHeaders.ClassroomName
FROM            GENTypes LEFT JOIN
                GENExamAnswerHeaders ON GENTypes.Id = GENExamAnswerHeaders.CourseId
			

where GENExamAnswerHeaders.StudentId=@ContactId
End
