/****** Object:  StoredProcedure [dbo].[SP_SelectCoursesTalent_ByTalentId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectCoursesTalent_ByTalentId] (@TalentId bigint) 
AS
Begin
select GENTalents_Generic.Id AS Id2,GENTalents_Generic.Id,GENTypes.Code,GENTypes.Name AS EntityName,GENTalents_Generic.EntityId AS EntityId,'GENType' AS BaseEntityName,GENTalents_Generic.BaseEntityId,GENTalents_Generic.DisplayOrder,
GENTalents_Generic.PassScore,GENTalents_Generic.Mandatory,GENTalents_Generic.DurationDays,GENTalents_Generic.PostCourseBreakInDays,GENTalents_Generic.TabAppearanceType,
(CASE WHEN dbo.GENTalents_Generic.TabAppearanceType = 0 THEN N'Text' WHEN dbo.GENTalents_Generic.TabAppearanceType = 1 THEN N'ImageText' 
WHEN dbo.GENTalents_Generic.TabAppearanceType = 2 THEN N'BackgroundText' WHEN dbo.GENTalents_Generic.TabAppearanceType = 3 THEN N'VideoText' 
WHEN dbo.GENTalents_Generic.TabAppearanceType = 4 THEN N'BackgroundImageText'  WHEN dbo.GENTalents_Generic.TabAppearanceType = 5 THEN N'BackgroundVideoText' 
ELSE N'' END) AS TabAppearanceTypeName,GENClassrooms.Id AS VcrId,GENClassrooms.Name AS VcrName, ''  AS CatName
--GENTypeCategories.Name AS CatName
from  GENTalents_Generic inner join 
GENTypes ON GENTalents_Generic.EntityId=GENTypes.Id and GENTalents_Generic.BaseEntityId=28  left join 
--CourseCategories ON GENTypes.Id=CourseCategories.CourseId   left join 
--GENTypeCategories ON CourseCategories.CategoryId=GENTypeCategories.Id   left join 
GENClassrooms ON GENTalents_Generic.VCRId=GENClassrooms.Id
WHERE GENTalents_Generic.TalentId=@TalentId
order by DisplayOrder
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectCRMTicketById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
