      ,'' as [NextActionColor]
      ,'' as [PreviousActionColor]
      ,'' as [CRMTicketId]
      ,'' as [FieldName]
      ,'' as [LastUpdatedByName]
	  from AchievementsOpenBals where 1 = 2
--select AllActivitiesWithDetails.* from AllActivitiesWithDetails
--WHERE BaseEntityId = @BaseEntityId AND EntityId = @TicketId 
--order by ActionDate desc

SELECT [dbo].[Employee_View].* FROM [dbo].[Employee_View]
INNER JOIN CRMTIckets ON CRMTIckets.EmployeeId = [Employee_View].Id
 WHERE CRMTIckets.Id = @TicketId

SELECT TOP(1) GENStatus.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
LEFT JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
LEFT JOIN GENStyles ON GENStatus.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @TicketId
ORDER BY [dbo].[GENProcesses].Id Desc

SELECT distinct NextStat.*,GENStyles.Name AS IconName, GENStyles.StyleValue AS IconStyle FROM [dbo].[GENProcesses]
inner JOIN GENStatus ON [dbo].[GENProcesses].ProcessId = GENStatus.Id
inner JOIN [dbo].[GENNextStatus] ON GENStatus.Id = [dbo].[GENNextStatus].CurrentStatusId
LEFT JOIN GENStatus NextStat ON NextStat.Id = [dbo].[GENNextStatus].NextStatusId
LEFT JOIN GENStyles ON NextStat.IconId = GENStyles.Id
WHERE [dbo].[GENProcesses].BaseEntityId = @BaseEntityId AND [dbo].[GENProcesses].EntityId = @TicketId
--ORDER BY [dbo].[GENNextStatus].Id Desc

exec SP_CRMTicket_GetRelatedTicketById @TicketId

exec SP_AllRelatedTicketByIdUp @TicketId

SELECT GENEntityClassifications.*,GENClassifications.Name As ClassificationName
   FROM GENEntityClassifications 
   LEFT JOIN GENClassifications ON GENEntityClassifications.ClassificationId = GENClassifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @TicketId

SELECT GENEntitySpecifications.*,GENSpecifications.Name AS SpecificationName,GENUnits.Name As UnitName
   FROM GENEntitySpecifications left join
   GENSpecifications ON GENEntitySpecifications.SpecificationId=GENSpecifications.id left join
   GENUnits ON GENEntitySpecifications.UnitId=GENUnits.id
 WHERE BaseEntityId = @BaseEntityId AND EntityId = @TicketId


 SELECT GENPointers.*
   FROM GENPointers 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @TicketId
