/****** Object:  StoredProcedure [dbo].[SP_SelectDatatoRepeated_Students]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE Proc  [dbo].[SP_SelectDatatoRepeated_Students]  (@StudentId bigint,@ClassroomId bigint)
AS 
Begin
select FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy') AS FromDateTimeString,
FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy') AS ToDateTimeString
from
GENClassroom_GENContact  inner join 
GENClassrooms ON GENClassroom_GENContact.ClassroomId=GENClassrooms.Id inner join 
GENTypes ON GENClassrooms.CourseId=GENTypes.Id
where 
GENClassroom_GENContact.StudentId = @StudentId and GENClassroom_GENContact.ClassroomId <> @ClassroomId and (dbo.AttendanceCall(GENClassroom_GENContact.StudentId,GENClassrooms.Id) >= GENClassrooms.Int4)

END
GO
