Create PROCEDURE [dbo].[SP_SelectEmogisByCommentId]
@Id INT 

AS
BEGIN

	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT COUNT(EmogyUserReplies.CommentId) as EmogyCount
	from EmogyUserReplies
	where EmogyUserReplies.CommentId=@Id
	group by (EmogyUserReplies.EmogyId)
	order by COUNT(EmogyUserReplies.CommentId) desc
	
END
GO
