/****** Object:  StoredProcedure [dbo].[SP_SelectEmployeeByEmail]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectEmployeeByEmail] (@Email nvarchar(250))
as
SELECT    Top 1 dbo.GENEmployees.*
FROM            dbo.GENEmployees RIGHT OUTER JOIN
                         dbo.AspNetUsers ON dbo.GENEmployees.UserId = dbo.AspNetUsers.Id
WHERE        (dbo.AspNetUsers.UserName = @Email or dbo.GENEmployees.Email =  @Email or dbo.GENEmployees.UserNameMail =  @Email) and dbo.GENEmployees.UserId is not null
GO
