CREATE Proc [dbo].[SP_SelectEmployeeClassroom_ByEmpId] (@empId bigint)
as
begin
select Distinct  GENClassrooms.Id,GENClassrooms.Name as ClassroomName,GENClassrooms.Code AS ClassroomCode, (CASE WHEN GENClassrooms.ClassRoomStatus = 0 THEN 'Started' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 1 THEN 'Dropped' ELSE CASE WHEN GENClassrooms.ClassRoomStatus = 2 THEN 'Done' ELSE '' END END END) AS ClassRoomStatusString ,GENClassrooms.FromDateTime,FORMAT(GENClassrooms.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString,COUNT(GENClassroom_GENContact.StudentId)  AS StudentCount, 
GENClassrooms.ToDateTime, FORMAT(GENClassrooms.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString
FROM            GENClassrooms LEFT JOIN
               GENClassroom_GENContact ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId
where GENClassrooms.InstructorId=@empId
GROUP BY   GENClassrooms.Id,GENClassrooms.Name,GENClassrooms.Code,GENClassrooms.ClassRoomStatus,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
End
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectEmployeeContactss_ByEmpId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectEmployeeContactss_ByEmpId] (@empId bigint)
as
begin

SELECT DISTINCT GENContacts.Id AS StudentId,GENContacts.Name AS StudentName,GENTypes.Name As CourseName,GENClassrooms.Name AS ClassroomName,
GENExamAnswerHeaders.TotalExamScore,GENExamAnswerHeaders.ExamName,GENClassrooms.Id,GENExamAnswerHeaders.ExamId,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
	FROM GENContacts 
	LEFT JOIN GENClassroom_GENContact ON GENContacts.Id = GENClassroom_GENContact.StudentId
	LEFT JOIN GENClassrooms ON GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
	LEFT JOIN GENTypes ON GENClassrooms.courseId = GENTypes.Id 
	left join GENExam_GENType ON GENTypes.Id =GENExam_GENType.CourseId
	LEFT Join GENExamAnswerHeaders ON  GENExamAnswerHeaders.StudentId=GENContacts.ID and GENExamAnswerHeaders.InstructorId = @empId
	LEFT JOIN GENPollCategories ON GENExamAnswerHeaders.ExamId = GENPollCategories.Id
	WHERE GENClassrooms.InstructorId = @empId AND ((GENPollCategories.ExamType <> 6 AND  GENPollCategories.ExamType <> 7) OR GENPollCategories.ExamType IS NULL)
	GROUP BY GENContacts.Id ,GENContacts.Name,GENTypes.Name,GENClassrooms.Name,
GENExamAnswerHeaders.TotalExamScore,GENExamAnswerHeaders.ExamName,GENClassrooms.Id,GENExamAnswerHeaders.ExamId,GENClassrooms.FromDateTime,GENClassrooms.ToDateTime
End	
GO
