CREATE Proc [dbo].[SP_SelectEmployeeCourses_ByEmpId] (@empId bigint)
as
begin
select  Distinct GENTypes.Id,GENTypes.Code As CourseCode, GENTypes.Name As CourseName,GENTypes.Int1 AS CourseTimeHours,GENTypes.Int2 AS CourseTimeMinutes,GENTypes.DisplayOrdering,GENTypes.IsActive,
COUNT(GENItems.Id)  AS NumberOfSessions
FROM            GENClassrooms LEFT JOIN
               GENTypes ON GENClassrooms.CourseId=GENTypes.Id left join 
			   GENItems ON GENTypes.Id=GENItems.TypeId
where GENClassrooms.InstructorId=@empId
group by  GENTypes.Id,GENTypes.Code, GENTypes.Name ,GENTypes.Int1,GENTypes.Int2,GENTypes.DisplayOrdering,GENTypes.IsActive


End
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectEmployeeExam_ByEmpId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectEmployeeExam_ByEmpId] (@empId bigint)
as
begin
select GENPollCategories.Name AS ExamName,(CASE WHEN GENPollCategories.ExamType = 0 THEN 'FinalExam' ELSE CASE WHEN GENPollCategories.ExamType = 1 THEN 'MidExam' ELSE CASE WHEN GENPollCategories.ExamType = 2 THEN 'Quiz' ELSE CASE WHEN GENPollCategories.ExamType = 3 THEN 'Exercise' 
ELSE CASE WHEN GENPollCategories.ExamType = 4 THEN 'Assessment' ELSE CASE WHEN GENPollCategories.ExamType = 5 THEN 'Assignment' 
ELSE CASE WHEN GENPollCategories.ExamType = 6 THEN 'Questionaire' ELSE CASE WHEN GENPollCategories.ExamType = 7 THEN 'Poll' 
 ELSE '' END END END END END END END END) AS ExamTypeString,GENPollCategories.Time AS ExamTime,GENPollCategories.Weight,GENPollCategories.ActucalScore
FROM           GENPollCategories  LEFT JOIN
              GENClassrooms  ON GENPollCategories.Id=GENClassrooms.ExamId
where GENClassrooms.InstructorId=@empId

UNION 

select  GENPollCategories.Name AS ExamName,(CASE WHEN GENPollCategories.ExamType = 0 THEN 'FinalExam' ELSE CASE WHEN GENPollCategories.ExamType = 1 THEN 'MidExam' ELSE CASE WHEN GENPollCategories.ExamType = 2 THEN 'Quiz' ELSE CASE WHEN GENPollCategories.ExamType = 3 THEN 'Exercise' 
ELSE CASE WHEN GENPollCategories.ExamType = 4 THEN 'Assessment' ELSE CASE WHEN GENPollCategories.ExamType = 5 THEN 'Assignment' 
ELSE CASE WHEN GENPollCategories.ExamType = 6 THEN 'Questionaire' ELSE CASE WHEN GENPollCategories.ExamType = 7 THEN 'Poll' 
 ELSE '' END END END END END END END END) AS ExamTypeString,GENPollCategories.Time AS ExamTime,GENPollCategories.Weight,GENPollCategories.ActucalScore
FROM            GENPollCategories LEFT JOIN
               GENExam_GENClassroom ON GENPollCategories.Id=GENExam_GENClassroom.ExamId  LEFT JOIN
			   GENClassrooms  ON GENExam_GENClassroom.ClassroomId=GENClassrooms.Id
	
where GENClassrooms.InstructorId=@empId

End
GO
