/****** Object:  StoredProcedure [dbo].[SP_SelectExams_ByTalentId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create Proc [dbo].[SP_SelectExams_ByTalentId] (@TalentId bigint )
as
begin
  SELECT GENExam_GENTalent.*,GENExam_GENTalent.Id AS Id2,GENTalents.Name As TalentName,Format(GENExam_GENTalent.DisplayDateTime,'dd/MM/yyyy hh:mm tt') AS DisplayDateTimeString,GENPollCategories.Name AS ExamName,GENPollCategories.ExamType,
  (case when dbo.GENPollCategories.ExamType = 0 then N'FinalExam' when dbo.GENPollCategories.ExamType = 1 then N'MidExam'
						 when dbo.GENPollCategories.ExamType = 2 then N'Quiz' when dbo.GENPollCategories.ExamType = 3 then N'Exercise' 
						 when dbo.GENPollCategories.ExamType = 4 then N'Assessment' when dbo.GENPollCategories.ExamType = 5 then N'Assignment' 
						 when dbo.GENPollCategories.ExamType = 6 then N'Questionaire'  when dbo.GENPollCategories.ExamType = 7 then N'Poll'
						 when dbo.GENPollCategories.ExamType = 8 then N'Other' when dbo.GENPollCategories.ExamType = 9 then N'PreAssessment' when dbo.GENPollCategories.ExamType = 10 then N'PostAssessment'
						 when dbo.GENPollCategories.ExamType = 11 then N'TrainerAssessment' when dbo.GENPollCategories.ExamType = 12 then N'VCRAssessment' end) as ExamTypeName
   FROM GENExam_GENTalent left join
   GENTalents ON GENExam_GENTalent.TalentId = GENTalents.Id left join
   GENPollCategories ON GENExam_GENTalent.ExamId = GENPollCategories.Id
   WHERE  GENExam_GENTalent.TalentId = @TalentId
End
GO
