    -- Insert statements for procedure here
SELECT           dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as VideoURL, 
   dbo.GENWikis.AudioURL, dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'RichContent',@langCode) as RichContent,
   dbo.GENWikis.TargetUrl,
   --dbo.GENWikis.WikiCategoryId,
   --dbo.GENWikis.Code,
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Name',@langCode) as Name, 
                         dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description',@langCode) as Description,
						 --dbo.GENWikis.ColorCode,
						 --dbo.GENWikis.IsCheckedOut, dbo.GENWikis.DateCreated, dbo.GENWikis.DateUpdated, dbo.GENWikis.CheckinDate, 
						 --dbo.GENWikis.CheckoutDate, dbo.GENWikis.Timeout, 
                         dbo.GENWikis.DisplayOrdering,
						 --dbo.GENWikis.CreatedById, 
						 dbo.GENWikis.LastUpdatedById, dbo.GENWikis.CheckoutBy,dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String1',@langCode)   as String,
						 --dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String2',@langCode) as String2, 
						 --dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String3',@langCode) as String3, 
						 --dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String4',@langCode) as String4, 
       --                  dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String5',@langCode) as String5,
						 --dbo.GENWikis.Int1, dbo.GENWikis.Int2, dbo.GENWikis.Int3, dbo.GENWikis.Int4, dbo.GENWikis.Int5,
						 --dbo.GENWikis.Long1, dbo.GENWikis.Long2, dbo.GENWikis.Long3, dbo.GENWikis.Long4, 
       --                  dbo.GENWikis.Long5, dbo.GENWikis.Float1, dbo.GENWikis.Float2, dbo.GENWikis.Float3,
						 --dbo.GENWikis.Float4, dbo.GENWikis.Float5, dbo.GENWikis.Decimal1, dbo.GENWikis.Decimal2, dbo.GENWikis.Decimal3, 
       --                  dbo.GENWikis.Decimal4, dbo.GENWikis.Decimal5, dbo.GENWikis.Bool1, dbo.GENWikis.Bool2, dbo.GENWikis.Bool3, 
						-- dbo.GENWikis.Bool4, dbo.GENWikis.Bool5,
						FORMAT(dbo.GENWikis.Date1, 'dd/MM/yyyy hh:mm tt') AS Date1String,	FORMAT(dbo.GENWikis.Date1, 'yyyy') AS [Year],
						 --dbo.GENWikis.Date2, 
       --                  dbo.GENWikis.Date3, dbo.GENWikis.Date4, dbo.GENWikis.Date5, dbo.GENWikis.ValueId1,
						 --dbo.GENWikis.ValueId2, dbo.GENWikis.ValueId3, dbo.GENWikis.ValueId4, dbo.GENWikis.ValueId5, 
						 --dbo.GENWikis.IconId, 
                         (CASE WHEN (dbo.GENWikis.Image IS NULL OR dbo.GENWikis.Image = '') THEN '/assets/images/Default.png' ELSE dbo.GENWikis.Image END) AS Image,
						 dbo.GENWikis.IsActive,
						 dbo.GENWikis.IsPublish
						 --dbo.GENWikis.ExpectedCheckoutDate, 
						 --dbo.GENWikis.IsMenu, 
						 --dbo.fn_FirstFile_BaseEntityEntityId(6, dbo.GENWikis.Id) AS [File]
                         --dbo.GENListValues.Id AS ListValueId, dbo.GENListValues.Name AS ListValueName, dbo.GENListValues.DisplayOrdering AS ListValueDusplayOrder
FROM            dbo.GENWikis
                        --LEFT OUTER JOIN
                        -- dbo.GENListValues ON dbo.GENWikis.ValueId1 = dbo.GENListValues.Id
WHERE        (dbo.GENWikis.WikiCategoryId = @CategoryId) AND (dbo.GENWikis.IsPublish = 1) AND (dbo.GENWikis.IsActive = 1)
ORDER BY dbo.GENWikis.DisplayOrdering 
end
GO
