CREATE Proc [dbo].[SP_SelectItemDeal_ByItemId] (@ItemId bigint)
as
begin
select dbo.CRMDeals.Amount,Count(dbo.CRMDeals.Amount) as AmountCount,dbo.DealInfoes.ResponsiblePersonName,dbo.DealInfoes.ProcessName,dbo.DealInfoes.valueId1tName
,DATEDIFF(DAY, dbo.CRMDeals.DateCreated, GETDATE()) AS LifeDateNumber,dbo.DealInfoes.OpenDateString, dbo.CRMDeals.Probability,dbo.DealInfoes.PriortyName,
FORMAT(dbo.DealInfoes.LastActivityDate, 'dd/MM/yyyy hh:mm tt') AS DealActivityString, dbo.DealInfoes.ContactName,dbo.CRMDeals.DefaultPhone,dbo.CRMDeals.DefaultEmail,dbo.DealInfoes.CompanyName,
 dbo.DealInfoes.ExpectedCloseDateString
FROM             dbo.CRMDeals LEFT JOIN
                dbo.CRMDealItems ON dbo.CRMDeals.Id = dbo.CRMDealItems.DealId LEFT JOIN
				 dbo.DealInfoes ON dbo.CRMDeals.Id = dbo.DealInfoes.DealId 

where CRMDealItems.ItemId=@ItemId
GROUP BY  dbo.CRMDeals.Amount,dbo.DealInfoes.ResponsiblePersonName,dbo.DealInfoes.ProcessName,dbo.DealInfoes.valueId1tName,dbo.CRMDeals.DateCreated,
dbo.DealInfoes.OpenDateString,dbo.CRMDeals.Probability,dbo.DealInfoes.PriortyName,dbo.DealInfoes.LastActivityDate,dbo.DealInfoes.ContactName,
dbo.CRMDeals.DefaultPhone,dbo.CRMDeals.DefaultEmail,dbo.DealInfoes.CompanyName, dbo.DealInfoes.ExpectedCloseDateString
End
