/****** Object:  StoredProcedure [dbo].[SP_SelectLastPoll]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 13/09/2020
-- Description:	Select Last Poll
-- =============================================
CREATE PROCEDURE [dbo].[SP_SelectLastPoll] @LangCode NVARCHAR(20)
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
    -- Insert statements for procedure here
	SELECT DISTINCT 
                         dbo.GENPolls.Id AS QuestionId, dbo.PollCategoryandPolls.PollCategoryId AS ExamId, PollCategory.Name AS ExamName, dbo.GENPolls.Question, dbo.GENPolls.DisplayOrdering, dbo.GENPolls.QuestionType, 
                         dbo.GENPolls.Weight, dbo.GENPolls.MinAnsNumber, dbo.GENPolls.MaxAnsNumber, dbo.GENPollAnswers.Answer, dbo.GENPollAnswers.IsCorrect, dbo.GENPollAnswers.DisplayOrdering AS AnswerDisplayOrder, 
                         dbo.GENPollAnswers.Id AS AnswerId, dbo.PollCategoryandPolls.QdOrder, dbo.GENPolls.Image AS QuestionImage, dbo.GENVideos.AzureUri AS QuestionVideo, dbo.GENVideos.Id AS QuestionVideoId,
						 dbo.GENPolls.Audio AS QuestionAudio, GENPollAnswers.Image AS AnswerImage
FROM      dbo.GENPolls      
LEFT JOIN dbo.GENPollAnswers  ON dbo.GENPollAnswers.PollId = dbo.GENPolls.Id 
LEFT JOIN dbo.GENVideos ON dbo.GENVideos.EntityId = dbo.GENPolls.Id AND dbo.GENVideos.BaseEntityId = 83
LEFT JOIN dbo.PollCategoryandPolls ON dbo.GENPolls.Id = dbo.PollCategoryandPolls.PollId
LEFT JOIN ( SELECT Top 1 * FROM  dbo.GENPollCategories WHERE GENPollCategories.ExamType = 7 AND GENPollCategories.IsActive = 1 ORDER BY Id DESC) 
PollCategory ON PollCategory.Id = dbo.PollCategoryandPolls.PollCategoryId
LEFT JOIN GENListValues ON PollCategory.LanguageId = GENListValues.Id
	WHERE  dbo.GENPolls.IsActive=1 AND PollCategory.ExamType = 7 AND (GENListValues.ShortCode = @LangCode OR @LangCode IS NULL OR @LangCode = 'en' OR GENListValues.ShortCode = 'all')
						 ORDER BY dbo.PollCategoryandPolls.QdOrder
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectLastSurvey]    Script Date: 7/1/2026 10:45:04 AM ******/
