/****** Object:  StoredProcedure [dbo].[SP_SelectLatestFour_Wikis]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_SelectLatestFour_Wikis] 
	-- Add the parameters for the stored procedure here
	@CategoryId bigint,@langCode nvarchar(500)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
SELECT  TOP(4)         dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as VideoURL, 
   dbo.GENWikis.AudioURL, dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'RichContent',@langCode) as RichContent,
   dbo.GENWikis.TargetUrl,
   --dbo.GENWikis.WikiCategoryId,
   --dbo.GENWikis.Code,
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Name',@langCode) as Name, 
                         dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description',@langCode) as Description,
                         dbo.GENWikis.DisplayOrdering,
						 dbo.GENWikis.LastUpdatedById, dbo.GENWikis.CheckoutBy,dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String1',@langCode)   as String,
						FORMAT(dbo.GENWikis.Date1, 'dd/MM/yyyy hh:mm tt') AS Date1String,	FORMAT(dbo.GENWikis.Date1, 'yyyy') AS [Year],
                         (CASE WHEN (dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Image',@langCode) IS NULL OR dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Image',@langCode) = '') 
						 THEN '/assets/images/Default.png' ELSE dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Image',@langCode) END) AS Image,
						 dbo.GENWikis.IsActive,
						 dbo.GENWikis.IsPublish
FROM            dbo.GENWikis
WHERE        (dbo.GENWikis.WikiCategoryId = @CategoryId) AND (dbo.GENWikis.IsPublish = 1) AND (dbo.GENWikis.IsActive = 1) AND (dbo.GENWikis.IsDeleted = 0)
AND((dbo.fn_Wiki_Translate_ByKeyandId_If_LangIsEnOrFr(dbo.GENWikis.Id,'Name',@langCode) IS NOT NULL 
and dbo.fn_Wiki_Translate_ByKeyandId_If_LangIsEnOrFr(dbo.GENWikis.Id,'Name',@langCode) not in ('')) or (@langCode is null or @langCode = 'ar'))
ORDER BY dbo.GENWikis.Date1 desc
end
GO
