/****** Object:  StoredProcedure [dbo].[SP_SelectMyTeam]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectMyTeam] (@EmployeeId Bigint)

as
with empolyee_cte as (
Select Id,Name
,EmployeeId,
0 as Level_,
UserId,
IsActive

from GENEmployees
where Id = @EmployeeId

union all

select p1.Id,
p1.Name,
p1.EmployeeId,
Level_ + 1,
p1.UserId,
p1.IsActive
from empolyee_cte p2
inner join GENEmployees p1 on p1.EmployeeId =p2.Id	
where p2.IsActive=1
)
select * from empolyee_cte
GO
