/****** Object:  StoredProcedure [dbo].[SP_SelectPageOfPageById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_SelectPageOfPageById]
	-- Add the parameters for the stored procedure here
	@POPId BIGINT, @LangId BIGINT, @RoleId NVARCHAR(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENPageOfPages.[Id] ,GENPageOfPages.[Code] ,GENPageOfPages.[FirstCode] 
		,(CASE WHEN GENTranslate_BackendPage.Name IS NOT NULL THEN GENTranslate_BackendPage.Name ELSE GENPageOfPages.[Name] END) AS Name
		,(CASE WHEN GENTranslate_BackendPage.Name IS NOT NULL THEN GENTranslate_BackendPage.Name ELSE GENPageOfPages.[Name] END) AS DisplayName
		,GENPageOfPages.[Description] ,GENPageOfPages.[DateCreated] ,GENPageOfPages.[DateUpdated] ,GENPageOfPages.[CreatedById] ,GENPageOfPages.[LastUpdatedById]
		,GENPageOfPages.[IsUser] ,GENPageOfPages.[IsActive] ,GENPageOfPages.[IsPublish] ,GENPageOfPages.[IsFPSubsidiaries] ,GENPageOfPages.[IsSPSubsidiaries]
		,GENPageOfPages.[IsSearchBar] ,GENPageOfPages.[IsReadOnly] ,GENPageOfPages.[IsCheckedout] ,GENPageOfPages.[IsActivityMenu] ,GENPageOfPages.[TimeoutCount]
		,GENPageOfPages.[StyleId] ,GENPageOfPages.[CreateType] ,GENPageOfPages.[popTypeId] ,GENPageOfPages.[GENListValuesTypeId] ,GENPageOfPages.[EntityId]
		,(CASE WHEN GENPageOfPages.[CategoryId] IS NOT NULL THEN GENPageOfPages.[CategoryId] ELSE 0 END) AS CategoryId ,GENPageOfPages.[BackendPageId] ,GENPageOfPages.[TypeStatusId] ,GENPageOfPages.[BaseTab_Id] ,GENPageOfPages.[BackgroundColor] 
		,GENPageOfPages.[OpenNewTab], GENStyles.StyleValue AS StyleName, BaseEntities.Name AS EntityName, GENBackendPages.BackendSectionId AS BackendSectionId
		,GENBackendPages.Name AS BackendPageName,GENBackendPages.BackgroundColor AS BackgroundColor,GENBackendPages.IconDisplayId AS IconDisplayId, GENBackendPages.URL AS Url
		,(CASE WHEN GENBackendPages.PaddingIconDisplay IS NOT NULL THEN GENBackendPages.PaddingIconDisplay ELSE 0 END) AS PaddingIconDisplay,(CASE WHEN GENBackendPages.Size IS NOT NULL THEN GENBackendPages.Size ELSE 0 END) AS Size, GENBackendPages.StyleId AS StyleId,GENBackendPages.TextAlignId AS TextAlignId
		,GENBackendPages.TextColor AS TextColor,(CASE WHEN  GENBackendPages.DisplayOrder IS NOT NULL THEN  GENBackendPages.DisplayOrder ELSE 0 END) AS DisplayOrder, BaseEntities.CategoryApiUrl AS ApiURL,GENTypeStatus.Name AS StatustypeName,
		Reports.RDLCName AS RDLCName, Reports.Name AS ReportName,GENPageOfPages.ReportId, GENPageOfPages.HTMLTemplateId,
		HTMLTemplates.Name AS TemplateName, CASE WHEN HTMLTemplates.Template IS NOT NULL THEN HTMLTemplates.Template ELSE 'Create' END AS Template,GENPageOfPages.isDataManger,
		GENPageOfPages.NumberGridRows,ShowButtonMail
	FROM GENPageOfPages 
	LEFT JOIN BaseEntities ON GENPageOfPages.EntityId = BaseEntities.Id
	LEFT JOIN GENBackendPages ON GENPageOfPages.BackendPageId = GENBackendPages.Id
	LEFT JOIN GENTypeStatus ON GENPageOfPages.TypeStatusId = GENTypeStatus.Id
	LEFT JOIN GENStyles ON GENPageOfPages.StyleId = GENStyles.Id
	LEFT JOIN Reports ON GENPageOfPages.ReportId = Reports.Id
	LEFT JOIN GENTranslate_BackendPage ON GENTranslate_BackendPage.[BackendPageId] = GENBackendPages.Id AND GENTranslate_BackendPage.[LangId] = @LangId
	LEFT JOIN HTMLTemplates ON GENPageOfPages.HTMLTemplateId = HTMLTemplates.Id
	WHERE GENPageOfPages.Id = @POPId

	SELECT PageOfPageRelations.[Id] ,PageOfPageRelations.[PageOfPageId] ,[SearchpopId] ,[FieldId] ,[ForeignKeyId] ,[ForeignKeyName] ,
	(CASE WHEN GENTranslate_PageOfPageRelation.Name IS NOT NULL THEN GENTranslate_PageOfPageRelation.Name ELSE PageOfPageRelations.[DisplayName] END) AS DisplayName,[FilterName] ,[EntityId] ,[DataName] ,[FieldName] ,[EntityName]
      ,[IsActive] ,[FieldCols] ,[SearchCols] ,[IsIndex] ,[IsPrimaryKey] ,[IsIdentity] ,[AllowEditing] ,[AllowFiltering] ,[IsTemplateColumn] ,[Visible] ,[Width]
      ,[TemplateID] ,[Format] ,[Field] ,[TextAlign] ,[Type] ,[DisplayOrder] ,[IsMandatory], (CASE WHEN FilterEntityId IS NOT NULL THEN FilterEntityId ELSE 0 END) AS FilterEntityId
      ,PageOfPageRelations.[EntityApi],BaseEntityRelations.[DBField],PageOfPageRelations.EntityIdString,PageOfPageRelations.EntityIdStringName, PageOfPageRelations.[DefaultValue],
	  IsMultiSelection,IsDataManager,AllowSorting,IsUnique,IsAutoGenerate,IsCuting
	   FROM PageOfPageRelations
	  LEFT JOIN GENTranslate_PageOfPageRelation ON GENTranslate_PageOfPageRelation.PageOfPageRelationId = PageOfPageRelations.Id AND 
	  GENTranslate_PageOfPageRelation.[LangId] =@LangId  left join
	  BaseEntityRelations ON PageOfPageRelations.FieldId=BaseEntityRelations.Id
	WHERE PageOfPageRelations.PageOfPageId = @POPId

	SELECT RelatedPageofPages.*,(CASE WHEN GENBackendPages.DisplayName IS NOT NULL THEN GENBackendPages.DisplayName ELSE GENPageOfPages.Name END) AS PageofPageName
	,BaseEntities.Name AS EntityName, REPLACE(GENBackendPages.URL,'Index/','') AS RelatedURL, REPLACE(BaseEntities.Url,'Index/','') AS EntityURL,
	(CASE WHEN [Type] = 1 THEN 'Redirect' ELSE CASE WHEN [Type] = 2 THEN 'QuickAdd' ELSE CASE WHEN [Type] = 3 THEN 'ConvertTo' ELSE '' END END END) AS TypeName,
	GENPageOfPages.HTMLTemplateId,
   CASE WHEN HTMLTemplates.Template IS NOT NULL THEN HTMLTemplates.Template ELSE 'Create' END AS Template
	FROM RelatedPageofPages
	LEFT JOIN GENPageOfPages ON RelatedPageofPages.PageOfPageId = GENPageOfPages.Id
	LEFT JOIN BaseEntities ON GENPageOfPages.EntityId = BaseEntities.Id
	LEFT JOIN HTMLTemplates ON GENPageOfPages.HTMLTemplateId = HTMLTemplates.Id
	LEFT JOIN GENBackendPages ON GENPageOfPages.BackendPageId = GENBackendPages.Id
	WHERE RelatedPageofPages.OriginalPageOfPageId = @POPId

	SELECT PageofPageReport_Role.*, AspNetRoles.Name AS IdentityRoleName, Reports.Name AS ReportName,Reports.RDLCName,Reports.SPName  FROM PageofPageReport_Role
	LEFT JOIN AspNetRoles ON PageofPageReport_Role.IdentityRoleId = AspNetRoles.Id
	LEFT JOIN Reports ON PageofPageReport_Role.PageOfPageReportId = Reports.Id
	WHERE PageofPageReport_Role.PageOfPageId = @POPId  AND PageofPageReport_Role.IdentityRoleId = @RoleId

	SELECT Authentications.*,AspNetRoles.Name AS IdentityRoleName, AccessCriterias.Name AS AccessCriteriaName FROM Authentications
	LEFT JOIN AccessCriterias ON Authentications.AccessCriteriaId = AccessCriterias.Id
	LEFT JOIN AspNetRoles ON Authentications.IdentityRoleId = AspNetRoles.Id
	LEFT JOIN GENBackendPages ON Authentications.BackendPageId = GENBackendPages.Id
	LEFT JOIN GENPageOfPages ON GENBackendPages.Id = GENPageOfPages.BackendPageId
	WHERE GENPageOfPages.Id = @POPId AND Authentications.IdentityRoleId = @RoleId

	SELECT PageOfPageField_Role.Id,PageOfPageField_Role.UserAuthentication,PageOfPageField_Role.DateCreated ,PageOfPageField_Role.DateUpdated
	,PageOfPageField_Role.PageOfPageFieldId ,PageOfPageField_Role.IdentityRoleId ,PageOfPageField_Role.CreatedById ,PageOfPageField_Role.LastUpdatedById
	,PageOfPageField_Role.FieldType
  FROM PageOfPageField_Role 
  LEFT JOIN PageOfPageRelations ON PageOfPageField_Role.PageOfPageFieldId = PageOfPageRelations.Id AND PageOfPageField_Role.FieldType = 1 AND PageOfPageRelations.IsActive = 1 --AND PageOfPageRelations.PageOfPageId = 49
  LEFT JOIN PageOfPageFeilds ON PageOfPageField_Role.PageOfPageFieldId = PageOfPageFeilds.Id AND PageOfPageField_Role.FieldType = 0 AND PageOfPageFeilds.IsActive = 1 --AND PageOfPageFeilds.PageOfPageId = 49
  LEFT JOIN GENPageOfPages ON (PageOfPageFeilds.PageOfPageId = GENPageOfPages.Id OR PageOfPageRelations.PageOfPageId = GENPageOfPages.Id)
  WHERE  PageOfPageField_Role.IdentityRoleId = @RoleId AND GENPageOfPages.Id = @POPId

  SELECT BaseTabGENPageOfPages.Id, (CASE WHEN Translate_BaseTabs.Name IS NOT NULL THEN Translate_BaseTabs.Name ELSE BaseTabGENPageOfPages.DisplayName END) AS DisplayName
	  ,BaseTabGENPageOfPages.BaseTabId, BaseTabGENPageOfPages.GENPageOfPagesId
      ,BaseTabGENPageOfPages.BaseEntityId, BaseTabGENPageOfPages.SearchPageId, BaseTabGENPageOfPages.IsIndex, BaseTabGENPageOfPages.ImageTypeId
      ,BaseTabGENPageOfPages.ReferPageofPageId, BaseTabGENPageOfPages.DisplayOrder, BaseTabGENPageOfPages.ReferPageofPageId AS RefrerPageofPageId
	  ,SearchPage.BackgroundColor AS Color, SearchPageStyle.StyleValue AS SearchPageIcon
	  ,(CASE WHEN BaseTabGENPageOfPages.BaseEntityId IS NOT NULL THEN BaseTabGENPageOfPages.BaseEntityId ELSE 0 END) AS EntityIdTo, SearchPage.Name AS SearchPageName
	  ,BaseTabs.IsActive,BaseTabs.IsPublish, BaseTabs.LastUpdatedById, BaseTabs.CreatedById, BaseTabs.DateUpdated, BaseTabs.DateCreated, BaseTabs.Description
	  ,BaseEntities.Name AS BaseEntityName, BaseTabs.Name,BasetabGENPageOfPagesRoles.RoleId,BasetabGENPageOfPagesRoles.RoleName
  FROM BaseTabGENPageOfPages
  LEFT JOIN BaseTabs ON BaseTabGENPageOfPages.BaseTabId = BaseTabs.Id
  LEFT JOIN BasetabGENPageOfPagesRoles ON BasetabGENPageOfPagesRoles.PageOfPagesBaseTabId = BaseTabGENPageOfPages.Id
  LEFT JOIN Translate_BaseTabs ON Translate_BaseTabs.PageOfPageBaseTabId = BaseTabGENPageOfPages.Id AND Translate_BaseTabs.[LangId] =@LangId
  LEFT JOIN GENPageOfPages SearchPage ON BaseTabGENPageOfPages.SearchPageId = SearchPage.Id
  LEFT JOIN GENStyles SearchPageStyle ON SearchPage.StyleId = SearchPageStyle.Id
  LEFT JOIN BaseEntities ON BaseTabGENPageOfPages.BaseEntityId = BaseEntities.Id
  WHERE BaseTabGENPageOfPages.GENPageOfPagesId = @POPId AND BasetabGENPageOfPagesRoles.RoleId = @RoleId
  order by BaseTabGENPageOfPages.DisplayOrder

  SELECT BasetabGENPageOfPages_Field.* FROM BasetabGENPageOfPages_Field
  LEFT JOIN BaseTabGENPageOfPages ON BasetabGENPageOfPages_Field.PageOfPagesBaseTabId = BaseTabGENPageOfPages.Id
  LEFT JOIN BasetabGENPageOfPagesRoles ON BasetabGENPageOfPagesRoles.PageOfPagesBaseTabId = BaseTabGENPageOfPages.Id
  WHERE BaseTabGENPageOfPages.GENPageOfPagesId = @POPId AND BasetabGENPageOfPagesRoles.RoleId = @RoleId

  SELECT PageOfPageFeilds.[Id], PageOfPageFeilds.[Value], PageOfPageFeilds.[FeildId], PageOfPageFeilds.[PageOfPageId], PageOfPageFeilds.[FilterValue]
      ,PageOfPageFeilds.[FilterName], (CASE WHEN GENTranslate_PageOfPageFeilds.Name IS NOT NULL THEN GENTranslate_PageOfPageFeilds.Name ELSE PageOfPageFeilds.[DisplayName] END) AS DisplayName
	  ,PageOfPageFeilds.[RegEx], PageOfPageFeilds.[RegExMessage], PageOfPageFeilds.[IsActive]
      ,PageOfPageFeilds.[IsIndex], PageOfPageFeilds.[IsPrimaryKey], PageOfPageFeilds.[IsIdentity], PageOfPageFeilds.[AllowEditing], PageOfPageFeilds.[IsTemplateColumn]
      ,PageOfPageFeilds.[AllowFiltering], PageOfPageFeilds.[Visible], PageOfPageFeilds.[Width], PageOfPageFeilds.[TemplateID], PageOfPageFeilds.[Format]
      ,PageOfPageFeilds.[Field], PageOfPageFeilds.[TextAlign], PageOfPageFeilds.[InputType], PageOfPageFeilds.[Type], PageOfPageFeilds.[DisplayOrder]
      ,PageOfPageFeilds.[Cols], PageOfPageFeilds.[DecimalTypeId], PageOfPageFeilds.[FilterEntityId], PageOfPageFeilds.[IsMandatory], PageOfPageFeilds.[IsImport]
      ,PageOfPageFeilds.[IsTranslate], BaseEntityFields.DBField,BaseEntityFields.Id AS BaseEntityField, BaseEntityFields.TypeListValueName AS DataType
	  ,GENPageOfPages.Name AS PageofPageName,BaseEntities.CategoryApiUrl AS ApiURL,PageOfPageFeilds.[DefaultValue],HeaderTemplateID,
	  IsMultiSelection,IsDataManager,AllowSorting,IsUnique,IsAutoGenerate
  FROM PageOfPageFeilds 
  LEFT JOIN GENTranslate_PageOfPageFeilds ON GENTranslate_PageOfPageFeilds.PageOfPageFeildId = PageOfPageFeilds.Id AND GENTranslate_PageOfPageFeilds.[LangId] = @LangId
  LEFT JOIN BaseEntityFields ON PageOfPageFeilds.FeildId = BaseEntityFields.Id
  LEFT JOIN GENPageOfPages ON PageOfPageFeilds.PageOfPageId = GENPageOfPages.Id
  LEFT JOIN BaseEntities ON GENPageOfPages.EntityId = BaseEntities.Id
  WHERE PageOfPageFeilds.[PageOfPageId] = @POPId AND PageOfPageFeilds.IsActive = 1
  ORDER BY PageOfPageFeilds.DisplayOrder

  SELECT PageOfPageRelations.[Id] ,PageOfPageRelations.[PageOfPageId] ,[SearchpopId] ,[FieldId] ,[ForeignKeyId] ,[ForeignKeyName] ,
	PageOfPageRelations.[DisplayName] AS DisplayName,[FilterName] ,[EntityId] ,[DataName] ,[FieldName] ,[EntityName]
      ,[IsActive] ,[FieldCols] ,[SearchCols] ,PageOfPageRelations.[IsIndex] ,[IsPrimaryKey] ,[IsIdentity] ,[AllowEditing] ,[AllowFiltering] ,[IsTemplateColumn] ,[Visible] ,[Width]
      ,[TemplateID] ,[Format] ,[Field] ,[TextAlign] ,[Type] ,PageOfPageRelations.[DisplayOrder] ,[IsMandatory], (CASE WHEN FilterEntityId IS NOT NULL THEN FilterEntityId ELSE 0 END) AS FilterEntityId
      ,PageOfPageRelations.[EntityApi],BaseEntityRelations.[DBField]
	   FROM PageOfPageRelations
	   LEFT JOIN BaseTabGENPageOfPages ON PageOfPageRelations.PageOfPageId = BaseTabGENPageOfPages.SearchPageId
	  LEFT JOIN BaseEntityRelations ON PageOfPageRelations.FieldId=BaseEntityRelations.Id
	WHERE BaseTabGENPageOfPages.GENPageOfPagesId = @POPId


END
GO
