CREATE Proc [dbo].[SP_SelectQuestions_byCourseId] (@CourseId bigint)
AS
Begin
select Course_Question.Id,GENPolls.Id AS  QuestionId,GENPolls.Question AS QuestionName,GENPolls.IsActive AS QuestionActive,
 (CASE WHEN QuestionType = 0 THEN 'MultipleChoice' ELSE CASE WHEN QuestionType = 1 THEN 'Value' ELSE CASE WHEN QuestionType = 2 THEN 'TrueFalse' ELSE CASE WHEN QuestionType = 3 THEN 'Article' ELSE CASE WHEN QuestionType = 4 THEN 'Checkbox' ELSE '' END END
                          END END END) AS QuestionTypeName, 
                         (CASE WHEN LevelQuestions = 1 THEN 'Easy' ELSE CASE WHEN LevelQuestions = 2 THEN 'Medium' ELSE CASE WHEN LevelQuestions = 3 THEN 'High' ELSE CASE WHEN LevelQuestions = 4 THEN 'Distinct' ELSE '' END END
                          END END) AS QuestionLevelName,GENPolls.Weight AS QuestionWeight,GENPolls.Code AS QuestionCode
From Course_Question  inner join 
GENPolls ON Course_Question.QuestionId=GENPolls.Id
where Course_Question.CourseId=@CourseId and GENPolls.IsActive=1
End
GO
