/****** Object:  StoredProcedure [dbo].[SP_SelectRawDataById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_SelectRawDataById] (@RawDataId bigint, @BaseEntityId bigint,@POPId bigint =null)
as
DECLARE @CompanyId BIGINT = NULL
DECLARE @ContactId BIGINT
--DECLARE @DefaultAddress NVARCHAR(MAX) = NULL
--select TOP(1) @CompanyId = [dbo].[RawData_View].CompanyId from [dbo].[RawData_View] where Id = @RawDataId

--SELECT @DefaultAddress= DefaultAddress from [dbo].[RawData_View] where Id = @RawDataId

SELECT TOP(1) *, (CASE WHEN [dbo].[RawData_View].CompanyId IS NOT NULL THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END) AS IsSelectedCompany from [dbo].[RawData_View] where Id = @RawDataId



SELECT GENImages.*, GENImages.AzureUri AS Image FROM GENImages WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

SELECT GENFiles.*,GENListValues.Name AS LanguageName, FORMAT(GENFiles.DateCreated, 'dd/MM/yyyy') AS DateCreatedString, 
FORMAT(GENFiles.DateCreated, 'hh:mm tt') AS TimeCreatedString, REVERSE(LEFT(REVERSE(GENFiles.AzureUri), CHARINDEX('.', REVERSE(GENFiles.AzureUri)) - 1)) AS FileExt 
FROM GENFiles
LEFT JOIN GENListValues ON GENFiles.LanguageId = GENListValues.Id
 WHERE GENFiles.BaseEntityId = @BaseEntityId AND GENFiles.EntityId = @RawDataId

SELECT GENAudios.*,FORMAT(GENAudios.DateCreated, 'dd/MM/yyyy') AS DateCreatedString 
FROM GENAudios WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

SELECT GENVideos.*,FORMAT(GENVideos.DateCreated, 'dd/MM/yyyy') AS DateCreatedString
 FROM GENVideos WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

SELECT GENLinks.*,GENItem_LinkTypes.Name AS LinkTypeName
 FROM GENLinks left join
 GENItem_LinkTypes ON GENLinks.linkTypeId=GENItem_LinkTypes.Id
 WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

SELECT [dbo].[GENEntity_Tag].*, GENTags.Name AS TagName FROM [dbo].[GENEntity_Tag]
LEFT JOIN GENTags ON [dbo].[GENEntity_Tag].TagId = GENTags.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

SELECT [dbo].[GENEntity_GENWiki].*, GENWikis.Name AS Name FROM [dbo].[GENEntity_GENWiki] 
LEFT JOIN GENWikis ON [dbo].[GENEntity_GENWiki].WikiId = GENWikis.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

SELECT GENEntityPricings.*, GENCurrencies.Name AS CurrencyName, GENRegions.Name AS regionName, GENUnits.Name AS UnitName,
 FORMAT(GENEntityPricings.FromDateTime, 'dd/MM/yyyy hh:mm tt') AS FromDateTimeString, 
 FORMAT(GENEntityPricings.ToDateTime, 'dd/MM/yyyy hh:mm tt') AS ToDateTimeString FROM GENEntityPricings
LEFT JOIN GENCurrencies ON GENEntityPricings.CurrencyId = GENCurrencies.Id
LEFT JOIN GENRegions ON GENEntityPricings.RegionId = GENRegions.Id
LEFT JOIN GENUnits ON GENEntityPricings.UnitId = GENUnits.Id
WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId 

SELECT GENPhones.*,GENPhoneTypes.Name AS PhoneTypeName, GENPhones.PhoneNumber AS PhoneNumberPrimary, (CASE WHEN GENPhones.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENPhones
LEFT JOIN GENPhoneTypes ON GENPhones.PhoneTypeId = GENPhoneTypes.Id
WHERE EntityId = @RawDataId and BaseEntityId=@BaseEntityId

SELECT GENEmails.*,GENEmails.Id As Id2,GENEmailTypes.Name AS EmailTypeName, GENEmails.Email AS EmailPrimary, (CASE WHEN GENEmails.IsDefault = 1 THEN 'far fa-check-circle' ELSE '' END) AS IsDefaultIcon
FROM GENEmails
LEFT JOIN GENEmailTypes ON GENEmails.EmailTypeId = GENEmailTypes.Id
WHERE EntityId = @RawDataId and BaseEntityId=@BaseEntityId

SELECT GENAddresses.*, GENRegions.Name AS RegionName,GENCountries.Name AS CountryName, GENProvinces.Name AS ProvinceName, 
GENGovernorates.Name AS GovernorateName, GENCities.Name AS CityName, GENDistricts.Name AS DistrictName,GENAddressZones.Name AS AddressZoneName, GENAreas.Name AS AreaName,
GENListValues.Name AS AddressTypeName
FROM GENAddresses
LEFT JOIN GENRegions ON GENAddresses.RegionsId = GENRegions.Id
LEFT JOIN GENCountries ON GENAddresses.CountryId = GENCountries.Id
LEFT JOIN GENProvinces ON GENAddresses.ProvinceId = GENProvinces.Id
LEFT JOIN GENGovernorates ON GENAddresses.GovernorateId = GENGovernorates.Id
LEFT JOIN GENCities ON GENAddresses.CityId = GENCities.Id
LEFT JOIN GENDistricts ON GENAddresses.DistrictId = GENDistricts.Id
LEFT JOIN GENAddressZones ON GENAddresses.AddressZoneId = GENAddressZones.Id
LEFT JOIN GENAreas ON GENAddresses.AreaId = GENAreas.Id
LEFT JOIN GENListValues ON GENAddresses.AddressTypeId = GENListValues.Id
 WHERE EntityId = @RawDataId AND BaseEntityId = @BaseEntityId

Select CRMSentEmails.[To], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @RawDataId and CRMSentEmails.EmailEntityPoPId=@POPId


Select CRMSentEmails.[From], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @RawDataId and CRMSentEmails.EmailEntityPoPId=@POPId



Select CRMSentEmails.[Cc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @RawDataId and CRMSentEmails.EmailEntityPoPId=@POPId

Select CRMSentEmails.[Bcc], CRMSentEmails.[Subject],FORMAT(CRMSentEmails.DateSent, 'dd/MM/yyyy') AS DateSentString,CRMSentEmails.[DateSent],
CRMSentEmails.[Body]

From CRMSentEmails

Where CRMSentEmails.EmailEntityId= @RawDataId and CRMSentEmails.EmailEntityPoPId=@POPId


Select GENBranches.*
From GENBranches
Where GENBranches.BaseEntityId=@BaseEntityId and GENBranches.EntityId=@RawDataId

SELECT GENEntityClassifications.*,GENClassifications.Name As ClassificationName
   FROM GENEntityClassifications 
   LEFT JOIN GENClassifications ON GENEntityClassifications.ClassificationId = GENClassifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

   SELECT GENEntitySpecifications.*,GENSpecifications.Name As SpecificationName
   FROM GENEntitySpecifications 
   LEFT JOIN GENSpecifications ON GENEntitySpecifications.SpecificationId = GENSpecifications.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId


   SELECT GENNews.*
   FROM GENNews 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

   
   
   SELECT GenRoles.*,AspNetRoles.Name as RoleName
   FROM GenRoles 
   left join AspNetRoles ON GenRoles.RoleId=AspNetRoles.Id
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId

   SELECT GENPointers.*
   FROM GENPointers 
   WHERE BaseEntityId = @BaseEntityId AND EntityId = @RawDataId




 SELECT GENTranslate_RawData.*, (CASE WHEN GENTranslate_RawData.FieldId  IS NOT NULL THEN(PageOfPageFeilds.DisplayName) ELSE '' END) AS FieldDisplayName,
  GENListValues.Name AS LanguageName
   FROM GENTranslate_RawData Left join 
   PageOfPageFeilds ON GENTranslate_RawData.FieldId=PageOfPageFeilds.id left join
   BaseEntityFields ON GENTranslate_RawData.BaseEntityFieldId =BaseEntityFields.id left join
   GENListValues ON GENTranslate_RawData.LangId = GENListValues.Id
  WHERE  GENTranslate_RawData.RawDataId = @RawDataId



select GENContact_Generic.Id,GENContacts.Name,GENContact_Generic.ContactId, CASE
    WHEN GENContacts.Image is null THEN '/Content/images/avatar.jpg'
	else GENContacts.Image end as Image,GENContacts.Position,GENContacts.DefaultEmail,GENContacts.DefaultPhone,
	FORMAT(GENContacts.DateCreated, 'dd/MM/yyyy') AS DateCreatedString,FORMAT(GENContacts.DateCreated, 'hh:mm tt') As TimeCreatedString,(CASE WHEN GENContacts.IsActive = 1 THEN 'True' ELSE 'False' END) AS IsActiveString,
	GENContact_Generic.RelativeRelationId,Relat.Name As RelativeRelationName,Assessment.Name As AssessmentName,CRMSources.Name As SourceName,GENContacts.IsActive,GENContact_Generic.EntityId,GENContact_Generic.BaseEntityId

from  GENContact_Generic left join

	GENContacts ON GENContact_Generic.ContactId=GENContacts.Id  left join
	GENListValues Relat ON GENContact_Generic.RelativeRelationId=Relat.Id left join
	GENListValues Assessment ON GENContacts.AssessmentId=Assessment.Id left join
	CRMSources ON GENContacts.SourceId=CRMSources.Id 
where  GENContact_Generic.EntityId=@RawDataId and GENContact_Generic.BaseEntityId=@BaseEntityId


select AllActivitiesWithDetails.* from AllActivitiesWithDetails
LEFT JOIN [dbo].[Contact_View] ON ActivityContactId = [dbo].[Contact_View].Id OR AllActivitiesWithDetails.ContactPersonId = [dbo].[Contact_View].Id
WHERE AllActivitiesWithDetails.EntityId =@RawDataId  and AllActivitiesWithDetails.BaseEntityId=@BaseEntityId



exec SP_GetAllChatMessages @POPId,@RawDataId
GO
