Create PROC [dbo].[SP_SelectRepliesComment_ByCommentId] (@CommentId bigint)--SP_SelectRepliesComment_ByCommentId 2
AS
Begin
Select GENComments.Id, GENComments.CommentText,GENComments.Description,GENBlogs.Text AS BlogTitle,
 FORMAT(dbo.GENComments.CreatedDate, 'dd/MM/yyyy') AS CreatedDateString,AspNetUsers.Name AS CreatedByName
from GENComments left join 
GENBlogs ON GENComments.BlogId =GENBlogs.Id left join
GENComments Parent ON GENComments.ParentId=Parent.Id left join 
AspNetUsers ON GENComments.CreatedById=AspNetUsers.Id
Where GENComments.ParentId=@CommentId and GENComments.DeletedById is null 
--and GENComments.IsActive=1 and GENComments.IsPublish =1

END
GO
