CREATE Proc [dbo].[SP_SelectSessions_ByCourseId] (@CourseId bigint)
as
begin
select Course_Session.Id,GENItems.Id As SessionId,GENItems.Name AS SessionName,GENItems.Code As SessionCode,GENItems.Int1,GENItems.DisplayOrder,GENTypes.Id as CourseId

FROM Course_Session  LEFT JOIN
GENItems ON Course_Session.SessionId=GENItems.Id LEFT JOIN
				GENTypes ON Course_Session.CourseId=GENTypes.Id
			

where Course_Session.CourseId=@CourseId AND GENItems.IsDeleted=0 and GENItems.IsActive=1
order by DisplayOrder
End
GO
