GO
CREATE Proc [dbo].[SP_SelectSessions_ByExamId] (@ExamId bigint)
as
begin
select GENItems.Name AS SessionName,GENTypes.Name AS CourseName
FROM            GENExam_GENItem  LEFT JOIN
				GENItems ON GENExam_GENItem.SessionId=GENItems.Id  LEFT JOIN
				GENTypes ON GENItems.TypeId=GENTypes.Id
			

where GENExam_GENItem.ExamId=@ExamId
End
GO
