GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectSessionsData_ByCourseId]    (@CourseId bigint)
as
begin
select distinct GENItems.*
FROM    Course_Session  inner  JOIN
GENItems ON Course_Session.SessionId=GENItems.Id 
where (Course_Session.CourseId=@CourseId or @CourseId is null or @CourseId = 0) AND GENItems.IsDeleted=0 and GENItems.IsActive=1
order by GENItems.DisplayOrder
End
GO
