GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_SelectSocialMedia] 
	@CategoryId bigint,@langCode nvarchar(500)
AS
BEGIN
	
	SET NOCOUNT ON;

    
SELECT           dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as  Facebook ,
   dbo.GENWikis.AudioURL as  Twitter ,
   dbo.GENWikis.TargetUrl as  Instagram , dbo.GENWikis.String1 as  LinkedIn ,dbo.GENWikis.String2 as  Youtube 
FROM            dbo.GENWikis             
WHERE        (dbo.GENWikis.WikiCategoryId = @CategoryId) AND (dbo.GENWikis.IsPublish = 1) AND (dbo.GENWikis.IsActive = 1) AND (dbo.GENWikis.Bool1 = 1)
ORDER BY dbo.GENWikis.DisplayOrdering
end
GO
