 select distinct Id, ExamName,TotalExamScore,TotalScore,ExamWeight,
dbo.Diff_BetweenDates_HoursAndMin(GENExamAnswerHeaders.StartDateTime, GENExamAnswerHeaders.EndtDateTime) AS ExamTimeString,
CourseName,
