/****** Object:  StoredProcedure [dbo].[SP_SelectTalents_ByTalentBuilders]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_SelectTalents_ByTalentBuilders] (@TalentBuilderId bigint)
AS
Begin
select GENTalents.Code, GENTalents.Name,GENTalents.Id,Format(GENTalents.FromDateTime,'dd/MM/yyyy') AS FromDateTimeString,Format(GENTalents.ToDateTime,'dd/MM/yyyy') AS ToDateTimeString,
GENTalents.Code,Count(GENContact_Talent.Id) AS	NumberOfStudents
from  GENTalents left join
GENContact_Talent ON GENTalents.Id=GENContact_Talent.TalentId
WHERE GENTalents.TalentBuilderId = @TalentBuilderId and GENTalents.isdeleted=0
group by GENTalents.Code, GENTalents.Name,GENTalents.Id,GENTalents.FromDateTime,GENTalents.ToDateTime
