CREATE PROCEDURE [dbo].[SP_SelectTicketCRMStatusEmpDashboard]  @Id nvarchar(128)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @TicketCount bigint
	SELECT  @TicketCount = COUNT(Id) FROM CRMTickets WHERE (IsDeleted <> 1) OR (IsDeleted IS NULL)
    -- Insert statements for procedure here
	SELECT *, round(((CAST([dbo].[VW_Status_CRMTicket_EmpDashboard].[Count] AS float) / CAST(@TicketCount AS float)) * 100), 2) AS TotalPercent FROM [dbo].[VW_Status_CRMTicket_EmpDashboard]
	WHERE EmployeeId = @Id
END
GO
