/****** Object:  StoredProcedure [dbo].[SP_SelectTreebuilder_TalentNuilderId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_SelectTreebuilder_TalentNuilderId] (@TalentBuilderId bigint)
AS
Begin
--declare @TalentBuilderId int = 6;
WITH HierarchicalCTE AS
(
SELECT Cat.Id,ParentId, Cat.Code, Cat.Name, 1 AS LEVEL ,
Cast(Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as Fullpath
FROM GENTypeCategories Cat
where cat.TalentBuilderId = @TalentBuilderId
UNION ALL
SELECT Cat.Id,Cat.ParentId, Cat.Code, Cat.Name, cte.level+1 AS LEVEL ,
Cast(Cte.Fullpath + '-' + Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as FullPath
FROM HierarchicalCTE cte
inner join GENTypeCategories Cat ON Cat.ParentId = cte.id
)
select * from HierarchicalCTE
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectTypCatgory_ById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[SP_SelectTypCatgory_ById]  (@Id bigint,@langCode nvarchar(500))
AS
Begin
Select  GENTypeCategories.Id,dbo.fn_TypeCategories_Translate_ByKeyandId( dbo.GENTypeCategories.Id,'Name',@langCode) AS Name,
dbo.fn_TypeCategories_Translate_ByKeyandId( dbo.GENTypeCategories.Id,'RichContent',@langCode) As Details,
dbo.fn_TypeCategories_Translate_ByKeyandId( dbo.GENTypeCategories.Id,'Code',@langCode) AS String,
GENTypeCategories.DisplayOrdering,dbo.fn_FirstImage_BaseEntityEntityId(187,GENTypeCategories.Id) as ImageCategory,
dbo.fn_TypeCategories_Translate_ByKeyandId(dbo.GENTypeCategories.Id,'Description',@langCode) AS Description,
Count(distinct GENTypes.Id) AS Countcourses,cast(sum(GENTypes.int1 * 60 + GENTypes.Int2) / 60 as int) as TotalHours,
GENTalents.Id AS TalentId,GENTalents.Name AS TalentName,dbo.fn_GetPriceString_ById(184,dbo.GENTalents.Id,@langCode,0) as TalentPrice,
FORMAT(GENTalents.FromDateTime,'dd/MM/yyyy') AS FromDate,FORMAT(GENTalents.ToDateTime,'dd/MM/yyyy') AS ToDate,
FORMAT(GENTalents.Date2,'dd/MM/yyyy') AS EndDateForRegistration
From  GENTypeCategories left join
GENTypes ON GENTypeCategories.Id=GENTypes.TypeCategoryId left join 
GENTalents ON GENTypeCategories.TalentId=GENTalents.Id
Where  GENTypeCategories.Id=@Id 
group by GENTypeCategories.Id,GENTypeCategories.Name,GENTypeCategories.RichContent,GENTypeCategories.Code,GENTypeCategories.DisplayOrdering,
GENTypeCategories.Description,GENTalents.Id,GENTalents.Name,GENTalents.FromDateTime,GENTalents.ToDateTime,GENTalents.Date2
End
GO
