CREATE  PROCEDURE [dbo].[SP_SelectWikiCategoryId] -- SP_SelectWikiCategoryId 54,'ar'
	
	@CategoryId bigint,@langCode nvarchar(500)
AS
BEGIN

	SET NOCOUNT ON;


SELECT           dbo.GENWikis.Id,   
   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'VideoURL',@langCode) as VideoURL, 
   dbo.GENWikis.AudioURL, dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'RichContent',@langCode) as RichContent,
   dbo.GENWikis.TargetUrl,

   dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Name',@langCode) as Name, 
                         dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'Description',@langCode) as Description,
				
                         dbo.GENWikis.DisplayOrdering,

						 dbo.GENWikis.LastUpdatedById, dbo.GENWikis.CheckoutBy,dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String1',@langCode)   as String1,
						 dbo.fn_Wiki_Translate_ByKeyandId( dbo.GENWikis.Id,'String2',@langCode)   as String2,
						
						FORMAT(dbo.GENWikis.Date1, 'dd/MM/yyyy hh:mm tt') AS Date1String,	FORMAT(dbo.GENWikis.Date1, 'yyyy') AS [Year],
					
                         (CASE WHEN (dbo.GENWikis.Image IS NULL OR dbo.GENWikis.Image = '') THEN '/assets/images/Default.png' ELSE dbo.GENWikis.Image END) AS Image,
						 dbo.GENWikis.IsActive,
						 dbo.GENWikis.IsPublish
FROM            dbo.GENWikis
                      
WHERE        (dbo.GENWikis.WikiCategoryId = @CategoryId) AND (dbo.GENWikis.IsPublish = 1) AND (dbo.GENWikis.IsActive = 1)
ORDER BY dbo.GENWikis.DisplayOrdering
end
GO
/****** Object:  StoredProcedure [dbo].[SP_SelectWikiNotesByContactId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_SelectWikiNotesByContactId] (@ContactId bigint)
as

SELECT GENWikis.*,FORMAT(GENWikis.DateCreated, 'dd/MM/yyyy hh:mm tt') AS DateCreatedString,FORMAT(GENWikis.DateUpdated, 'dd/MM/yyyy hh:mm tt') AS DateUpdatedString, 
GENWikiCategories.Name AS CategoryName, GENWikiCategories.Name AS WikiCatName,
GENContacts.Name AS ContactName, AspNetUsers.Name As LastUpdatedByName FROM GENWikis
LEFT JOIN GENWikiCategories ON GENWikis.WikiCategoryId = GENWikiCategories.Id
LEFT JOIN AspNetUsers ON GENWikis.LastUpdatedById = AspNetUsers.Id
LEFT JOIN GENContacts ON GENWikis.ContactId= GENContacts.Id
Where GENWikis.ContactId = @ContactId
GO
