CREATE Procedure [dbo].[SP_Status_CRMTicket_Time] @WhereClause nvarchar(MAX), @DateTimeFrom nvarchar(250), @DateTimeTo nvarchar(250)
AS
DECLARE @TableSelect nvarchar(MAX)

SET @TableSelect = 'SELECT DISTINCT dbo.GENStatus.Id, dbo.GENStatus.DisplayOrdering AS DisplayOrdering, dbo.GENStatus.Name AS Name, dbo.GENStyles.StyleValue AS Icon, 
		(CASE WHEN dbo.GENStatus.ColorCode IS NOT NULL THEN dbo.GENStatus.ColorCode ELSE ''#00a7d0'' END) AS Color, CAST(StatCount.CountStatus AS bigint) AS Count
FROM            dbo.GENStatus LEFT JOIN
                         dbo.CRMTicket_View_Update ON dbo.GENStatus.Id = dbo.CRMTicket_View_Update.ProcessId LEFT JOIN
                         dbo.GENStyles ON dbo.GENStatus.IconId = dbo.GENStyles.Id CROSS APPLY 
						 [dbo].[tfn_StatusCRMCount](dbo.GENStatus.Id, '''+ @DateTimeFrom +''', '''+@DateTimeTo+''') StatCount';

SET @TableSelect  = @TableSelect + ' ' + @WhereClause;
EXEC(@TableSelect)
GO
