CREATE PROCEDURE [dbo].[SP_StudentNotificationsByCourse]
(
  @Message nvarchar(max)=null,
  @CreatedById nvarchar(max)= null, @LastUpdatedById nvarchar(max)= null,
@Name nvarchar(max)=null, @URL nvarchar(max)=null, @IsNew bit=null,@FieldName nvarchar(max)=null, @TypeofNotification nvarchar(max)=null,@BaseEntityId bigint=null,
 @CreatedByName nvarchar(max)=null,@CourseId bigint=null,@Number int=null, @NoOfRetry bigint =null,@TrimUser bit=null,
 @IsRead bit=null, @IsSystemNotification bit =null ,@IsSound bit =null,@Priority bit =null,@IsDelivered bit =null,@IsMail bit =null,@IsiPhone bit =null,
 @IsAndroid bit =null,@IsFacebook bit =null,@Isweb bit=null ,@IsDeleted bit=null,@IsEmail bit =null
    ,@IsCanceled bit =null ,@IsiPhoneSent bit =null,@IsAndroidSent bit =null,@IsFacbookSent bit =null  ,@IsTwitter bit =null ,@IsTwitterSent  bit =null ,
	@Bool6 bit =null ,@Bool7 bit =null,@Bool8   bit =null,@Bool9 bit =null,@Bool10  bit =null ,@Bool11 bit =null
 ,@Bool12 bit =null ,@Bool13 bit =null ,@Bool14 bit =null ,@Bool15 bit =null,@Bool16 bit =null,@Bool17 bit =null,@Bool18 bit =null,@Bool19 bit =null,
 @Bool20 bit =null,@IsCheckedOut bit =null,@IsPosted bit =null,
 @IsPublish bit =null ,@IsActive bit  =null,@Bool1 bit =0,@Bool2 bit =0 ,@Bool3 bit =0,@Bool4 bit =0,@Bool5 bit =0
)
AS
BEGIN
   
    SET NOCOUNT ON

    -- Insert statements for procedure here
   insert into GENPushNotifications( Message , NotificationDate , CreatedById, LastUpdatedById , DateCreated, DateUpdated , Name,
	 URL,IsNew,FieldName , TypeofNotification , BaseEntityId , CreatedByName , EntityId , Number , UserId , Email,NoOfRetry,TrimUser,IsRead,
	 IsSystemNotification ,IsSound,Priority,IsDelivered,IsMail,IsiPhone,IsAndroid,IsFacebook,Isweb,IsDeleted,IsEmail
           ,IsCanceled
           ,IsiPhoneSent
           ,IsAndroidSent
           ,IsFacbookSent
           ,IsTwitter
           ,IsTwitterSent
		   ,Bool6
           ,Bool7
           ,Bool8
           ,Bool9
           ,Bool10
           ,Bool11
           ,Bool12
           ,Bool13
           ,Bool14
           ,Bool15
           ,Bool16
           ,Bool17
           ,Bool18
           ,Bool19
           ,Bool20
		   ,IsCheckedOut
           ,CheckinDate
           ,CheckoutDate
		   ,ExpectedCheckoutDate
           ,IsPosted
           ,IsPublish
           ,IsActive
		   ,Bool1
           ,Bool2
           ,Bool3
           ,Bool4
           ,Bool5
		   ,Timeout)
  select   @Message ,GETDATE() , @CreatedById, @LastUpdatedById ,GETDATE(),GETDATE() ,@Name, @URL, @IsNew, @FieldName ,
	@TypeofNotification ,@BaseEntityId ,@CreatedByName ,Contacts_Courses.StudentId ,@Number ,GENContacts.UserId ,GENContacts.DefaultEmail, @NoOfRetry ,@TrimUser,
 @IsRead, @IsSystemNotification,@IsSound,@Priority,@IsDelivered ,@IsMail ,@IsiPhone ,
 @IsAndroid ,@IsFacebook,@Isweb ,@IsDeleted ,@IsEmail 
    ,@IsCanceled ,@IsiPhoneSent ,@IsAndroidSent ,@IsFacbookSent  ,@IsTwitter  ,@IsTwitterSent  ,
	@Bool6  ,@Bool7 ,@Bool8 ,@Bool9 ,@Bool10   ,@Bool11
 ,@Bool12 ,@Bool13 ,@Bool14  ,@Bool15 ,@Bool16 ,@Bool17 ,@Bool18 ,@Bool19,
 @Bool20 ,@IsCheckedOut ,GETDATE(),GETDATE() ,GETDATE(),@IsPosted ,
 @IsPublish ,@IsActive ,@Bool1,@Bool2  ,@Bool3 ,@Bool4,@Bool5,12  from Contacts_Courses  inner join 
GENContacts on Contacts_Courses.StudentId=GENContacts.Id
where Contacts_Courses.CourseId = @CourseId
									  
END
