CREATE Proc [dbo].[SP_SysErrorLogs_InsertNew] (@UserId nvarchar(128), @AppId nvarchar(500), @UserName nvarchar(500), @EntityName nvarchar(500), @EntityId bigint, @BaseEntityId bigint, @PageofPagesId bigint, @ExpId bigint, @ExpDetails nvarchar(500))
as
declare @Id bigint
INSERT       
INTO              SysErrorLogs( UserId, AppId, UserName, DateCreated, EntityName, EntityId, BaseEntityId, PageofPagesId, ExpId, ExpDetails)
VALUES                          (@UserId, @AppId, @UserName, GETDATE(), @EntityName, @EntityId, @BaseEntityId, @PageofPagesId, @ExpId, @ExpDetails)
SELECT @Id = SCOPE_IDENTITY()
GO
/****** Object:  StoredProcedure [dbo].[SP_TalentsByTypcatId]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[SP_TalentsByTypcatId]
@CatId int,
@langCode nvarchar(50) = 'ar'
as
begin
WITH HierarchicalCTE AS
(
SELECT Cat.Id,ParentId, Cat.Code, Cat.Name, 1 AS LEVEL ,
Cast(Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as Fullpath,Cat.TalentId,Cat.IsActive,Cat.IsPublish
FROM GENTypeCategories Cat


where cat.Id = @CatId
UNION ALL
SELECT Cat.Id,Cat.ParentId, Cat.Code, Cat.Name, cte.level+1 AS LEVEL ,
Cast(Cte.Fullpath + '-' + Cat.Code + ' - ' +Cat.Name As nvarchar(max)) as FullPath
,Cat.TalentId,Cat.IsActive,Cat.IsPublish
FROM HierarchicalCTE cte
inner join GENTypeCategories Cat ON Cat.ParentId = cte.id
)
select cte.*,Talent.Name AS TalentName,dbo.fn_GetPriceString_ById(184,Talent.Id,@langCode,0) as TalentPrice,
FORMAT(Talent.FromDateTime,'dd/MM/yyyy') AS FromDate,FORMAT(Talent.ToDateTime,'dd/MM/yyyy') AS ToDate,
FORMAT(Talent.Date2,'dd/MM/yyyy') AS EndDateForRegistration from HierarchicalCTE cte
left join GENTalents Talent on Talent.Id= cte.TalentId
where cte.TalentId is not null and cte.IsActive = 1 and cte.IsPublish = 1
end
GO
