/****** Object:  StoredProcedure [dbo].[SP_TicketInfo_insertNew]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--, iif(dbo.CRMTickets.OverDueDate <= getdate(), cast(1 AS bit), cast(0 AS bit)) AS IsOverDue
CREATE proc [dbo].[SP_TicketInfo_insertNew](@TicketId bigint)
as
INSERT         
INTO              TicketInfoes( TIcketId, ColorCode, LastUpdatedByName, CreatedByName, ContactName, StatusName, ProcessId, ProcessName, EmployeeName, ResponsiblePersonImage, StatusIcon, AssessmentName, StatusColor, 
                         PriortyName, PriortyIcon, PriortyColor, DateCreatedString, TimeCreatedString, DateUpdatedString, TimeUpdatedString, ManagerId, EmployeeUserName, EmployeeUserId, CountCreated, TotalCountCreated, ActivityDate, 
                         BrandName, BranchName, OrderSource_Name, OrderType_Name, ComplainType_Name, ComplainClassif_Name, Satisfaction_Name, TicketSources_Name, ReservClassifi_Name, DateReservString, TimeReservString,numSet, 
                         TicketLifeDate, ActivityCount,CallCount,ListValueClassificationName,valueId1tName,valueId2tName,valueId3tName,valueId4tName,valueId5tName,EscalatedToName,ContactCategoryName,TicketTypeName,CurrencyName
						 ,TicketTypeIcon,TicketTypeColor,ComplainTypeColor,ComplainTypeIcon,ComplainClassifColor,ComplainClassifIcon,ReasonName,ReasonColor
						 ,ReasonIcon,ReasonTypeName,ReasonTypeColor,ReasonTypeIcon,EscalatedToPosition)
SELECT DISTINCT 
                        
                       @TicketId,  CASE WHEN dbo.GENEmployees.ColorCode IS NOT NULL AND dbo.GENEmployees.ColorCode <> '' THEN dbo.GENEmployees.ColorCode ELSE '#39cccc' END AS ColorCode, 
                         dbo.AspNetUsers.Name AS LastUpdatedByName, CreatedBy.Name AS CreatedByName, dbo.GENContacts.Name AS ContactName, dbo.GENStatus.Name AS StatusName, dbo.fnProcess_Id(dbo.CRMTickets.Id, 169) AS ProcessId, 
                         dbo.fnProcess_Name(dbo.CRMTickets.Id, 169) AS ProcessName, dbo.GENEmployees.Name AS EmployeeName, dbo.GENEmployees.Image AS ResponsiblePersonImage, dbo.GENStyles.StyleValue AS StatusIcon, 
                         Assessment.Name AS AssessmentName, dbo.fnProcess_Color(dbo.CRMTickets.Id, 169) AS StatusColor, 
                          Priority.Name AS PriortyName, dbo.fn_Icon_Style(Priority.IconId) AS PriortyIcon, Priority.ColorCode AS PriortyColor, CONVERT(varchar, dbo.CRMTickets.DateCreated, 103) AS DateCreatedString, 
                         (SELECT FORMAT(dbo.CRMTickets.DateCreated,'hh:mm tt')) AS  TimeCreatedString, CONVERT(varchar, dbo.CRMTickets.DateUpdated, 103) AS DateUpdatedString,
						  (SELECT FORMAT(dbo.CRMTickets.DateUpdated,'hh:mm tt')) AS TimeUpdatedString, dbo.GENEmployees.EmployeeId AS ManagerId, 
                         EmployeeUser.UserName AS EmployeeUserName, EmployeeUser.Id AS EmployeeUserId, dbo.fn_EmpCreatedCRMTicketLastDay(EmployeeUser.Id) AS CountCreated, dbo.fn_EmpTotalCreatedCRMTicket(EmployeeUser.Id) 
                         AS TotalCountCreated, dbo.fn_EmpLastActivty(EmployeeUser.UserName) AS ActivityDate, dbo.GENBrands.Name AS BrandName, dbo.GENBranches.Name AS BranchName, 
                          dbo.GENListValues.Name AS OrderSource_Name, GENListValues_1.Name AS OrderType_Name, 
                          GENListValues_2.Name AS ComplainType_Name, dbo.fnListValue_ById(CRMTickets.ValueId4,NULL) AS ComplainClassif_Name, 
                         GENListValues_4.Name AS Satisfaction_Name, dbo.CRMSources.Name AS TicketSources_Name, dbo.GENClassifications.Name AS ReservClassifi_Name, CONVERT(varchar, dbo.CRMTickets.OpenDate, 103) 
                         AS DateReservString, CONVERT(varchar, dbo.CRMTickets.OpenDate, 108) AS TimeReservString, dbo.CRMTickets.Int1 AS numSet, 
                         dbo.Diff_BetweenDates(CRMTickets.DateCreated, GETDATE()) AS TicketLifeDate, dbo.fn_ActivityCount_ByEntityandBaseEntityId(CRMTickets.Id, 169) AS ActivityCount, 
                         dbo.fn_ActivityCount_ByEntityandBaseEntityId_TypeName(CRMTickets.Id, 169, 'Call') AS CallCount, dbo.fnListValue_ById(CRMTickets.ClassificationId,NULL) AS ListValueClassificationName,
						 dbo.fnListValue_ById(dbo.CRMTickets.ValueId1,NULL) as valueId1tName, dbo.fnListValue_ById(dbo.CRMTickets.ValueId2,NULL) as valueId2tName,
						  dbo.fnListValue_ById(dbo.CRMTickets.ValueId3,NULL) as valueId3tName, dbo.fnListValue_ById(dbo.CRMTickets.ValueId4,NULL) as valueId4tName,
						   dbo.fnListValue_ById(dbo.CRMTickets.ValueId5,NULL) as valueId5tName,dbo.fnEmployee_NameById(dbo.CRMTickets.EscalatedTo) as EscalatedToName,
						   dbo.fnContactCategory_NameById(dbo.CRMTickets.ContactCategoryId) as ContactCategoryName,CRMSRVTicketTypes.Name as TicketTypeName,GENCurrencies.Name as CurrencyName
						   ,dbo.fn_Icon_Style( CRMSRVTicketTypes.IconId) as TicketTypeIcon,CRMSRVTicketTypes.ColorCode as TicketTypeColor
						   , GENListValues_2.ColorCode AS ComplainTypeColor, dbo.fn_Icon_Style(GENListValues_2.IconId) AS ComplainTypeIcon
						     , GENListValues_4.ColorCode AS ComplainClassifColor, dbo.fn_Icon_Style(GENListValues_4.IconId) AS ComplainClassifIcon
							 , CRMSRVReasons.Name as ReasonName ,CRMSRVReasons.ColorCode as ReasonColor, dbo.fn_Icon_Style(CRMSRVReasons.IconId) AS ReasonIcon
							 , CRMSRVReasonTypes.Name as ReasonTypeName ,CRMSRVReasonTypes.ColorCode as ReasonTypeColor, dbo.fn_Icon_Style(CRMSRVReasonTypes.IconId) AS ReasonTypeIcon,
							 dbo.fnEmployee_PosisionById(dbo.CRMTickets.EscalatedTo) as EscalatedToPosition
FROM            dbo.CRMTickets LEFT OUTER JOIN
dbo.CRMSRVTicketTypes ON dbo.CRMTickets.TicketTypeId = dbo.CRMSRVTicketTypes.Id LEFT OUTER JOIN 
dbo.GENCurrencies ON dbo.CRMTickets.CurrencyId = dbo.GENCurrencies.Id LEFT OUTER JOIN 
                         dbo.GENContacts ON dbo.CRMTickets.ContactId = dbo.GENContacts.Id LEFT OUTER JOIN
                         dbo.GENStatus ON dbo.CRMTickets.StatusId = dbo.GENStatus.Id LEFT OUTER JOIN
						   dbo.CRMSRVReasons ON dbo.CRMTickets.ReasonId = dbo.CRMSRVReasons.Id LEFT OUTER JOIN
						     dbo.CRMSRVReasonTypes ON dbo.CRMTickets.ReasonTypeId = dbo.CRMSRVReasonTypes.Id LEFT OUTER JOIN
                         dbo.GENEmployees ON dbo.CRMTickets.EmployeeId = dbo.GENEmployees.Id LEFT OUTER JOIN
                         dbo.AspNetUsers AS EmployeeUser ON EmployeeUser.Id = dbo.GENEmployees.UserId LEFT OUTER JOIN
                         dbo.GENListValues AS Assessment ON dbo.CRMTickets.AssessmentId = Assessment.Id LEFT OUTER JOIN
                         dbo.GENListValues AS Priority ON dbo.CRMTickets.PriortyId = Priority.Id LEFT OUTER JOIN
                         dbo.GENStyles ON dbo.GENStatus.IconId = dbo.GENStyles.Id LEFT OUTER JOIN
                         dbo.AspNetUsers ON dbo.CRMTickets.LastUpdatedById = dbo.AspNetUsers.Id LEFT JOIN
                         dbo.AspNetUsers CreatedBy ON dbo.CRMTickets.CreatedById = CreatedBy.Id LEFT OUTER JOIN
                         dbo.GENBrands ON dbo.CRMTickets.BrandId = dbo.GENBrands.Id LEFT OUTER JOIN
                         dbo.GENBranches ON dbo.CRMTickets.BranchId = dbo.GENBranches.Id LEFT OUTER JOIN
                         dbo.CRMSources ON dbo.CRMTickets.SourceId = dbo.CRMSources.Id LEFT OUTER JOIN
                         dbo.GENListValues ON dbo.CRMTickets.ValueId1 = dbo.GENListValues.Id LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_1 ON dbo.CRMTickets.ValueId2 = GENListValues_1.Id LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_2 ON dbo.CRMTickets.ValueId3 = GENListValues_2.Id LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_3 ON dbo.CRMTickets.ValueId4 = GENListValues_3.Id LEFT OUTER JOIN
                         dbo.GENListValues AS GENListValues_4 ON dbo.CRMTickets.SatisfactionId = GENListValues_4.Id LEFT OUTER JOIN
                         dbo.GENClassifications ON dbo.CRMTickets.ClassificationId = dbo.GENClassifications.Id


						where dbo.CRMTickets.Id =@TicketId
GO
/****** Object:  StoredProcedure [dbo].[SP_TicketInfo_UpateById]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
