--    Phone = dbo.fnContact_PhoneString(@ContactId)
--FROM
--    ContactInfoes
--WHERE
--    ContactInfoes.ContactId = @ContactId
END
ELSE
BEGIN
exec [dbo].[SP_TicketInfo_insertNew] @ticketId
END
