/****** Object:  StoredProcedure [dbo].[SP_TopRatingAndLessRating]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create   proc [dbo].[SP_TopRatingAndLessRating]  -- SP_TopRatingAndLessRating '2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
As
 DECLARE @TopRatingName NVARCHAR(max);
 DECLARE @LessRatingName NVARCHAR(max);
WITH Ratings AS (
   SELECT 
            E.Id,
            E.Name,
            SUM(GR.Rating) AS TotalRating
        FROM GENRatings GR
    INNER JOIN 
        TLMSClassroom_Session TCS ON GR.BaseEntityId = 198 AND TCS.Id = GR.EntityId
    INNER JOIN 
        GENEmployees E ON E.EmployeeCategoryId = 1 AND E.Id = TCS.InstructorId
    WHERE 
        (
            (CAST(TCS.SessionDateTime AS date) BETWEEN CAST(@DateF AS date) AND CAST(@DateTo AS date))
            OR (@DateF IS NULL AND @DateTo IS NULL AND CAST(TCS.SessionDateTime AS date) BETWEEN CAST(DATEADD(month, -1, GETDATE()) AS date) AND CAST(GETDATE() AS date))
            OR (LEN(@DateF) = 0 AND LEN(@DateTo) = 0)
        )
    GROUP BY 
        E.Id, E.Name
)
SELECT 
		@TopRatingName = (SELECT TOP 1 Name FROM Ratings ORDER BY TotalRating DESC),
        @LessRatingName = (SELECT TOP 1 Name FROM Ratings ORDER BY TotalRating ASC);
 SELECT @TopRatingName TopRatingName , @LessRatingName LessRatingName
GO
/****** Object:  StoredProcedure [dbo].[SP_TraineesAndLecturesListInfo]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_TraineesAndLecturesListInfo]  --SP_TraineesAndLecturesListInfo'2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
as
begin
with RatingsCount AS (
     SELECT 
        GENEmployees.Id, 
        GENEmployees.Name,
        SUM(GENRatings.Rating) AS Rating ,
		SUM(CASE WHEN Rating = 5 THEN 1 ELSE 0 END) AS Excellent,
		SUM(CASE WHEN Rating = 4 THEN 1 ELSE 0 END) AS VeryGood,
		SUM(CASE WHEN Rating = 3 THEN 1 ELSE 0 END) AS Good,
		SUM(CASE WHEN Rating = 2 THEN 1 ELSE 0 END) AS Pass,
		SUM(CASE WHEN Rating = 1 THEN 1 ELSE 0 END) AS Weak,
		sum(res.CountOfTrainer) as CountOfTrainer,
		COUNT(DISTINCT res.Id) AS CountOfLecture,
		CAST(ROUND(SUM(DATEDIFF(MINUTE, res.FromDateTime, res.ToDateTime)) / 60.0, 0) AS INT) AS TotalDurationHours
    FROM 
        GENEmployees 
    left JOIN 
	(select TLMSClassroom_Session.Id,TLMSClassroom_Session.InstructorId,count(GENClassroom_GENContact.Id) as CountOfTrainer,TLMSClassroom_Session.FromDateTime
	, TLMSClassroom_Session.ToDateTime
	from TLMSClassroom_Session 
	left join GENClassroom_GENContact on GENClassroom_GENContact.ClassroomId = TLMSClassroom_Session.ClassroomId and GENClassroom_GENContact.BookingTypeId = 1
	and ((cast(TLMSClassroom_Session.SessionDateTime as date) >= cast(@DateF as date) and cast(TLMSClassroom_Session.SessionDateTime as date) <= cast(@DateTo as date)) 
		or (@DateF is null and @DateTo is null and ((cast(TLMSClassroom_Session.SessionDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) 
		and cast(TLMSClassroom_Session.SessionDateTime as date) <= cast(GETDATE() as date)) ) )
		or (len(@DateF) = 0 and len(@DateTo) = 0))
		group by TLMSClassroom_Session.Id,TLMSClassroom_Session.InstructorId,TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime
	) res ON GENEmployees.Id = res.InstructorId  
    left JOIN 
        GENRatings  ON GENRatings.BaseEntityId = 198 AND res.Id = GENRatings.EntityId  and GENEmployees.Id = GENRatings.EntityId2
		where GENEmployees.EmployeeCategoryId = 1 AND GENEmployees.IsDeleted =0  and GENEmployees.IsActive = 1
    GROUP BY 
		
        GENEmployees.Id, 
        GENEmployees.Name
)

SELECT 
    res.id as Id,
    res.Name,
    res.CountOfLecture,
    res.TotalDurationHours,
    res.CountOfTrainer,
	res.Excellent AS Excellent,
    res.VeryGood AS VeryGood,
    res.Good AS Good,
    res.Pass AS Pass,
    res.Weak AS Weak,
	(case when res.CountOfTrainer is null or res.CountOfTrainer = 0 then 0 else cast(round((res.Excellent  + res.VeryGood)*100.00/isnull(res.CountOfTrainer, 0.00)*1.00,2) as decimal(5,2)) end)
	StasifationPercentage
from  RatingsCount res
where   res.Name is not Null
group by    res.Id, res.Name,  res.CountOfLecture, res.TotalDurationHours, res.CountOfTrainer, res.Excellent, res.VeryGood, res.Good,res.Pass,res.Weak
order by (case when res.CountOfTrainer is null or  res.CountOfTrainer = 0 then 0 else cast(round((res.Excellent  + res.VeryGood)*100.00/isnull(res.CountOfTrainer, 0.00)*1.00,2) as decimal(5,2)) end) desc
end
GO
/****** Object:  StoredProcedure [dbo].[SP_TraineesInfo]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   Proc [dbo].[SP_TraineesInfo]
@DateF Datetime,
@DateTo Datetime
As
Begin
declare @Tranees int ;
declare @ParticipationActivity int ;
declare @MostParticipation nvarchar(max) ;

select @Tranees = count(distinct c.Id) 
from GENContacts c 
where ((cast(c.datecreated as date) >= cast(@DateF as date) and cast(c.datecreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(c.datecreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(c.datecreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

select @ParticipationActivity =  count(distinct g.Id) from gencontacts c 
	inner join GENClassroom_GENContact cc on cc.studentId = c.id
	inner join GENClassrooms g on cc.classroomId = g.id
	where((cast(g.FromDateTime as date) >= cast(@DateF as date) and cast(g.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(g.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(g.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

select @MostParticipation = name  from (select top 1 count(distinct g.id) as sequence ,c.name ,g.id as ParticipationActivity from gencontacts c 
	inner join GENClassroom_GENContact cc on cc.studentId = c.id
	inner join GENClassrooms g on cc.classroomId = g.id
	where((cast(g.FromDateTime as date) >= cast(@DateF as date) and cast(g.FromDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(g.FromDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(g.FromDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
	group by c.name ,g.id)as MostParticipation;

	select 
	@Tranees as Tranees,
	@ParticipationActivity as ParticipationActivity,
	@MostParticipation as MostParticipation,
	8 DataSetNo

End
GO
/****** Object:  StoredProcedure [dbo].[SP_TrainersAndLecturers]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[SP_TrainersAndLecturers] 
as
begin
select TLMSClassroom_Session.Name from TLMSClassroom_Session
inner join 
(
select top 1 GENEmployees.Id,GENEmployees.Name,SUM(GENRatings.Rating) as Rating from GENRatings 
inner join TLMSClassroom_Session on GENRatings.BaseEntityId = 198 and TLMSClassroom_Session.Id = GENRatings.EntityId
inner join GENEmployees on GENEmployees.EmployeeCategoryId = 1 and GENEmployees.Id = TLMSClassroom_Session.InstructorId
group by GENEmployees.Id,GENEmployees.Name
order by SUM(GENRatings.Rating) desc
) as res on res.Id = TLMSClassroom_Session.InstructorId
-------------------------------------------------
-------------------------------------------------
select TLMSClassroom_Session.Name from TLMSClassroom_Session
inner join 
(
select top 1 GENEmployees.Id,GENEmployees.Name,SUM(GENRatings.Rating) as Rating from GENRatings 
inner join TLMSClassroom_Session on GENRatings.BaseEntityId = 198 and TLMSClassroom_Session.Id = GENRatings.EntityId
inner join GENEmployees on GENEmployees.EmployeeCategoryId = 1 and GENEmployees.Id = TLMSClassroom_Session.InstructorId
group by GENEmployees.Id,GENEmployees.Name
order by SUM(GENRatings.Rating) asc
) as res on res.Id = TLMSClassroom_Session.InstructorId
---------------------------------------------------
---------------------------------------------------
SELECT 
    res.Name,
    COUNT(DISTINCT TLMSClassroom_Session.Id) AS CountOfLecture,
    CAST(ROUND(SUM(DATEDIFF(MINUTE, TLMSClassroom_Session.FromDateTime, TLMSClassroom_Session.ToDateTime)) / 60.0, 0) AS INT) AS TotalDurationHours,
    COUNT(DISTINCT GENContacts.Id) AS CountOfTrainer,
	res.Excellent AS Excellent,
    res.VeryGood AS VeryGood,
    res.Good AS Good,
    res.Pass AS Pass,
    res.Weak AS Weak,
	Cast(round((res.Excellent  + res.VeryGood)*1.00/COUNT(DISTINCT GENContacts.Id)*1.00,2)as decimal(10,1))
FROM 
    TLMSClassroom_Session
INNER JOIN 
    GENClassrooms ON GENClassrooms.Id = TLMSClassroom_Session.ClassroomId
INNER JOIN 
    GENClassroom_GENContact ON GENClassroom_GENContact.ClassroomId = GENClassrooms.Id
INNER JOIN 
    GENContacts ON GENContacts.Id = GENClassroom_GENContact.StudentId
INNER JOIN 
(
    SELECT 
        GENEmployees.Id, 
        GENEmployees.Name,
        SUM(GENRatings.Rating) AS Rating ,
		SUM(CASE WHEN Rating = 5 THEN 1 ELSE 0 END) AS Excellent,
		SUM(CASE WHEN Rating = 4 THEN 1 ELSE 0 END) AS VeryGood,
		SUM(CASE WHEN Rating = 3 THEN 1 ELSE 0 END) AS Good,
		SUM(CASE WHEN Rating = 2 THEN 1 ELSE 0 END) AS Pass,
		SUM(CASE WHEN Rating = 1 THEN 1 ELSE 0 END) AS Weak
    FROM 
        GENRatings 
    INNER JOIN 
        TLMSClassroom_Session ON GENRatings.BaseEntityId = 198 AND TLMSClassroom_Session.Id = GENRatings.EntityId
    INNER JOIN 
        GENEmployees ON GENEmployees.EmployeeCategoryId = 1 AND GENEmployees.Id = TLMSClassroom_Session.InstructorId
    GROUP BY 
        GENEmployees.Id, 
        GENEmployees.Name
) AS res 
ON 
    res.Id = TLMSClassroom_Session.InstructorId
GROUP BY 
    res.Name,res.Excellent,res.verygood,res.good,res.pass,res.weak
order by Max(res.Rating) desc
end
GO
/****** Object:  StoredProcedure [dbo].[SP_TrainersAndLecturersInfo]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[SP_TrainersAndLecturersInfo]  -- [SP_TrainersAndLecturersInfo]'2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
AS 
BEGIN
    DECLARE @Trainees INT;
    DECLARE @TraineesActive INT;
    DECLARE @TraineesNotActive INT;
    DECLARE @TopRatingName NVARCHAR(max);
    DECLARE @LessRatingName NVARCHAR(max);
    DECLARE @MostExecution NVARCHAR(max);
    DECLARE @LessExecution NVARCHAR(max);

    -- Calculate the number of distinct Trainees
    SELECT @Trainees = COUNT(DISTINCT E.id),@TraineesActive = count(distinct(case when TLMSClassroom_Session.Id is not null then E.id else null end))
	--,@TraineesNotActive = count(distinct(case when TLMSClassroom_Session.Id is not null then null else  E.id  end))
    FROM GENEmployees E
    left join TLMSClassroom_Session on  E.Id = TLMSClassroom_Session.InstructorId
    WHERE E.EmployeeCategoryId = 1 AND E.IsDeleted = 0 AND E.IsActive = 1
	and ((cast(E.datecreated as date) >= cast(@DateF as date) and cast(E.datecreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(E.datecreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(E.datecreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

    -- Calculate the number of distinct not active Trainees
    SELECT @TraineesNotActive = COUNT(DISTINCT E.id)
    FROM GENEmployees E
	left join TLMSClassroom_Session on  E.Id = TLMSClassroom_Session.InstructorId 
    WHERE E.EmployeeCategoryId = 1 AND E.IsDeleted = 0   AND E.IsActive = 1 and TLMSClassroom_Session.Id is null 
	and ((cast(E.datecreated as date) >= cast(@DateF as date) and cast(E.datecreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(E.datecreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(E.datecreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));


    -- Get the name of the employee with the top rating
    SELECT TOP 1 @TopRatingName = E.Name
    FROM GENRatings 
    INNER JOIN TLMSClassroom_Session  ON GENRatings.BaseEntityId = 198 AND TLMSClassroom_Session.Id = GENRatings.EntityId
    INNER JOIN GENEmployees E ON E.EmployeeCategoryId = 1 AND E.Id = TLMSClassroom_Session.InstructorId
	where ((cast(TLMSClassroom_Session.SessionDateTime as date) >= cast(@DateF as date) and cast(TLMSClassroom_Session.SessionDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(TLMSClassroom_Session.SessionDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(TLMSClassroom_Session.SessionDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
    GROUP BY E.Id, E.Name
    ORDER BY SUM(GENRatings.Rating) DESC;

    -- Get the name of the employee with the lowest rating
    SELECT TOP 1 @LessRatingName = GENEmployees.Name
    FROM GENRatings 
    INNER JOIN TLMSClassroom_Session ON GENRatings.BaseEntityId = 198 AND TLMSClassroom_Session.Id = GENRatings.EntityId
    INNER JOIN GENEmployees ON GENEmployees.EmployeeCategoryId = 1 AND GENEmployees.Id = TLMSClassroom_Session.InstructorId
	where ((cast(TLMSClassroom_Session.SessionDateTime as date) >= cast(@DateF as date) and cast(TLMSClassroom_Session.SessionDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(TLMSClassroom_Session.SessionDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(TLMSClassroom_Session.SessionDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0))
    GROUP BY GENEmployees.Id, GENEmployees.Name
    ORDER BY SUM(GENRatings.Rating) ASC;

    -- Calculate the session with the most executions
    SELECT TOP 1 @MostExecution = I.Name
    FROM GENItems I 
    INNER JOIN TLMSClassroom_Session T ON T.SessionId = I.Id
	where ((cast(T.SessionDateTime as date) >= cast(@DateF as date) and cast(t.SessionDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(t.SessionDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(t.SessionDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0)) and T.Name is not null
    GROUP BY I.Name
    ORDER BY COUNT(DISTINCT T.id) DESC;

    -- Calculate the session with the least executions
    SELECT TOP 1 @LessExecution = I.Name
    FROM GENItems I 
    INNER JOIN TLMSClassroom_Session T ON T.SessionId = I.Id
	where ((cast(t.SessionDateTime as date) >= cast(@DateF as date) and cast(t.SessionDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(t.SessionDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(t.SessionDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0)) and T.Name is not null
    GROUP BY I.Name
    ORDER BY COUNT(DISTINCT T.id) ASC;

    -- Return the results
    SELECT 
        @Trainees AS Trainees, 
        @TraineesActive AS TraineesActive, 
        @TraineesNotActive AS TraineesNotActive,
        @TopRatingName AS TopRatingName,
        @LessRatingName AS LessRatingName,
        @MostExecution AS MostExecution,
        @LessExecution AS LessExecution;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_TrainersAndLecturersInfo_01_testing]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create     PROC [dbo].[SP_TrainersAndLecturersInfo_01_testing]  -- SP_TrainersAndLecturersInfo_01_testing'2019-01-01', '2030-12-31'
@DateF Datetime,
@DateTo Datetime
AS 
BEGIN
    DECLARE @Trainees INT;
    DECLARE @TraineesActive INT;
    DECLARE @TraineesNotActive INT;
    DECLARE @TopRatingName NVARCHAR(max);
    DECLARE @LessRatingName NVARCHAR(max);
    DECLARE @MostExecution NVARCHAR(max);
    DECLARE @LessExecution NVARCHAR(max);

    -- Calculate the number of distinct Trainees
    SELECT @Trainees = COUNT(DISTINCT E.id),@TraineesActive = count(distinct(case when TLMSClassroom_Session.Id is not null then E.id else null end))
	--,@TraineesNotActive = count(distinct(case when TLMSClassroom_Session.Id is not null then null else  E.id  end))
    FROM GENEmployees E
    left join TLMSClassroom_Session on  E.Id = TLMSClassroom_Session.InstructorId
    WHERE E.EmployeeCategoryId = 1 AND E.IsDeleted = 0 AND E.IsActive = 1
	and ((cast(E.datecreated as date) >= cast(@DateF as date) and cast(E.datecreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(E.datecreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(E.datecreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));

    -- Calculate the number of distinct not active Trainees
    SELECT @TraineesNotActive = COUNT(DISTINCT E.id)
    FROM GENEmployees E
	left join TLMSClassroom_Session on  E.Id = TLMSClassroom_Session.InstructorId 
    WHERE E.EmployeeCategoryId = 1 AND E.IsDeleted = 0   AND E.IsActive = 1 and TLMSClassroom_Session.Id is null 
	and ((cast(E.datecreated as date) >= cast(@DateF as date) and cast(E.datecreated as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(E.datecreated as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(E.datecreated as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0));
WITH Ratings AS (
   SELECT 
            E.Id,
            E.Name,
            SUM(GR.Rating) AS TotalRating
        FROM GENRatings GR
    INNER JOIN 
        TLMSClassroom_Session TCS ON GR.BaseEntityId = 198 AND TCS.Id = GR.EntityId
    INNER JOIN 
        GENEmployees E ON E.EmployeeCategoryId = 1 AND E.Id = TCS.InstructorId
    WHERE 
        (
            (CAST(TCS.SessionDateTime AS date) BETWEEN CAST(@DateF AS date) AND CAST(@DateTo AS date))
            OR (@DateF IS NULL AND @DateTo IS NULL AND CAST(TCS.SessionDateTime AS date) BETWEEN CAST(DATEADD(month, -1, GETDATE()) AS date) AND CAST(GETDATE() AS date))
            OR (LEN(@DateF) = 0 AND LEN(@DateTo) = 0)
        )
    GROUP BY 
        E.Id, E.Name
)
SELECT 
		@TopRatingName = (SELECT TOP 1 Name FROM Ratings ORDER BY TotalRating DESC),
        @LessRatingName = (SELECT TOP 1 Name FROM Ratings ORDER BY TotalRating ASC);
   
    WITH SessionExecutions AS (
     SELECT 
            I.Name,
            COUNT(DISTINCT T.Id) AS ExecutionCount
     FROM 
        GENItems I
    INNER JOIN 
        TLMSClassroom_Session T ON T.SessionId = I.Id
 where ((cast(t.SessionDateTime as date) >= cast(@DateF as date) and cast(t.SessionDateTime as date) <= cast(@DateTo as date)) 
     or (@DateF is null and @DateTo is null and ((cast(t.SessionDateTime as date) >= cast(DATEADD(month,-1,GETDATE()) as date) and cast(t.SessionDateTime as date) <= cast(GETDATE() as date)) ) )
     or (len(@DateF) = 0 and len(@DateTo) = 0)) and T.Name is not null
    GROUP BY 
        I.Name
)
SELECT 
    @MostExecution = (SELECT TOP 1 Name FROM SessionExecutions ORDER BY ExecutionCount DESC),
    @LessExecution = (SELECT TOP 1 Name FROM SessionExecutions ORDER BY ExecutionCount ASC);



    -- Return the results
    SELECT 
        @Trainees AS Trainees, 
        @TraineesActive AS TraineesActive, 
        @TraineesNotActive AS TraineesNotActive,
        @TopRatingName AS TopRatingName,
        @LessRatingName AS LessRatingName,
        @MostExecution AS MostExecution,
        @LessExecution AS LessExecution;
END
GO
