CREATE PROCEDURE [dbo].[SP_TypeById] @Id BIGINT,@langCode nvarchar(500),@IsLocal bit
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENTypes.[Id]
      ,dbo.fn_Type_Translate_ByKeyandId( GENTypes.Id,'Name',@langCode) AS [Name]
