      ,GENTypes.[CheckoutDate]
      ,GENTypes.[Timeout]
      ,GENTypes.[DisplayOrdering]
      ,GENTypes.[CreatedById]
      ,GENTypes.[LastUpdatedById]
      ,GENTypes.[CheckoutBy]
      ,dbo.fn_Type_Translate_ByKeyandId( GENTypes.Id,'String1',@langCode) AS [String1]
      ,dbo.fn_Type_Translate_ByKeyandId( GENTypes.Id,'String2',@langCode) AS [String2]
      ,dbo.fn_Type_Translate_ByKeyandId( GENTypes.Id,'String3',@langCode) AS [String3]
      ,dbo.fn_Type_Translate_ByKeyandId( GENTypes.Id,'String4',@langCode) AS [String4]
      ,dbo.fn_Type_Translate_ByKeyandId( GENTypes.Id,'String5',@langCode) AS [String5]
      ,GENTypes.[Int1]
      ,GENTypes.[Int2]
      ,GENTypes.[Int3]
      ,GENTypes.[Int4]
      ,GENTypes.[Int5]
      ,GENTypes.[Long1]
      ,GENTypes.[Long2]
      ,GENTypes.[Long3]
      ,GENTypes.[Long4]
      ,GENTypes.[Long5]
      ,GENTypes.[Float1]
      ,GENTypes.[Float2]
      ,GENTypes.[Float3]
      ,GENTypes.[Float4]
      ,GENTypes.[Float5]
      ,GENTypes.[Decimal1]
      ,GENTypes.[Decimal2]
      ,GENTypes.[Decimal3]
      ,GENTypes.[Decimal4]
      ,GENTypes.[Decimal5]
      ,GENTypes.[Bool1]
      ,GENTypes.[Bool2]
      ,GENTypes.[Bool3]
      ,GENTypes.[Bool4]
      ,GENTypes.[Bool5]
      ,GENTypes.[Date1]
      ,GENTypes.[Date2]
      ,GENTypes.[Date3]
      ,GENTypes.[Date4]
      ,GENTypes.[Date5]
      ,GENTypes.[ValueId1]
      ,GENTypes.[ValueId2]
      ,GENTypes.[ValueId3]
      ,GENTypes.[ValueId4]
      ,GENTypes.[ValueId5]
      ,GENTypes.[IconId]
      ,GENTypes.[ExpectedCheckoutDate]
      ,GENTypes.[IsPosted],dbo.fn_FirstImage_BaseEntityEntityId(28,GENTypes.Id) as [Image], dbo.fn_GetPriceString_ById(28,dbo.GENTypes.Id,@langCode,@IsLocal) as PriceString,
	dbo.fn_TypeCategories_Translate_ByKeyandId( dbo.GENTagCategories.Id,'Name',@langCode) AS ListValue1Name,
						 CAST((SUM(GENRatings.Rating)/ COUNT(GENRatings.Id)) AS DECIMAL(18,2)) AS Rate, COUNT(GENRatings.Id) AS RatingCount,
						 GENTypes.CourseType,
	dbo.fn_FirstVideo_BaseEntityEntityId(28, dbo.GENTypes.Id) AS Video,GENClassrooms.Id AS VcrId
	FROM GENTypes 
	LEFT  JOIN dbo.GENClassrooms ON dbo.GENTypes.Id = dbo.GENClassrooms.CourseId
	LEFT  JOIN dbo.GENTagCategories ON dbo.GENTypes.TypeCategoryId = dbo.GENTagCategories.Id
	LEFT JOIN GENRatings ON GENTypes.Id = GENRatings.EntityId AND GENRatings.BaseEntityId = 28
	WHERE GENTypes.Id = @Id
	GROUP BY dbo.GENTypes.Id, dbo.GENTypes.RichContent, dbo.GENTypes.Code, dbo.GENTypes.ColorCode, dbo.GENTypes.IsCheckedOut, dbo.GENTypes.DateCreated, dbo.GENTypes.DateUpdated, dbo.GENTypes.CheckinDate, dbo.GENTypes.CheckoutDate, dbo.GENTypes.Timeout, 
                         dbo.GENTypes.DisplayOrdering, dbo.GENTypes.CreatedById, dbo.GENTypes.LastUpdatedById, dbo.GENTypes.CheckoutBy,
                         dbo.GENTypes.Int1, dbo.GENTypes.Int2, dbo.GENTypes.Int3, dbo.GENTypes.Int4, dbo.GENTypes.Int5, dbo.GENTypes.Long1, dbo.GENTypes.Long2, dbo.GENTypes.Long3, dbo.GENTypes.Long4, 
                         dbo.GENTypes.Long5, dbo.GENTypes.Float1, dbo.GENTypes.Float2, dbo.GENTypes.Float3, dbo.GENTypes.Float4, dbo.GENTypes.Float5, dbo.GENTypes.Decimal1, dbo.GENTypes.Decimal2, dbo.GENTypes.Decimal3, 
                         dbo.GENTypes.Decimal4, dbo.GENTypes.Decimal5, dbo.GENTypes.Bool1, dbo.GENTypes.Bool2, dbo.GENTypes.Bool3, dbo.GENTypes.Bool4, dbo.GENTypes.Bool5, dbo.GENTypes.Date1, dbo.GENTypes.Date2, 
                         dbo.GENTypes.Date3, dbo.GENTypes.Date4, dbo.GENTypes.Date5, dbo.GENTypes.ValueId1, dbo.GENTypes.ValueId2, dbo.GENTypes.ValueId3, dbo.GENTypes.ValueId4, dbo.GENTypes.ValueId5, dbo.GENTypes.IconId, 
                        dbo.GENTypes.IsActive, dbo.GENTypes.IsPublish, dbo.GENTypes.ExpectedCheckoutDate,GENTagCategories.Id,
						dbo.GENTypes.Name,dbo.GENTypes.Description,dbo.GENTypes.String1,dbo.GENTypes.String2,dbo.GENTypes.String3,dbo.GENTypes.String4,dbo.GENTypes.String5,
						dbo.GENTypes.IsPosted, GENTypes.CourseType,GENClassrooms.Id
END
