/****** Object:  StoredProcedure [dbo].[SP_UpdateContactProgressCompletion]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 02/09/2020
-- Description:	UPDATE Contact completion progress
-- =============================================
CREATE PROCEDURE [dbo].[SP_UpdateContactProgressCompletion]
	-- Add the parameters for the stored procedure here
	@Id BIGINT,
	@EntityId BIGINT,
	@BaseEntityId BIGINT,
	@LastUpdatedById nvarchar(max),
	@CurrentVideoDuration bigint,
	@CurrentReadPages int,
	@FileVideoDownloaded bit,
	@ItemId BIGINT = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	if((select count(Id) from GENContactProgressCompletionDetails where ContactProgressCompletionId = @Id AND EntityId = @EntityId AND BaseEntityId = @BaseEntityId) > 0)
	begin
    -- Insert statements for procedure here
	UPDATE [dbo].[GENContactProgressCompletionDetails]
	SET [LastUpdatedById] = @LastUpdatedById,
	FirstVideoPlay = @CurrentVideoDuration,
	CurrentReadPages = @CurrentReadPages,
	FileVideoDownloaded = @FileVideoDownloaded
     WHERE ContactProgressCompletionId = @Id AND EntityId = @EntityId AND BaseEntityId = @BaseEntityId AND CompletionPercentage < 100

	 UPDATE [dbo].[GENContactProgressCompletionDetails]
	SET [LastUpdatedById] = @LastUpdatedById,
	NextVideoPlay = @CurrentVideoDuration,
	CurrentReadPages = @CurrentReadPages,
	FileVideoDownloaded = @FileVideoDownloaded
     WHERE ContactProgressCompletionId = @Id AND EntityId = @EntityId AND BaseEntityId = @BaseEntityId AND FirstVideoPlay = TotalVideoDuration  AND CompletionPercentage = 100
	 end
	 else
	 begin
	 INSERT INTO [dbo].[GENContactProgressCompletionDetails]
           ([DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById] ,[TotalRequiredProgressValue]
           ,[TotalVideoDuration] ,[FirstVideoPlay],[NextVideoPlay],[TotalFilePages] ,[CurrentReadPages] ,[FileVideoDownloaded] ,[ContactProgressCompletionId]
           ,[BaseEntityId] ,[EntityId])
     SELECT
           GETDATE(),GETDATE() ,@LastUpdatedById ,@LastUpdatedById, 100
           ,VideoDurationSeconds ,(case when GENItemVideos.Id = @EntityId then @CurrentVideoDuration else 0 end),0 ,0 ,(case when GENItemVideos.Id = @EntityId then @CurrentReadPages else 0 end) 
		   ,(case when GENItemVideos.Id = @EntityId then @FileVideoDownloaded else 0 end) ,@Id
           ,181 ,GENItemVideos.Id
		FROM GENItemVideos
		WHERE ItemId = @ItemId and Id not in (select EntityId from GENContactProgressCompletionDetails where ContactProgressCompletionId = @Id and BaseEntityId = 181)

	
	INSERT INTO [dbo].[GENContactProgressCompletionDetails]
           ([DateCreated] ,[DateUpdated] ,[CreatedById] ,[LastUpdatedById] ,[TotalRequiredProgressValue]
           ,[TotalVideoDuration] ,[FirstVideoPlay],[NextVideoPlay] ,[TotalFilePages] ,[CurrentReadPages] ,[FileVideoDownloaded] ,[ContactProgressCompletionId]
           ,[BaseEntityId] ,[EntityId])
     SELECT
           GETDATE() ,GETDATE() ,@LastUpdatedById ,@LastUpdatedById,100
           ,0 ,(case when GENItemFiles.Id = @EntityId then @CurrentVideoDuration else 0 end),0 ,TotalPages ,(case when GENItemFiles.Id = @EntityId then @CurrentReadPages else 0 end) 
		   ,(case when GENItemFiles.Id = @EntityId then @FileVideoDownloaded else 0 end) ,@Id
           ,182 ,GENItemFiles.Id
		FROM GENItemFiles
		WHERE ItemId = @ItemId and Id not in (select EntityId from GENContactProgressCompletionDetails where ContactProgressCompletionId = @Id and BaseEntityId = 182)

	 end
END
GO
