/****** Object:  StoredProcedure [dbo].[SP_UpdateEscalation]    Script Date: 1/1/2020 12:00:49 PM ******/
CREATE Proc [dbo].[SP_UpdateEscalation]
as

update CRMTickets 

set EscalationDate = DATEADD(MINUTE, EscalTable.EscalationTime, GETDATE()),
 EscalatedTo = EscalTable.EmployeeId,
 ManualEscalationTime = GETDATE()
 
FROM CRMTickets ticket
CROSS APPLY GetReportedToTableByStatusId(12,(select ProcessId from dbo.CRMTicket_View_Update where id =ticket.id ),ticket.EscalatedTo) as EscalTable
 WHERE EXISTS
(SELECT id FROM CRMTicket_View_Update where IsOverDue =1 and id =ticket.id and ( EscalationDate <= GETDATE() or EscalationDate is null));



--update CRMDeals 

--set EscalationDate = DATEADD(MINUTE, EscalTable.EscalationTime, GETDATE()),
