Create PROCEDURE [dbo].[SP_UpdateGenpoll]
    @UserId NVARCHAR(Max),
    @Question NVARCHAR(MAX),
    @QuestionNumber NVARCHAR(Max),
    @QuestionType INT,
    @Weight float,
	@Audio nvarchar(MAX) = null,
	@Video nvarchar(MAX) = null,
	@Id bigint
AS
BEGIN
    update genpolls
	set LastUpdatedById = @UserId
