SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[SP_UpdateOverDue]
as
 
INSERT INTO [dbo].[GENProcessHistories]
           ([BaseEntityId]
           ,[ProcessId]
           ,[EntityId]
           ,[DateCreated]
           ,[CreatedById]
           ,[CreatedToId]
           ,[ProcessHistoryType])
		   SELECT DISTINCT GENProcesses.BaseEntityId,GENProcesses.Id,GENProcesses.EntityId,GETDATE(),NULL,NULL,2
		   FROM CRMTicket_View_Update 
		   LEFT JOIN GENProcesses ON (CRMTicket_View_Update.ProcessId = GENProcesses.ProcessId 
					AND GENProcesses.EntityId = CRMTicket_View_Update.Id AND GENProcesses.BaseEntityId = 169)
		   LEFT JOIN GENProcessHistories ON GENProcesses.Id = GENProcessHistories.ProcessId
		   WHERE CRMTicket_View_Update.IsOverDue = 1 AND GENProcesses.Id NOT IN (SELECT ProcessId FROM [dbo].[GENProcessHistories] WHERE [dbo].[GENProcessHistories].[ProcessHistoryType] = 2);

INSERT INTO [dbo].[GENProcessHistories]
           ([BaseEntityId]
           ,[ProcessId]
           ,[EntityId]
           ,[DateCreated]
           ,[CreatedById]
           ,[CreatedToId]
           ,[ProcessHistoryType])
		   SELECT DISTINCT GENProcesses.BaseEntityId,GENProcesses.Id,GENProcesses.EntityId,GETDATE(),NULL,NULL,2
		   FROM Deal_View_Update 
		   LEFT JOIN GENProcesses ON (Deal_View_Update.ProcessId = GENProcesses.ProcessId 
					AND GENProcesses.EntityId = Deal_View_Update.Id AND GENProcesses.BaseEntityId = 144)
		   LEFT JOIN GENProcessHistories ON GENProcesses.Id = GENProcessHistories.ProcessId
		   WHERE Deal_View_Update.IsOverDue = 1 AND GENProcesses.Id NOT IN (SELECT ProcessId FROM [dbo].[GENProcessHistories] WHERE [dbo].[GENProcessHistories].[ProcessHistoryType] = 2);
GO
