CREATE Proc [dbo].[SP_UpdateTalentRequest]  (@StudentId bigint,@TalentId bigint,@Value bigint,@Type nvarchar(200),@Reason nvarchar(MAX))
AS
Begin
IF (@Type = N'Accept')
begin
Update Contacts_Courses
set TalentStatus=@Value,AcceptDate=GETDATE(),Reason=NULL
where StudentId=@StudentId and TalentId=@TalentId
end
else
begin
Update Contacts_Courses
set TalentStatus=@Value,RejectDate=GETDATE(),Reason=@Reason
where StudentId=@StudentId and TalentId=@TalentId
end

END
GO
