-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 08/03/2021
-- Description:	Get User groups that the user had been added to
-- =============================================
CREATE PROCEDURE [dbo].[SP_UserChatGroups] --''
	-- Add the parameters for the stored procedure here
	@UserId NVARCHAR(MAX)
	,@EnableVcr bit =null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT GENChatGroups.*,dbo.CountChatGroupMessages(GENChatGroups.Id,@UserId) as countMessages, LastMessage.MessageTime 
	FROM GENChatGroups
	LEFT JOIN GENChatGroupUsers ON GENChatGroups.Id = GENChatGroupUsers.ChatGroupId
	LEFT JOIN GENClassrooms ON GENChatGroupUsers.EntityId=GENClassrooms.Id AND GENChatGroupUsers.BaseEntityId=176
	OUTER APPLY (SELECT TOP 1 * FROM GENChatMessages WHERE GENChatMessages.ChatGroupId = GENChatGroups.Id ORDER BY MessageTime DESC) LastMessage
	WHERE GENChatGroupUsers.UserId = @UserId 
	--and (GENClassrooms.ToDateTime >= GETDATE() or @EnableVcr is null or @EnableVcr =0)
END
GO
