/****** Object:  StoredProcedure [dbo].[SP_UsernameUnreceivedChatMessagesOfUser]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 23/02/2021
-- Description:	Get unreceived user messages
-- =============================================
CREATE PROCEDURE [dbo].[SP_UsernameUnreceivedChatMessagesOfUser] 
	-- Add the parameters for the stored procedure here
	@ReceiverId NVARCHAR(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- Insert statements for procedure here
	SELECT DISTINCT AspNetUsers.UserName, GENChatMessages.Id, GENChatMessages.ChatGroupId
	FROM GENChatMessages
	LEFT JOIN AspNetUsers ON UserSenderId = AspNetUsers.Id
	LEFT JOIN GENChatGroupMessages ON GENChatMessages.Id = GENChatGroupMessages.ChatMessageId
	WHERE GENChatGroupMessages.UserReceiverId = @ReceiverId AND GENChatGroupMessages.IsReceived = 0;

	UPDATE GENChatGroupMessages
	SET IsReceived = 1
	WHERE UserReceiverId = @ReceiverId AND IsReceived = 0;

	UPDATE GENChatMessages
	SET IsReceived = 1
	WHERE IsReceived = 0 AND (SELECT COUNT(Id) From GENChatGroupMessages Where ChatMessageId = GENChatMessages.Id) = (SELECT COUNT(Id) From GENChatGroupMessages Where IsReceived = 1 AND ChatMessageId = GENChatMessages.Id)


    

	
END
GO
