SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 23/02/2021
-- Description:	Get unreceived user messages
-- =============================================
CREATE PROCEDURE [dbo].[SP_UsernameUnreceivedMessagesOfUser] 
	-- Add the parameters for the stored procedure here
	@ReceiverId NVARCHAR(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT DISTINCT AspNetUsers.UserName FROM GENChatMessages
	LEFT JOIN AspNetUsers ON UserSenderId = AspNetUsers.Id
	WHERE UserReceiverId = @ReceiverId AND IsReceived = 0;

	UPDATE GENChatMessages
	SET IsReceived = 1
	WHERE UserReceiverId = @ReceiverId AND IsReceived = 0;

	
END
GO
/****** Object:  StoredProcedure [dbo].[SP_Users_GetAllStudents]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Batch submitted through debugger: SQLQuery16.sql|7|0|C:\Users\Mahmoud\AppData\Local\Temp\~vsF37B.sql
CREATE proc [dbo].[SP_Users_GetAllStudents] --SP_Users_GetAllStudents 'beae3111-fbb5-4506-a43a-b67fe5ae80f9',40373,''
@UserId nvarchar(256),@Id bigint ,@searchtext nvarchar(50)
as
begin
select distinct us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,GENContacts.Position,cs.SubStatus ,dbo.countMessages(us.Id,@UserId) as countMessages,
CURRENT_TIMESTAMP as EventDate,'' as EventDateString , cs.MainStatusId
, CASE
    WHEN GENContacts.Image is null THEN NULL
	else GENContacts.Image
  end as Image
from
GENContacts LEFT JOIN
GENClassroom_GENContact ON GENClassroom_GENContact.StudentId=GENContacts.Id 
LEFT JOIN GENClassrooms ON GENClassrooms.Id=GENClassroom_GENContact.ClassroomId 
LEFT JOIN AspNetUsers us on GENContacts.UserId=us.Id
left join TLMSClassroom_Session ON dbo.GENClassrooms.Id = dbo.TLMSClassroom_Session.ClassroomId 
inner JOIN dbo.GENEmployees ON  TLMSClassroom_Session.InstructorId=GENEmployees.Id 
LEFT join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
--CROSS APPLY [dbo].[tfn_fnEventDate](us.UserName)
where GENEmployees.Id=@Id And  GENClassrooms.FromDateTime < GETDATE() And GENClassrooms.ToDateTime > GETDATE() And (GENContacts.Name like  '%'+@searchtext+'%' or @searchtext=' ' ) And (us.Id!=@UserId)  
end
GO
/****** Object:  StoredProcedure [dbo].[SP_Users_GetAllUsers]    Script Date: 7/1/2026 10:45:04 AM ******/
