GO
-- Batch submitted through debugger: SQLQuery16.sql|7|0|C:\Users\Mahmoud\AppData\Local\Temp\~vsF37B.sql
CREATE proc [dbo].[SP_Users_GetAllUsers] @id nvarchar(256) ,@searchtext nvarchar(50)
as
begin
select us.Id,us.Name,us.UserName,ss.Name As MainStatus,ss.ColorCode,emp.Position,cs.SubStatus ,
dbo.countMessages(us.Id,@id) as countMessages,
--dbo.fnEventDate(us.UserName) as EventDate,
--dbo.fnEventDateString(us.UserName) as EventDateString , 
cs.MainStatusId
, CASE
    WHEN emp.Image is null THEN '/assets/img/Avatar.webp'
	else emp.Image
  end as Image
from  AspNetUsers us
LEFT JOIN GENEmployees emp on emp.UserId = us.Id
left join GENChatStatus cs on cs.CreatedBy=us.Id
LEFT JOIN GENStatus ss on cs.MainStatusId = ss.Id
where (us.Name like  '%'+@searchtext+'%' or @searchtext=' ' )And us.Id!=@id
end
GO
