/****** Object:  StoredProcedure [dbo].[SP_WorkOrderItemsByOrderAndType]    Script Date: 7/1/2026 10:45:04 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Yahia Zakaria
-- Create date: 19 May 2019
-- Description:	Work Order Items Data
-- =============================================
CREATE PROCEDURE [dbo].[SP_WorkOrderItemsByOrderAndType] @WorkOrderId bigint, @Type bigint
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT [TCRWorkItems].Id AS Id, TCRItems.Name, [TCRWorkItems].WorkItemQTY, CRMQuoteItems.Price, ([TCRWorkItems].WorkItemQTY * CRMQuoteItems.Price) AS TotalPrice, CRMQuoteItems.Discount FROM [TCRWorkItems]
  JOIN TCRItems ON [TCRWorkItems].TCRItemId = TCRItems.Id
  JOIN CRMQuoteItems ON TCRItems.QuoteItemId = CRMQuoteItems.Id
  JOIN TCRWorkOrders ON [TCRWorkItems].WorkOrderId = TCRWorkOrders.Id
  --JOIN Items_View ON [TCRWorkItems].ItemId = Items_View.Id
  WHERE TCRWorkOrders.Id = @WorkOrderId AND TCRWorkOrders.TypeId =@Type
END
GO
