GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROC [dbo].[Update_Contact_EmailSentDate] (@UserId nvarchar(MAX))
AS
Begin

Update GENContacts
Set EmailSentDate =SWITCHOFFSET(SYSDATETIMEOFFSET(), '+02:00') 
where UserId=@UserId
END
GO
